/*
 * Raspberry Pi 4 Model B - Soil Moisture Sensor (DFRobot v2.0) via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> DFRobot Soil Moisture Sensor v2.0 analog output
 *
 * Build: gcc -Wall -Wextra -O2 -o soil_moisture soil_moisture.c -lpigpio -lrt
 * Run:   sudo ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define SAMPLE_PERIOD  1          /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (don't care, clocked out for data)
 *
 * Response (3 bytes):
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in lower 2 bits
 *   rx[2] = b7..b0
 *   10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    char tx[3] = {
        0x01,
        (char)((0x08 | channel) << 4),
        0x00
    };
    char rx[3] = {0};

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Sensor (MCP3008 CH0) - sampling every %d s\n",
           SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (moisture < 0) {
            fprintf(stderr, "Error: failed to read moisture level\n");
        } else {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            printf("[%s] Moisture Level: %d\n", ts, moisture);
            fflush(stdout);
        }

        /* Sleep in 100 ms increments so we can respond to signals promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

