/*
 * Raspberry Pi 4 Model B – MLX91219 Hall-Effect Current Sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX91219 VCC  -> 3.3 V (Pi pin 1)
 *   MLX91219 GND  -> GND   (Pi pin 6)
 *   MLX91219 ADDR -> GND   (selects AIN0 input)
 *   MLX91219 OUT  -> ADS1115 AIN0
 *   ADS1115 SDA   -> Pi GPIO2 (pin 3)
 *   ADS1115 SCL   -> Pi GPIO3 (pin 5)
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -lm -lpigpio -lrt
 * Run:    sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADS1115 constants (pigpio I2C uses 7-bit addresses) ---- */
#define ADS1115_ADDR        0x48          /* ADDR pin tied to GND  */
#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/* Config-register bit fields */
#define ADS1115_CFG_OS_SINGLE   0x8000    /* Begin a single conversion */
#define ADS1115_CFG_MUX_AIN0    0x4000    /* AIN0 single-ended       */
#define ADS1115_CFG_PGA_4_096V  0x0200    /* ±4.096 V range          */
#define ADS1115_CFG_MODE_SINGLE 0x0100    /* Single-shot mode        */
#define ADS1115_CFG_DR_128SPS   0x0080    /* 128 samples/sec         */
#define ADS1115_CFG_CQUE_NONE   0x0003    /* Disable comparator      */

/* Conversion time for 128 SPS (~7.8 ms); we poll every 500 ms */
#define POLL_INTERVAL_US  500000
#define CONV_TIMEOUT_US   10000

/* ---- Calibration ---- */
#define ADC_FULL_SCALE    32767.0        /* 16-bit signed max for ±4.096 V */
#define ADC_VREF          4.096
#define SENSOR_SENSITIVITY 0.001         /* Example: 1 mV/A */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (big-endian on wire).  */
/* ------------------------------------------------------------------ */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (big-endian on wire). */
/* ------------------------------------------------------------------ */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion on AIN0 and read the result.      */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int ads1115_read_ain0(int handle, int16_t *adc_value)
{
    uint16_t cfg = ADS1115_CFG_OS_SINGLE | ADS1115_CFG_MUX_AIN0 |
                   ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SINGLE |
                   ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* Poll the OS bit until it reads 1 (conversion complete). */
    uint16_t val = 0;
    for (int i = 0; i < CONV_TIMEOUT_US / 100; i++) {
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &val) != 0)
            return -1;
        if (val & ADS1115_CFG_OS_SINGLE)
            break;
        gpioDelay(100);
    }
    if (!(val & ADS1115_CFG_OS_SINGLE)) {
        fprintf(stderr, "[ERROR] ADS1115 conversion timeout\n");
        return -1;
    }

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &raw) != 0)
        return -1;

    *adc_value = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus 1 at ADS1115_ADDR ---- */
    g_i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(1, 0x%02X) failed: %d\n",
                ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t adc_value = 0;

        if (ads1115_read_ain0(g_i2c_handle, &adc_value) != 0) {
            fprintf(stderr, "[WARN] ADC read failed; will retry next cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Convert raw ADC count to current (A). */
        double voltage = (double)adc_value * ADC_VREF / ADC_FULL_SCALE;
        double current = voltage / SENSOR_SENSITIVITY;

        printf("Current: %.4f A\n", current);
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- graceful cleanup ---- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

