/*
 * Raspberry Pi 3 Model B+ — KY-026 Flame Sensor + MCP3008 ADC logging
 *
 * Wiring:
 *   KY-026 D0  -> GPIO4  (BCM 4, digital flame output)
 *   KY-026 VCC -> 3.3 V
 *   KY-026 GND -> GND
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND/DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 9,  SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 10, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  SPI0 CE0)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_log flame_log.c -lpigpio -lrt
 * Run:    sudo ./flame_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLAME_SENSOR_PIN      4          /* BCM 4 — digital output from KY-026 */
#define SPI_CHANNEL           0          /* SPI0 CE0 (BCM 8)                   */
#define SPI_SPEED             1000000    /* 1 MHz                              */
#define SPI_FLAGS             0          /* Mode 0, active-low CE              */
#define ADC_CHANNEL           0          /* MCP3008 single-ended channel 0     */
#define LOG_FILE              "flame_data.csv"
#define SAMPLE_INTERVAL_US    1000000    /* 1 second                           */
#define ADC_MAX               1023       /* 10-bit ADC full-scale              */
#define TEMP_MIN              0.0f       /* °C — clamp below this              */
#define TEMP_MAX              100.0f     /* °C — clamp above this              */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  initialize_gpio(void);
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static float calculate_temperature(int adc_value);
static int  log_data(int flame_detected, float temperature);
static void cleanup(void);

/* ------------------------------- Handlers --------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------ GPIO init --------------------------------- */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    /* Enable internal pull-down so the line is defined when the sensor is
     * disconnected or its output is low. */
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n",
                FLAME_SENSOR_PIN);
        /* Non-fatal: continue anyway. */
    }

    return 0;
}

/* ------------------------------ SPI init ---------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, %d Hz).\n",
                SPI_CHANNEL, SPI_SPEED);
        return -1;
    }
    return 0;
}

/* --------------------------- Read MCP3008 --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d (must be 0-7).\n",
                channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d).\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }

    *out_value = adc_value;
    return 0;
}

/* ------------------------ Temperature approximation ------------------------ */
static float calculate_temperature(int adc_value)
{
    float temperature = (float)adc_value / (float)ADC_MAX * TEMP_MAX;
    if (temperature < TEMP_MIN) temperature = TEMP_MIN;
    if (temperature > TEMP_MAX) temperature = TEMP_MAX;
    return temperature;
}

/* ------------------------------ Logging ----------------------------------- */
static int log_data(int flame_detected, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%.2f\n", timestamp, flame_detected,
                temperature) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
        return -1;
    }

    return 0;
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialise SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flame_detected,temperature_c\n");
        fflush(g_log_file);
    }

    printf("Flame sensor logging started. Press Ctrl+C to stop.\n");
    printf("Logging to: %s\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_PIN);
        if (flame_detected < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d.\n",
                    FLAME_SENSOR_PIN);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error: ADC read failed on channel %d.\n",
                    ADC_CHANNEL);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = calculate_temperature(adc_value);

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Error: logging failed.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

