code:
/*
 * Fire Detection System for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Keyes KY-026 Flame Sensor  -> GPIO4  (BCM), digital output
 *   - LM393‑based Heat Sensor   -> ADS1115 AIN0 (single-ended), I2C bus 1
 *   - Active-HIGH buzzer        -> GPIO27 (BCM)
 *
 * Behavior:
 *   - Polls flame sensor every 100 ms with 50 ms debounce.
 *   - Polls temperature every 100 ms.
 *   - Activates buzzer for 2 s when both flame and temperature exceed
 *     thresholds.
 *   - Logs events to fire_log.txt.
 *   - Handles SIGINT cleanly: exits main loop, turns buzzer off,
 *     closes I2C, closes log, calls driver cleanup.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o fire_detect fire_detect.c -lm
 *
 * Run:
 *   ./fire_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define FLAME_SENSOR_PIN      4    /* BCM 4  – KY-026 digital out */
#define BUZZER_PIN            27   /* BCM 27 – active-HIGH buzzer */

#define I2C_BUS               1
#define ADS1115_ADDR          0x48  /* ADS1115 default address when ADDR pin
                                      is tied to GND */

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config word: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS,
 * disable comparator, active low, non-latching, 100 ms debounce */
#define ADS1115_CONFIG_BASE   0x8083  /* OS bit + MUX[14:12] + PGA[11:9] */
#define ADS1115_CONFIG_DR_128 0x0080  /* Data rate 128 SPS */
#define ADS1115_CONFIG_CQUE_1 0x0001  /* Assert after 1 conversion */

#define TEMPERATURE_THRESHOLD 60.0f  /* °C */
#define BUZZER_DURATION_MS    2000   /* 2 s */
#define POLL_INTERVAL_US      100000 /* 100 ms */
#define DEBOUNCE_US           50000  /* 50 ms */

#define LOG_FILE_NAME         "fire_log.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_file = NULL;
static int                   g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  initialize_gpio(void);
static int  initialize_i2c(void);
static int  read_flame_sensor(void);
static int  read_temperature_sensor(float *temperature);
static void activate_buzzer(int duration_ms);
static void log_event(const char *message);
static void cleanup(void);

/* ------------------------------- Signal ----------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ GPIO init --------------------------------- */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                BUZZER_PIN);
        return -1;
    }

    /* Start with buzzer off */
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state on GPIO%d.\n",
                BUZZER_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------ I2C init ---------------------------------- */

static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (err=%d).\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        return -1;
    }

    /* Configure ADS1115: single-shot, AIN0 single-ended, +/-4.096 V,
     * 128 SPS, 100 ms comparator debounce, active low, non-latching. */
    uint16_t config = ADS1115_CONFIG_BASE
                    | ADS1115_CONFIG_DR_128
                    | ADS1115_CONFIG_CQUE_1;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------- Flame sensor read ------------------------------ */

static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n",
                FLAME_SENSOR_PIN);
        return 0;  /* treat as no flame */
    }
    return level;
}

/* ----------------------- Temperature sensor read -------------------------- */

static int read_temperature_sensor(float *temperature)
{
    if (temperature == NULL) {
        return -1;
    }

    /* Trigger a single-shot conversion on AIN0 */
    uint16_t config = ADS1115_CONFIG_BASE
                    | ADS1115_CONFIG_DR_128
                    | ADS1115_CONFIG_CQUE_1
                    | 0x8000;  /* assert OS bit to start conversion */

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Warning: failed to trigger ADS1115 conversion.\n");
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Warning: failed to select conversion register.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Warning: failed to read ADS1115 conversion.\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);

    /* +/-4.096 V range -> 1 bit = 125 µV; raw is signed 16-bit */
    float voltage = (float)raw * 0.000125f;

    /* LM393 output: 5 V = 100 °C, 0 V = 0 °C.  Map linearly. */
    *temperature = (voltage / 5.0f) * 100.0f;

    return 0;
}

/* ------------------------------ Buzzer act -------------------------------- */

static void activate_buzzer(int duration_ms)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to turn buzzer ON.\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn buzzer OFF.\n");
    }
}

/* ------------------------------ Log event --------------------------------- */

static void log_event(const char *message)
{
    if (g_log_file == NULL) {
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed.\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r() failed.\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Warning: strftime() failed.\n");
        return;
    }

    fprintf(g_log_file, "[%s] %s\n", timestamp, message);
    fflush(g_log_file);
}

/* -------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Ensure buzzer is off */
    if (g_i2c_handle >= 0) {
        gpioWrite(BUZZER_PIN, 0);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    /* Register signal handler for SIGINT / SIGTERM */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise I2C for ADS1115 */
    if (initialize_i2c() < 0) {
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fire detection system started.\n");
    printf("  Flame sensor : GPIO%d\n", FLAME_SENSOR_PIN);
    printf("  Buzzer       : GPIO%d\n", BUZZER_PIN);
    printf("  Temperature  : ADS1115 AIN0 (threshold %.1f °C)\n",
           TEMPERATURE_THRESHOLD);
    printf("  Log file     : %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    int    flame_prev   = 0;
    bool   flame_stable = true;
    float  temperature  = 0.0f;
    int    rc           = EXIT_SUCCESS;

    while (g_running) {
        int flame = read_flame_sensor();

        /* 50 ms debounce on flame sensor */
        if (flame != flame_prev) {
            gpioDelay(DEBOUNCE_US);
            int recheck = read_flame_sensor();
            flame_stable = (recheck == flame);
            flame_prev = recheck;
        }

        int temp_ok = read_temperature_sensor(&temperature);

        if (flame_stable && flame) {
            log_event("Flame detected!");
        }

        if (temp_ok && temperature > TEMPERATURE_THRESHOLD) {
            log_event("Temperature exceeds threshold!");
        }

        if (flame_stable && flame && temp_ok &&
            temperature > TEMPERATURE_THRESHOLD) {
            log_event("FIRE DETECTED!");
            activate_buzzer(BUZZER_DURATION_MS);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return rc;
}

