/*
 * Fire Detection System for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Keyes KY-026 Flame Sensor  -> GPIO4  (BCM), digital output
 *   - LM393‑based Heat Sensor   -> ADS1115 AIN0 (single-ended), I2C bus 1
 *   - Active-HIGH buzzer        -> GPIO27 (BCM)
 *
 * Behavior:
 *   - Polls flame sensor every 100 ms with 50 ms debounce.
 *   - Polls temperature every 100 ms.
 *   - Activates buzzer for 2 s when both flame and temperature exceed
 *     thresholds.
 *   - Logs events to fire_log.txt.
 *   - Handles SIGINT cleanly: exits main loop, turns buzzer off,
 *     closes I2C, closes log, calls driver cleanup.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o fire_detect fire_detect.c -lm
 *
 * Run:
 *   ./fire_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define FLAME_SENSOR_PIN      4    /* BCM 4  – KY-026 digital out */
#define BUZZER_PIN            27   /* BCM 27 – active-HIGH buzzer */

#define I2C_BUS               1
#define ADS1115_ADDR          0x48  /* ADS1115 default address when ADDR pin
                                      is tied to GND */

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config word: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS,
 * disable comparator, active low, non-latching, 100 ms debounce */
#define ADS1115_CONFIG_BASE   0x8083  /* OS bit + MUX[14:12] + PGA[11:9] */
#define ADS1115_CONFIG_DR_128 0x0080  /* Data rate 128 SPS */
#define ADS1115_CONFIG_CQUE_1 0x0001  /* Assert after 1 conversion */

#define TEMPERATURE_THRESHOLD 60.0f  /* °C */
#define BUZZER_DURATION_MS    2000   /* 2 s */
#define POLL_INTERVAL_US      100000 /* 100 ms */
#define DEBOUNCE_US           50000  /* 50 ms */

#define LOG_FILE_NAME         "fire_log.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_file = NULL;
static int                   g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  initialize_gpio(void);
static int  initialize_i2c(void);
static int  read_flame_sensor(void);
static int  read_temperature_sensor(float *temperature);
static void activate_buzzer(int duration_ms);
static void log_event(const char *message);
static void cleanup(void);

/* ------------------------------- Signal ----------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ GPIO init --------------------------------- */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                BUZZER_PIN);
        return -1;
    }

    /* Start with buzzer off */
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state on GPIO%d.\n",
                BUZZER_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------ I2C init ---------------------------------- */

static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (err=%d).\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        return -1;
    }

    /* Configure ADS1115: single-shot, AIN0 single-ended, +/-4.096 V,
     * 128 SPS, 100 ms comparator debounce, active low, non-latching. */
    uint16_t config = ADS1115_CONFIG_BASE
                    | ADS1115_CONFIG_DR_128
                    | ADS1115_CONFIG_CQUE_1;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------- Flame sensor read ------------------------------ */

static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n",
                FLAME_SENSOR_PIN);
        return 0;  /* treat as no flame */
    }
    return level;
}

/* ----------------------- Temperature sensor read -------------------------- */

static int read_temperature_sensor(float *temperature)
{
    if (temperature == NULL) {
        return -1;
    }

    /* Trigger a single-shot conversion on AIN0 */
    uint16_t config = ADS1115_CONFIG_BASE
                    | ADS1115_CONFIG_DR_128
                    | ADS1115_CONFIG_CQUE_1
                    | 0x8000;  /* assert OS bit to start conversion */

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Warning: failed to trigger ADS1115 conversion.\n");
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Warning: failed to select conversion register.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Warning: failed to read ADS1115 conversion.\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);

    /* +/-4.096 V range -> 1 bit = 125 µV; raw is signed 16-bit */
    float voltage = (float)raw * 0.000125f;

    /* LM393 output: 5 V = 100 °C, 0 V = 0 °C.  Map linearly. */
    *temperature = (voltage / 5.0f) * 100.0f;

    return 0;
}

/* ------------------------------ Buzzer act -------------------------------- */

static void activate_buzzer(int duration_ms)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to turn buzzer ON.\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn buzzer OFF.\n");
    }
}

/* ------------------------------ Log event --------------------------------- */

static void log_event(const char *message)
{
    if (g_log_file == NULL) {
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed.\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r() failed.\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Warning: strftime() failed.\n");
        return;
    }

    fprintf(g_log_file, "[%s] %s\n", timestamp, message);
    fflush(g_log_file);
}

/* -------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Ensure buzzer is off */
    if (g_i2c_handle >= 0) {
        gpioWrite(BUZZER_PIN, 0);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    /* Register signal handler for SIGINT / SIGTERM */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise I2C for ADS1115 */
    if (initialize_i2c() < 0) {
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fire detection system started.\n");
    printf("  Flame sensor : GPIO%d\n", FLAME_SENSOR_PIN);
    printf("  Buzzer       : GPIO%d\n", BUZZER_PIN);
    printf("  Temperature  : ADS1115 AIN0 (threshold %.1f °C)\n",
           TEMPERATURE_THRESHOLD);
    printf("  Log file     : %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    int    flame_prev   = 0;
    bool   flame_stable = true;
    float  temperature  = 0.0f;
    int    rc           = EXIT_SUCCESS;

    while (g_running) {
        int flame = read_flame_sensor();

        /* 50 ms debounce on flame sensor */
        if (flame != flame_prev) {
            gpioDelay(DEBOUNCE_US);
            int recheck = read_flame_sensor();
            flame_stable = (recheck == flame);
            flame_prev = recheck;
        }

        int temp_ok = read_temperature_sensor(&temperature);

        if (flame_stable && flame) {
            log_event("Flame detected!");
        }

        if (temp_ok && temperature > TEMPERATURE_THRESHOLD) {
            log_event("Temperature exceeds threshold!");
        }

        if (flame_stable && flame && temp_ok &&
            temperature > TEMPERATURE_THRESHOLD) {
            log_event("FIRE DETECTED!");
            activate_buzzer(BUZZER_DURATION_MS);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return rc;
}

code:
/*
 * Raspberry Pi 5 - MLX91219 Current Sensor via MCP3008 ADC
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (spidev0.0), 1 MHz, mode 0
 *   - MLX91219 current sensor connected to MCP3008 CH0
 *   - Cooling fan on GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8U
#define SPI_MODE        0

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023
#define ADC_MIN_VALUE   0

#define CURRENT_THRESHOLD 500.0f
#define FAN_GPIO_LINE    18
#define FAN_CHIP_NAME    "gpiochip4"
#define FAN_CHIP_NUM     0
#define LOG_FILE         "current_log.txt"
#define SAMPLE_INTERVAL  1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *value,
 * or -1 on SPI transfer failure or sensor-absent condition.
 */
static int read_mcp3008(int spi_fd, uint8_t channel, uint16_t *value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)rx[2];

    /* Sensor-absent heuristic: all zeros or all ones typically means disconnected */
    if (raw == ADC_MIN_VALUE || raw == ADC_MAX_VALUE) {
        fprintf(stderr, "Warning: ADC reading at rail (%u) - sensor absent or wiring fault\n", raw);
        return -1;
    }

    *value = raw;
    return 0;
}

/*
 * Convert the 10-bit ADC value to a current reading in milliamperes.
 * MLX91219: 0 V -> 0 A, Vcc -> Vcc / Rshunt.
 * Returns -1.0f on error.
 */
static float adc_to_current(uint16_t adc_value, float vcc, float r_shunt)
{
    if (r_shunt <= 0.0f) {
        fprintf(stderr, "Invalid R_shunt value\n");
        return -1.0f;
    }
    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * vcc;
    return (voltage / r_shunt) * 1000.0f;
}

static void log_current(float current_ma)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Current: %.2f mA\n", timestamp, current_ma);
    fclose(fp);
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *fan_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request fan line --- */
    chip = gpiod_chip_open_by_name(FAN_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s - falling back to gpiochip%d\n",
                FAN_CHIP_NAME, strerror(errno), FAN_CHIP_NUM);
        chip = gpiod_chip_open_by_number(FAN_CHIP_NUM);
        if (!chip) {
            fprintf(stderr, "Failed to open gpiochip%d: %s\n", FAN_CHIP_NUM, strerror(errno));
            goto cleanup;
        }
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", FAN_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    /* --- Main loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(spi_fd, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error reading ADC value - skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float current_ma = adc_to_current(adc_value, 3.3f, 0.1f);
        if (current_ma < 0.0f) {
            fprintf(stderr, "Error converting ADC to current - skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_current(current_ma);

        int fan_state = (current_ma > CURRENT_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(fan_line, fan_state) < 0) {
            fprintf(stderr, "Failed to set fan GPIO state: %s\n", strerror(errno));
        }

        printf("Current: %.2f mA, Fan: %s\n", current_ma, fan_state ? "ON" : "OFF");
        sleep(SAMPLE_INTERVAL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure fan is OFF on every exit path */
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return ret;
}

