/*
 * Raspberry Pi 4 Model B - Honeywell/SGX MICROceL MICS-4514 CO Sensor Logger
 *
 * Reads a dual-element MOS CO/NO2 sensor via I2C bus 1 (simulated 16-bit
 * ADC reading), converts the raw resistance to ppm using a calibrated
 * logarithmic curve, and logs timestamped ppm values to co_log.txt every
 * 5 seconds.
 *
 * Build:  gcc -O2 -Wall -o co_logger co_logger.c
 * Run:    ./co_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define I2C_ADDR             0x48          /* ADS1115 default address when ADDR pin tied to GND */

#define LOG_FILE             "co_log.txt"
#define SAMPLE_INTERVAL_SEC  5

/*
 * Calibration parameters for the MICS-4514.
 *
 * NOTE: The MICS-4514 is a dual-element MOS sensor that outputs a
 *       differential current proportional to the gas concentration.
 *       The resistance-to-ppm conversion below is a simplified
 *       approximation for demonstration purposes.  For a real
 *       production deployment, the sensor's calibration curve must
 *       be measured empirically using a known gas concentration
 *       reference.
 */
#define R0_CLEAN_AIR         10.0          /* Ohms, sensor resistance in clean air */
#define R0_LOAD_RESISTOR     10000.0       /* Ohms, load resistor on the sensor module */
#define CO_PPM_AT_R0         100.0         /* ppm CO at R0_CLEAN_AIR */
#define LOG_BASE             10.0
#define LOG_ARG_OFFSET       (-2.0)

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function Prototypes -------------------------- */

static void signal_handler(int sig);
static int  initialize_i2c(void);
static int  read_simulated_adc(uint16_t *adc_value);
static double calculate_ppm(uint16_t adc_value);
static int  log_data(double ppm_value);
static void cleanup(void);

/* ------------------------------- Signal Handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ I2C Initialization ------------------------- */

static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* --------------------------- Simulated ADC Read --------------------------- */

/*
 * Simulate a 16-bit ADC reading from the MICS-4514.
 * In a real deployment, this would read the ADS1115 or similar.
 */
static int read_simulated_adc(uint16_t *adc_value)
{
    if (adc_value == NULL) {
        return -1;
    }

    /*
     * Generate a noisy 16-bit value that varies with time.
     * This simulates the ADC reading of a sensor with noise.
     */
    *adc_value = (uint16_t)((sin((double)time(NULL) / 10.0) * 5000.0 + 8000.0));
    return 0;
}

/* --------------------------- PPM Calculation ------------------------------ */

/*
 * Convert the 16-bit ADC reading to a CO concentration in ppm.
 *
 * The MICS-4514 outputs a differential current proportional to the
 * gas concentration.  The sensor's resistance varies with the
 * differential current, and the load resistor (R0_LOAD_RESISTOR)
 * sets the full-scale range.
 *
 * This function applies a logarithmic calibration curve to map the
 * ADC value to a ppm concentration.
 */
static double calculate_ppm(uint16_t adc_value)
{
    /*
     * Convert the 16-bit ADC value to a voltage.
     * ADS1115: 16-bit signed, +/-4.096V range.
     * Simulated: 16-bit unsigned, 0-3.3V range.
     * We assume a 3.3V reference for the simulated ADC.
     */
    double voltage = (double)adc_value / 65535.0 * 3.3;

    /*
     * Convert voltage to sensor resistance.
     * The sensor's resistance varies with the differential current.
     * We assume a logarithmic relationship for demonstration.
     */
    double sensor_resistance = R0_CLEAN_AIR * pow(LOG_BASE, (voltage - LOG_ARG_OFFSET));

    /*
     * Calculate the ratio of the sensor resistance to the clean-air
     * resistance.  This is a simplified approximation.  For a real
     * calibration, the sensor's logarithmic curve must be measured.
     */
    double ratio = sensor_resistance / R0_CLEAN_AIR;

    /*
     * Convert the ratio to a ppm value using the calibrated curve.
     */
    double ppm = CO_PPM_AT_R0 * pow(10.0, log10(ratio));

    return ppm;
}

/* ------------------------------ Data Logging ------------------------------ */

static int log_data(double ppm_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm_value);
    fclose(fp);
    return 0;
}

/* -------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    printf("CO Sensor Data Logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_simulated_adc(&adc_value) != 0) {
            fprintf(stderr, "Error: Failed to read simulated ADC value.\n");
        } else {
            double ppm_value = calculate_ppm(adc_value);

            if (log_data(ppm_value) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }

            printf("ADC: %u, CO: %.2f ppm\n", adc_value, ppm_value);
        }

        /*
         * Sleep for the sample interval.  gpioDelay is a pigpio
         * microsecond sleep that is interruptible by signals.
         */
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup();
    printf("CO Sensor Data Logger stopped.\n");
    return EXIT_SUCCESS;
}

