#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, float *co_ppm) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    unsigned int ox_value = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    unsigned int red_value = ((unsigned char)buf[2] << 8) | (unsigned char)buf[3];
    *co_ppm = (float)ox_value * 0.1f;
    return 0;
}

static int log_co_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening " LOG_FILE);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, CO: %.2f ppm\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

static int check_co_threshold(float co_ppm) {
    if (co_ppm > CO_THRESHOLD) {
        FILE *fp = fopen(ALERT_FILE, "a");
        if (fp == NULL) {
            perror("Error opening " ALERT_FILE);
            return -1;
        }
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, CO level exceeded threshold: %.2f ppm\n", timestamp, co_ppm);
        fclose(fp);
        return 1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float co_ppm;
        if (read_sensor_data(i2c_handle, &co_ppm) == 0) {
            if (log_co_data(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO data\n");
            }
            int alert = check_co_threshold(co_ppm);
            if (alert < 0) {
                fprintf(stderr, "Error checking CO threshold\n");
            } else if (alert == 1) {
                printf("CO level exceeded threshold: %.2f ppm\n", co_ppm);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

