#define ADC_MAX 1023                        /* 10-bit ADC */
#define ERROR_VALUE -999.0f

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO bit-banged I2C emulation (bit-bang helper – not production)   */
/* ------------------------------------------------------------------ */
static int gpio_write(int pin, int val)
{
    char path[32];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    if (fprintf(fp, "%d", val) < 0) { fclose(fp); return -1; }
    fclose(fp);
    return 0;
}

static int gpio_read(int pin)
{
    char path[32];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "r");
    if (!fp) return -1;
    int val = fgetc(fp);
    fclose(fp);
    return (val == '1') ? 1 : 0;
}

static int gpio_export(int pin)
{
    char path[32];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    if (fprintf(fp, "%d", pin) < 0) { fclose(fp); return -1; }
    fclose(fp);
    return 0;
}

static int gpio_unexport(int pin)
{
    char path[32];
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    if (fprintf(fp, "%d", pin) < 0) { fclose(fp); return -1; }
    fclose(fp);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir)
{
    char path[32];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) return -1;
    if (fprintf(fp, "%s", dir) < 0) { fclose(fp); return -1; }
    fclose(fp);
    return 0;
}

/*
 * Bit-bang a single I2C byte using the GPIO pins.
 * Returns 0 on success, -1 on error.
 */
static int i2c_bit_bang_byte(int sda_pin, int scl_pin, uint8_t byte)
{
    for (int i = 0; i < 8; i++) {
        int bit = (byte >> (7 - i)) & 1;

        /* Set SDA to output, drive low/high */
        if (gpio_set_direction(sda_pin, "out") < 0) return -1;
        if (gpio_write(sda_pin, bit) < 0) return -1;

        /* Set SCL high */
        if (gpio_set_direction(scl_pin, "out") < 0) return -1;
        if (gpio_write(scl_pin, 1) < 0) return -1;
        usleep(1);

        /* Release SCL (idle high) */
        if (gpio_set_direction(scl_pin, "in") < 0) return -1;
        usleep(1);

        /* Sample SDA on read (idle low) */
        if (!bit) {
            /* Release SDA (idle low) */
            if (gpio_set_direction(sda_pin, "in") < 0) return -1;
        }
    }
    return 0;
}

/*
 * Bit-bang an I2C transaction: write a single byte to the slave.
 * Returns 0 on success, -1 on error.
 */
static int i2c_bit_bang_write(int sda_pin, int scl_pin, uint8_t addr, uint8_t data)
{
    /* Start condition */
    if (gpio_set_direction(sda_pin, "out") < 0) return -1;
    if (gpio_write(sda_pin, 1) < 0) return -1;
    if (gpio_set_direction(scl_pin, "out") < 0) return -1;
    if (gpio_write(scl_pin, 1) < 0) return -1;
    usleep(1);

    /* Send address (7-bit, no R/W) */
    if (i2c_bit_bang_byte(sda_pin, scl_pin, addr) < 0) return -1;

    /* Send data */
    if (i2c_bit_bang_byte(sda_pin, scl_pin, data) < 0) return -1;

    /* Stop condition */
    if (gpio_set_direction(sda_pin, "out") < 0) return -1;
    if (gpio_write(sda_pin, 0) < 0) return -1;
    if (gpio_set_direction(scl_pin, "out") < 0) return -1;
    if (gpio_write(scl_pin, 0) < 0) return -1;
    usleep(1);

    return 0;
}

/*
 * Bit-bang an I2C transaction: read a single byte from the slave.
 * Returns the byte value (0–255) on success, -1 on error.
 */
static int i2c_bit_bang_read(int sda_pin, int scl_pin, uint8_t addr)
{
    /* Start condition */
    if (gpio_set_direction(sda_pin, "out") < 0) return -1;
    if (gpio_write(sda_pin, 1) < 0) return -1;
    if (gpio_set_direction(scl_pin, "out") < 0) return -1;
    if (gpio_write(scl_pin, 1) < 0) return -1;
    usleep(1);

    /* Send address (7-bit, R/W = 1) */
    if (i2c_bit_bang_byte(sda_pin, scl_pin, addr | 1) < 0) return -1;

    /* Release SDA (idle low) */
    if (gpio_set_direction(sda_pin, "in") < 0) return -1;

    uint8_t data = 0;
    for (int i = 0; i < 8; i++) {
        /* Set SCL high */
        if (gpio_set_direction(scl_pin, "out") < 0) return -1;
        if (gpio_write(scl_pin, 1) < 0) return -1;
        usleep(1);

        /* Sample SDA */
        int bit = gpio_read(sda_pin);
        if (bit < 0) return -1;
        data = (uint8_t)((data << 1) | bit);

        /* Release SCL (idle high) */
        if (gpio_set_direction(scl_pin, "in") < 0) return -1;
        usleep(1);
    }

    /* NACK (release SDA high) */
    if (gpio_set_direction(sda_pin, "out") < 0) return -1;
    if (gpio_write(sda_pin, 1) < 0) return -1;

    /* Stop condition */
    if (gpio_set_direction(scl_pin, "out") < 0) return -1;
    if (gpio_write(scl_pin, 0) < 0) return -1;
    usleep(1);

    return (int)data;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float avg_db)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f dB\n", ts, avg_db);
    } else {
        fprintf(fp, "(timestamp error), %.2f dB\n", avg_db);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Export GPIO pins */
    if (gpio_export(GPIO_MIC1) < 0 || gpio_export(GPIO_MIC2) < 0) {
        fprintf(stderr, "Failed to export GPIO pins: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set GPIO directions */
    if (gpio_set_direction(GPIO_MIC1, "in") < 0 ||
        gpio_set_direction(GPIO_MIC2, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO directions: %s\n", strerror(errno));
        gpio_unexport(GPIO_MIC1);
        gpio_unexport(GPIO_MIC2);
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int val1 = i2c_bit_bang_read(GPIO_MIC1, GPIO_MIC2, 0x40);
        int val2 = i2c_bit_bang_read(GPIO_MIC1, GPIO_MIC2, 0x41);

        float db1 = (val1 < 0) ? ERROR_VALUE :
                    ((float)val1 / (float)ADC_MAX) * 96.0f - 96.0f;
        float db2 = (val2 < 0) ? ERROR_VALUE :
                    ((float)val2 / (float)ADC_MAX) * 96.0f - 96.0f;

        float avg = (db1 + db2) / 2.0f;
        log_data(avg);

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpio_unexport(GPIO_MIC1);
    gpio_unexport(GPIO_MIC2);
    printf("\nAudio logger stopped.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * Raspberry Pi 4 Model B – Dual ADMP401 MEMS microphone RMS logger
 *
 * Hardware:
 *   MCP3008 ADC on SPI0:
 *     CE0  -> GPIO8  (BCM)  – Mic 1
 *     CE1  -> GPIO9  (BCM)  – Mic 2
 *     MISO -> GPIO9  (BCM)
 *     MOSI -> GPIO10 (BCM)
 *     SCLK -> GPIO11 (BCM)
 *   LED on GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o audio_logger audio_logger.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for SPI/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (Mic 1) */
#define SPI_CHANNEL_MIC2 1          /* SPI0 CE1 (Mic 2)  */
#define SPI_SPEED        1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define LED_PIN          27         /* BCM 27 */

#define SAMPLE_RATE_HZ   1000       /* 1 kHz sampling */
#define WINDOW_MS        100        /* 100 ms per channel */
#define WINDOW_SAMPLES   (SAMPLE_RATE_HZ * WINDOW_MS / 1000)  /* 100 */
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)           /* 1000 us */

#define RMS_THRESHOLD    0.1f       /* High-level RMS threshold (0–1.0) */
#define LED_ON_MS        500        /* LED on duration after threshold */

#define LOG_FILE         "audio_events.csv"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static int  g_spi_handle_mic2 = -1;

/* --------------------------- Function prototypes -------------------------- */

static int  initialize_spi(void);
static int  read_mcp3008(int spi_handle, int channel);
static float calculate_rms(const int *samples, int count);
static void log_event(float rms1, float rms2);
static void trigger_led(float rms1, float rms2);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI ------------------------------------- */

/*
 * Open the pigpio SPI channel for the MCP3008.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen(CE0) failed: %s\n", pigpio_error(g_spi_handle));
        return -1;
    }

    g_spi_handle_mic2 = spiOpen(SPI_CHANNEL_MIC2, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle_mic2 < 0) {
        fprintf(stderr, "Error: spiOpen(CE1) failed: %s\n", pigpio_error(g_spi_handle_mic2));
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        return -1;
    }

    return 0;
}

/*
 * Read a single-ended channel (0–7) from the MCP3008.
 * Returns the 10-bit ADC value (0–1023), or -1 on SPI error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed on channel %d: %s\n",
                channel, pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------- RMS -------------------------------------- */

/*
 * Calculate the RMS of a window of samples.
 * Returns the RMS value normalised to [0, 1].
 */
static float calculate_rms(const int *samples, int count)
{
    if (count <= 0) {
        return 0.0f;
    }

    double sum_sq = 0.0;
    for (int i = 0; i < count; i++) {
        double centered = (double)samples[i] - 512.0;  /* 10-bit ADC mid-scale */
        sum_sq += centered * centered;
    }

    double rms = sqrt(sum_sq / (double)count);
    return (float)(rms / 512.0);  /* normalise to 0–1 */
}

/* ------------------------------- Logging ---------------------------------- */

/*
 * Append a timestamped RMS event to the CSV file.
 */
static void log_event(float rms1, float rms2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: cannot open " LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error: localtime_r failed");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.4f,%.4f\n", ts, rms1, rms2);
    fclose(fp);
}

/* ------------------------------- LED -------------------------------------- */

/*
 * Turn the LED on for LED_ON_MS milliseconds if either RMS exceeds threshold.
 */
static void trigger_led(float rms1, float rms2)
{
    if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
        if (gpioWrite(LED_PIN, 1) < 0) {
            fprintf(stderr, "Warning: gpioWrite(LED on) failed\n");
        }
        gpioDelay(LED_ON_MS * 1000);  /* gpioDelay takes microseconds */
        if (gpioWrite(LED_PIN, 0) < 0) {
            fprintf(stderr, "Warning: gpioWrite(LED off) failed\n");
        }
    }
}

/* ------------------------------- Signal ----------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_spi_handle_mic2 >= 0) {
        spiClose(g_spi_handle_mic2);
        g_spi_handle_mic2 = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------- */

int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Initialise SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    printf("Audio logger started. Sampling %d samples/channel (%d ms), "
           "threshold %.2f, LED on %d ms. Press Ctrl+C to exit.\n",
           WINDOW_SAMPLES, WINDOW_MS, RMS_THRESHOLD, LED_ON_MS);

    int samples1[WINDOW_SAMPLES];
    int samples2[WINDOW_SAMPLES];

    while (g_running) {
        int idx = 0;
        int err1 = 0, err2 = 0;

        /* Acquire a window of samples from both microphones */
        for (int i = 0; i < WINDOW_SAMPLES && g_running; i++) {
            int v1 = read_mcp3008(g_spi_handle, 0);
            int v2 = read_mcp3008(g_spi_handle_mic2, 0);

            if (v1 < 0) {
                err1 = 1;
            } else {
                samples1[idx] = v1;
                idx++;
            }

            if (v2 < 0) {
                err2 = 1;
            } else {
                samples2[idx] = v2;
                idx++;
            }

            gpioDelay(SAMPLE_PERIOD_US);
        }

        if (err1 || err2) {
            fprintf(stderr, "Warning: SPI read error (mic1=%d, mic2=%d)\n", err1, err2);
            continue;
        }

        if (idx != WINDOW_SAMPLES) {
            fprintf(stderr, "Warning: incomplete window (%d/%d samples)\n", idx, WINDOW_SAMPLES);
            continue;
        }

        /* Calculate RMS for the acquired window */
        float rms1 = calculate_rms(samples1, WINDOW_SAMPLES);
        float rms2 = calculate_rms(samples2, WINDOW_SAMPLES);

        /* Log the event */
        log_event(rms1, rms2);

        /* Trigger LED if threshold exceeded */
        trigger_led(rms1, rms2);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

