/*
 * Raspberry Pi 4 Model B – MLX91204 Hall sensor via ADS1115 ADC
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1 (SDA = GPIO2, SCL = GPIO3), address 0x48
 *   - MLX91204 analog output connected to ADS1115 A0
 *   - Warning LED on GPIO17 (BCM), active-high
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lm
 *
 * Run:
 *   sudo ./hall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits (16-bit, big-endian on the bus) */
#define ADS1115_CFG_OS_BEGIN   0x8000  /* Begin a single conversion */
#define ADS1115_CFG_MUX_A0    0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096 0x0200  /* +/-4.096 V range */
#define ADS1115_CFG_MODE_SS   0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128    0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* Disable comparator */

#define CURRENT_THRESHOLD      50.0f   /* Amperes */
#define BUFFER_SIZE            100
#define SAMPLE_RATE_HZ         10
#define SAMPLE_PERIOD_MS       (1000 / SAMPLE_RATE_HZ)

#define LED_GPIO               17      /* BCM pin */

/* ADS1115: 16-bit signed, 4.096 V range → 1 bit = 125 µA */
#define ADC_PGA_VREF           4.096f
#define ADC_MAX_COUNT          32767.0f
#define ADC_TO_AMPS            (ADC_PGA_VREF / ADC_MAX_COUNT)

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_led_fd = -1;

/* Circular buffer */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static CircularBuffer g_cb;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write16(int fd, uint8_t reg, uint16_t val);
static int  i2c_read16(int fd, uint8_t reg, uint16_t *out);
static int  ads1115_init(int fd);
static int  ads1115_read_a0(int fd, int16_t *raw);
static float raw_to_current(int16_t raw);
static void cb_init(CircularBuffer *cb);
static void cb_push(CircularBuffer *cb, float value);
static float cb_average(const CircularBuffer *cb);
static void led_set(int on);
static void cleanup(void);
static void sigint_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read16: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ----------------------------- ADS1115 ----------------------------------- */
static int ads1115_init(int fd)
{
    /*
     * Config: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS,
     *         comparator disabled.
     */
    uint16_t cfg = ADS1115_CFG_OS_BEGIN
                 | ADS1115_CFG_MUX_A0
                 | ADS1115_CFG_PGA_4_096
                 | ADS1115_CFG_MODE_SS
                 | ADS1115_CFG_DR_128
                 | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* Allow first conversion to complete (128 SPS → ~7.8 ms) */
    usleep(12000);
    return 0;
}

static int ads1115_read_a0(int fd, int16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_OS_BEGIN
                 | ADS1115_CFG_MUX_A0
                 | ADS1115_CFG_PGA_4_096
                 | ADS1115_CFG_MODE_SS
                 | ADS1115_CFG_DR_128
                 | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* Poll OS bit (bit 15) – set when conversion is complete */
    uint16_t val = 0;
    for (int i = 0; i < 20; i++) {
        usleep(2000);
        if (i2c_read16(fd, ADS1115_REG_CONFIG, &val) != 0)
            return -1;
        if (val & ADS1115_CFG_OS_BEGIN)
            break;
    }
    if (!(val & ADS1115_CFG_OS_BEGIN)) {
        fprintf(stderr, "ads1115_read_a0: conversion timeout\n");
        return -1;
    }

    uint16_t conv_raw;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &conv_raw) != 0)
        return -1;

    *raw = (int16_t)conv_raw;
    return 0;
}

/* ----------------------------- Conversion -------------------------------- */
static float raw_to_current(int16_t raw)
{
    return (float)raw * ADC_TO_AMPS;
}

/* ----------------------------- Circular buffer --------------------------- */
static void cb_init(CircularBuffer *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void cb_push(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ----------------------------- LED control ------------------------------- */
static void led_set(int on)
{
    if (g_led_fd >= 0) {
        uint8_t val = (uint8_t)(on ? 1 : 0);
        if (write(g_led_fd, &val, 1) != 1)
            fprintf(stderr, "led_set(%d): %s\n", on, strerror(errno));
    }
}

/* ----------------------------- Cleanup / signal --------------------------- */
static void cleanup(void)
{
    led_set(0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_led_fd >= 0) {
        close(g_led_fd);
        g_led_fd = -1;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a config read – if it fails, sensor may be absent */
    uint16_t cfg_probe = 0;
    if (i2c_read16(g_i2c_fd, ADS1115_REG_CONFIG, &cfg_probe) != 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X – check wiring.\n",
                ADS1115_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (ads1115_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- LED on GPIO17 (BCM) via sysfs ---- */
    g_led_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (g_led_fd < 0) {
        /* Fallback: try direct access */
        g_led_fd = open("/sys/class/gpio/gpio17/value", O_RDWR);
        if (g_led_fd < 0) {
            fprintf(stderr, "open GPIO export: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    } else {
        uint8_t buf[4] = "17\0";
        if (write(g_led_fd, buf, 3) != 3) {
            fprintf(stderr, "export GPIO17: %s\n", strerror(errno));
            close(g_led_fd);
            g_led_fd = -1;
            cleanup();
            return EXIT_FAILURE;
        }
        close(g_led_fd);
        g_led_fd = -1;

        /* Set direction to output */
        g_led_fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
        if (g_led_fd < 0) {
            fprintf(stderr, "set GPIO17 direction: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        uint8_t dir_buf[7] = "output\0";
        if (write(g_led_fd, dir_buf, 6) != 6) {
            fprintf(stderr, "set GPIO17 output: %s\n", strerror(errno));
            close(g_led_fd);
            g_led_fd = -1;
            cleanup();
            return EXIT_FAILURE;
        }
        close(g_led_fd);
        g_led_fd = -1;

        /* Value file */
        g_led_fd = open("/sys/class/gpio/gpio17/value", O_RDWR);
        if (g_led_fd < 0) {
            fprintf(stderr, "open GPIO17 value: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    cb_init(&g_cb);
    led_set(0);

    printf("Hall sensor monitoring started. Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t raw = 0;
        if (ads1115_read_a0(g_i2c_fd, &raw) != 0) {
            fprintf(stderr, "ADC read error – continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        float current = raw_to_current(raw);
        cb_push(&g_cb, current);
        float avg = cb_average(&g_cb);

        printf("Current: %.2f A | Avg(%d): %.2f A | LED: %s\n",
               current, g_cb.count, avg,
               (avg > CURRENT_THRESHOLD) ? "ON" : "OFF");

        led_set(avg > CURRENT_THRESHOLD);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

