/*
 * TCS34725 color sensor logger for Raspberry Pi 4 Model B
 * Uses the Adafruit TCS34725 driver (pigpio).
 *
 * Wiring:
 *   TCS34725 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   TCS34725 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   TCS34725 VDD -> 3.3 V
 *   TCS34725 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o color_logger color_logger.c -lpigpio -lrt
 *   (must be run as root for pigpio I2C access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29          /* TCS34725 default I2C address */
#define LOG_FILE       "color_log.csv"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MAX_CONSEC_ERR 3             /* consecutive I2C failures before exit */

/* TCS34725 registers */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02
#define TCS34725_ENABLE_WEN  0x04

#define TCS34725_ID_VALUE   0x44    /* TCS34725 ID byte */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0)
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[WARN] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[WARN] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns data as (msb << 8) | lsb */
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TCS34725 driver                                                     */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    uint8_t id = 0;

    if (i2c_read_byte(handle, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read TCS34725 ID register.\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "[ERROR] Unexpected TCS34725 ID: 0x%02X (expected 0x%02X).\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);  /* 3 ms power-on delay */

    /* Set integration time (ATIME) to 2.4 ms (0xFF) */
    if (i2c_write_byte(handle, TCS34725_ATIME, 0xFF) < 0)
        return -1;

    /* Enable RGBC ADC */
    if (i2c_write_byte(handle, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    return 0;
}

static int tcs34725_read_rgbc(int handle, uint16_t *r, uint16_t *g,
                              uint16_t *b, uint16_t *c)
{
    if (i2c_read_word(handle, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    /* Check whether file already exists so we can write a header */
    int need_header = (access(LOG_FILE, F_OK) != 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    if (need_header)
        fprintf(g_log_file, "timestamp,clear,red,green,blue\n");

    return 0;
}

static void log_sample(uint16_t c, uint16_t r, uint16_t g, uint16_t b)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[WARN] localtime_r failed; skipping sample.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_file, "%s,%u,%u,%u,%u\n", ts, c, r, g, b);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] TCS34725 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t r, g, b, c;

        if (tcs34725_read_rgbc(g_i2c_handle, &r, &g, &b, &c) == 0) {
            log_sample(c, r, g, b);
            consecutive_errors = 0;
        } else {
            if (++consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "[ERROR] %d consecutive I2C failures; aborting.\n",
                        consecutive_errors);
                break;
            }
        }

        /* Sleep for the remainder of the sample period (interruptible) */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    cleanup();
    return (consecutive_errors >= MAX_CONSEC_ERR) ? EXIT_FAILURE : EXIT_SUCCESS;
}

