#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define MCP3008_CHANNEL 0
#define ADC_MAX         1023
#define ADC_VREF        3.3
#define R_LOAD          1000.0
#define V_SUPPLY        3.3
#define CURRENT_THRESHOLD 10.0
#define MOTOR_GPIO      17
#define LOG_FILE        "current_log.csv"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES     3

static volatile sig_atomic_t g_terminate = 0;
static int g_spi_fd = -1;
static int g_motor_gpio = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_current(int adc_value) {
    float v_out = ((float)adc_value / (float)ADC_MAX) * ADC_VREF;
    return (v_out / R_LOAD) * (V_SUPPLY / ADC_VREF);
}

static int log_current(float current) {
    int is_new = (access(LOG_FILE, F_OK) != 0);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (is_new) {
        if (fprintf(fp, "Timestamp,Current (A)\n") < 0) {
            perror("fprintf(header)");
            fclose(fp);
            return -1;
        }
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.3f\n", ts, current) < 0) {
        perror("fprintf(data)");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

static int control_motor(int state) {
    if (g_motor_gpio < 0) {
        fprintf(stderr, "Motor GPIO not initialized\n");
        return -1;
    }
    if (gpioWrite(g_motor_gpio, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", g_motor_gpio, state);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_motor_gpio = MOTOR_GPIO;
    if (gpioSetMode(g_motor_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", g_motor_gpio);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(g_motor_gpio, 1) < 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", g_motor_gpio);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !g_terminate) {
            adc_value = read_mcp3008(g_spi_fd, MCP3008_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed (attempt %d/%d), retrying...\n",
                        retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed after %d attempts, continuing...\n",
                    MAX_RETRIES);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (current > CURRENT_THRESHOLD) {
            printf("Over-current detected: %.3f A\n", current);
            if (control_motor(0) < 0) {
                fprintf(stderr, "Failed to disable motor\n");
            }
            sleep(SAMPLE_INTERVAL);
            if (control_motor(1) < 0) {
                fprintf(stderr, "Failed to re-enable motor\n");
            }
        } else {
            printf("Current: %.3f A\n", current);
            sleep(SAMPLE_INTERVAL);
        }
    }

    printf("\nShutting down...\n");

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_motor_gpio >= 0) {
        gpioWrite(g_motor_gpio, 1);
        gpioTerminate();
        g_motor_gpio = -1;
    }

    return EXIT_SUCCESS;
}

