/*
 * MLX90817 pressure logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX90817 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90817 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90817 VDD  -> 3.3 V
 *   MLX90817 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90817_log mlx90817_log.c -lpigpio -lrt
 * Run:    sudo ./mlx90817_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define MLX90817_ADDR        0x30          /* default 7-bit I2C address */
#define LOG_FILE             "pressure_log.csv"
#define SAMPLE_PERIOD_US     1000000       /* 1 second */
#define MAX_READ_RETRIES     3             /* consecutive failures before aborting */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- ISO-8601 UTC timestamp ---- */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit pressure value from the MLX90817.
 * Returns 0 on success and stores the pressure in kPa in *out_kpa.
 * Returns -1 on I2C error.
 */
static int read_pressure(int handle, float *out_kpa)
{
    /*
     * The MLX90817 returns 16-bit data in two consecutive registers.
     * pigpio's i2cReadWordData sends the register address then reads
     * two bytes; on the MLX90817 this is interpreted as little-endian
     * pressure data.  We convert to kPa using the scale factor
     * documented in the datasheet.
     */
    int raw = i2cReadWordData(handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData failed (reg 0x00, code %d)\n", raw);
        return -1;
    }

    /* pigpio returns the word as (msb << 8) | lsb; swap to get the
     * sensor's little-endian byte order. */
    uint16_t swapped = (uint16_t)(((raw & 0xFF00) >> 8) | ((raw & 0x00FF) << 8));

    /* Scale factor from datasheet: 1 LSB = 0.001 kPa */
    *out_kpa = (float)swapped * 0.001f;
    return 0;
}

/* ---- Logging ---- */
static int log_pressure(FILE *fp, const char *timestamp, float pressure_kpa)
{
    if (fprintf(fp, "%s,%.3f\n", timestamp, pressure_kpa) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush of log file failed\n");
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X, code %d)\n",
                I2C_BUS, MLX90817_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (once) ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0 ||
            fflush(g_log_file) != 0) {
            fprintf(stderr, "[FATAL] Cannot write header to log file\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signal handling\n");
    }

    printf("MLX90817 logger started. Logging to %s every 1 s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* ---- Main loop ---- */
    int consecutive_failures = 0;

    while (g_running) {
        float pressure_kpa = 0.0f;

        if (read_pressure(g_i2c_handle, &pressure_kpa) == 0) {
            consecutive_failures = 0;

            char timestamp[32];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_pressure(g_log_file, timestamp, pressure_kpa) != 0) {
                    fprintf(stderr, "[ERROR] Logging failed; continuing\n");
                } else {
                    printf("%s  %.3f kPa\n", timestamp, pressure_kpa);
                }
            } else {
                fprintf(stderr, "[ERROR] Failed to generate timestamp\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "[ERROR] Pressure read failed (%d consecutive)\n",
                    consecutive_failures);

            if (consecutive_failures >= MAX_READ_RETRIES) {
                fprintf(stderr, "[FATAL] %d consecutive read failures; aborting.\n",
                        consecutive_failures);
                break;
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_PERIOD_US / 10);
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

