/*
 * Raspberry Pi 4 Model B – MLX90834 Pressure Sensor via ADS1115 ADC Bridge
 *
 * Wiring:
 *   MLX90834 SENT output  -> ADS1115 AIN0 (single-ended)
 *   MLX90834 VDD          -> 3.3 V (Pi pin 1)
 *   MLX90834 GND          -> GND (Pi pin 9)
 *   ADS1115 SDA           -> Pi GPIO2 (pin 3, I2C bus 1)
 *   ADS1115 SCL           -> Pi GPIO3 (pin 5, I2C bus 1)
 *   ADS1115 ADDR          -> GND (I2C address 0x48)
 *   ADS1115 AIN1 NTC      -> 3.3 V (Pi pin 1)
 *   ADS1115 AIN1 NTC      -> GND (Pi pin 9)
 *   Warning LED anode     -> Pi GPIO17 (pin 11) through 330 Ω resistor
 *   Warning LED cathode   -> GND (Pi pin 9)
 *
 * Build: gcc -O2 -Wall -o mlx90834_monitor mlx90834_monitor.c -lpigpio -lrt
 * Run:   sudo ./mlx90834_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config register bit fields */
#define ADS1115_CFG_OS_SINGLE   0x8000  /* Begin single conversion */
#define ADS1115_CFG_MUX_AIN0    0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_MUX_AIN1    0x5000  /* AIN1 single-ended */
#define ADS1115_CFG_PGA_4_096V  0x0200  /* +/-4.096 V range */
#define ADS1115_CFG_MODE_SINGLE 0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128SPS   0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE   0x0003  /* Disable comparator */

#define LED_GPIO              17
#define PRESSURE_THRESHOLD    105.0f   /* kPa */
#define SAMPLE_PERIOD_US      1000000  /* 1 second */
#define MAX_RETRIES           3
#define ADC_FULL_SCALE        32767.0f /* 16-bit signed, +/-4.096 V => 32767 */
#define ADC_VREF              4.096f   /* PGA gain = 1 */
#define NTC_VREF              3.3f
#define NTC_R0                10000.0f /* Reference resistor, ohms */
#define NTC_ALPHA             0.001129148457f /* MLX90834 NTC alpha */
#define NTC_BETA              0.000150000000f /* MLX90834 NTC beta */
#define NTC_RT_COEFF          0.000000000000f /* MLX90834 NTC rt coeff */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal Handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ ADS1115 ---------------------------------- */
static int ads1115_write_config(int handle, uint16_t config)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int ads1115_read_conversion(int handle, int16_t *out)
{
    char reg = ADS1115_REG_CONV;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) < 0)
        return -1;
    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;

    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/*
 * Trigger a single-ended conversion on the given channel and return the
 * raw 16-bit signed value.  Returns 0 on success, -1 on error.
 */
static int ads1115_read_channel(int handle, uint16_t mux, int16_t *out)
{
    uint16_t config = ADS1115_CFG_OS_SINGLE | mux | ADS1115_CFG_PGA_4_096V |
                      ADS1115_CFG_MODE_SINGLE | ADS1115_CFG_DR_128SPS |
                      ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_config(handle, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    return ads1115_read_conversion(handle, out);
}

/* ------------------------------ Conversion ------------------------------- */
static float raw_to_pressure(int16_t raw)
{
    /*
     * MLX90834 SENT output is a differential signal proportional to
     * pressure.  The ADS1115 PGA gain is 1 (4.096 V full-scale), so a
     * full-scale reading corresponds to 4.096 V.
     */
    float voltage = (raw / ADC_FULL_SCALE) * ADC_VREF;
    /*
     * Placeholder linear calibration.  Replace with the actual
     * sensor's transfer function (e.g., a polynomial).
     */
    return voltage * 100.0f;
}

static float raw_to_temperature(int16_t raw)
{
    /*
     * AIN1 is connected to an NTC resistor.  The NTC resistance is
     * inversely proportional to temperature, so a higher voltage
     * (higher ADC reading) means a lower temperature.
     */
    float voltage = (raw / ADC_FULL_SCALE) * ADC_VREF;
    if (voltage <= 0.0f)
        return NAN;

    float r_ntc = NTC_R0 * (NTC_VREF / voltage - 1.0f);
    if (r_ntc <= 0.0f)
        return NAN;

    float inv_t = NTC_ALPHA + NTC_BETA * logf(r_ntc / NTC_R0);
    if (isnan(inv_t))
        return NAN;

    return 1.0f / inv_t - 273.15f;
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (err=%d)\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("MLX90834 Pressure Monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw_pressure = 0, raw_temp = 0;
        bool pressure_ok = false, temp_ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (ads1115_read_channel(g_i2c_handle, ADS1115_CFG_MUX_AIN0, &raw_pressure) == 0) {
                pressure_ok = true;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff */
        }

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (ads1115_read_channel(g_i2c_handle, ADS1115_CFG_MUX_AIN1, &raw_temp) == 0) {
                temp_ok = true;
                break;
            }
            gpioDelay(100000);
        }

        if (!pressure_ok || !temp_ok) {
            fprintf(stderr, "Sensor read failed (pressure=%s, temp=%s).\n",
                    pressure_ok ? "ok" : "fail",
                    temp_ok ? "ok" : "fail");
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float pressure = raw_to_pressure(raw_pressure);
        float temperature = raw_to_temperature(raw_temp);

        if (isnan(temperature)) {
            fprintf(stderr, "Invalid temperature reading (raw=0x%04X).\n",
                    (uint16_t)raw_temp);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Pressure: %.2f kPa, Temperature: %.2f C\n",
               pressure, temperature);

        gpioWrite(LED_GPIO, (pressure > PRESSURE_THRESHOLD) ? 1 : 0);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ------------------------------ Cleanup ------------------------------- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

