/*
 * Raspberry Pi 3 Model B+ — Hall-effect current monitor
 *
 * Hardware:
 *   - Melexis MLX91209 Hall-effect current sensor (analog output)
 *   - MCP3008 10-bit SPI ADC on SPI0 CE0 (BCM GPIO8 = CE, GPIO11 = SCLK,
 *     GPIO10 = MOSI, GPIO9 = MISO), SPI mode 0, 1 MHz
 *   - Motor current-sense amplifier output wired to MCP3008 CH0
 *   - GPIO27 (BCM) driven HIGH to shut down the motor on overcurrent
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware-access GPIO pins).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* MCP3008 on CE0 (BCM GPIO8)            */
#define SPI_SPEED        1000000    /* 1 MHz                                 */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                 */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0        */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code             */

#define OVERCURRENT_THRESHOLD  10.0 /* Amperes                               */
#define SAMPLE_PERIOD_US       100000 /* 100 ms                              */

#define MOTOR_SHUTDOWN_PIN 27       /* BCM GPIO27 — HIGH = motor OFF         */

#define LOG_FILE_NAME    "current_log.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes -------------------------- */

static int  initialize_hardware(void);
static int  read_adc(int channel, int *out_value);
static float calculate_current(int adc_value);
static void log_current(float current);
static void overcurrent_handler(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize hardware */
    if (initialize_hardware() != 0) {
        fprintf(stderr, "Error: hardware initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error: SPI read failed on channel %d.\n",
                    ADC_CHANNEL);
            break;
        }

        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr,
                    "Error: ADC value %d out of range [0, %d].\n",
                    adc_value, ADC_MAX);
            break;
        }

        float current = calculate_current(adc_value);
        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            overcurrent_handler();
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Hardware init ------------------------------- */

static int initialize_hardware(void)
{
    /*
     * MCP3008 SPI wiring (BCM numbering):
     *   CE0  -> BCM GPIO8  (physical pin 24)
     *   SCLK -> BCM GPIO11 (physical pin 23)
     *   MOSI -> BCM GPIO10 (physical pin 19)
     *   MISO -> BCM GPIO9  (physical pin 21)
     *   VDD  -> 3.3 V, VREF -> 3.3 V, DGND/AGND -> GND
     */

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d, "
                        "flags 0x%x). pigpio error: %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        return -1;
    }

    /* Configure motor-shutdown pin as output, default LOW (motor ON) */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n",
                MOTOR_SHUTDOWN_PIN);
        return -1;
    }
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n",
                MOTOR_SHUTDOWN_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------ SPI read --------------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer, SPI mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7).\n",
                channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01,
                   (char)((0x08 | (channel & 0x07)) << 4),
                   0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* --------------------------- Current conversion --------------------------- */

/*
 * Placeholder linear conversion.
 * Replace with your sensor's calibration curve (e.g., transfer function).
 */
static float calculate_current(int adc_value)
{
    return (float)adc_value / (float)ADC_MAX * 10.0f;
}

/* ------------------------------ Logging ---------------------------------- */

static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return;
    }

    if (fflush(g_log_file) != 0) {
        perror("Error flushing log file");
    }
}

/* --------------------------- Overcurrent action --------------------------- */

static void overcurrent_handler(void)
{
    fprintf(stderr, "Overcurrent detected! Shutting down motor.\n");

    if (g_log_file != NULL) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            strftime(timestamp, sizeof(timestamp),
                     "%Y-%m-%d %H:%M:%S", &timeinfo);
            fprintf(g_log_file, "%s, OVERCURRENT: Motor shutdown triggered\n",
                    timestamp);
            fflush(g_log_file);
        }
    }

    /* Drive GPIO27 HIGH to shut down the motor */
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to drive GPIO27 HIGH.\n");
    }

    g_running = 0; /* Exit main loop */
}

/* ------------------------------ Cleanup ----------------------------------- */

static void cleanup(void)
{
    /* Ensure motor is OFF before releasing resources */
    if (g_spi_handle >= 0) {
        gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

