/*
 * Methane monitor using MCP3008 ADC and Honeywell MICROpeL 41000-020 sensor.
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (SPI, GPIO) — no direct driver library reference
 *
 * Wiring
 *   MCP3008 VDD  -> Pi 3.3 V (pin 1)
 *   MCP3008 VREF -> Pi 3.3 V (pin 1)
 *   MCP3008 AGND -> Pi GND  (pin 6)
 *   MCP3008 DGND -> Pi GND  (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, BCM)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, BCM)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, BCM)
 *   MCP3008 CS   -> Pi GPIO8  (CE0, BCM)
 *   MCP3008 CH0  -> MICROpeL analog output
 *
 * Build:  gcc -O2 -Wall -Wextra -o methane_monitor methane_monitor.c -lpigpio -lrt
 * Run:    sudo ./methane_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define THRESHOLD_PPM  1000.0f
#define LOG_FILE       "methane_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                     */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_fp     = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer heavy cleanup to main()       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel; returns 0..1023 or -1 on error   */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out low bits)
     *
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2].
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (spiXfer returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;   /* 0..1023 */
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to ppm (linear approximation)                      */
/* ------------------------------------------------------------------ */
static float adc_to_ppm(int adc_value)
{
    /*
     * Placeholder linear conversion.
     * Adjust slope/intercept based on your sensor calibration
     * (e.g., load resistor, voltage divider, sensor-specific
     *  transfer function).
     */
    return (float)adc_value * 0.1f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with ISO-8601 timestamp                                */
/* ------------------------------------------------------------------ */
static void log_reading(FILE *fp, float ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f ppm\n", ts, ppm) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    } else {
        fflush(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Check threshold and emit leak alarm                                 */
/* ------------------------------------------------------------------ */
static void check_threshold(float ppm)
{
    if (ppm > THRESHOLD_PPM) {
        fprintf(stderr,
                "*** LEAK ALARM *** Methane concentration %.2f ppm exceeds threshold %.0f ppm\n",
                ppm, THRESHOLD_PPM);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Methane monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            /* SPI error already reported; wait and retry */
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float ppm = adc_to_ppm(adc);

        log_reading(g_log_fp, ppm);
        check_threshold(ppm);

        sleep(SAMPLE_PERIOD);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

