/*
 * Raspberry Pi 4 Model B - MLX90830 Pressure Logger
 *
 * Hardware:
 *   - MLX90830 analog pressure sensor (0-100 kPa) -> ADS1115 AIN0
 *   - ADS1115 I2C ADC on /dev/i2c-1 (SDA=GPIO2, SCL=GPIO3)
 *   - ADS1115 SDA/SCL/VDD/GND connected to Pi header pins 3/5/3.3/6
 *   - ADS1115 ADDR pin tied to GND (I2C address 0x48)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c -lm
 *
 * Run:
 *   ./pressure_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config register (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1 (start single conversion)
 *   Bits 14:12 MUX    = 100 (AIN0 vs GND)
 *   Bits 11:9  PGA    = 001 (±4.096 V)
 *   Bit  8     MODE   = 1 (single-shot)
 *   Bits 7:5   DR     = 100 (128 SPS)
 *   Bit  4     COMP_MODE = 0
 *   Bit  3     COMP_POL  = 0
 *   Bit  2     COMP_LAT  = 0
 *   Bits 1:0   COMP_QUE  = 11 (disable comparator)
 *
 * Binary: 1 100 001 1 100 0 0 0 11 -> 0xC283
 */
#define ADS1115_CONFIG_BASE 0xC283

/* Conversion time for 128 SPS (~7.8 ms); allow margin */
#define ADS1115_CONV_MS    10

/* MLX90830 transfer function (0-100 kPa -> 0-3.3 V) */
#define VREF_VOLTS         3.3f
#define PRESSURE_MAX_KPA   100.0f
#define ADC_MAX_COUNT      32767.0f   /* 16-bit signed, single-ended */

/* Sampling interval */
#define SAMPLE_INTERVAL_S  1

/* Log file */
#define LOG_FILE           "pressure_log.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  i2c_write_reg16(int fd, uint8_t reg, uint16_t val);
static int  i2c_read_reg16(int fd, uint8_t reg, uint16_t *out);
static int  ads1115_init(int fd);
static int  ads1115_read_pressure(int fd, float *pressure_kpa);
static int  log_pressure(FILE *fp, float pressure_kpa);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C register helpers ------------------------ */

/* Write a 16-bit value to an ADS1115 register (big-endian on the bus). */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (big-endian on the bus). */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------ ADS1115 helpers --------------------------- */

/*
 * Initialise the ADS1115: set config register to single-shot, AIN0 vs GND,
 * ±4.096 V, 128 SPS, single-shot mode, comparator disabled.
 */
static int ads1115_init(int fd)
{
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, ADS1115_CONFIG_BASE) != 0) {
        fprintf(stderr, "ads1115_init: failed to write config register\n");
        return -1;
    }
    return 0;
}

/*
 * Trigger a single-shot conversion, wait for completion, and convert the
 * raw ADC count to pressure (kPa).
 *
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_pressure(int fd, float *pressure_kpa)
{
    uint16_t config;
    uint16_t raw;
    int16_t  signed_raw;
    float    voltage;

    /* Trigger a new conversion by writing the config register */
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, ADS1115_CONFIG_BASE) != 0) {
        fprintf(stderr, "ads1115_read_pressure: failed to trigger conversion\n");
        return -1;
    }

    /* Wait for conversion to complete (~7.8 ms at 128 SPS) */
    usleep(ADS1115_CONV_MS * 1000);

    /* Read the conversion result */
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) != 0) {
        fprintf(stderr, "ads1115_read_pressure: failed to read conversion\n");
        return -1;
    }

