     * MLX90830 transfer function:
     *   pressure (kPa) = voltage (V) * (100 / 3.3)
     */
    *pressure_kpa = voltage * (PRESSURE_MAX_KPA / VREF_VOLTS);
    return 0;
}

/* --------------------------------- Logging -------------------------------- */

static int log_pressure(FILE *fp, float pressure_kpa)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "log_pressure: localtime_r failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "log_pressure: strftime failed\n");
        return -1;
