    if (fflush(fp) != 0) {
        fprintf(stderr, "log_pressure: fflush failed: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

/* -------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---------------------------------- Main ---------------------------------- */

int main(void)
