    if (fflush(fp) != 0) {
        fprintf(stderr, "log_pressure: fflush failed: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

/* -------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---------------------------------- Main ---------------------------------- */

int main(void)
{
    float pressure_kpa;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
