#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "Failed to assert CS pin\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS pin\n");
        return -1;
    }

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
    return adc_value;
}

static float calculate_humidity(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) return -1.0;
    return 100.0 - ((float)adc_value / 4095.0) * 100.0;
}

static float calculate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) return -1.0;
    return ((float)adc_value / 4095.0) * 100.0 - 20.0;
}

static int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
    return 0;
}

static int send_email_alert(float humidity) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\n"
             "Humidity threshold exceeded!\n"
             "Timestamp: %s\n"
             "Humidity: %.2f%%\" | ssmtp %s",
             timestamp, humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        perror("Error executing ssmtp command");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to initialize CS pin state\n");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        if (humidity < 0.0 || temperature < 0.0) {
            fprintf(stderr, "Invalid sensor reading (humidity=%.2f, temperature=%.2f)\n", humidity, temperature);
            sleep(1);
            continue;
        }

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded! Sending email alert.\n");
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);
        sleep(5);
    }

    printf("\nCleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

