/*
 * Raspberry Pi 5 - TMP36 Temperature Logger via MCP3208 ADC
 *
 * Hardware:
 *   - MCP3208 ADC on SPI0 (/dev/spidev0.0):
 *       VDD  -> 3.3 V
 *       VREF -> 3.3 V
 *       CLK  -> GPIO11 (BCM)
 *       DOUT -> GPIO9  (BCM)
 *       DIN  -> GPIO10 (BCM)
 *       CS   -> GPIO8  (BCM)
 *   - TMP36 temperature sensor:
 *       VCC  -> 3.3 V
 *       GND  -> GND
 *       OUT  -> MCP3208 CH0
 *
 * Build:
 *   gcc -O2 -Wall -o temp_logger temp_logger.c -lgpiod
 *
 * Run:
 *   sudo ./temp_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   4095U   /* 12-bit ADC */
#define ADC_VREF        3.3f
#define ADC_VOLTAGE_MAX 3.3f

#define TMP36_MIN_TEMP  -40.0f
#define TMP36_MAX_TEMP  125.0f
#define TMP36_SCALE     100.0f  /* 10 mV/°C */

#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_INTERVAL 1       /* seconds */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    /*
     * On the Raspberry Pi 5 the SPI CE0 line is exposed as gpiochip4
     * BCM GPIO8.  We acquire it as a static output (active-low
     * chip-select) so the MCP3208 is idle when the line is high.
     */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, 8);
    if (!g_cs_line) {
        fprintf(stderr, "Error getting GPIO8 (CE0): %s\n", strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "mcp3208-cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO8 as output: %s\n", strerror(errno));
        g_cs_line = NULL;
        gpiod_chip_close(g_chip); g_chip = NULL;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_adc(uint16_t *adc_value)
{
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | ADC_CHANNEL) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    /* Assert chip-select (active low) */
    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "Error asserting CS: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    /* Deassert chip-select */
    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "Error deasserting CS: %s\n", strerror(errno));
        return -1;
    }

    /*
     * MCP3208 single-ended mode: 12-bit result.
     * rx[1] contains bits 11..4, rx[2] contains bits 3..0.
     */
    *adc_value = ((uint16_t)(rx[1] & 0x0F) << 8) | (uint16_t)rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
static float adc_to_celsius(uint16_t adc_value)
{
    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
    return (voltage - 0.5f) * TMP36_SCALE;
}

/* ------------------------------------------------------------------ */
static int log_open(void)
{
    int needs_header = 0;

    /* Check if the file exists / is empty */
    if (access(LOG_FILE, F_OK) == 0) {
        FILE *check = fopen(LOG_FILE, "r");
        if (!check) {
            fprintf(stderr, "Warning: cannot check %s: %s\n",
                    LOG_FILE, strerror(errno));
            return -1;
        }
        fseek(check, 0, SEEK_END);
        if (ftell(check) == 0)
            needs_header = 1;
        fclose(check);
    } else {
        needs_header = 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (needs_header)
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_adc(&adc_value) < 0) {
            fprintf(stderr, "SPI read error; retrying in %d s...\n",
                    SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC reads 0 - sensor absent or wiring fault?\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value >= ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC saturated - possible sensor fault?\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < TMP36_MIN_TEMP || temperature > TMP36_MAX_TEMP) {
            fprintf(stderr,
                    "Warning: temperature %.2f C out of valid range [%.1f, %.1f] - sensor absent or disconnected?\n",
                    temperature, TMP36_MIN_TEMP, TMP36_MAX_TEMP);
        }

        log_sample(temperature);
        printf("Temperature: %.2f C\n", temperature);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

