/*
 * ADXL335 Impact Detector via MCP3008 ADC on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> ADXL335 X-axis analog output
 *   MCP3008 CH1  -> ADXL335 Y-axis analog output
 *   MCP3008 CH2  -> ADXL335 Z-axis analog output
 *   ADXL335 VCC  -> 3.3 V
 *   ADXL335 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o impact_detector impact_detector.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for SPI/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                       */
#define SPI_SPEED      1000000    /* 1 MHz                                  */
#define SPI_FLAGS      0          /* Mode 0, active-low CS, 8-bit words      */

#define ADC_CHANNEL_X  0
#define ADC_CHANNEL_Y  1
#define ADC_CHANNEL_Z  2

#define IMPACT_THRESHOLD 1000     /* Raw ADC count threshold                */
#define SAMPLE_RATE_HZ   100      /* Samples per second                     */
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define LOG_FILE_NAME   "impact_log.txt"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  initialize(void);
static int  read_adc(int channel);
static void log_data(int x, int y, int z);
static void detect_impact(int x, int y, int z);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ---------------------------- */

static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /*
     * spiOpen returns a handle >= 0 on success, or < 0 on failure.
     * pigpio manages the CS line automatically for the configured channel.
     */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        gpioTerminate();
        return -1;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ----------------------------- MCP3008 Read ------------------------------ */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   TX[2] = 0x00                       (clock out remaining bits)
 *   RX[1] bits 1..0 + RX[2] bits 7..0  -> 10-bit result
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7).\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed for channel %d (returned %d).\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value %d out of 10-bit range for channel %d.\n",
                adc_value, channel);
        return -1;
    }

    return adc_value;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_data(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(g_log_file);
}

/* ----------------------------- Impact Detection -------------------------- */

static void detect_impact(int x, int y, int z)
{
    if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        localtime_r(&rawtime, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        fprintf(g_log_file, "%s,IMPACT DETECTED,%d,%d,%d\n", timestamp, x, y, z);
        fflush(g_log_file);
        printf("%s: IMPACT DETECTED (X=%d, Y=%d, Z=%d)\n", timestamp, x, y, z);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    while (g_running) {
        int x = read_adc(ADC_CHANNEL_X);
        int y = read_adc(ADC_CHANNEL_Y);
        int z = read_adc(ADC_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Warning: ADC read error, skipping sample.\n");
        } else {
            log_data(x, y, z);
            detect_impact(x, y, z);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

