code:
/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 *
 * Reads raw IR and RED ADC values from the Si1172 via I2C bus 1, once per
 * second, and logs them to biometric_log.csv with a header row and error
 * flags.  Because the Si1172 requires a proprietary algorithm to convert
 * raw PPG samples to true HR and SpO2, the program logs the raw values
 * as proxy data.  See the comments in the code for details.
 *
 * Build:  gcc -O2 -Wall -o si1172_log si1172_log.c -lpigpio -lrt
 * Run:    sudo ./si1172_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Constants ------------------------------ */

#define I2C_BUS              1
#define SI1172_ADDR          0x60          /* Si1172 default I2C address  */

#define LOG_FILE             "biometric_log.csv"
#define SAMPLE_PERIOD_US     1000000       /* 1 second                    */

/*
 * Si1172 register addresses (representative; the exact register map
 * depends on the specific variant.  A full register map is available
 * in the Si1172 datasheet.)
 */
#define REG_HW_ID            0x00
#define REG_HW_REV           0x01
#define REG_IR_DATA          0x10
#define REG_RED_DATA         0x12
#define REG_STATUS           0x20
#define REG_COMMAND          0x30

/* Error codes for the error flag column */
#define ERR_NONE             0
#define ERR_I2C_TRANS        1
#define ERR_SENSOR_ABSENT    2

/* --------------------------- Global state ----------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------- Signal handling ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers ------------------------------ */

/*
 * Write a single byte to a Si1172 register.
 * Returns 0 on success, -1 on error.
 */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X <- 0x%02X failed (rc=%d)\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si1172 register.
 * Returns the byte value (0-255) on success, -1 on error.
 */
static int si1172_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    return rc;
}

/*
 * Read a 16-bit little-endian value from two consecutive Si1172 registers.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int si1172_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int lo = si1172_read_reg(handle, reg);
    if (lo < 0)
        return -1;
    int hi = si1172_read_reg(handle, reg + 1);
    if (hi < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/*
 * Initialise the Si1172: verify HW_ID and issue a soft-reset.
 * Returns 0 on success, -1 on error.
 */
static int si1172_init(int handle)
{
    int hw_id = si1172_read_reg(handle, REG_HW_ID);
    if (hw_id < 0) {
        fprintf(stderr, "[Si1172] cannot read HW_ID (sensor absent or bus error)\n");
        return -1;
    }
    if (hw_id != 0x72) {
        fprintf(stderr, "[Si1172] unexpected HW_ID 0x%02X (expected 0x72)\n", hw_id);
        return -1;
    }

    /* Soft reset: write 0x01 to the command register */
    if (si1172_write_reg(handle, REG_COMMAND, 0x01) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle after reset */

    int rev = si1172_read_reg(handle, REG_HW_REV);
    if (rev < 0)
        return -1;
    printf("[Si1172] HW_ID=0x%02X HW_REV=0x%02X\n", hw_id, rev);

    /*
     * Minimal configuration: enable ADC channels and start continuous
     * measurement.  A full production implementation would load the
     * Si1172 firmware image and configure the PPG LED drive currents
     * and measurement parameters.
     */
    if (si1172_write_reg(handle, 0x0F, 0x03) < 0)   /* ADC_ENABLE */
        return -1;
    if (si1172_write_reg(handle, 0x11, 0x01) < 0)   /* MEAS_RATE   */
        return -1;
    if (si1172_write_reg(handle, 0x30, 0x01) < 0)   /* START_MEAS  */
        return -1;

    return 0;
}

/* --------------------------- Logging ---------------------------------- */

static void log_sample(FILE *fp, time_t ts, uint16_t ir, uint16_t red,
                       int hr_proxy, int spo2_proxy, int err)
{
    fprintf(fp, "%ld,%u,%u,%d,%d,%d\n",
            (long)ts, ir, red, hr_proxy, spo2_proxy, err);
    fflush(fp);
}

/* ------------------------------ Main ---------------------------------- */

int main(void)
{
    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1172_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (si1172_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1172 initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,ir_adc,red_adc,hr_proxy,spo2_proxy,error\n");
        fflush(g_log_file);
    }

    printf("Si1172 logging started.  Press Ctrl-C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        time_t now = time(NULL);
        uint16_t ir  = 0;
        uint16_t red = 0;
        int err = ERR_NONE;

        if (si1172_read_reg16(g_i2c_handle, REG_IR_DATA, &ir) < 0 ||
            si1172_read_reg16(g_i2c_handle, REG_RED_DATA, &red) < 0) {
            err = ERR_I2C_TRANS;
            /* Log the error row; do not crash the loop */
            log_sample(g_log_file, now, 0, 0, 0, 0, err);
        } else {
            /*
             * Proxy values: the Si1172 requires a proprietary PPG
             * algorithm to convert raw IR and RED ADC samples to
             * true HR and SpO2.  We log the raw values as placeholders
             * so the data is still available for downstream analysis.
             */
            int hr_proxy   = (int)ir;
            int spo2_proxy = (int)red;
            log_sample(g_log_file, now, ir, red, hr_proxy, spo2_proxy, err);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

