/*
 * Raspberry Pi 4 Model B — Honeywell SpiroQuant A+ ES1-005 flow sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> SpiroQuant A+ analog output
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lm -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                       */
#define SPI_SPEED      1000000    /* 1 MHz                                  */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                  */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0         */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code              */
#define FLOW_MIN       0.0f       /* L/min — valid range                    */
#define FLOW_MAX       5.0f       /* L/min                                  */
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples                */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  initialize_spi(void);
static int  read_adc(int channel, int *adc_value);
static float convert_to_flow_rate(int adc_value);
static int  log_flow_rate(float flow_rate);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI initialization ------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/* ----------------------------- Read MCP3008 ------------------------------- */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_adc(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d: %s\n",
                bytes, (bytes < 0) ? pigpio_error(bytes) : "short transfer");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ----------------------------- Flow rate conversion ----------------------- */
static float convert_to_flow_rate(int adc_value)
{
    /*
     * Placeholder linear mapping.
     * Replace with the sensor's calibration curve from the datasheet.
     */
    return (float)adc_value * (FLOW_MAX / (float)ADC_MAX);
}

/* ----------------------------- Logging ----------------------------------- */
static int log_flow_rate(float flow_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    char timestamp[40];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_L_min\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Flow monitoring started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error: ADC read failed; skipping sample\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Sensor-absent / fault detection */
        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC value 0 — sensor may be absent or disconnected\n");
        } else if (adc_value >= ADC_MAX) {
            fprintf(stderr, "Warning: ADC saturated at %d — sensor may be saturated or disconnected\n", adc_value);
        }

        float flow_rate = convert_to_flow_rate(adc_value);

        /* Flow rate validation */
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Warning: flow rate %.2f L/min out of range [%.1f, %.1f]\n",
                    flow_rate, FLOW_MIN, FLOW_MAX);
        }

        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Error: logging failed\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

