/*
 * Raspberry Pi Zero W – TDK ICP-10125 I2C Temperature & Pressure Logger
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   ICP-10125 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o icp10125_logger icp10125_logger.c
 * Run:    ./icp10125_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define ICP10125_ADDR    0x60          /* default 7-bit I2C address */
#define MEAS_CMD         0x3617        /* high-precision measurement command */
#define MEAS_DELAY_US    10000         /* 10 ms worst-case conversion time */
#define SAMPLE_PERIOD_S  5             /* seconds between samples */
#define LOG_FILE         "environmental_data.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
