/*
 * Dual MP23ABS1 (analog MEMS) microphone sample reader for Raspberry Pi 3 B+.
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 CE0 (GPIO8), SCLK=GPIO11, MOSI=GPIO10, MISO=GPIO9.
 *   - MP23ABS1 microphone 1 wired to MCP3008 CH0.
 *   - MP23ABS1 microphone 2 wired to MCP3008 CH1.
 *
 * Build:
 *   gcc -O2 -Wall -o mic_dual mic_dual.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for SPI/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define MIC1_CHANNEL   0          /* MCP3008 CH0 */
#define MIC2_CHANNEL   1          /* MCP3008 CH1 */

#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *out_value.
 * Returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit ADC value.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %u (ret=%d)\n", channel, ret);
        return -1;
    }

    *out_value = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)(rx[2] & 0xFF);
    return 0;
}

/*
 * Basic noise-cancellation: subtract a scaled version of mic2 from mic1.
 * Returns the result clamped to [0, 1023].
 */
static uint16_t noise_cancel(uint16_t mic1, uint16_t mic2, int gain1, int gain2)
{
    int32_t diff = (int32_t)mic1 - ((int32_t)mic2 * gain2 / gain1);
    if (diff < 0)
        diff = 0;
    if (diff > 1023)
        diff = 1023;
    return (uint16_t)diff;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        fprintf(stderr, "  gain values are integers in the range [1, 1023]\n");
        return EXIT_FAILURE;
    }

    int gain1 = atoi(argv[1]);
    int gain2 = atoi(argv[2]);

    if (gain1 <= 0 || gain1 > 1023 || gain2 <= 0 || gain2 > 1023) {
        fprintf(stderr, "Gain values must be in the range (1, 1023)\n");
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sampling MP23ABS1 microphones (CH0, CH1) at %d Hz. Press Ctrl+C to stop.\n",
           SAMPLE_RATE_HZ);
    printf("Mic1 Gain: %d, Mic2 Gain: %d\n", gain1, gain2);
    printf("Timestamp,Mic1,Mic2,NoiseCancelled\n");
    fflush(stdout);

    while (g_running) {
        uint16_t mic1 = 0, mic2 = 0;

        if (read_mcp3008(spi_handle, MIC1_CHANNEL, &mic1) != 0) {
            fprintf(stderr, "Error reading mic1; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_mcp3008(spi_handle, MIC2_CHANNEL, &mic2) != 0) {
            fprintf(stderr, "Error reading mic2; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        uint16_t cancelled = noise_cancel(mic1, mic2, gain1, gain2);

        printf("%ld,%u,%u,%u\n", (long)time(NULL), mic1, mic2, cancelled);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

