#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8

#define ADC_CHANNEL     0
#define BUZZER_GPIO     18
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES     3
#define ADC_MAX         1023

#define TEMP_FILE       "ambient_temp.txt"
#define LOG_FILE        "flame_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(float *temp_out) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s — using default 25.0 °C\n",
                TEMP_FILE, strerror(errno));
        *temp_out = 25.0f;
        return -1;
    }
    if (fscanf(fp, "%f", temp_out) != 1) {
        fprintf(stderr, "Warning: cannot parse temperature from %s — using default 25.0 °C\n",
                TEMP_FILE);
        *temp_out = 25.0f;
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (*temp_out < -40.0f || *temp_out > 125.0f) {
        fprintf(stderr, "Warning: temperature %.2f °C out of range — using default 25.0 °C\n",
                *temp_out);
        *temp_out = 25.0f;
        return -1;
    }
    return 0;
}

static int read_adc(int channel, int *adc_out) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < 0 || value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value %d out of range\n", value);
        return -1;
    }
    *adc_out = value;
    return 0;
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3f / (float)(ADC_MAX + 1);
}

static float compensate_voltage(float voltage, float temperature) {
    return voltage * (1.0f + (temperature - 25.0f) * 0.004f);
}

static void log_data(int adc_value, float voltage, float compensated,
                     float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s,%d,%.3f,%.3f,%.2f,%s\n",
            ts, adc_value, voltage, compensated, temperature,
            flame_detected ? "YES" : "NO");
    fflush(g_log_fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: cannot set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: cannot set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: cannot set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_fp, "# Flame sensor log started — timestamp,adc,voltage,compensated,temp,flame\n");
    fflush(g_log_fp);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 25.0f;
        if (read_temperature(&temperature) < 0) {
            fprintf(stderr, "Warning: using default temperature 25.0 °C\n");
        }

        int adc_value = -1;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            if (read_adc(ADC_CHANNEL, &adc_value) == 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retry %d/%d after SPI error\n", retries, MAX_RETRIES);
                    gpioDelay(100000);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: ADC read failed after %d retries — skipping sample\n", MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float compensated = compensate_voltage(voltage, temperature);
        int flame_detected = (compensated > 0.5f) ? 1 : 0;

        log_data(adc_value, voltage, compensated, temperature, flame_detected);

        gpioWrite(BUZZER_GPIO, flame_detected ? 1 : 0);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

