#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define SPI_FLAGS        0
#define LED_PIN          17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW  70.0
#define SAMPLE_INTERVAL_US 5000000
#define POLL_INTERVAL_US   100000
#define JSON_FILE_NAME     "water_levels.json"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: start bit (0x01)
     * Byte 1: SGL/DIFF=1 + D2 D1 D0 channel, left-shifted by 4 (0x80 | (channel << 4))
     * Byte 2: don't care (0x00)
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float calculate_water_level(int adc_value) {
    if (adc_value < 0) return 0.0f;
    float level = ((float)adc_value / 1023.0f) * 100.0f;
    if (level < 0.0f)   level = 0.0f;
    if (level > 100.0f) level = 100.0f;
    return level;
}

static void log_water_level(float water_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[40];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long ms = ts.tv_nsec / 1000000L;

    fprintf(g_json_file, "{\"timestamp\":\"%s.%03ldZ\",\"water_level\":%.2f}\n",
            timestamp, ms, water_level);
    fflush(g_json_file);
}

static void control_led(float water_level) {
    static int led_state = 0;
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        if (gpioWrite(LED_PIN, 1) == 0) {
            led_state = 1;
            printf("Water level above threshold (%.2f%%). LED ON.\n", water_level);
        } else {
            fprintf(stderr, "Failed to turn LED on.\n");
        }
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        if (gpioWrite(LED_PIN, 0) == 0) {
            led_state = 0;
            printf("Water level below threshold (%.2f%%). LED OFF.\n", water_level);
        } else {
            fprintf(stderr, "Failed to turn LED off.\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    g_json_file = fopen(JSON_FILE_NAME, "w");
    if (g_json_file == NULL) {
        perror("Failed to open JSON file");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_json_file, "[\n");
    fflush(g_json_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(g_json_file);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float water_level = calculate_water_level(adc_value);
        printf("Water Level: %.2f%%\n", water_level);

        log_water_level(water_level);
        control_led(water_level);

        /* Sleep in 100 ms increments so signals are caught promptly */
        int remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && g_running) {
            int chunk = (remaining > POLL_INTERVAL_US) ? POLL_INTERVAL_US : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    fprintf(g_json_file, "]\n");
    fclose(g_json_file);
    g_json_file = NULL;

    gpioWrite(LED_PIN, 0);
    spiClose(g_spi_handle);
    g_spi_handle = -1;

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

