/*
 * Raspberry Pi Zero W - Honeywell AWM7300V Airflow Sensor Logger
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0)
 *     CE0  -> GPIO8  (physical pin 24)
 *     SCLK -> GPIO11 (physical pin 23)
 *     MOSI -> GPIO10 (physical pin 19)
 *     MISO -> GPIO9  (physical pin 21)
 *     VDD  -> 3.3 V, VREF -> 3.3 V, DGND/AGND -> GND
 *   - Honeywell AWM7300V analog output -> MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for SPI/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* CE0 on SPI0 */
#define SPI_SPEED      1000000    /* 1 MHz - well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define MCP3008_CHANNEL 0         /* AWM7300V on MCP3008 CH0 */

#define SAMPLE_INTERVAL_US 100000 /* 100 ms */
#define LOG_FILE_NAME      "airflow_log.csv"

/*
 * AWM7300V transfer function (approximate):
 *   LPM = (ADC_value / 1023.0) * 20.0
 *   (0..1023 -> 0..20 LPM)
 */
#define ADC_MAX_VALUE 1023.0
#define LPM_MAX       20.0

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *adc_value);
static double adc_to_lpm(int adc_value);
static int  log_airflow(double lpm);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ SPI init --------------------------------- */

static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/* ------------------------- MCP3008 single-ended read ---------------------- */

/*
 * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   TX[2] = 0x00                       (clock out remaining bits)
 *   RX[1] bits 1..0 + RX[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d (must be 0-7)\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d: %s\n",
                bytes, (bytes < 0) ? pigpio_error(bytes) : "short transfer");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ----------------------------- Conversion -------------------------------- */

static double adc_to_lpm(int adc_value)
{
    return ((double)adc_value / ADC_MAX_VALUE) * LPM_MAX;
}

/* ------------------------------ Logging ---------------------------------- */

static int log_airflow(double lpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, lpm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }

    return 0;
}

/* ------------------------------ Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long file_size = ftell(g_log_file);
        if (file_size == 0) {
            fprintf(g_log_file, "timestamp,airflow_lpm\n");
            fflush(g_log_file);
        }
    } else {
        fprintf(stderr, "Warning: fseek failed on log file; header may be missing\n");
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error: failed to read MCP3008 channel %d\n",
                    MCP3008_CHANNEL);
            /* Brief pause before retry to avoid log flooding on persistent bus errors */
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double lpm = adc_to_lpm(adc_value);

        if (log_airflow(lpm) != 0) {
            fprintf(stderr, "Error: failed to log airflow reading\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

