#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_VALUE 0
#define DEFAULT_MAX_VALUE 1023
#define DEFAULT_THRESHOLD 30
#define DEFAULT_INTERVAL 60
#define DEFAULT_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONF "/etc/msmtprc"
#define DATA_FILE "plant_data.txt"
#define SPI_SPEED 500000
#define SPI_FLAGS 0

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_moisture(int adc_value, int min_value, int max_value) {
    if (adc_value < min_value) adc_value = min_value;
    if (adc_value > max_value) adc_value = max_value;
    return (int)(((float)(adc_value - min_value) / (float)(max_value - min_value)) * 100.0);
}

static void log_data(int moisture_level) {
    FILE *fp = fopen(DATA_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open %s: %s\n", DATA_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d\n", timestamp, moisture_level);
    fclose(fp);
}

static void send_email_alert(const char *recipient, int moisture_level) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Alert\n\nPlant moisture level below threshold at %s. Current moisture level: %d%%\" | msmtp -C %s %s",
             timestamp, moisture_level, DEFAULT_MSMTP_CONF, recipient);

    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not execute msmtp: %s\n", strerror(errno));
        return;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_value = DEFAULT_MIN_VALUE;
    int max_value = DEFAULT_MAX_VALUE;
    int threshold = DEFAULT_THRESHOLD;
    int interval = DEFAULT_INTERVAL;
    const char *recipient = DEFAULT_RECIPIENT;
    const char *msmtp_conf = DEFAULT_MSMTP_CONF;

    if (argc > 1) spi_channel = atoi(argv[1]);
    if (argc > 2) adc_channel = atoi(argv[2]);
    if (argc > 3) min_value = atoi(argv[3]);
    if (argc > 4) max_value = atoi(argv[4]);
    if (argc > 5) threshold = atoi(argv[5]);
    if (argc > 6) interval = atoi(argv[6]);
    if (argc > 7) recipient = argv[7];
    if (argc > 8) msmtp_conf = argv[8];

    if (min_value < 0 || min_value > 1023) {
        fprintf(stderr, "Error: Invalid min_value. Must be between 0 and 1023.\n");
        return 1;
    }
    if (max_value < 0 || max_value > 1023) {
        fprintf(stderr, "Error: Invalid max_value. Must be between 0 and 1023.\n");
        return 1;
    }
    if (min_value >= max_value) {
        fprintf(stderr, "Error: min_value must be less than max_value.\n");
        return 1;
    }
    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Error: Invalid threshold. Must be between 0 and 100.\n");
        return 1;
    }
    if (interval <= 0) {
        fprintf(stderr, "Error: Invalid interval. Must be greater than 0.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in %d seconds.\n", interval);
            sleep(interval);
            continue;
        }

        int moisture_level = calculate_moisture(adc_value, min_value, max_value);
        log_data(moisture_level);

        if (moisture_level < threshold) {
            send_email_alert(recipient, moisture_level);
        }

        sleep(interval);
    }

    cleanup();
    printf("Plant monitoring stopped.\n");
    return 0;
}

