        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring Started.\n");
    printf("  SPI device : %s\n", SPI_DEVICE);
    printf("  ADC channel: %d\n", ADC_CHANNEL);
    printf("  Interval   : %d s\n", interval);
    printf("  Log file   : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
