 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 = GPIO8, MISO = GPIO9, MOSI = GPIO10, SCLK = GPIO11)
 *   - MLX90823 analog output connected to MCP3008 CH0
 *
 * Build: gcc -O2 -Wall -o mlx90823_reader mlx90823_reader.c -lpigpio -lrt
 * Run:   sudo ./mlx90823_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8) */
#define SPI_BAUD       1000000    /* 1 MHz SPI clock */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define ADC_VREF       3.3        /* Reference voltage */

#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

/* MLX90823 transfer function (example - adjust per datasheet) */
#define MIN_PRESSURE_PA   0.0f
#define MAX_PRESSURE_PA   100000.0f
#define MIN_ADC_VALUE     200      /* ~0.66 V at 3.3 V */
#define MAX_ADC_VALUE     800      /* ~2.66 V at 3.3 V */

static volatile sig_atomic_t g_terminate = 0;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on SPI error.
 */
static int read_mcp3008(int handle, int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI command (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    *out_value = adc_value;
    return 0;
}

static float adc_to_pressure(int adc_value)
{
    if (adc_value < MIN_ADC_VALUE) adc_value = MIN_ADC_VALUE;
    if (adc_value > MAX_ADC_VALUE) adc_value = MAX_ADC_VALUE;

    float v = (float)adc_value / (float)ADC_MAX_VALUE * ADC_VREF;
    return MIN_PRESSURE_PA +
           (v - (float)MIN_ADC_VALUE / ADC_MAX_VALUE * ADC_VREF) *
           (MAX_PRESSURE_PA - MIN_PRESSURE_PA) /
           ((float)MAX_ADC_VALUE - (float)MIN_ADC_VALUE) / ADC_VREF;
}

static void log_pressure(float pressure_pa)
{
