    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI0 CE0 | MCP3008 CH0 | Sample every 1 s\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (!g_terminate) {
        int adc_value = 0;

        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read error - continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Sensor-absent / bus-error detection */
        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC value is 0 - sensor may be absent or disconnected\n");
        } else if (adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC saturated at VREF - sensor may be absent or disconnected\n");
        }

        float pressure = adc_to_pressure(adc_value);
        log_pressure(pressure);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

