 * Run:   sudo ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                         */
#define SPI_SPEED      1000000    /* 1 MHz                                    */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                    */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0           */
#define SAMPLE_PERIOD  5          /* Seconds between samples                  */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code               */
#define STUCK_THRESH   10         /* Count of consecutive stuck readings      */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* --------------------------- Signal Handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ SPI Helpers ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(fd, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------ Sensor Data ------------------------------ */
typedef struct {
    int adc_value;
    bool valid;
} sensor_data_t;

static sensor_data_t read_sensor(int fd, int channel)
{
    sensor_data_t data = { .adc_value = -1, .valid = false };

    int adc = read_mcp3008(fd, channel);
    if (adc < 0) {
        return data;
    }

    /*
     * Sensor-absent / wiring fault detection:
     *   0   -> no charge on the sensor's capacitance plate
     *   1023-> VREF at the ADC input (sensor absent or shorted to VREF)
     */
    if (adc == 0 || adc == ADC_MAX) {
        fprintf(stderr,
                "Warning: ADC reading stuck at %d (sensor absent or wiring fault).\n",
                adc);
    }

    data.adc_value = adc;
    data.valid = true;
    return data;
}

/* --------------------------------- Logging -------------------------------- */
static void log_data(int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] Soil Moisture ADC Value: %d\n", timestamp, adc_value);
    fflush(stdout);
}

/* --------------------------------- Cleanup -------------------------------- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        spiClose(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

/* ---------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_fd < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Data Logger\n");
    printf("SPI0 CE0 @ %d Hz, MCP3008 CH0 every %d s. Press Ctrl+C to exit.\n",
           SPI_SPEED, SAMPLE_PERIOD);
    fflush(stdout);

    /* --- Main loop --- */
    int stuck_count = 0;

    while (g_running) {
        sensor_data_t data = read_sensor(g_spi_fd, ADC_CHANNEL);

        if (data.valid) {
            log_data(data.adc_value);
            stuck_count = 0;
        } else {
            stuck_count++;
            fprintf(stderr,
                    "Error reading sensor data (stuck count: %d).\n",
                    stuck_count);

            if (stuck_count >= STUCK_THRESH) {
                fprintf(stderr,
                        "Too many consecutive errors - aborting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

