/*
 * Soil Moisture Monitor — Raspberry Pi Zero W
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 -> GPIO8, MOSI -> GPIO10, MISO -> GPIO9, SCLK -> GPIO11)
 *   - Generic soil moisture sensor analog output connected to MCP3008 channel 0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 *
 * Run:
 *   ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD_S 5          /* seconds between readings */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel, padded)
 *   tx[2] = 0x00                       (don't-care, clocks out low 2 bits)
 *
 * Result (10-bit) is assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    uint16_t value = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)rx[2];
    *out = value;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_moisture_percentage(uint16_t adc_value)
{
    float pct = ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f;
    if (pct < 0.0f)   pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ------------------------------------------- */
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI mode ---------------------------------------- */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI bits per word ------------------------------- */
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI max speed ----------------------------------- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitor started.\n");
    printf("SPI device : %s | Mode %u | %u bits | %u Hz\n",
           SPI_DEVICE, mode, bits, speed);
    printf("ADC channel: %u\n", ADC_CHANNEL);
    printf("Sample period: %d s\n", SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main sampling loop ---------------------------------------- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            float moisture = calculate_moisture_percentage(adc_value);
            printf("ADC: %4u  | Moisture: %5.1f%%\n", adc_value, moisture);
            fflush(stdout);
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    /* ---- Clean shutdown -------------------------------------------- */
    printf("\nExiting gracefully...\n");
    if (close(fd) < 0) {
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

