#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define NUM_SENSORS     4
#define SAMPLE_INTERVAL 1
#define CSV_FILENAME    "environmental_data.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %d: %s\n", channel, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3f / 1023.0f;
}

static void log_data(FILE *fp, float voltages[NUM_SENSORS]) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp,
            voltages[0], voltages[1], voltages[2], voltages[3]);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    g_csv_fp = fopen(CSV_FILENAME, "a");
    if (g_csv_fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", CSV_FILENAME, strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return 1;
    }

    fseek(g_csv_fp, 0, SEEK_END);
    long fsize = ftell(g_csv_fp);
    if (fsize == 0) {
        fprintf(g_csv_fp, "Timestamp,Sensor1,Sensor2,Sensor3,Sensor4\n");
        fflush(g_csv_fp);
    }

    printf("Starting environmental monitoring. Press Ctrl+C to stop.\n");

    while (g_running) {
        float voltages[NUM_SENSORS];
        int error_flag = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(g_spi_fd, i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                error_flag = 1;
                break;
            }
            voltages[i] = adc_to_voltage(adc_value);
        }

        if (!error_flag) {
            log_data(g_csv_fp, voltages);
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");

    if (g_csv_fp != NULL) {
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    return 0;
}

