/*
 * Soil Moisture Monitor with MCP3008 ADC and Relay-Controlled Pump
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern GPIO/SPI API)
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK, BCM 11)
 *   MCP3008 DOUT -> GPIO9  (MISO,  BCM 9)
 *   MCP3008 DIN  -> GPIO10 (MOSI, BCM 10)
 *   MCP3008 CS   -> GPIO8  (CE0,  BCM 8)
 *   MCP3008 CH0  -> Vegetronix VH400 analog output
 *   Relay IN     -> GPIO17 (BCM 17)
 *   Relay VCC    -> 12 V, Relay GND -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:    sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 on SPI bus 0 (BCM 8)              */
#define SPI_SPEED        1000000    /* 1 MHz                                 */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                 */
#define MCP3008_CHANNEL  0          /* Single-ended CH0                      */
#define PUMP_GPIO        17         /* BCM 17, active-high relay             */
#define LOW_THRESHOLD    300        /* Turn pump ON  below this reading      */
#define HIGH_THRESHOLD   600        /* Turn pump OFF above this reading      */
#define SAMPLE_PERIOD_US 5000000    /* 5 seconds in microseconds            */
#define BUFFER_SIZE      20

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static int      g_pump_state = 0;   /* 0 = off, 1 = on                       */

/* Circular buffer */
typedef struct {
    time_t timestamp;
    int    moisture_level;
    int    pump_state;
} LogEntry;

static LogEntry g_log_buffer[BUFFER_SIZE];
static int      g_buffer_index = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static void control_pump(int moisture_level);
static void log_data(int moisture_level, int pump_state);
static void print_buffer(void);
static void timer_callback(void *userdata);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- MCP3008 Read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX: [0x01] [SGL|D2|D1|D0 << 4] [0x00]
 *   RX: [don't care] [don't care] [b9 b8 .. b0]  -> 10-bit result
 * Returns 0-1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * pigpio's spiOpen flags bit 0 = active-low CE polarity.
     * SPI mode 0: CPOL=0, CPHA=0.
     */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ----------------------------- Pump Control ------------------------------ */
static void control_pump(int moisture_level)
{
    if (moisture_level < LOW_THRESHOLD && g_pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            g_pump_state = 1;
            printf("Pump ON  (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to set pump GPIO high\n");
        }
    } else if (moisture_level > HIGH_THRESHOLD && g_pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            g_pump_state = 0;
            printf("Pump OFF (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to set pump GPIO low\n");
        }
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(int moisture_level, int pump_state)
{
    time_t now = time(NULL);
