 * Build:  gcc -Wall -Wextra -O2 -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:    sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
