/* ----------------------------- MCP3008 Read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX: [0x01] [SGL|D2|D1|D0 << 4] [0x00]
 *   RX: [don't care] [don't care] [b9 b8 .. b0]  -> 10-bit result
 * Returns 0-1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * pigpio's spiOpen flags bit 0 = active-low CE polarity.
     * SPI mode 0: CPOL=0, CPHA=0.
     */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

