/*
 * MAX30102 Pulse Oximeter Monitor for Raspberry Pi Zero W
 *
 * Monitors SpO2 and Heart Rate once per second.
 * Logs events below 95% SpO2 or above 100 BPM to health_log.txt.
 *
 * Wiring:
 *   MAX30102 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MAX30102 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MAX30102 VDD -> 3.3V
 *   MAX30102 GND -> GND
 *
 * Build: gcc -O2 -Wall -o max30102_monitor max30102_monitor.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MAX30102_ADDR  0x57

/* MAX30102 Registers */
#define REG_INTR_STATUS_1  0x00
#define REG_INTR_STATUS_2  0x01
#define REG_INTR_ENABLE_1  0x02
#define REG_INTR_ENABLE_2  0x03
#define REG_FIFO_WR_PTR    0x04
#define REG_OVERFLOW_CTR   0x05
#define REG_FIFO_RD_PTR    0x06
#define REG_FIFO_DATA      0x07
#define REG_FIFO_CONFIG    0x08
#define REG_MODE_CONFIG    0x09
#define REG_SPO2_CONFIG    0x0A
#define REG_LED1_PA        0x0C
#define REG_LED2_PA        0x0D
#define REG_PART_ID        0xFF

#define EXPECTED_PART_ID   0x15

#define SPO2_THRESHOLD     95
#define HR_THRESHOLD       100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_max30102(int fd)
{
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "MAX30102 Part ID mismatch: got 0x%02X, expected 0x%02X\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }

    /* Reset device */
    if (i2c_write_reg8(fd, REG_MODE_CONFIG, 0x40) < 0)
        return -1;
    usleep(10000);

    /* Disable interrupts */
    if (i2c_write_reg8(fd, REG_INTR_ENABLE_1, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, REG_INTR_ENABLE_2, 0x00) < 0)
        return -1;

    /* FIFO: sample averaging 4, almost-full threshold 17 */
    if (i2c_write_reg8(fd, REG_FIFO_CONFIG, 0x0F) < 0)
        return -1;

    /* Mode: SpO2 + Red LED */
    if (i2c_write_reg8(fd, REG_MODE_CONFIG, 0x03) < 0)
        return -1;

    /* SpO2: 4096us sample, 100us LED pulse, 4096us range */
    if (i2c_write_reg8(fd, REG_SPO2_CONFIG, 0x27) < 0)
        return -1;

    /* LED pulse amplitudes: ~2.5mA for both channels */
    if (i2c_write_reg8(fd, REG_LED1_PA, 0x24) < 0)
        return -1;
    if (i2c_write_reg8(fd, REG_LED2_PA, 0x24) < 0)
        return -1;

    return 0;
}

static int read_max30102_data(int fd, uint16_t *red, uint16_t *ir)
{
    uint16_t r, i;
    if (i2c_read_reg16(fd, 0x0F, &r) < 0)
        return -1;
    if (i2c_read_reg16(fd, 0x10, &i) < 0)
        return -1;
    *red = r;
    *ir  = i;
    return 0;
}

static int calculate_spo2(uint16_t red, uint16_t ir)
{
    if (ir == 0)
        return 0;
    float ratio = (float)red / (float)ir;
    float spo2 = 110.0f - 25.0f * ratio;
    if (spo2 < 0.0f)
        spo2 = 0.0f;
    if (spo2 > 100.0f)
        spo2 = 100.0f;
    return (int)spo2;
}

static int calculate_heart_rate(uint16_t ir)
{
    /* Placeholder: real heart-rate calculation requires a proper PPG signal */
    (void)ir;
    return 70;
}

static void log_event(int spo2, int heart_rate)
{
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open health_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, SpO2: %d%%, Heart Rate: %d BPM\n", ts, spo2, heart_rate);
    }
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MAX30102_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MAX30102_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_max30102(g_i2c_fd) < 0) {
        fprintf(stderr, "MAX30102 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MAX30102 initialized. Monitoring SpO2 and Heart Rate...\n");

    while (g_running) {
        uint16_t red, ir;
        if (read_max30102_data(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Failed to read MAX30102 data.\n");
            sleep(1);
            continue;
        }

        int spo2 = calculate_spo2(red, ir);
        int heart_rate = calculate_heart_rate(ir);

        printf("SpO2: %d%%, Heart Rate: %d BPM\n", spo2, heart_rate);

        if (spo2 < SPO2_THRESHOLD || heart_rate > HR_THRESHOLD) {
            log_event(spo2, heart_rate);
            printf("Event logged to health_log.txt\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, REG_MODE_CONFIG, 0x40);
        close(g_i2c_fd);
    }
    return EXIT_SUCCESS;
}

