/*
 * MQ-2 gas sensor monitor with MCP3008 ADC and active buzzer.
 *
 * Hardware (Raspberry Pi 40-pin header):
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 9,  SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 10, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  SPI0 CE0)
 *   MCP3008 CH0  -> MQ-2 analog output
 *   Buzzer +     -> GPIO24 (BCM 24) via transistor/MOSFET
 *   Buzzer -     -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mq2_buzzer mq2_buzzer.c -lpigpio -lrt
 * Run:    sudo ./mq2_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)  */
#define SPI_SPEED      1000000    /* 1 MHz             */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define MCP3008_CHANNEL 0         /* Single-ended CH0 */
#define BUZZER_PIN      24        /* BCM 24 */
#define THRESHOLD       500       /* ADC count threshold */
#define SAMPLE_US       500000    /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.      */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     *
     * Result (10-bit) is assembled from:
     *   ((rx[1] & 0x03) << 8) | rx[2]
     */
    unsigned char tx[3] = { 0x01,
                            (unsigned char)((0x08 | channel) << 4),
                            0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static int control_buzzer(int on)
{
    int rc = gpioWrite(BUZZER_PIN, on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN=%d, %d) failed: %s\n",
                BUZZER_PIN, on, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Safe state: buzzer off, GPIO24 low */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetMode(BUZZER_PIN, PI_INPUT);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Buzzer pin setup ------------------------------------------ */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN=%d, PI_OUTPUT) failed\n",
                BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_PIN, 0);   /* start with buzzer off */

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen(channel=%d, speed=%d, flags=%d) failed: %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS,
                pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitor started.\n");
    printf("SPI channel %d, ADC channel %d, buzzer on GPIO%d, threshold %d.\n",
           SPI_CHANNEL, MCP3008_CHANNEL, BUZZER_PIN, THRESHOLD);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int buzzer_on = (adc_value >= THRESHOLD) ? 1 : 0;
        if (control_buzzer(buzzer_on) < 0) {
            fprintf(stderr, "Buzzer control failed — continuing\n");
        }

        printf("ADC: %4d  Buzzer: %s\n",
               adc_value, buzzer_on ? "ON" : "off");

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

