        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Safe state: buzzer off, GPIO24 low */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetMode(BUZZER_PIN, PI_INPUT);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Buzzer pin setup ------------------------------------------ */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN=%d, PI_OUTPUT) failed\n",
                BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_PIN, 0);   /* start with buzzer off */

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen(channel=%d, speed=%d, flags=%d) failed: %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS,
                pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitor started.\n");
    printf("SPI channel %d, ADC channel %d, buzzer on GPIO%d, threshold %d.\n",
           SPI_CHANNEL, MCP3008_CHANNEL, BUZZER_PIN, THRESHOLD);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int buzzer_on = (adc_value >= THRESHOLD) ? 1 : 0;
        if (control_buzzer(buzzer_on) < 0) {
            fprintf(stderr, "Buzzer control failed — continuing\n");
        }

        printf("ADC: %4d  Buzzer: %s\n",
               adc_value, buzzer_on ? "ON" : "off");

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

