/*
 * door_lock_release.c — Raspberry Pi 5 (Bookworm, kernel 6.6+)
 *
 * Monitors a Sharp GP2Y0A21YK0F IR distance sensor via an ADS1115 ADC
 * on /dev/i2c-1, samples every 200 ms after calibration, and when the
 * distance reading falls below the calibrated threshold it pulses the
 * relay on GPIO17 for 3 s to release a door lock.  The magnetic reed
 * sensor on GPIO27 (active-low, pull-up) is read to log whether the
 * door was actually opened.
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2  (BCM)
 *   ADS1115 SCL -> GPIO3  (BCM)
 *   ADS1115 ADDR-> GND    (I2C address 0x48)
 *   ADS1115 A0  -> GP2Y0A21YK0F analog out
 *   Relay IN    -> GPIO17 (BCM, active-high)
 *   Reed sensor -> GPIO27 (BCM, active-low, pull-up)
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock_release door_lock_release.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CFG  0x01

/* Config register bits */
#define ADS1115_CFG_OS    0x8000  /* Operational status / single-shot start */
#define ADS1115_CFG_MUX_A0 0x4000 /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096 0x0200
#define ADS1115_CFG_MODE_SS  0x0100 /* Single-shot mode */
#define ADS1115_CFG_DR_128   0x0080 /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003

#define RELAY_GPIO       17
#define REED_GPIO        27

#define LOG_FILE         "/var/log/door_events.log"

#define SAMPLE_PERIOD_MS 200
#define CALIB_SAMPLES    10
#define CALIB_INTERVAL_MS 50
#define RELAY_PULSE_MS   3000
#define POLL_INTERVAL_MS 100

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* --------------------------- Signal handling ----------------------------- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&ts.tv_sec, &tm_buf);
    if (!tm) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char tbuf[64];
    if (strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, msg);
    fclose(fp);
}

/* ------------------------------- GPIO helpers ----------------------------- */
static int gpio_export(int pin)
{
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (len < 0 || (size_t)len >= sizeof(buf))
        return -1;

    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (!fp) {
        if (errno == EBUSY) {
            /* Already exported — that's fine. */
            errno = 0;
            return 0;
        }
        fprintf(stderr, "gpio_export(%d): %s\n", pin, strerror(errno));
        return -1;
    }
    if (fwrite(buf, 1, (size_t)len, fp) != (size_t)len) {
        fprintf(stderr, "gpio_export write: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_unexport(int pin)
{
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (len < 0 || (size_t)len >= sizeof(buf))
        return -1;

    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (!fp) {
        fprintf(stderr, "gpio_unexport(%d): %s\n", pin, strerror(errno));
        return -1;
    }
    if (fwrite(buf, 1, (size_t)len, fp) != (size_t)len) {
        fprintf(stderr, "gpio_unexport write: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "gpio_set_direction(%d): %s\n", pin, strerror(errno));
        return -1;
    }
    if (fwrite(dir, 1, strlen(dir), fp) != strlen(dir)) {
        fprintf(stderr, "gpio_set_direction write: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_write(int pin, int val)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "gpio_write(%d): %s\n", pin, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", val) < 0) {
        fprintf(stderr, "gpio_write write: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_read(int pin)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "gpio_read(%d): %s\n", pin, strerror(errno));
        return -1;
    }
    int val = fgetc(fp);
    fclose(fp);
    if (val == '0') return 0;
    if (val == '1') return 1;
    return -1;
}

/* ------------------------------- I2C helpers ------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    struct i2c_msg msg = {
        .addr  = ADS1115_ADDR,
        .flags = 0,
        .len   = 3,
        .buf   = buf,
    };
    struct i2c_rdwr_ioctl_data data = {
        .msgs  = &msg,
        .nmsgs = 1,
    };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "i2c_write16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0,            .len = 1, .buf = &reg_buf },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD,     .len = 2, .buf = (uint8_t *)out },
    };
    struct i2c_rdwr_ioctl_data data = {
        .msgs  = msgs,
        .nmsgs = 2,
    };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "i2c_read16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------- ADS1115 ---------------------------------- */
static int ads1115_init(int fd)
{
    /*
     * Config: single-shot, AIN0 single-ended, PGA ±4.096 V, 128 SPS,
     * comparator disabled.
     */
    uint16_t cfg = ADS1115_CFG_OS | ADS1115_CFG_MUX_A0 |
                   ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                   ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) == -1)
        return -1;
    return 0;
}

static int ads1115_read_raw(int fd, int16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_OS | ADS1115_CFG_MUX_A0 |
                   ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                   ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) == -1)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    usleep(10000);

    uint16_t val;
    if (i2c_read16(fd, ADS1115_REG_CONV, &val) == -1)
        return -1;

    *raw = (int16_t)val;
    return 0;
}

/* ------------------------------- Calibration ------------------------------ */
static int calibrate_threshold(int fd, int *threshold)
{
    int sum = 0;
    int valid = 0;

    for (int i = 0; i < CALIB_SAMPLES; i++) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) == -1) {
            fprintf(stderr, "Calibration read %d failed\n", i);
            return -1;
        }
        sum += raw;
        valid++;
        usleep(CALIB_INTERVAL_MS * 1000);
    }

    if (valid == 0) {
        fprintf(stderr, "No valid calibration samples\n");
        return -1;
    }

    *threshold = sum / valid;
    printf("Calibration complete: threshold = %d\n", *threshold);
    return 0;
}

/* ------------------------------- Main loop -------------------------------- */
int main(void)
{
    int threshold = 0;

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* ---- GPIO setup ---- */
    if (gpio_export(RELAY_GPIO) == -1)
        return EXIT_FAILURE;
    if (gpio_export(REED_GPIO) == -1) {
        gpio_unexport(RELAY_GPIO);
        return EXIT_FAILURE;
    }
    if (gpio_set_direction(RELAY_GPIO, "out") == -1) {
        gpio_unexport(RELAY_GPIO);
        gpio_unexport(REED_GPIO);
        return EXIT_FAILURE;
    }
    if (gpio_set_direction(REED_GPIO, "in") == -1) {
        gpio_unexport(RELAY_GPIO);
        gpio_unexport(REED_GPIO);
        return EXIT_FAILURE;
    }
    if (gpio_write(RELAY_GPIO, 0) == -1) {
        gpio_unexport(RELAY_GPIO);
        gpio_unexport(REED_GPIO);
        return EXIT_FAILURE;
    }

    /* ---- I2C setup ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        gpio_unexport(RELAY_GPIO);
        gpio_unexport(REED_GPIO);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpio_unexport(RELAY_GPIO);
        gpio_unexport(REED_GPIO);
        return EXIT_FAILURE;
    }

    if (ads1115_init(g_i2c_fd) == -1) {
        fprintf(stderr, "ADS1115 init failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        gpio_unexport(RELAY_GPIO);
        gpio_unexport(REED_GPIO);
        return EXIT_FAILURE;
    }

    /* ---- Calibration ---- */
    if (calibrate_threshold(g_i2c_fd, &threshold) == -1) {
        fprintf(stderr, "Calibration failed\n");
        close(g_i2c_fd);
        gpio_unexport(RELAY_GPIO);
        gpio_unexport(REED_GPIO);
        return EXIT_FAILURE;
    }

    printf("Starting monitoring loop (threshold=%d)...\n", threshold);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) == -1) {
            log_event("I2C read error — continuing");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if ((int)raw < threshold) {
            printf("Distance below threshold (%d < %d) — releasing lock\n",
                   raw, threshold);

            if (gpio_write(RELAY_GPIO, 1) == -1) {
                log_event("Relay pulse start failed");
            } else {
                log_event("Relay activated");
            }

            /* Pulse the relay for 3 s. */
            for (int elapsed = 0; elapsed < RELAY_PULSE_MS && g_running; elapsed += POLL_INTERVAL_MS)
                usleep(POLL_INTERVAL_MS * 1000);

            if (gpio_write(RELAY_GPIO, 0) == -1) {
                log_event("Relay pulse end failed");
            } else {
                log_event("Relay deactivated");
            }

            /* Read reed sensor after the pulse. */
            int reed = gpio_read(REED_GPIO);
            if (reed == -1) {
                log_event("Reed sensor read error");
            } else if (reed == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpio_write(RELAY_GPIO, 0);
    gpio_unexport(RELAY_GPIO);
    gpio_unexport(REED_GPIO);
    if (g_i2c_fd != -1)
        close(g_i2c_fd);

    return EXIT_SUCCESS;
}

