/*
 * Raspberry Pi 5 – Simultaneous MCP3008 ADC logging (3 sensors)
 *
 * Wiring (BCM numbering):
 *   SPI0 MOSI  -> GPIO10
 *   SPI0 MISO  -> GPIO9
 *   SPI0 SCLK  -> GPIO11
 *   MCP3008 CS0-> GPIO8
 *   MCP3008 CS1-> GPIO7
 *   MCP3008 CS2-> GPIO25
 *
 * Build:  gcc -O2 -Wall -o soil_log soil_log.c -lpigpio -lrt
 * Run:    sudo ./soil_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 limits */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define NUM_SENSORS     3
#define LOG_INTERVAL_S  5
#define LOG_FILE        "soil_moisture_log.csv"

/* BCM GPIO pins for manual CS control */
static const int cs_pins[NUM_SENSORS] = {8, 7, 25};

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from an MCP3008.
 * Returns 0–1023 on success, -1 on error.                             */
static int read_mcp3008(int fd, int cs_pin, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    /* Assert chip-select (active low) */
    if (gpioWrite(cs_pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(CS low) failed on pin %d\n", cs_pin);
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed on CS%d (ioctl returned %d): %s\n",
                cs_pin, ret, strerror(errno));
        gpioWrite(cs_pin, 1);   /* release CS on error */
        return -1;
    }

    /* Deassert chip-select */
    if (gpioWrite(cs_pin, 1) < 0) {
        fprintf(stderr, "gpioWrite(CS high) failed on pin %d\n", cs_pin);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int s1, int s2, int s3)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, s1, s2, s3) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int initialize_spi(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure manual CS pins as outputs, deasserted ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(cs_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode(CS) failed on pin %d\n", cs_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(cs_pins[i], 1) < 0) {
            fprintf(stderr, "gpioWrite(CS high) failed on pin %d\n", cs_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = initialize_spi();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append; write header if new) ---- */
    int file_exists = (access(LOG_FILE, F_OK) == 0);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            fprintf(stderr, "Cannot write header: %s\n", strerror(errno));
            fclose(fp);
            close(g_spi_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fflush(fp);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(fp);
        close(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int s1 = read_mcp3008(g_spi_fd, cs_pins[0], 0);
        int s2 = read_mcp3008(g_spi_fd, cs_pins[1], 0);
        int s3 = read_mcp3008(g_spi_fd, cs_pins[2], 0);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);   /* 100 ms */
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    fclose(fp);
    close(g_spi_fd);
    g_spi_fd = -1;
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

