    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(fp);
        close(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int s1 = read_mcp3008(g_spi_fd, cs_pins[0], 0);
        int s2 = read_mcp3008(g_spi_fd, cs_pins[1], 0);
        int s3 = read_mcp3008(g_spi_fd, cs_pins[2], 0);

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
