/*
 * Soil moisture monitor and irrigator for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - Vegetronix VH400 soil moisture sensor  -> MCP3008 channel 0
 *   - MCP3008 ADC on SPI0 (CE0 / GPIO 8), 1 MHz, mode 0
 *   - Relay/water-pump driver on GPIO 18 (BCM, active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO 8)                       */
#define SPI_SPEED        1000000    /* 1 MHz                                   */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                   */

#define PUMP_GPIO        18         /* BCM 18, active-high relay/pump driver   */

#define DEFAULT_THRESHOLD   30.0f   /* % of 0-3V range                         */
#define DEFAULT_PUMP_DURATION 10    /* seconds                                */
#define DEFAULT_SLEEP_INTERVAL 60   /* seconds                                */
#define LOG_FILE         "irrigation.log"

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0          */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC                              */
#define VREF             3.3f       /* Reference voltage                       */
#define SENSOR_VMAX      3.0f       /* Vegetronix VH400 full-dry output        */

#define SPI_RETRIES      3
#define SPI_RETRY_DELAY  100000     /* microseconds between retries            */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static int  g_pump_gpio  = PUMP_GPIO;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  read_mcp3008(int channel, int *out_value);
static int  read_moisture_level(float *out_percent);
static void control_pump(int on);
static void log_event(const char *msg);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ SPI / ADC -------------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on failure.
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        log_event("Invalid ADC channel requested");
        return -1;
    }
    if (out_value == NULL) {
        log_event("read_mcp3008: NULL output pointer");
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   Byte 2: 0x00                       (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= SPI_RETRIES; ++attempt) {
        int rc = spiXfer(g_spi_handle, tx, rx, 3);
        if (rc == 3) {
            int value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            if (value < 0 || value > ADC_MAX_VALUE) {
                log_event("ADC value out of range");
                return -1;
            }
            *out_value = value;
            return 0;
        }
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "SPI transfer failed (attempt %d/%d): rc=%d",
                 attempt, SPI_RETRIES, rc);
        log_event(msg);
        if (attempt < SPI_RETRIES)
            gpioDelay(SPI_RETRY_DELAY);
    }
    return -1;
}

/*
 * Convert ADC count to a percentage of the 0-3V range.
 * Returns 0 on success, -1 on error.
 */
static int read_moisture_level(float *out_percent)
{
    int adc;
    if (read_mcp3008(ADC_CHANNEL, &adc) != 0)
        return -1;

    float voltage = (float)adc * VREF / (float)(ADC_MAX_VALUE + 1);
    float percent = (voltage / SENSOR_VMAX) * 100.0f;
    if (percent < 0.0f)   percent = 0.0f;
    if (percent > 100.0f) percent = 100.0f;

    char msg[128];
    snprintf(msg, sizeof(msg),
             "ADC=%d  V=%.3f  moisture=%.1f%%", adc, voltage, percent);
    log_event(msg);

    *out_percent = percent;
    return 0;
}

/* ------------------------------ Pump control ----------------------------- */

static void control_pump(int on)
{
    if (gpioWrite(g_pump_gpio, on ? 1 : 0) != 0) {
        log_event(on ? "Failed to activate pump" : "Failed to deactivate pump");
        return;
    }
    log_event(on ? "Pump activated" : "Pump deactivated");
}

/* ------------------------------- Logging --------------------------------- */

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------ Cleanup ---------------------------------- */

static void cleanup(void)
{
    /* Ensure pump is off before releasing resources. */
    if (g_spi_handle >= 0) {
        gpioWrite(g_pump_gpio, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */

int main(int argc, char *argv[])
{
    float threshold   = DEFAULT_THRESHOLD;
    int   pump_duration = DEFAULT_PUMP_DURATION;
    int   sleep_interval = DEFAULT_SLEEP_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
        case 't':
            threshold = atof(optarg);
            if (threshold < 0.0f || threshold > 100.0f) {
                fprintf(stderr, "Threshold must be 0-100%% (got %.2f)\n", threshold);
                return EXIT_FAILURE;
            }
            break;
        case 'd':
            pump_duration = atoi(optarg);
            if (pump_duration <= 0) {
                fprintf(stderr, "Pump duration must be positive (got %d)\n", pump_duration);
                return EXIT_FAILURE;
            }
            break;
        case 's':
            sleep_interval = atoi(optarg);
            if (sleep_interval <= 0) {
                fprintf(stderr, "Sleep interval must be positive (got %d)\n", sleep_interval);
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr,
                    "Usage: %s [-t threshold%%] [-d pump_duration_s] [-s sleep_interval_s]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Pump GPIO ---- */
    if (gpioSetMode(g_pump_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", g_pump_gpio);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(g_pump_gpio, 0);

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char banner[160];
    snprintf(banner, sizeof(banner),
             "Irrigation system started: threshold=%.1f%%  pump=%ds  sleep=%ds",
             threshold, pump_duration, sleep_interval);
    log_event(banner);

    /* ---- Main loop ---- */
    while (g_running) {
        float moisture;
        if (read_moisture_level(&moisture) != 0) {
            log_event("Sensor read failed after retries; skipping irrigation cycle");
        } else if (moisture < threshold) {
            log_event("Moisture below threshold; activating pump");
            control_pump(1);
            /*
             * Sleep in 1-second increments so SIGINT/SIGTERM is noticed promptly.
             */
            for (int s = 0; s < pump_duration && g_running; ++s)
                sleep(1);
            control_pump(0);
        } else {
            log_event("Moisture sufficient; pump idle");
        }

        /*
         * Sleep in 1-second increments so SIGINT/SIGTERM is noticed promptly.
         */
        for (int s = 0; s < sleep_interval && g_running; ++s)
            sleep(1);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

