/*
 * PCF8591 AIN0 monitor — Raspberry Pi
 *
 * Wiring:
 *   PCF8591 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   PCF8591 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   PCF8591 VDD  -> 3.3 V
 *   PCF8591 VSS  -> GND
 *   PCF8591 A0   -> GND  (AIN0 single-ended)
 *
 * The PCF8591 returns the result of the *previous* conversion on the
 * first read after a write that selects a new channel or mode.  To
 * get a fresh reading we first issue a dummy write (control byte 0x40)
 * to prime the conversion, then a second read returns the current
 * sample.
 *
 * Build:  gcc -O2 -Wall -Wextra -o pcf8591_ain0 pcf8591_ain0.c
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48          /* default 7-bit address */
#define PCF8591_CTRL   0x40          /* AIN0 single-ended, auto-increment off */

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_sigint_handler() != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Prime the PCF8591: write the control byte to select AIN0
     * single-ended and start the first conversion.
     */
    uint8_t ctrl = PCF8591_CTRL;
    if (write(fd, &ctrl, 1) != 1) {
        fprintf(stderr, "write(control byte) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Dummy read: the first byte returned is the result of the
     * previous conversion.  Discard it.
     */
    uint8_t dummy;
    if (read(fd, &dummy, 1) != 1) {
        fprintf(stderr, "dummy read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (!g_stop) {
        uint8_t sample;
        ssize_t n = read(fd, &sample, 1);
        if (n != 1) {
            if (g_stop)
                break;
            fprintf(stderr, "read(AIN0) failed: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("AIN0: %3u  (%.1f%%)\n", sample,
               (double)sample / 255.0 * 100.0);
        fflush(stdout);

        usleep(100000);  /* 100 ms */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

