code:
/*
 * Raspberry Pi 3 Model B+ — Honeywell SS49E Hall sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E (linear Hall sensor) on ADS1115 channel AIN0
 *   - ADS1115 ADC on I2C bus 1, address 0x48
 *   - GPIO27 (BCM) driven HIGH on threshold breach
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lm
 *
 * Run:
 *   ./hall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word for single-shot reads on AIN0, single-shot mode,
 * 4.096 V gain, 128 SPS, no comparator.
 *
 *   Bit 15    1   Operational status / single-shot start
 *   Bits 14:12 100 AIN0 single-ended
 *   Bit 11    0   Mux gain 4.096 V
 *   Bit 10    0   0 = traditional comparator
 *   Bits 9:8  10  128 SPS
 *   Bit  7    0   No comparator mode
 *   Bits 5:4  00  Active low, non-latching, 1 sample
 *   Bit  3    0   Non-continuous comparator
 *   Bits 1:0  11  Assert after 1 conversion
 */
#define ADS1115_CONFIG_BASE 0x8483

#define GPIO_PIN          27
#define THRESHOLD_GAUSS   500.0f
#define BUFFER_SIZE       10
#define SAMPLE_PERIOD_US  1000000  /* 1 second */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  i2c_write_reg16(int fd, uint8_t reg, uint16_t val);
static int  i2c_read_reg16(int fd, uint8_t reg, uint16_t *out);
static int  ads1115_read_ain0(int fd, int16_t *raw_out);
static float voltage_to_gauss(float v);
static void buffer_push(float v, float *buf, int *idx, int sz);
static float buffer_avg(const float *buf, int sz);
static void gpio_set(int pin, int val);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */

/* Write a 16-bit value to an ADS1115 register (big-endian on the bus). */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        syslog(LOG_ERR, "I2C write to reg 0x%02X failed", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (big-endian on the bus). */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed", reg);
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        syslog(LOG_ERR, "I2C read from reg 0x%02X failed", reg);
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the raw 16-bit result.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_ain0(int fd, int16_t *raw_out)
{
    uint16_t cfg = ADS1115_CONFIG_BASE;

    /* Write config to start a conversion */
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw_u;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw_u) < 0)
        return -1;

    *raw_out = (int16_t)raw_u;
    return 0;
}

/* ----------------------------- Conversions ------------------------------- */

/*
 * Convert a raw ADS1115 reading to a magnetic field strength in Gauss.
 *
 * ADS1115 at gain 4.096 V: 1 LSB = 125 µV.
 * SS49E: 1 mT = 100 G.
 *
 * raw * 0.000125 / 0.001 = raw * 0.000125 * 100 = raw * 0.125
 */
static float voltage_to_gauss(float v)
{
    return v * 0.125f * 100.0f;
}

/* ----------------------------- Circular buffer --------------------------- */

static void buffer_push(float v, float *buf, int *idx, int sz)
{
    buf[*idx] = v;
    *idx = (*idx + 1) % sz;
}

static float buffer_avg(const float *buf, int sz)
{
    float sum = 0.0f;
    for (int i = 0; i < sz; i++)
        sum += buf[i];
    return sum / (float)sz;
}

/* ----------------------------- GPIO helpers ------------------------------ */

static void gpio_set(int pin, int val)
{
    char path[32];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "open GPIO%d value failed", pin);
        return;
    }
    if (write(fd, val ? "1" : "0", 1) != 1)
        syslog(LOG_ERR, "write GPIO%d failed", pin);
    close(fd);
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpio_set(GPIO_PIN, 0);
    closelog();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "open %s failed", I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "ioctl I2C_SLAVE 0x%02X failed", ADS1115_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the default config */
    uint16_t cfg_check;
    if (i2c_read_reg16(g_i2c_fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        syslog(LOG_ERR, "ADS1115 not responding at 0x%02X", ADS1115_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO27 as output, initial LOW */
    gpio_set(GPIO_PIN, 0);

    /* Circular buffer */
    float buffer[BUFFER_SIZE];
    int   buf_idx = 0;
    for (int i = 0; i < BUFFER_SIZE; i++)
        buffer[i] = 0.0f;

    syslog(LOG_INFO, "Hall monitor started (threshold %.1f G)", THRESHOLD_GAUSS);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(g_i2c_fd, &raw) < 0) {
            syslog(LOG_ERR, "ADC read failure — sample skipped");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = (float)raw * 0.000125f;  /* 4.096 V gain */

        if (voltage < 0.0f || voltage > 3.3f) {
            syslog(LOG_ERR, "Voltage out of range: %.4f V", voltage);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        buffer_push(gauss, buffer, &buf_idx, BUFFER_SIZE);
        float avg = buffer_avg(buffer, BUFFER_SIZE);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_ERR, "Threshold breach: avg %.2f G > %.1f G",
                   avg, THRESHOLD_GAUSS);
            gpio_set(GPIO_PIN, 1);
        } else {
            gpio_set(GPIO_PIN, 0);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

