/*
 * Raspberry Pi Zero W - Soil Moisture Monitor & Pump Controller
 *
 * Hardware:
 *   - Vegetronix VH400 soil moisture sensor -> MCP3008 ADC channel 0
 *   - MCP3008 SPI: SPI0 CE0 (GPIO8), SCLK (GPIO11), MOSI (GPIO10), MISO (GPIO9)
 *   - Relay/pump on GPIO18 (BCM)
 *
 * Behavior:
 *   - Reads VH400 via MCP3008 channel 0 every 60 s.
 *   - When moisture < 300, runs pump for 10 s, logs event.
 *   - Graceful shutdown on SIGINT/SIGTERM.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for SPI/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                       */
#define SPI_SPEED        1000000    /* 1 MHz                                  */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                  */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0         */
#define MOISTURE_THRESH  300        /* 10-bit threshold                       */
#define PUMP_GPIO        18         /* BCM pin for relay/pump                 */
#define PUMP_DURATION_S  10         /* Pump-on duration per event             */
#define SAMPLE_INTERVAL  60         /* Seconds between readings              */
#define LOG_FILE         "watering_events.txt"
#define ADC_MAX          1023       /* 10-bit ADC full-scale code              */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pigpio_ready = 0;

/* --------------------------- Function prototypes ------------------------- */
static int  read_mcp3008(int channel, int *out_value);
static void control_pump(int on);
static void log_event(int moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MCP3008 --------------------------------- */
/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on error.
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   tx[2] = 0x00                       (clock out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    if (value < 0 || value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", value);
        return -1;
    }

    *out_value = value;
    return 0;
}

/* ------------------------------- Pump GPIO -------------------------------- */
static void control_pump(int on)
{
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", PUMP_GPIO, on);
    }
}

/* ------------------------------- Logging ---------------------------------- */
static void log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture: %d - Watering ON\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

/* --------------------------- Signal handling ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly                 */
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_pigpio_ready) {
        control_pump(0);    /* ensure pump is off                         */
        if (g_spi_handle >= 0) {
            spiClose(g_spi_handle);
            g_spi_handle = -1;
        }
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_pump(0);        /* start with pump off                        */

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen(%d, %d, %d) failed (handle=%d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started.\n");
    printf("  ADC channel : %d\n", ADC_CHANNEL);
    printf("  Pump GPIO   : %d\n", PUMP_GPIO);
    printf("  Threshold   : %d\n", MOISTURE_THRESH);
    printf("  Sample int.: %d s\n", SAMPLE_INTERVAL);
    printf("  Log file    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int moisture = -1;

        if (read_mcp3008(ADC_CHANNEL, &moisture) < 0) {
            fprintf(stderr, "Error: ADC read failed; skipping cycle\n");
        } else {
            printf("Moisture level: %d\n", moisture);

            if (moisture < MOISTURE_THRESH) {
                printf("Moisture below threshold (%d). Activating pump for %d s...\n",
                       MOISTURE_THRESH, PUMP_DURATION_S);

                control_pump(1);
                log_event(moisture);

                /*
                 * Sleep in 1-second increments so we can respond to signals
                 * promptly during the pump-on window.
                 */
                for (int i = 0; i < PUMP_DURATION_S && g_running; i++) {
                    sleep(1);
                }

                control_pump(0);
                printf("Pump deactivated.\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

