/*
 * Rain sensor monitor using MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  pin 24)
 *   MCP3008 DGND -> GND  (pin 6)
 *   YL-83 AOUT   -> MCP3008 CH0
 *   YL-83 VCC    -> 3.3 V
 *   YL-83 GND    -> GND
 *
 * Build:  gcc -O2 -Wall -o rain_monitor rain_monitor.c -lpigpio -lrt
 * Run:    sudo ./rain_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (bus 0, channel 0)            */
#define SPI_SPEED      1000000    /* 1 MHz                                  */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                  */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0         */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code              */
#define SAMPLE_PERIOD  1          /* seconds between readings               */
#define VREF           3.3f       /* ADC reference voltage (volts)          */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ MCP3008 ---------------------------------- */
/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (value stored in *out), -1 on SPI transfer failure.
 */
static int read_mcp3008(int handle, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3-byte transfer, mode 0, MSB-first):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (don't-care)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in the two LSBs
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint16_t value = ((uint16_t)(rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    *out = value;
    return 0;
}

/* ------------------------------ Intensity -------------------------------- */
static float calculate_rainfall_intensity(uint16_t adc_value)
{
    /*
     * YL-83 output: dry air -> ~0 V (0 ADC), rain -> ~3.3 V (1023 ADC).
     * Map linearly to 0.0 (dry) -> 1.0 (heavy).
     */
    float intensity = (float)adc_value / (float)ADC_MAX;
    if (intensity < 0.0f) intensity = 0.0f;
    if (intensity > 1.0f) intensity = 1.0f;
    return intensity;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

