    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("SPI channel %d, ADC channel %d, sampling every %d s.\n",
           SPI_CHANNEL, ADC_CHANNEL, SAMPLE_PERIOD);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
        } else {
            float intensity = calculate_rainfall_intensity(adc_value);

            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                snprintf(ts, sizeof(ts), "<unknown-time>");
            }

            printf("[%s] ADC=%4u  Intensity=%.3f\n", ts, adc_value, intensity);
            fflush(stdout);
        }

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

