/*
 * Raspberry Pi potentiometer-controlled motor PWM using MCP3008 ADC.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MCP3008 CH0  -> Potentiometer wiper (0 V -> 3.3 V)
 *   Motor PWM    -> GPIO18 (Pin 12, hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_pwm motor_pwm.c -lpigpio -lrt
 * Run:
 *   sudo ./motor_pwm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)  */
#define SPI_SPEED      1000000    /* 1 MHz             */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0       */
#define PWM_GPIO       18         /* BCM 18 (hardware PWM0) */
#define PWM_FREQ       1000       /* 1 kHz             */
#define PWM_RANGE      1023       /* Duty 0..1023      */
#define SAMPLE_US      100000     /* 100 ms loop delay */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended mode)                */
/* Returns 0..1023 on success, -1 on SPI error.                        */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00                       (clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    /* Ensure PWM is off before terminating pigpio */
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- PWM setup -------------------------------------------------- */
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialise PWM duty cycle on GPIO %d\n",
                PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SPI setup -------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioPWM(PWM_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Potentiometer-controlled motor PWM running.\n");
    printf("  ADC channel : %d\n", ADC_CHANNEL);
    printf("  PWM GPIO    : %d\n", PWM_GPIO);
    printf("  PWM freq    : %d Hz\n", PWM_FREQ);
    printf("  PWM range   : %d\n", PWM_RANGE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (gpioPWM(PWM_GPIO, adc_value) < 0) {
            fprintf(stderr, "PWM write failed for duty %d\n", adc_value);
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, adc_value);
        gpioDelay(SAMPLE_US);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

