/*
 * Raspberry Pi 4 Model B - Honeywell SS49E Hall Sensor Monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall sensor (magnetic field -> analog output)
 *   - ADS1115 16-bit ADC on I2C bus 1, address 0x48
 *   - ADS1115 AIN0 single-ended, PGA gain 4.096 V
 *   - LED on GPIO17 (BCM), 50 ms on / 50 ms off for 1 s on threshold breach
 *
 * Build:
 *   gcc -O2 -Wall -o hall_monitor hall_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADS1115_ADDR         0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS        = 1  (begin single conversion)
 *   Bits 14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA      = 001 (4.096 V)
 *   Bit  8     MODE     = 1  (single-shot)
 *   Bits 7:5   DR       = 100 (128 SPS)
 *   Bit  4     COMP_MODE= 0
 *   Bit  3     COMP_POL = 0
 *   Bit  2     COMP_LAT = 0
 *   Bits 1:0   COMP_QUE = 11 (disable comparator)
 *
 * Binary: 1 100 001 1 100 0 0 0 11 -> 0xC283
 */
#define ADS1115_CONFIG_BASE   0xC283

#define DEFAULT_THRESHOLD_GAUSS 100.0
#define DEFAULT_SAMPLE_US      100000   /* 100 ms */
#define LED_BLINK_MS           50
#define LED_BLINK_COUNT        20       /* 1 s total */
#define LED_GPIO               17

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ----------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * ADS1115 expects big-endian: MSB first, then LSB.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ADS1115] Failed to write reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * ADS1115 returns big-endian: MSB first, then LSB.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ADS1115] Failed to select reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ADS1115] Failed to read reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-ended conversion on AIN0 and read the raw ADC code.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_ain0(int handle, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_BASE;

    /* Write config to start a conversion */
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /*
     * Wait for conversion to complete.
     * At 128 SPS, a conversion takes ~7.8 ms. Poll the OS bit (bit 15).
     */
    for (int i = 0; i < 20; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) != 0)
            return -1;
        if (cfg & 0x8000)
            break;
        gpioDelay(5000); /* 5 ms */
    }

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *raw_out = (int16_t)raw;
    return 0;
}

/*
 * Convert raw ADC code to Gauss.
 * PGA = 4.096 V -> 1 bit = 125 uV.
 * SS49E sensitivity: ~100 mGauss/V.
 * So 1 bit = 125 uV / 0.1 mV/V = 1.25 mGauss.
 */
static double raw_to_gauss(int16_t raw)
{
    return (double)raw * 0.00125;
}

/* ------------------------------ LED blink -------------------------------- */

static void led_blink(int gpio)
{
    for (int i = 0; i < LED_BLINK_COUNT && g_running; i++) {
        gpioWrite(gpio, 1);
        gpioDelay(LED_BLINK_MS * 1000);
        gpioWrite(gpio, 0);
        gpioDelay(LED_BLINK_MS * 1000);
    }
}

/* ------------------------------- Main ------------------------------------ */

int main(int argc, char *argv[])
{
    double threshold = DEFAULT_THRESHOLD_GAUSS;
    int sample_us = DEFAULT_SAMPLE_US;
    int opt;

    while ((opt = getopt(argc, argv, "t:s:h")) != -1) {
        switch (opt) {
        case 't':
            threshold = atof(optarg);
            if (threshold <= 0.0) {
                fprintf(stderr, "Threshold must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        case 's':
            sample_us = atoi(optarg);
            if (sample_us <= 0) {
                fprintf(stderr, "Sample interval must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-t threshold_gauss] [-s sample_us]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    printf("Hall sensor monitor started.\n");
    printf("  Threshold: %.2f Gauss\n", threshold);
    printf("  Sample interval: %d us\n", sample_us);
    printf("  LED on GPIO%d, 50 ms on/50 ms off for 1 s on breach.\n",
           LED_GPIO);
    printf("  Press Ctrl+C to exit.\n\n");

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n",
                LED_GPIO, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
            gpioDelay(sample_us);
            continue;
        }

        double gauss = raw_to_gauss(raw);
        printf("Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold breached! Blinking LED for 1 s.\n");
            led_blink(LED_GPIO);
        }

        gpioDelay(sample_us);
    }

    /* ---- Cleanup ---- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
