code:
/*
 * Raspberry Pi 4 Model B — Soil Moisture Monitor & Pump Controller
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / GPIO8, 1 MHz, mode 0)
 *   - HL-69 analog soil moisture sensor -> MCP3008 CH0
 *   - Relay module on GPIO17 (active-high, BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c \
 *       -lmosquitto-dev -lpigpio -lrt
 *
 * Run:
 *   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL       0          /* MCP3008 on SPI0 CE0 (GPIO8)          */
#define SPI_SPEED         1000000    /* 1 MHz                                */
#define SPI_FLAGS         0          /* Mode 0, active-low CE                */

#define MCP3008_CHANNEL   0          /* Single-ended channel 0               */
#define ADC_MAX           1023       /* 10-bit ADC full-scale                */

#define PUMP_GPIO         17         /* Relay control pin (BCM)              */
#define HYSTERESIS_LOW    30         /* % below which pump activates         */
#define HYSTERESIS_HIGH   35         /* % above which pump deactivates        */

#define MQTT_HOST         "localhost"
#define MQTT_PORT         1883
#define MQTT_TOPIC_PUMP   "pump_control"
#define MQTT_TOPIC_DATA   "soil_moisture"
#define MQTT_KEEPALIVE    60
#define MQTT_QOS          0

#define SAMPLE_INTERVAL   60         /* seconds between readings             */
#define MAX_RETRIES       3          /* SPI retries per sample               */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static struct mosquitto *g_mosq = NULL;

/* --------------------------- Function prototypes -------------------------- */

static int  read_mcp3008(int channel, int *out_value);
static int  set_pump(int gpio, int state);
static void log_message(int priority, const char *message);
static void signal_handler(int sig);
static void cleanup(void);
static void on_connect(struct mosquitto *mosq, void *userdata, int result);
static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message);

/* ------------------------------- MCP3008 ---------------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on error.
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        log_message(LOG_ERR, "Invalid MCP3008 channel requested.");
        return -1;
    }
    if (out_value == NULL) {
        log_message(LOG_ERR, "read_mcp3008: NULL output pointer.");
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   Byte 2: 0x00                       (don't care, clocks out low byte)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        int ret = spiXfer(g_spi_handle, tx, rx, 3);
        if (ret == 3) {
            int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            if (value < 0 || value > ADC_MAX) {
                log_message(LOG_ERR, "MCP3008 value out of 10-bit range.");
                return -1;
            }
            *out_value = value;
            return 0;
        }
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "SPI transfer failed (attempt %d/%d): returned %d",
                 attempt, MAX_RETRIES, ret);
        log_message(LOG_ERR, msg);
        if (attempt < MAX_RETRIES) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    log_message(LOG_ERR, "MCP3008 read failed after all retries.");
    return -1;
}

/* ------------------------------- Pump GPIO -------------------------------- */

static int set_pump(int gpio, int state)
{
    if (gpioWrite(gpio, state) < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Failed to write GPIO %d (state=%d): %s",
                 gpio, state, pigpio_error(gpioRead(gpio)));
        log_message(LOG_ERR, msg);
        return -1;
    }
    return 0;
}

/* ------------------------------- Logging ---------------------------------- */

static void log_message(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

/* ------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    /* Ensure pump is off before tearing down */
    if (g_spi_handle >= 0) {
        set_pump(PUMP_GPIO, 0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_mosq != NULL) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    gpioTerminate();
    closelog();
}

/* ------------------------------- Signal ----------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MQTT callbacks ------------------------------- */

static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "Connected to MQTT broker.");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Failed to subscribe to %s: %s",
                     MQTT_TOPIC_PUMP, mosquitto_strerror(rc));
            log_message(LOG_ERR, msg);
        } else {
            log_message(LOG_INFO, "Subscribed to topic: " MQTT_TOPIC_PUMP);
        }
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "MQTT connect failed: %s", mosquitto_strerror(result));
        log_message(LOG_ERR, msg);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "Disconnected from MQTT broker.");
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
        log_message(LOG_WARNING, msg);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message == NULL || message->payload == NULL || message->payloadlen <= 0) {
        log_message(LOG_WARNING, "Empty MQTT message received.");
        return;
    }

    /* Ensure payload is NUL-terminated for safe string comparison */
    char payload[32] = { 0 };
    int copy_len = (message->payloadlen < (int)sizeof(payload) - 1)
                   ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, copy_len);

    if (strcmp(message->topic, MQTT_TOPIC_PUMP) != 0) {
        return; /* not our topic */
    }

    if (strcmp(payload, "pump_on") == 0) {
        log_message(LOG_INFO, "Received pump_on command — turning pump ON.");
        if (set_pump(PUMP_GPIO, 1) == 0) {
            log_message(LOG_INFO, "Pump activated.");
        }
    } else if (strcmp(payload, "pump_off") == 0) {
        log_message(LOG_INFO, "Received pump_off command — turning pump OFF.");
        if (set_pump(PUMP_GPIO, 0) == 0) {
            log_message(LOG_INFO, "Pump deactivated.");
        }
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Unknown command: %s", payload);
        log_message(LOG_WARNING, msg);
    }
}

/* ------------------------------- Main ------------------------------------- */

int main(void)
{
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed.");
        closelog();
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "spiOpen failed: %s", pigpio_error(g_spi_handle));
        log_message(LOG_ERR, msg);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set pump GPIO mode.");
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_pump(PUMP_GPIO, 0) < 0) {
        log_message(LOG_ERR, "Failed to initialise pump to OFF state.");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- MQTT init --- */
    mosquitto_lib_init();
    g_mosq = mosquitto_new(NULL, true, NULL);
    if (g_mosq == NULL) {
        log_message(LOG_ERR, "mosquitto_new failed (out of memory).");
        cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "mosquitto_connect to %s:%d failed: %s",
                 MQTT_HOST, MQTT_PORT, mosquitto_strerror(rc));
        log_message(LOG_ERR, msg);
        cleanup();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "mosquitto_loop_start failed: %s", mosquitto_strerror(rc));
        log_message(LOG_ERR, msg);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message(LOG_INFO, "Soil monitor started.");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) != 0) {
            log_message(LOG_ERR, "Sensor read failed — skipping cycle.");
        } else {
            int moisture = (int)(((float)adc_value / (float)ADC_MAX) * 100.0f);

            /* Hysteresis control */
            static bool pump_on = false;
