/*
 * MCP3008 channel 0 reader on Raspberry Pi (Pi 3/4, 40-pin header)
 * SPI bus /dev/spidev0.0, mode 0, MSB-first, 1 MHz, CS on GPIO8.
 *
 * Wiring (BCM numbering):
 *   GPIO11 (BCM 11) -> SPI0_SCLK (CLK)
 *   GPIO9  (BCM 9)  -> SPI0_MISO (DOUT)
 *   GPIO10 (BCM 10) -> SPI0_MOSI (DIN)
 *   GPIO8  (BCM 8)  -> SPI0_CE0  (CS)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mcp3008_ch0 mcp3008_ch0.c
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define ADC_CHANNEL     0          /* MCP3008 channel 0 */
#define VREF            3.3f       /* Reference voltage (VDD) */
#define SAMPLE_DELAY_US 500000U    /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer, mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (don't-care)
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    return raw;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = spi_init(SPI_DEVICE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("MCP3008 channel %d reader on %s\n", ADC_CHANNEL, SPI_DEVICE);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        int raw = mcp3008_read(fd, ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            float voltage = (float)raw * VREF / 1024.0f;
            printf("Raw: %4d  Voltage: %.3f V\n", raw, voltage);
        }
        usleep(SAMPLE_DELAY_US);
    }

    if (close(fd) < 0) {
        fprintf(stderr, "close(spi): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

