#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define MOTOR_PIN_1     17
#define MOTOR_PIN_2     27

#define NOISE_THRESHOLD 500
#define SAMPLE_DELAY_US 10000
#define PWM_FREQUENCY   100
#define PWM_RANGE       1000

#define LOG_FILE        "vibration_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_PIN_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_PIN_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_PIN_2);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR_PIN_1, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR_PIN_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR_PIN_2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR_PIN_2);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR_PIN_1, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR_PIN_1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(MOTOR_PIN_2, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR_PIN_2);
        gpioTerminate();
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        log_event("SPI initialization failed");
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    while (g_running) {
        int noise_level = read_mcp3008(g_spi_fd, 0);
        if (noise_level < 0) {
            log_event("ADC read error, skipping iteration");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (noise_level > NOISE_THRESHOLD) {
            int duty = (noise_level - NOISE_THRESHOLD) / 10;
            if (duty > PWM_RANGE) duty = PWM_RANGE;

            if (gpioPWM(MOTOR_PIN_1, duty) < 0) {
                fprintf(stderr, "Failed to set PWM on GPIO%d\n", MOTOR_PIN_1);
            }
            if (gpioPWM(MOTOR_PIN_2, duty) < 0) {
                fprintf(stderr, "Failed to set PWM on GPIO%d\n", MOTOR_PIN_2);
            }

            char msg[128];
            snprintf(msg, sizeof(msg), "Vibration event: noise=%d, duty=%d", noise_level, duty);
            log_event(msg);
        } else {
            if (gpioPWM(MOTOR_PIN_1, 0) < 0) {
                fprintf(stderr, "Failed to stop PWM on GPIO%d\n", MOTOR_PIN_1);
            }
            if (gpioPWM(MOTOR_PIN_2, 0) < 0) {
                fprintf(stderr, "Failed to stop PWM on GPIO%d\n", MOTOR_PIN_2);
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioPWM(MOTOR_PIN_1, 0);
    gpioPWM(MOTOR_PIN_2, 0);

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    gpioTerminate();
    log_event("Program terminated");

    return 0;
}

