#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define CSV_FILE "tamper_log.csv"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define SPI_SPEED_HZ 1000000
#define SAMPLE_INTERVAL_SEC 5
#define BH1750_CONV_MS 180

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }
    unsigned int mode = SPI_MODE_0;
    unsigned int bits = 8;
    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_init(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_bh1750(int i2c_fd) {
    unsigned char cmd = BH1750_CONT_HIGH_RES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing BH1750 command: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    unsigned char buf[2] = {0};
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading BH1750 data: %s\n", strerror(errno));
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void log_data(FILE *fp, float sound_level, float light_level, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }
    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) return 1;
    int i2c_fd = i2c_init(I2C_DEVICE, BH1750_ADDR);
    if (i2c_fd < 0) {
        close(spi_fd);
        return 1;
    }
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILE, strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    while (running) {
        int adc_value = read_mcp3008(spi_fd, 0);
        int light_level = read_bh1750(i2c_fd);
        float sound_level = -1.0f;
        float light_level_lux = -1.0f;
        int error_code = 0;
        if (adc_value < 0) {
            error_code = 1;
        } else {
            sound_level = (float)adc_value * 0.1f;
        }
        if (light_level < 0) {
            error_code = 2;
        } else {
            light_level_lux = (float)light_level / 1.2f;
        }
        log_data(fp, sound_level, light_level_lux, error_code);
        sleep(SAMPLE_INTERVAL_SEC);
    }
    fclose(fp);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

