/*
 * Raspberry Pi 4 Model B — Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / GPIO 8), SCLK / GPIO 11, MOSI / GPIO 10,
 *     MISO / GPIO 9, VDD 3.3 V, VREF 3.3 V, DGND/AGND common to Pi.
 *   - Vegetronix VH400 analog output wired to MCP3008 CH0.
 *   - Relay/water-pump driver on BCM GPIO 17 (active-high).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware-PWM/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 (GPIO 8)                          */
#define SPI_SPEED        1000000    /* 1 MHz                                 */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                 */

#define PUMP_GPIO        17         /* BCM 17 — relay driver (active-high)   */
#define MOISTURE_CHANNEL 0          /* MCP3008 single-ended channel 0        */

#define MOISTURE_THRESHOLD 30       /* % — pump activates below this value   */
#define SAMPLE_INTERVAL_S  60       /* seconds between readings              */
#define MAX_RETRIES        3        /* retries per SPI transfer              */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static int  read_mcp3008(int channel, int *out_value);
static void log_moisture(int moisture_percent);
static void control_pump(bool on);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* ensure pump is OFF at start */

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, pigpio_error(g_spi_handle));
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started.\n");
    printf("  SPI channel : %d (CE0)\n", SPI_CHANNEL);
    printf("  SPI speed   : %d Hz\n", SPI_SPEED);
    printf("  Pump GPIO   : %d\n", PUMP_GPIO);
    printf("  Threshold   : %d%%\n", MOISTURE_THRESHOLD);
    printf("  Sample intv : %d s\n", SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int moisture = -1;
        int retries = 0;
        bool read_ok = false;

        while (retries < MAX_RETRIES && !read_ok && g_running) {
            if (read_mcp3008(MOISTURE_CHANNEL, &moisture) == 0) {
                read_ok = true;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Warning: SPI read failed (attempt %d/%d).\n",
                            retries, MAX_RETRIES);
                    gpioDelay(1000000);  /* 1 s back-off before retry */
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: SPI read failed after %d attempts — skipping cycle.\n",
                    MAX_RETRIES);
        } else {
            /* Convert 10-bit ADC value (0–1023) to 0–100 % */
            int percent = (int)(((float)moisture / 1023.0f) * 100.0f);
            if (percent < 0)   percent = 0;
            if (percent > 100) percent = 100;

            log_moisture(percent);

            if (percent < MOISTURE_THRESHOLD) {
                control_pump(true);
            } else {
                control_pump(false);
            }
        }

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d (must be 0–7).\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d: %s\n",
                bytes, (bytes < 0) ? pigpio_error(bytes) : "short transfer");
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ------------------------------ Logging ---------------------------------- */
static void log_moisture(int moisture_percent)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };

    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "<unknown-time>");
    }

    printf("[%s] Moisture: %d%%  (ADC raw: %d)\n", ts, moisture_percent,
           (moisture_percent * 1023) / 100);
    fflush(stdout);
}

/* --------------------------- Pump control -------------------------------- */
static void control_pump(bool on)
{
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed.\n", PUMP_GPIO, on ? 1 : 0);
    }
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is OFF */
    if (g_spi_handle >= 0 || gpioInitialise() >= 0) {  /* pigpio still available */
        gpioWrite(PUMP_GPIO, 0);
    }

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;  /* let main loop exit cleanly */
}

