                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Warning: SPI read failed (attempt %d/%d).\n",
                            retries, MAX_RETRIES);
                    gpioDelay(1000000);  /* 1 s back-off before retry */
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: SPI read failed after %d attempts — skipping cycle.\n",
                    MAX_RETRIES);
        } else {
            /* Convert 10-bit ADC value (0–1023) to 0–100 % */
            int percent = (int)(((float)moisture / 1023.0f) * 100.0f);
            if (percent < 0)   percent = 0;
            if (percent > 100) percent = 100;

            log_moisture(percent);

            if (percent < MOISTURE_THRESHOLD) {
                control_pump(true);
            } else {
                control_pump(false);
            }
        }

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d (must be 0–7).\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d: %s\n",
                bytes, (bytes < 0) ? pigpio_error(bytes) : "short transfer");
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ------------------------------ Logging ---------------------------------- */
static void log_moisture(int moisture_percent)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };

    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "<unknown-time>");
    }

    printf("[%s] Moisture: %d%%  (ADC raw: %d)\n", ts, moisture_percent,
           (moisture_percent * 1023) / 100);
    fflush(stdout);
}

/* --------------------------- Pump control -------------------------------- */
static void control_pump(bool on)
{
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed.\n", PUMP_GPIO, on ? 1 : 0);
    }
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is OFF */
    if (g_spi_handle >= 0 || gpioInitialise() >= 0) {  /* pigpio still available */
        gpioWrite(PUMP_GPIO, 0);
    }

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;  /* let main loop exit cleanly */
}

