/*
 * Raspberry Pi Zero W – IR Distance Sensor (GP2Y0A21YK0F) + MCP3008 ADC + Relay
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 / GPIO8), channel 0
 *   - GP2Y0A21YK0F IR distance sensor connected to MCP3008 CH0
 *   - Relay on GPIO17 (BCM), active-high
 *
 * Behavior:
 *   Polls the sensor every 100 ms. When the distance drops below 20 cm,
 *   energizes the relay for 1 s, logs the event with a timestamp, and
 *   enters a 1 s debounce period.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_monitor door_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/SPI/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 (GPIO8)                          */
#define SPI_SPEED        1000000    /* 1 MHz – well within MCP3008 spec     */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0       */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code            */

#define RELAY_GPIO       17         /* BCM pin for relay (active-high)      */

#define DISTANCE_THRESHOLD_CM  20.0f
#define POLL_INTERVAL_US       100000   /* 100 ms                            */
#define DEBOUNCE_DELAY_US      1000000  /* 1 s                               */
#define RELAY_PULSE_US         1000000  /* 1 s relay energization             */

#define LOG_FILE         "door_events.log"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pigpio_ready = 0;

/* --------------------------- Function prototypes -------------------------- */

static int  read_adc(int channel);
static float calculate_distance(int adc_value);
static void control_relay(int on);
static void log_event(float distance_cm);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- ADC ------------------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 * Returns the 10-bit code (0–1023) on success, or -1 on error.
 *
 * MCP3008 SPI protocol (3-byte transfer, Mode 0):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   TX[2] = 0x00                       (clock out remaining bits)
 *   RX[1] bits 1:0 + RX[2] bits 7:0    -> 10-bit result
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/*
 * Convert the raw ADC code to a distance in centimetres.
 *
 * NOTE: The GP2Y0A21YK0F is a digital IR distance sensor; this function
 *       provides a linear approximation based on the known voltage-to-range
 *       curve (adjust for your specific module). Replace with a calibrated
 *       curve if you have a digital-out module or use a digital-to-analog
 *       converter (e.g., TSL2561) for analog-output sensors.
 */
static float calculate_distance(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    /*
     * Approximate inverse: distance (cm) ≈ 100 / (adc / 1023.0)
     * Clamps to [1.0, 100.0] so the result is always physically meaningful.
     */
    float distance = 100.0f / ((float)adc_value / (float)ADC_MAX);
    if (distance < 1.0f) distance = 1.0f;
    if (distance > 100.0f) distance = 100.0f;
    return distance;
}

/* ------------------------------- Relay ----------------------------------- */

static void control_relay(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", RELAY_GPIO, on);
    }
}

/* ------------------------------- Logging --------------------------------- */

static void log_event(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm);
    } else {
        fprintf(fp, "<timestamp-error> - Distance: %.2f cm\n", distance_cm);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
}

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_pigpio_ready) {
        control_relay(0);
        if (g_spi_handle >= 0) {
            spiClose(g_spi_handle);
            g_spi_handle = -1;
        }
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* --- Configure relay GPIO --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_relay(0);

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen(CE%d, %d, 0) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door monitor started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error – skipping cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float distance_cm = calculate_distance(adc_value);

        if (distance_cm < DISTANCE_THRESHOLD_CM) {
            printf("Distance: %.2f cm – door opening!\n", distance_cm);
            control_relay(1);
            log_event(distance_cm);

            /* Debounce: wait, but allow signal to interrupt */
            uint32_t elapsed = 0;
            while (g_running && elapsed < DEBOUNCE_DELAY_US) {
                gpioDelay(100000); /* 100 ms slices */
                elapsed += 100000;
            }

            control_relay(0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

