 *       curve if you have a digital-out module or use a digital-to-analog
 *       converter (e.g., TSL2561) for analog-output sensors.
 */
static float calculate_distance(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    /*
     * Approximate inverse: distance (cm) ≈ 100 / (adc / 1023.0)
     * Clamps to [1.0, 100.0] so the result is always physically meaningful.
     */
    float distance = 100.0f / ((float)adc_value / (float)ADC_MAX);
    if (distance < 1.0f) distance = 1.0f;
    if (distance > 100.0f) distance = 100.0f;
    return distance;
}

/* ------------------------------- Relay ----------------------------------- */

static void control_relay(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", RELAY_GPIO, on);
    }
}

/* ------------------------------- Logging --------------------------------- */

static void log_event(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm);
    } else {
        fprintf(fp, "<timestamp-error> - Distance: %.2f cm\n", distance_cm);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
}

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_pigpio_ready) {
        control_relay(0);
        if (g_spi_handle >= 0) {
            spiClose(g_spi_handle);
            g_spi_handle = -1;
        }
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* --- Configure relay GPIO --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_relay(0);

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen(CE%d, %d, 0) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door monitor started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error – skipping cycle\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float distance_cm = calculate_distance(adc_value);

        if (distance_cm < DISTANCE_THRESHOLD_CM) {
            printf("Distance: %.2f cm – door opening!\n", distance_cm);
            control_relay(1);
            log_event(distance_cm);

            /* Debounce: wait, but allow signal to interrupt */
            uint32_t elapsed = 0;
            while (g_running && elapsed < DEBOUNCE_DELAY_US) {
                gpioDelay(100000); /* 100 ms slices */
                elapsed += 100000;
            }

            control_relay(0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

