/*
 * Raspberry Pi Zero W – Vegetronix VH400 soil-moisture monitor
 *   MCP3008 ADC  (SPI0 CE0, 1 MHz, mode 0)
 *   ASCO RedHat 8210 proportional valve (GPIO17, PWM 100 Hz, 0-100 %)
 *
 * Build:  gcc -O2 -Wall -o irrigation irrigation.c -lpigpio -lrt
 * Run:    sudo ./irrigation
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                         */
#define SPI_SPEED      1000000    /* 1 MHz                                    */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words        */

#define VALVE_GPIO     17         /* BCM 17 – ASCO RedHat 8210 PWM input      */
#define PWM_FREQ       100        /* Hz                                       */
#define PWM_RANGE      100        /* duty-cycle steps 0..100                  */

#define SAMPLE_COUNT   3
#define SAMPLE_DELAY   200000     /* 200 ms between samples                   */
#define LOG_INTERVAL   5          /* seconds between log entries              */
#define LOG_FILE       "irrigation.log"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  read_mcp3008(int channel);
static int  set_valve_position(int position);
static int  log_data(int r0, int r1, int r2, int avg, int pos);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- MCP3008 ---------------------------------- */
/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns the 10-bit ADC value (0-1023) or -1 on error.
 *
 * MCP3008 SPI protocol (3-byte transfer, mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* ------------------------------- Valve PWM -------------------------------- */
static int set_valve_position(int position)
{
    if (position < 0)   position = 0;
    if (position > 100) position = 100;

    if (gpioPWM(VALVE_GPIO, position) != 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

/* ------------------------------- Logging ---------------------------------- */
static int log_data(int r0, int r1, int r2, int avg, int pos)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    if (!tm) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n", ts, r0, r1, r2, avg, pos) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure valve is closed before terminating pigpio */
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Signals ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Valve GPIO setup --- */
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed on GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed on GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_valve_position(0) != 0) {
        fprintf(stderr, "Failed to initialise valve to closed position\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation system started. Logging to %s every %d s.\n",
           LOG_FILE, LOG_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int readings[SAMPLE_COUNT];
        int valid = 0;

        for (int i = 0; i < SAMPLE_COUNT && g_running; i++) {
            int r = read_mcp3008(0);
            if (r < 0) {
                fprintf(stderr, "Sample %d read failed; skipping.\n", i);
                gpioDelay(SAMPLE_DELAY);
                continue;
            }
            readings[valid++] = r;
            gpioDelay(SAMPLE_DELAY);
        }

        if (valid == 0) {
            fprintf(stderr, "No valid samples this cycle; skipping.\n");
            continue;
        }

        long sum = 0;
        for (int i = 0; i < valid; i++)
            sum += readings[i];
        int avg = (valid > 0) ? (int)(sum / valid) : 0;

        int pos = (avg * 100) / 1023;   /* 0-1023 -> 0-100 */
        if (pos < 0)   pos = 0;
        if (pos > 100) pos = 100;

        if (set_valve_position(pos) != 0) {
            fprintf(stderr, "Failed to set valve position %d\n", pos);
        }

        if (log_data(readings[0],
                     (valid > 1) ? readings[1] : -1,
                     (valid > 2) ? readings[2] : -1,
                     avg, pos) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep for the remainder of the 5-second interval */
        for (int s = 0; s < LOG_INTERVAL && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

