/*
 * Raspberry Pi Zero W - YL-69 Soil Moisture Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   YL-69 A0     -> MCP3008 CH0
 *   YL-69 VCC    -> 3.3V
 *   YL-69 GND    -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define LOG_FILE       "soil_data.txt"
#define SAMPLE_INTERVAL 5         /* seconds */
#define MAX_RETRIES    5
#define RETRY_BASE_US  100000     /* 100 ms */
#define ADC_MAX        1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (Mode 0, MSB-first):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   Byte 2: 0x00                       (clocks out low 2 bits)
 *
 * Response (3 bytes):
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in upper nibble
 *   rx[2] = b7..b0
 *   10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Conversion                                                          */
/* ------------------------------------------------------------------ */
static float adc_to_moisture_percentage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float moisture_percentage)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Moisture: %.2f%%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_percentage);
    } else {
        fprintf(fp, "<timestamp-error>, Moisture: %.2f%%\n", moisture_percentage);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = -1;
        int retries = 0;
        int delay_us = RETRY_BASE_US;

        /* Retry loop for SPI read */
        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retry %d/%d\n",
                        retries, MAX_RETRIES);
                gpioDelay(delay_us);
                delay_us *= 2;   /* exponential backoff */
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed after %d retries; skipping sample\n",
                    MAX_RETRIES);
            log_data(-1.0f);   /* error entry */
        } else if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            log_data(-1.0f);
        } else {
            float moisture = adc_to_moisture_percentage(adc_value);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture);
            log_data(moisture);
        }

        /* Sleep SAMPLE_INTERVAL seconds, checking g_running every second */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* --- cleanup ---------------------------------------------------- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nSoil moisture monitoring stopped.\n");
    return EXIT_SUCCESS;
}

