/*
 * Theremin-like instrument using HC-SR04 ultrasonic sensor and a
 * photoresistor (LDR) on a Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 Trig -> GPIO23 (BCM)
 *   HC-SR04 Echo -> GPIO24 (BCM) [3.3 V-compatible via voltage divider]
 *   MCP3008    CLK  -> GPIO11 (BCM)
 *   MCP3008    DOUT -> GPIO9  (BCM)
 *   MCP3008    DIN  -> GPIO10 (BCM)
 *   MCP3008    CS   -> GPIO8  (BCM)
 *   MCP3008    Vdd  -> 3.3 V, VREF -> 3.3 V, AGND/DGND -> GND
 *   LDR        +    -> MCP3008 CH0, - -> GND
 *   PWM        GPIO18 (BCM) -> external audio amplifier
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lm
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/pwm.h>

/* ----------------------------- Configuration ----------------------------- */
#define CONFIG_FILE          "theremin_config.txt"
#define SPI_DEVICE           "/dev/spidev0.0"
#define PWM_EXPORT_PATH      "/sys/class/pwm/pwmchip0/export"
#define PWM_UNEXPORT_PATH    "/sys/class/pwm/pwmchip0/unexport"
#define PWM_PERIOD_PATH      "/sys/class/pwm/pwmchip0/pwm0/period"
#define PWM_DUTY_CYCLE_PATH  "/sys/class/pwm/pwmchip0/pwm0/duty_cycle"
#define PWM_ENABLE_PATH      "/sys/class/pwm/pwmchip0/pwm0/enable"

#define TRIG_PIN             23
#define ECHO_PIN             24
#define SPI_SPEED_HZ         1000000
#define SPI_BITS_PER_WORD    8
#define SPI_MODE             SPI_MODE_0

#define LDR_ADC_CHANNEL      0
#define LDR_ADC_MAX          1023          /* MCP3008 10-bit */

#define MIN_FREQUENCY        200.0f
#define MAX_FREQUENCY        20000.0f
#define MIN_VOLUME           0.0f
#define MAX_VOLUME           1.0f

#define MAX_DISTANCE_CM      400.0f
#define MIN_DISTANCE_CM      2.0f

#define ECHO_TIMEOUT_US      30000         /* 30 ms */
#define LOOP_DELAY_US        10000         /* 10 ms */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pwm_exported = 0;

/* Calibration parameters (persisted to file) */
typedef struct {
    float distance_min;
    float distance_max;
    float volume_min;
    float volume_max;
} CalibrationData;

static CalibrationData g_cal = {
    .distance_min = 20.0f,
    .distance_max = 300.0f,
    .volume_min   = 0.2f,
    .volume_max   = 0.8f
};

/* ----------------------------- Helpers ---------------------------------- */
static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        fprintf(stderr, "write(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_file(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len - 1);
    if (n < 0) {
        fprintf(stderr, "read(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);
    return 0;
}

static int pwm_export(void) {
    if (g_pwm_exported) return 0;
    if (write_file(PWM_EXPORT_PATH, "0") != 0) return -1;
    sleep_us(100000);
    g_pwm_exported = 1;
    return 0;
}

static int pwm_unexport(void) {
    if (!g_pwm_exported) return 0;
    if (write_file(PWM_UNEXPORT_PATH, "0") != 0) return -1;
    g_pwm_exported = 0;
    return 0;
}

static int pwm_set_duty_cycle(unsigned int duty_ns) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%u", duty_ns);
    return write_file(PWM_DUTY_CYCLE_PATH, buf);
}

static int pwm_set_enable(int enable) {
    return write_file(PWM_ENABLE_PATH, enable ? "1" : "0");
}

static int pwm_set_frequency(float freq_hz) {
    if (freq_hz <= 0.0f) return -1;
    unsigned int period_ns = (unsigned int)(1000000000UL / freq_hz);
    char buf[32];
    snprintf(buf, sizeof(buf), "%u", period_ns);
    if (write_file(PWM_PERIOD_PATH, buf) != 0) return -1;
    return 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    return 0;
}

static void spi_close(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int mcp3008_read(uint8_t channel) {
    if (channel > 7) return -1;
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };
    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/*
 * Measure distance with HC-SR04.
 * Returns distance in cm, or -1.0f on timeout/error.
 */
static float get_distance(void) {
    /* 10 us trigger pulse */
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd >= 0) {
        dprintf(fd, "%d", TRIG_PIN);
        close(fd);
        sleep_us(10000);
    }
    fd = open("/sys/class/gpio/gpio23/value", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open GPIO23: %s\n", strerror(errno));
        return -1.0f;
    }
    dprintf(fd, "1");
    close(fd);
    sleep_us(10);
    fd = open("/sys/class/gpio/gpio23/value", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open GPIO23: %s\n", strerror(errno));
        return -1.0f;
    }
    dprintf(fd, "0");
    close(fd);

    /* Wait for echo rising edge */
    unsigned int elapsed = 0;
    while (elapsed < ECHO_TIMEOUT_US) {
        fd = open("/sys/class/gpio/gpio24/value", O_RDONLY);
        if (fd < 0) {
            fprintf(stderr, "open GPIO24: %s\n", strerror(errno));
            return -1.0f;
        }
        char v;
        if (read(fd, &v, 1) != 1) {
            fprintf(stderr, "read GPIO24: %s\n", strerror(errno));
            close(fd);
            return -1.0f;
        }
        close(fd);
        if (v == '1') break;
        sleep_us(10);
        elapsed += 10;
    }
    if (elapsed >= ECHO_TIMEOUT_US) return -1.0f;

    /* Measure echo high duration */
    unsigned int start = elapsed;
    elapsed = 0;
    while (elapsed < ECHO_TIMEOUT_US) {
        fd = open("/sys/class/gpio/gpio24/value", O_RDONLY);
        if (fd < 0) {
            fprintf(stderr, "open GPIO24: %s\n", strerror(errno));
            return -1.0f;
        }
        char v;
        if (read(fd, &v, 1) != 1) {
            fprintf(stderr, "read GPIO24: %s\n", strerror(errno));
            close(fd);
            return -1.0f;
        }
        close(fd);
        if (v == '0') break;
        sleep_us(10);
        elapsed += 10;
    }
    if (elapsed >= ECHO_TIMEOUT_US) return -1.0f;

    unsigned int pulse_us = elapsed - start;
    /* speed of sound ~343 m/s => 0.0343 cm/us */
    return (float)pulse_us * 0.0343f;
}

static float map_distance_to_frequency(float distance) {
    if (distance < 0.0f) distance = MAX_DISTANCE_CM;
    if (distance < g_cal.distance_min) distance = g_cal.distance_min;
    if (distance > g_cal.distance_max) distance = g_cal.distance_max;
    float norm = (distance - g_cal.distance_min) /
                 (g_cal.distance_max - g_cal.distance_min);
    return MIN_FREQUENCY + norm * (MAX_FREQUENCY - MIN_FREQUENCY);
}

static float map_ldr_to_volume(int adc) {
    if (adc < 0) adc = 0;
    if (adc > LDR_ADC_MAX) adc = LDR_ADC_MAX;
    float norm = (float)adc / (float)LDR_ADC_MAX;
    return MIN_VOLUME + norm * (MAX_VOLUME - MIN_VOLUME);
}

static void set_pwm_volume(float volume) {
    if (volume < MIN_VOLUME) volume = MIN_VOLUME;
    if (volume > MAX_VOLUME) volume = MAX_VOLUME;
    unsigned int period_ns = 1000000000UL;
    unsigned int duty_ns   = (unsigned int)(period_ns * volume);
    pwm_set_duty_cycle(duty_ns);
}

static void set_pwm_frequency(float freq) {
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    pwm_set_frequency(freq);
}

static void save_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", CONFIG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "distance_min=%.2f\n", g_cal.distance_min);
    fprintf(fp, "distance_max=%.2f\n", g_cal.distance_max);
    fprintf(fp, "volume_min=%.2f\n", g_cal.volume_min);
    fprintf(fp, "volume_max=%.2f\n", g_cal.volume_max);
    fclose(fp);
}

static void load_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Config file not found; using defaults.\n");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = line;
        char *val = eq + 1;
        while (*key == ' ') key++;
        char *ke = key + strlen(key) - 1;
        while (ke > key && *ke == ' ') { *ke = '\0'; ke--; }
        while (*val == ' ') val++;
        ke = val + strlen(val) - 1;
        while (ke > val && *ke == ' ') { *ke = '\0'; ke--; }
        if (strcmp(key, "distance_min") == 0)
            g_cal.distance_min = atof(val);
        else if (strcmp(key, "distance_max") == 0)
            g_cal.distance_max = atof(val);
        else if (strcmp(key, "volume_min") == 0)
            g_cal.volume_min = atof(val);
        else if (strcmp(key, "volume_max") == 0)
            g_cal.volume_max = atof(val);
    }
    fclose(fp);
    printf("Config loaded: dist=[%.2f, %.2f]  vol=[%.2f, %.2f]\n",
           g_cal.distance_min, g_cal.distance_max,
           g_cal.volume_min, g_cal.volume_max);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main ------------------------------------- */
int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    load_config();

    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    if (pwm_export() != 0) {
        fprintf(stderr, "PWM export failed.\n");
        spi_close();
        return 1;
    }

    if (pwm_set_enable(1) != 0) {
        fprintf(stderr, "PWM enable failed.\n");
        pwm_unexport();
        spi_close();
        return 1;
    }

    float last_distance = MAX_DISTANCE_CM;
    float last_volume   = MAX_VOLUME;

    printf("Theremin running. Ctrl+C to exit.\n");

    while (g_running) {
        float distance = get_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Distance read error; retaining last value.\n");
        } else {
            last_distance = distance;
        }

        int ldr_adc = mcp3008_read(LDR_ADC_CHANNEL);
        if (ldr_adc < 0) {
            fprintf(stderr, "LDR read error; retaining last value.\n");
        } else {
            last_volume = map_ldr_to_volume(ldr_adc);
        }

        float freq = map_distance_to_frequency(last_distance);
        set_pwm_frequency(freq);
        set_pwm_volume(last_volume);

        sleep_us(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    pwm_set_enable(0);
    pwm_unexport();
    spi_close();
    save_config();
    printf("\nTheremin stopped.\n");
    return 0;
}

