/*
 * MQ-3 Alcohol Sensor Reader via MCP3008 ADC on Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MQ-3 analog output
 *
 * Build: gcc -O2 -Wall -o alcohol_reader alcohol_reader.c -lpigpio -lrt
 * Run:   sudo ./alcohol_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit words */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD_US 1000000    /* 1 second */
#define MAX_RETRIES      3
#define RETRY_DELAY_US   100000     /* 100 ms */
#define LOG_FILE         "alcohol_log.txt"

/* Alcohol detection thresholds (ppm) */
#define ALCOHOL_LIMIT_HIGH  50.0f
#define ALCOHOL_LIMIT_LOW   20.0f

/* MCP3008 full-scale 10-bit ADC range */
#define ADC_MAX_VALUE       1023

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (don't care, clocks out low 2 bits)
 *
 * Response:
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in lower 2 bits
 *   rx[2] = b7..b0
 *   10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Alcohol classification                                              */
/* ------------------------------------------------------------------ */
static const char *classify_alcohol(int adc_value)
{
    if (adc_value > (int)(ADC_MAX_VALUE * (ALCOHOL_LIMIT_HIGH / 100.0f)))
        return "Alcohol detected! Limit exceeded.";
    if (adc_value < (int)(ADC_MAX_VALUE * (ALCOHOL_LIMIT_LOW  / 100.0f)))
        return "Sobriety confirmed.";
    return "Alcohol level within acceptable range.";
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, const char *status)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    fprintf(fp, "%s, ADC: %d, Status: %s\n", timestamp, adc_value, status);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int spi_handle, FILE *fp)
{
    if (spi_handle >= 0)
        spiClose(spi_handle);
    if (fp)
        fclose(fp);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_handle = -1;
    int ret_code   = EXIT_FAILURE;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, speed %d, flags %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, spi_handle);
        goto cleanup_gpio;
    }

    /* --- Log file --------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup_spi;
    }

    /* --- Signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup_log;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup_log;
    }

    printf("MQ-3 Alcohol Sensor Reader started. Press Ctrl+C to exit.\n");
    printf("Logging to %s\n", LOG_FILE);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = -1;
        int read_ok   = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
            if (adc_value >= 0) {
                read_ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read ADC after %d attempts\n", MAX_RETRIES);
            log_data(g_log_fp, -1, "ADC read failed");
            goto next_sample;
        }

        /* Sensor-absent heuristic: ADC stuck at rail */
        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC at rail (%d) — sensor may be absent or disconnected\n",
                    adc_value);
        }

        const char *status = classify_alcohol(adc_value);
        log_data(g_log_fp, adc_value, status);
        printf("ADC: %4d  Status: %s\n", adc_value, status);

    next_sample:
        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; ++i)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    ret_code = EXIT_SUCCESS;

cleanup_log:
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
cleanup_spi:
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
cleanup_gpio:
    gpioTerminate();
    return ret_code;
}

