/*
 * Irrigation controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - DFROBOT Soil Moisture Sensor (analog out) -> MCP3008 CH0
 *   - MCP3008 on SPI0: CE0=GPIO8, SCLK=GPIO11, MOSI=GPIO10, MISO=GPIO9
 *   - Relay (active high) on BCM GPIO18
 *
 * Build:
 *   gcc -O2 -Wall -o irrigation irrigation.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                       */
#define SPI_SPEED        1000000    /* 1 MHz                                  */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                  */
#define MCP3008_CHANNEL  0          /* Single-ended channel 0                 */
#define PUMP_GPIO        18         /* BCM GPIO18 (active high relay)         */
#define MOISTURE_THRESHOLD 300      /* 10-bit ADC value below this = dry      */
#define SAMPLE_INTERVAL  60         /* Seconds between readings              */
#define LOG_FILE         "irrigation.log"

/* ----------------------------- Globals ----------------------------------- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static void log_data(int moisture, int pump_status);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   TX[2] = 0x00                       (clock out remaining bits)
 *   RX[1] bits 1..0 + RX[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(int moisture, int pump_status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Pump: %s\n",
            timestamp, moisture, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

/* ----------------------------- Signal / cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure pump is off before terminating pigpio */
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* pump off at startup */

    /* --- Log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation controller started. Sampling every %d s.\n",
           SAMPLE_INTERVAL);

    /* --- Main loop --- */
    while (!terminate) {
        int moisture = read_mcp3008(MCP3008_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "Sensor read error — logging and continuing\n");
            log_data(-1, 0);
        } else {
            int pump_status = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
            gpioWrite(PUMP_GPIO, pump_status);
            log_data(moisture, pump_status);
            printf("Moisture: %d  Pump: %s\n",
                   moisture, pump_status ? "ON" : "OFF");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

