#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Hardware connections (Raspberry Pi 4 Model B):
 *   MCP3008 ADC:
 *     VDD  -> 3.3 V (Pin 1)
 *     VREF -> 3.3 V (Pin 1)
 *     AGND -> GND  (Pin 6)
 *     CLK  -> GPIO11 (SCLK)
 *     DOUT -> GPIO9  (MISO)
 *     DIN  -> GPIO10 (MOSI)
 *     CS   -> GPIO8  (CE0)
 *     CH0  -> Potentiometer 1 (wiper to 3.3 V, ground)
 *     CH1  -> Potentiometer 2 (wiper to 3.3 V, ground)
 *
 *   Adafruit Mini DC Motor with wires (Product ID 155):
 *     Motor 1:
 *       IN1 -> GPIO23 (direction)
 *       IN2 -> GPIO18 (enable, PWM)
 *     Motor 2:
 *       IN1 -> GPIO25 (direction)
 *       IN2 -> GPIO24 (enable, PWM)
 */

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

#define MOTOR1_DIR_PIN 23
#define MOTOR1_PWM_PIN  18
#define MOTOR2_DIR_PIN 25
#define MOTOR2_PWM_PIN  24

#define PWM_FREQUENCY 1000   /* 1 kHz */
#define PWM_RANGE     255

#define ACCELERATION_STEPS 10
#define ACCELERATION_DELAY_US 10000   /* 10 ms per step */
#define HOLD_TIME_US 2000000          /* 2 s */
#define PAUSE_TIME_US 5000000         /* 5 s */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI error, -2 on invalid channel.
 */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -2;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static void set_motor_direction(int motor, int direction) {
    int dir_pin = (motor == 1) ? MOTOR1_DIR_PIN : MOTOR2_DIR_PIN;
    if (gpioWrite(dir_pin, direction) < 0) {
        fprintf(stderr, "Warning: Failed to write direction pin %d\n", dir_pin);
    }
}

static void set_motor_speed(int motor, int speed) {
    int pwm_pin = (motor == 1) ? MOTOR1_PWM_PIN : MOTOR2_PWM_PIN;
    if (gpioPWM(pwm_pin, speed) < 0) {
        fprintf(stderr, "Warning: Failed to set PWM on pin %d\n", pwm_pin);
    }
}

static void stop_motor(int motor) {
    set_motor_speed(motor, 0);
}

static void cleanup(void) {
    stop_motor(1);
    stop_motor(2);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor direction pins as outputs */
    if (gpioSetMode(MOTOR1_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set motor direction pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor PWM pins as outputs */
    if (gpioSetMode(MOTOR1_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set motor PWM pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range for both motor PWM pins */
    if (gpioSetPWMfrequency(MOTOR1_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR1_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values.\n");
            /* Brief pause before retrying to avoid spamming on persistent bus errors */
            gpioDelay(100000);
            continue;
        }

        /* Map ADC values (0-1023) to speed values (0-255) */
        int speed1 = (pot1_value * 255) / 1023;
        int speed2 = (pot2_value * 255) / 1023;

        /* Accelerate motor 1 */
        for (int i = 0; i <= ACCELERATION_STEPS && g_running; i++) {
            set_motor_speed(1, (i * speed1) / ACCELERATION_STEPS);
            gpioDelay(ACCELERATION_DELAY_US);
        }

        /* Hold constant speed for 2 seconds */
        for (int i = 0; i < 20 && g_running; i++) {
            set_motor_speed(2, speed2);
            gpioDelay(100000);
        }

        /* Decelerate motor 1 */
        for (int i = ACCELERATION_STEPS; i >= 0 && g_running; i--) {
            set_motor_speed(1, (i * speed1) / ACCELERATION_STEPS);
            gpioDelay(ACCELERATION_DELAY_US);
        }

        /* Pause for 5 seconds */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000);
        }

        /* Reverse direction: Motor 1 forward, Motor 2 backward */
        set_motor_direction(1, 1);
        set_motor_direction(2, 0);

        /* Accelerate motor 1 and 2 in opposite directions */
        for (int i = 0; i <= ACCELERATION_STEPS && g_running; i++) {
            set_motor_speed(1, (i * speed1) / ACCELERATION_STEPS);
            set_motor_speed(2, (i * speed2) / ACCELERATION_STEPS);
            gpioDelay(ACCELERATION_DELAY_US);
        }

        /* Hold constant speed for 2 seconds */
        for (int i = 0; i < 20 && g_running; i++) {
            set_motor_speed(1, speed1);
            set_motor_speed(2, speed2);
            gpioDelay(100000);
        }

        /* Decelerate motor 1 and 2 */
        for (int i = ACCELERATION_STEPS; i >= 0 && g_running; i--) {
            set_motor_speed(1, (i * speed1) / ACCELERATION_STEPS);
            set_motor_speed(2, (i * speed2) / ACCELERATION_STEPS);
            gpioDelay(ACCELERATION_DELAY_US);
        }

        /* Pause for 5 seconds */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

