#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define SAMPLE_INTERVAL_US 10000
#define DEBOUNCE_DELAY_US 10000
#define NOISE_CALIBRATION_TIME 5
#define SOUND_THRESHOLD 500

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4 (single-ended + channel select)
     * Byte 2: 0x00 (don't care, clocked out to read data)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx[1] + 8 bits of rx[2] */
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calibrate_noise_level(void) {
    int sum = 0;
    int valid = 0;

    printf("Calibrating ambient noise level for %d seconds...\n", NOISE_CALIBRATION_TIME);
    for (int i = 0; i < NOISE_CALIBRATION_TIME * 100 && running; i++) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading MCP3008 during calibration\n");
            return -1;
        }
        sum += sample;
        valid++;
        gpioDelay(10000); /* 10 ms */
    }

    if (!running) {
        return -1;
    }

    if (valid == 0) {
        fprintf(stderr, "No valid samples collected during calibration\n");
        return -1;
    }

    return sum / valid;
}

int main(void) {
