    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    struct timespec next;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &next) < 0) {
        fprintf(stderr, "Failed to get initial time: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(spi_fd, cs_line, 0, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed, continuing\n");
            next.tv_nsec += SAMPLE_PERIOD_NS;
            if (next.tv_nsec >= 1000000000L) {
                next.tv_nsec -= 1000000000L;
                next.tv_sec++;
            }
            clock_nanosleep(CLOCK_MONOTONIC_RAW, TIMER_ABSTIME, &next, NULL);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            next.tv_nsec += SAMPLE_PERIOD_NS;
            if (next.tv_nsec >= 1000000000L) {
                next.tv_nsec -= 1000000000L;
                next.tv_sec++;
            }
            clock_nanosleep(CLOCK_MONOTONIC_RAW, TIMER_ABSTIME, &next, NULL);
            continue;
        }

        if (fprintf(log_file, "%ld.%09ld|%d\n", (long)ts.tv_sec, (long)ts.tv_nsec, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log: %s\n", strerror(errno));
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log: %s\n", strerror(errno));
        }

        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_nsec -= 1000000000L;
            next.tv_sec++;
        }
        clock_nanosleep(CLOCK_MONOTONIC_RAW, TIMER_ABSTIME, &next, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

