/*
 * ADXL335 analog accelerometer reader via MCP3008 10-bit ADC on Raspberry Pi 4.
 *
 * Wiring (BCM numbering):
 *   MCP3008 CS  -> GPIO8  (physical pin 24, chip select)
 *   MCP3008 DIN -> GPIO10 (physical pin 19, master out)
 *   MCP3008 DOUT-> GPIO9  (physical pin 21, master in)
 *   MCP3008 CLK -> GPIO11 (physical pin 23, SPI clock)
 *   MCP3008 VDD -> 3.3 V, VREF -> 3.3 V, DGND/AGND -> GND
 *   ADXL335 X_OUT -> MCP3008 CH0
 *   ADXL335 Y_OUT -> MCP3008 CH1
 *   ADXL335 Z_OUT -> MCP3008 CH2
 *   ADXL335 VDD  -> 3.3 V, GND -> GND
 *
 * Build: gcc -O2 -Wall -o adxl335_mcp3008 adxl335_mcp3008.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* pigpio SPI channel 0 maps to CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz SPI clock                          */
#define SPI_FLAGS      0          /* SPI mode 0, active-low CS                */

#define ADC_CHANNELS   3          /* X, Y, Z                                  */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC                               */
#define ADC_VREF       3.3        /* MCP3008 reference voltage (V)            */

#define SAMPLE_PERIOD_US 100000   /* 100 ms -> 10 Hz                          */

/*
 * Kalman filter parameters.
 *
 * The ADXL335 is an analog accelerometer; the output voltage is a
 * function of acceleration and the load resistor.  We model the
 * process noise as a Gaussian white noise process with a standard
 * deviation that is proportional to the acceleration magnitude.
 *
 * The process noise covariance Q is adjusted empirically so that the
 * Kalman filter output converges to the true acceleration over time.
 */
#define KF_Q_STD_DEV   0.01       /* Process noise standard deviation (g)     */
#define KF_R_STD_DEV   0.1        /* Measurement noise standard deviation (g) */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ MCP3008 ---------------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 *
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *
 * Result (10-bit value):
 *   ((rx[1] & 0x03) << 8) | rx[2]
 *
 * Returns 0..1023 on success, -1 on SPI error, -2 on invalid channel.
 */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -2;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------ Kalman ----------------------------------- */

typedef struct {
    double x;          /* state (acceleration in g)                       */
    double p;          /* covariance                                      */
} kalman_state_t;

static void kalman_update(kalman_state_t *st, double measurement)
{
    double q = KF_Q_STD_DEV * KF_Q_STD_DEV;
    double r = KF_R_STD_DEV * KF_R_STD_DEV;

    st->p += q;                       /* predict process noise              */
    double k = st->p / (st->p + r);   /* Kalman gain                        */
    st->x += k * (measurement - st->x); /* update                            */
    st->p = (1.0 - k) * st->p;        /* update covariance                  */
}

/* ------------------------------ Conversion ------------------------------- */

/*
 * Convert raw ADC value to acceleration in g.
 *
 * ADXL335 X/Y/Z outputs are voltage-divided through a 6.35 kΩ resistor
 * (datasheet: 6.35 kΩ for ±2 g range).  The load resistor is 6.35 kΩ, so
 * the voltage is V = (Vref * raw) / 1024.  Acceleration in g is:
 *   a = (V - Vref/2) / (Vref/2) * 3.0  (for ±2 g range)
 *   a = (V - Vref/2) / (Vref/2) * 1.5  (for ±1 g range)
 *   a = (V - Vref/2) / (Vref/2) * 0.75 (for ±0.5 g range)
 *
 * We use ±2 g range -> scale = 3.0 g/V.
 */
static double adc_to_g(int adc_value)
{
    double voltage = ((double)adc_value / (double)ADC_MAX_VALUE) * ADC_VREF;
    return (voltage - (ADC_VREF / 2.0)) / (ADC_VREF / 2.0) * 3.0;
}

/* ------------------------------ Initialization ---------------------------- */

static bool initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return false;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d, flags=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        gpioTerminate();
        return false;
    }

    /*
     * Verify the MCP3008 is present by reading all three channels.
     * A disconnected device typically returns 0 or a small value.
     */
    for (int ch = 0; ch < ADC_CHANNELS; ch++) {
        int v = mcp3008_read(g_spi_handle, ch);
        if (v < 0) {
            fprintf(stderr, "MCP3008 not responding on channel %d\n", ch);
            spiClose(g_spi_handle);
            g_spi_handle = -1;
            gpioTerminate();
            return false;
        }
    }

    return true;
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!initialize()) {
        return EXIT_FAILURE;
    }

    kalman_state_t kf[ADC_CHANNELS];
    for (int i = 0; i < ADC_CHANNELS; i++) {
        kf[i].x = 0.0;
        kf[i].p = 1.0;
    }

    printf("ADXL335 via MCP3008 - Kalman filtered acceleration (10 Hz)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        double filtered[ADC_CHANNELS];
        bool read_ok = true;

        for (int ch = 0; ch < ADC_CHANNELS; ch++) {
            int adc = mcp3008_read(g_spi_handle, ch);
            if (adc < 0) {
                read_ok = false;
                break;
            }
            double g = adc_to_g(adc);
            kalman_update(&kf[ch], g);
            filtered[ch] = kf[ch].x;
        }

        if (!read_ok) {
            fprintf(stderr, "ADC read error - continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("X: %+.3f g  Y: %+.3f g  Z: %+.3f g\n",
               filtered[0], filtered[1], filtered[2]);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

