    double voltage = ((double)adc_value / (double)ADC_MAX_VALUE) * ADC_VREF;
    return (voltage - (ADC_VREF / 2.0)) / (ADC_VREF / 2.0) * 3.0;
}

/* ------------------------------ Initialization ---------------------------- */

static bool initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return false;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d, flags=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        gpioTerminate();
        return false;
    }

    /*
     * Verify the MCP3008 is present by reading all three channels.
     * A disconnected device typically returns 0 or a small value.
     */
    for (int ch = 0; ch < ADC_CHANNELS; ch++) {
        int v = mcp3008_read(g_spi_handle, ch);
        if (v < 0) {
            fprintf(stderr, "MCP3008 not responding on channel %d\n", ch);
            spiClose(g_spi_handle);
            g_spi_handle = -1;
            gpioTerminate();
            return false;
        }
    }

    return true;
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (!initialize()) {
        return EXIT_FAILURE;
    }

    kalman_state_t kf[ADC_CHANNELS];
    for (int i = 0; i < ADC_CHANNELS; i++) {
        kf[i].x = 0.0;
        kf[i].p = 1.0;
    }

    printf("ADXL335 via MCP3008 - Kalman filtered acceleration (10 Hz)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        double filtered[ADC_CHANNELS];
        bool read_ok = true;

        for (int ch = 0; ch < ADC_CHANNELS; ch++) {
            int adc = mcp3008_read(g_spi_handle, ch);
            if (adc < 0) {
                read_ok = false;
                break;
            }
            double g = adc_to_g(adc);
            kalman_update(&kf[ch], g);
            filtered[ch] = kf[ch].x;
        }

        if (!read_ok) {
            fprintf(stderr, "ADC read error - continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("X: %+.3f g  Y: %+.3f g  Z: %+.3f g\n",
               filtered[0], filtered[1], filtered[2]);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

