#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define MIN_FIELD_MT -100.0
#define MAX_FIELD_MT 100.0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a digital sensor pin and return the magnetic field in millitesla.
 * Returns 0.0 on success, or a sentinel value (-1000.0) on read failure.
 */
static double read_sensor(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Warning: gpioRead failed on pin %d (rc=%d)\n", pin, level);
        return MIN_FIELD_MT - 1000.0;
    }
    /* DRV5055VA: HIGH = 3.3 V = 3.3 V * 1000 / 3.3 = 1000 mT */
    return (double)level * 1000.0;
}

static int log_data(double s1, double s2, double s3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", s1, s2, s3);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("DRV5055VA Hall-Effect sensor logging started. Press Ctrl-C to stop.\n");

    while (running) {
        double s1 = read_sensor(SENSOR1_PIN);
        double s2 = read_sensor(SENSOR2_PIN);
        double s3 = read_sensor(SENSOR3_PIN);

        if (s1 < MIN_FIELD_MT - 1000.0 || s2 < MIN_FIELD_MT - 1000.0 || s3 < MIN_FIELD_MT - 1000.0) {
            fprintf(stderr, "Warning: GPIO read error detected; skipping this sample.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (s1 > MAX_FIELD_MT || s1 < MIN_FIELD_MT ||
            s2 > MAX_FIELD_MT || s2 < MIN_FIELD_MT ||
            s3 > MAX_FIELD_MT || s3 < MIN_FIELD_MT) {
            fprintf(stderr, "Warning: field out of range (s1=%.2f, s2=%.2f, s3=%.2f mT)\n",
                    s1, s2, s3);
        }

        if (log_data(s1, s2, s3) != 0) {
            fprintf(stderr, "Warning: logging failed for this sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

