/*
 * Soil moisture monitor and pump controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0, 500 kHz, mode 0), channel 0 (single-ended).
 *   - Pump relay on GPIO17 (BCM, active-high).
 *
 * Behavior:
 *   - Reads the ADC every 60 s.
 *   - When the 0-255 ADC value is below 30, turns the pump ON.
 *   - When the ADC is at or above 30, turns the pump OFF.
 *   - Logs every event to watering.log with timestamps.
 *   - On SIGINT/SIGTERM, turns the pump off and exits cleanly.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 on SPI0 */
#define SPI_SPEED        500000     /* 500 kHz */
#define SPI_FLAGS        0          /* mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 channel 0 (single-ended) */
#define PUMP_GPIO        17         /* BCM 17, active-high */
#define MOISTURE_THRESHOLD 30       /* 0-255 ADC value below which pump ON */
#define SAMPLE_INTERVAL  60         /* seconds between readings */
#define LOG_FILE         "watering.log"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static int      g_pump_state = 0;   /* 0 = off, 1 = on */
static FILE    *g_log_fp     = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  read_mcp3008(int channel);
static void log_event(const char *msg);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MCP3008 --------------------------------- */
/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 *
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 *   rx[1] bits 1:0  -> MSB of result
 *   rx[2]          -> LSB of result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        log_event("Error: invalid ADC channel requested.");
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------- Logging ---------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_fp, "[%s] %s\n", ts, msg);
    fflush(g_log_fp);
}

/* --------------------------- Signal / cleanup ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Ensure pump is off before releasing resources */
    if (g_pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_fp) {
        log_event("Program terminated.");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* start with pump off */

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error: cannot open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started.");

    /* --- Main loop --- */
    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            log_event("Error: ADC read failed; skipping cycle.");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Soil moisture ADC value: %d", adc);
            log_event(msg);

            int new_state = (adc < MOISTURE_THRESHOLD) ? 1 : 0;
            if (new_state != g_pump_state) {
                if (gpioWrite(PUMP_GPIO, new_state) == 0) {
                    g_pump_state = new_state;
                    snprintf(msg, sizeof(msg),
                             "Pump %s (ADC=%d, threshold=%d).",
                             new_state ? "ON" : "OFF", adc, MOISTURE_THRESHOLD);
                    log_event(msg);
                } else {
                    log_event("Error: failed to write pump GPIO.");
                }
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

