/*
 * Raspberry Pi 4 Model B – MQTT LED controller
 *
 * Subscribes to "home/led_control" on mqtt.eclipseprojects.io:1883
 * (TCP, QoS 0), parses JSON payloads expecting {"led_state": true|false},
 * and drives GPIO17 (BCM) HIGH when true and LOW when false.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rpi_led_control rpi_led_control.c \
 *               -lmosquitto -ljansson -lpigpio -lrt
 *
 * Requires: pigpio, libmosquitto, libjansson
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <stdbool.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <jansson.h>

#define MQTT_HOST      "mqtt.eclipseprojects.io"
#define MQTT_PORT      1883
#define MQTT_TOPIC     "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_KEEPALIVE 60
#define LED_GPIO       17
#define MAX_RETRY_SEC  60
#define MIN_RETRY_SEC  1

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Logging helper                                                      */
/* ------------------------------------------------------------------ */
static void log_ts(const char *level, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm)) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof(ts), "?");
    }
    fprintf(stderr, "[%s] [%s] %s\n", ts, level, msg);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *ud, int rc)
{
    (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        int sub_rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (sub_rc == MOSQ_ERR_SUCCESS) {
            printf("Connected to MQTT broker, subscribed to %s\n", MQTT_TOPIC);
        } else {
            log_ts("ERROR", "Failed to subscribe");
        }
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "MQTT connect failed: %s",
                 mosquitto_strerror(rc));
        log_ts("ERROR", buf);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *ud, int rc)
{
    (void)mosq; (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        printf("Disconnected cleanly from MQTT broker.\n");
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf), "Unexpected MQTT disconnect: %s",
                 mosquitto_strerror(rc));
        log_ts("ERROR", buf);
    }
}

static void on_message(struct mosquitto *mosq, void *ud,
                        const struct mosquitto_message *msg)
{
    (void)mosq; (void)ud;

    if (!msg || !msg->payload || msg->payloadlen <= 0) {
        log_ts("WARN", "Empty MQTT payload received");
        return;
    }

    /*
     * Expected JSON: {"led_state": true} or {"led_state": false}
     * Reject anything else.
     */
    json_error_t err;
    json_t *root = json_loadb((const char *)msg->payload, msg->payloadlen, 0, &err);
    if (!root) {
        char buf[256];
        snprintf(buf, sizeof(buf),
                 "JSON parse error: %s (line %d, col %d)",
                 err.text, err.line, err.column);
        log_ts("ERROR", buf);
        return;
    }

    json_t *js = json_object_get(root, "led_state");
    if (!js) {
        log_ts("ERROR", "Missing \"led_state\" key");
        json_decref(root);
        return;
    }

    if (!json_is_boolean(js)) {
        log_ts("ERROR", "\"led_state\" is not a boolean");
        json_decref(root);
        return;
    }

    bool state = json_boolean_value(js);

    if (gpioWrite(LED_GPIO, state ? 1 : 0) < 0) {
        log_ts("ERROR", "gpioWrite failed on LED GPIO");
    } else {
        printf("LED set to %s\n", state ? "ON" : "OFF");
    }

    json_decref(root);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        log_ts("FATAL", "pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        log_ts("FATAL", "Failed to set LED GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);   /* start with LED off */

    /* --- mosquitto init --------------------------------------------- */
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        log_ts("FATAL", "mosquitto_new failed (out of memory)");
        mosquitto_lib_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop with exponential backoff ------------------------ */
    int rc = EXIT_SUCCESS;
    int attempt = 0;
    int delay = MIN_RETRY_SEC;

    while (g_running) {
        int connect_rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT,
                                           MQTT_KEEPALIVE);
        if (connect_rc == MOSQ_ERR_SUCCESS) {
            printf("Connecting to %s:%d ...\n", MQTT_HOST, MQTT_PORT);
            if (mosquitto_loop_start(g_mosq) == MOSQ_ERR_SUCCESS) {
                printf("MQTT loop started. Waiting for messages...\n");
                while (g_running) {
                    sleep(1);
                }
                mosquitto_loop_stop(g_mosq, false);
            } else {
                log_ts("ERROR", "mosquitto_loop_start failed");
            }
            break;  /* connected and loop exited cleanly */
        }

        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Connect failed (rc=%d): %s",
                 connect_rc, mosquitto_strerror(connect_rc));
        log_ts("ERROR", buf);

        attempt++;
        delay = (attempt < 6) ? (MIN_RETRY_SEC << attempt) : MAX_RETRY_SEC;

        printf("Retrying in %d seconds...\n", delay);
        for (int i = 0; i < delay && g_running; i++) {
            sleep(1);
        }
    }

    /* --- graceful shutdown ----------------------------------------- */
    if (g_mosq) {
        mosquitto_loop_stop(g_mosq, true);
    }
    cleanup();
    return rc;
}

