/*
 * KY-038 Sound Sensor - Digital Output (DO) Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern GPIO API)
 *
 * Wiring:
 *   KY-038 DO  -> GPIO17 (BCM)
 *   Alarm LED  -> GPIO18 (BCM, with appropriate series resistor)
 *
 * Behavior:
 *   - Reads the digital DO pin every 100 ms.
 *   - When the DO line reads LOW (sound detected), the alarm LED is
 *     turned on for 1 s, then off, and the program continues monitoring.
 *   - SIGINT/SIGTERM cleanly releases GPIO lines and terminates pigpio.
 *   - Exits on any pigpio error.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17   /* KY-038 DO  (BCM) */
#define ALARM_LED_PIN    18   /* Alarm LED  (BCM) */

#define POLL_DELAY_US    100000   /* 100 ms between reads */
#define ALARM_DURATION_US 1000000 /* 1 s alarm pulse */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — releases both output and input lines              */
/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    gpioWrite(ALARM_LED_PIN, 0);   /* ensure LED is off */
    gpioSetMode(ALARM_LED_PIN, PI_INPUT);
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm LED as output, initially off ---- */
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", ALARM_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sound sensor pin as input ---- */
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    /* ---- Main monitoring loop ---- */
    while (g_running) {
        int level = gpioRead(SOUND_SENSOR_PIN);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SOUND_SENSOR_PIN);
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        printf("Sound Level: %d\n", level);
        fflush(stdout);

        /* KY-038 DO goes LOW when sound exceeds threshold */
        if (level == 0) {
            printf("Sound detected! Triggering alarm.\n");
            fflush(stdout);

            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED.\n");
                cleanup_gpio();
                return EXIT_FAILURE;
            }

            /* Keep LED on for 1 s, checking for shutdown signal */
            for (int i = 0; i < 10 && g_running; i++) {
                gpioDelay(100000); /* 100 ms slices */
            }

            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED.\n");
                cleanup_gpio();
                return EXIT_FAILURE;
            }
        }

        /* 100 ms poll delay */
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

