/*
 * vibration_monitor.c — SW-420 vibration sensor monitor for Raspberry Pi 4.
 *
 * Hardware:
 *   - SW-420 vibration module (DO pin) -> GPIO17 (BCM 17, physical pin 11)
 *   - VCC -> 3.3 V (physical pin 1), GND -> GND (physical pin 9)
 *
 * The SW-420 DO output is active-low: it pulls LOW when vibration exceeds
 * the module's threshold, so we request falling-edge events.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vibration_monitor vibration_monitor.c
 * Run:    sudo ./vibration_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "/dev/gpiochip0"
#define GPIO_LINE_OFFSET    17          /* BCM 17 */
#define LOG_FILE_PATH       "/var/log/vibration_shutdown.log"
#define CONSUMER_NAME       "vibration-monitor"
#define POLL_TIMEOUT_MS     1000        /* 1 s */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE_PATH ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Shutdown                                                            */
/* ------------------------------------------------------------------ */
static int initiate_shutdown(void)
{
    int rc = system("sudo shutdown -h now");
    if (rc == -1) {
        perror("system()");
        return -1;
    }
    if (!WIFEXITED(rc) || WEXITSTATUS(rc) != 0) {
        fprintf(stderr, "shutdown command failed (status=0x%04x)\n", rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open(" GPIO_CHIP_NAME ")");
        goto out;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line()");
        goto cleanup_chip;
    }

    /* Request the line for falling-edge events */
    if (gpiod_line_request_falling_edge_events(line, CONSUMER_NAME) < 0) {
        perror("gpiod_line_request_falling_edge_events()");
        goto cleanup_chip;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO17 (BCM)...\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main event loop */
    while (g_running) {
        int rv = gpiod_line_event_wait(line, &(struct timespec){
            .tv_sec  = POLL_TIMEOUT_MS / 1000,
            .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L
        });

        if (rv < 0) {
            if (errno == EINTR)
                continue;            /* interrupted by signal */
            perror("gpiod_line_event_wait()");
            goto cleanup_line;
        }
        if (rv == 0)
            continue;                /* timeout, no event */

        /* Read the event to confirm it and clear the queue */
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read()");
            continue;
        }

        /* Falling edge => vibration detected */
        printf("Vibration detected! Initiating shutdown...\n");
        fflush(stdout);

        if (log_event("Vibration detected! Initiating shutdown...") != 0)
            fprintf(stderr, "Warning: failed to log event.\n");

        if (initiate_shutdown() != 0)
            fprintf(stderr, "Warning: shutdown command failed.\n");

        ret = EXIT_SUCCESS;
        break;
    }

cleanup_line:
    gpiod_line_release(line);

cleanup_chip:
    gpiod_chip_close(chip);

out:
    if (!g_running)
        printf("\nExiting cleanly.\n");
    return ret;
}

