/*
 * BMP280 altitude logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP280 SDA -> GPIO2 (pin 3)
 *   BMP280 SCL -> GPIO3 (pin 5)
 *   BMP280 VDD -> 3.3 V
 *   BMP280 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bmp280_altitude bmp280_altitude.c -lm -lpigpio -lrt
 *
 * Run:
 *   sudo ./bmp280_altitude
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP280 constants (datasheet rev 1.26) ---- */
#define BMP280_I2C_ADDR        0x76
#define BMP280_REG_CHIP_ID     0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB_00    0x88

#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_CMD       0xB6

/* Oversampling x1 for both pressure and temperature */
#define BMP280_OSRS_T_X1       0x01
#define BMP280_OSRS_P_X1       0x01

/* Standby 1000 ms, IIR filter off */
#define BMP280_MISC_T1000MS    0x00
#define BMP280_MISC_FILTER_OFF 0x00

#define LOG_FILE_NAME          "altitude_log.txt"
#define SAMPLE_INTERVAL_US     5000000  /* 5 s */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Calibration coefficients (read once) ---- */
static uint16_t dig_T1;
static int16_t  dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t  dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t  t_fine;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a BMP280 register.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[BMP280] I2C read failed at reg 0x%02X (rc=%d)\n",
                reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a BMP280 register.                           */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[BMP280] I2C write failed at reg 0x%02X (rc=%d)\n",
                reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian calibration word.                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_calib_u16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (bmp280_read_reg(handle, reg, &lo) < 0) return -1;
    if (bmp280_read_reg(handle, reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit signed little-endian calibration word.                */
