/* ------------------------------------------------------------------ */
/* Read the 24-bit raw temperature and pressure.                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int bmp280_read_raw(int handle, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t d[6];
