    if (rc != 6) {
        fprintf(stderr, "[BMP280] I2C block read failed (rc=%d)\n", rc);
        return -1;
    }
    *raw_p = ((int32_t)d[0] << 12) | ((int32_t)d[1] << 4) | (d[2] >> 4);
    *raw_t = ((int32_t)d[3] << 12) | ((int32_t)d[4] << 4) | (d[5] >> 4);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compensate temperature (datasheet formula).                         */
/* ------------------------------------------------------------------ */
static int32_t bmp280_compensate_temp(int32_t raw_t)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)dig_T1)) * ((raw_t >> 4) - ((int32_t)dig_T1))) >> 12) *
            ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;  /* centi-degrees Celsius */
}

/* ------------------------------------------------------------------ */
/* Compensate pressure (datasheet formula).                            */
/* ------------------------------------------------------------------ */
static uint32_t bmp280_compensate_press(int32_t raw_p)
{
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)dig_P6);
    var2 = var2 + ((var1 * ((int32_t)dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)dig_P4) << 16);
    var1 = (((((int32_t)dig_P3) * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) +
            ((((int32_t)dig_P2) * var1) >> 1)) >> 18;
