    if (bmp280_read_calib_s16(g_i2c_handle, 0x92, &dig_P3)  < 0) goto cleanup_i2c;
    if (bmp280_read_calib_s16(g_i2c_handle, 0x94, &dig_P4)  < 0) goto cleanup_i2c;
    if (bmp280_read_calib_s16(g_i2c_handle, 0x96, &dig_P5)  < 0) goto cleanup_i2c;
    if (bmp280_read_calib_s16(g_i2c_handle, 0x98, &dig_P6)  < 0) goto cleanup_i2c;
    if (bmp280_read_calib_s16(g_i2c_handle, 0x9A, &dig_P7)  < 0) goto cleanup_i2c;
    if (bmp280_read_calib_s16(g_i2c_handle, 0x9C, &dig_P8)  < 0) goto cleanup_i2c;
    if (bmp280_read_calib_s16(g_i2c_handle, 0x9E, &dig_P9)  < 0) goto cleanup_i2c;

