    if (bmp280_write_reg(g_i2c_handle, BMP280_REG_CTRL_MEAS,
                         (BMP280_OSRS_T_X1 << 5) | (BMP280_OSRS_P_X1 << 2) | 0x03) < 0)
        goto cleanup_i2c;
