#define SPI_MODE 0
#define LM35_CHANNEL 0
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5
#define ADC_RESOLUTION 1024.0
#define LM35_VREF 5.0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_temperature(void) {
    int adc = read_mcp3008(LM35_CHANNEL);
    if (adc < 0) return -1000.0f;
    return (adc / ADC_RESOLUTION) * LM35_VREF * 100.0f;
}

static void add_to_buffer(float *buffer, int *index, float value) {
    buffer[*index] = value;
    *index = (*index + 1) % BUFFER_SIZE;
}

static int write_buffer_to_file(const char *filename, const float *buffer, int size) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    size_t written = fwrite(buffer, sizeof(float), size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        goto cleanup;
    }

    float buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int sample_count = 0;

    while (running) {
        float temperature = read_temperature();
        if (temperature < -999.0f) {
            fprintf(stderr, "Error reading temperature, skipping sample\n");
        } else {
            add_to_buffer(buffer, &buffer_index, temperature);
            printf("Temperature: %.2f °C\n", temperature);
            sample_count++;
            if (sample_count >= BUFFER_SIZE) {
                if (write_buffer_to_file("temp_log.dat", buffer, BUFFER_SIZE) < 0) {
                    fprintf(stderr, "Error writing buffer to file\n");
                }
                sample_count = 0;
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

