#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x5C
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 180

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0

#define LOG_FILE "environmental_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }
    unsigned char cmd = BH1750_CONT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        perror("write(BH1750 config)");
        return -1;
    }
    return 0;
}

static int bh1750_read(int fd, float *lux) {
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("read(BH1750)");
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int mcp3008_read(int spi_fd, int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(float light, int sound) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Light: %.2f, Sound: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, light, sound);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open(/dev/i2c-1)");
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        close(i2c_fd);
        return 1;
    }

    unsigned char spi_mode = SPI_MODE_0;
    unsigned char spi_bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        perror("ioctl(SPI config)");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float light = 0.0f;
        int sound = 0;
        int light_ok = 0, sound_ok = 0;

        if (bh1750_read(i2c_fd, &light) == 0) {
            light_ok = 1;
        } else {
            fprintf(stderr, "BH1750 read error\n");
        }

        if (mcp3008_read(spi_fd, MCP3008_CHANNEL, &sound) == 0) {
            sound_ok = 1;
        } else {
            fprintf(stderr, "MCP3008 read error\n");
        }

        if (light_ok || sound_ok) {
            log_data(light_ok ? light : -1.0f, sound_ok ? sound : -1);
        }

        sleep(1);
    }

    close(spi_fd);
    close(i2c_fd);
    return 0;
}

