/*
 * flame_monitor.c — Read a Keyes KY-026 flame sensor on a Raspberry Pi 5.
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (pin 1)
 *   KY-026 GND  -> GND    (pin 9)
 *   KY-026 D0   -> BCM 17 (pin 11) — digital output, active HIGH
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17          /* BCM 17 — physical pin 11 */
#define LOG_FILE         "flame_events.log"
#define POLL_INTERVAL_S  1           /* seconds between readings */

/* ------------------------------------------------------------------ */
/* Globals for signal-driven cleanup                                  */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one CSV row: timestamp,pin,state                              */
/* ------------------------------------------------------------------ */
static int log_event(FILE *fp, int pin, int state)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", ts, pin, state) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes log file and terminates pigpio               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* ---- Install signal handlers early ------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ------------------------------------------ */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* ---- Configure flame sensor pin as input with pull-down --------- */
    rc = gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed: %d\n",
                FLAME_SENSOR_PIN, rc);
        cleanup();
        return EXIT_FAILURE;
    }

    rc = gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN);
    if (rc != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed: %d\n",
                FLAME_SENSOR_PIN, rc);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending -------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
