/*
 * Light sequencer for Raspberry Pi 3 Model B+
 * Relays: 4 × Songle SRD-05VDC-SL (active-high)
 * Pins:   BCM 17, 22, 23, 24
 * Library: pigpio (modern GPIO API)
 *
 * Build:  gcc -Wall -Wextra -O2 -o light_seq light_seq.c -lpigpio -lrt
 * Run:    sudo ./light_seq
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1 17
#define RELAY2 22
#define RELAY3 23
#define RELAY4 24

#define ON_TIME_SEC  1
#define OFF_TIME_SEC 1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on SIGINT / SIGTERM            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helper: safe GPIO write with error checking                         */
/* ------------------------------------------------------------------ */
static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(gpio=%u, level=%u) failed\n",
                gpio, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helper: activate a relay for ON_TIME_SEC, then deactivate           */
/* ------------------------------------------------------------------ */
static void activate_relay(unsigned gpio)
{
    if (safe_write(gpio, 1) != 0)
        return;

    /*
     * Sleep in 100 ms increments so we can respond to signals promptly.
     * pigpio's gpioSleep is interruptible by signals, but we want to
     * exit promptly on SIGINT / SIGTERM.
     */
    for (int i = 0; i < ON_TIME_SEC * 10 && g_running; i++)
        gpioSleep(PI_TIME_RELATIVE, 0, 100000); /* 100 ms */

    safe_write(gpio, 0);

    /*
     * Wait for OFF_TIME_SEC but check for signals every 100 ms.
     */
    for (int i = 0; i < OFF_TIME_SEC * 10 && g_running; i++)
        gpioSleep(PI_TIME_RELATIVE, 0, 100000);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    const unsigned relays[] = { RELAY1, RELAY2, RELAY3, RELAY4 };
    const int num_relays = (int)(sizeof(relays) / sizeof(relays[0]));

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure relay pins as outputs, initialised LOW ---- */
    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relays[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(gpio=%u, PI_OUTPUT) failed\n",
                    relays[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (safe_write(relays[i], 0) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Light sequencer started. Relays on BCM %u, %u, %u, %u.\n",
           RELAY1, RELAY2, RELAY3, RELAY4);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        for (int i = 0; i < num_relays && g_running; i++)
            activate_relay(relays[i]);
    }

    /* ---- Graceful shutdown: deactivate all relays ---- */
    printf("\nShutting down...\n");
    for (int i = 0; i < num_relays; i++)
        safe_write(relays[i], 0);

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

