#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <driver_library.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define PWM_RANGE 255
#define PWM_DUTY 150

#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"
#define POLL_INTERVAL_SEC 1
#define MOTOR_RUN_SEC 3

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_rain_level(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void control_window(int rain_level) {
    int direction = (rain_level > RAIN_THRESHOLD) ? 1 : -1;
    const char *action = (direction > 0) ? "closing" : "opening";

    printf("Rain level: %d, %s window...\n", rain_level, action);

    if (driver_library_init() != 0) {
        fprintf(stderr, "Error initializing driver library\n");
        return;
    }

    driver_library_set_pwm_range(MOTOR_ENA, PWM_RANGE);
    driver_library_set_pwm_dutycycle(MOTOR_ENA, PWM_DUTY);

    driver_library_set_pin_mode(MOTOR_IN1, DRIVER_LIBRARY_OUTPUT);
    driver_library_set_pin_mode(MOTOR_IN2, DRIVER_LIBRARY_OUTPUT);

    if (direction > 0) {
        driver_library_write_pin(MOTOR_IN1, 1);
        driver_library_write_pin(MOTOR_IN2, 0);
    } else {
        driver_library_write_pin(MOTOR_IN1, 0);
        driver_library_write_pin(MOTOR_IN2, 1);
    }

    sleep(MOTOR_RUN_SEC);

    driver_library_write_pin(MOTOR_IN1, 0);
    driver_library_write_pin(MOTOR_IN2, 0);
    driver_library_set_pwm_dutycycle(MOTOR_ENA, 0);
    driver_library_terminate();

    printf("Window %s complete.\n", action);
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain sensor, skipping cycle.\n");
        } else {
            if (log_rain_level(rain_level) != 0) {
                fprintf(stderr, "Error logging rain level.\n");
            }
            control_window(rain_level);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

