/*
 * Raspberry Pi 4 Model B - MAX9814 Clap Detector
 *
 * Hardware:
 *   - MAX9814 analog microphone amplifier output -> BCM GPIO26 (ADC bit-banged)
 *   - LED + 330 ohm resistor -> BCM GPIO16
 *
 * Behavior:
 *   Samples the ADC on GPIO26 at 1 kHz, detects a clap above a threshold,
 *   debounces for 50 ms, lights the LED for 500 ms, and prints a timestamped
 *   message to stdout.  Runs until SIGINT (Ctrl+C).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o clap_detector clap_detector.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware-level GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_PIN        26
#define LED_PIN        16

#define SAMPLE_RATE_HZ 1000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define DEBOUNCE_MS     50
#define LED_ON_MS       500
#define THRESHOLD       100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single bit-banged ADC sample from the given GPIO pin.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_adc_bit_banged(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", pin);
        return -1;
    }

    /*
     * MAX9814 output is open-collector / open-drain.  We sample by
     * releasing the pin into a high-impedance input state and then
     * read the pulled-high or pulled-low value.
     */
    if (gpioSetPullUpDown(pin, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Error: failed to set pull-up/down on GPIO %d\n", pin);
        return -1;
    }

    gpioDelay(1); /* let the pin settle */

    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", pin);
        return -1;
    }

    return level;
}

/*
 * Convert a sequence of N bit-banged samples into a 10-bit ADC value.
 * MAX9814 output is typically biased near VDD/2, so the 10-bit range
 * is centered on 512.
 */
static int adc_samples_to_value(const int *samples, int n)
{
    int value = 0;
    for (int i = 0; i < n; i++) {
        value <<= 1;
        if (samples[i] == 1) {
            value |= 1;
        }
    }
    return value;
}

static void log_detection(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] Clap detected!\n", timestamp);
        fflush(stdout);
    } else {
        printf("[unknown time] Clap detected!\n");
        fflush(stdout);
    }
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Is the pigpio daemon running?  Run: sudo pigpiod\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO %d.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started.  ADC: GPIO%d | LED: GPIO%d\n", ADC_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool clap_active = false;
    uint32_t clap_start_tick = 0;

    while (g_running) {
        int samples[10];
        bool read_error = false;

        for (int i = 0; i < 10 && !read_error; i++) {
            int bit = read_adc_bit_banged(ADC_PIN);
            if (bit < 0) {
                read_error = true;
            } else {
                samples[i] = bit;
            }
        }

        if (read_error) {
            fprintf(stderr, "Warning: ADC read error, skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int adc_value = adc_samples_to_value(samples, 10);

        if (adc_value > THRESHOLD && !clap_active) {
            clap_active = true;
            clap_start_tick = gpioTick();
            log_detection();

            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Warning: failed to turn on LED.\n");
            }

            /*
             * Keep the LED on for LED_ON_MS, but allow SIGINT to
             * interrupt the 500 ms window.
             */
            uint32_t led_start = gpioTick();
            while (g_running && (gpioTick() - led_start) < (uint32_t)(LED_ON_MS * 1000)) {
                gpioDelay(1000);
            }

            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Warning: failed to turn off LED.\n");
            }
        } else if (clap_active) {
            /* Debounce: stay active for DEBOUNCE_MS after detection */
            if ((gpioTick() - clap_start_tick) > (uint32_t)(DEBOUNCE_MS * 1000)) {
                clap_active = false;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

