            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_data(-1);
        } else {
            log_data(moisture_level);
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

