/*
 * Raspberry Pi 3 Model B+ — MLX91209 current sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pi pin 1)
 *   MCP3008 VREF -> 3.3 V (Pi pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  pin 24)
 *   MCP3008 CH0  -> MLX91209 VOUT
 *   MLX91209 VCC -> 5 V (external supply)
 *   MLX91209 GND -> GND
 *   MLX91209 EN  -> GPIO17 (BCM 17, pin 11)
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c
 *
 * The MLX91209 is a 5 V output sensor; the 100 mV/A transfer function
 * yields ~100 mA per volt, so the full-scale 5 V span yields ~250 A.
 * Adjust scale_factor and offset if your sensor has a different ratio.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz — well within MCP3008 limits */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          SPI_MODE_0

#define GPIO_CHIP         "gpiochip0"
#define GPIO_LINE         17          /* BCM 17, pin 11 — MLX91209 EN */

#define ADC_CHANNEL       0           /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE     1023        /* 10-bit ADC */
#define ADC_VREF          3.3f        /* MCP3008 VREF tied to 3.3 V */

#define LOG_FILE          "current_log.txt"
#define SAMPLE_INTERVAL_S 1

/*
 * MLX91209 transfer function (typical): I = (V_out / V_ref) * full_scale
 *   MLX91209 VOUT = 100 mV/A  =>  1 V = 10 A
 *   MCP3008 VREF  = 3.3 V
 *   full_scale    = 5 V
 *   => scale = 10.0 / 3.3 * 5.0 = 16.666666666666668 A/V
 *   => offset = 0.0 A
 */
#define SCALE_FACTOR      16.666666666666668f
#define OFFSET_A          0.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on error.
 */
static int mcp3008_read(int spi_fd, uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *out_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* ---- Open SPI device ---- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    /* ---- Open GPIO chip and request EN line ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, default LOW (sensor OFF). */
    if (gpiod_line_request_output(line, "mlx91209-en", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("MLX91209 current monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t adc_value = 0;

        /*
         * Read ADC. If the transfer fails, log the error and continue.
         */
        if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Convert ADC counts to voltage and then to current. */
        float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
        float current = (voltage / ADC_VREF) * SCALE_FACTOR + OFFSET_A;

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *tm_info = localtime_r(&now, &tm_buf);
        char ts[32];
        if (tm_info == NULL) {
            snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");
        } else {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        }

        /* CSV line */
        if (fprintf(log_file, "%s,%.4f\n", ts, current) < 0) {
            perror("fprintf(log_file)");
        } else {
            fflush(log_file);
        }

        /*
         * Sensor-absent heuristic: if the ADC value is near 0 or near
         * full-scale, warn that the sensor may be disconnected or
         * the wiring is faulty.
         */
        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr,
                    "Warning: ADC saturated at %u — sensor may be absent or wiring fault\n",
                    adc_value);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

