/*
 * Raspberry Pi Zero W — MLX91211 current sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V (pin 2 or 4)
 *   MCP3008 VREF -> Pi 5V (pin 2 or 4)
 *   MCP3008 AGND -> Pi GND (pin 6)
 *   MCP3008 DGND -> Pi GND (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (pin 23, SPI0 SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (pin 21, SPI0 MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (pin 19, SPI0 MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (pin 24, SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 VOUT
 *   MLX91211 VDD -> Pi 5V (pin 2 or 4)
 *   MLX91211 GND -> Pi GND (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_logger current_logger.c -lpigpio -lrt
 * Run:    sudo ./current_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* MCP3008 CE0 (GPIO8)                       */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 spec (max 3.2) */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                     */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0            */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC                                */
#define ADC_VREF       5.0        /* Reference voltage (volts)                 */

#define SAMPLE_PERIOD_US 100000   /* 100 ms between samples                    */
#define LOG_FILE        "current_log.txt"

/*
 * MLX91211 load resistor: 100 Ω.
 * Current (A) = (V_sensor / R_load) * (V_ref / V_full_scale)
 * where V_full_scale = 3.3 V (pigpio SPI transfer returns 3.3 V for 1023).
 * We use V_full_scale = 5.0 V for the 5 V reference.
 */
#define R_LOAD          100.0     /* Load resistor (Ω)                         */
#define V_FULL_SCALE    5.0       /* pigpio SPI transfer returns 5 V for 1023   */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int   g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  read_mcp3008(int channel, int *adc_value);
static double adc_to_current(int adc_value);
static int  log_current(double current);
static void cleanup(void);

/* ------------------------------- Handlers --------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly                 */
}

/*
 * Read a single-ended channel from the MCP3008.
 *
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 *
 * Result (10-bit value):
 *   rx[1] bits 1..0  -> bits 9..8 of result
 *   rx[2]           -> bits 7..0 of result
 *
 * Returns 0 on success (adc_value set), -1 on SPI transfer error.
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/*
 * Convert ADC count to current (A).
 *   I = (V_sensor / R_load) * (V_ref / V_full_scale)
 *   V_sensor = (adc / V_full_scale) * V_ref
 *   I = (adc / (V_full_scale * R_load)) * V_ref
 */
static double adc_to_current(int adc_value)
{
    return ((double)adc_value / (ADC_VREF * R_LOAD)) * ADC_VREF;
}

/*
 * Append a timestamped current reading to the log file.
 * Returns 0 on success, -1 on file error.
 */
static int log_current(double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/*
 * Release all resources in reverse order of acquisition.
 */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- main ----------------------------------- */

int main(void)
{
    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus for MCP3008 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current logging started. Press Ctrl+C to stop.\n");
    printf("Logging to: %s\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            /* SPI transfer error — skip this sample, keep running */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* Sanity-check: ADC should not exceed VREF */
        if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        double current = adc_to_current(adc_value);

        /* Sanity-check: sensor output should not exceed VREF */
        if (current < 0.0 || current > ADC_VREF) {
            fprintf(stderr, "Current out of range: %.2f A (ADC %d)\n",
                    current, adc_value);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_current(current) != 0) {
            /* File error — stop logging but keep running */
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

