#include <driver_library.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4;
    tx_buf[2] = 0x00;
    if (spi_transfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

int log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }
    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    printf("%s,%.2f\n", timestamp, moisture_level);
    return 0;
}

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
    if (spi_handle >= 0) {
        spi_close(spi_handle);
        spi_handle = -1;
    }
    driver_library_terminate();
    exit(0);
}

int spi_setup(spi_config_t config) {
    spi_handle = spi_open(config.channel, config.baud);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d\n", config.channel);
        return -1;
    }
    return 0;
}

int main() {
    spi_config_t config = {SPI_CHANNEL, SPI_BAUD};
    if (driver_library_init() != 0) {
        fprintf(stderr, "Error: Could not initialize driver library\n");
        return 1;
    }
    if (spi_setup(config) != 0) {
        driver_library_terminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }
        double moisture_level = calculate_moisture_level(adc_value);
        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }
        sleep(READ_DELAY);
    }
    spi_close(spi_handle);
    driver_library_terminate();
    return 0;
}

