/*
 * security_cam.c — Raspberry Pi 4 Model B
 * HC-SR501 PIR sensor monitor with libcamera-still snapshot capture.
 *
 * Build:  gcc -O2 -Wall -Wextra -o security_cam security_cam.c -lpigpio -lrt
 * Run:    sudo ./security_cam
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO          17
#define DEBOUNCE_DELAY_US 200000   /* 200 ms */
#define POLL_INTERVAL_US  50000    /* 50 ms  */
#define CAPTURE_DIR       "/home/pi/security_cam"
#define FILENAME_MAX_LEN  256

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Directory helpers                                                   */
/* ------------------------------------------------------------------ */
static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "'%s' exists but is not a directory", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat('%s'): %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir('%s'): %s", path, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Created capture directory '%s'", path);
    return 0;
}

/* ------------------------------------------------------------------ */
/* libcamera-still snapshot                                            */
/* ------------------------------------------------------------------ */
static int capture_snapshot(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork(): %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null to keep syslog clean. */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);

        char *const argv[] = {
            "libcamera-still",
            "-o", (char *)filename,
            "--nopreview",
            "--timeout", "1000",
            "--encoding", "jpeg",
            "--quality", "85",
            NULL
        };

        execvp("libcamera-still", argv);
        /* If execvp returns, it failed. */
        syslog(LOG_ERR, "execvp(libcamera-still): %s", strerror(errno));
        _exit(127);
    }

    /* Parent: wait for child. */
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid(): %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    if (WIFEXITED(status))
        syslog(LOG_ERR, "libcamera-still exited with status %d",
               WEXITSTATUS(status));
    else if (WIFSIGNALED(status))
        syslog(LOG_ERR, "libcamera-still killed by signal %d",
               WTERMSIG(status));
    else
        syslog(LOG_ERR, "libcamera-still terminated abnormally");

    return -1;
}

/* ------------------------------------------------------------------ */
/* Timestamped filename                                                */
/* ------------------------------------------------------------------ */
static int build_filename(char *buf, size_t buflen, const char *dir,
                          const char *prefix)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time(): %s", strerror(errno));
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        syslog(LOG_ERR, "localtime_r() failed");
        return -1;
    }

    if (snprintf(buf, buflen, "%s/%s_%04d%02d%02d_%02d%02d%02d.jpg",
                 dir, prefix,
                 tm_local.tm_year + 1900, tm_local.tm_mon + 1, tm_local.tm_mday,
                 tm_local.tm_hour, tm_local.tm_min, tm_local.tm_sec)
        >= (int)buflen) {
        syslog(LOG_ERR, "Filename buffer too small");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera monitor (PIR GPIO%d)", PIR_GPIO);

    /* Install signal handlers. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Ensure capture directory exists. */
    if (ensure_directory(CAPTURE_DIR) != 0) {
        syslog(LOG_ERR, "Cannot proceed without capture directory");
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    /* Configure PIR pin as input with pull-down. */
    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "PIR GPIO%d configured as input (pull-down)", PIR_GPIO);

    /* Main polling loop. */
    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead(%d) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "Monitoring started (initial state: %d)", last_state);

    while (g_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            syslog(LOG_INFO, "PIR state change: %d -> %d",
                   last_state, current_state);

            /* Debounce: wait, then re-read. */
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead(%d) failed during debounce", PIR_GPIO);
                break;
            }

            if (confirmed == current_state) {
                /* Motion confirmed. */
                char filename[FILENAME_MAX_LEN];
                if (build_filename(filename, sizeof(filename),
                                   CAPTURE_DIR, "motion") == 0) {
                    syslog(LOG_INFO, "Motion detected — capturing: %s",
                           filename);
                    if (capture_snapshot(filename) == 0) {
                        syslog(LOG_INFO, "Snapshot saved: %s", filename);
                    } else {
                        syslog(LOG_ERR, "Snapshot capture failed for %s",
                               filename);
                    }
                }
            }
            last_state = confirmed;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown. */
    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

