#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1
#define PGM_HEADER_SIZE 18
#define MAX_FILENAME_LENGTH 64

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int save_pgm(const unsigned char *data, int width, int height, int image_number) {
    char filename[MAX_FILENAME_LENGTH];
    FILE *fp;
    unsigned char pgm_header[PGM_HEADER_SIZE];
    int header_len;

    snprintf(filename, sizeof(filename), "image_%04d.pgm", image_number);

    header_len = snprintf((char *)pgm_header, sizeof(pgm_header),
                          "P5\n%d %d\n255\n", width, height);
    if (header_len < 0 || (size_t)header_len >= sizeof(pgm_header)) {
        fprintf(stderr, "Error: Failed to format PGM header.\n");
        return -1;
    }

    fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fwrite(pgm_header, 1, (size_t)header_len, fp) != (size_t)header_len) {
        fprintf(stderr, "Error writing PGM header to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fwrite(data, 1, (size_t)(width * height), fp) != (size_t)(width * height)) {
        fprintf(stderr, "Error writing image data to %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    printf("Saved %s\n", filename);
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer = NULL;
    int buffer_size = 0;
    int image_number = 1;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(device, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device.\n", device);
        goto cleanup_fd;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O.\n", device);
        goto cleanup_fd;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Warning: driver adjusted image size to %ux%u.\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    if (req.count < 1) {
        fprintf(stderr, "Error: Insufficient buffer memory.\n");
        goto cleanup_fd;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup_fd;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup_fd;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto cleanup_mmap;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup_mmap;
    }

    printf("Capturing images from %s. Press Ctrl+C to stop.\n", device);

    while (!stop_flag) {
        fd_set fds;
        struct timeval tv;
        int rv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        rv = select(fd + 1, &fds, NULL, NULL, &tv);
        if (rv == -1) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            break;
        }
        if (rv == 0) {
            fprintf(stderr, "Error: select() timeout.\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        ret = xioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret == -1) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        if (save_pgm((unsigned char *)buffer, IMAGE_WIDTH, IMAGE_HEIGHT, image_number) == -1) {
            fprintf(stderr, "Error saving image %d.\n", image_number);
        }
        image_number++;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            break;
        }
    }

    if (stop_flag) {
        printf("\nStopping capture...\n");
    }

    enum v4l2_buf_type type_off = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type_off) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

cleanup_mmap:
    if (buffer && buffer != MAP_FAILED) {
        if (munmap(buffer, buffer_size) == -1) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        }
    }

cleanup_fd:
    if (fd != -1) {
        if (close(fd) == -1) {
            fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        }
    }

    return (stop_flag) ? EXIT_SUCCESS : EXIT_FAILURE;
}

