/*
 * CSI camera fragmenter for Raspberry Pi (BCM2711) using V4L2.
 *
 * Build:  gcc -O2 -Wall -Wextra -o csi_frag csi_frag.c
 * Run:    ./csi_frag <target_ip> <target_port>
 *
 * Captures YUYV frames from /dev/video0, fragments them into UDP
 * datagrams not exceeding 65000 bytes, and sends them to the
 * target IP/port with a header:
 *   uint32_t frame_idx   (big-endian)
 *   uint32_t frag_idx    (big-endian)
 *   uint32_t tot_frags   (big-endian)
 *   uint32_t payload_len (big-endian)
 *   payload_len bytes    (YUYV frame fragment)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define DEVICE_NAME      "/dev/video0"
#define FRAME_WIDTH      640
#define FRAME_HEIGHT     480
#define FRAME_SIZE       (FRAME_WIDTH * FRAME_HEIGHT * 2)   /* YUYV: 2 bytes/pixel */
#define MAX_PAYLOAD      65000
#define NUM_BUFFERS      4
#define HEADER_SIZE      (4 * sizeof(uint32_t))
#define MAX_PACKET_SIZE  (MAX_PAYLOAD + HEADER_SIZE)

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, buffer_t *buffers)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (*fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto fail_close;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = FRAME_WIDTH;
    fmt.fmt.pix.height      = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail_close;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV\n");
        goto fail_close;
    }

    memset(&req, 0, sizeof(req));
    req.count  = NUM_BUFFERS;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail_close;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail_close;
    }

    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = i;

        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto fail_unmap;
        }

        buffers[i].length = buf.length;
        buffers[i].start  = mmap(NULL, buf.length,
                                 PROT_READ | PROT_WRITE,
                                 MAP_SHARED, *fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            buffers[i].start = NULL;
            goto fail_unmap;
        }
    }

    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = i;

        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto fail_unmap;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto fail_unmap;
    }

    return 0;

fail_unmap:
    for (i = 0; i < req.count; ++i) {
        if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
            buffers[i].start = NULL;
        }
    }
fail_close:
    close(*fd);
    *fd = -1;
    return -1;
}

static void stop_camera(int fd, buffer_t *buffers)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (fd >= 0) {
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0)
            perror("VIDIOC_STREAMOFF");
    }

    for (unsigned int i = 0; i < NUM_BUFFERS; ++i) {
        if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
            buffers[i].start = NULL;
        }
    }

    if (fd >= 0) {
        close(fd);
    }
}

static int send_packet(int sockfd, const uint8_t *data, size_t len,
                       const struct sockaddr_in *addr)
{
    ssize_t sent = sendto(sockfd, data, len, 0,
                          (const struct sockaddr *)addr, sizeof(*addr));
    if (sent < 0) {
        perror("sendto");
        return -1;
    }
    if ((size_t)sent != len) {
        fprintf(stderr, "sendto: partial send (%zd of %zu)\n", sent, len);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target_ip> <target_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = -1;
    buffer_t buffers[NUM_BUFFERS];
    for (unsigned int i = 0; i < NUM_BUFFERS; ++i)
        buffers[i].start = NULL;

    if (init_camera(&fd, buffers) < 0) {
        fprintf(stderr, "Failed to initialize camera\n");
        return EXIT_FAILURE;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        stop_camera(fd, buffers);
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons((uint16_t)atoi(argv[2]));
    if (inet_pton(AF_INET, argv[1], &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", argv[1]);
        close(sockfd);
        stop_camera(fd, buffers);
        return EXIT_FAILURE;
    }

    unsigned int frame_idx = 0;
    struct v4l2_buffer buf;

    while (!g_stop) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv;
        tv.tv_sec  = 1;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        }
        if (r == 0) continue;

        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.index >= NUM_BUFFERS) {
            fprintf(stderr, "DQBUF index out of range\n");
            break;
        }

        if (buf.bytesused > buffers[buf.index].length) {
            fprintf(stderr, "Frame too large: %u > %zu\n",
                    buf.bytesused, buffers[buf.index].length);
            break;
        }

        size_t frame_len = buf.bytesused;
        const uint8_t *frame = (const uint8_t *)buffers[buf.index].start;

        size_t offset = 0;
        unsigned int frag_idx = 0;
        unsigned int tot_frags = (frame_len + MAX_PAYLOAD - 1) / MAX_PAYLOAD;

        while (offset < frame_len && !g_stop) {
            size_t remaining = frame_len - offset;
            size_t plen = (remaining < MAX_PAYLOAD) ? remaining : MAX_PAYLOAD;

            uint8_t *pkt = malloc(HEADER_SIZE + plen);
            if (!pkt) {
                perror("malloc");
                break;
            }

            uint32_t *hdr = (uint32_t *)pkt;
            hdr[0] = htonl(frame_idx);
            hdr[1] = htonl(frag_idx);
            hdr[2] = htonl(tot_frags);
            hdr[3] = htonl(plen);
            memcpy(pkt + HEADER_SIZE, frame + offset, plen);

            if (send_packet(sockfd, pkt, HEADER_SIZE + plen, &addr) < 0) {
                free(pkt);
                break;
            }

            free(pkt);
            offset += plen;
            frag_idx++;
        }

        frame_idx++;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    close(sockfd);
    stop_camera(fd, buffers);
    return EXIT_SUCCESS;
}

