    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            if (stop_flag) {
                fprintf(stderr, "Interrupted by signal\n");
                goto cleanup;
            }
        }
        perror("select");
        goto cleanup;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        goto cleanup;
    }

