        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused <= 0) {
        fprintf(stderr, "Dequeued buffer has invalid bytesused (%u)\n", buf.bytesused);
        goto cleanup;
    }

