    size_t written = 0;
    while (written < to_write) {
        size_t n = fwrite((char *)buffers[buf.index].start + written, 1, to_write - written, fp);
        if (n == 0) {
            if (ferror(fp)) {
                perror("fwrite");
                goto cleanup;
            }
            break;
        }
        written += n;
    }

    if (written != to_write) {
        fprintf(stderr, "Short write: %zu of %u bytes\n", written, buf.bytesused);
        goto cleanup;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        fp = NULL;
        goto cleanup;
    }
    fp = NULL;

