        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type_off = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type_off) < 0) {
        perror("VIDIOC_STREAMOFF");
        goto cleanup;
    }

    printf("Saved %u bytes to %s\n", buf.bytesused, OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) {
        enum v4l2_buf_type type_off = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type_off);
        close(fd);
    }
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }
    return ret;
}

