/*
 * Pan-tilt camera mount controller for Raspberry Pi.
 *
 * Servos (active-low PWM):
 *   Pan  -> GPIO4 (BCM), pulse 1 ms..2 ms -> duty 50..100/1000
 *   Tilt -> GPIO5 (BCM), pulse 1 ms..2 ms -> duty 50..100/1000
 *
 * Buttons (active-low, internal pull-ups):
 *   Tilt up    -> GPIO6 (BCM)
 *   Tilt down  -> GPIO7 (BCM)
 *   Pan left   -> GPIO8 (BCM)
 *   Pan right  -> GPIO9 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o pan_tilt pan_tilt.c -lpigpio -lrt
 * Run:    sudo ./pan_tilt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define PAN_PIN        4
#define TILT_PIN       5
#define TILT_UP_PIN    6
#define TILT_DOWN_PIN  7
#define PAN_LEFT_PIN   8
#define PAN_RIGHT_PIN  9

/* ---- Servo parameters ---- */
#define PWM_FREQ_HZ    20          /* 50 Hz -> 20 ms period            */
#define PWM_RANGE      1000        /* duty steps per period            */
#define PULSE_MIN_US   1000        /* 1 ms -> duty 50/1000             */
#define PULSE_MAX_US   2000        /* 2 ms -> duty 100/1000            */
#define PULSE_MID_US   1500        /* 1.5 ms -> duty 75/1000            */

#define POS_MIN        25          /* clamped position low             */
#define POS_MAX        125         /* clamped position high            */
#define POS_MID        75          /* mid-point                        */
#define STEP            5          /* position increment/decrement     */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Helpers ---- */
static int set_servo_pulse(int pin, int duty)
{
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Error: duty %d out of range [0..%d] on pin %d\n",
                duty, PWM_RANGE, pin);
        return -1;
    }
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int position_to_duty(int pos)
{
    if (pos < POS_MIN) pos = POS_MIN;
    if (pos > POS_MAX) pos = POS_MAX;
    return (int)(((long)(pos - POS_MIN) * (PWM_RANGE - 1)) / (POS_MAX - POS_MIN));
}

static int duty_to_position(int duty)
{
    return POS_MIN + (duty * (POS_MAX - POS_MIN)) / (PWM_RANGE - 1);
}

/* ---- Button read with pull-up ---- */
static int read_button(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pin);
        return -1;
    }
    return gpioRead(pin);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    /* Stop servo pulses and release pigpio */
    gpioPWM(PAN_PIN, 0);
    gpioPWM(TILT_PIN, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    int pan_pos  = POS_MID;
    int tilt_pos = POS_MID;

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure PWM pins ---- */
    if (gpioSetMode(PAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PAN_PIN, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TILT_PIN, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency and range ---- */
    if (gpioSetPWMfrequency(PAN_PIN,  PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(PAN_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(TILT_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PAN_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(PAN_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(TILT_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize servos to mid-position ---- */
    if (set_servo_pulse(PAN_PIN,  position_to_duty(pan_pos))  < 0 ||
        set_servo_pulse(TILT_PIN, position_to_duty(tilt_pos)) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt controller started.\n");
    printf("Pan: GPIO%d | Tilt: GPIO%d | Buttons: GPIO%d/GPIO%d/GPIO%d/GPIO%d\n",
           PAN_PIN, TILT_PIN, TILT_UP_PIN, TILT_DOWN_PIN, PAN_LEFT_PIN, PAN_RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int b_up    = read_button(TILT_UP_PIN);
        int b_down  = read_button(TILT_DOWN_PIN);
        int b_left  = read_button(PAN_LEFT_PIN);
        int b_right = read_button(PAN_RIGHT_PIN);

        if (b_up == 0) {
            tilt_pos += STEP;
            if (tilt_pos > POS_MAX) tilt_pos = POS_MAX;
            set_servo_pulse(TILT_PIN, position_to_duty(tilt_pos));
        } else if (b_down == 0) {
            tilt_pos -= STEP;
            if (tilt_pos < POS_MIN) tilt_pos = POS_MIN;
            set_servo_pulse(TILT_PIN, position_to_duty(tilt_pos));
        }

        if (b_left == 0) {
            pan_pos -= STEP;
            if (pan_pos < POS_MIN) pan_pos = POS_MIN;
            set_servo_pulse(PAN_PIN, position_to_duty(pan_pos));
        } else if (b_right == 0) {
            pan_pos += STEP;
            if (pan_pos > POS_MAX) pan_pos = POS_MAX;
            set_servo_pulse(PAN_PIN, position_to_duty(pan_pos));
        }

        usleep(50000); /* 50 ms poll interval */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

