    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    int pan_pos  = POS_MID;
    int tilt_pos = POS_MID;

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure PWM pins ---- */
    if (gpioSetMode(PAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PAN_PIN, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TILT_PIN, PI_OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency and range ---- */
    if (gpioSetPWMfrequency(PAN_PIN,  PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(PAN_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(TILT_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PAN_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(PAN_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(TILT_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize servos to mid-position ---- */
    if (set_servo_pulse(PAN_PIN,  position_to_duty(pan_pos))  < 0 ||
        set_servo_pulse(TILT_PIN, position_to_duty(tilt_pos)) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt controller started.\n");
    printf("Pan: GPIO%d | Tilt: GPIO%d | Buttons: GPIO%d/GPIO%d/GPIO%d/GPIO%d\n",
           PAN_PIN, TILT_PIN, TILT_UP_PIN, TILT_DOWN_PIN, PAN_LEFT_PIN, PAN_RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int b_up    = read_button(TILT_UP_PIN);
        int b_down  = read_button(TILT_DOWN_PIN);
        int b_left  = read_button(PAN_LEFT_PIN);
        int b_right = read_button(PAN_RIGHT_PIN);

        if (b_up == 0) {
            tilt_pos += STEP;
            if (tilt_pos > POS_MAX) tilt_pos = POS_MAX;
            set_servo_pulse(TILT_PIN, position_to_duty(tilt_pos));
        } else if (b_down == 0) {
            tilt_pos -= STEP;
            if (tilt_pos < POS_MIN) tilt_pos = POS_MIN;
            set_servo_pulse(TILT_PIN, position_to_duty(tilt_pos));
        }

        if (b_left == 0) {
            pan_pos -= STEP;
            if (pan_pos < POS_MIN) pan_pos = POS_MIN;
            set_servo_pulse(PAN_PIN, position_to_duty(pan_pos));
        } else if (b_right == 0) {
            pan_pos += STEP;
            if (pan_pos > POS_MAX) pan_pos = POS_MAX;
            set_servo_pulse(PAN_PIN, position_to_duty(pan_pos));
        }

        usleep(50000); /* 50 ms poll interval */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

