/*
 * capture_blur.c - Capture a YUYV frame from /dev/video0, convert to RGB24,
 * apply a blur filter, and save as a JPEG file.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_blur capture_blur.c -ljpeg
 * Run:    ./capture_blur
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define DEVICE_NAME   "/dev/video0"
#define FRAME_WIDTH   640
#define FRAME_HEIGHT  480
#define FRAME_TIMEOUT_SEC  2
#define JPEG_QUALITY  75

struct buffer {
    void   *start;
    size_t  length;
};

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb,
                         int width, int height)
{
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j += 2) {
            int y0 = yuyv[i * width * 2 + j * 2];
            int u  = yuyv[i * width * 2 + j * 2 + 1] - 128;
            int y1 = yuyv[i * width * 2 + (j + 1) * 2];
            int v  = yuyv[i * width * 2 + (j + 1) * 2 + 1] - 128;

            int r0 = y0 + (int)(1.402 * v);
            int g0 = y0 - (int)(0.34414 * u) - (int)(0.71414 * v);
            int b0 = y0 + (int)(1.772 * u);
            int r1 = y1 + (int)(1.402 * v);
            int g1 = y1 - (int)(0.34414 * u) - (int)(0.71414 * v);
            int b1 = y1 + (int)(1.772 * u);

            if (r0 < 0) r0 = 0; if (r0 > 255) r0 = 255;
            if (g0 < 0) g0 = 0; if (g0 > 255) g0 = 255;
            if (b0 < 0) b0 = 0; if (b0 > 255) b0 = 255;
            if (r1 < 0) r1 = 0; if (r1 > 255) r1 = 255;
            if (g1 < 0) g1 = 0; if (g1 > 255) g1 = 255;
            if (b1 < 0) b1 = 0; if (b1 > 255) b1 = 255;

            rgb[i * width * 3 + j * 3 + 0] = (unsigned char)r0;
            rgb[i * width * 3 + j * 3 + 1] = (unsigned char)g0;
            rgb[i * width * 3 + j * 3 + 2] = (unsigned char)b0;
            rgb[i * width * 3 + (j + 1) * 3 + 0] = (unsigned char)r1;
            rgb[i * width * 3 + (j + 1) * 3 + 1] = (unsigned char)g1;
            rgb[i * width * 3 + (j + 1) * 3 + 2] = (unsigned char)b1;
        }
    }
    return 0;
}

static void blur_rgb24(unsigned char *rgb, int width, int height)
{
    unsigned char *tmp = malloc((size_t)width * height * 3);
    if (!tmp) {
        fprintf(stderr, "blur_rgb24: malloc failed: %s\n", strerror(errno));
        return;
    }
    memcpy(tmp, rgb, (size_t)width * height * 3);

    for (int i = 1; i < height - 1; i++) {
        for (int j = 1; j < width - 1; j++) {
            int r = 0, g = 0, b = 0;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    r += tmp[(i + di) * width * 3 + (j + dj) * 3 + 0];
                    g += tmp[(i + di) * width * 3 + (j + dj) * 3 + 1];
                    b += tmp[(i + di) * width * 3 + (j + dj) * 3 + 2];
                }
            }
            rgb[i * width * 3 + j * 3 + 0] = (unsigned char)(r / 9);
            rgb[i * width * 3 + j * 3 + 1] = (unsigned char)(g / 9);
            rgb[i * width * 3 + j * 3 + 2] = (unsigned char)(b / 9);
        }
    }
    free(tmp);
}

static int write_jpeg(const unsigned char *rgb, int width, int height,
                      const char *filename)
{
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr       jerr;
    FILE                       *outfile = NULL;
    unsigned char              *row_pointer[1];
    int                         row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "write_jpeg: fopen(%s): %s\n", filename, strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width      = width;
    cinfo.image_height     = height;
    cinfo.input_components = 3;
    cinfo.in_color_space   = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;
    row_pointer[0] = rgb;
    while (cinfo.next_scanline < cinfo.image_height) {
        if (jpeg_write_scanlines(&cinfo, row_pointer, 1) != 1) {
            fprintf(stderr, "write_jpeg: jpeg_write_scanlines failed\n");
            jpeg_destroy_compress(&cinfo);
            fclose(outfile);
            return -1;
        }
        row_pointer[0] += row_stride;
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(outfile);
    return 0;
}

int main(void)
{
    int                fd = -1;
    struct buffer     *buffers = NULL;
    unsigned int       n_buffers = 0;
    unsigned char     *rgb = NULL;
    unsigned char     *yuyv = NULL;
    int                ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP: %s\n", strerror(errno));
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = FRAME_WIDTH;
    fmt.fmt.pix.height      = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT: %s\n", strerror(errno));
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count  = 4;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS: %s\n", strerror(errno));
        goto cleanup;
    }
    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "calloc buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = n_buffers;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QUERYBUF(%u): %s\n", buf.index, strerror(errno));
            goto cleanup;
        }
        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start  = mmap(NULL, buf.length,
                                         PROT_READ | PROT_WRITE,
                                         MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers].start == MAP_FAILED) {
            fprintf(stderr, "mmap(%u): %s\n", buf.index, strerror(errno));
            buffers[n_buffers].start = NULL;
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QBUF(%u): %s\n", buf.index, strerror(errno));
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON: %s\n", strerror(errno));
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec  = FRAME_TIMEOUT_SEC;
    tv.tv_usec = 0;

    int rv = select(fd + 1, &fds, NULL, NULL, &tv);
    if (rv == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "select interrupted by signal\n");
        } else {
            fprintf(stderr, "select: %s\n", strerror(errno));
        }
        goto streamoff;
    }
    if (rv == 0) {
        fprintf(stderr, "select timeout: no frame captured\n");
        goto streamoff;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF: %s\n", strerror(errno));
        goto streamoff;
    }

    yuyv = malloc((size_t)FRAME_WIDTH * FRAME_HEIGHT * 2);
    if (!yuyv) {
        fprintf(stderr, "malloc yuyv: %s\n", strerror(errno));
        goto streamoff;
    }
    memcpy(yuyv, buffers[buf.index].start, (size_t)FRAME_WIDTH * FRAME_HEIGHT * 2);

    rgb = malloc((size_t)FRAME_WIDTH * FRAME_HEIGHT * 3);
    if (!rgb) {
        fprintf(stderr, "malloc rgb: %s\n", strerror(errno));
        goto streamoff;
    }
    yuyv_to_rgb24(yuyv, rgb, FRAME_WIDTH, FRAME_HEIGHT);
    blur_rgb24(rgb, FRAME_WIDTH, FRAME_HEIGHT);

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char filename[64];
    if (t) {
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", t);
    } else {
        snprintf(filename, sizeof(filename), "capture_unknown.jpg");
    }

    if (write_jpeg(rgb, FRAME_WIDTH, FRAME_HEIGHT, filename) == 0) {
        printf("Saved %s\n", filename);
        ret = EXIT_SUCCESS;
    } else {
        fprintf(stderr, "Failed to write JPEG\n");
    }

streamoff:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF: %s\n", strerror(errno));
    }

cleanup:
    if (rgb) free(rgb);
    if (yuyv) free(yuyv);
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }
    if (fd >= 0) close(fd);
    return ret;
}

