/*
 * v4l2_capabilities.c
 *
 * Prints V4L2 capabilities of /dev/video0 on a Raspberry Pi with the
 * V4L2 subsystem active.  Uses the standard Linux V4L2 ioctls.
 *
 * Build:  gcc -O2 -Wall -Wextra -o v4l2_capabilities v4l2_capabilities.c
 * Run:    ./v4l2_capabilities
 */

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/videodev2.h>
#include <sys/ioctl.h>

#define DEVICE_NAME "/dev/video0"

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

static void print_fourcc(unsigned int pixelformat)
{
    /* V4L2_PIX_FMT_RGB24 is 0x32315250 on little-endian ARM, but the
     * fourcc is typically printed as "RGB24".  We reverse the bytes
     * so the ASCII order matches the numeric value on big-endian hosts. */
    unsigned char a = (pixelformat     ) & 0xFF;
    unsigned char b = (pixelformat >>  8) & 0xFF;
    unsigned char c = (pixelformat >> 16) & 0xFF;
    unsigned char d = (pixelformat >> 24) & 0xFF;
    printf("'%c%c%c%c' (0x%08X)", a, b, c, d, pixelformat);
}

static void print_framerate(unsigned int numerator, unsigned int denominator)
{
    if (denominator == 0)
        printf("?");
    else
        printf("%u/%u = %.2f", numerator, denominator,
               (double)numerator / denominator);
}

/* ------------------------------------------------------------------ */
/* V4L2 ioctls                                                         */
/* ------------------------------------------------------------------ */

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

/* ------------------------------------------------------------------ */
/* Capability query                                                    */
/* ------------------------------------------------------------------ */

static int query_capabilities(int fd, struct v4l2_capability *cap)
{
    memset(cap, 0, sizeof(*cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Frame size enumeration                                              */
/* ------------------------------------------------------------------ */

static int enumerate_frame_sizes(int fd)
{
    struct v4l2_frmsizeenum frmsize;
    unsigned int pixelformat = V4L2_PIX_FMT_YUYV; /* any 8-bit format */
    unsigned int i = 0;

    printf("\n=== Supported Frame Sizes ===\n");

    for (;;) {
        memset(&frmsize, 0, sizeof(frmsize));
        frmsize.index = i++;
        frmsize.pixel_format = pixelformat;

        if (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == -1) {
            if (errno == EINVAL)
                break;          /* no more frame sizes for this format */
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n",
                    strerror(errno));
            return -1;
        }

        switch (frmsize.type) {
        case V4L2_FRMSIZE_TYPE_DISCRETE:
            printf("  %u x %u", frmsize.discrete.width,
                   frmsize.discrete.height);
            break;
        case V4L2_FRMSIZE_TYPE_STEPWISE:
            printf("  %u-%u, step %u", frmsize.stepwise.min_width,
                   frmsize.stepwise.max_width, frmsize.stepwise.step_width);
            break;
        case V4L2_FRMSIZE_TYPE_CONTINUOUS:
            printf("  %u-%u", frmsize.stepwise.min_width,
                   frmsize.stepwise.max_width);
            break;
        default:
            printf("  (unknown type %u)", frmsize.type);
            break;
        }

        printf("  ");
        print_fourcc(frmsize.pixel_format);
        printf("\n");
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Frame interval enumeration                                          */
/* ------------------------------------------------------------------ */

static int enumerate_frame_intervals(int fd)
{
    struct v4l2_frmivalenum frmival;
    unsigned int pixelformat = V4L2_PIX_FMT_YUYV;
    unsigned int i = 0;

    printf("\n=== Supported Frame Intervals ===\n");

    for (;;) {
        memset(&frmival, 0, sizeof(frmival));
        frmival.index = i++;
        frmival.pixel_format = pixelformat;
        frmival.width  = 640;
        frmival.height = 480;

        if (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == -1) {
            if (errno == EINVAL)
                break;          /* no more intervals for this size/format */
            fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n",
                    strerror(errno));
            return -1;
        }

        switch (frmival.type) {
        case V4L2_FRMIVAL_TYPE_DISCRETE:
            printf("  %u x %u  ", frmival.discrete.width,
                   frmival.discrete.height);
            print_framerate(frmival.discrete.numerator,
                            frmival.discrete.denominator);
            printf(" fps\n");
            break;
        case V4L2_FRMIVAL_TYPE_STEPWISE:
            printf("  %u x %u  %u/%u-%u/%u  step %u/%u\n",
                   frmival.stepwise.width, frmival.stepwise.height,
                   frmival.stepwise.min.numerator,
                   frmival.stepwise.min.denominator,
                   frmival.stepwise.max.numerator,
                   frmival.stepwise.max.denominator,
                   frmival.stepwise.step.numerator,
                   frmival.stepwise.step.denominator);
            break;
        case V4L2_FRMIVAL_TYPE_CONTINUOUS:
            printf("  %u x %u  %u/%u-%u/%u\n",
                   frmival.stepwise.width, frmival.stepwise.height,
                   frmival.stepwise.min.numerator,
                   frmival.stepwise.min.denominator,
                   frmival.stepwise.max.numerator,
                   frmival.stepwise.max.denominator);
            break;
        default:
            printf("  (unknown type %u)\n", frmival.type);
            break;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Autofocus query                                                     */
/* ------------------------------------------------------------------ */

static int query_autofocus(int fd)
{
    struct v4l2_queryctrl queryctrl;

    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (xioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == -1) {
        if (errno == EINVAL) {
            printf("\nAutofocus: NOT SUPPORTED\n");
            return 0;
        }
        fprintf(stderr, "VIDIOC_QUERYCTRL failed: %s\n", strerror(errno));
        return -1;
    }

    printf("\nAutofocus: %s (default %d)\n",
           queryctrl.name, queryctrl.default_value);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    int rc = EXIT_SUCCESS;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (query_capabilities(fd, &cap) == -1) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Device: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus info: %s\n", cap.bus_info);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (enumerate_frame_sizes(fd) == -1) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (enumerate_frame_intervals(fd) == -1) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (query_autofocus(fd) == -1) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("\n");

cleanup:
    if (fd != -1)
        close(fd);
    return rc;
}

