#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define PWM_FREQUENCY    50
#define PULSE_WIDTH_MIN  1000
#define PULSE_WIDTH_MAX  2000
#define PULSE_WIDTH_CENTER 1500
#define STEP_SIZE        10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_button(int pin) {
    return gpioRead(pin);
}

static int set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < PULSE_WIDTH_MIN) pulse_width = PULSE_WIDTH_MIN;
    if (pulse_width > PULSE_WIDTH_MAX) pulse_width = PULSE_WIDTH_MAX;
    return gpioServo(pin, pulse_width);
}

int main(void) {
    int pan_position = PULSE_WIDTH_CENTER;
    int tilt_position = PULSE_WIDTH_CENTER;

