#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <cjson/cJSON.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define JPEG_QUALITY 85
#define HTTP_TIMEOUT_MS 10000
#define HTTP_RETRIES 3
#define HTTP_RETRY_DELAY_MS 1000

static volatile sig_atomic_t g_running = 1;
static int g_http_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "raspistill -o %s -q %d -e jpg -t 1 2>/dev/null",
                       filename, JPEG_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: filename too long for raspistill command\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspistill failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }
    size_t pos = strlen(buf);
    int ret = snprintf(buf + pos, len - pos, ".%06ldZ", ts.tv_nsec / 1000);
    if (ret < 0 || (size_t)ret >= len - pos) {
        fprintf(stderr, "Error: timestamp buffer too small\n");
        return -1;
    }
    return 0;
}

static cJSON *create_json_payload(const char *filename, const char *timestamp,
                                  int motion_status, int gpio_pin) {
    cJSON *root = cJSON_CreateObject();
    if (!root) return NULL;
    if (cJSON_AddStringToObject(root, "filename", filename) == NULL ||
        cJSON_AddStringToObject(root, "timestamp", timestamp) == NULL ||
        cJSON_AddNumberToObject(root, "motion_status", motion_status) == NULL ||
        cJSON_AddNumberToObject(root, "gpio_pin", gpio_pin) == NULL) {
        cJSON_Delete(root);
        return NULL;
    }
    return root;
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents;
    (void)userp;
    return size * nmemb;
}

static int post_data(const char *url, const char *json_string, const char *filename) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: multipart/form-data");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, HTTP_TIMEOUT_MS);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT_MS, HTTP_TIMEOUT_MS);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    CURLcode res = curl_easy_perform(curl);
    curl_slist_free_all(headers);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    curl_easy_cleanup(curl);
    if (http_code < 200 || http_code >= 300) {
        fprintf(stderr, "Error: HTTP response code %ld\n", http_code);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }
    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", PIR_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d) failed\n", PIR_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

static int initialize_http(void) {
    if (g_http_initialized) return 0;
    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init() failed\n");
        return -1;
    }
    g_http_initialized = 1;
    return 0;
}

static void cleanup_http(void) {
    if (!g_http_initialized) return;
    curl_global_cleanup();
    g_http_initialized = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: invalid port %s\n", argv[2]);
        return EXIT_FAILURE;
    }
    if (initialize_http() != 0) return EXIT_FAILURE;
    if (initialize_gpio() != 0) {
        cleanup_http();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup_gpio();
        cleanup_http();
        return EXIT_FAILURE;
    }
    if (ensure_directory("motion_captures") != 0) {
        cleanup_gpio();
        cleanup_http();
        return EXIT_FAILURE;
    }
    char http_url[256];
    int ret = snprintf(http_url, sizeof(http_url), "http://%s:%d/upload",
                       server_ip, server_port);
    if (ret < 0 || (size_t)ret >= sizeof(http_url)) {
        fprintf(stderr, "Error: URL too long\n");
        cleanup_gpio();
        cleanup_http();
        return EXIT_FAILURE;
    }
    printf("Monitoring PIR on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);
    while (g_running) {
        int motion = gpioRead(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", PIR_GPIO);
            break;
        }
        if (motion == 1) {
            char timestamp[40];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
                break;
            }
            char filename[128];
            ret = snprintf(filename, sizeof(filename), "motion_captures/motion_%s.jpg",
                           timestamp);
            if (ret < 0 || (size_t)ret >= sizeof(filename)) {
                fprintf(stderr, "Error: filename buffer too small\n");
                break;
            }
            if (capture_image(filename) == 0) {
                cJSON *payload = create_json_payload(filename, timestamp, 1, PIR_GPIO);
                if (payload) {
                    char *json_string = cJSON_PrintUnformatted(payload);
                    if (json_string) {
                        int post_ok = 0;
                        for (int attempt = 0; attempt < HTTP_RETRIES && g_running; attempt++) {
                            if (post_data(http_url, json_string, filename) == 0) {
                                post_ok = 1;
                                break;
                            }
                            if (attempt < HTTP_RETRIES - 1) {
                                fprintf(stderr, "Retrying in %d ms...\n", HTTP_RETRY_DELAY_MS);
                                gpioDelay(HTTP_RETRY_DELAY_MS * 1000);
                            }
                        }
                        if (!post_ok) {
                            fprintf(stderr, "Error: failed to post data after %d attempts\n",
                                    HTTP_RETRIES);
                        }
                        free(json_string);
                    } else {
                        fprintf(stderr, "Error: cJSON_PrintUnformatted() failed\n");
                    }
                    cJSON_Delete(payload);
                } else {
                    fprintf(stderr, "Error: create_json_payload() failed\n");
                }
            }
            gpioDelay(DEBOUNCE_SEC * 1000000);
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    cleanup_gpio();
    cleanup_http();
    return EXIT_SUCCESS;
}

