    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", PIR_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d) failed\n", PIR_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

static int initialize_http(void) {
    if (g_http_initialized) return 0;
    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init() failed\n");
        return -1;
    }
    g_http_initialized = 1;
    return 0;
}

static void cleanup_http(void) {
    if (!g_http_initialized) return;
    curl_global_cleanup();
    g_http_initialized = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: invalid port %s\n", argv[2]);
        return EXIT_FAILURE;
    }
    if (initialize_http() != 0) return EXIT_FAILURE;
    if (initialize_gpio() != 0) {
        cleanup_http();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup_gpio();
        cleanup_http();
        return EXIT_FAILURE;
    }
    if (ensure_directory("motion_captures") != 0) {
        cleanup_gpio();
        cleanup_http();
        return EXIT_FAILURE;
    }
    char http_url[256];
    int ret = snprintf(http_url, sizeof(http_url), "http://%s:%d/upload",
                       server_ip, server_port);
    if (ret < 0 || (size_t)ret >= sizeof(http_url)) {
        fprintf(stderr, "Error: URL too long\n");
        cleanup_gpio();
        cleanup_http();
        return EXIT_FAILURE;
    }
    printf("Monitoring PIR on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);
    while (g_running) {
        int motion = gpioRead(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", PIR_GPIO);
            break;
        }
        if (motion == 1) {
            char timestamp[40];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
                break;
            }
            char filename[128];
            ret = snprintf(filename, sizeof(filename), "motion_captures/motion_%s.jpg",
                           timestamp);
            if (ret < 0 || (size_t)ret >= sizeof(filename)) {
                fprintf(stderr, "Error: filename buffer too small\n");
                break;
            }
            if (capture_image(filename) == 0) {
                cJSON *payload = create_json_payload(filename, timestamp, 1, PIR_GPIO);
                if (payload) {
                    char *json_string = cJSON_PrintUnformatted(payload);
                    if (json_string) {
                        int post_ok = 0;
                        for (int attempt = 0; attempt < HTTP_RETRIES && g_running; attempt++) {
                            if (post_data(http_url, json_string, filename) == 0) {
                                post_ok = 1;
                                break;
                            }
                            if (attempt < HTTP_RETRIES - 1) {
                                fprintf(stderr, "Retrying in %d ms...\n", HTTP_RETRY_DELAY_MS);
                                gpioDelay(HTTP_RETRY_DELAY_MS * 1000);
                            }
                        }
                        if (!post_ok) {
                            fprintf(stderr, "Error: failed to post data after %d attempts\n",
                                    HTTP_RETRIES);
                        }
                        free(json_string);
                    } else {
                        fprintf(stderr, "Error: cJSON_PrintUnformatted() failed\n");
                    }
                    cJSON_Delete(payload);
                } else {
                    fprintf(stderr, "Error: create_json_payload() failed\n");
                }
            }
            gpioDelay(DEBOUNCE_SEC * 1000000);
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    cleanup_gpio();
    cleanup_http();
    return EXIT_SUCCESS;
}

