#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define PIR_GPIO_LINE 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define CAPTURE_TIMEOUT_MS 2000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s: %s\n", ts, message);
    } else {
        fprintf(fp, "(unknown time): %s\n", message);
    }
    fclose(fp);
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "%s exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_image(void) {
    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        log_message("localtime_r failed");
        return -1;
    }
    char filename[128];
    char command[256];
    char ts[32];
    strftime(ts, sizeof(ts), "%Y%m%d_%H%M%S", &tm_info);
    snprintf(filename, sizeof(filename), "%s/%s_%03ld.jpg", IMAGE_DIR, ts, (long)(t % 1000));
    snprintf(command, sizeof(command),
             "raspistill -o '%s' -w 640 -h 480 -q 85 --timeout %d --nopreview",
             filename, CAPTURE_TIMEOUT_MS);
    int status = system(command);
    if (status == -1) {
        log_message("system() failed to launch raspistill");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        char msg[256];
        snprintf(msg, sizeof(msg), "Image captured: %s", filename);
        log_message(msg);
        return 0;
    }
    if (WIFEXITED(status)) {
        char msg[256];
        snprintf(msg, sizeof(msg), "raspistill exited with status %d", WEXITSTATUS(status));
        log_message(msg);
    } else if (WIFSIGNALED(status)) {
        char msg[256];
        snprintf(msg, sizeof(msg), "raspistill killed by signal %d", WTERMSIG(status));
        log_message(msg);
    } else {
        log_message("raspistill terminated abnormally");
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    if (ensure_directory(IMAGE_DIR) != 0) {
        fprintf(stderr, "Cannot create or access %s\n", IMAGE_DIR);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_message("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        perror("gpiod_chip_get_line");
        log_message("Failed to get GPIO line 17");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "pir_motion") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        log_message("Failed to request falling edge events on GPIO17");
        goto cleanup;
    }

    printf("Motion detection started on GPIO17. Press Ctrl+C to exit.\n");
    log_message("Motion detection started");

    while (program_running) {
        struct timespec ts = { 0, 100 * 1000 * 1000 };
        int ev = gpiod_line_event_wait(pir_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            log_message("Error waiting for GPIO event");
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(pir_line, &event) < 0) {
            perror("gpiod_line_event_read");
            log_message("Error reading GPIO event");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        struct timespec debounce = { 0, DEBOUNCE_MS * 1000 * 1000 };
        nanosleep(&debounce, NULL);

        int val = gpiod_line_get_value(pir_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            log_message("Error reading GPIO value after debounce");
            continue;
        }
        if (val == 0) {
            capture_image();
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    log_message("Motion detection stopped");
    return ret;
}

