/*
 * Raspberry Pi UVC camera capture: YUYV -> cropped YUYV (200x150).
 *
 * Build:  gcc -O2 -Wall -Wextra -o uvc_crop uvc_crop.c
 * Run:    ./uvc_crop
 *
 * Uses the V4L2 ioctl interface (no deprecated wiringPi).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME      "/dev/video0"
#define OUTPUT_FILE      "cropped.yuv"
#define CAPTURE_WIDTH    640
#define CAPTURE_HEIGHT   480
#define CROP_WIDTH       200
#define CROP_HEIGHT      150
#define FRAME_TIMEOUT_S  2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void)
{
    int fd = -1;
    void *buffer = NULL;
    size_t buffer_size = 0;
    FILE *out = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* ---- open device ---- */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        goto cleanup;
    }

    /* ---- query capabilities ---- */
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto cleanup;
    }

    /* ---- set format ---- */
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = CAPTURE_WIDTH;
    fmt.fmt.pix.height      = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device did not accept YUYV\n");
        goto cleanup;
    }
    if (fmt.fmt.pix.width != CAPTURE_WIDTH || fmt.fmt.pix.height != CAPTURE_HEIGHT) {
        fprintf(stderr, "Warning: format changed to %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    /* ---- request single-planar buffer ---- */
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count  = 1;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    /* ---- query and mmap buffer ---- */
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index  = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }
    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    /* ---- queue buffer ---- */
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index  = 0;
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    /* ---- start streaming ---- */
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    /* ---- wait for a frame with select() ---- */
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    struct timeval tv;
    tv.tv_sec  = FRAME_TIMEOUT_S;
    tv.tv_usec = 0;
    int sel = select(fd + 1, &fds, NULL, NULL, &tv);
    if (sel < 0) {
        if (errno == EINTR) {
            if (g_stop) {
                fprintf(stderr, "Interrupted by signal\n");
                goto cleanup;
            }
            perror("select");
            goto cleanup;
        }
        perror("select");
        goto cleanup;
    }
    if (sel == 0) {
        fprintf(stderr, "Timeout: no frame captured\n");
        goto cleanup;
    }

    /* ---- dequeue frame ---- */
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    /* ---- validate frame dimensions ---- */
    if (buf.bytesused < (size_t)(CAPTURE_WIDTH * CAPTURE_HEIGHT * 2)) {
        fprintf(stderr, "Frame too small: %u bytes\n", buf.bytesused);
        goto cleanup;
    }

    /* ---- crop YUYV ---- */
    size_t out_size = (size_t)CROP_WIDTH * CROP_HEIGHT * 2;
    unsigned char *out_buf = malloc(out_size);
    if (!out_buf) {
        perror("malloc");
        goto cleanup;
    }

    const unsigned char *src = (const unsigned char *)buffer;
    for (int y = 0; y < CROP_HEIGHT; y++) {
        int src_y = y + (CAPTURE_HEIGHT - CROP_HEIGHT) / 2;
        size_t row_offset = (size_t)src_y * CAPTURE_WIDTH * 2;
        memcpy(out_buf + (size_t)y * CROP_WIDTH * 2,
               src + row_offset + (CAPTURE_WIDTH - CROP_WIDTH) / 2 * 2,
               (size_t)CROP_WIDTH * 2);
    }

    /* ---- write YUYV ---- */
    out = fopen(OUTPUT_FILE, "wb");
    if (!out) {
        perror("fopen(" OUTPUT_FILE ")");
        goto cleanup;
    }
    size_t written = fwrite(out_buf, 1, out_size, out);
    if (written != out_size) {
        perror("fwrite");
        goto cleanup;
    }
    if (fflush(out) != 0) {
        perror("fflush");
        goto cleanup;
    }

    printf("Cropped %dx%d YUYV frame written to %s\n", CROP_WIDTH, CROP_HEIGHT, OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (out) {
        fclose(out);
    }
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, buffer_size);
    }
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
        close(fd);
    }
    if (out_buf) {
        free(out_buf);
    }
    return ret;
}

