/*
 * Servo control via arrow keys on a Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Pan  servo signal -> GPIO17 (BCM)
 *   Tilt servo signal -> GPIO18 (BCM)
 *   Both servos: V+ -> 5 V, GND -> GND (common ground with Pi).
 *
 * SG90 servos: ~50 Hz PWM, pulse width 1 ms (0°) to 2 ms (180°).
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_control servo_control.c -lpigpio -lrt
 * Run:    sudo ./servo_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    17
#define TILT_SERVO_PIN   18
#define SERVO_FREQ_HZ    50          /* 50 Hz hardware PWM -> 20 ms period */
#define SERVO_PERIOD_US  20000       /* 20 ms period in microseconds */
#define MIN_PULSE_US     1000        /* 1 ms -> 0°   */
#define MAX_PULSE_US     2000        /* 2 ms -> 180° */
#define NEUTRAL_ANGLE    90
#define STEP_DEGREES     5
#define DELAY_MS         100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Convert a 0-180° angle to a 50 Hz PWM pulse width in microseconds.
 * Returns 0 on success, -1 on out-of-range error.
 */
static int angle_to_pulse_us(int angle, int *pulse_us)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: angle %d out of range (0-180).\n", angle);
        return -1;
    }
    *pulse_us = MIN_PULSE_US +
                (int)((long)(angle) * (MAX_PULSE_US - MIN_PULSE_US) / 180);
    return 0;
}

/*
 * Set a servo to the given angle.
 * Returns 0 on success, -1 on PWM write failure.
 */
static int set_servo_angle(int pin, int angle)
{
    int pulse_us;
    if (angle_to_pulse_us(angle, &pulse_us) != 0)
        return -1;

    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse %d us).\n",
                pin, pulse_us);
        return -1;
    }
    return 0;
}

/*
 * Move a servo by `step` degrees in the given direction.
 * direction: +1 = forward (increase angle), -1 = reverse (decrease angle).
 * Returns 0 on success, -1 on error.
 */
static int move_servo(int pin, int step, int direction)
{
    static int pan_angle  = NEUTRAL_ANGLE;
    static int tilt_angle = NEUTRAL_ANGLE;
    int *angle_ptr;

    if (pin == PAN_SERVO_PIN)
        angle_ptr = &pan_angle;
    else if (pin == TILT_SERVO_PIN)
        angle_ptr = &tilt_angle;
    else {
        fprintf(stderr, "Error: invalid servo pin %d.\n", pin);
        return -1;
    }

    *angle_ptr += step * direction;

    if (*angle_ptr < 0) {
        fprintf(stderr, "Warning: angle %d on pin %d clamped to 0.\n",
                *angle_ptr, pin);
        *angle_ptr = 0;
    } else if (*angle_ptr > 180) {
        fprintf(stderr, "Warning: angle %d on pin %d clamped to 180.\n",
                *angle_ptr, pin);
        *angle_ptr = 180;
    }

    return set_servo_angle(pin, *angle_ptr);
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure servo pins as output --- */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan pin %d.\n",
                PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt pin %d.\n",
                TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start both servos at neutral 90° --- */
    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control ready.\n");
    printf("Pan  servo: GPIO%d | Tilt servo: GPIO%d | 50 Hz PWM\n",
           PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Arrows: pan left/right, tilt up/down.  Press 'q' to quit.\n");
    fflush(stdout);

    /* --- Main command loop --- */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            /* EOF typically means stdin closed (e.g. pipe break). */
            break;
        }

        switch (c) {
        case 'a': /* left  -> pan  left  */
        case 'A':
            if (move_servo(PAN_SERVO_PIN, STEP_DEGREES, -1) != 0)
                fprintf(stderr, "Error: pan left failed.\n");
            break;
        case 'd': /* right -> pan  right */
        case 'D':
            if (move_servo(PAN_SERVO_PIN, STEP_DEGREES, +1) != 0)
                fprintf(stderr, "Error: pan right failed.\n");
            break;
        case 'w': /* up    -> tilt up   */
        case 'W':
            if (move_servo(TILT_SERVO_PIN, STEP_DEGREES, +1) != 0)
                fprintf(stderr, "Error: tilt up failed.\n");
            break;
        case 's': /* down  -> tilt down */
        case 'S':
            if (move_servo(TILT_SERVO_PIN, STEP_DEGREES, -1) != 0)
                fprintf(stderr, "Error: tilt down failed.\n");
            break;
        case 'q':
        case 'Q':
            /* Clean shutdown requested by user. */
            g_running = 0;
            break;
        case '\n':
        case '\r':
        case '\t':
        case ' ':
            /* Ignore whitespace. */
            break;
        default:
            printf("Unknown command '%c'.\n", c);
            break;
        }

        if (g_running)
            usleep(DELAY_MS * 1000);
    }

    /* --- Clean shutdown: return servos to neutral and release pigpio --- */
    printf("\nShutting down...\n");
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

