        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", OLED_I2C_ADDR, strerror(errno));
        close(oled_fd);
        oled_fd = -1;
        return -1;
    }
    oled_command(0xAE);
    oled_command(0xD5); oled_command(0x80);
    oled_command(0xA8); oled_command(0x3F);
    oled_command(0xD3); oled_command(0x00);
    oled_command(0x40);
    oled_command(0x8D); oled_command(0x14);
    oled_command(0x20); oled_command(0x00);
    oled_command(0xA1);
    oled_command(0xC8);
    oled_command(0xDA); oled_command(0x12);
    oled_command(0x81); oled_command(0xCF);
    oled_command(0xD9); oled_command(0xF1);
    oled_command(0xDB); oled_command(0x40);
    oled_command(0xA4);
    oled_command(0xA6);
    oled_command(0xAF);
    return 0;
}

static void oled_clear(void) {
    uint8_t blank[OLED_WIDTH];
    memset(blank, 0, OLED_WIDTH);
    for (int page = 0; page < OLED_HEIGHT / 8; page++) {
        oled_command(0xB0 + page);
        oled_command(0x00);
        oled_command(0x10);
        oled_data(blank, OLED_WIDTH);
    }
}

static void oled_print_string(int x, int y, const char *str) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) return;
    oled_command(0xB0 + (y / 8));
    oled_command(0x00 + (x & 0x0F));
    oled_command(0x10 + ((x >> 4) & 0x0F));
    uint8_t buf[128];
    int idx = 0;
    while (*str && idx < 127) {
        unsigned char c = (unsigned char)*str;
        if (c < 32 || c > 126) c = '?';
        for (int i = 0; i < 5; i++) {
            buf[idx++] = font5x7[c][i];
        }
        buf[idx++] = 0x00;
        str++;
    }
    if (idx > 0) oled_data(buf, idx);
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open CPU temp: %s\n", strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to parse CPU temp\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static float read_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
        return -1.0f;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);
    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_time = idle + iowait;
    float cpu_usage = 0.0f;
    if (prev_total != 0) {
        unsigned long long totald = total - prev_total;
        unsigned long long idled = idle_time - prev_idle;
        cpu_usage = (float)(totald - idled) / totald * 100.0f;
    }
    prev_idle = idle_time;
    prev_total = total;
    return cpu_usage;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (oled_init() != 0) {
        return 1;
    }
    oled_clear();

    while (running) {
        int temp = read_cpu_temp();
        float usage = read_cpu_usage();

        char temp_str[32], usage_str[32];
        if (temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: ERR");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %d.%02dC", temp / 1000, (temp % 1000) / 10);
        }
        if (usage < 0.0f) {
            snprintf(usage_str, sizeof(usage_str), "Usage: ERR");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", usage);
        }

        oled_clear();
        oled_print_string(0, 0, temp_str);
        oled_print_string(0, 10, usage_str);

        sleep(1);
    }

    oled_clear();
    if (oled_fd >= 0) {
        close(oled_fd);
        oled_fd = -1;
    }
    return 0;
}

