#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27

#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80

#define LCD_DISPLAYON 0x04
#define LCD_CURSOROFF 0x00
#define LCD_BLINKOFF 0x00

#define LCD_2LINE 0x08
#define LCD_4BITMODE 0x00
#define LCD_5x8DOTS 0x00

#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTDECREMENT 0x00

#define LCD_RS 0x01
#define LCD_RW 0x02
#define LCD_EN 0x04
#define LCD_BL 0x08
#define LCD_D4 0x10
#define LCD_D5 0x20
#define LCD_D6 0x40
#define LCD_D7 0x80

#define FLOW_SCALING_FACTOR 0.001
#define FLOW_TIME_INTERVAL_US 1000000
#define LCD_UPDATE_INTERVAL_S 10

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    if (i2cWriteByte(i2c_handle, data | LCD_EN | LCD_BL) < 0) {
        fprintf(stderr, "Error: I2C write failed during strobe\n");
    }
    gpioDelay(1);
    if (i2cWriteByte(i2c_handle, (data & ~LCD_EN) | LCD_BL) < 0) {
        fprintf(stderr, "Error: I2C write failed after strobe\n");
    }
    gpioDelay(50);
}

static void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0);
    int bits_low = mode | ((bits << 4) & 0xF0);
    lcd_strobe(bits_high);
    lcd_strobe(bits_low);
}

static void lcd_command(int cmd) {
    lcd_byte(cmd, 0x00);
    if (cmd == LCD_CLEARDISPLAY || cmd == LCD_RETURNHOME) {
        gpioDelay(2000);
    }
}

static void lcd_data(int data) {
    lcd_byte(data, LCD_RS);
}

static void lcd_string(const char *s) {
    while (*s) {
        lcd_data(*s++);
    }
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_byte(0x33, 0);
    lcd_byte(0x32, 0);
    lcd_byte(0x28, 0);
    lcd_byte(0x0C, 0);
    lcd_byte(0x06, 0);
    lcd_byte(0x01, 0);
    gpioDelay(2000);
}

static void lcd_update(double flow_rate, double total_volume) {
    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/s", flow_rate);
    snprintf(line2, sizeof(line2), "Total: %.2f L", total_volume);

    lcd_command(LCD_CLEARDISPLAY);
    gpioDelay(2000);
    lcd_command(LCD_RETURNHOME);
    gpioDelay(2000);
    lcd_command(LCD_SETDDRAMADDR | 0x00);
    lcd_string(line1);
    lcd_command(LCD_SETDDRAMADDR | 0x40);
    lcd_string(line2);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (err=%d)\n", I2C_BUS, LCD_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();

    uint32_t last_tick = 0;
    double total_volume = 0.0;
    double last_flow_rate = 0.0;
    int last_state = 0;
    uint32_t last_lcd_update_time = 0;

    while (running) {
        uint32_t current_tick = gpioTick();
        int current_state = gpioRead(FLOW_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d\n", FLOW_SENSOR_GPIO);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                if (last_tick != 0) {
                    uint32_t pulse_width = current_tick - last_tick;
                    double volume_change = (double)pulse_width * FLOW_SCALING_FACTOR;
                    total_volume += volume_change;
                }
            }
            last_tick = current_tick;
            last_state = current_state;
        }

        if (current_tick - last_lcd_update_time >= LCD_UPDATE_INTERVAL_S * 1000000) {
            double flow_rate = 0.0;
            if (last_tick != 0) {
                uint32_t elapsed_us = current_tick - last_tick;
                if (elapsed_us > 0) {
                    flow_rate = (double)elapsed_us * FLOW_SCALING_FACTOR;
                }
            }
            lcd_update(flow_rate, total_volume);
            last_lcd_update_time = current_tick;
        }

        uint32_t elapsed_us = current_tick - last_tick;
        double flow_rate = (double)elapsed_us * FLOW_SCALING_FACTOR;

        printf("Flow Rate: %.2f L/s, Total Volume: %.2f L\n", flow_rate, total_volume);
        fflush(stdout);

        gpioDelay(100000);
    }

    if (i2c_handle >= 0) {
        lcd_command(LCD_CLEARDISPLAY);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

