/*
 * Raspberry Pi 4 Model B – Anemometer & Wind Vane Monitor
 *
 * Hardware:
 *   - Anemometer pulse on GPIO17 (BCM), rising edge interrupt
 *   - MCP3008 ADC on SPI0/CE0, channel 0, 1 MHz, mode 0
 *   - 16x2 LCD via PCF8574 backpack on I2C bus 1, address 0x27
 *
 * Build:
 *   gcc -O2 -Wall -o anemometer anemometer.c -lm
 *
 * Run:
 *   ./anemometer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define ANEMOMETER_GPIO      17          /* BCM pin for anemometer pulse */
#define SPI_CHANNEL          0           /* SPI0 CE0 */
#define SPI_SPEED            1000000     /* 1 MHz */
#define SPI_FLAGS            0           /* mode 0, active-low CE */
#define I2C_BUS              1
#define LCD_ADDR             0x27        /* PCF8574 backpack at 0x27 */

#define SAMPLE_WINDOW_US     500000      /* 500 ms per wind-speed sample */
#define SAMPLE_DELAY_US      500000      /* 500 ms between displays */
#define LCD_CLEAR_DELAY_US   3000        /* 3 ms for clear-screen command */
#define LCD_DATA_DELAY_US    100         /* 100 us between data bytes */
#define LCD_CMD_DELAY_US     1000        /* 1 ms between commands */
#define LCD_INIT_DELAY_US    50000       /* 50 ms after init */

#define WIND_DIR_THRESHOLD   10          /* ADC delta to trigger direction change */
#define MAX_STUCK_READINGS   10          /* consecutive stuck-value rejections */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static int g_last_adc = -1;
static int g_stuck_count = 0;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Anemometer ISR ------------------------------ */

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* ------------------------------- LCD helpers ----------------------------- */

/*
 * PCF8574 backpack bit layout (4-bit mode, N=1, D0..D3 = LCD data, RS=bit 0):
 *   RS  RW  E   D0  D1  D2  D3  LED  LED  LED  LED  LED  LED  LED  LED  LED
 *   0   0   1   x   x   x   x   x    x    x    x    x    x    x    x    x
 *   0   1   1   x   x   x   x   x    x    x    x    x    x    x    x    x
 *   1   0   1   x   x   x   x   x    x    x    x    x    x    x    x    x
 *   1   1   1   x   x   x   x   x    x    x    x    x    x    x    x    x
 *
 * E is active-high; RS = 0 for command, 1 for data.
 */

static void lcd_byte(int handle, uint8_t val, uint8_t rs)
{
    /*
     * pigpio I2C writeByteData / readByteData use the combined 8-bit
     * register/data protocol, so we write the data byte directly.
     * For the PCF8574 we need to control the RS line via the
     * PCF8574's control lines, so we use i2cWriteByteData with the
     * combined register/data byte.  We mask the upper nibble so
     * the PCF8574's control bits are preserved.
     */
    uint8_t data = val & 0x0F;          /* nibble low */
    uint8_t ctrl = (rs ? 0x01 : 0x00) | 0x08; /* RS=rs, E=1 */

    if (i2cWriteByteData(handle, data, ctrl) < 0) {
        fprintf(stderr, "i2cWriteByteData failed: %s\n", strerror(errno));
        return;
    }
    gpioDelay(LCD_DATA_DELAY_US);

    ctrl |= 0x04;                       /* E=0 */
    if (i2cWriteByteData(handle, data, ctrl) < 0) {
        fprintf(stderr, "i2cWriteByteData (E low) failed: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1);

    ctrl &= ~0x04;                      /* E=1 */
    if (i2cWriteByteData(handle, data, ctrl) < 0) {
        fprintf(stderr, "i2cWriteByteData (E high) failed: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1);

    ctrl &= ~0x04;                      /* E=0 */
    if (i2cWriteByteData(handle, data, ctrl) < 0) {
        fprintf(stderr, "i2cWriteByteData (E low) failed: %s\n", strerror(errno));
        return;
    }
    gpioDelay(1);
}

static void lcd_command(int handle, uint8_t cmd)
{
    lcd_byte(handle, cmd, 0);
    if (cmd == 0x01)
        gpioDelay(LCD_CLEAR_DELAY_US);
    else
        gpioDelay(LCD_CMD_DELAY_US);
}

static void lcd_data(int handle, uint8_t data)
{
    lcd_byte(handle, data, 1);
}

static void lcd_string(int handle, const char *s)
{
    while (*s)
        lcd_data(handle, (uint8_t)*s++);
}

static void lcd_clear(int handle)
{
    lcd_command(handle, 0x01);
}

static void lcd_set_cursor(int handle, int col, int row)
{
    uint8_t addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_command(handle, addr);
}

/* ------------------------------- MCP3008 --------------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] low 2 bits + rx[2] 8 bits    -> 10-bit result
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "spiXfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

/* ------------------------------- Wind speed ------------------------------ */

static double calculate_wind_speed(int pulses, uint32_t window_us)
{
    if (window_us == 0)
        return 0.0;
    return (double)pulses * 60000000.0 / (double)window_us;
}

/* ------------------------------- Wind direction -------------------------- */

static int read_wind_direction(int spi_handle)
{
    int adc = read_mcp3008(spi_handle, 0);
    if (adc < 0)
        return -1;

    if (g_last_adc >= 0) {
        int delta = abs(adc - g_last_adc);
        if (delta > WIND_DIR_THRESHOLD) {
            if (adc > g_last_adc)
                return 1;          /* right */
            else
                return -1;         /* left */
        }
    }
    g_last_adc = adc;
    return 0;
}

/* ------------------------------- Display --------------------------------- */

static void display_wind_data(int lcd_handle, double wind_speed, int direction)
{
    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Wind Speed: %.2f m/s", wind_speed);
    snprintf(line2, sizeof(line2), "Direction: %s",
             direction == 1 ? "Right" :
             direction == -1 ? "Left" : "Straight");

    lcd_clear(lcd_handle);
    lcd_set_cursor(lcd_handle, 0, 0);
    lcd_string(lcd_handle, line1);
    lcd_set_cursor(lcd_handle, 0, 1);
    lcd_string(lcd_handle, line2);
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    int spi_handle = -1;
    int lcd_handle = -1;
    int ret = EXIT_FAILURE;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Anemometer ISR ---- */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- SPI0 CE0 ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- I2C bus 1 ---- */
    lcd_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (lcd_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- LCD init ---- */
    lcd_command(lcd_handle, 0x33);
    lcd_command(lcd_handle, 0x32);
    lcd_command(lcd_handle, 0x28);       /* 2-line, 5x8 font */
    lcd_command(lcd_handle, 0x0C);       /* display on, cursor off */
    lcd_command(lcd_handle, 0x06);       /* entry mode: increment */
    lcd_clear(lcd_handle);

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Anemometer & Wind Vane Monitor running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint32_t start = gpioTick();
        uint32_t elapsed = 0;

        g_pulse_count = 0;
        g_stuck_count = 0;

        while (g_running && elapsed < SAMPLE_WINDOW_US) {
            uint32_t now = gpioTick();
            elapsed = now - start;
            gpioDelay(10000);            /* 10 ms poll */
        }

        if (!g_running)
            break;

        int pulses = g_pulse_count;
        double wind_speed = calculate_wind_speed(pulses, SAMPLE_WINDOW_US);

        int direction = read_wind_direction(spi_handle);
        if (direction == -1) {
            fprintf(stderr, "Warning: wind direction read failed\n");
            direction = 0;
        }

        display_wind_data(lcd_handle, wind_speed, direction);

        /* Sensor-absent heuristic: too many consecutive stuck readings */
        int adc = read_mcp3008(spi_handle, 0);
        if (adc < 0) {
            fprintf(stderr, "Warning: SPI/ADC communication failure\n");
        } else if (adc == 0 || adc == 1023) {
            g_stuck_count++;
            if (g_stuck_count >= MAX_STUCK_READINGS) {
                fprintf(stderr, "Warning: ADC stuck at %d for %d samples – sensor absent?\n",
                        adc, g_stuck_count);
            }
        } else {
            g_stuck_count = 0;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (lcd_handle >= 0) {
        lcd_clear(lcd_handle);
        i2cClose(lcd_handle);
    }
    if (spi_handle >= 0)
        spiClose(spi_handle);
    gpioTerminate();
    return ret;
}

