/*
 * Water Flow Monitor — Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - YF-S201 water flow sensor (pulse output) -> GPIO17 (BCM, physical pin 11)
 *   - LCD1602 on I2C bus 1, address 0x27 (7-segment display on physical pins 16-22)
 *
 * Build:
 *   gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLOW_SENSOR_GPIO      17          /* BCM pin for YF-S201 pulse output */
#define I2C_BUS               1           /* /dev/i2c-1 on RPi 3B+ */
#define LCD_ADDR              0x27        /* LCD1602 I2C address (A0->GND) */

#define FLOW_INTERVAL_SEC     1           /* measurement window */
#define ZERO_PULSE_THRESHOLD  5           /* consecutive zero windows before warning */
#define WARN_WINDOWS          30          /* ~5 min of zero-pulse warning */

/* LCD1602 HD44780 commands */
#define LCD_CLEARDISPLAY      0x01
#define LCD_RETURNHOME        0x02
#define LCD_ENTRYMODESET      0x04
#define LCD_DISPLAYCONTROL    0x08
#define LCD_FUNCTIONSET       0x20
#define LCD_SETDDRAMADDR      0x80

#define LCD_DISPLAYON         0x04
#define LCD_CURSOROFF         0x00
#define LCD_BLINKOFF          0x00

#define LCD_2LINE             0x08
#define LCD_4BITMODE          0x00
#define LCD_5x8DOTS           0x00

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static int                   g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata);
static int  lcd_write_nibble(uint8_t nibble);
static int  lcd_send_byte(uint8_t val, uint8_t mode);
static int  lcd_command(uint8_t cmd);
static int  lcd_data(uint8_t data);
static int  lcd_string(const char *s);
static int  lcd_clear(void);
static int  lcd_init(void);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Pulse counter ----------------------------- */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)tick; (void)userdata;
    if (level == 1) {
        g_pulse_count++;
    }
}

/* ----------------------------- LCD low-level helpers --------------------- */
static int lcd_write_nibble(uint8_t nibble)
{
    if (i2cWriteByte(g_i2c_handle, nibble) < 0) {
        return -1;
    }
    return 0;
}

static int lcd_send_byte(uint8_t val, uint8_t mode)
{
    uint8_t high = (val & 0xF0) | mode;
    uint8_t low  = ((val << 4) & 0xF0) | mode;

    /* HD44780 requires E high for > 300 ns; we drive E for 1 ms to be safe */
    if (lcd_write_nibble(high | 0x04) < 0) return -1;
    gpioDelay(1000);                       /* 1 ms */
    if (lcd_write_nibble(high & ~0x04) < 0) return -1;
    gpioDelay(1000);

    if (lcd_write_nibble(low | 0x04) < 0) return -1;
    gpioDelay(1000);
    if (lcd_write_nibble(low & ~0x04) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int lcd_command(uint8_t cmd)
{
    return lcd_send_byte(cmd, 0x00);
}

static int lcd_data(uint8_t data)
{
    return lcd_send_byte(data, 0x01);
}

static int lcd_string(const char *s)
{
    for (int i = 0; s[i] != '\0'; i++) {
        if (lcd_data((uint8_t)s[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

static int lcd_clear(void)
{
    if (lcd_command(LCD_CLEARDISPLAY) < 0) return -1;
    gpioDelay(2000);                       /* clear needs up to 1.52 ms */
    return 0;
}

static int lcd_init(void)
{
    /*
     * LCD1602 on I2C: HD44780 expects a 4-bit interface (3-wire SDA+SCL+VCC).
     * The pigpio i2cWriteByte() function sends a single byte on the bus, which
     * is interpreted as an 8-bit command by the HD44780 when in 4-bit mode.
     * We must therefore emulate the 4-bit interface by bit-banging the
     * 4 data pins (bit 3,2,1,0 of the byte) and the E line (bit 2 of the byte).
     *
     * We use the 4-bit interface initialization sequence:
     *   1. Send 0x33, then 0x32 — force 4-bit mode.
     *   2. Function set: 0x28 — 4-bit, 2 lines, 5x8 font.
     *   3. Display off.
     *   4. Clear display.
     *   5. Entry mode set: 0x06 — increment, no shift.
     */
    if (lcd_write_nibble(0x33) < 0) return -1;
    gpioDelay(5000);
    if (lcd_write_nibble(0x32) < 0) return -1;
    gpioDelay(5000);

    if (lcd_command(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS) < 0) return -1;
    if (lcd_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF) < 0) return -1;
    if (lcd_command(LCD_ENTRYMODESET | 0x06) < 0) return -1;
    if (lcd_clear() < 0) return -1;

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        lcd_clear();
        lcd_string("Shutting down...");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * YF-S201 module has an on-board pull-up; enable the internal pull-up
     * so the line is defined when the sensor is disconnected.
     */
    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", FLOW_SENSOR_GPIO);
    }

    /* --- I2C setup --- */
    g_i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
