        if (pulses == 0) {
            zero_pulse_count++;
            if (zero_pulse_count >= ZERO_PULSE_THRESHOLD) {
                warn_count++;
                if (warn_count >= WARN_WINDOWS) {
                    lcd_clear();
                    lcd_string("Warning: No pulses");
                    lcd_command(LCD_SETDDRAMADDR | 0x40);
                    lcd_string("Sensor absent?");
                    warn_count = 0;          /* reset to avoid repeated warnings */
                }
            }
        } else {
            zero_pulse_count = 0;
            warn_count = 0;
        }

