#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, int value) {
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        safe_write(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        safe_write(col_pins[i], 1);
    }
}

static void display_led(int row, int col) {
    if (safe_write(row_pins[row], 1) != 0) return;
    if (safe_write(col_pins[col], 0) != 0) return;
    gpioDelay(SCAN_DELAY_US);
    safe_write(row_pins[row], 0);
    safe_write(col_pins[col], 1);
}

static void display_pattern(const int pattern[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = 0; c < NUM_COLS; c++) {
            if (pattern[r][c]) {
                display_led(r, c);
            }
        }
    }
}

static void shift_left(int pattern[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = 0; c < NUM_COLS - 1; c++) {
            pattern[r][c] = pattern[r][c + 1];
        }
        pattern[r][NUM_COLS - 1] = 0;
    }
}

static void shift_right(int pattern[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = NUM_COLS - 1; c > 0; c--) {
            pattern[r][c] = pattern[r][c - 1];
        }
        pattern[r][0] = 0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_set_mode(col_pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    clear_matrix();

    int pattern1[NUM_ROWS][NUM_COLS] = {0};
    int pattern2[NUM_ROWS][NUM_COLS] = {0};

    pattern1[0][0] = 1;
    pattern2[7][7] = 1;

    while (running) {
        display_pattern(pattern1);
        shift_left(pattern1);

        display_pattern(pattern2);
        shift_right(pattern2);

        gpioDelay(50000);
    }

    clear_matrix();
    gpioTerminate();
    return EXIT_SUCCESS;
}

