/*
 * 8x8 common-anode LED matrix wave animation using libgpiod v2 API.
 *
 * Wiring (BCM numbering):
 *   Row anodes:  2, 3, 4, 17, 27, 22, 10, 9
 *   Column cathodes: 14, 15, 18, 23, 24, 25, 8, 7
 *
 * A column is lit when its cathode is LOW and all row anodes are HIGH.
 * The animation scans columns left-to-right, lighting LEDs row by row.
 *
 * Build:  gcc -O2 -Wall -Wextra -o matrix_wave matrix_wave.c -lgpiod
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define COL_DELAY_MS 150

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_rows(struct gpiod_line_bulk *bulk, int val)
{
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpiod_line_set_value(gpiod_line_bulk_get_line(bulk, i), val) < 0) {
            fprintf(stderr, "set_rows: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int set_cols(struct gpiod_line_bulk *bulk, int val)
{
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpiod_line_set_value(gpiod_line_bulk_get_line(bulk, i), val) < 0) {
            fprintf(stderr, "set_cols: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void delay_ms(unsigned int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk row_bulk;
    struct gpiod_line_bulk col_bulk;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_init(&row_bulk);
    gpiod_line_bulk_init(&col_bulk);

    for (int i = 0; i < NUM_ROWS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, row_pins[i]);
        if (!line) {
            fprintf(stderr, "get row line %u: %s\n", row_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&row_bulk, line);
    }

    for (int i = 0; i < NUM_COLS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, col_pins[i]);
        if (!line) {
            fprintf(stderr, "get col line %u: %s\n", col_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&col_bulk, line);
    }

    if (gpiod_line_request_bulk_output(&row_bulk, "matrix_wave", 0) < 0) {
        fprintf(stderr, "request row lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_bulk_output(&col_bulk, "matrix_wave", 1) < 0) {
        fprintf(stderr, "request col lines: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        if (set_rows(&row_bulk, 0) < 0) goto cleanup;
        if (set_cols(&col_bulk, 1) < 0) goto cleanup;

        for (int col = 0; col < NUM_COLS && g_running; col++) {
            if (gpiod_line_set_value(gpiod_line_bulk_get_line(&col_bulk, col), 0) < 0)
                goto cleanup;

            for (int row = 0; row < NUM_ROWS && g_running; row++) {
                if (gpiod_line_set_value(gpiod_line_bulk_get_line(&row_bulk, row), 1) < 0)
                    goto cleanup;
                delay_ms(1);
                if (gpiod_line_set_value(gpiod_line_bulk_get_line(&row_bulk, row), 0) < 0)
                    goto cleanup;
            }

            if (gpiod_line_set_value(gpiod_line_bulk_get_line(&col_bulk, col), 1) < 0)
                goto cleanup;

            delay_ms(COL_DELAY_MS);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (gpiod_line_bulk_num_lines(&row_bulk) > 0)
        gpiod_line_set_value_bulk(&row_bulk, 0);
    if (gpiod_line_bulk_num_lines(&col_bulk) > 0)
        gpiod_line_set_value_bulk(&col_bulk, 0);

    gpiod_line_release_bulk(&row_bulk);
    gpiod_line_release_bulk(&col_bulk);
    gpiod_chip_close(chip);

    return ret;
}

