/*
 * Raspberry Pi 3 Model B+ - VL53L3CX Multi-Target Time-of-Flight Sensor Reader
 *
 * Reads distance measurements from an STMicroelectronics VL53L3CX sensor
 * connected to I2C bus 1 (GPIO 2 = SDA, GPIO 3 = SCL).
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download to enable
 *       multi-target ranging. This sequence is not publicly documented
 *       and is implemented as a stub here. Replace the stub with the
 *       official STMicroelectronics firmware download routine to obtain
 *       production-quality multi-target ranging.
 *
 * Build:  gcc -O2 -Wall -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C ---- */
#define I2C_BUS              1
#define VL53L3CX_ADDR        0x29

/* ---- Timing ---- */
#define POLL_INTERVAL_US     100000   /* 100 ms */
#define MAX_RANGING_MS       1000     /* 1 s timeout waiting for data-ready */

/* ---- Sensor status codes ---- */
#define VL53L3CX_STATUS_OK                   0x0000
#define VL53L3CX_STATUS_ERROR_I2C            0x0001
#define VL53L3CX_STATUS_ERROR_RANGE_FAIL     0x0002
#define VL53L3CX_STATUS_ERROR_RANGE_TIMEOUT  0x0003

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_byte(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] Read byte failed at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[I2C] Write byte failed at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[I2C] Block read failed at reg 0x%02X: got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_block(int handle, uint8_t reg, const uint8_t *buf, uint32_t len)
{
    int rc = i2cWriteI2CBlockData(handle, reg, (const char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[I2C] Block write failed at reg 0x%02X: wrote %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_init(int handle)
{
    uint8_t model_id = 0;

    /*
     * Verify sensor identity. The VL53L3CX returns 0xEA in the first
     * byte of the model ID register.
     */
    if (i2c_read_byte(handle, 0x010F, &model_id) != 0) {
        fprintf(stderr, "[VL53L3CX] Cannot read model ID - sensor absent or bus error.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "[VL53L3CX] Unexpected model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    printf("[VL53L3CX] Model ID verified (0x%02X).\n", model_id);

    /*
     * STMicroelectronics proprietary firmware download sequence.
     * This is a stub; replace with the official STMicroelectronics
     * firmware download to obtain production-quality multi-target
     * ranging.
     */
    printf("[VL53L3CX] Proprietary firmware download stub - skipping.\n");
    printf("[VL53L3CX] For production use, replace stub with official ST firmware download.\n");

    /*
     * Optional: configure multi-target mode.
     * (Register addresses and values are placeholders; replace with
     *  the actual STMicroelectronics register values.)
     */
    if (i2c_write_byte(handle, 0x0000, 0x01) != 0) {
        fprintf(stderr, "[VL53L3CX] Failed to configure multi-target mode.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one ranging frame                                              */
/* ------------------------------------------------------------------ */
static int vl53l3cx_read_ranging(int handle, uint16_t *status,
                                 uint16_t *num_targets,
                                 uint16_t *distances[],
                                 uint16_t *num_bytes_read)
{
    uint8_t  buf[256];
    uint8_t  ready = 0;
    uint32_t bytes_read = 0;
    int      rc;
    int      attempt;

    /*
     * Poll the data-ready register. The exact register address is
     * placeholdered; replace with the actual STMicroelectronics
     * register value.
     */
    for (attempt = 0; attempt < MAX_RANGING_MS; attempt++) {
        rc = i2c_read_byte(handle, 0x0010, &ready);
        if (rc != 0) {
            return VL53L3CX_STATUS_ERROR_I2C;
        }
        if (ready == 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (ready != 0x01) {
        return VL53L3CX_STATUS_ERROR_RANGE_TIMEOUT;
    }

    /*
     * Read the full ranging data block.
     * The exact register address and length are placeholdered;
     * replace with the actual STMicroelectronics register value.
     */
    rc = i2c_read_block(handle, 0x0011, buf, sizeof(buf));
    if (rc != 0) {
        return VL53L3CX_STATUS_ERROR_I2C;
    }

    /*
     * Parse the ranging data block.
     * This is a stub; replace with the actual STMicroelectronics
     * parsing logic.
     */
    *status = VL53L3CX_STATUS_OK;
    *num_targets = 3;
    *num_bytes_read = 64;

    /*
     * Allocate and populate the distance array.
     * In a real implementation, distances[i] would contain the
     * distance in mm for target i.
     */
    *distances = (uint16_t *)malloc((*num_targets) * sizeof(uint16_t));
    if (*distances == NULL) {
        fprintf(stderr, "[VL53L3CX] Memory allocation failed.\n");
        return VL53L3CX_STATUS_ERROR_I2C;
    }

    for (uint16_t i = 0; i < *num_targets; i++) {
        (*distances)[i] = (uint16_t)(i + 1) * 10; /* Example data */
    }

    /*
     * Mark data as processed by writing to the status register.
     * The exact register address is placeholdered; replace with
     * the actual STMicroelectronics register value.
     */
    if (i2c_write_byte(handle, 0x0012, 0x01) != 0) {
        return VL53L3CX_STATUS_ERROR_I2C;
    }

    return VL53L3CX_STATUS_OK;
}

/* ------------------------------------------------------------------ */
/* Print timestamped distances                                         */
/* ------------------------------------------------------------------ */
static void print_distances(uint16_t num_targets, uint16_t *distances)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Targets: %u\n", timestamp, num_targets);
    for (uint16_t i = 0; i < num_targets; i++) {
        printf("  Target %u: %u mm\n", i + 1, distances[i]);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* Initialize pigpio */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "[pigpio] Initialization failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x29 */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[I2C] Failed to open bus %d addr 0x%02X: %d\n",
                I2C_BUS, VL53L3CX_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l3cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[VL53L3CX] Initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[signal] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[signal] sigaction(SIGTERM)");
    }

    printf("[VL53L3CX] Reading ranging data every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000);

    /* Main loop */
    while (g_running) {
        uint16_t  status = 0;
        uint16_t  num_targets = 0;
        uint16_t  *distances = NULL;
        uint16_t  num_bytes_read = 0;

        rc = vl53l3cx_read_ranging(g_i2c_handle, &status, &num_targets,
                                   &distances, &num_bytes_read);

        if (rc == VL53L3CX_STATUS_OK) {
            print_distances(num_targets, distances);
        } else if (rc == VL53L3CX_STATUS_ERROR_RANGE_TIMEOUT) {
            fprintf(stderr, "[VL53L3CX] Ranging timeout - no data ready.\n");
        } else if (rc == VL53L3CX_STATUS_ERROR_I2C) {
            fprintf(stderr, "[VL53L3CX] I2C communication error.\n");
        } else {
            fprintf(stderr, "[VL53L3CX] Unknown error code: %u\n", rc);
        }

        free(distances);
        distances = NULL;

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\n[VL53L3CX] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

