/*
 * MLX75031 Time-of-Flight distance logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX75031 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75031 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75031 VDD -> 3.3 V
 *   MLX75031 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75031_logger mlx75031_logger.c
 *
 * The MLX75031 is a time-of-flight sensor that provides distance data
 * via a digital I2C interface.  This program reads the 16-bit distance
 * register (register 0x00) every 100 ms, logs the timestamped distance
 * to depth_log.csv, and recovers from transient I2C errors by re-opening
 * the I2C bus.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NAME      "/dev/i2c-1"
#define MLX75031_ADDR     0x30          /* 7-bit I2C address */
#define DISTANCE_REG      0x00          /* 16-bit distance register */
#define LOG_FILE_NAME     "depth_log.csv"
#define SAMPLE_PERIOD_MS  100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(void)
{
    int fd = open(I2C_BUS_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s): %s\n", I2C_BUS_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MLX75031_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a 16-bit big-endian register from the MLX75031.
 * Returns 0 on success and stores the value in *out;
 * returns -1 on I/O error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write (reg ptr 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read two bytes (big-endian) */
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[ERROR] I2C read (reg 0x%02X): got %zd bytes, %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    /* Check whether the file already exists so we can write a header */
    int need_header = (access(LOG_FILE_NAME, F_OK) != 0);

    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", LOG_FILE_NAME, strerror(errno));
        return -1;
    }

    if (need_header) {
        if (fprintf(g_log_fp, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "[ERROR] fprintf(header): %s\n", strerror(errno));
            fclose(g_log_fp);
            g_log_fp = NULL;
            return -1;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "[ERROR] fflush(header): %s\n", strerror(errno));
            fclose(g_log_fp);
            g_log_fp = NULL;
            return -1;
        }
    }

    return 0;
}

static int log_data(uint16_t distance_mm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&now, &tm_info)) {
        fprintf(stderr, "[ERROR] localtime_r\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "[ERROR] fprintf(data): %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "[ERROR] fflush(data): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus and target the MLX75031 */
    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    /* Open the log file */
    if (log_open() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX75031 logger started.  Sampling every %d ms.  Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD_MS);

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance = 0;

        if (i2c_read_reg16(g_i2c_fd, DISTANCE_REG, &distance) != 0) {
            fprintf(stderr, "[WARN] I2C read failed; attempting re-open...\n");

            /* Attempt to recover the I2C bus */
            close(g_i2c_fd);
            g_i2c_fd = -1;

            usleep(500000);  /* 0.5 s back-off before retry */

            g_i2c_fd = i2c_open();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "[ERROR] Re-open failed; will retry next cycle.\n");
                /* Log the error row and continue */
                if (log_data(0xFFFF) != 0) {
                    fprintf(stderr, "[ERROR] Failed to log error row.\n");
                }
                continue;
            }

            /* Re-open the log file in append mode */
            if (log_open() != 0) {
                fprintf(stderr, "[ERROR] Re-open log file failed.\n");
                /* Continue running; next iteration will attempt recovery */
            }

            /* Log the error row */
            if (log_data(0xFFFF) != 0) {
                fprintf(stderr, "[ERROR] Failed to log error row.\n");
            }

            continue;  /* skip the sleep below and loop back */
        }

        /* Log the valid reading */
        if (log_data(distance) != 0) {
            fprintf(stderr, "[ERROR] Failed to log data row.\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

