/*
 * Si1145 Proximity & Ambient Light Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1145 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si1145 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si1145 VDD -> 3.3 V
 *   Si1145 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1145_logger si1145_logger.c -li2c
 *
 * Run:
 *   sudo ./si1145_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ---- Si1145 constants (from datasheet) ---- */
#define SI1145_I2C_ADDR        0x60
#define SI1145_REG_PART_ID     0x00
#define SI1145_REG_HW_KEY      0x07
#define SI1145_REG_MEAS_RATE0  0x08
#define SI1145_REG_ALS_RATE    0x09
#define SI1145_REG_ALS_IRQ_EN  0x0A
#define SI1145_REG_ALS_IRQ_CFG 0x0B
#define SI1145_REG_PS_RATE     0x0C
#define SI1145_REG_PS_IRQ_EN   0x0D
#define SI1145_REG_PS_IRQ_CFG  0x0E
#define SI1145_REG_ALS_VIS_DATA0 0x10
#define SI1145_REG_ALS_IR_DATA0  0x12
#define SI1145_REG_PS1_DATA0     0x16
#define SI1145_REG_COMMAND      0x30

#define SI1145_PART_ID         0x45
#define SI1145_HW_KEY_VAL      0x17
#define SI1145_CMD_RESET       0x01
#define SI1145_CMD_PS_FORCE    0x05
#define SI1145_CMD_ALS_FORCE   0x06

#define I2C_BUS_DEV            "/dev/i2c-1"
#define LOG_FILE_NAME          "biometric_log.txt"
#define SAMPLE_INTERVAL_US     500000  /* 500 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/*  Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Si1145 is little-endian */
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Si1145 sensor operations                                          */
/* ------------------------------------------------------------------ */

static int si1145_reset(int fd)
{
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0)
        return -1;
    usleep(10000);  /* allow reset to complete */
    return 0;
}

static int si1145_init(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr,
                "Si1145 not detected (PART_ID=0x%02X, expected 0x%02X)\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    if (si1145_reset(fd) < 0)
        return -1;

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0)
        return -1;

    /* Measurement rate: 0 → every 8 ms (typ) */
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0)
        return -1;

    /* ALS rate: 0 → force-mode */
    if (i2c_write_reg8(fd, SI1145_REG_ALS_RATE, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_IRQ_EN, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_IRQ_CFG, 0x00) < 0)
        return -1;

    /* PS rate: 0 → force-mode */
    if (i2c_write_reg8(fd, SI1145_REG_PS_RATE, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1145_REG_PS_IRQ_EN, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1145_REG_PS_IRQ_CFG, 0x00) < 0)
        return -1;

    return 0;
}

static int si1145_read_proximity(int fd, uint16_t *prox)
{
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0)
        return -1;
    usleep(10000);  /* conversion time */
    return i2c_read_reg16(fd, SI1145_REG_PS1_DATA0, prox);
}

static int si1145_read_ambient_light(int fd, uint16_t *ambient)
{
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0)
        return -1;
    usleep(10000);
    return i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, ambient);
}

/* ------------------------------------------------------------------ */
/*  Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_data(FILE *fp, uint16_t prox, uint16_t ambient)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n",
            ts, prox, ambient);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, ERROR: %s\n", ts, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/*  Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1145_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1145 logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        uint16_t prox = 0, ambient = 0;
        int      ok = 1;

        if (si1145_read_proximity(g_i2c_fd, &prox) < 0) {
            log_error(g_log_fp, "Failed to read proximity data");
            ok = 0;
        }
        if (si1145_read_ambient_light(g_i2c_fd, &ambient) < 0) {
            log_error(g_log_fp, "Failed to read ambient light data");
            ok = 0;
        }

        if (ok) {
            log_data(g_log_fp, prox, ambient);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

