/*
 * proximity_monitor.c — Raspberry Pi 5
 *
 * Polls an E18-D50NK IR proximity sensor on GPIO line 4 (BCM) every 100 ms
 * and logs a timestamped entry to proximity.log whenever the sensor
 * transitions from HIGH (no object) to LOW (object detected).
 *
 * LED indicator on GPIO line 17 (BCM, physical pin 11) blinks on detection.
 *
 * Build:  gcc -O2 -Wall -Wextra -o proximity_monitor proximity_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define SENSOR_LINE_OFFSET  4   /* BCM 4, physical pin 7  */
#define LED_LINE_OFFSET     17  /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_MS    100
#define LED_BLINK_MS        100
#define LOG_FILE            "proximity.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write an ISO 8601 UTC timestamped entry to the log file.
 * Returns 0 on success, -1 on failure (message printed to stderr).
 */
static int log_detection(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", ts) < 0) {
        fprintf(stderr, "fprintf() to %s failed: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the library's default chip name lookup */
        chip = gpiod_chip_open_by_name("the library's API call");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    sensor_line = gpiod_chip_get_line(chip, SENSOR_LINE_OFFSET);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line %d: %s\n",
                SENSOR_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE_OFFSET);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d: %s\n",
                LED_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_input(sensor_line, "proximity_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "proximity_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Main polling loop ---- */
    int prev_val = gpiod_line_get_value(sensor_line);
    if (prev_val < 0) {
        fprintf(stderr, "Initial sensor read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            fprintf(stderr, "Sensor read failed: %s\n", strerror(errno));
            break;
        }

        /* Detect falling edge: HIGH -> LOW (object entered calibrated range) */
        if (prev_val == 1 && val == 0) {
            if (log_detection() == 0) {
                /* Blink LED for 100 ms */
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "LED on failed: %s\n", strerror(errno));
                }
                usleep(LED_BLINK_MS * 1000);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "LED off failed: %s\n", strerror(errno));
                }
            }
        }

        prev_val = val;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release resources ---- */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);   /* best-effort LED off */
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

