/*
 * Si1145 Proximity & Ambient Light Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si1145 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si1145 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si1145 VDD  -> 3.3 V (pin 1)
 *   Si1145 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -o si1145_logger si1145_logger.c -li2c
 * Run:    sudo ./si1145_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ---- Si1145 constants (from datasheet) ---- */
#define SI1145_I2C_ADDR        0x60
#define SI1145_REG_PART_ID     0x00
#define SI1145_REG_HW_KEY      0x07
#define SI1145_REG_MEAS_RATE0  0x08
#define SI1145_REG_ALS_RATE    0x09
#define SI1145_REG_ALS_IRQ_EN  0x0A
#define SI1145_REG_ALS_IRQ_CFG 0x0B
#define SI1145_REG_ALS_DATA0   0x22
#define SI1145_REG_PS1_DATA0   0x24

#define SI1145_PART_ID         0x45
#define SI1145_HW_KEY_VAL      0x17

#define I2C_BUS_DEV            "/dev/i2c-1"
#define LOG_FILE_NAME          "biometric_data.log"
#define SAMPLE_INTERVAL_SEC    1

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Si1145 sends LSB first */
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1145 sensor                                                       */
/* ------------------------------------------------------------------ */
static int si1145_init(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Si1145 not detected (PART_ID=0x%02X, expected 0x%02X)\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    /* Write HW_KEY to enable the device */
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0)
        return -1;

    /* Configure measurement rate: 0x08 -> 8 ms per measurement cycle */
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x08) < 0)
        return -1;

    /* ALS rate: 0x00 -> no auto-measure; we sample manually */
    if (i2c_write_reg8(fd, SI1145_REG_ALS_RATE, 0x00) < 0)
        return -1;

    /* Clear any pending ALS IRQ */
    if (i2c_write_reg8(fd, SI1145_REG_ALS_IRQ_EN, 0x00) < 0)
        return -1;

    return 0;
}

static int si1145_read_proximity(int fd, uint16_t *prox)
{
    return i2c_read_reg16(fd, SI1145_REG_PS1_DATA0, prox);
}

static int si1145_read_ambient_light(int fd, uint16_t *als)
{
    return i2c_read_reg16(fd, SI1145_REG_ALS_DATA0, als);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t prox, uint16_t als)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (!tm_info) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u\n", ts, prox, als) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1145_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,proximity,ambient_light\n");
        fflush(g_log_file);
    }

    printf("Si1145 logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        uint16_t prox = 0, als = 0;

        if (si1145_read_proximity(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "Proximity read failed; continuing.\n");
        } else if (si1145_read_ambient_light(g_i2c_fd, &als) < 0) {
            fprintf(stderr, "Ambient light read failed; continuing.\n");
        } else {
            if (log_data(g_log_file, prox, als) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

