    }

    printf("Si1145 logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        uint16_t prox = 0, als = 0;

        if (si1145_read_proximity(g_i2c_fd, &prox) < 0) {
            fprintf(stderr, "Proximity read failed; continuing.\n");
        } else if (si1145_read_ambient_light(g_i2c_fd, &als) < 0) {
            fprintf(stderr, "Ambient light read failed; continuing.\n");
        } else {
            if (log_data(g_log_file, prox, als) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

