#define APDS9960_BDATAL      0x9A
#define APDS9960_BDATAH      0x9B
#define APDS9960_PDATAL      0x9C
#define APDS9960_PDATAH      0x9D

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

/* ---- APDS9960 driver ---- */
static int apds9960_init(int handle)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (i2c_read_byte(handle, APDS9960_ID, &id) < 0)
        return -1;
    if (id != 0xAB) {
        fprintf(stderr, "[ERROR] Unexpected APDS9960 ID: 0x%02X (expected 0xAB)\n", id);
        return -1;
    }

    /* Reset device */
    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x00) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Configure proximity integration time (ATIME) */
    if (i2c_write_byte(handle, APDS9960_ATIME, 0xFF) < 0)
        return -1;

    /* Configure proximity wait time (PTIME) */
    if (i2c_write_byte(handle, APDS9960_PTIME, 0xFF) < 0)
        return -1;

    /* Configure proximity pulse count (PPULSE) */
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x87) < 0)
        return -1;

    /* Configure control register (PGAIN=4x, AGAIN=16x) */
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x60) < 0)
        return -1;

    /* Enable proximity and RGBC ADC (PGEN=1, PEN=1, AGEN=1, AEN=1) */
    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x03) < 0)
        return -1;

    return 0;
}

static int apds9960_read_proximity(int handle, uint16_t *proximity)
{
    return i2c_read_word(handle, APDS9960_PDATAL, proximity);
}

static int apds9960_read_color(int handle, uint16_t *red, uint16_t *green,
                               uint16_t *blue, uint16_t *clear)
{
    if (i2c_read_word(handle, APDS9960_CDATAL, clear) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_RDATAL, red)   < 0) return -1;
    if (i2c_read_word(handle, APDS9960_GDATAL, green) < 0) return -1;
    if (i2c_read_word(handle, APDS9960_BDATAL, blue)  < 0) return -1;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, uint16_t red, uint16_t green,
                     uint16_t blue, uint16_t clear, uint16_t proximity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u,%u\n",
            timestamp, red, green, blue, clear, proximity);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    uint16_t red, green, blue, clear, proximity;
    int reinit_attempts = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, APDS9960_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (apds9960_init(i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] APDS9960 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Clear,Proximity\n");
        fflush(log_file);
    }

    /* Register signal handlers */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("APDS9960 proximity & RGB logger started. Press Ctrl+C to stop.\n");

    /* Main polling loop */
    while (!terminate) {
        if (apds9960_read_proximity(i2c_handle, &proximity) < 0) {
            fprintf(stderr, "[WARN] Proximity read failed; re-initialising I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000); /* 1 s backoff */

            for (reinit_attempts = 0; reinit_attempts < MAX_REINIT_ATTEMPTS; reinit_attempts++) {
                i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
                if (i2c_handle >= 0) {
                    if (apds9960_init(i2c_handle) == 0)
                        break;
                    i2cClose(i2c_handle);
                    i2c_handle = -1;
                }
                gpioDelay(1000000); /* 1 s between attempts */
            }

            if (i2c_handle < 0) {
                fprintf(stderr, "[FATAL] I2C re-initialisation failed after %d attempts.\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }
            continue;
        }

        if (apds9960_read_color(i2c_handle, &red, &green, &blue, &clear) < 0) {
            fprintf(stderr, "[WARN] Color read failed; continuing.\n");
        }

        if (proximity > PROXIMITY_THRESHOLD) {
            log_data(log_file, red, green, blue, clear, proximity);
            printf("Proximity threshold exceeded: R=%u G=%u B=%u C=%u P=%u\n",
                   red, green, blue, clear, proximity);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

