/*
 * Si1182-A-GMR Heart Rate Monitor (Raspberry Pi 5, I2C bus 1)
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3)
 *   Si1182 SCL  -> GPIO3 (pin 5)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o heartrate heartrate.c -li2c
 * Run:    ./heartrate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60          /* Si1182-A-GMR default I2C address */
#define CSV_FILENAME   "heartrate.csv"
#define SAMPLE_PERIOD  100000        /* microseconds (100 ms) */

/* Si1182 register addresses (example; adjust per datasheet if different) */
#define REG_HW_KEY     0x07
#define REG_HW_KEY_VAL 0x17
#define REG_PS1_DATA0  0x22
#define REG_PS1_DATA1  0x23

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "i2c_smbus_write_byte_data(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0) {
        fprintf(stderr, "i2c_smbus_read_byte_data(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

static int init_si1182(int fd)
{
    if (i2c_write_byte(fd, REG_HW_KEY, REG_HW_KEY_VAL) < 0)
        return -1;
    return 0;
}

static int read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo, hi;
    if (i2c_read_byte(fd, REG_PS1_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_byte(fd, REG_PS1_DATA1, &hi) < 0)
        return -1;
    *prox = ((uint16_t)hi << 8) | lo;
    return 0;
}

static float calculate_bpm(uint16_t prox)
{
    /*
     * Placeholder linear mapping.
     * A real implementation would use a calibrated curve derived from
     * the sensor's proximity-to-heart-rate characteristic.
     */
    return (float)prox * 0.5f + 50.0f;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

int main(void)
{
    int fd = -1;
    FILE *csv = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling ------------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus --------------------------------------------------- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Initialize sensor ---------------------------------------------- */
    if (init_si1182(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        goto cleanup;
    }

    /* --- Open CSV file -------------------------------------------------- */
    csv = fopen(CSV_FILENAME, "a");
    if (!csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(csv) == 0)
        fprintf(csv, "timestamp,bpm\n");

    printf("Si1182 heart rate monitor started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --------------------------------------------- */
    while (g_running) {
        uint16_t prox;
        if (read_proximity(fd, &prox) < 0) {
            /* Skip this sample; keep running */
            usleep(SAMPLE_PERIOD);
            continue;
        }

        float bpm = calculate_bpm(prox);
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (fprintf(csv, "%s,%.2f\n", ts, bpm) < 0) {
            fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
            break;
        }
        if (fflush(csv) != 0) {
            fprintf(stderr, "fflush(CSV) failed: %s\n", strerror(errno));
            break;
        }

        printf("%s  prox=%u  bpm=%.2f\n", ts, prox, bpm);
        usleep(SAMPLE_PERIOD);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (csv)
        fclose(csv);
    if (fd >= 0)
        close(fd);
    return rc;
}

