code:
/*
 * VL53L0X distance logger for Raspberry Pi 3 Model B+
 * Uses raw I2C and GPIO (no driver library).
 *
 * Wiring:
 *   VL53L0X SDA -> GPIO2 (I2C1 SDA)
 *   VL53L0X SCL -> GPIO3 (I2C1 SCL)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *   GPIO17 (BCM) -> GPIO17 (physical pin 11) with pull-up
 *
 * Build: gcc -O2 -Wall -o vl53l0x_logger vl53l0x_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x29

/* VL53L0X register addresses */
#define REG_IDENTIFICATION_MODEL_ID          0x000
#define REG_SYSTEM_INTERRUPT_CLEAR           0x015
#define REG_RESULT_INTERRUPT_STATUS          0x044
#define REG_RESULT_RANGE_STATUS              0x04D
#define REG_RESULT_DISTANCE                  0x062
#define REG_SYSTEM_MODE_START                0x000
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO     0x00A
#define REG_GPIO_HV_MUX_CTRL                 0x00B
#define REG_GPIO_TIO_HV_STATUS               0x00C
#define REG_SYSTEM_THRESHOLD_HIGH            0x00E
#define REG_SYSTEM_THRESHOLD_LOW             0x010
#define REG_SYSTEM_CONFIG_RANGE_EN           0x018
#define REG_SYSTEM_INTERMEASUREMENT_PERIOD   0x01B
#define REG_SYSTEM_GROUPED_PARAMETER_HOLD    0x01C
#define REG_SYSTEM_RANGE_CONFIG              0x024
#define REG_SYSTEM_INTERMEASUREMENT_PERIOD_2 0x06B
#define REG_SYSTEM_SEQUENCE_CONFIG           0x06C
#define REG_SYSTEM_INTERMEASUREMENT_PERIOD_3 0x06E
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO_2   0x014
#define REG_SYSTEM_INTERRUPT_CLEAR_2         0x016

#define EXPECTED_MODEL_ID 0xEA
#define GPIO_PIN          17
#define LOG_FILE          "distance_log.txt"
#define POLL_TIMEOUT_MS   100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *val)
{
    uint8_t wbuf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "i2c_read_reg8 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *val)
{
    uint8_t wbuf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    uint8_t rbuf[2];
    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, rbuf, sizeof(rbuf)) != (ssize_t)sizeof(rbuf)) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */
static int sensor_present(int fd)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, REG_IDENTIFICATION_MODEL_ID, &model_id) != 0)
        return -1;
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Sensor not found: model ID = 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor configuration                                                */
/* ------------------------------------------------------------------ */
static int configure_sensor(int fd)
{
    /* Clear any pending interrupts */
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* GPIO17 as interrupt output, active low */
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) != 0)
        return -1;

    /* Enable GPIO interrupt */
    if (i2c_write_reg8(fd, REG_SYSTEM_MODE_START, 0x40) != 0)
        return -1;

    /* Start continuous ranging */
    if (i2c_write_reg8(fd, REG_SYSTEM_MODE_START, 0x02) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single measurement and read distance                      */
/* ------------------------------------------------------------------ */
static int read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t dist = 0;

    /* Start a single measurement */
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;
    if (i2c_write_reg8(fd, REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS for completion (timeout ~100 ms) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg8(fd, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Measurement timeout\n");
        return -1;
    }

    /* Read distance */
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear interrupt */
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Stop ranging */
        (void)i2c_write_reg8(g_i2c_fd, REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (sensor_present(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L0X not detected at 0x%02X\n", VL53L0X_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance logger started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(g_i2c_fd, &distance) == 0) {
            if (log_distance(g_log_fp, distance) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Distance read failed; continuing.\n");
        }
        usleep(100000); /* 100 ms between readings */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

