#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ---- CH101 I2C constants (from TDK datasheet) ---- */
#define CH101_I2C_ADDR        0x51          /* default 7-bit address */
#define CH101_REG_DISTANCE    0x00          /* distance register (16-bit, mm) */
#define CH101_REG_TRIGGER     0x01          /* trigger register */
#define CH101_TRIGGER_SINGLE  0x01          /* start a single measurement */

#define I2C_BUS_NAME          "/dev/i2c-1"
#define LOG_FILE_NAME         "distance_log.txt"
#define SAMPLE_PERIOD_US      200000        /* 200 ms between samples */
#define TRIGGER_DELAY_US      50000         /* 50 ms after trigger */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register; returns 0 on success, -1 on error. */
static int ch101_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success, -1 on error. */
static int ch101_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    ssize_t n = write(fd, &reg_buf, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single measurement and read the distance in mm. */
static int ch101_read_distance_mm(int fd, uint16_t *distance_mm)
{
    if (ch101_write_reg(fd, CH101_REG_TRIGGER, CH101_TRIGGER_SINGLE) != 0)
        return -1;

    usleep(TRIGGER_DELAY_US);

    if (ch101_read_reg16(fd, CH101_REG_DISTANCE, distance_mm) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "1970-01-01 00:00:00");
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    FILE *log_file = NULL;
    int ret_code = EXIT_FAILURE;

    /* ---- Signal handling for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open the I2C bus ---- */
    fd = open(I2C_BUS_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                CH101_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Open the log file ---- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Cannot open log file %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    printf("CH101 distance logger started.  Bus=%s  Addr=0x%02X  Log=%s\n",
           I2C_BUS_NAME, CH101_I2C_ADDR, LOG_FILE_NAME);
    printf("Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_read_distance_mm(fd, &distance_mm) != 0) {
            fprintf(stderr, "Sensor read failed; skipping this sample.\n");
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));

            if (fprintf(log_file, "%s, %u\n", ts, distance_mm) < 0) {
                fprintf(stderr, "Log write failed: %s\n", strerror(errno));
            } else {
                fflush(log_file);
                printf("%s, %u mm\n", ts, distance_mm);
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret_code;
}

