/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 ultrasonic ToF sensor reader
 *
 * Hardware:
 *   - ICU-20201 I2C address: 0x62 (7-bit) on /dev/i2c-1
 *   - LED on GPIO 17 (BCM), active-high
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_led icu20201_led.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for GPIO/I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x62          /* ICU-20201 default 7-bit address */
#define GPIO_LED             17            /* BCM pin for the LED            */
#define DISTANCE_THRESHOLD   20.0f         /* cm                             */
#define SAMPLE_PERIOD_US     100000        /* 100 ms                         */
#define LOG_FILE             "distance_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static bool     g_gpio_inited = false;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_distance(float *distance_cm);
static void control_led(float distance_cm);
static void log_distance(float distance_cm);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read distance from the ICU-20201.
 *
 * The ICU-20201 is a ToF sensor; the distance is obtained by sampling the
 * on-chip measurement register (0x22).  A full conversion typically takes
 * ~3 ms; we wait up to 5 ms before reading.
 *
 * Returns 0 on success and stores the distance in cm; -1 on I2C error.
 */
static int read_distance(float *distance_cm)
{
    char buf[2];
    int  bytes_read;

    /* Trigger a measurement by writing 0x01 to the command register (0x00). */
    if (i2cWriteByteData(g_i2c_handle, 0x00, 0x01) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(cmd) failed\n");
        return -1;
    }

    /* Wait for the conversion to complete (max ~3 ms). */
    gpioDelay(5000);  /* 5 ms */

    /* Read the 2-byte distance result from register 0x22. */
    bytes_read = i2cReadI2CBlockData(g_i2c_handle, 0x22, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(dist) returned %d\n",
                bytes_read);
        return -1;
    }

    /*
     * Distance is encoded as a 16-bit big-endian value in mm.
     * Convert to cm.
     */
    uint16_t distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance_cm = (float)distance_mm / 10.0f;
    return 0;
}

/* ----------------------------- LED control ------------------------------- */
static void control_led(float distance_cm)
{
    int level = (distance_cm < DISTANCE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GPIO_LED, level) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(LED=%d) failed\n", GPIO_LED);
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_distance(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s) failed\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, distance_cm);
    fclose(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_gpio_inited) {
        gpioWrite(GPIO_LED, 0);
        gpioSetMode(GPIO_LED, PI_INPUT);
        g_gpio_inited = false;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off. */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(LED=%d) failed\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "[FATAL] gpioWrite(LED, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_gpio_inited = true;

    /* Initialize I2C. */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signals\n");
    }

    printf("ICU-20201 distance monitor started.  Threshold: %.1f cm.  Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    /* Main sampling loop. */
    while (g_running) {
        float distance_cm;

        if (read_distance(&distance_cm) == 0) {
            control_led(distance_cm);
            log_distance(distance_cm);
            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            fprintf(stderr, "[WARN] read_distance failed; will retry next cycle\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

