        fprintf(stderr, "[ERROR] fopen(%s) failed\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, distance_cm);
    fclose(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_gpio_inited) {
        gpioWrite(GPIO_LED, 0);
        gpioSetMode(GPIO_LED, PI_INPUT);
        g_gpio_inited = false;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off. */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(LED=%d) failed\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "[FATAL] gpioWrite(LED, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_gpio_inited = true;

    /* Initialize I2C. */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signals\n");
    }

    printf("ICU-20201 distance monitor started.  Threshold: %.1f cm.  Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    /* Main sampling loop. */
    while (g_running) {
        float distance_cm;

        if (read_distance(&distance_cm) == 0) {
            control_led(distance_cm);
            log_distance(distance_cm);
            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            fprintf(stderr, "[WARN] read_distance failed; will retry next cycle\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

