/*
 * Si1182 GMR Proximity & Ambient Light Sensor logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   Si1182 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si1182 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si1182 VDD -> 3.3 V
 *   Si1182 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o si1182_logger si1182_logger.c -li2c
 * Run:    sudo ./si1182_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1182 register map (subset) ---- */
#define SI1182_I2C_ADDR        0x60
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_HW_KEY      0x07
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_ALS_RATE    0x09
#define SI1182_REG_ALS_IRQ_EN  0x0A
#define SI1182_REG_ALS_IRQ_CFG 0x0B
#define SI1182_REG_ALS_DATA0   0x22
#define SI1182_REG_PS1_DATA0   0x24

#define SI1182_HW_KEY_VAL      0x17
#define SI1182_PART_ID_VAL     0x82

#define I2C_BUS_DEV            "/dev/i2c-1"
#define LOG_FILE_NAME          "biometric_log.txt"
#define SAMPLE_INTERVAL_US     500000   /* 500 ms */
#define MAX_RETRIES            3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] write reg 0x%02X: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "[ERROR] write (reg select 0x%02X): %s (wrote %zd)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "[ERROR] read reg 0x%02X: %s (got %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success. */
static int si1182_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, reg, &lo) < 0) return -1;
    if (si1182_read_reg(fd, reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: verify part ID, then configure measurement rate. */
static int si1182_init(int fd)
{
    uint8_t part_id = 0;
    if (si1182_read_reg(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_VAL) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_VAL);
        return -1;
    }

    if (si1182_write_reg(fd, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) < 0)
        return -1;

    /* Measurement rate: 0x00 = 100 ms, 0x01 = 150 ms, 0x02 = 200 ms */
    if (si1182_write_reg(fd, SI1182_REG_MEAS_RATE0, 0x02) < 0)
        return -1;

    /* ALS rate: 0x00 = 100 ms, 0x01 = 150 ms, 0x02 = 200 ms */
    if (si1182_write_reg(fd, SI1182_REG_ALS_RATE, 0x02) < 0)
        return -1;

    /* Enable ALS interrupt on data-ready */
    if (si1182_write_reg(fd, SI1182_REG_ALS_IRQ_EN, 0x01) < 0)
        return -1;

    /* Configure interrupt polarity and debounce */
    if (si1182_write_reg(fd, SI1182_REG_ALS_IRQ_CFG, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] open %s: %s\n", I2C_BUS_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl I2C_SLAVE 0x%02X: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "[ERROR] Si1182 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[ERROR] fopen %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1182 logger started. Logging to %s every 500 ms. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        uint16_t proximity = 0, ambient_light = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (si1182_read_reg16(g_i2c_fd, SI1182_REG_PS1_DATA0, &proximity) == 0 &&
                si1182_read_reg16(g_i2c_fd, SI1182_REG_ALS_DATA0, &ambient_light) == 0) {
                ok = 1;
                break;
            }
            usleep(10000);  /* 10 ms back-off before retry */
        }

        if (!ok) {
            fprintf(stderr, "[WARN] Sensor read failed after %d attempts; skipping sample.\n",
                    MAX_RETRIES);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        /* Log to file */
        if (fprintf(g_log_fp, "%s, Proximity: %u, Ambient Light: %u\n",
                    ts, proximity, ambient_light) < 0) {
            fprintf(stderr, "[ERROR] fprintf to log: %s\n", strerror(errno));
        } else {
            fflush(g_log_fp);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

