 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2  (I2C bus 1 SDA, pin 3)
 *   ICU-20201 SCL  -> GPIO 3  (I2C bus 1 SCL, pin 5)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode     -> GPIO 17 (BCM) through ~330 Ω resistor -> GND
 *
 * Build:  gcc -O2 -Wall -o tof_monitor tof_monitor.c -lpigpio -lrt
 * Run:    ./tof_monitor [distance_threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ICU-20201 register map (subset) ---- */
#define ICU20201_I2C_ADDR        0x2A
#define ICU20201_WHO_AM_I        0x01
#define ICU20201_WHO_AM_I_VAL    0x20
#define ICU20201_DISTANCE_LSB    0x28
#define ICU20201_DISTANCE_MSB    0x29
#define ICU20201_CONFIG_REG      0x0A
#define ICU20201_CONFIG_VAL      0x00

/* ---- GPIO / timing ---- */
#define LED_GPIO                 17
#define I2C_BUS                  1
#define POLL_INTERVAL_US         50000   /* 50 ms */
#define LOG_FILE                 "tof_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.    */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.   */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) for read failed\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint8_t)data[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit distance register (little-endian).                  */
static int read_distance_mm(int handle, int *distance_mm)
{
    uint8_t lsb, msb;
    if (reg_read(handle, ICU20201_DISTANCE_LSB, &lsb) != 0)
        return -1;
    if (reg_read(handle, ICU20201_DISTANCE_MSB, &msb) != 0)
        return -1;
