    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ICU20201_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor presence check ---- */
    uint8_t who_am_i = 0;
    if (reg_read(g_i2c_handle, ICU20201_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I – sensor absent or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != ICU20201_WHO_AM_I_VAL) {
