    if (reg_write(g_i2c_handle, ICU20201_CONFIG_REG, ICU20201_CONFIG_VAL) != 0) {
        fprintf(stderr, "[ERROR] Failed to configure ICU-20201.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        cleanup();
