/*
 * Raspberry Pi Zero W - Omron B5L-LD50-07050 3D TOF Intrusion Detector
 *
 * Hardware:
 *   - Sensor SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3.3 V, GND -> GND
 *   - I2C bus: /dev/i2c-1
 *   - Sensor I2C address: 0x50 (7-bit)
 *
 * Protocol (simplified):
 *   1. Send 4-byte command frame: 0x01 0x00 0x00 0x00
 *   2. Wait >= 10 ms for measurement
 *   3. Read 15-byte response:
 *        Byte 0: 0x01 (header)
 *        Bytes 11-12: 16-bit big-endian distance in mm
 *
 * Build: gcc -O2 -Wall -o intrusion intrusion.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x50
#define LOG_FILE       "intrusion_log.txt"
#define THRESHOLD_MM   1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_MS 100
#define MEASURE_DELAY_MS 10
#define RESP_LEN       15
#define CMD_LEN        4
#define HEADER_VAL     0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_resp(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t cmd[CMD_LEN] = { 0x01, 0x00, 0x00, 0x00 };
    uint8_t resp[RESP_LEN];

    if (i2c_write_cmd(fd, cmd, CMD_LEN) != 0)
        return -1;

    msleep(MEASURE_DELAY_MS);

    if (i2c_read_resp(fd, resp, RESP_LEN) != 0)
        return -1;

    if (resp[0] != HEADER_VAL) {
        fprintf(stderr, "Unexpected response header: 0x%02X (expected 0x%02X)\n",
                resp[0], HEADER_VAL);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[11] << 8) | resp[12];
    return 0;
}

static float calculate_average(const uint16_t *samples, int n)
{
    uint32_t sum = 0;
    for (int i = 0; i < n; i++)
        sum += samples[i];
    return (float)sum / (float)n;
}

static void log_intrusion(float avg_dist_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s, %.2f\n", ts, avg_dist_mm);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Log file not open; event lost.\n");
    }
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t samples[NUM_SAMPLES];
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            uint16_t dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                samples[valid++] = dist;
            }
            msleep(SAMPLE_DELAY_MS);
        }

        if (valid == 0) {
            fprintf(stderr, "No valid samples in cycle; skipping.\n");
            continue;
        }

        float avg = calculate_average(samples, valid);
        printf("Average distance: %.2f mm\n", avg);

        if (avg < THRESHOLD_MM) {
            printf("Intrusion detected!\n");
            log_intrusion(avg);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

