#include <pigpio.h>

/* ---- VL53L0X constants (from datasheet / Adafruit library) ---- */
#define VL53L0X_ADDR             0x29
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_SYSTEM_MODE_START      0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L0X_REG_RESULT_RANGE_STATUS    0x0014
#define VL53L0X_REG_RESULT_DISTANCE        0x0096

#define VL53L0X_MODEL_ID         0xEACC
#define VL53L0X_MODE_SINGLESHOT  0x01
#define VL53L0X_MODE_CONTINUOUS  0x02
#define VL53L0X_RANGE_READY      0x01
#define VL53L0X_POLL_TIMEOUT_MS  100
#define POLL_INTERVAL_US        500000  /* 500 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit register address.                        */
/* Returns 0 on success, -1 on error (errno preserved by caller).      */
/* ------------------------------------------------------------------ */
static int vl53l0x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes from a 16-bit register address.                        */
/* Returns 0 on success, -1 on error (errno preserved by caller).      */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_block(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char reg_buf[2];
    reg_buf[0] = (char)(reg >> 8);
    reg_buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, reg_buf, 2) != 2)
        return -1;
    if (i2cReadDevice(handle, (char *)data, len) != len)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a 16-bit register address.                  */
/* Returns 0 on success, -1 on error (errno preserved by caller).      */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_byte(int handle, uint16_t reg, uint8_t *value)
{
    return vl53l0x_read_block(handle, reg, value, 1);
}

/* ------------------------------------------------------------------ */
/* Verify sensor presence by reading the model ID register.            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l0x_verify_id(int handle)
{
    uint8_t id = 0;
    if (vl53l0x_read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &id) != 0) {
        fprintf(stderr, "Error: failed to read model ID register (errno %d: %s)\n",
                errno, strerror(errno));
        return -1;
    }
    if (id != (VL53L0X_MODEL_ID & 0xFF)) {
        fprintf(stderr, "Error: model ID mismatch (got 0x%02X, expected 0x%02X)\n",
                id, VL53L0X_MODEL_ID & 0xFF);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot measurement and wait for completion.          */
/* Returns distance in mm on success, -1 on error.                     */
/* ------------------------------------------------------------------ */
static int vl53l0x_read_distance(int handle)
{
    uint8_t status = 0;
    uint8_t dist_buf[2];
    uint16_t distance = 0;

    /* Start a single-shot measurement */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_MODE_START,
                           VL53L0X_MODE_SINGLESHOT) != 0) {
        fprintf(stderr, "Error: failed to start measurement (errno %d: %s)\n",
                errno, strerror(errno));
        return -1;
    }

    /* Poll the interrupt status register until data is ready */
    for (int i = 0; i < VL53L0X_POLL_TIMEOUT_MS; i++) {
        if (vl53l0x_read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Error: failed to read interrupt status (errno %d: %s)\n",
                    errno, strerror(errno));
            return -1;
        }
        if (status & VL53L0X_RANGE_READY)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & VL53L0X_RANGE_READY)) {
        fprintf(stderr, "Error: measurement timeout (data not ready within %d ms)\n",
                VL53L0X_POLL_TIMEOUT_MS);
        return -1;
    }

    /* Read the 16-bit distance result */
    if (vl53l0x_read_block(handle, VL53L0X_REG_RESULT_DISTANCE, dist_buf, 2) != 0) {
        fprintf(stderr, "Error: failed to read distance register (errno %d: %s)\n",
                errno, strerror(errno));
        return -1;
    }

    distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return (int)distance;
}

/* ------------------------------------------------------------------ */
/* Print current timestamp and distance to stdout.                     */
/* ------------------------------------------------------------------ */
static void print_distance(int distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s Distance: %d mm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the VL53L0X address */
    g_i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (errno %d: %s)\n",
                errno, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (vl53l0x_verify_id(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L0X not detected or ID mismatch\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X initialized. Reading distance every 500 ms. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int distance = vl53l0x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            print_distance(distance);
        } else {
            /* On read error, warn and continue rather than exit */
            fprintf(stderr, "Warning: distance read failed, retrying...\n");
        }

        /* Sleep 500 ms; pigpioDelay is microseconds */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

