#define SI1182_REG_HW_KEY    0x07
#define SI1182_REG_MEAS_RATE 0x08
#define SI1182_REG_ALS_RATE  0x09
#define SI1182_REG_PS_LED21  0x0F
#define SI1182_REG_PS_LED3   0x10
#define SI1182_REG_PS_LED4   0x11
#define SI1182_REG_PS1_DATA0 0x18
#define SI1182_REG_PS1_DATA1 0x19
#define SI1182_REG_PS2_DATA0 0x1A
#define SI1182_REG_PS2_DATA1 0x1B
#define SI1182_REG_PS3_DATA0 0x1C
#define SI1182_REG_PS3_DATA1 0x1D
#define SI1182_REG_PS4_DATA0 0x1E
#define SI1182_REG_PS4_DATA1 0x1F

#define SI1182_HW_KEY_VAL    0x17
#define SI1182_PART_ID       0x82

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register; returns 0 on success, -1 on error. */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success, -1 on error. */
static int si1182_read_reg16(int handle, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(handle, reg_lo, &lo) < 0)
        return -1;
    if (si1182_read_reg(handle, reg_lo + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: verify part ID, then configure LED current
 * and measurement rates.  Returns 0 on success, -1 on error. */
static int si1182_init(int handle)
{
    uint8_t part_id;

    /* --- Verify sensor presence via PART_ID --- */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID – sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID);
        return -1;
    }
    printf("[INFO] Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* --- Write HW_KEY to enable the device --- */
    if (si1182_write_reg(handle, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) < 0)
        return -1;

    /* --- Configure LED current for proximity measurements --- */
    if (si1182_write_reg(handle, SI1182_REG_PS_LED21, 0x0F) < 0)   /* LED1 current */
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_LED3,  0x00) < 0)   /* LED2 current */
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_LED4,  0x00) < 0)   /* LED3 current */
        return -1;

    /* --- Measurement rate: 10 ms (0x0A) --- */
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE, 0x0A) < 0)
        return -1;

    /* --- ALS rate: 0 (manual / periodic) --- */
    if (si1182_write_reg(handle, SI1182_REG_ALS_RATE, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the Si1182 address --- */
    g_i2c_handle = i2cOpen(1, SI1182_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI1182_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise the sensor --- */
    if (si1182_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] Si1182 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Reading proximity every 500 ms. Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t ps1, ps2, ps3, ps4;

        if (si1182_read_reg16(g_i2c_handle, SI1182_REG_PS1_DATA0, &ps1) < 0 ||
            si1182_read_reg16(g_i2c_handle, SI1182_REG_PS2_DATA0, &ps2) < 0 ||
            si1182_read_reg16(g_i2c_handle, SI1182_REG_PS3_DATA0, &ps3) < 0 ||
            si1182_read_reg16(g_i2c_handle, SI1182_REG_PS4_DATA0, &ps4) < 0) {
            fprintf(stderr, "[WARN] I2C read error – continuing.\n");
        } else {
            printf("PS1: %5u  PS2: %5u  PS3: %5u  PS4: %5u\n",
                   ps1, ps2, ps3, ps4);
        }

        /* 500 ms delay (microseconds) */
        gpioDelay(500000);
    }

    /* --- Clean shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

