/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   MLX75030 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030 mlx75030.c
 * Run:    ./mlx75030
 */

#include <errno.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x3E          /* 7-bit I2C address */
#define READ_INTERVAL  500           /* milliseconds */
#define MAX_RETRIES    3

/*
 * The MLX75030 is a read-only sensor; the distance is obtained by
 * issuing a read request and then reading back the 2-byte result.
 * We use a single-byte write of 0x00 to select the distance register
 * (register pointer = 0x00) and then a 2-byte read to get the
 * 16-bit distance value.
 */
#define DISTANCE_REG   0x00

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000U;
    ts.tv_nsec = (long)(ms % 1000U) * 1000000L;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* Retry with remaining time after interruption. */
    }
}

/*
 * Open the I2C bus and claim the slave address.
 * Returns a file descriptor (>= 0) on success, or -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Write a single register pointer byte to the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg_ptr(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write(reg ptr 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the sensor after the previously written
 * register pointer.  Returns 0 on success, -1 on failure.
 */
static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read: short read (%zd of %zu bytes)\n",
                n, len);
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit distance value from the MLX75030.
 * Returns 0 on success and stores the distance in *out_mm;
 * returns -1 on failure.
 */
static int read_distance(int fd, uint16_t *out_mm)
{
    uint8_t reg = DISTANCE_REG;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2c_write_reg_ptr(fd, reg) < 0) {
            sleep_ms(10);
            continue;
        }

        uint8_t data[2];
        if (i2c_read_data(fd, data, sizeof(data)) < 0) {
            sleep_ms(10);
            continue;
        }

        /*
         * The MLX75030 returns distance in mm as a 16-bit big-endian
         * value.  The low byte is the most significant byte.
         */
        *out_mm = ((uint16_t)data[0] << 8) | data[1];
        return 0;
    }

    fprintf(stderr, "Failed to read distance after %d attempts\n",
            MAX_RETRIES);
    return -1;
}

int main(void)
{
    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    int fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    /*
     * Probe: try a zero-length write to the device to confirm it
     * is present and responding.
     */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX75030 detected at 0x%02X on %s\n", MLX75030_ADDR, I2C_BUS);
    fflush(stdout);

    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(fd, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            fflush(stdout);
        }
        /*
         * On a read failure the diagnostic message already went to
         * stderr, so we just continue to the next cycle.
         */

        sleep_ms(READ_INTERVAL);
    }

    /* Clean shutdown on signal. */
    if (close(fd) < 0) {
        perror("close");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

