/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W
 *
 * Reads distance from channel 0, ambient light, and error flags every 500 ms
 * over I2C bus 1 (GPIO2=SDA, GPIO3=SCL).
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3101 opt3101.c -lpigpio -lrt
 * Run:    sudo ./opt3101
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3101 register map (subset) ---- */
#define OPT3101_I2C_ADDR        0x38

#define REG_SYSTEM_CONFIG       0x00
#define REG_RESULT_DISTANCE     0x04
#define REG_RESULT_AMBIENT      0x06
#define REG_RESULT_ERROR        0x08

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read a 16-bit little-endian register ---- */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0)
        return -1;

    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;

    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ---- Read a 16-bit big-endian register ---- */
static int read_reg16_be(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0)
        return -1;

    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;

    *out = (uint16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* ---- Write a 16-bit little-endian register ---- */
static int write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[2];
    buf[0] = (char)(val & 0xFF);
    buf[1] = (char)((val >> 8) & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf, 2) < 0)
        return -1;

    return 0;
}

/* ---- Initialise OPT3101: enable channel 0, set integration time ---- */
static int opt3101_init(int handle)
{
    /*
     * SYSTEM_CONFIG (0x00):
     *   bit 0   = CH0_EN (channel 0 enabled)
     *   bits 1:2 = INT_TIME (integration time: 0b00 = 100 ms)
     *   bits 3:4 = RESERVED
     *   bits 5:7 = RESERVED
     * Value = 0x0001  -> CH0_EN = 1, INT_TIME = 100 ms
     */
    if (write_reg16(handle, REG_SYSTEM_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Error: failed to write SYSTEM_CONFIG register\n");
        return -1;
    }

    /* Allow integration time to elapse before first measurement */
    gpioDelay(150000); /* 150 ms */
    return 0;
}

/* ---- Read and log sensor data ---- */
static int read_sensor_data(int handle, uint16_t *distance,
                            uint16_t *ambient, uint16_t *error)
{
    if (read_reg16(handle, REG_RESULT_DISTANCE, distance) < 0) {
        fprintf(stderr, "Error: failed to read distance register\n");
        return -1;
    }
    if (read_reg16(handle, REG_RESULT_AMBIENT, ambient) < 0) {
        fprintf(stderr, "Error: failed to read ambient register\n");
        return -1;
    }
    if (read_reg16(handle, REG_RESULT_ERROR, error) < 0) {
        fprintf(stderr, "Error: failed to read error register\n");
        return -1;
    }
    return 0;
}

/* ---- Print error flags ---- */
static void print_error_flags(uint16_t err)
{
    if (err & 0x0001) fprintf(stderr, "  [ERR_RANGE_SATURATED]");
    if (err & 0x0002) fprintf(stderr, "  [ERR_SIGNAL_TIMEOUT]");
    if (err & 0x0004) fprintf(stderr, "  [ERR_RANGE_OUT_OF_RANGE]");
    if (err & 0x0008) fprintf(stderr, "  [ERR_SENSOR_FAULT]");
    if (err & 0x0010) fprintf(stderr, "  [ERR_AMBIENT_SATURATED]");
    if (err & 0x0020) fprintf(stderr, "  [ERR_AMBIENT_OUT_OF_RANGE]");
    if (err & 0x0040) fprintf(stderr, "  [ERR_AMBIENT_FAULT]");
    if (err & 0x0080) fprintf(stderr, "  [ERR_DATA_FAULT]");
    if (err & 0x0100) fprintf(stderr, "  [ERR_DATA_TIMEOUT]");
    if (err & 0x0200) fprintf(stderr, "  [ERR_DATA_NOT_READY]");
    if (err & 0x0400) fprintf(stderr, "  [ERR_DATA_INVALID]");
    if (err & 0x0800) fprintf(stderr, "  [ERR_DATA_OVERFLOW]");
    if (err & 0x1000) fprintf(stderr, "  [ERR_DATA_UNDERFLOW]");
    if (err & 0x2000) fprintf(stderr, "  [ERR_DATA_CAL_FAULT]");
    if (err & 0x4000) fprintf(stderr, "  [ERR_DATA_CAL_TIMEOUT]");
    if (err & 0x8000) fprintf(stderr, "  [ERR_DATA_CAL_NOT_READY]");
    fprintf(stderr, "\n");
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at OPT3101 address */
    g_i2c_handle = i2cOpen(1, OPT3101_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X\n",
                OPT3101_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (opt3101_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: OPT3101 initialisation failed (sensor may be absent)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3101 reader started. Press Ctrl-C to stop.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0, ambient = 0, error = 0;

        if (read_sensor_data(g_i2c_handle, &distance, &ambient, &error) == 0) {
            printf("Distance: %5u mm  |  Ambient: %5u  |  Error: 0x%04X",
                   distance, ambient, error);
            if (error)
                print_error_flags(error);
            else
                putchar('\n');
        } else {
            fprintf(stderr, "Error: I2C read failure\n");
        }

        /* 500 ms delay (microseconds) */
        gpioDelay(500000);
    }

    /* Cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

