/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VCC  -> 5V  (Pin 2 or 4)
 *   GND  -> GND (Pin 6 or 9)
 *   TRIG -> GPIO17 (BCM 17, Pin 11)
 *   ECHO -> GPIO18 (BCM 18, Pin 12)  [1 kOhm resistor in series]
 *
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse                 */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait               */
#define SAMPLE_PERIOD_US 1000000     /* 1 s between samples                */
#define MAX_PULSE_US     38000       /* HC-SR04 max range ~5 m (~38 ms)     */
#define MIN_PULSE_US     1000        /* HC-SR04 minimum measurable ~2 cm   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read distance in cm.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on invalid pulse.
 */
static double read_distance_cm(void)
{
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;

    /* --- Issue 10 us trigger pulse ---------------------------------- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER high.\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER low.\n");
        return -1.0;
    }

    /* --- Wait for echo rising edge (timeout 200 ms) ----------------- */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            return -1.0;                 /* no echo — sensor absent or not responding */
        }
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge (timeout 200 ms) ---------------- */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > ECHO_TIMEOUT_US) {
            return -1.0;                 /* echo stuck high — sensor stuck */
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;

    /* --- Validate pulse duration ------------------------------------ */
    if (pulse_us == 0 || pulse_us > MAX_PULSE_US) {
        return -2.0;                     /* pulse out of HC-SR04 range */
    }

    /* --- Convert pulse duration to distance (cm) -------------------- */
    /* speed of sound ~343 m/s => 0.0343 cm/us; round trip => /2         */
    return (double)pulse_us * 0.0343 / 2.0;
}

/* ------------------------------------------------------------------ */
static void log_distance(double distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins ---------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown -------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance sensor reader started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("  Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        double distance = read_distance_cm();

        if (distance >= 0.0) {
            log_distance(distance);
        } else if (distance == -1.0) {
            fprintf(stderr, "Warning: echo timeout (sensor absent or not responding).\n");
        } else {
            fprintf(stderr, "Warning: invalid pulse duration (out of range).\n");
        }

        /* Sleep 1 s in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);          /* 100 ms */
        }
    }

    /* --- Cleanup ---------------------------------------------------- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");

    return EXIT_SUCCESS;
}

