/*
 * intrusion_detector.c — Raspberry Pi 3 Model B+
 *
 * Reads a TI IWR1443 mmWave radar's range profile over UART (/dev/serial0),
 * decodes the 64-bin distance data, and logs an intrusion event to
 * intrusion_log.csv when any bin exceeds a 1.0-meter threshold.
 *
 * Wiring:
 *   IWR1443 UART  -> Pi UART0 (GPIO 14 = TX, GPIO 15 = RX)
 *   Alert LED     -> GPIO 17 (BCM) through a suitable current-limiting
 *                   resistor (e.g., 330 Ω)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o intrusion_detector intrusion_detector.c
 *
 * Run:
 *   ./intrusion_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define ALERT_LED_PIN    17          /* BCM GPIO 17 */
#define DISTANCE_THRESHOLD 1.0f      /* meters */
#define NUM_BINS         64
#define BIN_SIZE         2           /* 16-bit little-endian */
#define MAGIC_WORD_SIZE  8
#define PROFILE_SIZE     (NUM_BINS * BIN_SIZE)
#define FRAME_SIZE       (MAGIC_WORD_SIZE + PROFILE_SIZE)
#define LOG_FILE         "intrusion_log.csv"
#define POLL_TIMEOUT_MS  1000
#define ALERT_DURATION_S 2

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART helpers                                                        */
/* ------------------------------------------------------------------ */
static int uart_init(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open()");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr()");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;   /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr()");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/*
 * Read exactly `len` bytes from `fd` within `timeout_ms`.
 * Returns the number of bytes read, -1 on error, -2 on timeout.
 */
static int uart_read_exact(int fd, uint8_t *buf, size_t len, int timeout_ms)
{
    size_t total = 0;
    while (total < len) {
        if (!g_running)
            return -1;

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
