/*
 * obstacle_buzzer.c — Raspberry Pi 4 Model B
 *
 * Reads an E18-D80NK IR obstacle sensor on GPIO 17 (active-low: 0 = obstacle)
 * and drives a buzzer on GPIO 18 (active-high).  Logs state transitions
 * to obstacle_log.txt with ISO-8601 timestamps.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_buzzer obstacle_buzzer.c -lgpiod
 * Run:    ./obstacle_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>

#define SENSOR_PIN  17
#define BUZZER_PIN  18
#define LOG_FILE    "obstacle_log.txt"
#define POLL_MS     100

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_event(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(fp, "%s %s\n", ts, msg);
    fflush(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor = NULL;
    struct gpiod_line *buzzer = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: try the first chip found */
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    /* ---- get lines ---- */
    sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        perror("gpiod_chip_get_line(sensor)");
        goto cleanup;
    }
    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    /* ---- request lines ---- */
    if (gpiod_line_request_input(sensor, "obstacle_sensor") < 0) {
        perror("gpiod_line_request_input(sensor)");
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer, "obstacle_buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    printf("Obstacle detection started.  Sensor=GPIO%d  Buzzer=GPIO%d  Log=%s\n",
           SENSOR_PIN, BUZZER_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int prev_state = -1;   /* force first log */

    while (g_running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            perror("gpiod_line_get_value(sensor)");
            /* brief back-off before retry */
            struct timespec ts = {0, POLL_MS * 1000000L};
            nanosleep(&ts, NULL);
            continue;
        }

        /* E18-D80NK is active-low: 0 => obstacle detected */
        int obstacle = (val == 0) ? 1 : 0;

        if (gpiod_line_set_value(buzzer, obstacle) < 0) {
            perror("gpiod_line_set_value(buzzer)");
        }

        if (obstacle != prev_state) {
            log_event(log_fp, obstacle ? "Obstacle detected" : "Obstacle cleared");
            prev_state = obstacle;
        }

        struct timespec ts = {0, POLL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer) {
        gpiod_line_set_value(buzzer, 0);   /* ensure buzzer off */
        gpiod_line_release(buzzer);
    }
    if (sensor)
        gpiod_line_release(sensor);
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);

    return ret;
}

