/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic distance monitor
 *
 * Hardware:
 *   - ICU-20201 I2C address: 0x44 (7-bit) on bus 1
 *   - Alert output on BCM GPIO 17 (physical pin 11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_monitor icu20201_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for I2C/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ICU20201_ADDR        0x44          /* 7-bit I2C address */
#define ALERT_GPIO           17            /* BCM pin 17 (physical pin 11) */
#define DISTANCE_THRESHOLD   10.0f         /* cm */
#define LOG_FILE             "distance_log.txt"
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define MAX_RETRIES          3

/*
 * ICU-20201 register map (representative subset).
 * The exact register layout depends on the specific ICU-20201 variant;
 * adjust the constants below to match the datasheet revision.
 */
#define REG_PRODUCT_ID       0x00
#define REG_DISTANCE_MSB     0x08
#define REG_DISTANCE_LSB     0x09
#define REG_STATUS           0x0A
#define REG_CONFIG           0x0B

#define EXPECTED_PRODUCT_ID  0x2020

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_distance(float *distance_cm);
static void log_distance(float distance_cm);
static void check_threshold(float distance_cm);
static void cleanup(void);

/* ------------------------------- Handlers -------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Safe to call even if pigpio was never initialised */
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------ I2C helpers ------------------------------ */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read of register 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    /* Chirp distance registers are big-endian */
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write to register 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------ Initializers ----------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (rc=%d)\n",
                I2C_BUS, ICU20201_ADDR, g_i2c_handle);
        return -1;
    }

    /* Verify sensor presence by reading the product ID register */
    uint16_t product_id = 0;
    if (i2c_read_reg16(g_i2c_handle, REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "Sensor not responding on I2C bus %d, addr 0x%02X\n",
                I2C_BUS, ICU20201_ADDR);
        return -1;
    }

    if (product_id != EXPECTED_PRODUCT_ID) {
        fprintf(stderr, "Unexpected product ID: 0x%04X (expected 0x%04X)\n",
                product_id, EXPECTED_PRODUCT_ID);
        return -1;
    }

    printf("ICU-20201 detected (product ID 0x%04X) on I2C bus %d, addr 0x%02X\n",
           product_id, I2C_BUS, ICU20201_ADDR);
    return 0;
}

static int init_gpio(void)
{
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALERT_GPIO);
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d to LOW\n", ALERT_GPIO);
        return -1;
    }
    return 0;
}

/* ------------------------------ Sensor read ------------------------------ */
static int read_distance(float *distance_cm)
{
    uint16_t raw = 0;
    int      attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(g_i2c_handle, REG_DISTANCE_MSB, &raw) == 0) {
            break;
        }
        gpioDelay(10000); /* 10 ms back-off before retry */
    }

    if (attempt >= MAX_RETRIES) {
        fprintf(stderr, "Failed to read distance after %d attempts\n", MAX_RETRIES);
        return -1;
    }

    /*
     * Convert raw 16-bit distance value to cm.
     * The exact conversion factor depends on the ICU-20201 variant;
     * the factor below is a typical placeholder.
     */
    *distance_cm = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------ Logging ---------------------------------- */
static void log_distance(float distance_cm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, %.2f cm\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------ Threshold alert -------------------------- */
static void check_threshold(float distance_cm)
{
    if (distance_cm < DISTANCE_THRESHOLD) {
        if (gpioWrite(ALERT_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to assert alert on GPIO %d\n", ALERT_GPIO);
        } else {
            printf("Distance %.2f cm below threshold %.1f cm – alert triggered\n",
                   distance_cm, DISTANCE_THRESHOLD);
        }
    } else {
        if (gpioWrite(ALERT_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to deassert alert on GPIO %d\n", ALERT_GPIO);
        }
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialise I2C and verify sensor presence */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise GPIO alert pin */
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring distance (threshold %.1f cm). Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    /* Main polling loop */
    while (g_running) {
        float distance_cm = 0.0f;

        if (read_distance(&distance_cm) == 0) {
            log_distance(distance_cm);
            check_threshold(distance_cm);
        } else {
            fprintf(stderr, "Sensor read error – continuing to next cycle\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

