/*
 * Parking assistance system using STMicroelectronics VL53L1X ToF sensor.
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: VL53L1X, I2C address 0x29
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -li2c
 *
 * Log file:  distance_log.csv  (header created only when file is new)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ---- VL53L1X register definitions (16-bit addresses, big-endian on bus) ---- */
#define VL53L1X_ADDR                0x29
#define VL53L1X_REG_IDENTIFICATION  0x010F
#define VL53L1X_REG_SYSTEM_MODE     0x0000
#define VL53L1X_REG_RESULT_RANGE    0x0014
#define VL53L1X_REG_RESULT_STATUS   0x0089

#define VL53L1X_IDENTIFICATION_VALUE 0xEACC
#define VL53L1X_MODE_SINGLESHOT     0x00
#define VL53L1X_MODE_CONTINUOUS     0x02
#define VL53L1X_STATUS_DATA_READY   0x01

#define I2C_BUS_NAME "/dev/i2c-1"
#define LOG_FILE_NAME "distance_log.csv"
#define POLL_INTERVAL_US 100000  /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit-addressed register.                      */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_byte(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes from a 16-bit-addressed register.                      */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_block(int fd, uint16_t reg, uint8_t *data, size_t len)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor.                                      */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    uint8_t id_buf[2];
    uint16_t id;

    /* Read and verify the 16-bit identification register. */
    if (vl53l1x_read_block(fd, VL53L1X_REG_IDENTIFICATION, id_buf, sizeof(id_buf)) != 0)
        return -1;
    id = ((uint16_t)id_buf[0] << 8) | id_buf[1];
    if (id != VL53L1X_IDENTIFICATION_VALUE) {
        fprintf(stderr, "VL53L1X identification mismatch: got 0x%04X, expected 0x%04X\n",
                id, VL53L1X_IDENTIFICATION_VALUE);
        return -1;
    }

    /* Put the sensor into continuous-ranging mode. */
    if (vl53l1x_write_byte(fd, VL53L1X_REG_SYSTEM_MODE, VL53L1X_MODE_CONTINUOUS) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the latest distance measurement.                              */
/* Returns distance in mm on success, -1 on error, -2 if not ready.   */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int fd)
{
    uint8_t status;
    uint8_t dist_buf[2];
    uint16_t dist_mm;

    /* Poll the status register. */
    if (vl53l1x_read_block(fd, VL53L1X_REG_RESULT_STATUS, &status, 1) != 0)
        return -1;

    if (!(status & VL53L1X_STATUS_DATA_READY))
        return -2;                 /* not ready yet */

    /* Read the 16-bit range result. */
    if (vl53l1x_read_block(fd, VL53L1X_REG_RESULT_RANGE, dist_buf, sizeof(dist_buf)) != 0)
        return -1;

    dist_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return (int)dist_mm;
}

/* ------------------------------------------------------------------ */
/* Append a CSV line: timestamp,distance_mm                            */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Print a parking guidance message based on distance.                */
/* ------------------------------------------------------------------ */
static void print_guidance(int distance_mm)
{
    if (distance_mm < 300)
        printf("Guidance: STOP\n");
    else if (distance_mm < 600)
        printf("Guidance: APPROACH\n");
    else if (distance_mm < 1200)
        printf("Guidance: SLOW\n");
    else
        printf("Guidance: CLEAR\n");
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int rc = EXIT_SUCCESS;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS_NAME, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        rc = EXIT_FAILURE;
        goto cleanup_i2c;
    }

    /* ---- Initialise sensor ---- */
    if (vl53l1x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        rc = EXIT_FAILURE;
        goto cleanup_i2c;
    }

    /* ---- Open log file (create with header if new) ---- */
    int file_exists = (access(LOG_FILE_NAME, F_OK) == 0);
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        rc = EXIT_FAILURE;
        goto cleanup_i2c;
    }
    if (!file_exists) {
        if (fprintf(g_log_fp, "timestamp,distance_mm\n") < 0 || fflush(g_log_fp) != 0) {
            fprintf(stderr, "Cannot write header: %s\n", strerror(errno));
            rc = EXIT_FAILURE;
            goto cleanup_all;
        }
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_fd);

        if (distance == -1) {
            fprintf(stderr, "Sensor read error — continuing\n");
        } else if (distance == -2) {
            /* Not ready yet — just wait. */
        } else {
            if (log_data(g_log_fp, distance) != 0)
                fprintf(stderr, "Logging failed\n");
            print_guidance(distance);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");

    /* ---- Graceful shutdown ---- */
    /* Put sensor back into standby before releasing resources. */
    (void)vl53l1x_write_byte(g_i2c_fd, VL53L1X_REG_SYSTEM_MODE, 0x00);

cleanup_all:
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        g_log_fp = NULL;
    }

cleanup_i2c:
    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0)
            fprintf(stderr, "close(i2c) failed: %s\n", strerror(errno));
        g_i2c_fd = -1;
    }

    return rc;
}

code:
/*
 * CH201 ultrasonic Time-of-Flight distance reader with LED blink frequency
 * proportional to distance on a Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   CH201 SDA  -> GPIO 2  (I2C bus 1 SDA, pin 3)
 *   CH201 SCL  -> GPIO 3  (I2C bus 1 SCL, pin 5)
 *   CH201 VDD  -> 3.3 V
 *   CH201 GND  -> GND
 *   LED anode  -> GPIO 18 (BCM) via 330 ohm resistor to GND
 *
 * Build:  gcc -O2 -Wall -o ch201_led ch201_led.c -lpigpio -lrt
 * Run:    sudo ./ch201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define CH201_I2C_ADDR       0x24          /* default 7-bit address */
#define LED_GPIO             18            /* BCM pin */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between samples */
#define HALF_CYCLE_US        5000          /* 5 ms half-cycle (~200 Hz base) */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000         /* 10 ms */

/* CH201 register addresses (16-bit registers, big-endian on the bus) */
#define CH201_REG_PRODUCT_ID      0x0000
#define CH201_REG_DISTANCE_MSB    0x0008
#define CH201_REG_DISTANCE_LSB    0x0009
#define CH201_REG_RANGE_STATUS    0x000A
#define CH201_REG_SYSTEM_CONFIG   0x0010
#define CH201_REG_SYSTEM_CONFIG2  0x0011

#define CH201_PRODUCT_ID_EXPECTED 0x01

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteDevice(handle, buf, 3) == 0)
            return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteDevice(handle, reg_buf, 2) == 0) {
            if (i2cReadDevice(handle, (char *)value, 1) == 1)
                return 0;
        }
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* --------------------------- Sensor init --------------------------------- */
static int ch201_init(int handle)
{
    uint8_t product_id = 0;
    if (i2c_read_reg16(handle, CH201_REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "Error: failed to read CH201 product ID (sensor absent or bus error)\n");
        return -1;
    }
    if (product_id != CH201_PRODUCT_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected product ID 0x%02X (expected 0x%02X)\n",
                product_id, CH201_PRODUCT_ID_EXPECTED);
        return -1;
    }

    /* Standby -> active: clear SYSTEM_CONFIG.SLEEP, set SYSTEM_CONFIG.RANGE_EN */
    if (i2c_write_reg16(handle, CH201_REG_SYSTEM_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error: failed to write SYSTEM_CONFIG\n");
        return -1;
    }
    gpioDelay(1000);  /* allow first measurement to complete */
    return 0;
}

/* --------------------------- Distance read -------------------------------- */
static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t msb = 0, lsb = 0;

    if (i2c_read_reg16(handle, CH201_REG_DISTANCE_MSB, &msb) != 0)
        return -1;
    if (i2c_read_reg16(handle, CH201_REG_DISTANCE_LSB, &lsb) != 0)
        return -1;

    *distance_mm = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* --------------------------- LED control --------------------------------- */
static void led_on(void)  { gpioWrite(LED_GPIO, 1); }
static void led_off(void) { gpioWrite(LED_GPIO, 0); }

/* --------------------------- Main loop ----------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_off();

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (code %d)\n",
                I2C_BUS, CH201_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: CH201 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance reader started (I2C bus %d, addr 0x%02X, LED GPIO %d)\n",
           I2C_BUS, CH201_I2C_ADDR, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (!g_terminate) {
        uint16_t distance = 0;
        if (ch201_read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Warning: I2C read error, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        /* Blink frequency: 200 Hz base, 100 Hz for distance < 50 mm */
        int freq_us = 5000;  /* 200 Hz base */
        if (distance < 500)
            freq_us = 10000; /* 100 Hz */

        /* Distance and frequency */
        printf("%s  Distance: %5u mm  Blink: %3d Hz\n",
               ts, distance, freq_us / 1000);
        fflush(stdout);

        /* One half-cycle of the LED blink */
        led_on();
        gpioDelay(freq_us);
        led_off();
        gpioDelay(freq_us);

        /* Ensure we stay within the 100 ms sample period */
        gpioDelay(SAMPLE_PERIOD_US - (2 * freq_us));
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    led_off();
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

