/*
 * MLX75030 Time-of-Flight distance logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MLX75030 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MLX75030 VDD -> 3.3 V
 *   MLX75030 GND -> GND
 *
 * Build: gcc -O2 -Wall -o mlx75030_logger mlx75030_logger.c -lpigpio -lrt
 * Run:   sudo ./mlx75030_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define MLX75030_ADDR    0x2A          /* Default I2C address (A0=A1=GND) */
#define LOG_FILE         "distance_log.csv"
#define SAMPLE_PERIOD_US 100000        /* 100 ms */
#define MAX_RETRIES      3
#define MEASURE_DELAY_US 10000         /* 10 ms measurement settling */

/* MLX75030 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE_MSB 0x0000
#define REG_DISTANCE_LSB 0x0001
#define REG_COMMAND      0x0002

/* Command to trigger a single distance measurement */
#define CMD_MEASURE      0x0001

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register address.                  */
/* pigpio's i2cWriteWordData sends (reg << 8) | data on the wire,       */
/* so we must pack the 16-bit register address into the arg field.     */
/* ------------------------------------------------------------------ */
static int mlx_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    uint16_t cmd = (uint16_t)((reg << 8) | (value & 0xFF));
    int rc = i2cWriteWordData(handle, reg, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteWordData(reg=0x%04X, val=0x%04X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register address.                 */
/* ------------------------------------------------------------------ */
static int mlx_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%04X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns data as (msb << 8) | lsb */
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the distance in centimeters.         */
/* Returns 0 on success, -1 on persistent failure.                     */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, float *distance_cm)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (mlx_write_reg16(handle, REG_COMMAND, CMD_MEASURE) < 0) {
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        uint16_t msb = 0, lsb = 0;
        if (mlx_read_reg16(handle, REG_DISTANCE_MSB, &msb) < 0) {
            gpioDelay(10000);
            continue;
        }
        if (mlx_read_reg16(handle, REG_DISTANCE_LSB, &lsb) < 0) {
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = (uint16_t)((msb << 8) | lsb);
        *distance_cm = (float)raw / 10.0f;   /* 10 cm resolution */
        return 0;
    }

    fprintf(stderr, "[ERROR] Distance read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float distance)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("[ERROR] fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", ts, distance);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MLX75030_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 logger started. Logging to %s every 100 ms.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (!g_terminate) {
        float distance = 0.0f;
        if (read_distance(g_i2c_handle, &distance) == 0) {
            if (log_data(LOG_FILE, distance) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nMLX75030 logger stopped.\n");
    return EXIT_SUCCESS;
}

