#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS   50
#define POLL_MS       10
#define LOG_FILE      "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

static int debounce_and_log(int sensor_id, int *last_state, int current_state) {
    static uint32_t last_change_tick[2] = {0, 0};
    uint32_t now = gpioTick();
    int elapsed;

    if (now < last_change_tick[sensor_id - 1]) {
        elapsed = (int)(0xFFFFFFFF - last_change_tick[sensor_id - 1] + now + 1);
    } else {
        elapsed = (int)(now - last_change_tick[sensor_id - 1]);
    }

    if (elapsed >= (DEBOUNCE_MS * 1000)) {
        if (current_state != *last_state) {
            *last_state = current_state;
            last_change_tick[sensor_id - 1] = now;

            if (current_state == 0) {
                return log_event(sensor_id, "DETECTED");
            } else {
                return log_event(sensor_id, "CLEARED");
            }
        }
    }

    return 0;
}

int main(void) {
    int last_state_1 = -1;
    int last_state_2 = -1;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        if (debounce_and_log(1, &last_state_1, s1) != 0) {
            fprintf(stderr, "Logging failed for sensor 1\n");
        }
        if (debounce_and_log(2, &last_state_2, s2) != 0) {
            fprintf(stderr, "Logging failed for sensor 2\n");
        }

        gpioDelay(POLL_MS * 1000);
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("fclose");
        }
        log_file = NULL;
    }

    ret = gpioTerminate();
    if (ret != 0) {
        fprintf(stderr, "gpioTerminate returned %d\n", ret);
        return EXIT_FAILURE;
    }

    printf("Proximity detection stopped.\n");
    return EXIT_SUCCESS;
}

