/*
 * CH-101 Time-of-Flight distance logger for Raspberry Pi 5.
 *
 * Wiring:
 *   CH-101 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   CH-101 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   CH-101 VDD  -> 3.3 V
 *   CH-101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_logger ch101_logger.c
 * Run:    ./ch101_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- CH-101 register map (subset) ---- */
#define CH101_I2C_ADDR          0x29
#define CH101_REG_MEAS_STATUS   0x00
#define CH101_REG_DISTANCE_MSB  0x01
#define CH101_REG_DISTANCE_LSB  0x02

/* ---- Timing ---- */
#define I2C_BUS                 "/dev/i2c-1"
#define SAMPLE_PERIOD_MS        500
#define MEAS_TIMEOUT_MS         50
#define LOG_FILE                "distance_log.csv"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register.                           */
/* Returns 0 on success, -1 on error (errno preserved by caller).      */
/* ------------------------------------------------------------------ */
static int ch101_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C short write to reg 0x%02X: %zd bytes\n",
                    reg, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register.                          */
/* Returns 0 on success (value stored in *out), -1 on error.           */
/* ------------------------------------------------------------------ */
static int ch101_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        if (n < 0)
            fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C short write (reg select 0x%02X)\n", reg);
        return -1;
    }

    uint8_t val;
    n = read(fd, &val, 1);
    if (n != 1) {
        if (n < 0)
            fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C short read from reg 0x%02X\n", reg);
        return -1;
    }

    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres.                                       */
/* Returns 0 on success (distance in *mm), -1 on error.                */
/* ------------------------------------------------------------------ */
static int ch101_read_distance(int fd, int *mm)
{
    uint8_t status;
    int elapsed = 0;

    /* Poll MEAS_STATUS until data-ready or timeout. */
    while (elapsed < MEAS_TIMEOUT_MS) {
        if (ch101_read_reg8(fd, CH101_REG_MEAS_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)            /* bit 0 = data ready */
            break;
        usleep(10000);                /* 10 ms */
        elapsed += 10;
    }

    if (elapsed >= MEAS_TIMEOUT_MS) {
        fprintf(stderr, "CH-101 measurement timeout (status=0x%02X)\n",
                status);
        return -1;
    }

    uint8_t msb, lsb;
    if (ch101_read_reg8(fd, CH101_REG_DISTANCE_MSB, &msb) != 0)
        return -1;
    if (ch101_read_reg8(fd, CH101_REG_DISTANCE_LSB, &lsb) != 0)
        return -1;

    *mm = ((int)msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append) ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "timestamp,distance_mm\n");

    printf("Logging CH-101 distance to %s (Ctrl-C to stop)\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int distance_mm;

        if (ch101_read_distance(g_i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Skipping sample due to I2C error.\n");
        } else {
            /* ISO-8601 timestamp */
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *tm = localtime_r(&now, &tm_buf);
            char ts[32];
            if (tm)
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);
            else
                snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");

            fprintf(g_log_fp, "%s,%d\n", ts, distance_mm);
            fflush(g_log_fp);
            printf("%s  distance=%d mm\n", ts, distance_mm);
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early on signal. */
        for (int remaining = SAMPLE_PERIOD_MS;
             remaining > 0 && g_running;
             remaining -= 100)
            usleep(remaining < 100 ? remaining * 1000 : 100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

