#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29
#define NUM_ZONES 64
#define POLL_INTERVAL_MS 500

// VL53L5CX Register Addresses (16-bit)
#define VL53L5CX_REG_SOFT_RESET 0x0003
#define VL53L5CX_REG_SYSTEM_MODE 0x0000
#define VL53L5CX_REG_RANGE_CONFIG 0x0001
#define VL53L5CX_REG_PHASECAL_CONFIG 0x0002
#define VL53L5CX_REG_INTERMEASUREMENT 0x0003
#define VL53L5CX_REG_SYSTEM_THRESH_HIGH 0x0004
#define VL53L5CX_REG_SYSTEM_THRESH_LOW 0x0005
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CONFIG 0x0006
#define VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0007
#define VL53L5CX_REG_RESULT_INTERRUPT_STATUS 0x0008
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0009
#define VL53L5CX_REG_RESULT_DISTANCE 0x000A

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

// Write a 16-bit register address and 16-bit value to the sensor
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "Error writing reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read a 16-bit value from a 16-bit register address
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing reg address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Initialize the VL53L5CX sensor
static int init_vl53l5cx(int fd) {
    // Software reset
    if (i2c_write_reg16(fd, VL53L5CX_REG_SOFT_RESET, 0x0001) < 0) return -1;
    usleep(10000); // 10ms delay
    if (i2c_write_reg16(fd, VL53L5CX_REG_SOFT_RESET, 0x0000) < 0) return -1;
    usleep(10000); // 10ms delay

    // Configure for 8x8 zone grid (64 zones)
    if (i2c_write_reg16(fd, VL53L5CX_REG_RANGE_CONFIG, 0x0001) < 0) return -1; // Enable range
    if (i2c_write_reg16(fd, VL53L5CX_REG_PHASECAL_CONFIG, 0x0001) < 0) return -1; // Enable phase calibration
    if (i2c_write_reg16(fd, VL53L5CX_REG_INTERMEASUREMENT, 0x000A) < 0) return -1; // 10ms intermeasurement
    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_THRESH_HIGH, 0x0000) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_THRESH_LOW, 0x0000) < 0) return -1;
    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_INTERRUPT_CONFIG, 0x0001) < 0) return -1; // Enable interrupt
    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) < 0) return -1; // Clear interrupt

    return 0;
}

// Read all 64 zone distances
static int read_zone_distances(int fd, uint16_t *distances) {
    uint16_t range_status = 0;
    if (i2c_read_reg16(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &range_status) < 0) return -1;

    if ((range_status & 0x0001) == 0) {
        fprintf(stderr, "No new data available\n");
        return -1;
    }

    for (int i = 0; i < NUM_ZONES; i++) {
        uint16_t reg = VL53L5CX_REG_RESULT_DISTANCE + (i * 2);
        if (i2c_read_reg16(fd, reg, &distances[i]) < 0) return -1;
    }

    // Clear interrupt
    if (i2c_write_reg16(fd, VL53L5CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) < 0) return -1;

    return 0;
}

int main() {
    int fd = -1;
    uint16_t distances[NUM_ZONES];

    // Setup signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Initialize sensor
    if (init_vl53l5cx(fd) < 0) {
        fprintf(stderr, "Failed to initialize VL53L5CX sensor\n");
        close(fd);
        return 1;
    }

    printf("VL53L5CX initialized. Reading zone distances every %dms...\n", POLL_INTERVAL_MS);

    // Main loop
    while (running) {
        if (read_zone_distances(fd, distances) == 0) {
            printf("Zone Distances: ");
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("%u ", distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read zone distances\n");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

