/*
 * MLX75030 Time-of-Flight distance sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD -> 3.3 V
 *   MLX75030 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o mlx75030 mlx75030.c -lpigpio -lrt
 * Run:    sudo ./mlx75030
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define MLX75030_ADDR        0x2A          /* default 7-bit I2C address */
#define SAMPLE_PERIOD_US     100000        /* 100 ms between samples */
#define I2C_RETRY_COUNT      3
#define I2C_RETRY_DELAY_US   10000         /* 10 ms between retries */

/*
 * MLX75030 register map (representative subset).
 * The exact register addresses depend on the specific MLX75030 variant;
 * adjust these constants to match the datasheet for your module.
 */
#define REG_SOFT_RESET       0x00
#define REG_SYSTEM_CONFIG    0x01
#define REG_DISTANCE_MSB     0x04
#define REG_DISTANCE_LSB     0x05
#define REG_STATUS           0x06

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */

/*
 * Write a single byte to a register with retry.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; ++attempt) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr,
                "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, I2C_RETRY_COUNT);
        if (attempt < I2C_RETRY_COUNT - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a single byte from a register with retry.
 * Returns the byte value (0–255) on success, -1 on failure.
 */
static int i2c_read_reg(int handle, uint8_t reg)
{
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; ++attempt) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0)
            return rc;
        fprintf(stderr,
                "[WARN] i2cReadByteData(reg=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, I2C_RETRY_COUNT);
        if (attempt < I2C_RETRY_COUNT - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int i2c_read_reg16(int handle, uint8_t reg_lsb, uint16_t *out)
{
    int lsb = i2c_read_reg(handle, reg_lsb);
    if (lsb < 0)
        return -1;
    int msb = i2c_read_reg(handle, reg_lsb + 1);
    if (msb < 0)
        return -1;
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */

/*
 * Initialise the MLX75030:
 *   1. Soft-reset the device.
 *   2. Configure the system (e.g. enable continuous ranging).
 *   3. Wait for the first measurement to be ready.
 *
 * Returns 0 on success, -1 on failure.
 */
static int sensor_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg(handle, REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Soft reset failed — sensor may be absent or bus error.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /*
     * Configure system: enable continuous ranging, etc.
     * The exact value depends on the module; use the datasheet.
     */
    if (i2c_write_reg(handle, REG_SYSTEM_CONFIG, 0x01) != 0) {
        fprintf(stderr, "[ERROR] System configuration write failed.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for configuration to take effect */

    /* Allow first measurement to complete */
    gpioDelay(50000); /* 50 ms */

    return 0;
}

/* --------------------------- Distance read -------------------------------- */

/*
 * Read the distance in mm.
 * Returns 0 on success and stores the distance in *distance_mm, -1 on failure.
 */
static int read_distance(int handle, uint16_t *distance_mm)
{
    int status = i2c_read_reg(handle, REG_STATUS);
    if (status < 0) {
        fprintf(stderr, "[ERROR] Failed to read status register.\n");
        return -1;
    }

    /*
     * Check the data-ready bit (or a specific error bit) in the status
     * register.  Adjust the mask to match your module's datasheet.
     */
    if ((status & 0x01) == 0) {
        /* Data not ready yet — not an error, just skip this sample */
        return -1;
    }

    if (i2c_read_reg16(handle, REG_DISTANCE_LSB, distance_mm) != 0) {
        fprintf(stderr, "[ERROR] Failed to read distance registers.\n");
        return -1;
    }

    return 0;
}

/* --------------------------- Timestamp helper ----------------------------- */

static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000);
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MLX75030 address */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d).\n",
                I2C_BUS, MLX75030_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (sensor_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Sensor initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance sensor reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (read_distance(g_i2c_handle, &distance_mm) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("%s  Distance: %u mm\n", ts, distance_mm);
            fflush(stdout);
        } else {
            /*
             * read_distance() returns -1 on transient errors (e.g. data not
             * ready yet).  A persistent -1 may indicate a bus or sensor
             * failure; log it but continue sampling.
             */
            fprintf(stderr, "[WARN] read_distance() failed; will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --------------------------- Graceful shutdown ------------------------ */
    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

