/*
 * VL53L4CX Time-of-Flight distance sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   VL53L4CX SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   VL53L4CX SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   VL53L4CX VDD  -> 3.3 V
 *   VL53L4CX GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l4cx_reader vl53l4cx_reader.c -li2c
 *
 * Run:
 *   sudo ./vl53l4cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ---- VL53L4CX register map (subset) ---- */
#define VL53L4CX_I2C_ADDR          0x29

#define VL53L4CX_REG_SOFT_RESET     0x0000
#define VL53L4CX_REG_SYSTEM_START   0x0001
#define VL53L4CX_REG_INT_STATUS     0x0044
#define VL53L4CX_REG_RESULT_DIST    0x0096

#define VL53L4CX_INT_DATA_READY     0x01

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address followed by a 16-bit data value.    */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(0x%04X, 0x%04X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address followed by a 16-bit data value.     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_read16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read16: write address 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "i2c_read16: read data 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

