static int vl53l4cx_init(int fd)
{
    /* Soft reset */
    if (i2c_write16(fd, VL53L4CX_REG_SOFT_RESET, 0x0001) != 0)
        return -1;
    usleep(10000); /* 10 ms */

    /* Start ranging */
    if (i2c_write16(fd, VL53L4CX_REG_SYSTEM_START, 0x0001) != 0)
        return -1;
    usleep(10000); /* 10 ms for first measurement */

    return 0;
}

/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int fd, uint16_t *distance_mm)
