        return 1; /* not ready yet */

    if (i2c_read16(fd, VL53L4CX_REG_RESULT_DIST, distance_mm) != 0)
        return -1;

    /* Clear interrupt so the next measurement can be flagged */
    if (i2c_write16(fd, VL53L4CX_REG_INT_STATUS, 0x0000) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%06ld", ts.tv_nsec / 1000);
