code:
/*
 * Raspberry Pi 4 Model B - VL53L1X Time-of-Flight Distance Sensor Monitor
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1 (GPIO 2 SDA, GPIO 3 SCL), address 0x29
 *   - Buzzer on GPIO 22 (BCM), active-high
 *
 * Behavior:
 *   - Reads distance every 500 ms in continuous ranging mode.
 *   - Sounds buzzer when distance < 100 mm.
 *   - Handles I2C errors gracefully and logs them.
 *   - Clean shutdown on SIGINT / SIGTERM.
 *
 * Build:
 *   gcc -O2 -Wall -o vl53l1x_monitor vl53l1x_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define BUZZER_GPIO          22
#define DISTANCE_THRESHOLD   100          /* mm */
#define POLL_INTERVAL_US     500000       /* 500 ms */

/* --------------------------- VL53L1X Registers --------------------------- */
#define VL53L1X_REG_SOFT_RESET                 0x0003
#define VL53L1X_REG_SYSTEM_MODE_START          0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR     0x0046
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS    0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS        0x0089
#define VL53L1X_REG_RESULT_DISTANCE            0x0096

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function Prototypes ------------------------- */
static void signal_handler(int sig);
static void log_error(const char *msg);
static int  init_vl53l1x(void);
static int  read_distance(uint16_t *distance_mm);
static void buzzer_on(void);
static void buzzer_off(void);
static void cleanup(void);

/* ------------------------------- Helpers --------------------------------- */
static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
}

static void buzzer_on(void)  { gpioWrite(BUZZER_GPIO, 1); }
static void buzzer_off(void) { gpioWrite(BUZZER_GPIO, 0); }

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    buzzer_off();
    gpioTerminate();
}

/* --------------------------- VL53L1X Init -------------------------------- */
static int init_vl53l1x(void) {
    /* Soft reset */
    if (i2cWriteByteData(g_i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        log_error("Failed to write soft-reset low");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (i2cWriteByteData(g_i2c_handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        log_error("Failed to write soft-reset high");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start continuous ranging mode */
    if (i2cWriteByteData(g_i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) {
        log_error("Failed to start continuous ranging");
        return -1;
    }
    return 0;
}

/* --------------------------- Read Distance ------------------------------- */
static int read_distance(uint16_t *distance_mm) {
    int status = i2cReadByteData(g_i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
    if (status < 0) {
        log_error("Failed to read interrupt status");
        return -1;
    }

    /* Bit 0 indicates new data ready */
    if (!(status & 0x01)) {
        return 1; /* No new data yet */
    }

    /* Read 16-bit distance (little-endian) */
    char buf[2];
    if (i2cReadI2CBlockData(g_i2c_handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) != 2) {
        log_error("Failed to read distance data");
        return -1;
    }

    *distance_mm = (uint16_t)((buf[1] << 8) | buf[0]);

    /* Clear interrupt to allow next measurement */
    if (i2cWriteByteData(g_i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        log_error("Failed to clear interrupt");
        return -1;
    }

    return 0;
}

/* --------------------------- Signal Handler ------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Main ------------------------------------ */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set buzzer GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    buzzer_off();

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_vl53l1x() < 0) {
        log_error("VL53L1X initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;
        int rc = read_distance(&distance);

        if (rc == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                buzzer_on();
                gpioDelay(500000); /* 500 ms */
                buzzer_off();
            }
        } else if (rc < 0) {
            /* I2C error already logged; skip this cycle */
        }
        /* rc == 1: no new data, just wait */

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

