/*
 * parking_assist.c — Raspberry Pi 4 Model B
 *
 * HC-SR04 ultrasonic sensor (trigger BCM 23, echo BCM 24)
 * SG90 servo (control BCM 17)
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:    sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_PER_US  0.0343          /* cm/us at ~20 °C */
#define MIN_DISTANCE_CM           2.0
#define MAX_DISTANCE_CM           400.0
#define SERVO_MIN_ANGLE           (-90)            /* degrees */
#define SERVO_MAX_ANGLE           (90)

/* ---- Timing constants (microseconds) ---- */
#define TRIGGER_PULSE_US          10
#define ECHO_TIMEOUT_US           50000            /* 50 ms */
#define LOOP_DELAY_US             200000           /* 200 ms */
#define LOG_FILE                  "sensor_data.log"

/* ---- Sentinel error value ---- */
#define ERROR_DISTANCE            (-1.0)

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns distance in cm, or ERROR_DISTANCE on timeout / error.      */
/* ------------------------------------------------------------------ */
static double read_distance(void)
{
    /* Issue 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(trigger HIGH) failed\n");
        return ERROR_DISTANCE;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger LOW) failed\n");
        return ERROR_DISTANCE;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return ERROR_DISTANCE;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout if stuck high) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return ERROR_DISTANCE;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    double distance = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm out of range [%.1f–%.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return ERROR_DISTANCE;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
static int map_distance_to_angle(double distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double frac = (distance - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(SERVO_MIN_ANGLE +
                 frac * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));
}

/* ------------------------------------------------------------------ */
static void log_data(double distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "<timestamp-error>, Distance: %.2f cm\n", distance);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5000);  /* 5 ms settle */

    /* ---- Main loop ---- */
    while (g_running) {
        double distance = read_distance();

        if (distance != ERROR_DISTANCE) {
            int angle = map_distance_to_angle(distance);
            if (gpioServo(SERVO_PIN, angle) < 0) {
                fprintf(stderr, "gpioServo failed for angle %d\n", angle);
            }
            log_data(distance);
        } else {
            /* Keep servo at current position on sensor error */
            fprintf(stderr, "Sensor read error — skipping servo update\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    gpioServo(SERVO_PIN, 0);   /* stop servo pulses */
    gpioDelay(10000);          /* allow last pulse to complete */
    gpioServo(SERVO_PIN, 0);   /* ensure pulses are off */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

