code:
/*
 * Raspberry Pi 3 Model B+ — VL53L1X distance monitor with buzzer alert
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1, address 0x29
 *   - Buzzer on GPIO23 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_monitor vl53l1x_monitor.c -lm -lpigpio -lrt
 *
 * Run:
 *   sudo ./vl53l1x_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <mqueue.h>
#include <pigpio.h>

#include "vl53l1x.h"

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define BUZZER_GPIO          23
#define DISTANCE_THRESHOLD   100          /* mm */
#define TIMING_BUDGET_MS     50
#define SAMPLE_PERIOD_US     (TIMING_BUDGET_MS * 1000)
#define MQ_NAME              "/vl53l1x_distance"
#define MQ_MAX_MSG           10
#define MQ_MSG_SIZE          64
#define POLL_TIMEOUT_S       1

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static mqd_t    g_mq = (mqd_t)-1;
static pthread_mutex_t g_mq_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Message queue                                                       */
/* ------------------------------------------------------------------ */
static int init_message_queue(void)
{
    struct mq_attr attr;
    memset(&attr, 0, sizeof(attr));
    attr.mq_flags   = 0;
    attr.mq_maxmsg  = MQ_MAX_MSG;
    attr.mq_msgsize = MQ_MSG_SIZE;
    attr.mq_curmsgs = 0;

    g_mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (g_mq == (mqd_t)-1) {
        perror("mq_open");
        return -1;
    }
    return 0;
}

static void send_message(const char *msg)
{
    if (g_mq == (mqd_t)-1)
        return;

    pthread_mutex_lock(&g_mq_mutex);
    if (mq_send(g_mq, msg, strlen(msg) + 1, 0) == -1)
        perror("mq_send");
    pthread_mutex_unlock(&g_mq_mutex);
}

/* ------------------------------------------------------------------ */
/* Buzzer                                                              */
/* ------------------------------------------------------------------ */
static void buzzer_on(void)
{
    gpioWrite(BUZZER_GPIO, 1);
}

static void buzzer_off(void)
{
    gpioWrite(BUZZER_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        vl53l1x_stop_ranging(&g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_mq != (mqd_t)-1) {
        mq_close(g_mq);
        mq_unlink(MQ_NAME);
        g_mq = (mqd_t)-1;
    }

    buzzer_off();
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Buzzer GPIO ------------------------------------------------ */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    buzzer_off();

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init ------------------------------------------------ */
    if (vl53l1x_init(&g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Message queue ---------------------------------------------- */
    if (init_message_queue() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X monitoring started (threshold %d mm, bus %d, addr 0x%02X).\n",
           DISTANCE_THRESHOLD, I2C_BUS, VL53L1X_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(&g_i2c_handle, &distance);

        if (rc != 0) {
            fprintf(stderr, "I2C read error (rc=%d): %s\n", rc, strerror(errno));
            buzzer_off();
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            buzzer_on();
        } else {
            buzzer_off();
        }

        char msg[64];
        snprintf(msg, sizeof(msg), "Distance: %u mm", distance);
        send_message(msg);

        usleep(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

