    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init ------------------------------------------------ */
    if (vl53l1x_init(&g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Message queue ---------------------------------------------- */
    if (init_message_queue() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X monitoring started (threshold %d mm, bus %d, addr 0x%02X).\n",
           DISTANCE_THRESHOLD, I2C_BUS, VL53L1X_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(&g_i2c_handle, &distance);

        if (rc != 0) {
            fprintf(stderr, "I2C read error (rc=%d): %s\n", rc, strerror(errno));
            buzzer_off();
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            buzzer_on();
        } else {
            buzzer_off();
        }

        char msg[64];
        snprintf(msg, sizeof(msg), "Distance: %u mm", distance);
        send_message(msg);

        usleep(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

