/*
 * Parking sensor using HC-SR04 ultrasonic sensor on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5V  (pin 2)
 *   HC-SR04 GND  -> GND (pin 6)
 *   HC-SR04 TRIG -> GPIO17 (pin 11)
 *   HC-SR04 ECHO -> GPIO27 (pin 13) [3.3 V-safe via voltage divider if 5 V ECHO]
 *   Buzzer +     -> GPIO22 (pin 15) via transistor/MOSFET
 *   Buzzer -     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:
 *   sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND_CM_PER_US  0.0343   /* cm/us at ~20 °C */
#define TIMEOUT_US                30000    /* 30 ms max echo wait */
#define MIN_DISTANCE_CM           2.0
#define MAX_DISTANCE_CM           400.0
#define THRESHOLD_CM              30.0
#define POLL_INTERVAL_US          100000   /* 100 ms */
#define TRIGGER_PULSE_US          10

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo interrupt state                                                */
/* ------------------------------------------------------------------ */
typedef struct {
    volatile uint32_t start_tick;
    volatile uint32_t end_tick;
    volatile bool     got_rising;
    volatile bool     got_falling;
} echo_state_t;

static echo_state_t g_echo;

/*
 * pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min.
 * This subtraction handles the wrap-around correctly.
 */
static inline uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;          /* unsigned subtraction wraps correctly */
}

/*
 * pigpio dispatches callbacks on a dedicated thread, so we keep the
 * handler as short as possible and only update volatile state.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_echo.start_tick  = tick;
        g_echo.got_rising  = true;
        g_echo.got_falling = false;
    } else if (level == 0 && g_echo.got_rising) {
        g_echo.end_tick    = tick;
        g_echo.got_falling = true;
    }
}

/* ------------------------------------------------------------------ */
/* Trigger pulse                                                       */
/* ------------------------------------------------------------------ */
static void trigger_pulse(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: gpioWrite(TRIGGER, 1) failed\n");
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(TRIGGER, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    /* Reset state */
    g_echo.start_tick  = 0;
    g_echo.end_tick    = 0;
    g_echo.got_rising  = false;
    g_echo.got_falling = false;

    trigger_pulse();

    /* Wait for falling edge (echo completion) with timeout */
    uint32_t waited = 0;
    while (!g_echo.got_falling && waited < TIMEOUT_US) {
        gpioDelay(100);            /* 100 µs granularity */
        waited += 100;
    }

    if (!g_echo.got_rising) {
        fprintf(stderr, "Warning: no echo rising edge (sensor absent?)\n");
        return -1.0f;
    }
    if (!g_echo.got_falling) {
        fprintf(stderr, "Warning: echo timeout (no falling edge within %u µs)\n",
                TIMEOUT_US);
        return -1.0f;
    }

    uint32_t elapsed = tick_diff(g_echo.start_tick, g_echo.end_tick);
    float distance = (float)elapsed * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f-%.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void buzzer_on(void)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: gpioWrite(BUZZER, 1) failed\n");
    }
}

static void buzzer_off(void)
{
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(BUZZER, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    buzzer_off();
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* ---- Register echo interrupt ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started.  TRIG=GPIO%d  ECHO=GPIO%d  BUZZER=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm  Poll: %u µs  Timeout: %u µs\n",
           THRESHOLD_CM, POLL_INTERVAL_US, TIMEOUT_US);
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            printf("Distance: ERROR\n");
        } else {
            printf("Distance: %.2f cm  %s\n",
                   distance,
                   (distance < THRESHOLD_CM) ? "[ALERT]" : "[OK]");

            if (distance < THRESHOLD_CM) {
                buzzer_on();
            } else {
                buzzer_off();
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

