code:
/*
 * Gate controller for Raspberry Pi Zero W
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (address 0x29)
 *   - SG90 servo on GPIO18 (BCM) with hardware PWM
 *
 * Build:
 *   gcc -O2 -Wall -o gate_controller gate_controller.c -lm
 *
 * Remote control (v2 callback API):
 *   ./gate_controller --remote
 *   ./gate_controller --remote-port 8080
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x29
#define SERVO_PIN        18
#define SERVO_FREQ       50          /* Hz */
#define SERVO_DUTY_MIN   500         /* us */
#define SERVO_DUTY_MAX   2500        /* us */
#define SERVO_DUTY_OPEN  1500        /* us */
#define SERVO_DUTY_CLOSE 1000        /* us */
#define DISTANCE_THRESHOLD 20        /* cm */
#define LOG_FILE         "gate_log.txt"
#define POLL_INTERVAL_US 500000      /* 0.5 s */
#define MAX_RETRIES      3
#define BOOT_TIMEOUT_MS  2000

/* VL53L1X register addresses */
#define VL53L1X_SOFT_RESET            0x0003
#define VL53L1X_SYSTEM_START          0x0000
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_RESULT_RANGE_STATUS   0x0089
#define VL53L1X_RESULT_DISTANCE       0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *val)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *val)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    uint8_t data[2];
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read16 from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X                                                             */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    /* Software reset */
    if (i2c_write_reg8(fd, VL53L1X_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000); /* 10 ms */
    if (i2c_write_reg8(fd, VL53L1X_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000); /* 10 ms */

    /* Poll for device presence / boot */
    uint8_t status = 0;
    for (int i = 0; i < BOOT_TIMEOUT_MS; i += 50) {
        if (i2c_read_reg8(fd, VL53L1X_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status != 0) break;
        usleep(50000); /* 50 ms */
    }
    if (status == 0) {
        fprintf(stderr, "VL53L1X boot timeout (sensor absent or not responding)\n");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg8(fd, VL53L1X_SYSTEM_START, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    if (i2c_read_reg8(fd, VL53L1X_RESULT_INTERRUPT_STATUS, &status) < 0)
        return -1;

    if (status & 0x01) {
        uint16_t dist = 0;
        if (i2c_read_reg16(fd, VL53L1X_RESULT_DISTANCE, &dist) < 0)
            return -1;
        *distance_mm = dist;

        /* Clear interrupt */
        if (i2c_write_reg8(fd, VL53L1X_RESULT_INTERRUPT_STATUS, 0x01) < 0)
            return -1;

        return 0;
    }
    return 1; /* no new data yet */
}

/* ------------------------------------------------------------------ */
/* Servo (hardware PWM via sysfs)                                      */
/* ------------------------------------------------------------------ */
static int servo_init(void)
{
    int ret = 0;
    char path[64];

    /* Export GPIO18 */
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", SERVO_PIN) < 0) {
        fprintf(stderr, "Failed to write GPIO export: %s\n", strerror(errno));
        ret = -1;
    }
    fclose(fp);
    if (ret) return -1;

    /* Wait for sysfs to create the GPIO directory */
    for (int i = 0; i < 10; i++) {
        snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d", SERVO_PIN);
        if (access(path, F_OK) == 0) break;
        usleep(100000);
    }

    /* Set direction to output */
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", SERVO_PIN);
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Configure PWM via sysfs */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/export");
    fp = fopen(path, "w");
    if (!fp) {
        /* May already be exported; ignore EBUSY */
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
            return -1;
        }
    } else {
        if (fprintf(fp, "0") < 0) {
            fprintf(stderr, "Failed to write PWM export: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
        fclose(fp);
    }

    /* Set period (50 Hz -> 20 000 us) */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "20000") < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Set initial duty cycle (closed) */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", SERVO_DUTY_CLOSE) < 0) {
        fprintf(stderr, "Failed to set initial duty cycle: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Enable PWM */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "1") < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    return 0;
}

static void servo_set_duty(int duty_us)
{
    if (duty_us < SERVO_DUTY_MIN) duty_us = SERVO_DUTY_MIN;
    if (duty_us > SERVO_DUTY_MAX) duty_us = SERVO_DUTY_MAX;

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return;
    }
    if (fprintf(fp, "%d", duty_us) < 0) {
        fprintf(stderr, "Failed to set duty cycle: %s\n", strerror(errno));
    }
    fclose(fp);
}

static void servo_cleanup(void)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", SERVO_PIN);
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "in");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", SERVO_PIN);
        fclose(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Remote control (v2 callback API)                                    */
/* ------------------------------------------------------------------ */
static void force_open(void)
{
    servo_set_duty(SERVO_DUTY_OPEN);
    log_event("Gate opened by remote command");
}

static void force_close(void)
{
    servo_set_duty(SERVO_DUTY_CLOSE);
    log_event("Gate closed by remote command");
}

static void status_request(void)
{
    /* Dummy: always closed (0) */
    printf("Gate status: 0\n");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int remote_mode = 0;
    int remote_port = 8080;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--remote") == 0) {
            remote_mode = 1;
        } else if (strcmp(argv[i], "--remote-port") == 0 && i + 1 < argc) {
            remote_port = atoi(argv[++i]);
            if (remote_port <= 0 || remote_port > 65535) {
                fprintf(stderr, "Invalid port: %s\n", argv[i]);
                return 1;
            }
        } else {
            fprintf(stderr, "Usage: %s [--remote] [--remote-port <port>]\n", argv[0]);
            return 1;
        }
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        return 1;
    }

    /* Initialize I2C */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus");
        fclose(g_log_fp);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    /* Initialize servo */
    if (servo_init() < 0) {
        fprintf(stderr, "Servo initialization failed\n");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    log_event("Gate controller started");

    /* Remote control server (v2 callback API) */
    if (remote_mode) {
        int server_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd < 0) {
            perror("socket");
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        int opt = 1;
        if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
            perror("setsockopt");
            close(server_fd);
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(remote_port);

        if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("bind");
            close(server_fd);
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        if (listen(server_fd, 3) < 0) {
            perror("listen");
            close(server_fd);
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        printf("Remote control listening on port %d\n", remote_port);

        while (g_running) {
            int client_fd = accept(server_fd, NULL, NULL);
            if (client_fd < 0) {
                if (errno == EINTR) continue;
                perror("accept");
                break;
            }

            char buf[128];
            ssize_t n = read(client_fd, buf, sizeof(buf) - 1);
            if (n > 0) {
                buf[n] = '\0';
                /* Strip trailing newline */
                while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) {
                    buf[--n] = '\0';
                }

                if (strcmp(buf, "open") == 0) {
                    force_open();
                } else if (strcmp(buf, "close") == 0) {
                    force_close();
                } else if (strcmp(buf, "status") == 0) {
                    status_request();
                } else {
                    fprintf(stderr, "Unknown command: %s\n", buf);
                }
            }
            close(client_fd);
        }

        close(server_fd);
    }

    /* Main polling loop */
    while (g_running) {
        uint16_t distance_mm = 0;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            int rc = vl53l1x_read_distance(g_i2c_fd, &distance_mm);
            if (rc == 0) {
                read_ok = 1;
            } else if (rc < 0) {
                fprintf(stderr, "I2C read error (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                usleep(100000);
            } else {
                /* No new data yet, wait a bit */
                usleep(100000);
            }
        }

        if (read_ok) {
            float distance_cm = distance_mm / 10.0f;
            printf("Distance: %.1f cm\n", distance_cm);

            if (distance_cm < DISTANCE_THRESHOLD) {
                servo_set_duty(SERVO_DUTY_OPEN);
                log_event("Object detected, gate opening");
            } else {
                servo_set_duty(SERVO_DUTY_CLOSE);
                log_event("Path clear, gate closing");
            }
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
            log_event("Failed to read distance after retries");
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Cleanup */
    servo_set_duty(SERVO_DUTY_CLOSE);
    log_event("Gate controller shutting down");
    servo_cleanup();
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_fp) fclose(g_log_fp);
    return 0;
}

raw:
/*
 * Gate controller for Raspberry Pi Zero W
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (address 0x29)
 *   - SG90 servo on GPIO18 (BCM) with hardware PWM
 *
 * Build:
 *   gcc -O2 -Wall -o gate_controller gate_controller.c -lm
 *
 * Remote control (v2 callback API):
 *   ./gate_controller --remote
 *   ./gate_controller --remote-port 8080
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x29
#define SERVO_PIN        18
#define SERVO_FREQ       50          /* Hz */
#define SERVO_DUTY_MIN   500         /* us */
#define SERVO_DUTY_MAX   2500        /* us */
#define SERVO_DUTY_OPEN  1500        /* us */
#define SERVO_DUTY_CLOSE 1000        /* us */
#define DISTANCE_THRESHOLD 20        /* cm */
#define LOG_FILE         "gate_log.txt"
#define POLL_INTERVAL_US 500000      /* 0.5 s */
#define MAX_RETRIES      3
#define BOOT_TIMEOUT_MS  2000

/* VL53L1X register addresses */
#define VL53L1X_SOFT_RESET            0x0003
#define VL53L1X_SYSTEM_START          0x0000
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_RESULT_RANGE_STATUS   0x0089
#define VL53L1X_RESULT_DISTANCE       0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *val)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *val)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    uint8_t data[2];
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read16 from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X                                                             */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    /* Software reset */
    if (i2c_write_reg8(fd, VL53L1X_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000); /* 10 ms */
    if (i2c_write_reg8(fd, VL53L1X_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000); /* 10 ms */

    /* Poll for device presence / boot */
    uint8_t status = 0;
    for (int i = 0; i < BOOT_TIMEOUT_MS; i += 50) {
        if (i2c_read_reg8(fd, VL53L1X_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status != 0) break;
        usleep(50000); /* 50 ms */
    }
    if (status == 0) {
        fprintf(stderr, "VL53L1X boot timeout (sensor absent or not responding)\n");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg8(fd, VL53L1X_SYSTEM_START, 0x01) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    if (i2c_read_reg8(fd, VL53L1X_RESULT_INTERRUPT_STATUS, &status) < 0)
        return -1;

    if (status & 0x01) {
        uint16_t dist = 0;
        if (i2c_read_reg16(fd, VL53L1X_RESULT_DISTANCE, &dist) < 0)
            return -1;
        *distance_mm = dist;

        /* Clear interrupt */
        if (i2c_write_reg8(fd, VL53L1X_RESULT_INTERRUPT_STATUS, 0x01) < 0)
            return -1;

        return 0;
    }
    return 1; /* no new data yet */
}

/* ------------------------------------------------------------------ */
/* Servo (hardware PWM via sysfs)                                      */
/* ------------------------------------------------------------------ */
static int servo_init(void)
{
    int ret = 0;
    char path[64];

    /* Export GPIO18 */
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", SERVO_PIN) < 0) {
        fprintf(stderr, "Failed to write GPIO export: %s\n", strerror(errno));
        ret = -1;
    }
    fclose(fp);
    if (ret) return -1;

    /* Wait for sysfs to create the GPIO directory */
    for (int i = 0; i < 10; i++) {
        snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d", SERVO_PIN);
        if (access(path, F_OK) == 0) break;
        usleep(100000);
    }

    /* Set direction to output */
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", SERVO_PIN);
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Configure PWM via sysfs */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/export");
    fp = fopen(path, "w");
    if (!fp) {
        /* May already be exported; ignore EBUSY */
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
            return -1;
        }
    } else {
        if (fprintf(fp, "0") < 0) {
            fprintf(stderr, "Failed to write PWM export: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
        fclose(fp);
    }

    /* Set period (50 Hz -> 20 000 us) */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "20000") < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Set initial duty cycle (closed) */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", SERVO_DUTY_CLOSE) < 0) {
        fprintf(stderr, "Failed to set initial duty cycle: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Enable PWM */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "1") < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    return 0;
}

static void servo_set_duty(int duty_us)
{
    if (duty_us < SERVO_DUTY_MIN) duty_us = SERVO_DUTY_MIN;
    if (duty_us > SERVO_DUTY_MAX) duty_us = SERVO_DUTY_MAX;

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return;
    }
    if (fprintf(fp, "%d", duty_us) < 0) {
        fprintf(stderr, "Failed to set duty cycle: %s\n", strerror(errno));
    }
    fclose(fp);
}

static void servo_cleanup(void)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", SERVO_PIN);
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "in");
        fclose(fp);
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", SERVO_PIN);
        fclose(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Remote control (v2 callback API)                                    */
/* ------------------------------------------------------------------ */
static void force_open(void)
{
    servo_set_duty(SERVO_DUTY_OPEN);
    log_event("Gate opened by remote command");
}

static void force_close(void)
{
    servo_set_duty(SERVO_DUTY_CLOSE);
    log_event("Gate closed by remote command");
}

static void status_request(void)
{
    /* Dummy: always closed (0) */
    printf("Gate status: 0\n");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int remote_mode = 0;
    int remote_port = 8080;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--remote") == 0) {
            remote_mode = 1;
        } else if (strcmp(argv[i], "--remote-port") == 0 && i + 1 < argc) {
            remote_port = atoi(argv[++i]);
            if (remote_port <= 0 || remote_port > 65535) {
                fprintf(stderr, "Invalid port: %s\n", argv[i]);
                return 1;
            }
        } else {
            fprintf(stderr, "Usage: %s [--remote] [--remote-port <port>]\n", argv[0]);
            return 1;
        }
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        return 1;
    }

    /* Initialize I2C */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus");
        fclose(g_log_fp);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    /* Initialize servo */
    if (servo_init() < 0) {
        fprintf(stderr, "Servo initialization failed\n");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    log_event("Gate controller started");

    /* Remote control server (v2 callback API) */
    if (remote_mode) {
        int server_fd = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd < 0) {
            perror("socket");
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        int opt = 1;
        if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
            perror("setsockopt");
            close(server_fd);
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(remote_port);

        if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("bind");
            close(server_fd);
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        if (listen(server_fd, 3) < 0) {
            perror("listen");
            close(server_fd);
            servo_cleanup();
            close(g_i2c_fd);
            fclose(g_log_fp);
            return 1;
        }

        printf("Remote control listening on port %d\n", remote_port);

        while (g_running) {
            int client_fd = accept(server_fd, NULL, NULL);
            if (client_fd < 0) {
                if (errno == EINTR) continue;
                perror("accept");
                break;
            }

            char buf[128];
            ssize_t n = read(client_fd, buf, sizeof(buf) - 1);
            if (n > 0) {
                buf[n] = '\0';
                /* Strip trailing newline */
                while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) {
                    buf[--n] = '\0';
                }

                if (strcmp(buf, "open") == 0) {
                    force_open();
                } else if (strcmp(buf, "close") == 0) {
                    force_close();
                } else if (strcmp(buf, "status") == 0) {
                    status_request();
                } else {
                    fprintf(stderr, "Unknown command: %s\n", buf);
                }
            }
            close(client_fd);
        }

        close(server_fd);
    }

    /* Main polling loop */
    while (g_running) {
        uint16_t distance_mm = 0;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            int rc = vl53l1x_read_distance(g_i2c_fd, &distance_mm);
            if (rc == 0) {
                read_ok = 1;
            } else if (rc < 0) {
                fprintf(stderr, "I2C read error (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                usleep(100000);
            } else {
                /* No new data yet, wait a bit */
                usleep(100000);
            }
        }

        if (read_ok) {
            float distance_cm = distance_mm / 10.0f;
            printf("Distance: %.1f cm\n", distance_cm);

            if (distance_cm < DISTANCE_THRESHOLD) {
                servo_set_duty(SERVO_DUTY_OPEN);
                log_event("Object detected, gate opening");
            } else {
                servo_set_duty(SERVO_DUTY_CLOSE);
                log_event("Path clear, gate closing");
            }
        } else {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
            log_event("Failed to read distance after retries");
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Cleanup */
    servo_set_duty(SERVO_DUTY_CLOSE);
    log_event("Gate controller shutting down");
    servo_cleanup();
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_fp) fclose(g_log_fp);
    return 0;
}

