/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO23 (physical pin 16)
 *   ECHO -> GPIO24 (physical pin 18)  [5 V echo; use voltage divider or level shifter for 3.3 V Pi]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/alert support).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN        23          /* BCM 23, physical pin 16 */
#define ECHO_PIN        24          /* BCM 24, physical pin 18 */

#define SPEED_OF_SOUND  0.0343      /* cm/us (343 m/s) */
#define TRIGGER_PULSE   10          /* us                 */
#define SAMPLE_PERIOD   200         /* ms between samples  */
#define ECHO_TIMEOUT    60          /* ms                  */
#define MIN_PULSE_US    100         /* noise / glitch filter */
#define MAX_PULSE_US    30000       /* ~4 m round trip cap  */

/* Shared state between alert callback and main thread */
static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen = false;
static volatile bool     g_new_reading = false;
static volatile sig_atomic_t g_running = 1;

static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio callback thread)               */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_rising_tick = tick;
        g_echo_seen   = true;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_falling_tick = tick;
        g_new_reading  = true;
    }
    /* level == 2 indicates a watchdog timeout; ignored here */
}

/* ------------------------------------------------------------------ */
/* Distance calculation with 32-bit tick wraparound handling           */
/* ------------------------------------------------------------------ */
static double calculate_distance(uint32_t rising, uint32_t falling)
{
    uint32_t diff = falling - rising;          /* unsigned subtraction wraps correctly */
    return (double)diff * SPEED_OF_SOUND / 2.0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f\n", timestamp, distance);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio initialization ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(50);  /* let line settle */

    /* Register alert callback for both edges */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Warning: could not open distance_log.txt for appending.\n");
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: BCM %d (physical pin 16)\n", TRIG_PIN);
    printf("  ECHO: BCM %d (physical pin 18, 5 V -> level-shifted)\n", ECHO_PIN);
    printf("  Sampling: 5 Hz, logging to distance_log.txt\n");
    printf("  Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /* Reset per-cycle state */
        g_echo_seen   = false;
        g_new_reading = false;

        /* Generate 10 us trigger pulse */
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIGGER_PULSE);
        gpioWrite(TRIG_PIN, 0);

        /* Wait for echo with timeout (ECHO_TIMEOUT ms) */
        uint32_t wait_start = gpioTick();
        while (!g_new_reading && g_running) {
            if ((gpioTick() - wait_start) / 1000 > ECHO_TIMEOUT) {
                break;
            }
            gpioDelay(100);  /* 100 us sleep to avoid busy-waiting */
        }

        if (!g_new_reading) {
            if (g_echo_seen) {
                fprintf(stderr, "Warning: echo timeout (no falling edge within %d ms).\n",
                        ECHO_TIMEOUT);
            } else {
                fprintf(stderr, "Warning: no echo received within %d ms.\n", ECHO_TIMEOUT);
            }
            gpioDelay(SAMPLE_PERIOD * 1000);  /* wait before next trigger */
            continue;
        }

        /* Valid reading available */
        uint32_t rising  = g_rising_tick;
        uint32_t falling = g_falling_tick;

        uint32_t pulse_us = falling - rising;
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: out-of-range pulse %u us (noise/object too far).\n",
                    pulse_us);
            gpioDelay(SAMPLE_PERIOD * 1000);
            continue;
        }

        double distance = calculate_distance(rising, falling);
        log_distance(distance);

        /* Wait for next sample period */
        gpioDelay(SAMPLE_PERIOD * 1000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

