/*
 * Smart Parking Gate — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor
 *       I2C bus 1  (GPIO2 = SDA, GPIO3 = SCL)
 *       Shutdown   -> GPIO23 (BCM)
 *       Interrupt  -> GPIO24 (BCM)
 *   - Servo motor
 *       PWM signal -> GPIO18 (BCM, hardware PWM)
 *
 * Behavior:
 *   - Opens gate when object within 50 cm.
 *   - Closes gate when object outside 60 cm.
 *   - Logs every state change to parking_log.txt.
 *   - Handles sensor absence, I2C errors, and signals.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SHUTDOWN_PIN         23          /* BCM 23 — sensor shutdown */
#define INTERRUPT_PIN        24          /* BCM 24 — sensor interrupt */
#define SERVO_PIN            18          /* BCM 18 — servo PWM */

#define DISTANCE_THRESHOLD_CM  50.0f
#define DISTANCE_HYSTERESIS_CM 60.0f

#define SERVO_OPEN_US         1500       /* ~90° */
#define SERVO_CLOSED_US       500        /* ~0°  */
#define SERVO_STOP_US         0          /* disable PWM */

#define LOG_FILE              "parking_log.txt"
#define POLL_DELAY_US         100000     /* 100 ms */
#define MAX_RETRIES           3

/* VL53L1X register addresses */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK   0x0096
#define VL53L1X_REG_RESULT_DISTANCE          0x0099
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR   0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG  0x0084
#define VL53L1X_REG_SYSTEM_THRESH_HIGH       0x008C
#define VL53L1X_REG_SYSTEM_THRESH_LOW        0x008E

#define VL53L1X_MODEL_ID      0xEA
#define VL53L1X_RANGE_READY   0x01

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* --------------------------- Forward declarations ------------------------ */

static int  vl53l1x_write_reg(uint16_t reg, uint8_t value);
static int  vl53l1x_read_reg(uint16_t reg, uint8_t *buf, uint8_t len);
static int  vl53l1x_init(void);
static int  vl53l1x_read_distance(uint16_t *distance_mm);
static void set_servo(int open);
static void log_event(const char *event, float distance);
static void signal_handler(int sig);
static void cleanup(void);

/* ============================ VL53L1X helpers =========================== */

/*
 * Write a single byte to a 16-bit-addressed VL53L1X register.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_write_reg(uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(g_i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "[VL53L1X] write reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from a 16-bit-addressed VL53L1X register.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_reg(uint16_t reg, uint8_t *buf, uint8_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "[VL53L1X] write addr 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "[VL53L1X] read reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Initialise the VL53L1X sensor.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_init(void)
{
    uint8_t model_id = 0;

    /* Read and verify model ID */
    if (vl53l1x_read_reg(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "[VL53L1X] Cannot read model ID — sensor absent or bus error\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "[VL53L1X] Unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    /* Clear any pending interrupt */
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* Configure interrupt on new sample ready */
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) != 0)
        return -1;

    /* Set thresholds for interrupt-on-change */
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_THRESH_HIGH, 0x0A) != 0)
        return -1;
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_THRESH_LOW,  0x08) != 0)
        return -1;

    /* Start continuous ranging */
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_MODE_START, 0x40) != 0)
        return -1;

    return 0;
}

/*
 * Read the latest distance measurement in mm.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2];

    /* Poll range status */
    if (vl53l1x_read_reg(VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0)
        return -1;

    if ((status & VL53L1X_RANGE_READY) == 0) {
        /* No new sample yet — not an error */
        return 1;
    }

    /* Read 2-byte distance */
    if (vl53l1x_read_reg(VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt so the next measurement can be flagged */
    if (vl53l1x_write_reg(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ================================ Servo ================================= */

static void set_servo(int open)
{
    int pulse_us = open ? SERVO_OPEN_US : SERVO_CLOSED_US;
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "[SERVO] gpioServo failed for pin %d\n", SERVO_PIN);
    }
}

/* ================================ Logging ================================ */

static void log_event(const char *event, float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s - %s - Distance: %.2f cm\n", timestamp, event, distance);
    fflush(g_log_file);
}

/* ============================== Signal / cleanup ========================= */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Stop ranging */
        vl53l1x_write_reg(VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Stop servo PWM */
    gpioServo(SERVO_PIN, SERVO_STOP_US);

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ================================ Main =================================== */

int main(void)
{
    int gate_open = 0;
    int first_read = 1;

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO --- */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set interrupt pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Parking Gate running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(&distance_mm);

        if (rc == 0) {
            float distance_cm = (float)distance_mm / 10.0f;

            if (first_read) {
                gate_open = (distance_cm < DISTANCE_THRESHOLD_CM);
                first_read = 0;
            }

            if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_open) {
                set_servo(1);
                gate_open = 1;
                log_event("Gate opened", distance_cm);
            } else if (distance_cm > DISTANCE_HYSTERESIS_CM && gate_open) {
                set_servo(0);
                gate_open = 0;
                log_event("Gate closed", distance_cm);
            }
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error — attempting re-initialisation\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000); /* 100 ms back-off */
            g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Re-open failed — exiting\n");
                break;
            }
            if (vl53l1x_init() != 0) {
                fprintf(stderr, "Re-init failed — exiting\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

