/*
 * Raspberry Pi 4 Model B – VL53L1X gate controller
 *
 * Polls a VL53L1X ToF sensor on I2C bus 1 every 500 ms, detects an object
 * within 20 cm, and controls a gate relay (GPIO 18 = open, GPIO 19 = close).
 *
 * Build:  gcc -O2 -Wall -Wextra -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 * Run:    sudo ./gate_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* ADDR pin tied to GND */
#define GATE_OPEN_PIN        18            /* Relay IN1 */
#define GATE_CLOSE_PIN       19            /* Relay IN2 */
#define DISTANCE_THRESHOLD_MM 200          /* 20 cm */
#define POLL_INTERVAL_US     500000        /* 500 ms */
#define LOG_FILE             "gate_events.log"

/* --------------------------- VL53L1X registers --------------------------- */
#define VL53L1X_SOFT_RESET_GO2H   0x0003
#define VL53L1X_SOFT_RESET_GO2L   0x0004
#define VL53L1X_SYSTEM_START      0x0000
#define VL53L1X_RESULT_INT_STATUS 0x0014
#define VL53L1X_RESULT_RANGE_STATUS 0x0018
#define VL53L1X_RESULT_DISTANCE   0x0096
#define VL53L1X_RANGE_CONFIG_A    0x005E
#define VL53L1X_RANGE_CONFIG_B    0x0060
#define VL53L1X_RANGE_CONFIG_C    0x0062
#define VL53L1X_RANGE_CONFIG_D    0x0064
#define VL53L1X_RANGE_CONFIG_E    0x0066
#define VL53L1X_RANGE_CONFIG_F    0x0068
#define VL53L1X_RANGE_CONFIG_G    0x006A
#define VL53L1X_RANGE_CONFIG_H    0x006C
#define VL53L1X_RANGE_CONFIG_I    0x006E
#define VL53L1X_RANGE_CONFIG_J    0x0070
#define VL53L1X_RANGE_CONFIG_K    0x0072
#define VL53L1X_RANGE_CONFIG_L    0x0074
#define VL53L1X_RANGE_CONFIG_M    0x0076
#define VL53L1X_RANGE_CONFIG_N    0x0078
#define VL53L1X_RANGE_CONFIG_O    0x007A
#define VL53L1X_RANGE_CONFIG_P    0x007C
#define VL53L1X_RANGE_CONFIG_Q    0x007E
#define VL53L1X_RANGE_CONFIG_R    0x0080
#define VL53L1X_RANGE_CONFIG_S    0x0082
#define VL53L1X_RANGE_CONFIG_T    0x0084
#define VL53L1X_RANGE_CONFIG_U    0x0086
#define VL53L1X_RANGE_CONFIG_V    0x0088
#define VL53L1X_RANGE_CONFIG_W    0x008A
#define VL53L1X_RANGE_CONFIG_X    0x008C
#define VL53L1X_RANGE_CONFIG_Y    0x008E
#define VL53L1X_RANGE_CONFIG_Z    0x0090

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static int  init_vl53l1x(int handle);
static int  read_distance_mm(int handle, uint16_t *distance_mm);
static void control_gate(int distance_mm);
static void log_event(const char *event);
static void log_error(const char *msg);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Helpers --------------------------------- */

/* Write a 16-bit register address and a 16-bit value to the VL53L1X. */
static int vl53l1x_write16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address and a 16-bit value from the VL53L1X. */
static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data_buf, 2) != 2)
        return -1;

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------- VL53L1X --------------------------------- */

/*
 * Initialize the VL53L1X:
 *   1. Soft reset (GO2H then GO2L).
 *   2. Configure timing budget (20 ms).
 *   3. Start ranging.
 */
static int init_vl53l1x(int handle)
{
    uint16_t range_status = 0;
    int      rc;

    /* Soft reset: GO2H then GO2L */
    rc = vl53l1x_write16(handle, VL53L1X_SOFT_RESET_GO2H, 0x0001);
    if (rc < 0) { log_error("VL53L1X soft reset GO2H failed"); return -1; }
    gpioDelay(1000); /* 1 ms */

    rc = vl53l1x_write16(handle, VL53L1X_SOFT_RESET_GO2L, 0x0001);
    if (rc < 0) { log_error("VL53L1X soft reset GO2L failed"); return -1; }
    gpioDelay(1000); /* 1 ms */

    /*
     * Configure timing budget (20 ms).
     * The VL53L1X timing budget register is 0x006B.  We set it to 0x0014
     * (20 ms).  For a 10 ms budget use 0x000A.
     */
    rc = vl53l1x_write16(handle, 0x006B, 0x0014);
    if (rc < 0) { log_error("VL53L1X timing budget write failed"); return -1; }

    /* Start ranging */
    rc = vl53l1x_write16(handle, VL53L1X_SYSTEM_START, 0x0001);
    if (rc < 0) { log_error("VL53L1X system start failed"); return -1; }

    /* Wait for first measurement to be ready */
    for (int i = 0; i < 100; i++) {
        rc = vl53l1x_read16(handle, VL53L1X_RESULT_RANGE_STATUS, &range_status);
        if (rc < 0) {
            log_error("VL53L1X range status read failed");
            return -1;
        }
        if ((range_status & 0x0001) != 0)
            break;
        gpioDelay(10000); /* 10 ms */
    }
    if ((range_status & 0x0001) == 0) {
        log_error("VL53L1X first measurement not ready");
        return -1;
    }

    return 0;
}

/*
 * Read the 16-bit distance register (0x0096).
 * Returns 0 on success, -1 on I2C error.
 */
static int read_distance_mm(int handle, uint16_t *distance_mm)
{
    uint16_t range_status = 0;
    int      rc;

    /* Poll for new data */
    for (int i = 0; i < 100; i++) {
        rc = vl53l1x_read16(handle, VL53L1X_RESULT_RANGE_STATUS, &range_status);
        if (rc < 0) {
            log_error("VL53L1X range status read failed");
            return -1;
        }
        if ((range_status & 0x0001) != 0)
            break;
        gpioDelay(10000); /* 10 ms */
    }
    if ((range_status & 0x0001) == 0) {
        log_error("VL53L1X data not ready");
        return -1;
    }

    rc = vl53l1x_read16(handle, VL53L1X_RESULT_DISTANCE, distance_mm);
    if (rc < 0) {
        log_error("VL53L1X distance read failed");
        return -1;
    }

    return 0;
}

/* ------------------------------- Gate logic ------------------------------ */

static void control_gate(int distance_mm)
{
    if (distance_mm > 0 && distance_mm < DISTANCE_THRESHOLD_MM) {
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
        log_event("Gate OPEN");
    } else {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
        log_event("Gate CLOSE");
    }
}

/* ------------------------------- Logging --------------------------------- */

static void log_event(const char *event)
{
    time_t     rawtime;
    struct tm  tm_utc;
    char       timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_utc);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (g_log_file) {
        fprintf(g_log_file, "%s %s\n", timestamp, event);
        fflush(g_log_file);
    }
    printf("%s %s\n", timestamp, event);
}

static void log_error(const char *msg)
{
    time_t     rawtime;
    struct tm  tm_utc;
    char       timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_utc);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (g_log_file) {
        fprintf(g_log_file, "%s ERROR: %s\n", timestamp, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s ERROR: %s\n", timestamp, msg);
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Stop ranging */
        vl53l1x_write16(g_i2c_handle, VL53L1X_SYSTEM_START, 0x0000);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Reset GPIO pins */
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioSetMode(GATE_OPEN_PIN, PI_INPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_INPUT);

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------- Signals --------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    uint16_t distance_mm;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    gpioSetMode(GATE_OPEN_PIN,   PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN,  PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_vl53l1x(g_i2c_handle) < 0) {
        log_error("VL53L1X initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Gate controller started");

    /* Main polling loop */
    while (g_running) {
        if (read_distance_mm(g_i2c_handle, &distance_mm) == 0) {
            control_gate((int)distance_mm);
        } else {
            log_error("Failed to read distance");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Gate controller stopping");
    cleanup();
    return EXIT_SUCCESS;
}

