/*
 * Raspberry Pi 4 Model B – VL53L1X distance-controlled motor controller
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Motor +     -> GPIO17 (forward)
 *   Motor -     -> GPIO18 (backward)
 *   Trigger     -> GPIO24 (rising edge = new measurement)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* default 7-bit I2C address       */
#define MOTOR_FORWARD_PIN    17
#define MOTOR_BACKWARD_PIN   18
#define TRIGGER_PIN          24

#define DISTANCE_THRESHOLD_1 100           /* mm – below  -> forward          */
#define DISTANCE_THRESHOLD_2 300           /* mm – above  -> backward         */

#define I2C_RETRY_COUNT      3
#define I2C_RETRY_DELAY_US   1000          /* 1 ms backoff between retries    */
#define MEASUREMENT_POLL_US  5000          /* 5 ms poll interval while waiting*/
#define MEASUREMENT_TIMEOUT  100           /* 500 ms timeout                  */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET            0x0003
#define VL53L1X_REG_SYSTEM_START          0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS   0x0089
#define VL53L1X_REG_RESULT_DISTANCE       0x0096

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void motor_stop(void);
static void motor_forward(void);
static void motor_backward(void);
static void control_motor(uint16_t distance_mm);
static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);

/* ----------------------------- I2C helpers ------------------------------- */

/* Write one byte to a 16-bit register address. */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[I2C] write reg 0x%04X failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, I2C_RETRY_COUNT);
        if (attempt < I2C_RETRY_COUNT - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* Read `len` bytes from a 16-bit register address. */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, addr_buf, 2);
        if (rc != 0) {
            fprintf(stderr, "[I2C] write addr 0x%04X failed (rc=%d), attempt %d/%d\n",
                    reg, rc, attempt + 1, I2C_RETRY_COUNT);
            if (attempt < I2C_RETRY_COUNT - 1)
                gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }
        rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "[I2C] read reg 0x%04X failed (rc=%d, expected %u), attempt %d/%d\n",
                reg, rc, len, attempt + 1, I2C_RETRY_COUNT);
        if (attempt < I2C_RETRY_COUNT - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ----------------------------- VL53L1X driver ----------------------------- */

/*
 * Initialise the VL53L1X:
 *   1. Soft reset (write 0x00 to SOFT_RESET)
 *   2. Wait 1 ms for the device to recover
 *   3. Start continuous ranging (write 0x01 to SYSTEM_START)
 *
 * Returns 0 on success, -1 on failure.
 */
static int vl53l1x_init(int handle)
{
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "[VL53L1X] soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000);                       /* 1 ms recovery                  */

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "[VL53L1X] start ranging write failed\n");
        return -1;
    }
    return 0;
}

/*
 * Read a single distance measurement.
 *   1. Trigger a single-shot measurement by writing 0x01 to SYSTEM_START
 *   2. Poll RESULT_RANGE_STATUS (bit 0 = data-ready) until set or timeout
 *   3. Read 2 bytes from RESULT_DISTANCE
 *
 * Returns 0 on success and stores the distance in `distance_mm`; -1 on
 * failure (sensor absent, I2C error, or timeout).
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "[VL53L1X] trigger write failed\n");
        return -1;
    }

    uint8_t status = 0;
    for (int i = 0; i < MEASUREMENT_TIMEOUT; i++) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) {
            fprintf(stderr, "[VL53L1X] status read failed\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(MEASUREMENT_POLL_US);
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "[VL53L1X] measurement timeout (status=0x%02X)\n", status);
        return -1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0) {
        fprintf(stderr, "[VL53L1X] distance read failed\n");
        return -1;
    }
    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

/* ----------------------------- Motor control ----------------------------- */

static void motor_stop(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: STOP\n");
}

static void motor_forward(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: FORWARD\n");
}

static void motor_backward(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: BACKWARD\n");
}

static void control_motor(uint16_t distance_mm)
{
    if (distance_mm < DISTANCE_THRESHOLD_1)
        motor_forward();
    else if (distance_mm > DISTANCE_THRESHOLD_2)
        motor_backward();
    else
        motor_stop();
}

/* ----------------------------- Callbacks --------------------------------- */

static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)tick; (void)userdata;
    if (level != 1)            /* only rising edge */
        return;

    uint16_t distance_mm = 0;
    if (vl53l1x_read_distance(g_i2c_handle, &distance_mm) == 0) {
        printf("Distance: %u mm\n", distance_mm);
        control_motor(distance_mm);
    } else {
        fprintf(stderr, "[CB] sensor read failed – stopping motor\n");
        motor_stop();
    }
}

/* ----------------------------- Signal handling ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d) – sensor may be absent\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);   /* active-low trigger */

    motor_stop();

    /* --- ISR --- */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X motor control running. Ctrl+C to exit.\n");

    /* --- Main loop – sleep until signal --- */
    while (g_running)
        gpioDelay(100000);   /* 100 ms */

    /* --- Cleanup --- */
    gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL);  /* unregister ISR */
    motor_stop();
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

