/*
 * MPR121 Proximity Interactive Art Installation
 * Board:  Raspberry Pi 3 Model B+
 * I2C:    /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * LEDs:   GPIO17, GPIO18, GPIO27, GPIO22 (BCM)
 *
 * Build:  gcc -O2 -Wall -o mpr121_art mpr121_art.c -lpigpio -lrt
 * Run:    sudo ./mpr121_art
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- MPR121 I2C ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5C          /* ADDR pin tied to GND */

/* ---- MPR121 Register Map ---- */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_MHDF           0x2F
#define MPR121_NHDF           0x30
#define MPR121_NCLF           0x31
#define MPR121_FDLF           0x32
#define MPR121_NHDT           0x33
#define MPR121_NCLT           0x34
#define MPR121_FDLT           0x35
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E

/* ---- GPIO ---- */
#define LED_0_PIN 17
#define LED_1_PIN 18
#define LED_2_PIN 27
#define LED_3_PIN 22

/* ---- Timing ---- */
#define POLL_DELAY_US  50000   /* 50 ms */
#define LOG_FILE       "mpr121_art.log"

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- MPR121 init ---- */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* Verify device presence by reading back ECR */
    uint8_t ecr_val = 0;
    if (i2c_read_reg(fd, MPR121_ECR, &ecr_val) < 0)
        return -1;
    if (ecr_val != 0x00) {
        fprintf(stderr, "MPR121 not responding (ECR=0x%02X, expected 0x00)\n", ecr_val);
        return -1;
    }

    /* Rising / falling filter defaults */
    if (i2c_write_reg(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDF, 0x05) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg(fd, MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (i2c_write_reg(fd, MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for both touch and release */
    if (i2c_write_reg(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=00 (6 samples), CDC=16 µA, CDT=0.5 µs */
    if (i2c_write_reg(fd, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT=0.5 µs, SFI=4 samples, ESI=4 ms */
    if (i2c_write_reg(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (i2c_write_reg(fd, MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

/* ---- Read touch status ---- */
static int mpr121_read_touch(int fd, uint16_t *status)
{
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ---- LED pattern ---- */
static void set_led_pattern(uint8_t pattern)
{
    gpioWrite(LED_0_PIN, (pattern >> 0) & 1);
    gpioWrite(LED_1_PIN, (pattern >> 1) & 1);
    gpioWrite(LED_2_PIN, (pattern >> 2) & 1);
    gpioWrite(LED_3_PIN, (pattern >> 3) & 1);
}

/* ---- Logging ---- */
static void log_event(uint8_t electrode)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s - Electrode %u touched\n", ts, electrode);
    fflush(g_log_fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Turn off LEDs and terminate pigpio */
    gpioWrite(LED_0_PIN, 0);
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioWrite(LED_3_PIN, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIOs */
    if (gpioSetMode(LED_0_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_3_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_0_PIN, 0);
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioWrite(LED_3_PIN, 0);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 proximity art running. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch(g_i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                set_led_pattern((uint8_t)(i + 1));
                log_event((uint8_t)i);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
