/*
 * MPR121 Capacitive Touch Proximity Detector for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MPR121 on I2C bus 1, address 0x5C (ADDR pin tied to GND)
 *   - LED on GPIO 27 (BCM)
 *
 * Behavior:
 *   - Reads the device ID to verify the sensor is present.
 *   - Configures the MPR121 for touch detection (FFI=1, SFI=12, ESI=1).
 *   - Monitors the 12 touch inputs for a proximity event.
 *   - When a proximity event is detected, lights the LED for 1 second,
 *     logs the event with a timestamp to proximity.log, and continues
 *     monitoring.
 *   - Handles I2C errors and SIGINT/SIGTERM for clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR        0x5C
#define LED_GPIO           27
#define LOG_FILE           "proximity.log"
#define POLL_DELAY_US      10000   /* 10 ms */
#define LED_ON_DURATION_US 1000000 /* 1 second */

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ECR            0x5E
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR_ENABLE     0x8F
#define MPR121_SOFTRESET      0x80

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(g_i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error: I2C write failed (reg=0x%02X, val=0x%02X)\n",
                reg, value);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPR121 initialization                                               */
/* ------------------------------------------------------------------ */
static int mpr121_init(void)
{
    uint8_t device_id = 0;

    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Read and verify device ID (should be 0x12 for MPR121) */
    if (mpr121_read_reg(0x5C, &device_id) < 0)
        return -1;
    if (device_id != 0x12) {
        fprintf(stderr, "Error: Unexpected device ID 0x%02X (expected 0x12)\n",
                device_id);
        return -1;
    }

    /* Baseline filtering: CONFIG1 = 0x10 (baseline tracking) */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0)
        return -1;

    /* Debounce: 3 samples for touch and release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0)
        return -1;

    /* AFE configuration: FFI=1, SFI=12, ESI=1 */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0)
        return -1;

    /* Enable all 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ECR, MPR121_ECR_ENABLE) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read touch status                                                   */
/* ------------------------------------------------------------------ */
static int mpr121_read_touch_status(uint16_t *touch_status)
{
    uint8_t low = 0, high = 0;

    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &low) < 0)
        return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &high) < 0)
        return -1;

    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log proximity event                                                 */
/* ------------------------------------------------------------------ */
static void log_proximity_event(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Proximity detected\n",
                tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
                tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec);
    } else {
        fprintf(fp, "[timestamp error] - Proximity detected\n");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Disable electrodes */
        i2cWriteByteData(g_i2c_handle, MPR121_ECR, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus 1 at MPR121 address */
    g_i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n",
                MPR121_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 proximity detector running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Check if any of the 12 electrodes are touched */
        if (touch_status & 0x0FFF) {
            printf("Proximity detected!\n");
            log_proximity_event();

            /* Turn LED on for 1 second */
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_DURATION_US);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

