/*
 * HC-SR04 ultrasonic distance measurement on a Raspberry Pi Zero W.
 *
 * Wiring:
 *   VCC  -> 5 V (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO17 (BCM 17, pin 11)
 *   ECHO -> GPIO18 (BCM 18, pin 12)  [3.3 V-tolerant on Pi Zero W]
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define SPEED_OF_SOUND   343.0          /* m/s at 20 C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define ECHO_TIMEOUT_US  30000          /* 30 ms */
#define TRIGGER_PULSE_US 10
#define TRIGGER_LOW_US   5
#define SAMPLE_PERIOD_S  1
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout, -2 on read error.
 */
static long measure_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* --- Wait for echo rising edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    for (;;) {
        int v = gpioRead(ECHO_PIN);
        if (v < 0) {
            fprintf(stderr, "Error: gpioRead(ECHO) failed\n");
            return -2;
        }
        if (v == 1) {
            start_tick = gpioTick();
            break;
        }
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo never went high (sensor absent or wiring fault)\n");
            return -1;
        }
        gpioDelay(100);
    }

    /* --- Wait for echo falling edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    for (;;) {
        int v = gpioRead(ECHO_PIN);
        if (v < 0) {
            fprintf(stderr, "Error: gpioRead(ECHO) failed\n");
            return -2;
        }
        if (v == 0) {
            end_tick = gpioTick();
            break;
        }
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo pulse exceeded %d us\n", ECHO_TIMEOUT_US);
            return -1;
        }
        gpioDelay(100);
    }

    return (long)(end_tick - start_tick);
}

static float calculate_distance_cm(long pulse_us)
{
    /* distance = (pulse_us * speed) / 2 / 1e6  (round-trip) */
    return (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;
}

static void log_distance(FILE *fp, float distance_cm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "Error: gmtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, distance_cm) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
    }
}

int main(void)
{
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        goto cleanup_gpio;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        goto cleanup_gpio;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        goto cleanup_gpio;
    }
    gpioDelay(5000);  /* 5 ms settle */

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        goto cleanup_gpio;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        /* --- Issue 10 us trigger pulse --- */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
            break;
        }
        gpioDelay(TRIGGER_LOW_US);  /* 5 us low before next trigger */

        /* --- Measure echo --- */
        long pulse_us = measure_echo_us();
        if (pulse_us < 0) {
            /* Timeout or read error already reported; wait and retry */
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* --- Validate range --- */
        float distance_cm = calculate_distance_cm(pulse_us);
        if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
            fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f-%.0f], skipping\n",
                    distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* --- Log --- */
        log_distance(fp, distance_cm);

        /* --- Wait for next sample --- */
        sleep(SAMPLE_PERIOD_S);
    }

    rc = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (fp != NULL) {
        fclose(fp);
    }

cleanup_gpio:
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    if (rc == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return rc;
}

