/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi Zero W
 *
 * Wiring:
 *   VCC  -> 5V  (Pin 2)
 *   GND  -> GND (Pin 6)
 *   TRIG -> GPIO17 (Pin 11)
 *   ECHO -> GPIO18 (Pin 12) via 1k/2k voltage divider (5.6k total)
 *
 * The voltage divider keeps the Pi input at ~3.3V during echo pulses
 * at distances up to ~4 m.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN      17
#define ECHO_PIN      18
#define LOG_FILE      "distance_log.txt"
#define TRIGGER_US    10          /* 10 us trigger pulse width            */
#define SAMPLE_PERIOD 1000000     /* 1 second between measurements        */
#define ECHO_TIMEOUT  30000       /* 30 ms max echo wait (5.6k divider)   */
#define MIN_PULSE_US  58          /* ~1 cm  (58 us at ~343 m/s/V)         */
#define MAX_PULSE_US  25000       /* ~4 m   (25 ms at ~343 m/s/V)         */
#define SOUND_SPEED   0.0343      /* m/s/V at 20 C                        */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_done  = false;
static volatile bool     g_running    = true;
static FILE             *g_log_fp     = NULL;

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio thread context                        */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge — start of echo pulse */
        g_start_tick = tick;
        g_echo_done  = false;
    } else if (level == 0) {
        /* Falling edge — end of echo pulse */
        g_end_tick = tick;
        g_echo_done = true;
    }
    /* level == 2 (timeout) is ignored here; handled in main loop */
}

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Compute pulse width with tick wrap-around handling                  */
/* ------------------------------------------------------------------ */
static uint32_t pulse_width_us(uint32_t start, uint32_t end)
{
    return end - start;          /* pigpio ticks are 32-bit microseconds */
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (us) to distance (m)                            */
/* ------------------------------------------------------------------ */
static float pulse_to_distance_m(uint32_t pulse_us)
{
    return (float)pulse_us * SOUND_SPEED / 2.0f / 1000000.0f;
}

/* ------------------------------------------------------------------ */
/* Append a reading to the log file                                    */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, float distance_m)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s, Distance: %.2f m\n", ts, distance_m) < 0) {
        perror("fprintf to log file");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Disable ISR before terminating pigpio */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output.\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(50);                 /* 50 us settle */

    /* ---- Register ISR on both edges of ECHO ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: cannot register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, log=%s\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset state for this cycle */
        g_echo_done = false;
        g_start_tick = 0;
        g_end_tick   = 0;

        /* Generate 10 us trigger pulse */
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(TRIGGER_US);
        gpioWrite(TRIG_PIN, 0);

        /* Wait for echo with timeout (30 ms) */
        uint32_t waited = 0;
        while (!g_echo_done && waited < ECHO_TIMEOUT && g_running) {
            gpioDelay(100);       /* 100 us granularity */
            waited += 100;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_done) {
            fprintf(stderr, "Warning: echo timeout (no object or out of range).\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        uint32_t pulse_us = pulse_width_us(g_start_tick, g_end_tick);

        if (pulse_us == 0) {
            fprintf(stderr, "Warning: zero-length pulse (spurious).\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse %u us out of valid range [%u-%u].\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        float distance_m = pulse_to_distance_m(pulse_us);

        if (log_distance(g_log_fp, distance_m) != 0) {
            fprintf(stderr, "Warning: failed to log distance.\n");
        }

        printf("Distance: %.2f m\n", distance_m);

        /* Wait for next sample period */
        gpioDelay(SAMPLE_PERIOD);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

