/*
 * VL53L1X ToF sensor reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA, physical pin 3)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL, physical pin 5)
 *   VL53L1X XSHUT -> GPIO27 (BCM 27, physical pin 13)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_reader vl53l1x_reader.c -li2c -lpigpio -lrt
 *
 * Run:
 *   sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- VL53L1X constants (from datasheet / datasheet-derived headers) ---- */
#define VL53L1X_ADDR             0x29
#define VL53L1X_XSHUT_PIN        27          /* BCM 27 */
#define VL53L1X_I2C_BUS          1

#define REG_SOFT_RESET           0x0003
#define REG_SYSTEM_MODE_START    0x0000
#define REG_RESULT_INTERRUPT     0x0044
#define REG_RESULT_RANGE_STATUS  0x0089
#define REG_RESULT_DISTANCE      0x0096

#define SOFT_RESET_VALUE         0x00
#define SYSTEM_MODE_START_VALUE  0x01

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address and a single byte of data.          */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write failed (reg 0x%04X, val 0x%02X): %s",
               reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a 16-bit register address.                  */
/* Returns 0 on success and stores the value in *out; -1 on failure.   */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    char data;

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        syslog(LOG_ERR, "I2C write (addr) failed (reg 0x%04X): %s",
               reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, &data, 1) != 1) {
        syslog(LOG_ERR, "I2C read failed (reg 0x%04X): %s",
               reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)data;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from a 16-bit register.           */
/* Returns 0 on success and stores the value in *out; -1 on failure.   */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char buf[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        syslog(LOG_ERR, "I2C write (addr) failed (reg 0x%04X): %s",
               reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read failed (reg 0x%04X): %s",
               reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor.                                      */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t status = 0;

    /* Soft reset */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, SOFT_RESET_VALUE) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (vl53l1x_write_byte(handle, REG_RESULT_INTERRUPT, 0x00) != 0)
        return -1;

    /* Start continuous ranging */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_MODE_START,
                           SYSTEM_MODE_START_VALUE) != 0)
        return -1;

    /* Verify the sensor is responding by reading the range status */
    if (vl53l1x_read_byte(handle, REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;

    syslog(LOG_INFO, "VL53L1X initialised (range status = 0x%02X)", status);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the distance in millimetres.                                   */
/* Returns 0 on success and stores the distance in *distance_mm;       */
/* -1 on failure.                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t dist = 0;

    /* Poll the interrupt register to check for new data */
    if (vl53l1x_read_byte(handle, REG_RESULT_INTERRUPT, &status) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data yet — not an error, just skip this cycle */
        return 1;
    }

    /* Read the distance */
    if (vl53l1x_read_word(handle, REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear the interrupt so the next measurement can be flagged */
    if (vl53l1x_write_byte(handle, REG_RESULT_INTERRUPT, 0x01) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting VL53L1X reader (I2C bus %d, addr 0x%02X)",
           VL53L1X_I2C_BUS, VL53L1X_ADDR);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- XSHUT pin as output, default LOW (sensor disabled) ---- */
    if (gpioSetMode(VL53L1X_XSHUT_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", VL53L1X_XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VL53L1X_XSHUT_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO%d", VL53L1X_XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(VL53L1X_I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus %d, addr 0x%02X): %s",
               VL53L1X_I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed — sensor may be absent");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Enable the sensor (active-low XSHUT) ---- */
    if (gpioWrite(VL53L1X_XSHUT_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d high", VL53L1X_XSHUT_PIN);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "VL53L1X reader running — polling every 100 ms");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            syslog(LOG_INFO, "%s Distance: %u mm", ts, distance);
        } else if (rc < 0) {
            syslog(LOG_ERR, "Distance read error — continuing");
        }
        /* rc == 1 means no new data — just wait */

        gpioDelay(100000); /* 100 ms */
    }

    /* ---- Cleanup ---- */
    syslog(LOG_INFO, "Shutting down VL53L1X reader");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(VL53L1X_XSHUT_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

