    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read failed (reg 0x%04X): %s",
               reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor.                                      */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t status = 0;

    /* Soft reset */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, SOFT_RESET_VALUE) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (vl53l1x_write_byte(handle, REG_RESULT_INTERRUPT, 0x00) != 0)
        return -1;

    /* Start continuous ranging */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_MODE_START,
                           SYSTEM_MODE_START_VALUE) != 0)
        return -1;

    /* Verify the sensor is responding by reading the range status */
    if (vl53l1x_read_byte(handle, REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;

    syslog(LOG_INFO, "VL53L1X initialised (range status = 0x%02X)", status);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the distance in millimetres.                                   */
/* Returns 0 on success and stores the distance in *distance_mm;       */
/* -1 on failure.                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t dist = 0;

    /* Poll the interrupt register to check for new data */
    if (vl53l1x_read_byte(handle, REG_RESULT_INTERRUPT, &status) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data yet — not an error, just skip this cycle */
        return 1;
    }

    /* Read the distance */
    if (vl53l1x_read_word(handle, REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear the interrupt so the next measurement can be flagged */
    if (vl53l1x_write_byte(handle, REG_RESULT_INTERRUPT, 0x01) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting VL53L1X reader (I2C bus %d, addr 0x%02X)",
           VL53L1X_I2C_BUS, VL53L1X_ADDR);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- XSHUT pin as output, default LOW (sensor disabled) ---- */
    if (gpioSetMode(VL53L1X_XSHUT_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", VL53L1X_XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VL53L1X_XSHUT_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO%d", VL53L1X_XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(VL53L1X_I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus %d, addr 0x%02X): %s",
               VL53L1X_I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed — sensor may be absent");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Enable the sensor (active-low XSHUT) ---- */
    if (gpioWrite(VL53L1X_XSHUT_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d high", VL53L1X_XSHUT_PIN);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "VL53L1X reader running — polling every 100 ms");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            syslog(LOG_INFO, "%s Distance: %u mm", ts, distance);
        } else if (rc < 0) {
            syslog(LOG_ERR, "Distance read error — continuing");
        }
        /* rc == 1 means no new data — just wait */

        gpioDelay(100000); /* 100 ms */
    }

    /* ---- Cleanup ---- */
    syslog(LOG_INFO, "Shutting down VL53L1X reader");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(VL53L1X_XSHUT_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

