#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20.0f
#define POLL_INTERVAL_US 100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_MODE 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static int write_reg16(int handle, uint16_t reg, uint8_t val) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)val };
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *val) {
    char addr[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, addr, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)val, 1);
}

static int read_reg16_16bit(int handle, uint16_t reg, uint16_t *val) {
    char addr[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, addr, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *val = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_sensor(int handle) {
    if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        log_message("Error: soft reset write failed");
        return -1;
    }
    gpioDelay(10000);
    if (write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        log_message("Error: soft reset release failed");
        return -1;
    }
    gpioDelay(10000);
    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) {
        log_message("Error: mode set failed");
        return -1;
    }
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm) {
    uint8_t status = 0;
    uint16_t dist_mm = 0;

    if (write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, 0x01) < 0) {
        log_message("Error: start ranging failed");
        return -1;
    }

    for (int i = 0; i < 50; i++) {
        gpioDelay(10000);
        if (read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
            log_message("Error: reading range status failed");
            return -1;
        }
        if (status & 0x01) break;
    }

    if (!(status & 0x01)) {
        log_message("Error: ranging timeout");
        return -1;
    }

    if (read_reg16_16bit(handle, VL53L1X_REG_RESULT_DISTANCE, &dist_mm) < 0) {
        log_message("Error: reading distance failed");
        return -1;
    }

    *distance_cm = (float)dist_mm / 10.0f;
    return 0;
}

static void control_gate(int gpio, float distance_cm) {
    static bool gate_open = false;
    bool should_open = (distance_cm < DISTANCE_THRESHOLD);

    if (should_open && !gate_open) {
        gpioWrite(gpio, 1);
        log_message("Gate opened");
        gate_open = true;
    } else if (!should_open && gate_open) {
        gpioWrite(gpio, 0);
        log_message("Gate closed");
        gate_open = false;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    while (running) {
        float distance_cm = 0.0f;
        if (read_distance_cm(i2c_handle, &distance_cm) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_message(msg);
            control_gate(GATE_GPIO, distance_cm);
        } else {
            log_message("Error reading distance");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    log_message("Shutting down");
    gpioWrite(GATE_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

