/*
 * HC-SR04 ultrasonic distance measurement with SG90 servo panning.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained, actively maintained)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   SG90 signal  -> GPIO18 (BCM, hardware PWM-capable)
 *
 * Build:  gcc -O2 -Wall -o distance_servo distance_servo.c -lpigpio -lrt
 * Run:    sudo ./distance_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define TRIGGER_PIN        23          /* BCM 23 - HC-SR04 TRIG */
#define ECHO_PIN           24          /* BCM 24 - HC-SR04 ECHO */
#define SERVO_PIN          18          /* BCM 18 - SG90 signal  */

#define TRIGGER_PULSE_US   10          /* 10 µs trigger pulse  */
#define ECHO_TIMEOUT_US    30000       /* 30 ms echo timeout   */
#define SAMPLE_PERIOD_US   100000      /* 100 ms between reads */
#define MAX_DISTANCE_CM    400.0f      /* HC-SR04 rated max    */
#define MIN_DISTANCE_CM    2.0f        /* HC-SR04 rated min    */
#define DEFAULT_SERVO_ANGLE 90         /* degrees (center)     */
#define MOVING_AVG_WINDOW  5

/* ----------------------------- Shared state ------------------------------ */

static volatile uint32_t g_pulse_width = 0;
static volatile bool     g_new_pulse   = false;
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Prototypes -------------------------------- */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata);
static float measure_distance(void);
static float moving_average(float new_value, float *window, int *index, int size);
static void log_data(float distance, int servo_angle);
static void signal_handler(int sig);

/* ----------------------------- Echo callback ----------------------------- */

/*
 * pigpio dispatches this on a dedicated thread, so we keep it minimal:
 *   - record the pulse width (tick difference, handling 32-bit wrap)
 *   - set the new-pulse flag
 *   - clear the trigger so the next measurement starts cleanly
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {                       /* rising edge  -> echo start */
        static uint32_t start_tick = 0;
        start_tick = tick;
    } else if (level == 0) {                /* falling edge -> echo end  */
        uint32_t end_tick = tick;
        uint32_t width;

        /* pigpio ticks are 32-bit microseconds; handle wrap-around */
        if (end_tick >= start_tick) {
            width = end_tick - start_tick;
        } else {
            width = (0xFFFFFFFFu - start_tick) + end_tick + 1u;
        }

        g_pulse_width = width;
        g_new_pulse   = true;

        /* Ensure trigger is low before next cycle */
        gpioWrite(TRIGGER_PIN, 0);
    }
}

/* ----------------------------- Distance measurement ---------------------- */

static float measure_distance(void)
{
    g_new_pulse = false;
    g_pulse_width = 0;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* 10 µs trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0f;
    }

    /* Wait for the echo callback to set the flag or timeout */
    uint32_t waited = 0;
    while (!g_new_pulse && waited < ECHO_TIMEOUT_US && g_running) {
        gpioDelay(100);                     /* 100 µs granularity */
        waited += 100;
    }

    if (!g_running) {
        return -1.0f;
    }

    if (!g_new_pulse) {
        fprintf(stderr, "Warning: echo timeout (no echo within %u µs)\n",
                ECHO_TIMEOUT_US);
        return -1.0f;
    }

    uint32_t width = g_pulse_width;
    g_new_pulse = false;

    /* distance = (pulse_us * 34300 cm/s) / 2 / 1e6 */
    float distance = (float)width * 0.01715f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f-%.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ----------------------------- Moving average ---------------------------- */

static float moving_average(float new_value, float *window, int *index, int size)
{
    window[*index] = new_value;
    *index = (*index + 1) % size;

    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += window[i];
    }
    return sum / (float)size;
}

/* ----------------------------- Data logging ------------------------------ */

static void log_data(float distance, int servo_angle)
{
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening distance_log.csv");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n",
            tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
            tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
            distance, servo_angle);

    fflush(fp);
    fclose(fp);
}

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);

    /* ---- Register echo interrupt callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register signal handler ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open CSV file with header ---- */
    FILE *fp = fopen("distance_log.csv", "w");
    if (fp == NULL) {
        perror("Error opening distance_log.csv for writing");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,distance_cm,servo_angle_deg\n");
    fclose(fp);

    /* ---- Moving average window ---- */
    float window[MOVING_AVG_WINDOW] = {0.0f};
    int   window_index = 0;

    /* ---- Main loop ---- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: invalid distance reading, setting servo to %d\n",
                    DEFAULT_SERVO_ANGLE);
            if (gpioServo(SERVO_PIN, DEFAULT_SERVO_ANGLE) < 0) {
                fprintf(stderr, "Error: gpioServo failed\n");
            }
            log_data(-1.0f, DEFAULT_SERVO_ANGLE);
        } else {
            float filtered = moving_average(distance, window, &window_index,
                                            MOVING_AVG_WINDOW);

            int servo_angle = (int)(filtered / 50.0f * 180.0f);
            if (servo_angle < 0)            servo_angle = 0;
            if (servo_angle > 180)          servo_angle = 180;

            if (gpioServo(SERVO_PIN, servo_angle) < 0) {
                fprintf(stderr, "Error: gpioServo(%d) failed\n", servo_angle);
            }

            log_data(filtered, servo_angle);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    fprintf(stderr, "\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);                /* stop servo PWM */
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); /* unregister callback */
    gpioTerminate();

    return EXIT_SUCCESS;
}

