raw:
/*
 * VL53L1X Time-of-Flight Distance Monitor with LED Warning
 * Board:  Raspberry Pi 4 Model B
 * I2C:    Bus 1, VL53L1X default address 0x29
 * LED:    GPIO17 (BCM), active-high warning indicator
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_monitor vl53l1x_monitor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* default 7-bit I2C address      */
#define LED_GPIO             17            /* BCM pin for warning LED        */
#define DISTANCE_THRESHOLD   200           /* mm — warning triggers below    */
#define BUFFER_SIZE          10
#define SAMPLE_PERIOD_US     50000         /* 50 ms between readings         */

/* ------------------------ VL53L1X register map ------------------------- */
#define REG_SOFT_RESET       0x0000
#define REG_SYSTEM_START     0x0001
#define REG_SYSTEM_SEQUENCE  0x0002
#define REG_SYSTEM_INTERRUPT 0x000A
#define REG_SYSTEM_STATUS    0x0013
#define REG_RESULT_INTERRUPT 0x0044
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE  0x0096

#define REG_I2C_SLAVE_DEVICE 0x0001
#define REG_I2C_SLAVE_ADDR   0x0002

#define REG_SYSTEM_THRESH_HIGH 0x0010
#define REG_SYSTEM_THRESH_LOW  0x0011

#define REG_SYSTEM_CONFIG    0x001B
#define REG_SYSTEM_INTERMEAS 0x001E
#define REG_SYSTEM_RANGE_CONFIG 0x001F
#define REG_SYSTEM_RANGE_START  0x0080
#define REG_SYSTEM_RANGE_END    0x0081
#define REG_SYSTEM_RANGE_TIMEOUT 0x0082

#define REG_SYSTEM_CONFIG_GPIO 0x0030
#define REG_SYSTEM_CONFIG_GPIO_TIO 0x0031

#define REG_PHASECAL_CONFIG  0x0032
#define REG_MSRC_CONFIG      0x0060
#define REG_FINAL_CONFIG     0x0061
#define REG_SIGMA_EST        0x0062
#define REG_CROSSTALK_CONFIG 0x0063
#define REG_MSRC_CONFIG_2    0x0064
#define REG_PRE_RANGE_CONFIG 0x0070
#define REG_FINAL_RANGE_CONFIG 0x0071
#define REG_PRE_RANGE_HIST_BINS 0x0072
#define REG_FINAL_RANGE_HIST_BINS 0x0073
#define REG_PRE_RANGE_SIGMA_TH 0x0074
#define REG_FINAL_RANGE_SIGMA_TH 0x0075
#define REG_PRE_RANGE_MIN_COUNT_RATE 0x0076
#define REG_FINAL_RANGE_MIN_COUNT_RATE 0x0077

/* ----------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_pigpio_inited = false;

/* Circular buffer */
typedef struct {
    int    data[BUFFER_SIZE];
    int    head;
    int    count;
} CircularBuffer;

static CircularBuffer g_buffer;

/* --------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  init_vl53l1x(int handle);
static int  read_distance(int handle);
static void buffer_add(int value);
static void led_set(int on);
static void cleanup(void);

/* --------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* --------------------------- VL53L1X init ------------------------------ */
static int init_vl53l1x(int handle)
{
    /*
     * STMicroelectronics recommended initialization sequence.
     * Each write is checked for success; on failure we return -1.
     */
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: soft reset release failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for device to stabilize */

    /*
     * Set I2C slave device address (0x29).
     * The VL53L1X supports a dynamic address; the default is 0x29.
     */
    if (i2c_write_reg16(handle, REG_I2C_SLAVE_DEVICE, 0x29) < 0) {
        fprintf(stderr, "Error: failed to set I2C slave device\n");
        return -1;
    }

    /*
     * Configure GPIO15 as interrupt output (active high).
     * Bits [1:0] of REG_SYSTEM_CONFIG_GPIO select the GPIO function;
     * bit 0 of REG_SYSTEM_CONFIG_GPIO_TIO sets polarity.
     */
    if (i2c_write_reg16(handle, REG_SYSTEM_CONFIG_GPIO, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure GPIO15\n");
        return -1;
    }
    if (i2c_write_reg16(handle, REG_SYSTEM_CONFIG_GPIO_TIO, 0x01) < 0) {
        fprintf(stderr, "Error: failed to set GPIO15 polarity\n");
        return -1;
    }

    /*
     * Set inter-measurement period to 50 ms (0x0032 = 50000 / 1000).
     */
    if (i2c_write_reg16(handle, REG_SYSTEM_INTERMEAS, 0x0032) < 0) {
        fprintf(stderr, "Error: failed to set inter-measurement period\n");
        return -1;
    }

    /*
     * Configure phase calibration.
     */
    if (i2c_write_reg16(handle, REG_PHASECAL_CONFIG, 0x0B) < 0) {
        fprintf(stderr, "Error: failed to set phase calibration config\n");
        return -1;
    }

    /*
     * Configure MSRC (minimum signal rate check).
     */
    if (i2c_write_reg16(handle, REG_MSRC_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set MSRC config\n");
        return -1;
    }

    /*
     * Configure final range configuration.
     */
    if (i2c_write_reg16(handle, REG_FINAL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set final config\n");
        return -1;
    }

    /*
     * Configure sigma estimation.
     */
    if (i2c_write_reg16(handle, REG_SIGMA_EST, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set sigma estimation\n");
        return -1;
    }

    /*
     * Configure cross-talk compensation.
     */
    if (i2c_write_reg16(handle, REG_CROSSTALK_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set cross-talk config\n");
        return -1;
    }

    /*
     * Configure MSRC 2.
     */
    if (i2c_write_reg16(handle, REG_MSRC_CONFIG_2, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set MSRC 2 config\n");
        return -1;
    }

    /*
     * Configure pre-range configuration.
     */
    if (i2c_write_reg16(handle, REG_PRE_RANGE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set pre-range config\n");
        return -1;
    }

    /*
     * Configure final range configuration.
     */
    if (i2c_write_reg16(handle, REG_FINAL_RANGE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set final range config\n");
        return -1;
    }

    /*
     * Configure pre-range histogram bins.
     */
    if (i2c_write_reg16(handle, REG_PRE_RANGE_HIST_BINS, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set pre-range hist bins\n");
        return -1;
    }

    /*
     * Configure final range histogram bins.
     */
    if (i2c_write_reg16(handle, REG_FINAL_RANGE_HIST_BINS, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set final range hist bins\n");
        return -1;
    }

    /*
     * Configure pre-range sigma threshold.
     */
    if (i2c_write_reg16(handle, REG_PRE_RANGE_SIGMA_TH, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set pre-range sigma th\n");
        return -1;
    }

    /*
     * Configure final range sigma threshold.
     */
    if (i2c_write_reg16(handle, REG_FINAL_RANGE_SIGMA_TH, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set final range sigma th\n");
        return -1;
    }

    /*
     * Configure pre-range minimum count rate.
     */
    if (i2c_write_reg16(handle, REG_PRE_RANGE_MIN_COUNT_RATE, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set pre-range min count rate\n");
        return -1;
    }

    /*
     * Configure final range minimum count rate.
     */
    if (i2c_write_reg16(handle, REG_FINAL_RANGE_MIN_COUNT_RATE, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set final range min count rate\n");
        return -1;
    }

    /*
     * Start ranging.
     */
    if (i2c_write_reg16(handle, REG_SYSTEM_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    return 0;
}

/* --------------------------- Read distance ----------------------------- */
static int read_distance(int handle)
{
    uint8_t status = 0;
    uint8_t dist_buf[2];
    int     distance = -1;

    /*
     * Poll the range status register (0x89).
     * Bit 0 of the status byte indicates data ready.
     */
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error: failed to read range status\n");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Warning: range data not ready after timeout\n");
        return -1;
    }

    /*
     * Read 2 bytes from the distance register (0x96).
     */
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance data\n");
        return -1;
    }

    distance = (dist_buf[0] << 8) | dist_buf[1];

    /*
     * Clear the interrupt by writing to the result interrupt register.
     */
    if (i2c_write_reg16(handle, REG_RESULT_INTERRUPT, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt\n");
        /* Non-fatal: continue anyway */
    }

    return distance;
}

/* --------------------------- Circular buffer --------------------------- */
static void buffer_add(int value)
{
    g_buffer.data[g_buffer.head] = value;
    g_buffer.head = (g_buffer.head + 1) % BUFFER_SIZE;
    if (g_buffer.count < BUFFER_SIZE)
        g_buffer.count++;
}

/* --------------------------- LED control ------------------------------- */
static void led_set(int on)
{
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

/* --------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_pigpio_inited) {
        led_set(0);
        if (g_i2c_handle >= 0) {
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
        }
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* --------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    led_set(0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_vl53l1x(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    g_buffer.head  = 0;
    g_buffer.count = 0;

    /* Register signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int distance = read_distance(g_i2c_handle);

        if (distance >= 0) {
            buffer_add(distance);
            printf("Distance: %d mm\n", distance);
            led_set(distance < DISTANCE_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "Error reading distance, continuing...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * HC-SR04 ultrasonic distance sensor + hardware-timed PWM speaker as a
 * theremin-like instrument on a Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5 V (pin 2 or 4)
 *   HC-SR04 GND  -> GND (pin 6)
 *   HC-SR04 TRIG -> GPIO23 (pin 16, BCM 23)
 *   HC-SR04 ECHO -> GPIO24 (pin 18, BCM 24)
 *   Speaker     -> GPIO18 (pin 12, BCM 18, hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SPEAKER_PIN      18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f
#define PWM_DUTY_50      500000   /* 50% of 1,000,000 */
#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define LOOP_DELAY_US    100000   /* 100 ms */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns true on success, false on timeout or error.
 */
static bool measure_distance(float *distance_out)
{
    uint32_t start_tick, end_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return false;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return false;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return false;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo start timeout (no object)\n");
            return false;
        }
    }
    end_tick = gpioTick();

    /* Wait for echo falling edge (timeout if stuck high) */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - end_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo end timeout (stuck high)\n");
            return false;
        }
    }

    uint32_t pulse_us = gpioTick() - end_tick;

    /* distance = (pulse_us * 34300 cm/s) / 2 / 1,000,000 s/us */
    *distance_out = (float)pulse_us * 0.01715f;
    return true;
}

/*
 * Map distance to frequency on a logarithmic scale.
 * Returns true if the mapping is valid, false if the distance is out of range.
 */
static bool map_distance_to_frequency(float distance, float *frequency_out)
{
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return false;
    }

    /* Logarithmic mapping: freq = MIN_FREQ * (distance / MAX_DIST) ^ 2 */
    float normalized = distance / MAX_DISTANCE_CM;
    float freq = MIN_FREQUENCY_HZ * powf(normalized, 2.0f);

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    *frequency_out = freq;
    return true;
}

/*
 * Set PWM frequency and 50% duty cycle on the speaker pin.
 * Returns 0 on success, -1 on error.
 */
static int set_speaker_frequency(float frequency)
{
    int pwm_range = (int)(frequency * 2.0f);   /* range = freq * 2 for 50% duty */
    if (pwm_range < 1) pwm_range = 1;

    if (gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%.0f) failed\n", frequency);
        return -1;
    }
    if (gpioSetPWMrange(SPEAKER_PIN, pwm_range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", pwm_range);
        return -1;
    }
    if (gpioPWM(SPEAKER_PIN, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", PWM_DUTY_50);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, echo pin as input */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set speaker pin as output and initialise PWM to 0 Hz */
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SPEAKER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_speaker_frequency(0.0f) < 0) {
        fprintf(stderr, "Error: initial speaker frequency setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float current_frequency = MIN_FREQUENCY_HZ;
    bool first_iteration = true;

    while (g_running) {
        float distance;
        bool ok = measure_distance(&distance);

        if (ok) {
            float frequency;
            if (map_distance_to_frequency(distance, &frequency)) {
                current_frequency = frequency;
            } else {
                fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
            }
        } else {
            fprintf(stderr, "Warning: distance measurement failed\n");
        }

        if (set_speaker_frequency(current_frequency) < 0) {
            fprintf(stderr, "Error: failed to set speaker frequency\n");
            break;
        }

        if (first_iteration) {
            first_iteration = false;
            printf("Theremin running. Press Ctrl+C to exit.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioPWM(SPEAKER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

