#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define LOOP_DELAY_US    100000   /* 100 ms */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns true on success, false on timeout or error.
 */
static bool measure_distance(float *distance_out)
{
    uint32_t start_tick, end_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return false;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return false;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return false;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo start timeout (no object)\n");
            return false;
        }
    }
    end_tick = gpioTick();

    /* Wait for echo falling edge (timeout if stuck high) */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - end_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo end timeout (stuck high)\n");
            return false;
        }
    }

    uint32_t pulse_us = gpioTick() - end_tick;

    /* distance = (pulse_us * 34300 cm/s) / 2 / 1,000,000 s/us */
    *distance_out = (float)pulse_us * 0.01715f;
    return true;
}

/*
 * Map distance to frequency on a logarithmic scale.
 * Returns true if the mapping is valid, false if the distance is out of range.
 */
static bool map_distance_to_frequency(float distance, float *frequency_out)
{
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return false;
    }

    /* Logarithmic mapping: freq = MIN_FREQ * (distance / MAX_DIST) ^ 2 */
    float normalized = distance / MAX_DISTANCE_CM;
    float freq = MIN_FREQUENCY_HZ * powf(normalized, 2.0f);

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    *frequency_out = freq;
    return true;
}

/*
 * Set PWM frequency and 50% duty cycle on the speaker pin.
 * Returns 0 on success, -1 on error.
 */
static int set_speaker_frequency(float frequency)
{
    int pwm_range = (int)(frequency * 2.0f);   /* range = freq * 2 for 50% duty */
    if (pwm_range < 1) pwm_range = 1;

    if (gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%.0f) failed\n", frequency);
        return -1;
    }
    if (gpioSetPWMrange(SPEAKER_PIN, pwm_range) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", pwm_range);
        return -1;
    }
    if (gpioPWM(SPEAKER_PIN, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", PWM_DUTY_50);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, echo pin as input */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set speaker pin as output and initialise PWM to 0 Hz */
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SPEAKER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_speaker_frequency(0.0f) < 0) {
        fprintf(stderr, "Error: initial speaker frequency setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float current_frequency = MIN_FREQUENCY_HZ;
    bool first_iteration = true;

    while (g_running) {
        float distance;
        bool ok = measure_distance(&distance);

        if (ok) {
            float frequency;
            if (map_distance_to_frequency(distance, &frequency)) {
                current_frequency = frequency;
            } else {
                fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
            }
        } else {
            fprintf(stderr, "Warning: distance measurement failed\n");
        }

        if (set_speaker_frequency(current_frequency) < 0) {
            fprintf(stderr, "Error: failed to set speaker frequency\n");
            break;
        }

        if (first_iteration) {
            first_iteration = false;
            printf("Theremin running. Press Ctrl+C to exit.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioPWM(SPEAKER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

