/*
 * Theremin-like instrument using an HC-SR04 ultrasonic sensor and a
 * piezo buzzer on a Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5V  (pin 2 or 4)
 *   HC-SR04 GND  -> GND (pin 6)
 *   HC-SR04 TRIG -> GPIO23 (BCM 23, pin 16)
 *   HC-SR04 ECHO -> GPIO24 (BCM 24, pin 18)
 *   Buzzer +     -> GPIO18 (BCM 18, pin 12) via PWM0
 *   Buzzer -     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define MIN_DISTANCE_CM  5.0f
#define MAX_DISTANCE_CM  50.0f
#define MIN_FREQUENCY    200
#define MAX_FREQUENCY    2000

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  100000   /* 100 ms */
#define LOOP_DELAY_US    10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the distance in centimetres from the HC-SR04.
 * Returns 0 on success and stores the distance in *out_cm.
 * Returns -1 on timeout or GPIO error.
 */
static int measure_distance(float *out_cm)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER_PIN low\n");
        return -1;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER_PIN high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER_PIN low\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (out of range?)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    /* speed of sound 343 m/s => 34300 cm/s => 0.0343 cm/µs */
    *out_cm = (float)pulse_us * 0.0343f;
    return 0;
}

static int map_distance_to_frequency(float distance_cm, int *out_freq)
{
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    float normalized = (distance_cm - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int freq = (int)(MIN_FREQUENCY +
                     normalized * (MAX_FREQUENCY - MIN_FREQUENCY));

    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;

    *out_freq = freq;
    return 0;
}

int main(void)
{
    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN (GPIO%d) as output\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN (GPIO%d) as input\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN (GPIO%d) as output\n",
                BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pull-down on echo pin (HC-SR04 ECHO is open-drain) --- */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN\n");
    }

    /* --- Ensure trigger starts low --- */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise buzzer to a safe (silent) state --- */
    if (gpioSetPWMfrequency(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on BUZZER_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle on BUZZER_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float last_distance = MIN_DISTANCE_CM;
    int   last_frequency = MIN_FREQUENCY;
    int   first_reading = 1;

    printf("Theremin started. Press Ctrl+C to exit.\n");
    printf("Distance (cm) -> Frequency (Hz)\n");

    while (g_running) {
        float distance;
        int   frequency;

        if (measure_distance(&distance) == 0) {
            last_distance = distance;
            first_reading = 0;

            if (map_distance_to_frequency(distance, &frequency) == 0) {
                last_frequency = frequency;
            } else {
                fprintf(stderr, "Warning: frequency mapping failed\n");
            }
        } else {
            /* Sensor read failed: keep last valid frequency, report error */
            fprintf(stderr, "Warning: sensor read failed, using last valid "
                            "frequency %d Hz\n", last_frequency);
        }

        /* Generate a continuous tone on the buzzer */
        if (gpioSetPWMfrequency(BUZZER_PIN, last_frequency) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency to %d Hz\n",
                    last_frequency);
        }
        if (gpioPWM(BUZZER_PIN, 128) < 0) {  /* 50 % duty cycle */
            fprintf(stderr, "Error: failed to set PWM duty cycle\n");
        }

        printf("Distance: %.2f cm  ->  Frequency: %d Hz\n",
               last_distance, last_frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(BUZZER_PIN, 0);
    gpioSetPWMfrequency(BUZZER_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

