/*
 * Raspberry Pi 4 Model B - TDK InvenSense ICU-20201 Ultrasonic ToF Sensor
 * SPI Interface (pigpio) - Obstacle Avoidance Distance Logging
 *
 * Wiring:
 *   ICU-20201 VCC -> 3.3V (Pin 1)
 *   ICU-20201 GND -> GND  (Pin 9)
 *   ICU-20201 SCLK -> GPIO11 (Pin 23)
 *   ICU-20201 MOSI -> GPIO10 (Pin 19)
 *   ICU-20201 MISO -> GPIO9  (Pin 21)
 *   ICU-20201 CS   -> GPIO8  (Pin 24, CE0)
 *
 * Build: gcc -Wall -Wextra -O2 -o distance_logger distance_logger.c -lpigpio -lrt
 * Run:   sudo ./distance_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 (GPIO8)                          */
#define SPI_SPEED      1000000    /* 1 MHz                                */
#define SPI_FLAGS      0          /* Mode 0, active-low CS                */

#define LOG_FILE       "distance_log.csv"
#define SAMPLE_DELAY_US 100000    /* 100 ms between readings              */

/*
 * ICU-20201 register map (example - adjust per datasheet revision).
 * The ICU-20201 exposes a 16-bit SPI interface with a 16-bit data
 * register (RANGE_DATA) containing the distance in millimetres.
 */
#define REG_RANGE_DATA 0x0002
#define REG_SYSTEM_CTRL 0x0001
#define REG_PRODUCT_ID 0x0000
#define EXPECTED_PROD_ID 0x2020

/* ----------------------------- Globals ---------------------------------- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ----------------------------- Prototypes ------------------------------- */
static int  spi_read_register(uint16_t reg, uint16_t *value);
static int  spi_write_register(uint16_t reg, uint16_t value);
static int  init_sensor(void);
static int  read_distance(uint16_t *distance_mm);
static void log_data(uint16_t distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI Helpers ------------------------------ */

/*
 * Read a 16-bit register from the ICU-20201.
 * SPI frame: [reg_addr(16) | 0x0000] -> [data_hi(8) | data_lo(8)]
 */
static int spi_read_register(uint16_t reg, uint16_t *value)
{
    if (value == NULL) {
        fprintf(stderr, "spi_read_register: NULL value pointer\n");
        return -1;
    }

    char tx_buf[4];
    char rx_buf[4];

    tx_buf[0] = (reg >> 8) & 0xFF;
    tx_buf[1] = reg & 0xFF;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    int bytes = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (bytes != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", bytes);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)rx_buf[2] << 8) | (uint8_t)rx_buf[3];
    return 0;
}

/*
 * Write a 16-bit value to a 16-bit register on the ICU-20201.
 * SPI frame: [reg_addr(16) | data(16)]
 */
static int spi_write_register(uint16_t reg, uint16_t value)
{
    char tx_buf[4];
    char rx_buf[4];

    tx_buf[0] = (reg >> 8) & 0xFF;
    tx_buf[1] = reg & 0xFF;
    tx_buf[2] = (value >> 8) & 0xFF;
    tx_buf[3] = value & 0xFF;

    int bytes = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (bytes != 4) {
        fprintf(stderr, "SPI write error: expected 4 bytes, got %d\n", bytes);
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor Init ------------------------------ */
static int init_sensor(void)
{
    uint16_t prod_id = 0;

    /* Verify sensor presence by reading the PRODUCT_ID register */
    if (spi_read_register(REG_PRODUCT_ID, &prod_id) != 0) {
        fprintf(stderr, "Error: failed to read PRODUCT_ID (sensor absent or SPI bus error)\n");
        return -1;
    }

    if (prod_id != EXPECTED_PROD_ID) {
        fprintf(stderr, "Error: unexpected PRODUCT_ID 0x%04X (expected 0x%04X)\n",
                prod_id, EXPECTED_PROD_ID);
        return -1;
    }

    /*
     * Example system configuration: start continuous ranging.
     * Adjust register addresses and values per the ICU-20201 datasheet.
     */
    if (spi_write_register(REG_SYSTEM_CTRL, 0x0001) != 0) {
        fprintf(stderr, "Error: failed to configure SYSTEM_CTRL\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Distance Read ---------------------------- */
static int read_distance(uint16_t *distance_mm)
{
    if (distance_mm == NULL) {
        fprintf(stderr, "read_distance: NULL pointer\n");
        return -1;
    }

    if (spi_read_register(REG_RANGE_DATA, distance_mm) != 0) {
        fprintf(stderr, "Error: failed to read RANGE_DATA register\n");
        return -1;
    }

    /* Sanity-check the distance range (200-5000 mm) */
    if (*distance_mm < 200 || *distance_mm > 5000) {
        fprintf(stderr, "Warning: distance out of range: %u mm\n", *distance_mm);
        return -1;
    }

    return 0;
}

/* ----------------------------- Logging ---------------------------------- */
static void log_data(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(log_file);
}

/* ----------------------------- Signal / Cleanup ------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel (mode 0, 1 MHz, active-low CS on CE0) */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Obstacle avoidance distance logging started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        uint16_t distance_mm = 0;

        if (read_distance(&distance_mm) == 0) {
            log_data(distance_mm);
            printf("Distance: %u mm\n", distance_mm);
        } else {
            fprintf(stderr, "Error: failed to read distance\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

