/*
 * Si1175 ambient light / proximity sensor logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si1175 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   Si1175 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   Si1175 VDD  -> 3.3 V
 *   Si1175 GND  -> GND
 *
 * The Si1175 default I2C address is 0x60 (7-bit).
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1175_logger si1175_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1175 constants (from datasheet) ---- */
#define SI1175_I2C_ADDR        0x60
#define SI1175_REG_PART_ID     0x00
#define SI1175_REG_HW_KEY      0x07
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define SI1175_REG_COMMAND     0x30

#define SI1175_PART_ID         0x75
#define SI1175_HW_KEY_VAL      0x17
#define SI1175_CMD_RESET       0x01
#define SI1175_CMD_ALS_FORCE   0x06

#define I2C_BUS_NAME           "/dev/i2c-1"
#define LOG_FILE_NAME          "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC    5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1175 register.                                */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int si1175_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1175 register.                               */
/* Returns the byte value (0–255) on success, -1 on error.             */
/* ------------------------------------------------------------------ */
static int si1175_read_reg(int fd, uint8_t reg)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg ptr 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return (int)val;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit ambient light value (little-endian).                */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int si1175_read_als_visible(int fd, uint16_t *out)
{
    int lo = si1175_read_reg(fd, SI1175_REG_ALS_VIS_DATA0);
    if (lo < 0)
        return -1;
    int hi = si1175_read_reg(fd, SI1175_REG_ALS_VIS_DATA1);
    if (hi < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1175: verify part ID, reset, set HW key,           */
/* force a ALS measurement.                                            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int si1175_init(int fd)
{
    int part_id = si1175_read_reg(fd, SI1175_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Cannot read Si1175 PART_ID – sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1175_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X) – wrong sensor?\n",
                part_id, SI1175_PART_ID);
        return -1;
    }

    if (si1175_write_reg(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) < 0)
        return -1;
    usleep(10000);  /* 10 ms reset settling */

    if (si1175_write_reg(fd, SI1175_REG_HW_KEY, SI1175_HW_KEY_VAL) < 0)
        return -1;

    /* Force an ALS measurement so the first sample is valid */
    if (si1175_write_reg(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) < 0)
        return -1;
    usleep(10000);  /* 10 ms conversion */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row with an ISO-8601 timestamp.                      */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t als_visible)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    if (!tm) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, als_visible) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS_NAME, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1175_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (si1175_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1175 initialisation failed – check wiring and address.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,als_visible\n") < 0 || fflush(g_log_fp) != 0) {
            fprintf(stderr, "Cannot write header: %s\n", strerror(errno));
            fclose(g_log_fp);
