/*
 * Si1120 ambient light and proximity logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si1120 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   Si1120 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   Si1120 VDD -> 3.3 V
 *   Si1120 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1120_logger si1120_logger.c -lpigpio -lrt
 * Run:    sudo ./si1120_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1120 constants (from datasheet) ---- */
#define SI1120_I2C_ADDR        0x60
#define SI1120_REG_PART_ID     0x00
#define SI1120_PART_ID_EXPECT  0x20
#define SI1120_REG_RESET       0x07
#define SI1120_RESET_VALUE     0x01
#define SI1120_REG_ALS_DATA0   0x22
#define SI1120_REG_PS_DATA0    0x24
#define SI1120_REG_COMMAND     0x30
#define SI1120_CMD_RESET       0x01
#define SI1120_CMD_PS_FORCE    0x05
#define SI1120_CMD_ALS_FORCE   0x06

/* ---- Application constants ---- */
#define I2C_BUS              1
#define LOG_FILE             "si1120_log.txt"
#define SAMPLE_PERIOD_US     500000   /* 500 ms */
#define RETRY_DELAY_US       10000    /* 10 ms  */
#define MAX_RETRIES          3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a Si1120 register with retries.                     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1120_write_byte(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (i2cWriteByteData(handle, reg, value) == 0)
            return 0;
        fprintf(stderr,
                "[attempt %d/%d] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                attempt, MAX_RETRIES, reg, value);
        if (attempt < MAX_RETRIES)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a byte from a Si1120 register with retries.                    */
/* Returns the byte value (0–255) on success, -1 on failure.            */
/* ------------------------------------------------------------------ */
static int si1120_read_byte(int handle, uint8_t reg)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        int v = i2cReadByteData(handle, reg);
        if (v >= 0)
            return v;
        fprintf(stderr,
                "[attempt %d/%d] i2cReadByteData(reg=0x%02X) failed\n",
                attempt, MAX_RETRIES, reg);
        if (attempt < MAX_RETRIES)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers.    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1120_read_word(int handle, uint8_t reg_low, uint16_t *out)
{
    int lo = si1120_read_byte(handle, reg_low);
    if (lo < 0)
        return -1;
    int hi = si1120_read_byte(handle, reg_low + 1);
    if (hi < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the Si1120 and verify the part ID.                             */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1120_init(int handle)
{
    /* Issue software reset via command register. */
    if (si1120_write_byte(handle, SI1120_REG_COMMAND,
                          SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to send reset command.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Read and verify the part ID. */
    int part_id = si1120_read_byte(handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read part ID.\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID_EXPECT) {
        fprintf(stderr,
                "Unexpected part ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1120_PART_ID_EXPECT);
        return -1;
    }
    printf("Si1120 detected (part ID 0x%02X).\n", part_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a forced ALS + proximity measurement.                       */
/* ------------------------------------------------------------------ */
static int si1120_trigger_measurement(int handle)
{
    if (si1120_write_byte(handle, SI1120_REG_COMMAND,
                          SI1120_CMD_PS_FORCE) != 0) {
        fprintf(stderr, "Failed to trigger proximity measurement.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for conversion */
    if (si1120_write_byte(handle, SI1120_REG_COMMAND,
                          SI1120_CMD_ALS_FORCE) != 0) {
        fprintf(stderr, "Failed to trigger ALS measurement.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for conversion */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file.                        */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t als, uint16_t prox)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[24];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, ALS=%u, Proximity=%u\n", ts, als, prox);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1120_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (si1120_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging Si1120 data to %s (Ctrl-C to stop)...\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (si1120_trigger_measurement(g_i2c_handle) != 0) {
            fprintf(stderr, "Measurement trigger failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        uint16_t als = 0, prox = 0;
        if (si1120_read_word(g_i2c_handle, SI1120_REG_ALS_DATA0, &als) != 0) {
            fprintf(stderr, "ALS read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (si1120_read_word(g_i2c_handle, SI1120_REG_PS_DATA0, &prox) != 0) {
            fprintf(stderr, "Proximity read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_file, als, prox);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

