/*
 * Si1182-A-GM optical sensor reader for Raspberry Pi 3 Model B+
 * Uses standard Linux I2C ioctl interface (/dev/i2c-1).
 *
 * Wiring:
 *   Si1182 SDA -> GPIO2 (pin 3)
 *   Si1182 SCL -> GPIO3 (pin 5)
 *   Si1182 VDD -> 3.3 V
 *   Si1182 GND -> GND
 *
 * Build:  gcc -O2 -Wall -o si1182_log si1182_log.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60

/* Si1182 register addresses (from datasheet) */
#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x08
#define REG_ALS_DATA    0x22
#define REG_PS_DATA     0x24

#define HW_KEY_VAL      0x17
#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/* Write a single byte to a register. Returns 0 on success, -1 on error. */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read a single byte from a register. Returns 0 on success, -1 on error. */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd)\n",
                reg, strerror(errno), n);
        return -1;
    }

    uint8_t val;
    n = read(fd, &val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit little-endian register pair. Returns 0 on success, -1 on error. */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd)\n",
                reg, strerror(errno), n);
        return -1;
    }

    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_si1182(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read Part ID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID 0x%02X (expected 0x%02X). Wrong sensor?\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (Part ID 0x%02X).\n", part_id);

    if (i2c_write_reg(fd, REG_HW_KEY, HW_KEY_VAL) != 0) {
        fprintf(stderr, "Failed to write HW_KEY.\n");
        return -1;
    }

    /*
     * Measurement rate: 0x08 = 100 ms (datasheet table 1-1).
     * Bits [7:4] = measurement rate, bits [3:0] = LED current.
     * 0x08 = 100 ms, 0x00 = LED current default.
     */
    if (i2c_write_reg(fd, REG_MEAS_RATE, 0x08) != 0) {
        fprintf(stderr, "Failed to write MEAS_RATE.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint16_t *lux, uint16_t *proximity)
{
    if (i2c_read_reg16(fd, REG_ALS_DATA, lux) != 0)
        return -1;
    if (i2c_read_reg16(fd, REG_PS_DATA, proximity) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t lux, uint16_t proximity)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;

    fprintf(fp, "%s.%03ld,%u,%u\n", timestamp, ms, lux, proximity);
    fflush(fp);

    printf("%s.%03ld,%u,%u\n", timestamp, ms, lux, proximity);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire sensor address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_si1182(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("biometric_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open biometric_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,lux,proximity\n");
        fflush(g_log_fp);
    }

    printf("Logging Si1182 data to biometric_log.txt (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t lux = 0, proximity = 0;
        if (read_sensor_data(g_i2c_fd, &lux, &proximity) == 0) {
            log_data(g_log_fp, lux, proximity);
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }
        usleep(100000); /* 100 ms */
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

