    long ms = ts.tv_nsec / 1000000L;

    fprintf(fp, "%s.%03ld,%u,%u\n", timestamp, ms, lux, proximity);
    fflush(fp);

    printf("%s.%03ld,%u,%u\n", timestamp, ms, lux, proximity);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire sensor address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_si1182(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("biometric_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open biometric_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,lux,proximity\n");
        fflush(g_log_fp);
    }

    printf("Logging Si1182 data to biometric_log.txt (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t lux = 0, proximity = 0;
        if (read_sensor_data(g_i2c_fd, &lux, &proximity) == 0) {
            log_data(g_log_fp, lux, proximity);
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }
        usleep(100000); /* 100 ms */
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

