#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_PS1_DATA1 0x19
#define SI1145_REG_COMMAND 0x30
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PSALS_FORCE 0x07
#define SI1145_HW_KEY_VAL 0x17
#define SI1145_PART_ID 0x45
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s - ERROR: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
    if (log_file) {
        fprintf(log_file, "%s - ERROR: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
        fflush(log_file);
    }
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        log_error("I2C read failed");
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id;
    if (read_register(handle, SI1145_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "ERROR: Invalid Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);
    if (write_register(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_register(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    return 0;
}

static int read_proximity(int handle, uint16_t *proximity) {
    uint8_t ps1_data0, ps1_data1;
    if (read_register(handle, SI1145_REG_PS1_DATA0, &ps1_data0) < 0) return -1;
    if (read_register(handle, SI1145_REG_PS1_DATA1, &ps1_data1) < 0) return -1;
    *proximity = ((uint16_t)ps1_data1 << 8) | ps1_data0;
    return 0;
}

static int log_proximity_data(uint16_t proximity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s, %u\n", timestamp, proximity) < 0) {
        log_error("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (initialize_sensor(i2c_handle) < 0) {
        log_error("Sensor initialization failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Proximity logging started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        uint16_t proximity = 0;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_proximity(i2c_handle, &proximity) == 0) {
                success = 1;
                break;
            }
            gpioDelay(100000);
        }
        if (success) {
            if (log_proximity_data(proximity) < 0) {
                log_error("Failed to log proximity data");
            }
        } else {
            log_error("Failed to read proximity data after retries");
            break;
        }
        gpioDelay(1000000);
    }
    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

