/*
 * HC-SR04 Ultrasonic Distance Sensor - Buzzer Alert
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern GPIO API)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM) via voltage divider (5 V -> 3.3 V)
 *   Buzzer      -> GPIO27 (BCM)
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04_buzzer hcsr04_buzzer.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define BUZZER_PIN       27

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define DISTANCE_THRESHOLD 20.0           /* cm */
#define TRIGGER_PULSE_US 10               /* 10 µs trigger pulse */
#define SAMPLE_PERIOD_S  1.0              /* seconds between readings */

/* Shared state between callback and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_new_data   = false;

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * level: 1 = rising edge, 0 = falling edge, 2 = timeout (not used here).
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_start_tick = tick;
        g_echo_seen  = true;
    } else if (level == 0 && g_echo_seen) {
        /* Falling edge: end of echo pulse */
        g_end_tick   = tick;
        g_new_data   = true;
        g_echo_seen  = false;
    }
}

/*
 * Generate a 10 µs trigger pulse on the trigger pin.
 * Returns 0 on success, -1 on failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Compute distance in cm from the two pigpio ticks (32-bit microseconds).
 * pigpio ticks are 32-bit and wrap every ~71.6 min; handle the wrap.
 */
static double calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start;          /* correct even across a wrap */
    return (double)diff * SPEED_OF_SOUND / 2000000.0;
}

int main(void)
{
    /* ---- Install signal handler for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial state failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER, 0) initial state failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callback for both rising and falling edges */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance sensor started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("  Threshold: %.1f cm | Sample period: %.1f s\n",
           DISTANCE_THRESHOLD, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset shared state for this cycle */
        g_new_data   = false;
        g_echo_seen  = false;
        g_start_tick = 0;
        g_end_tick   = 0;

        if (trigger_sensor() < 0) {
            fprintf(stderr, "Warning: trigger pulse failed, retrying...\n");
            time_sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Wait for the echo callback to record the pulse width */
        time_sleep(0.02);                 /* 20 ms — well above the 3 µs echo */

        if (!g_new_data) {
            fprintf(stderr, "Warning: no echo received within timeout\n");
            /* Ensure buzzer is off on timeout */
            gpioWrite(BUZZER_PIN, 0);
            time_sleep(SAMPLE_PERIOD_S);
            continue;
        }

        double distance = calculate_distance(g_start_tick, g_end_tick);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Distance: %.2f cm  -> ALERT\n", distance);
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                fprintf(stderr, "Warning: gpioWrite(BUZZER, 1) failed\n");
            }
        } else {
            printf("Distance: %.2f cm  -> normal\n", distance);
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Warning: gpioWrite(BUZZER, 0) failed\n");
            }
        }

        time_sleep(SAMPLE_PERIOD_S);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetAlertFunc(ECHO_PIN, NULL);   /* unregister callback */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

