/*
 * parking_assist.c — Raspberry Pi Zero W
 *
 * HC-SR04 ultrasonic distance sensor (trigger GPIO4, echo GPIO17)
 * SG90 servo motor (PWM GPIO18)
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:    sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

/* ---- HC-SR04 timing ---- */
#define TRIGGER_PULSE_US  10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US   30000       /* 30 ms max echo wait            */
#define MAX_RANGE_CM      400.0f      /* HC-SR04 rated max              */

/* ---- Servo mapping ---- */
#define SERVO_MIN_US      500         /* 0°   (200 cm)                  */
#define SERVO_MAX_US      2500        /* 180° (20 cm)                   */
#define DIST_MAX          200.0f      /* Upper distance threshold       */
#define DIST_MIN          20.0f       /* Lower distance threshold       */

/* ---- Loop timing ---- */
#define LOOP_DELAY_US     100000      /* 100 ms between readings        */

/* ---- Speed of sound ---- */
#define SOUND_SPEED_CM_S  34300.0f    /* cm/s at 20 °C                  */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns distance in cm, or -1.0 on timeout / error.                 */
static float read_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1.0f;
    }
    gpioDelay(5);                       /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger high) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger low) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    uint32_t t0 = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - t0) > ECHO_TIMEOUT_US) {
            return -1.0f;                 /* no echo — object too far    */
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            return -1.0f;                 /* echo stuck high              */
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    float distance = (pulse_us * SOUND_SPEED_CM_S) / 2000000.0f;

    if (distance < 0.0f || distance > MAX_RANGE_CM) {
        return -1.0f;                     /* out of sensor range         */
    }
    return distance;
}

/* ------------------------------------------------------------------ */
static int set_servo_angle(float distance)
{
    if (distance < 0.0f) {
        distance = DIST_MAX;              /* treat error as far away     */
    }
    if (distance > DIST_MAX) {
        distance = DIST_MAX;
    }
    if (distance < DIST_MIN) {
        distance = DIST_MIN;
    }

    float pulse_us = SERVO_MIN_US +
        (distance - DIST_MIN) *
        (SERVO_MAX_US - SERVO_MIN_US) / (DIST_MAX - DIST_MIN);

    if (gpioServo(SERVO_PIN, (int)pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %.0f µs\n",
                pulse_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);

    /* ---- Main loop ---- */
    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: distance read failed, retrying...\n");
        } else {
            printf("Distance: %.2f cm  |  Servo angle: %.0f°\n",
                   distance,
                   (distance - DIST_MIN) *
                   (180.0f - 0.0f) / (DIST_MAX - DIST_MIN) + 0.0f);
        }

        set_servo_angle(distance);
        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Cleanup ---- */
    gpioServo(SERVO_PIN, 0);            /* stop PWM pulses              */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

