/*
 * Raspberry Pi 3 Model B+ — VL53L1X gate controller
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1, default address 0x29
 *   - Servo on GPIO18 (BCM 18, hardware PWM-capable)
 *
 * Behavior:
 *   - Polls the VL53L1X distance register every 100 ms.
 *   - Opens gate when object > 250 mm and closes gate when object < 200 mm.
 *   - Logs open/close events with timestamps to gate_log.txt.
 *   - Handles I2C errors and SIGINT cleanly.
 *
 * Build:
 *   gcc -O2 -Wall -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* default 7-bit I2C address     */
#define GPIO_SERVO           18            /* BCM pin for servo PWM         */

#define DIST_THRESHOLD_HIGH  250           /* mm — open gate above this     */
#define DIST_THRESHOLD_LOW   200           /* mm — close gate below this    */

#define SERVO_OPEN_US        1000          /* pulse width for open gate     */
#define SERVO_CLOSED_US      2000          /* pulse width for closed gate   */
#define SERVO_NEUTRAL_US     1500          /* neutral pulse width           */

#define POLL_DELAY_US        100000        /* 100 ms between measurements   */
#define LOG_FILE             "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_RESULT_DISTANCE          0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR   0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG  0x0087
#define VL53L1X_REG_SYSTEM_THRESH_HIGH       0x008B
#define VL53L1X_REG_SYSTEM_THRESH_LOW        0x008C
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG      0x008A
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT  0x0081
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG   0x0061
#define VL53L1X_REG_SYSTEM_CONFIG            0x0060
#define VL53L1X_REG_PHASECAL_CONFIG          0x006B
#define VL53L1X_REG_RANGE_CONFIG_A           0x006C
#define VL53L1X_REG_RANGE_CONFIG_B           0x006D
#define VL53L1X_REG_RANGE_CONFIG_C           0x006E
#define VL53L1X_REG_RANGE_CONFIG_D           0x006F
#define VL53L1X_REG_RANGE_CONFIG_E           0x0070
#define VL53L1X_REG_RANGE_CONFIG_F           0x0071
#define VL53L1X_REG_RANGE_CONFIG_G           0x0072
#define VL53L1X_REG_RANGE_CONFIG_H           0x0073
#define VL53L1X_REG_RANGE_CONFIG_I           0x0074
#define VL53L1X_REG_RANGE_CONFIG_J           0x0075
#define VL53L1X_REG_RANGE_CONFIG_K           0x0076
#define VL53L1X_REG_RANGE_CONFIG_L           0x0077
#define VL53L1X_REG_RANGE_CONFIG_M           0x0078
#define VL53L1X_REG_RANGE_CONFIG_N           0x0079
#define VL53L1X_REG_RANGE_CONFIG_O           0x007A
#define VL53L1X_REG_RANGE_CONFIG_P           0x007B
#define VL53L1X_REG_RANGE_CONFIG_Q           0x007C
#define VL53L1X_REG_RANGE_CONFIG_R           0x007D
#define VL53L1X_REG_RANGE_CONFIG_S           0x007E
#define VL53L1X_REG_RANGE_CONFIG_T           0x007F

#define VL53L1X_MODEL_ID     0xEA          /* expected model ID            */
#define VL53L1X_RANGE_START  0x00          /* bit 0 of SYSTEM_MODE_START   */
#define VL53L1X_RANGE_STOP   0x01          /* bit 0 of SYSTEM_MODE_START   */

/* ----------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Prototypes -------------------------------- */

static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  init_vl53l1x(int handle);
static int  read_distance(int handle, uint16_t *distance_mm);
static void set_servo_pulse(int gpio, int pulse_us);
static void log_event(const char *event);
static void signal_handler(int sig);
static void cleanup(void);

/* --------------------------- I2C helpers ------------------------------- */

/* Write one byte to a 16-bit register address. */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read `len` bytes from a 16-bit register address. */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

/* --------------------------- VL53L1X init ------------------------------- */

static int init_vl53l1x(int handle)
{
    uint8_t model_id = 0;

    /* Verify model ID. */
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    /* Stop ranging before configuration. */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_RANGE_STOP) != 0) {
        fprintf(stderr, "Error: failed to stop ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Clear any pending interrupt. */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear interrupt.\n");
    }

    /* Configure timing budget (20 ms). */
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_A, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_B, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_C, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_D, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_E, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_F, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_G, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_H, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_I, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_J, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_K, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_L, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_M, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_N, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_O, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_P, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_Q, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_R, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_S, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_T, 0x00) != 0) return -1;

    /* Set threshold high and low. */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_HIGH,
                        (DIST_THRESHOLD_HIGH >> 8) & 0xFF) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_LOW,
                        DIST_THRESHOLD_HIGH & 0xFF) != 0) return -1;

    /* Start ranging. */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, VL53L1X_RANGE_START) != 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    return 0;
}

/* --------------------------- Distance read ------------------------------ */

static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) != 0)
        return -1;
    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* --------------------------- Servo control ------------------------------ */

static void set_servo_pulse(int gpio, int pulse_us)
{
    if (gpioPWM(gpio, pulse_us) != 0)
        fprintf(stderr, "Warning: gpioPWM failed on GPIO %d.\n", gpio);
}

/* --------------------------- Logging ------------------------------------ */

static void log_event(const char *event)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(g_log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(g_log_file);
}

/* --------------------------- Signal / cleanup --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioPWM(GPIO_SERVO, 0);
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------- Main ----------------------------------- */

int main(void)
{
    int gate_open = 0;

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus. */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor. */
    if (init_vl53l1x(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo GPIO. */
    if (gpioSetMode(GPIO_SERVO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", GPIO_SERVO);
        cleanup();
        return EXIT_FAILURE;
    }
    set_servo_pulse(GPIO_SERVO, SERVO_NEUTRAL_US);

    /* Open log file. */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed.\n");
    }

    printf("Gate controller running. Press Ctrl+C to exit.\n");

    /* Main loop. */
    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance > DIST_THRESHOLD_HIGH && !gate_open) {
            set_servo_pulse(GPIO_SERVO, SERVO_OPEN_US);
            gate_open = 1;
            log_event("Gate opened");
            printf("Gate opened (distance: %u mm)\n", distance);
        } else if (distance < DIST_THRESHOLD_LOW && gate_open) {
            set_servo_pulse(GPIO_SERVO, SERVO_CLOSED_US);
            gate_open = 0;
            log_event("Gate closed");
            printf("Gate closed (distance: %u mm)\n", distance);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

