        gpioDelay(LOOP_DELAY_US);
    }

    /* ----------------------------- Clean shutdown ----------------------------- */
    printf("\nShutting down: stopping servo and releasing pigpio...\n");

    /* Stop servo pulses (0 pulse width) */
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioServo(stop) failed during shutdown\n");
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

