/*
 * Raspberry Pi 4 Model B – HC-SR04 ultrasonic distance sensor → SG90 servo
 *
 * Wiring:
 *   HC-SR04 trigger  → GPIO23 (BCM)
 *   HC-SR04 echo    → GPIO24 (BCM)  [3.3 V-tolerant on Pi 4; use divider if 5 V]
 *   SG90 signal      → GPIO18 (BCM)
 *   SG90 V+          → 5 V
 *   SG90 GND         → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_servo hcsr04_servo.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Pin assignments ----------------------------- */
#define TRIGGER_PIN      23          /* HC-SR04 trigger  */
#define ECHO_PIN         24          /* HC-SR04 echo     */
#define SERVO_PIN        18          /* SG90 signal      */

/* ----------------------------- Timing constants ----------------------------- */
#define TRIGGER_PULSE_US  10          /* 10 µs trigger pulse                    */
#define ECHO_TIMEOUT_US   50000       /* 50 ms timeout waiting for echo edges   */
#define LOOP_DELAY_US     100000      /* 100 ms between measurements            */
#define MIN_DISTANCE_CM   2.0         /* HC-SR04 minimum range                   */
#define MAX_DISTANCE_CM   400.0       /* HC-SR04 maximum range                   */
#define MIN_VALID_CM      20.0        /* Acceptable minimum for servo mapping   */
#define MAX_VALID_CM      200.0       /* Acceptable maximum for servo mapping   */
#define SERVO_MIN_US      500         /* SG90 pulse width for 0°                 */
#define SERVO_MAX_US      2500        /* SG90 pulse width for 180°              */

/* ----------------------------- Globals ------------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Signal handler ------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ----------------------------- Helpers ------------------------------------- */

/*
 * Measure distance in cm.
 * Returns >= 0 on success, -1.0 on timeout / error.
 */
static double measure_distance(void)
{
    /* Issue 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger HIGH) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger LOW) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo rising-edge timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo falling-edge timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    if (pulse_us == 0) {
        fprintf(stderr, "Warning: zero-length pulse\n");
        return -1.0;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    return (pulse_us * 0.0343) / 2.0;
}

/*
 * Map distance to servo angle (0° = 500 µs, 180° = 2500 µs).
 * Returns -1.0 if the distance is outside the valid range.
 */
static double distance_to_angle(double distance)
{
    if (distance < MIN_VALID_CM || distance > MAX_VALID_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.1f–%.1f]\n",
                distance, MIN_VALID_CM, MAX_VALID_CM);
        return -1.0;
    }

    double frac = (distance - MIN_VALID_CM) / (MAX_VALID_CM - MIN_VALID_CM);
    return (180.0 * frac);
