        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(100000);  /* 100 ms */

    printf("HC-SR04 → SG90 servo control started. Press Ctrl+C to exit.\n");
    printf("Distance range: %.1f–%.1f cm  |  Servo range: %.0f–%.0f°\n",
           MIN_VALID_CM, MAX_VALID_CM, 0.0, 180.0);

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Warning: distance %.2f cm out of HC-SR04 range\n",
                    distance);
        } else {
            double angle = distance_to_angle(distance);
            if (angle < 0.0) {
                fprintf(stderr, "Warning: distance %.2f cm out of servo mapping range\n",
                        distance);
            } else {
                if (set_servo_angle(angle) < 0) {
                    fprintf(stderr, "Error: failed to set servo angle %.2f°\n", angle);
                } else {
                    printf("Distance: %6.2f cm  |  Servo angle: %6.2f°\n",
                           distance, angle);
                }
            }
        }

        /* 100 ms between measurements */
        gpioDelay(LOOP_DELAY_US);
    }

    /* ----------------------------- Clean shutdown ----------------------------- */
    printf("\nShutting down: stopping servo and releasing pigpio...\n");

    /* Stop servo pulses (0 pulse width) */
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioServo(stop) failed during shutdown\n");
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

