/*
 * Si7005 humidity & temperature sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si7005 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   Si7005 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   Si7005 VDD -> 3.3 V
 *   Si7005 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7005_reader si7005_reader.c -lpigpio -lrt
 * Run:    sudo ./si7005_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si7005 constants (from datasheet) ---- */
#define SI7005_ADDR             0x40
#define SI7005_REG_TEMP         0x03
#define SI7005_REG_HUMIDITY     0x05
#define SI7005_REG_CONFIG       0x0D

/*
 * CONFIG register bit layout (8-bit, write-only):
 *   bit 7:  0  (reserved)
 *   bit 6:  0  (reserved)
 *   bit 5:  0  (reserved)
 *   bit 4:  0  (reserved)
 *   bit 3:  0  (reserved)
 *   bit 2:  0  (reserved)
 *   bit 1:  0  (reserved)
 *   bit 0:  0  (reserved)
 *
 * Writing 0x00 enables the sensor and starts a single-shot measurement.
 */
#define SI7005_CONFIG_VALUE     0x00

/* ---- Timing constants (microseconds) ---- */
#define I2C_BUS                 1
#define I2C_BAUD                1000000   /* 1 MHz */
#define CONFIG_WAIT_US          10000     /* 10 ms  */
#define READ_WAIT_US            10000     /* 10 ms  */
#define SAMPLE_PERIOD_US        2000000   /* 2 s    */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si7005 register.                           */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si7005_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    int rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from a Si7005 register.              */
/* Returns 0 on success and stores the value in *out; -1 on failure.   */
/* ------------------------------------------------------------------ */
static int si7005_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char cmd = (char)reg;
    int rc = i2cWriteDevice(handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }

    gpioDelay(READ_WAIT_US);

    char data[2] = {0, 0};
    rc = i2cReadDevice(handle, data, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) short read: %d bytes\n", reg, rc);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and configure the Si7005.                          */
/* Returns a valid pigpio handle (>= 0) on success, -1 on failure.      */
/* ------------------------------------------------------------------ */
static int si7005_open(void)
{
    int handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7005_ADDR, handle);
        return -1;
    }

    /*
     * Issue a soft reset by writing 0x80 to the CONFIG register.
     * The datasheet says the sensor resets to a known state; we then
     * write 0x00 to enable continuous measurement.
     */
    if (si7005_write_reg(handle, SI7005_REG_CONFIG, 0x80) != 0) {
        fprintf(stderr, "[ERROR] Soft reset write failed; attempting recovery.\n");
        i2cClose(handle);
        return -1;
    }
    gpioDelay(CONFIG_WAIT_US);

    if (si7005_write_reg(handle, SI7005_REG_CONFIG, SI7005_CONFIG_VALUE) != 0) {
        fprintf(stderr, "[ERROR] Initial config write failed; attempting recovery.\n");
        i2cClose(handle);
        return -1;
    }
    gpioDelay(CONFIG_WAIT_US);

    return handle;
}

/* ------------------------------------------------------------------ */
/* Read temperature in degrees Celsius.                                */
/* Returns 0 on success and stores the value in *temp_c; -1 on failure.*/
/* ------------------------------------------------------------------ */
static int si7005_read_temperature(int handle, float *temp_c)
{
    uint16_t raw;
    if (si7005_read_reg16(handle, SI7005_REG_TEMP, &raw) != 0)
        return -1;

    /*
     * Temperature conversion:
     *   T(°C) = (raw / 65536.0) * 175.72 - 46.85
     * (From datasheet table 2.)
     */
    *temp_c = ((float)raw / 65536.0f) * 175.72f - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read humidity in percent RH.                                        */
/* Returns 0 on success and stores the value in *rh; -1 on failure.    */
/* ------------------------------------------------------------------ */
static int si7005_read_humidity(int handle, float *rh)
{
    uint16_t raw;
    if (si7005_read_reg16(handle, SI7005_REG_HUMIDITY, &raw) != 0)
        return -1;

    /*
     * Humidity conversion:
     *   RH = (raw / 65536.0) * 100.0
     * (From datasheet table 2.)
     */
    *rh = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio library ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus and configure sensor ---- */
    g_i2c_handle = si7005_open();
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] Failed to open Si7005 on I2C bus %d at addr 0x%02X\n",
                I2C_BUS, SI7005_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7005 reader started.  Bus %d, addr 0x%02X.  Press Ctrl-C to stop.\n",
           I2C_BUS, SI7005_ADDR);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temp_c = 0.0f, rh = 0.0f;
        bool ok = true;

        if (si7005_read_temperature(g_i2c_handle, &temp_c) != 0)
            ok = false;

        if (ok && si7005_read_humidity(g_i2c_handle, &rh) != 0)
            ok = false;

        if (ok) {
            printf("Temperature: %.2f °C  |  Humidity: %.2f %%\n", temp_c, rh);
        } else {
            fprintf(stderr, "[WARN] I2C read failure; re-opening bus.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;

            /* Brief recovery delay before retry */
            gpioDelay(100000); /* 100 ms */

            g_i2c_handle = si7005_open();
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[ERROR] Re-open failed; will retry next cycle.\n");
            }
        }

        /* Sleep SAMPLE_PERIOD_US, but wake early on signal */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

