     * write 0x00 to enable continuous measurement.
     */
    if (si7005_write_reg(handle, SI7005_REG_CONFIG, 0x80) != 0) {
        fprintf(stderr, "[ERROR] Soft reset write failed; attempting recovery.\n");
        i2cClose(handle);
        return -1;
    }
    gpioDelay(CONFIG_WAIT_US);

    if (si7005_write_reg(handle, SI7005_REG_CONFIG, SI7005_CONFIG_VALUE) != 0) {
        fprintf(stderr, "[ERROR] Initial config write failed; attempting recovery.\n");
        i2cClose(handle);
        return -1;
    }
    gpioDelay(CONFIG_WAIT_US);

    return handle;
}

/* ------------------------------------------------------------------ */
/* Read temperature in degrees Celsius.                                */
/* Returns 0 on success and stores the value in *temp_c; -1 on failure.*/
/* ------------------------------------------------------------------ */
static int si7005_read_temperature(int handle, float *temp_c)
{
    uint16_t raw;
    if (si7005_read_reg16(handle, SI7005_REG_TEMP, &raw) != 0)
        return -1;

    /*
     * Temperature conversion:
     *   T(°C) = (raw / 65536.0) * 175.72 - 46.85
     * (From datasheet table 2.)
     */
    *temp_c = ((float)raw / 65536.0f) * 175.72f - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read humidity in percent RH.                                        */
/* Returns 0 on success and stores the value in *rh; -1 on failure.    */
/* ------------------------------------------------------------------ */
static int si7005_read_humidity(int handle, float *rh)
{
    uint16_t raw;
    if (si7005_read_reg16(handle, SI7005_REG_HUMIDITY, &raw) != 0)
        return -1;

    /*
     * Humidity conversion:
     *   RH = (raw / 65536.0) * 100.0
     * (From datasheet table 2.)
     */
    *rh = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio library ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus and configure sensor ---- */
    g_i2c_handle = si7005_open();
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] Failed to open Si7005 on I2C bus %d at addr 0x%02X\n",
                I2C_BUS, SI7005_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7005 reader started.  Bus %d, addr 0x%02X.  Press Ctrl-C to stop.\n",
           I2C_BUS, SI7005_ADDR);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temp_c = 0.0f, rh = 0.0f;
        bool ok = true;

        if (si7005_read_temperature(g_i2c_handle, &temp_c) != 0)
            ok = false;

        if (ok && si7005_read_humidity(g_i2c_handle, &rh) != 0)
            ok = false;

        if (ok) {
            printf("Temperature: %.2f °C  |  Humidity: %.2f %%\n", temp_c, rh);
        } else {
            fprintf(stderr, "[WARN] I2C read failure; re-opening bus.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;

            /* Brief recovery delay before retry */
            gpioDelay(100000); /* 100 ms */

            g_i2c_handle = si7005_open();
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[ERROR] Re-open failed; will retry next cycle.\n");
            }
        }

        /* Sleep SAMPLE_PERIOD_US, but wake early on signal */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

