/*
 * MPU-6050 I2C reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3)
 * Sensor: TDK InvenSense MPU-6050 (WHO_AM_I = 0x68)
 *
 * Build: gcc -O2 -Wall -o mpu6050 mpu6050.c -lpigpio -lrt
 * Run:   sudo ./mpu6050
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (from datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

#define I2C_BUS             1
#define SAMPLE_PERIOD_US    100000   /* 100 ms */

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read a single byte register; returns 0 on success, -1 on error ---- */
static int read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        return -1;
    *val = (uint8_t)rc;
    return 0;
}

/* ---- Read a block of bytes starting at reg; returns 0 on success ---- */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len)
        return -1;
    return 0;
}

/* ---- Convert big-endian two's-complement bytes to int16 ---- */
static int16_t be16_to_int16(const uint8_t *p)
{
    return (int16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

/* ---- Verify sensor presence ---- */
static bool verify_sensor(int handle)
{
    uint8_t who;
    if (read_reg8(handle, MPU6050_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register.\n");
        return false;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I = 0x%02X, expected 0x%02X.\n",
                who, MPU6050_WHO_AM_I_VAL);
        return false;
    }
    return true;
}

/* ---- Initialise MPU-6050: wake from sleep, verify clock ---- */
static bool init_mpu6050(int handle)
{
    /* Wake up: clear SLEEP bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1.\n");
        return false;
    }
    /* Allow time for oscillator to stabilise */
    gpioDelay(100000); /* 100 ms */

    /* Verify clock source is internal Xtal */
    uint8_t pwr;
    if (read_reg8(handle, MPU6050_PWR_MGMT_1, &pwr) != 0) {
        fprintf(stderr, "Error: cannot read PWR_MGMT_1 after wake.\n");
        return false;
    }
    if ((pwr & 0x07) != 0x00) {
        fprintf(stderr, "Warning: PWR_MGMT_1 clock bits = 0x%02X (not internal Xtal).\n",
                pwr & 0x07);
        /* Continue anyway — user can check and re-init if needed */
    }
    return true;
}

/* ---- Read one sample and print it ---- */
static void read_and_print(int handle)
{
    uint8_t buf[14];

    /*
     * Read 14 bytes starting at ACCEL_XOUT_H (0x3B):
     *   [0..1]  accel X, [2..3]  accel Y, [4..5]  accel Z
     *   [6..7]  temp   (skipped), [8..9]  gyro X, [10..11] gyro Y, [12..13] gyro Z
     */
    if (read_block(handle, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Error: I2C block read failed.\n");
        return;
    }

    int16_t ax = be16_to_int16(&buf[0]);
    int16_t ay = be16_to_int16(&buf[2]);
    int16_t az = be16_to_int16(&buf[4]);
    /* Temperature bytes are at buf[6] and buf[7] — skipped here */
    int16_t gx = be16_to_int16(&buf[8]);
    int16_t gy = be16_to_int16(&buf[10]);
    int16_t gz = be16_to_int16(&buf[12]);

    printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
           ax, ay, az, gx, gy, gz);
    fflush(stdout);
}

int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at MPU6050 address ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence ---- */
    if (!verify_sensor(g_i2c_handle)) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (!init_mpu6050(g_i2c_handle)) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 logging started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, MPU6050_ADDR);
    printf("Press Ctrl+C to stop.\n");
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        read_and_print(g_i2c_handle);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    fflush(stdout);

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("Done.\n");
    return EXIT_SUCCESS;
}

