/*
 * SHT40 Temperature & Humidity Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHT40 VIN  -> Pi 3V3 (pin 1)
 *   SHT40 GND  -> Pi GND (pin 9)
 *   SHT40 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   SHT40 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -o sht40_reader sht40_reader.c -lpigpio -lrt
 * Run:    sudo ./sht40_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ---- SHT40 constants (per Adafruit SHT40 datasheet) ---- */
#define SHT40_ADDR             0x44
#define SHT40_MEASURE_CMD      0xFD   /* high repeatability, clock stretching disabled */
#define SHT40_MEASURE_DELAY_US 10000 /* 10 ms worst-case conversion time */
#define SHT40_CRC_POLY         0x31
#define SHT40_CRC_INIT         0xFF

#define I2C_BUS                1
#define SAMPLE_PERIOD_US       5000000 /* 5 seconds */

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/*  CRC-8 calculation (polynomial 0x31, init 0xFF, no final XOR)       */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SHT40_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/*  Signal handler                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Open the I2C bus to the SHT40                                       */
/* ------------------------------------------------------------------ */
static int open_i2c(void)
{
    int handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SHT40_ADDR, handle);
        return -1;
    }
    return handle;
}

/* ------------------------------------------------------------------ */
/*  Read temperature and humidity from the SHT40                       */
/*  Returns 0 on success, -1 on I/O or CRC error.                      */
/* ------------------------------------------------------------------ */
static int read_sht40(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_MEASURE_CMD;
    uint8_t data[6];

    /* Send the measurement command */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd 0x%02X)\n", cmd);
        return -1;
    }

    /* Wait for the measurement to complete (datasheet: max 10 ms) */
    gpioDelay(SHT40_MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC in byte 2) */
    if (sht40_crc8(data, 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(data, 2), data[2]);
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC in byte 5) */
    if (sht40_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(data + 3, 2), data[5]);
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open the I2C bus to the SHT40 */
    g_i2c_handle = open_i2c();
    if (g_i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (g_running) {
        if (read_sht40(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; re-opening I2C bus.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000); /* 100 ms back-off before retry */
            g_i2c_handle = open_i2c();
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[FATAL] Failed to re-open I2C bus.\n");
                break;
            }
        }

        /* Sleep 5 seconds in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    /* Graceful cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    fprintf(stderr, "[INFO] Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

