#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90614_ADDR  0x5A
#define TA_REG         0x06
#define TO_REG         0x07
#define LOG_FILE       "temperature_log.csv"
#define READ_INTERVAL  5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_temperatures(int fd, float *ambient, float *object) {
    int16_t raw_ta, raw_to;
    if (i2c_read_reg16(fd, TA_REG, &raw_ta) != 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, TO_REG, &raw_to) != 0) {
        return -1;
    }
    *ambient = (float)raw_ta * 0.02f - 273.15f;
    *object  = (float)raw_to * 0.02f - 273.15f;
    return 0;
}

static int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        return -1;
    }
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen " LOG_FILE);
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient, object;
        if (read_temperatures(fd, &ambient, &object) != 0) {
            fprintf(stderr, "Error reading temperature data.\n");
        } else {
            if (log_temperature(fp, ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        }
        sleep(READ_INTERVAL);
    }

    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

