/*
 * Raspberry Pi Zero W - STS30-DIS Temperature Logger
 *
 * Reads temperature from a Sensirion STS30-DIS sensor on I2C bus 1
 * (address 0x3A) every 5 seconds and appends timestamped values to
 * enclosure_temp_log.txt.  Errors are logged to error_log.txt.
 *
 * Build:  gcc -O2 -Wall -o sts30_logger sts30_logger.c -lpigpio -lrt
 * Run:    sudo ./sts30_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define STS30_ADDR           0x3A
#define STS30_MEASURE_CMD    0x3224   /* clock stretching disabled, no averaging */
#define STS30_MEASURE_MSB    (STS30_MEASURE_CMD >> 8)
#define STS30_MEASURE_LSB    (STS30_MEASURE_CMD & 0xFF)
#define STS30_MEASURE_DELAY  5000     /* microseconds (5 s) */
#define SAMPLE_INTERVAL_US   5000000  /* 5 s between samples */
#define LOG_FILE             "enclosure_temp_log.txt"
#define ERROR_LOG_FILE       "error_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *message)
{
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen(error_log.txt)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] ERROR: %s\n", message);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Data logging                                                        */
/* ------------------------------------------------------------------ */
static void log_data(float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(enclosure_temp_log.txt)");
        log_error("Failed to open data log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* STS30-DIS temperature read                                          */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and stores the temperature in *out_temp.
 * Returns -1 on I2C write failure, -2 on read failure, -3 on checksum
 * mismatch, and -4 if the sensor did not acknowledge the measurement
 * command (i.e., the bus returned 0 bytes).
 */
static int read_sts30_temperature(int handle, float *out_temp)
{
    uint8_t cmd[2] = { STS30_MEASURE_MSB, STS30_MEASURE_LSB };
    uint8_t buf[3];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        log_error("I2C write failed (command 0x3224)");
        return -1;
    }

    /* Wait for conversion to complete (datasheet: typ 1.5 ms, max 5 ms) */
    gpioDelay(STS30_MEASURE_DELAY);

    /* Read 3 bytes: MSB, LSB, CRC */
    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        log_error("I2C read failed (expected 3 bytes)");
        return -2;
    }

    /* Checksum validation */
    uint8_t crc = 0;
    for (int i = 0; i < 2; i++)
        crc ^= buf[i];
    if (crc != buf[2]) {
        log_error("STS30-DIS checksum mismatch");
        return -3;
    }

    /* Convert raw value to Celsius */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out_temp = (float)raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at STS30-DIS address 0x3A */
    g_i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n",
                STS30_ADDR, I2C_BUS);
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STS30-DIS temperature logger started.  Sampling every 5 s.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        int rc = read_sts30_temperature(g_i2c_handle, &temperature);

        if (rc == 0) {
            log_data(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else if (rc == -4) {
            log_error("Sensor did not acknowledge measurement command");
        } else {
            /* rc == -1, -2, -3 already logged inside read_sts30_temperature */
        }

        /* Sleep 5 s, but wake early if a signal arrives */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

