    if (crc != buf[2]) {
        log_error("STS30-DIS checksum mismatch");
        return -3;
    }

    /* Convert raw value to Celsius */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out_temp = (float)raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at STS30-DIS address 0x3A */
    g_i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X on bus %d\n",
                STS30_ADDR, I2C_BUS);
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STS30-DIS temperature logger started.  Sampling every 5 s.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        int rc = read_sts30_temperature(g_i2c_handle, &temperature);

        if (rc == 0) {
            log_data(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else if (rc == -4) {
            log_error("Sensor did not acknowledge measurement command");
        } else {
            /* rc == -1, -2, -3 already logged inside read_sts30_temperature */
        }

        /* Sleep 5 s, but wake early if a signal arrives */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

