/*
 * Raspberry Pi Zero W - Sensirion SDP810-125Pa differential pressure logger
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   SDP810 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c -lpigpio -lrt
 *   (pigpio must be installed and run with sudo)
 *
 * Run:
 *   sudo ./sdp810_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define SDP810_I2C_ADDRESS   0x21          /* SDP810-125Pa default I2C address */
#define LOG_FILE             "pressure_log.csv"
#define SAMPLE_INTERVAL_US   1000000       /* 1 second */
#define MEASUREMENT_DELAY_US 1000          /* 1 ms (datasheet: typ. 1 ms) */

/* SDP810 continuous measurement command (datasheet) */
static const uint8_t CMD_CONTINUOUS[2] = { 0x36, 0x12 };

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* --------------------------- CRC-8 (Sensirion) --------------------------- */

/*
 * Sensirion CRC-8 polynomial: x^8 + x^5 + x^4 + 1  (0x31)
 * Initialization value: 0xFF
 */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* --------------------------- Sensor helpers ------------------------------ */

/*
 * Send the continuous-measurement command to the SDP810.
 * Returns 0 on success, -1 on failure.
 */
static int sdp810_start_continuous(void)
{
    if (i2cWriteDevice(g_i2c_handle, (char *)CMD_CONTINUOUS, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to send continuous-measurement command\n");
        return -1;
    }
    return 0;
}

/*
 * Read the 9-byte measurement frame and validate CRCs.
 * Layout: [P_MSB, P_LSB, P_CRC, T_MSB, T_LSB, T_CRC, S_MSB, S_LSB, S_CRC]
 * Returns 0 on success, -1 on failure.
 */
static int sdp810_read_measurement(int16_t *raw_pressure,
                                   int16_t *raw_temperature,
                                   int16_t *raw_scale_factor)
{
    uint8_t buf[9];

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] Failed to read 9-byte measurement frame\n");
        return -1;
    }

    /* Validate CRCs for pressure, temperature, and scale-factor fields */
    if (sdp_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    *raw_pressure     = (int16_t)((buf[0] << 8) | buf[1]);
    *raw_temperature  = (int16_t)((buf[3] << 8) | buf[4]);
    *raw_scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    return 0;
}

/* ------------------------------ Logging ---------------------------------- */

static int log_data(float pressure_pa, float temperature_c)
{
    int is_new = (access(LOG_FILE, F_OK) != 0);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    if (is_new) {
        if (fprintf(fp, "timestamp,pressure_pa,temperature_c\n") < 0) {
            perror("[ERROR] fprintf header");
            fclose(fp);
            return -1;
        }
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("[ERROR] time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "[ERROR] gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c) < 0) {
        perror("[ERROR] fprintf data");
        fclose(fp);
        return -1;}

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP810_I2C_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start continuous measurement --- */
    if (sdp810_start_continuous() != 0) {
        fprintf(stderr, "[FATAL] Sensor not detected or bus error\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810 logger started. Logging to %s every 1 s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (!g_terminate) {
        /* Issue measurement command (datasheet: after 1 ms) */
        gpioDelay(MEASUREMENT_DELAY_US);

        int16_t raw_p = 0, raw_t = 0, raw_s = 0;
        if (sdp810_read_measurement(&raw_p, &raw_t, &raw_s) != 0) {
            fprintf(stderr, "[WARN] Measurement read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Guard against invalid scale factors (e.g. 0) */
        if (raw_s == 0) {
            fprintf(stderr, "[WARN] Scale factor is zero; skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Convert raw values with received scale factors */
        float pressure_pa = (float)raw_p / (float)raw_s;
        float temperature_c = (float)raw_t / (float)raw_s;

        if (log_data(pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "[WARN] Logging failed\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

