/*
 * SHT40 humidity & temperature logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SHT40 VDD  -> 3.3 V (Pin 1)
 *   SHT40 GND  -> GND   (Pin 9)
 *   SHT40 SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SHT40 SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -o sht40_logger sht40_logger.c
 * Run:    ./sht40_logger   (requires r/w access to /dev/i2c-1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44          /* 7-bit address */
#define MEASURE_CMD    0xFD          /* high repeatability, clock stretching disabled */
#define MEASURE_DELAY  10000         /* microseconds (10 ms) */
#define LOG_INTERVAL   5             /* seconds */
#define LOG_FILE       "sht40_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Sensirion CRC-8 (polynomial 0x31, init 0xFF) ---- */
static uint8_t sht_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handling ---- */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Read one SHT40 sample ----
 * Returns 0 on success, -1 on error.
 */
static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    ssize_t w = write(g_i2c_fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "[SHT40] write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASURE_DELAY);

    uint8_t buf[6];
    ssize_t r = read(g_i2c_fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[SHT40] read failed (got %zd bytes): %s\n",
                r, r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC checks */
    if (sht_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[SHT40] temperature CRC mismatch\n");
        return -1;
    }
    if (sht_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[SHT40] humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "[SHT40] temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[SHT40] humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

/* ---- Logging ---- */
static void log_data(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temperature, humidity);
    fflush(g_log_fp);
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SHT40_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 logger started. Logging to %s every %d s. Press Ctrl-C to stop.\n",
           LOG_FILE, LOG_INTERVAL);

    while (g_running) {
        float temperature, humidity;
        if (read_sht40(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("%s  T=%.2f C  H=%.2f %%\n",
                   "sample", temperature, humidity);
        } else {
            fprintf(stderr, "[SHT40] read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

