/*
 * Raspberry Pi Zero W – Sensirion SDP31 differential pressure logger
 *
 * Wiring:
 *   SDP31 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP31 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP31 VDD  -> 3.3 V
 *   SDP31 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 * Run:    sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SDP31_ADDR           0x21          /* Sensirion SDP31 default I2C address */

#define CMD_CONT_MEAS        0x362F        /* Continuous measurement command */
#define MEAS_DELAY_US        1000          /* Min. conversion time after trigger */
#define SAMPLE_INTERVAL_US   100000        /* 100 ms sampling interval */
#define MAX_RETRIES          3
#define RETRY_BASE_US        10000         /* 10 ms backoff base */

#define LOG_FILE_NAME        "airflow.log"

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------- Sensirion CRC-8 ----------------------------- */

/*
 * Sensirion SDP31 CRC-8 polynomial: 0x31, init: 0xFF, no final XOR.
 */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- I2C helpers ------------------------------- */

/*
 * Write a 16-bit command to the SDP31.
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the SDP31.
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, (int)len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if ((size_t)rc != len) {
        fprintf(stderr, "[ERROR] Short read: got %d of %zu bytes\n", rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------- Sensor operations --------------------------- */

/*
 * Trigger continuous measurement and wait for the first conversion.
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_start_continuous(int handle)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (sdp31_write_cmd(handle, CMD_CONT_MEAS) == 0) {
            gpioDelay(MEAS_DELAY_US);
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            gpioDelay((uint32_t)(RETRY_BASE_US << attempt));
    }
    return -1;
}

/*
 * Read one measurement frame and validate CRCs.
 * pressure_pa  – differential pressure in pascals
 * temperature_c – temperature in degrees Celsius
 * Returns 0 on success, -1 on failure.
 */
static int sdp31_read_measurement(int handle, float *pressure_pa, float *temperature_c)
{
    uint8_t data[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (sdp31_read_bytes(handle, data, sizeof(data)) == 0) {
            /* CRC checks: bytes 0-1, 3-4 */
            if (sensirion_crc8(&data[0], 2) != data[2]) {
                fprintf(stderr, "[WARN] Pressure CRC mismatch (attempt %d)\n", attempt + 1);
                gpioDelay((uint32_t)(RETRY_BASE_US << attempt));
                continue;
            }
            if (sensirion_crc8(&data[3], 2) != data[5]) {
                fprintf(stderr, "[WARN] Temperature CRC mismatch (attempt %d)\n", attempt + 1);
                gpioDelay((uint32_t)(RETRY_BASE_US << attempt));
                continue;
            }

            int16_t raw_pressure    = (int16_t)((data[0] << 8) | data[1]);
            int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);

            /* SDP31 conversion formulas (datasheet) */
            *pressure_pa    = (float)raw_pressure    * 0.01f;   /* Pa */
            *temperature_c  = (float)raw_temperature * 0.01f;   /* °C */
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            gpioDelay((uint32_t)(RETRY_BASE_US << attempt));
    }
    return -1;
}

/* ----------------------------- Logging --------------------------------- */

static void log_data(FILE *fp, float pressure_pa, float temperature_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c);
    fflush(fp);
}

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP31_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE_NAME ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- start continuous measurement --- */
    if (sdp31_start_continuous(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Failed to start continuous measurement\n");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP31 logging started. Press Ctrl+C to stop.\n");

    /* --- main sampling loop --- */
    while (g_running) {
        float pressure_pa = 0.0f, temperature_c = 0.0f;

        if (sdp31_read_measurement(g_i2c_handle, &pressure_pa, &temperature_c) == 0) {
            log_data(g_log_file, pressure_pa, temperature_c);
        } else {
            fprintf(stderr, "[WARN] Measurement read failed; will retry next cycle\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- graceful shutdown --- */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

