/*
 * Si7015 Temperature & Humidity Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si7015 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si7015 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si7015 VDD -> 3.3 V (pin 1)
 *   Si7015 GND -> GND  (pin 6)
 *
 * I2C address: 0x40 (7-bit)
 *
 * Build: gcc -O2 -Wall -o si7015_logger si7015_logger.c -lpigpio -lrt
 * Run:   sudo ./si7015_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SI7015_ADDR          0x40

/* Si7015 command set (No Hold Master mode) */
#define CMD_MEASURE_TEMP     0xE3   /* Temperature, clock stretching disabled */
#define CMD_MEASURE_HUMID    0xE5   /* Humidity, clock stretching disabled   */

/* Conversion time for No Hold Master mode is ~20 ms; we poll up to 100 ms */
#define MEASURE_TIMEOUT_US   100000
#define POLL_INTERVAL_US     1000   /* 1 ms between polls */

#define SAMPLE_INTERVAL_S    5
#define LOG_FILE             "sensor_data.txt"

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Error helpers ----------------------------- */

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* --------------------------- I2C helpers ------------------------------- */

/*
 * Write a single command byte to the Si7015.
 * Returns 0 on success, -1 on failure.
 */
static int si7015_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        log_error("i2cWriteByte failed");
        return -1;
    }
    return 0;
}

/*
 * Read a 2-byte measurement result from the Si7015.
 * Returns 0 on success and fills *out_raw; -1 on failure.
 */
static int si7015_read_measurement(int handle, uint16_t *out_raw)
{
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        log_error("i2cReadDevice returned unexpected byte count");
        return -1;
    }
    *out_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a measurement and wait for completion (No Hold Master mode).
 * Returns 0 on success, -1 on timeout or I/O error.
 */
static int si7015_trigger_and_wait(int handle, uint8_t cmd, uint16_t *out_raw)
{
    if (si7015_write_cmd(handle, cmd) != 0)
        return -1;

    uint32_t elapsed = 0;
    while (elapsed < MEASURE_TIMEOUT_US) {
        if (si7015_read_measurement(handle, out_raw) == 0)
            return 0;
        gpioDelay(POLL_INTERVAL_US);
        elapsed += POLL_INTERVAL_US;
    }

    log_error("measurement timeout (sensor may be absent or bus stuck)");
    return -1;
}

/* --------------------------- Conversion -------------------------------- */

static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* --------------------------- Logging ----------------------------------- */

static void log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("fopen log file failed");
        return;
    }

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temp_c, rh);
    fclose(fp);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n",
           ts, temp_c, rh);
}

/* --------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        log_error("gpioInitialise failed");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("i2cOpen failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7015 logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;

        if (si7015_trigger_and_wait(g_i2c_handle, CMD_MEASURE_TEMP, &raw_t) != 0) {
            log_error("temperature measurement failed");
            break;
        }
        if (si7015_trigger_and_wait(g_i2c_handle, CMD_MEASURE_HUMID, &raw_h) != 0) {
            log_error("humidity measurement failed");
            break;
        }

        float temp_c = raw_to_celsius(raw_t);
        float rh     = raw_to_humidity(raw_h);

        log_data(temp_c, rh);

        /* Sleep in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- Cleanup --- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

