    float temperature;  /* degrees C */
} sensor_data_t;

/*
 * Read one 9-byte measurement frame from the SDP800.
 * Layout: [P_MSB P_LSB P_CRC] [T_MSB T_LSB T_CRC] [S_MSB S_LSB S_CRC]
 */
static int read_sensor_data(int fd, sensor_data_t *data)
{
    uint8_t raw[9];

    if (i2c_read(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* CRC checks */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t dp_raw   = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t temp_raw = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t scale    = (int16_t)((raw[6] << 8) | raw[7]);

    if (scale == 0) {
        fprintf(stderr, "invalid scale factor (0)\n");
        return -1;
    }

    data->pressure    = (float)dp_raw   / (float)scale;
    data->temperature = (float)temp_raw / 200.0f;   /* °C / 200 */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const sensor_data_t *data)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0)
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, data->pressure, data->temperature);

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction() failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    if (i2c_write(g_i2c_fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* First measurement is ready after ~45 ms */
    usleep(MEAS_DELAY);

    sensor_data_t sensor_data;
    int consecutive_errors = 0;

    while (g_running) {
        if (read_sensor_data(g_i2c_fd, &sensor_data) == 0) {
            consecutive_errors = 0;
            if (log_data(&sensor_data) != 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
        }
        usleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    fprintf(stderr, "Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

