/*
 * Raspberry Pi Zero W - STS30-DIS Temperature Logger
 *
 * Wiring:
 *   STS30-DIS SDA -> GPIO2 (I2C bus 1 SDA)
 *   STS30-DIS SCL -> GPIO3 (I2C bus 1 SCL)
 *   STS30-DIS VDD -> 3.3 V
 *   STS30-DIS GND -> GND
 *
 * Build: gcc -O2 -Wall -o sts30_logger sts30_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define STS30_ADDR           0x30          /* default 7-bit I2C address */
#define STS30_CMD_MEASURE    0x3B08       /* single-shot, high repeatability */
#define STS30_MEASURE_MS     15            /* conversion time (ms) */
#define SAMPLE_INTERVAL_S    5             /* seconds between samples */
#define LOG_FILE             "enclosure_temp_log.txt"
#define ERROR_LOG_FILE       "error_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;
static FILE *g_err_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (g_err_fp) {
        fprintf(g_err_fp, "%s - ERROR: %s\n", ts, msg);
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s - ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read temperature from STS30                                         */
/* ------------------------------------------------------------------ */
static int read_sts30_temperature(double *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((STS30_CMD_MEASURE >> 8) & 0xFF),
        (uint8_t)(STS30_CMD_MEASURE & 0xFF)
    };
    uint8_t buf[3];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 2) {
        log_error("I2C write failed (command 0x3B08)");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(STS30_MEASURE_MS * 1000);   /* microseconds */

    /* Read 3 bytes: MSB, LSB, CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 3) != 3) {
        log_error("I2C read failed (3-byte response)");
        return -1;
    }

    /* Validate CRC */
    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC mismatch on temperature data");
        return -1;
    }

    /* Convert raw 16-bit value to Celsius */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (double)raw / 200.0;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, STS30_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERROR_LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("STS30-DIS logger started. Logging to %s, errors to %s\n",
           LOG_FILE, ERROR_LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        double temperature;

        if (read_sts30_temperature(&temperature) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(g_log_fp, "%s, %.2f\n", ts, temperature);
            fflush(g_log_fp);
            printf("%s, %.2f C\n", ts, temperature);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

