    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    /* SDP800-500Pa conversion: 0.01 Pa/LSB, 0.5 C/LSB */
    *pressure    = (float)raw_pressure * 0.01f;
    *temperature = (float)raw_temp     * 0.5f;
    return 0;
}

