    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    /* Start continuous measurement */
    if (i2c_write(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", SDP800_ADDR);
        goto cleanup;
    }

    /* Wait for first measurement to be ready (max ~45 ms) */
    usleep(50000);

    fp = fopen(LOG_FILE, "a");
