        } else {
            fprintf(stderr, "Read failed; continuing\n");
        }
        usleep(SAMPLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return ret;
}

