        rc = i2cWriteByte(i2c_handle, SI7021_CMD_MEASURE_TEMP);
        if (rc < 0) {
            fprintf(stderr, "[WARN] i2cWriteByte (measure) failed: %d (attempt %d/%d)\n",
                    rc, attempt + 1, I2C_RETRIES);
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        rc = i2cReadDevice(i2c_handle, buf, 2);
        if (rc == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *out = (float)raw / 10.0f;
            return 0;
        }

        fprintf(stderr, "[WARN] i2cReadDevice returned %d (attempt %d/%d)\n",
                rc, attempt + 1, I2C_RETRIES);
        gpioDelay(I2C_RETRY_DELAY_US);
    }

    fprintf(stderr, "[ERROR] Temperature read failed after %d retries.\n", I2C_RETRIES);
    return -1;
}

/* ------------------------------- Circular buffer -------------------------- */
static void add_to_buffer(float temperature)
{
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].timestamp   = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* --------------------------------- Fan control ---------------------------- */
static void control_fan(float temperature)
{
    static bool fan_on = false;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("[INFO] Temperature %.1f °C – fan ON\n", temperature);
        } else {
            fprintf(stderr, "[ERROR] Failed to set GPIO%d high.\n", FAN_GPIO);
        }
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("[INFO] Temperature %.1f °C – fan OFF\n", temperature);
        } else {
            fprintf(stderr, "[ERROR] Failed to set GPIO%d low.\n", FAN_GPIO);
        }
    }
}

/* ------------------------------- Signal / cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    /* Ensure fan is off before terminating pigpio */
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

/* ---------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed.\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0); /* Fan off at startup */

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialisation failed – sensor may be absent.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Si7021 fan controller running.  Ctrl+C to exit.\n");

    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            control_fan(temperature);
            printf("[INFO] Temperature: %.1f °C\n", temperature);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed – will retry next cycle.\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 20 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

