/*
 * SCD40 CO2 / Temperature / Humidity logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SCD40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o scd40_logger scd40_logger.c -lpigpio -lrt
 * Run:    sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SCD40 constants (per Sensirion SCD40 datasheet) ---- */
#define SCD40_I2C_ADDR          0x60
#define SCD40_BUS_NUM           1

#define CMD_START_PERIODIC      0x0010
#define CMD_STOP_PERIODIC       0x0104
#define CMD_GET_DATA_READY      0x0202
#define CMD_READ_MEASUREMENT    0x0300

#define SCD40_MEASUREMENT_DELAY_US 1000000  /* 1 s after start */
#define SCD40_POLL_INTERVAL_US    5000000  /* 5 s between polls */
#define SCD40_MAX_RETRIES         3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t scd40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Low-level I2C helpers ---- */
static int scd40_write_command(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_block(int handle, uint8_t *buf, size_t len)
{
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (got < %zu bytes)\n", len);
        return -1;
    }
    return 0;
}

/* ---- SCD40 measurement data ---- */
typedef struct {
    uint16_t co2;
    uint16_t temp_x100;   /* tenths of °C */
    uint16_t rh_x100;     /* tenths of %RH */
} scd40_data_t;

/* ---- Read one measurement block ---- */
static int scd40_read_measurement(int handle, scd40_data_t *out)
{
    uint8_t buf[9];
    if (scd40_read_block(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    if (scd40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on CO2 word\n");
        return -1;
    }
    if (scd40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature word\n");
        return -1;
    }
    if (scd40_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on humidity word\n");
        return -1;
    }

    out->co2          = ((uint16_t)buf[0] << 8) | buf[1];
    out->temp_x100    = ((uint16_t)buf[3] << 8) | buf[4];
    out->rh_x100      = ((uint16_t)buf[6] << 8) | buf[7];
    return 0;
}

/* ---- Data-ready flag ---- */
static int scd40_data_ready(int handle, bool *ready)
{
    if (scd40_write_command(handle, CMD_GET_DATA_READY) != 0)
        return -1;

    gpioDelay(2000);  /* 2 ms processing time */

    uint8_t buf[3];
    if (scd40_read_block(handle, buf, sizeof(buf)) != 0)
        return -1;

    if (scd40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }

    uint16_t word = ((uint16_t)buf[0] << 8) | buf[1];
    *ready = (word & 0x07FF) != 0;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, uint16_t co2, uint16_t temp_x100, uint16_t rh_x100)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%.1f,%.1f\n",
            ts, co2,
            temp_x100 / 100.0, rh_x100 / 100.0);
    fflush(fp);
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_write_command(g_i2c_handle, CMD_STOP_PERIODIC);
        gpioDelay(2000);  /* allow command to take effect */
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C ---- */
    g_i2c_handle = i2cOpen(SCD40_BUS_NUM, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                SCD40_BUS_NUM, SCD40_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("air_quality.log", "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(air_quality.log)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Start periodic measurement ---- */
    if (scd40_write_command(g_i2c_handle, CMD_START_PERIODIC) != 0) {
        fprintf(stderr, "[FATAL] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wait for first measurement to be ready */
    gpioDelay(SCD40_MEASUREMENT_DELAY_US);

    printf("SCD40 periodic measurement started. Logging to air_quality.log\n");
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        bool ready = false;
        if (scd40_data_ready(g_i2c_handle, &ready) != 0) {
            fprintf(stderr, "[WARN] data-ready poll failed; retrying next cycle\n");
            gpioDelay(SCD40_POLL_INTERVAL_US);
            continue;
        }

        if (!ready) {
            gpioDelay(SCD40_POLL_INTERVAL_US);
            continue;
        }

        scd40_data_t d;
        if (scd40_read_measurement(g_i2c_handle, &d) != 0) {
            fprintf(stderr, "[WARN] read measurement failed; retrying next cycle\n");
            gpioDelay(SCD40_POLL_INTERVAL_US);
            continue;
        }

        log_data(g_log_file, d.co2, d.temp_x100, d.rh_x100);
        printf("CO2: %u ppm  Temp: %.1f C  RH: %.1f %%\n",
               d.co2, d.temp_x100 / 100.0, d.rh_x100 / 100.0);

        gpioDelay(SCD40_POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

