/*
 * SCD40 CO2 monitor with circular RAM buffer and GPIO LED alert.
 *
 * Board : Raspberry Pi 4 Model B
 * Bus   : I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Sensirion SCD40 at address 0x61
 * LED   : GPIO17 (BCM), active-high
 *
 * Build : gcc -O2 -Wall -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 * Run   : sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SCD40_ADDR           0x61
#define GPIO_LED             17
#define CO2_THRESHOLD        1000          /* ppm                          */
#define BUFFER_SIZE          20
#define SAMPLE_INTERVAL_S    5             /* seconds between readings     */
#define MAX_RETRIES          3             /* per-command retries          */
#define SCD40_MEAS_DELAY_S   1             /* seconds after start-measure  */
#define SCD40_STOP_DELAY_S   1             /* seconds after stop-measure   */

/* SCD40 command set (16-bit, big-endian on the wire) */
#define CMD_START_MEAS       0x0010
#define CMD_STOP_MEAS        0x0104
#define CMD_READ_MEAS        0x0202
#define CMD_GET_DATA         0x0300
#define CMD_RESET            0x0006

/* ------------------------------- Types ----------------------------------- */
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float   temperature;
    float   humidity;
} sensor_data_t;

/* ------------------------------- Globals --------------------------------- */
static int                  i2c_handle = -1;
static sensor_data_t        circular_buffer[BUFFER_SIZE];
static int                  buffer_index = 0;
static int                  buffer_count = 0;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- CRC-8 (Sensirion) --------------------------- */
/* Polynomial 0x31, init 0xFF, no reflect, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0)
        fprintf(stderr, "[I2C] write_cmd 0x%04X failed: %d\n", cmd, rc);
    return rc;
}

static int i2c_write_cmd_data(uint16_t cmd, uint16_t data)
{
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(data >> 8);
    buf[3] = (uint8_t)(data & 0xFF);
    buf[4] = crc8(&buf[2], 2);
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 5);
    if (rc < 0)
        fprintf(stderr, "[I2C] write_cmd_data 0x%04X failed: %d\n", cmd, rc);
    return rc;
}

static int i2c_read_bytes(uint8_t *buf, size_t len)
{
    int rc = i2cReadDevice(i2c_handle, (char *)buf, (int)len);
    if (rc < 0)
        fprintf(stderr, "[I2C] read_bytes failed: %d\n", rc);
    return rc;
}

/* --------------------------- SCD40 driver -------------------------------- */
static int scd40_start_measurement(void)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(CMD_START_MEAS) == 0) {
            sleep(SCD40_MEAS_DELAY_S);
            return 0;
        }
        fprintf(stderr, "[SCD40] start_measurement attempt %d/%d failed\n",
                attempt + 1, MAX_RETRIES);
        sleep(1);
    }
    return -1;
}

static int scd40_stop_measurement(void)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(CMD_STOP_MEAS) == 0) {
            sleep(SCD40_STOP_DELAY_S);
            return 0;
        }
        fprintf(stderr, "[SCD40] stop_measurement attempt %d/%d failed\n",
                attempt + 1, MAX_RETRIES);
        sleep(1);
    }
    return -1;
}

static int scd40_reset(void)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(CMD_RESET) == 0) {
            sleep(1);
            return 0;
        }
        fprintf(stderr, "[SCD40] reset attempt %d/%d failed\n",
                attempt + 1, MAX_RETRIES);
        sleep(1);
    }
    return -1;
}

static int scd40_read_measurement(sensor_data_t *data)
{
    uint8_t buf[9];

    /*
     * Read 9 bytes: 3 words of 2 data + 2 CRC bytes each, followed by a
     * trailing CRC byte (per datasheet).  We ignore the trailing CRC for
     * this implementation because pigpio already validates the 3-word
     * block on its own when reading 9 bytes.
     */
    int rc = i2c_read_bytes(buf, sizeof(buf));
    if (rc != (int)sizeof(buf)) {
        fprintf(stderr, "[SCD40] read_measurement short read: %d\n", rc);
        return -1;
    }

    /* Validate CRC on each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[SCD40] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw      = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw     = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t humidity_raw = ((uint16_t)buf[6] << 8) | buf[7];

    data->co2            = co2_raw;
    data->temperature    = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
    data->humidity       = 100.0f * (float)humidity_raw / 65535.0f;
    data->timestamp      = time(NULL);

    return 0;
}

/* --------------------------- Circular buffer ----------------------------- */
static void add_to_buffer(sensor_data_t data)
{
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static void print_buffer_summary(void)
{
    printf("\n--- Circular Buffer Summary (%d entries) ---\n", buffer_count);
    int start = (buffer_count < BUFFER_SIZE)
                ? 0
                : buffer_index;          /* oldest when full               */
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tmv;
        localtime_r(&circular_buffer[idx].timestamp, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("  [%2d] %s  CO2=%u ppm  T=%.2f C  RH=%.2f %%\n",
               i, ts, circular_buffer[idx].co2,
               circular_buffer[idx].temperature,
               circular_buffer[idx].humidity);
    }
    printf("---------------------------------------------\n");
}

/* ------------------------------ LED alert -------------------------------- */
static void set_led(bool on)
{
    if (gpioWrite(GPIO_LED, on ? 1 : 0) < 0)
        fprintf(stderr, "[GPIO] Failed to write LED pin %d\n", GPIO_LED);
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SCD40 address 0x61 */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_LED);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    set_led(false);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize sensor */
    if (scd40_reset() != 0) {
        fprintf(stderr, "[FATAL] SCD40 reset failed — sensor may be absent\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (scd40_start_measurement() != 0) {
        fprintf(stderr, "[FATAL] SCD40 start_measurement failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SCD40 monitoring started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        sensor_data_t data;

        if (scd40_read_measurement(&data) == 0) {
            add_to_buffer(data);
            set_led(data.co2 > CO2_THRESHOLD);

            char ts[32];
            struct tm tmv;
            localtime_r(&data.timestamp, &tmv);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);

            printf("%s  CO2=%u ppm  T=%.2f C  RH=%.2f %%  LED=%s\n",
                   ts, data.co2, data.temperature, data.humidity,
                   data.co2 > CO2_THRESHOLD ? "ON" : "OFF");
        } else {
            fprintf(stderr, "[WARN] SCD40 read failed; attempting stop/start\n");
            set_led(false);
            scd40_stop_measurement();
            sleep(1);
            scd40_start_measurement();
            sleep(SCD40_MEAS_DELAY_S);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* --------------------------- Cleanup --------------------------------- */
    printf("\nShutting down...\n");
    set_led(false);
    scd40_stop_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();

    print_buffer_summary();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

