static int i2c_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0)
        fprintf(stderr, "[I2C] write_cmd 0x%04X failed: %d\n", cmd, rc);
    return rc;
