/*
 * TMP05 temperature sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TMP05 VCC  -> 3.3 V (pin 1)
 *   TMP05 GND  -> GND   (pin 9)
 *   TMP05 OUT  -> GPIO4 (BCM 4, physical pin 7)
 *
 * The TMP05 PWM output is a train of pulses where the high-pulse width
 * encodes the temperature; the total pulse period is a fixed reference.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_reader tmp05_reader.c -lpigpio -lrt
 * Run:    sudo ./tmp05_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          4          /* BCM 4, physical pin 7 */
#define LOG_FILE          "temperature_log.txt"
#define SAMPLE_PERIOD_US  5000000    /* 5 seconds */
#define EDGE_TIMEOUT_US   50000       /* 50 ms per edge wait */
#define TEMP_MIN          (-40.0f)
#define TEMP_MAX          (150.0f)
#define MAX_CONSEC_ERRORS 3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* Edge-wait with timeout                                              */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   > 0  : elapsed microseconds (>= timeout) on timeout,
 *   0    : edge detected,
 *   -1   : pigpio read error.
 */
static int wait_for_edge(int pin, int target_level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    if (start == 0) {
        return -1;
    }

    for (;;) {
        int level = gpioRead(pin);
        if (level < 0) {
            return -1;
        }
        if (level == target_level) {
            return 0;
        }
        if ((gpioTick() - start) >= timeout_us) {
            return (int)timeout_us;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Read one TMP05 cycle                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   0  : success (temp_out set),
 *  -1  : pigpio read error,
 *  -2  : timeout waiting for low-to-high transition,
 *  -3  : timeout waiting for high-to-low transition.
 */
static int read_tmp05(int pin, float *temp_out)
{
    /* Wait for the line to go HIGH (start of a new conversion cycle). */
    if (wait_for_edge(pin, 1, EDGE_TIMEOUT_US) != 0) {
        return -2;
    }

    uint32_t high_start = gpioTick();
    if (high_start == 0) {
        return -1;
    }

    /* Wait for the line to go LOW (end of the high pulse). */
    if (wait_for_edge(pin, 0, EDGE_TIMEOUT_US) != 0) {
        return -3;
    }

    uint32_t high_end = gpioTick();
    if (high_end == 0) {
        return -1;
    }

    uint32_t high_us = high_end - high_start;

    /*
     * TMP05 PWM:
     *   high_us / 1000000.0 * 150.0  -> temperature in °C.
     * The high-pulse width is proportional to the temperature.
     */
    *temp_out = (float)high_us / 1000000.0f * 150.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(FILE *fp, float temp)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s, Temperature: %.2f C\n", ts, temp);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s, ERROR: %s\n", ts, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature reader started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float temperature;
        int rc = read_tmp05(GPIO_PIN, &temperature);

        if (rc == 0) {
            consecutive_errors = 0;

            if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
                fprintf(stderr, "Warning: temperature %.2f C out of range [%.0f, %.0f]\n",
                        temperature, TEMP_MIN, TEMP_MAX);
                log_error(fp, "temperature out of range");
            } else {
                log_temperature(fp, temperature);
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            consecutive_errors++;
            const char *reason;
            switch (rc) {
                case -1: reason = "pigpio read error"; break;
                case -2: reason = "timeout waiting for high-to-low transition"; break;
                case -3: reason = "timeout waiting for low-to-high transition"; break;
                default: reason = "unknown error"; break;
            }
            fprintf(stderr, "Error reading TMP05: %s (consecutive: %d)\n",
                    reason, consecutive_errors);
            log_error(fp, reason);

            if (consecutive_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "Sensor malfunction suspected — logging to log file.\n");
                log_error(fp, "SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    fclose(fp);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

