/*
 * SHT35-DIS-B greenhouse simulator for Raspberry Pi 4 Model B
 *
 * Reads temperature and humidity from a Sensirion SHT35-DIS-B sensor
 * on I2C bus 1 (GPIO2=SDA, GPIO3=SCL), validates CRC-8, applies a
 * sinusoidal offset over one hour, and logs to environmental_data.txt
 * every 5 seconds.  Retries I2C reads up to 3 times; on unrecoverable
 * errors, logs NaN and continues.
 *
 * Build:  gcc -O2 -Wall -o sht35_sim sht35_sim.c -lpigpio -lm
 * Run:    sudo ./sht35_sim
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

#define I2C_BUS          1
#define SHT35_ADDR       0x44
#define MEASURE_CMD      0x2C34   /* high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 20000    /* 20 ms (datasheet: typ 15 ms) */
#define LOG_INTERVAL_S   5
#define MAX_RETRIES      3
#define RETRY_DELAY_S    1
#define LOG_FILE         "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read SHT35 with CRC validation ----
 * Returns 0 on success, -1 on failure.
 * Temperature in °C, humidity in %RH.
 */
static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t data[6];

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        /* Send measurement command */
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "[attempt %d/%d] I2C write failed\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        /* Wait for conversion (datasheet: typ 15 ms) */
        gpioDelay(MEASURE_DELAY_US);

        /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "[attempt %d/%d] I2C read failed\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        /* Validate CRC for temperature word */
        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "[attempt %d/%d] temperature CRC mismatch\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        /* Validate CRC for humidity word */
        if (crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "[attempt %d/%d] humidity CRC mismatch\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        /* Convert raw values to physical units */
        uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
        uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

        *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        /* Sanity range checks */
        if (*temperature < -40.0f || *temperature > 125.0f ||
            *humidity    <   0.0f || *humidity    > 100.0f) {
            fprintf(stderr, "[attempt %d/%d] out-of-range reading "
                            "(T=%.2f, RH=%.2f)\n",
                    attempt, MAX_RETRIES, *temperature, *humidity);
            if (attempt < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        return 0;
    }

    return -1;
}

/* ---- Apply sinusoidal offset over one hour ---- */
static void apply_greenhouse_offset(float *temperature, float *humidity)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);

    double elapsed = (double)(tm_utc.tm_hour * 3600 +
                              tm_utc.tm_min  * 60  +
                              tm_utc.tm_sec) / 3600.0;

    *temperature += 2.0f * (float)sin(2.0f * M_PI * elapsed);
    *humidity    += 5.0f * (float)sin(2.0f * M_PI * elapsed);
}

/* ---- Log one reading ---- */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT35 greenhouse simulator started.  Logging to %s every %d s.\n",
           LOG_FILE, LOG_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int rc = read_sht35(g_i2c_handle, &temperature, &humidity);

        if (rc == 0) {
            apply_greenhouse_offset(&temperature, &humidity);
            log_data(g_log_file, temperature, humidity);
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   "simulated", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; logging NaN.\n",
                    MAX_RETRIES);
            log_data(g_log_file, NAN, NAN);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

