            fprintf(stderr, "Sensor read failed after %d retries; logging NaN.\n",
                    MAX_RETRIES);
            log_data(g_log_file, NAN, NAN);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

