/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C address: 0x21 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x21
#define CSV_FILENAME   "airflow.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONV_TIME_MS   45         /* SDP810 conversion time (ms) */

/* SDP810 continuous measurement command (MSB first) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x1E };

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SDP810 spec       */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data                                                          */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;     /* Pa */
    float temperature;  /* °C */
} sensor_data_t;

/*
 * SDP810 9-byte data frame (big-endian, CRC-8 over each 2-byte word):
 *   [0..1] pressure MSB/LSB, [2] CRC
 *   [3..4] temperature MSB/LSB, [5] CRC
 *   [6..7] scale factor MSB/LSB, [8] CRC
 */
static int read_sensor_data(int fd, sensor_data_t *out)
{
    uint8_t raw[9];

    if (i2c_read(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Validate CRCs */
    for (int i = 0; i < 3; i++) {
        if (sdp_crc8(&raw[i * 3], 2) != raw[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure    = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_temperature = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t raw_scale       = (int16_t)((raw[6] << 8) | raw[7]);

    if (raw_scale == 0) {
        fprintf(stderr, "Invalid scale factor (0) — sensor not ready?\n");
        return -1;
    }

    /*
     * Sensor formulas (SDP810 datasheet):
     *   pressure    = raw_pressure / raw_scale * 0.01  (Pa)
     *   temperature = raw_temperature / 200.0          (°C)
     */
    out->pressure    = (float)raw_pressure    / (float)raw_scale * 0.01f;
    out->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                          */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SDP810_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    if (i2c_write(g_i2c_fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wait for first conversion */
    usleep(CONV_TIME_MS * 1000);

    /* Open CSV file */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_csv) == 0)
        fprintf(g_csv, "timestamp,pressure_pa,temperature_c\n");

    printf("SDP810 airflow logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        sensor_data_t d;

        if (read_sensor_data(g_i2c_fd, &d) == 0) {
            if (log_data(g_csv, d.pressure, d.temperature) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   d.pressure, d.temperature);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

