/*
 * Raspberry Pi Zero W – SHT35 DIS-B temperature & humidity logger
 *
 * Wiring:
 *   SHT35 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SHT35 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SHT35 VDD  -> 3.3 V
 *   SHT35 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c \
 *       -lm -lrt
 *
 * The SHT35 DIS-B is a 7-bit I2C address 0x44 (ADDR pin tied to GND).
 * Single-shot, high-repeatability, clock-stretching disabled:
 *   write [0x2C 0x0D]  →  measurement ~15 ms, 6 bytes + 2 CRC bytes each
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT35_ADDR     0x44
#define CSV_FILENAME   "environment.csv"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define MEAS_DELAY_MS  15         /* SHT35 conversion time (ms) */

/* SHT35 single-shot, high repeatability, clock-stretching disabled */
static const uint8_t CMD_MEASURE[2] = { 0x2C, 0x0D };

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                          */
/* ------------------------------------------------------------------ */
static int read_sht35(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                          */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temperature, float humidity)
{
    int need_header = 0;

    /* Check whether file exists and is non-empty */
    FILE *check = fopen(filename, "r");
    if (check == NULL) {
        if (errno == ENOENT)
            need_header = 1;
        else {
            fprintf(stderr, "Cannot open %s for check: %s\n",
                    filename, strerror(errno));
            return -1;
        }
    } else {
        fseek(check, 0, SEEK_END);
        if (ftell(check) == 0)
            need_header = 1;
        fclose(check);
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s for append: %s\n",
                filename, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&t, &tm_buf);
    char ts[32];
    if (tm == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto done;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto done;
    }

    if (ioctl(fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SHT35_ADDR, strerror(errno));
        goto cleanup_fd;
    }

    printf("SHT35 logger started on %s (addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, SHT35_ADDR);

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0)
                fprintf(stderr, "Warning: CSV logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup_fd:
    if (fd >= 0)
        close(fd);
done:
    printf("\nShutting down.\n");
    return rc;
}

code:
/*
 * Si7021 greenhouse monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si7021 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   Si7021 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   Si7021 VDD -> 3.3 V
 *   Si7021 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c -lpigpio -lrt
 * Run:    sudo ./greenhouse
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SI7021_ADDR      0x40          /* default 7-bit I2C address */
#define LOG_FILE         "environment.log"
#define SAMPLE_PERIOD_S  5             /* seconds between samples */
#define MEASURE_TIMEOUT  100           /* ms to wait for measurement */
#define RESET_CMD        0xFE          /* soft reset command */
#define TEMP_CMD         0xE3          /* temperature measurement, hold master */
#define HUM_CMD          0xE5          /* humidity measurement, hold master */
#define CRC_POLY         0x31          /* Si7021 CRC-8 polynomial x^8 + x^5 + x^4 + 1 */
#define CRC_INIT         0xFF          /* Si7021 CRC-8 initial value */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Si7021)                                                      */
/* ------------------------------------------------------------------ */
static uint8_t si7021_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ CRC_POLY)
                               : (uint8_t)(crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (i2cWriteByte(fd, cmd) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the Si7021.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(fd, (char *)buf, len);
    if (n < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (pigpio rc=%d)\n", n);
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "[ERROR] short read: got %d of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reset                                                        */
/* ------------------------------------------------------------------ */
static int si7021_reset(int fd)
{
    if (i2c_write_cmd(fd, RESET_CMD) != 0)
        return -1;
    gpioDelay(15000);  /* datasheet: wait >= 15 ms after reset */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Measurement                                                         */
/* ------------------------------------------------------------------ */
static int si7021_measure(int fd, uint8_t cmd, uint16_t *raw)
{
    if (i2c_write_cmd(fd, cmd) != 0)
        return -1;

    for (int elapsed = 0; elapsed < MEASURE_TIMEOUT; elapsed += 5) {
        gpioDelay(5000);  /* 5 ms granularity */

        uint8_t buf[3];
        if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
            return -1;

        /* CRC byte is the third byte */
        if (si7021_crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on cmd 0x%02X\n", cmd);
            return -1;
        }

        *raw = (uint16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }

    fprintf(stderr, "[ERROR] measurement 0x%02X timed out after %d ms\n",
            cmd, MEASURE_TIMEOUT);
    return -1;
}

static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    fclose(fp);
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,ERROR,ERROR\n", ts);
    fclose(fp);

    fprintf(stderr, "[ERROR] %s\n", msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Probe: try a soft reset to confirm the sensor is present.
     * A NACK on the reset command indicates no device at this address.
     */
    if (si7021_reset(g_i2c_fd) != 0) {
        fprintf(stderr, "[FATAL] No Si7021 detected at 0x%02X on bus %d\n",
                SI7021_ADDR, I2C_BUS);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new/empty */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        if (!fp) {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
                fclose(fp);
            } else {
                perror("[WARN] fopen(" LOG_FILE ")");
            }
        } else {
            fclose(fp);
        }
    }

    printf("Si7021 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;
        int ok = 1;

        if (si7021_measure(g_i2c_fd, TEMP_CMD, &raw_t) != 0)
            ok = 0;

        if (ok && si7021_measure(g_i2c_fd, HUM_CMD, &raw_h) != 0)
            ok = 0;

        if (ok) {
            float temp_c = raw_to_celsius(raw_t);
            float rh     = raw_to_humidity(raw_h);
            log_data(temp_c, rh);
            printf("T=%.2f C  RH=%.2f %%\n", temp_c, rh);
        } else {
            log_error("measurement failed; issuing soft reset");
            (void)si7021_reset(g_i2c_fd);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int s = 0; s < SAMPLE_PERIOD_S * 10 && g_running; s++)
            gpioDelay(100000);
    }

    /* Graceful cleanup */
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

