    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,ERROR,ERROR\n", ts);
    fclose(fp);

    fprintf(stderr, "[ERROR] %s\n", msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Probe: try a soft reset to confirm the sensor is present.
     * A NACK on the reset command indicates no device at this address.
     */
    if (si7021_reset(g_i2c_fd) != 0) {
        fprintf(stderr, "[FATAL] No Si7021 detected at 0x%02X on bus %d\n",
                SI7021_ADDR, I2C_BUS);
        i2cClose(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new/empty */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        if (!fp) {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
                fclose(fp);
            } else {
                perror("[WARN] fopen(" LOG_FILE ")");
            }
        } else {
            fclose(fp);
        }
    }

    printf("Si7021 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;
        int ok = 1;

        if (si7021_measure(g_i2c_fd, TEMP_CMD, &raw_t) != 0)
            ok = 0;

        if (ok && si7021_measure(g_i2c_fd, HUM_CMD, &raw_h) != 0)
            ok = 0;

        if (ok) {
            float temp_c = raw_to_celsius(raw_t);
            float rh     = raw_to_humidity(raw_h);
            log_data(temp_c, rh);
            printf("T=%.2f C  RH=%.2f %%\n", temp_c, rh);
        } else {
            log_error("measurement failed; issuing soft reset");
            (void)si7021_reset(g_i2c_fd);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int s = 0; s < SAMPLE_PERIOD_S * 10 && g_running; s++)
            gpioDelay(100000);
    }

    /* Graceful cleanup */
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

