/*
 * SDP810-500Pa differential pressure & temperature logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Sensirion SDP810-500Pa, I2C address 0x21
 *
 * Build:  gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 * Run:    sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS              1
#define SDP810_ADDR          0x21          /* factory default, A1 tied to GND */
#define MEASURE_CMD_MSB      0x36          /* continuous measurement command  */
#define MEASURE_CMD_LSB      0x1E          /* mass-flow / differential mode   */
#define CONVERSION_MS        45            /* SDP810 mass-flow conversion time */
#define SAMPLE_MS            1000          /* one sample per second            */
#define DATA_FILE            "airflow.dat"
#define MAX_RETRIES          3

/* --------------------------- Global state ------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_data_file  = NULL;
static bool     g_pigpio_inited = false;

/* --------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static uint8_t crc8(const uint8_t *data, int len);
static int  init_i2c(void);
static int  start_measurement(void);
static int  read_sensor_data(float *pressure, float *temperature);
static int  log_data(float pressure, float temperature);
static void cleanup(void);

/* ----------------------------- CRC-8 ----------------------------------- */
/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflection */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_inited = true;

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------- Start continuous measurement --------------------- */
static int start_measurement(void)
{
    uint8_t cmd[2] = { MEASURE_CMD_MSB, MEASURE_CMD_LSB };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (start measurement) failed: %d\n", rc);
        return -1;
    }
    return 0;
}

/* --------------------- Read 9-byte sensor frame ------------------------ */
static int read_sensor_data(float *pressure, float *temperature)
{
    uint8_t buf[9];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 9).\n", rc);
        return -1;
    }

    /* CRC validation */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch.\n");
        return -1;
    }

    /* Raw values are big-endian, signed 16-bit */
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /* Scale factors are in the last 3 bytes (big-endian) */
    int16_t scale_p = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t scale_t = (int16_t)((buf[8] << 8) | buf[0]);   /* note: byte order swapped */

    if (scale_p == 0 || scale_t == 0) {
        fprintf(stderr, "Error: invalid scale factor (p=%d, t=%d).\n", scale_p, scale_t);
        return -1;
    }

    /* Convert raw to physical units */
    *pressure    = (float)raw_pressure    / (float)scale_p;
    *temperature = (float)raw_temperature / (float)scale_t;

    return 0;
}

/* --------------------------- Log to file ------------------------------- */
static int log_data(float pressure, float temperature)
{
    if (fwrite(&pressure, sizeof(float), 1, g_data_file) != 1) {
        fprintf(stderr, "Error: fwrite pressure failed: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, g_data_file) != 1) {
        fprintf(stderr, "Error: fwrite temperature failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_data_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_data_file) {
        fclose(g_data_file);
        g_data_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_pigpio_inited) {
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (start_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    gpioDelay(CONVERSION_MS * 1000);

    g_data_file = fopen(DATA_FILE, "wb");
    if (!g_data_file) {
        fprintf(stderr, "Error: cannot open %s: %s\n", DATA_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sensor_data(&pressure, &temperature) == 0) {
            consecutive_errors = 0;
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Warning: log_data failed, continuing.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: sensor read failed (%d consecutive).\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Error: max retries reached, aborting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

