/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x25 (7-bit)
 * Continuous measurement command: 0x36 0x2F (MSB first, no stop)
 * Conversion time: 45 ms
 * Response: 9 bytes (3 words * 3 bytes + 1 CRC byte)
 *   Word 0: differential pressure (msw, lsw, crc)
 *   Word 1: temperature       (msw, lsw, crc)
 *   Word 2: scale factor      (msw, lsw, crc)
 * CRC-8 polynomial: 0x31, init: 0xFF
 *
 * Build: gcc -O2 -Wall -o sdp800_logger sdp800_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <i2c.h>

#define I2C_BUS          1
#define SDP800_ADDR      0x25
#define LOG_FILE         "pressure_log.txt"
#define SAMPLE_PERIOD_S  5
#define CONV_TIME_MS     45

/* Continuous measurement command (MSB first, no stop) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP800                   */
/* ------------------------------------------------------------------ */
static int read_sdp800(int fd, float *pressure_pa)
{
    uint8_t buf[9];

    /* Send continuous-measurement command (no register addressing) */
    if (i2c_write(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != (ssize_t)sizeof(CMD_CONT_MEAS)) {
        fprintf(stderr, "[ERROR] I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    usleep(CONV_TIME_MS * 1000);

    /* Read 9 bytes: pressure(3) + temperature(3) + scale(3) */
    ssize_t n = i2c_read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C read failed (got %zd bytes, expected %zu): %s\n",
                n, sizeof(buf), n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    /* Assemble 16-bit big-endian signed value for differential pressure */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure_pa = (float)raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading with a human-readable timestamp                       */
/* ------------------------------------------------------------------ */
static void log_pressure(FILE *fp, float pressure_pa)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s, %.2f Pa\n", ts, pressure_pa) < 0)
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
    else
        fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2c_close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    i2c_terminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize libi2c */
    if (i2c_init() < 0) {
        fprintf(stderr, "[FATAL] libi2c initialization failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SDP800 address */
    g_i2c_fd = i2c_open(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[FATAL] i2c_open(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SDP800_ADDR, strerror(errno));
        i2c_terminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        i2c_close(g_i2c_fd);
        i2c_terminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    printf("SDP800 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_S);

    /* Main sampling loop */
    while (g_running) {
        float pressure_pa;

        if (read_sdp800(g_i2c_fd, &pressure_pa) == 0) {
            log_pressure(g_log_fp, pressure_pa);
            printf("Pressure: %.2f Pa\n", pressure_pa);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

