        if (read_pressure(i2c_handle, &pressure) == 0) {
            float flow_rate = calculate_flow_rate(pressure);
            control_fan(flow_rate);
            log_data(pressure);
        } else {
            fprintf(stderr, "Error reading pressure, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
