#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LPS33HW constants (from datasheet) ---- */
#define LPS33HW_ADDR        0x5C          /* SA1 tied to GND */
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0xBD
#define CTRL_REG1           0x20
#define CTRL_REG2           0x21
#define PRESS_OUT_XL        0x28
#define TEMP_OUT_L          0x2B

#define SAMPLE_PERIOD_US    1000000       /* 1 second */
#define LOG_FILE_NAME       "environmental_data.txt"

/* ---- Globals for signal-safe cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped message to stderr and the log file.            */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(ts, sizeof ts, "UNKNOWN");
    }

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "[%s] ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an I2C register.                           */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an I2C register.                            */
/* Returns 0 on success; -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int write_reg8(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers.   */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int read_reg16_le(int handle, uint8_t reg_low, int16_t *out)
{
    uint8_t lo, hi;
    if (read_reg8(handle, reg_low, &lo) < 0)   return -1;
    if (read_reg8(handle, reg_low + 1, &hi) < 0) return -1;
    *out = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the LPS33HW: BDU=1, IF_ADD_INC=1, ODR=1 Hz.              */
/* ------------------------------------------------------------------ */
static int init_lps33hw(int handle)
{
    uint8_t who;
    if (read_reg8(handle, WHO_AM_I, &who) < 0) {
        log_error("Failed to read WHO_AM_I register.");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: BDU=1, IF_ADD_INC=1, ODR=1 Hz (0x11) */
    if (write_reg8(handle, CTRL_REG1, 0x11) < 0) {
        log_error("Failed to write CTRL_REG1.");
        return -1;
    }

    /* CTRL_REG2: reset BDU bit so data is updated continuously. */
    if (write_reg8(handle, CTRL_REG2, 0x00) < 0) {
        log_error("Failed to write CTRL_REG2.");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure (hPa) and temperature (°C).                          */
/* Returns 0 on success; -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *pressure, float *temperature)
{
    int16_t raw_p, raw_t;

    if (read_reg16_le(handle, PRESS_OUT_XL, &raw_p) < 0) {
        log_error("Failed to read pressure registers.");
        return -1;
    }
    if (read_reg16_le(handle, TEMP_OUT_L, &raw_t) < 0) {
        log_error("Failed to read temperature registers.");
        return -1;
    }

    /* LPS33HW datasheet conversion formulas. */
    *pressure    = (float)raw_p / 4096.0f;   /* hPa */
    *temperature = (float)raw_t / 100.0f;    /* °C  */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to the file and stdout.                              */
/* ------------------------------------------------------------------ */
static void log_data(float pressure, float temperature)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        log_error("localtime_r failed; skipping log entry.");
        return;
    }
    strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);

    printf("[%s] Pressure: %.2f hPa, Temperature: %.2f °C\n",
           ts, pressure, temperature);

    if (g_log_file) {
        fprintf(g_log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
                ts, pressure, temperature);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the LPS33HW address ---- */
    g_i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE_NAME ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (init_lps33hw(g_i2c_handle) < 0) {
        fprintf(stderr, "LPS33HW initialisation failed.\n");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LPS33HW logger started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (!g_terminate) {
        float pressure, temperature;

        if (read_sensor(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_error("Sensor read failed; will retry next cycle.");
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 1 s */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

