/*
 * Raspberry Pi Zero W – STLM75 temperature monitor with LED alert.
 *
 * Hardware:
 *   - STLM75 on I2C bus 1, address 0x48 (ADDR pin tied to GND).
 *     SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5).
 *   - LED on GPIO17 (BCM) with 330 Ω series resistor to GND.
 *
 * Build:  gcc -O2 -Wall -Wextra -o stlm75_monitor stlm75_monitor.c -lpigpio -lrt
 * Run:    sudo ./stlm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48          /* STLM75 default when ADDR pin tied to GND */
#define GPIO_LED       17            /* BCM pin for the LED */
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f         /* °C – turn LED on when average exceeds this */
#define SAMPLE_PERIOD  1             /* seconds between readings */

/* STLM75 register addresses */
#define REG_TEMP       0x00          /* temperature register (read-only) */
#define REG_CONFIG     0x01          /* configuration register (write-only) */

/* Configuration: continuous conversion, 12-bit resolution, no alert */
#define CONFIG_VALUE   0x00

typedef struct {
    float buffer[BUFFER_SIZE];
    int   count;                     /* number of valid samples currently in buffer */
    int   head;                      /* next write slot */
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_pigpio_inited = false;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
static void cb_init(CircularBuffer *cb)
{
    cb->count = 0;
    cb->head  = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* STLM75 helpers                                                      */
/* ------------------------------------------------------------------ */
static int stlm75_init(int handle)
{
    /*
     * Write the configuration register.  pigpio's i2cWriteByteData()
     * sends (reg, value) over the bus, so we pass the register address
     * as the first argument and the value as the second.
     */
    if (i2cWriteByteData(handle, REG_CONFIG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error: failed to write STLM75 config register.\n");
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit temperature register.
 * Returns 0 on success and stores the temperature in *out_celsius.
 * Returns -1 on I2C failure.
 */
static int stlm75_read_temperature(int handle, float *out_celsius)
{
    /*
     * pigpio's i2cReadWordData() returns the 16-bit word in host-byte-order
     * (big-endian on the Pi).  The STLM75 sends MSB first, so we must
     * swap bytes to get the correct value.
     */
    int raw = i2cReadWordData(handle, REG_TEMP);
    if (raw < 0) {
        fprintf(stderr, "Error: I2C read failed (pigpio code %d).\n", raw);
        return -1;
    }

    /* pigpio returns the word as (msb << 8) | lsb */
    uint16_t swapped = (uint16_t)(((raw & 0xFF00) >> 8) | ((raw & 0x00FF) << 8));

    /*
     * 12-bit resolution, two's-complement.  The upper 4 bits are the
     * integer part and the lower 4 bits are the fractional part (x0.0625).
     */
    int16_t signed_val = (int16_t)swapped;
    *out_celsius = (float)signed_val * 0.0625f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_inited) {
        /* Ensure LED is off before releasing resources */
        gpioWrite(GPIO_LED, 0);

        if (g_i2c_handle >= 0) {
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
        }
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio code %d).\n", g_i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- STLM75 init ---- */
    if (stlm75_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: STLM75 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);   /* start with LED off */

    /* ---- Signals ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Data structures ---- */
    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    printf("STLM75 monitoring started.  Threshold = %.1f °C.  Press Ctrl+C to exit.\n",
           (double)TEMP_THRESHOLD);

    /* ---- Main loop ---- */
    while (g_running) {
        float temperature;

        if (stlm75_read_temperature(g_i2c_handle, &temperature) == 0) {
            cb_add(&temp_buffer, temperature);
            float avg = cb_average(&temp_buffer);

            printf("Temperature: %.2f °C | Average: %.2f °C | LED: %s\n",
                   (double)temperature, (double)avg,
                   (avg > TEMP_THRESHOLD) ? "ON" : "OFF");

            if (avg > TEMP_THRESHOLD)
                gpioWrite(GPIO_LED, 1);
            else
                gpioWrite(GPIO_LED, 0);
        } else {
            /* I2C failure – ensure LED is off and skip this sample */
            gpioWrite(GPIO_LED, 0);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);  /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

