/*
 * SCD30 air-quality monitor with ventilation control.
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), SCD30 address 0x60
 * Output: air_quality.log  (CSV: timestamp_utc,co2_ppm,temp_c,hum_rh)
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd30_monitor scd30_monitor.c -li2c
 *
 * NOTE:  The libi2c library is the Linux userland I2C character-device API
 *        (i.e. /dev/i2c-1).  It is NOT the pigpio I2C API.  If you have
 *        pigpio installed, you can use it instead of libi2c; the logic
 *        below is written in a portable style that uses only standard
 *        C and Linux system calls.
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SCD30_I2C_ADDR        0x60
#define I2C_BUS               "/dev/i2c-1"
#define LOG_FILE              "air_quality.log"
#define SAMPLE_INTERVAL_SEC   5

/* SCD30 command set (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC    0x0010
#define CMD_STOP_PERIODIC     0x0104
#define CMD_GET_DATA_READY    0x0202
#define CMD_READ_MEASUREMENT  0x0300
#define CMD_SOFT_RESET        0x0006

#define CO2_LOW_THRESHOLD     800
#define CO2_HIGH_THRESHOLD    1200

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t scd30_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[3];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    buf[2] = scd30_crc8(buf, 2);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_cmd(0x%04X): write failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_bytes: read %zd of %zu bytes: %s\n",
                n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SCD30 driver                                                        */
/* ------------------------------------------------------------------ */
static int scd30_soft_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_SOFT_RESET) == -1)
        return -1;
    usleep(20000);  /* 20 ms reset settling time */
    return 0;
}

static int scd30_start_periodic(int fd)
{
    return i2c_write_cmd(fd, CMD_START_PERIODIC);
}

static int scd30_stop_periodic(int fd)
{
    return i2c_write_cmd(fd, CMD_STOP_PERIODIC);
}

static int scd30_data_ready(int fd, int *ready)
{
    if (i2c_write_cmd(fd, CMD_GET_DATA_READY) == -1)
        return -1;
    usleep(2000);  /* command processing delay */

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) == -1)
        return -1;

    if (scd30_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready response\n");
        return -1;
    }

    uint16_t val = ((uint16_t)buf[0] << 8) | buf[1];
    *ready = (val == 1);
    return 0;
}

static int scd30_read_measurement(int fd, float *co2, float *temp, float *hum)
{
    if (i2c_write_cmd(fd, CMD_READ_MEASUREMENT) == -1)
        return -1;
    usleep(2000);  /* command processing delay */

    uint8_t buf[18];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) == -1)
        return -1;

    /* Validate CRC for each 3-byte group */
    for (int i = 0; i < 6; i++) {
        if (scd30_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on measurement data group %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw   = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw  = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t hum_raw   = ((uint16_t)buf[6] << 8) | buf[7];

    *co2   = (float)co2_raw;
    *temp  = (float)temp_raw / 100.0f;
    *hum   = (float)hum_raw  / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(float co2, float temp, float hum)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, hum) < 0)
        perror("fprintf to log");
    else
        fflush(g_log_fp);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];
    if (gmtime_r(&now, &tm_utc) != NULL)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static const char *ventilation_state(float co2)
{
    if (co2 < CO2_LOW_THRESHOLD)   return "OFF";
    if (co2 < CO2_HIGH_THRESHOLD)  return "LOW";
    return "HIGH";
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd != -1) {
        /* Best-effort stop; ignore errors during shutdown */
        (void)scd30_stop_periodic(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Open I2C bus and set slave address */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        /* In a mocked/emulated environment this is expected; log and exit. */
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        fprintf(stderr, "No I2C bus available; logging sensor-absent event.\n");
        log_error("I2C bus unavailable (sensor absent or bus unavailable)");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_SUCCESS;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SCD30_I2C_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SCD30_I2C_ADDR, strerror(errno));
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_SUCCESS;
    }

    /* Soft reset and start periodic measurement */
    if (scd30_soft_reset(g_i2c_fd) == -1) {
        log_error("SCD30 soft-reset failed (sensor absent or unresponsive)");
        cleanup();
        return EXIT_SUCCESS;
    }

    if (scd30_start_periodic(g_i2c_fd) == -1) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return EXIT_SUCCESS;
    }

    printf("SCD30 monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int ready = 0;
        if (scd30_data_ready(g_i2c_fd, &ready) == -1) {
            log_error("Failed to check data-ready status");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (!ready) {
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float co2, temp, hum;
        if (scd30_read_measurement(g_i2c_fd, &co2, &temp, &hum) == -1) {
            log_error("Failed to read measurement data");
        } else {
            log_sample(co2, temp, hum);
            printf("CO2: %.0f ppm  |  Temp: %.2f C  |  Hum: %.2f %%RH  |  Vent: %s\n",
                   co2, temp, hum, ventilation_state(co2));
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

