/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+
 *
 * Reads exactly 9 bytes (pressure + temperature + scale-factor CRCs) over I2C
 * at the configured interval and verifies CRC-8 for each word.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c -lpigpio -lrt
 * Run:    ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_I2C_ADDR        0x25
#define SDP32_READ_CMD        0x362F   /* continuous read, mass flow / differential pressure */
#define SDP32_READ_LEN        9        /* 3 words × 3 bytes */
#define SDP32_CRC8_POLY       0x31
#define SDP32_CRC8_INIT       0xFF

#define DEFAULT_INTERVAL_MS   1000
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SDP32_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SDP32_CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(buf, len, "----");
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp32(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)(SDP32_READ_CMD >> 8),
        (uint8_t)(SDP32_READ_CMD & 0xFF)
    };
    uint8_t data[SDP32_READ_LEN];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (sensor absent or bus error)\n");
        return -1;
    }

    /* SDP32 needs ~45 ms for the first conversion */
    gpioDelay(45000);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale-factor(2)+crc */
    if (i2cReadDevice(handle, (char *)data, SDP32_READ_LEN) != SDP32_READ_LEN) {
        fprintf(stderr, "[ERROR] I2C read failed (sensor absent or bus error)\n");
        return -1;
    }

    /* CRC checks for each 2-byte word */
    if (sdp_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (sdp_crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / 200.0f;   /* SDP32 temp in °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
