/*
 * Raspberry Pi 4 Model B – Sensirion SDP810-125Pa differential pressure sensor
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   SDP810 SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C address: 0x21 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -lpigpio -lrt
 * Run:    sudo ./sdp810
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21
#define READ_LEN       9
#define CONV_DELAY_US  45000   /* 45 ms – exceeds SDP810 conversion time */
#define SAMPLE_PERIOD  1000000 /* 1 s */

/* SDP810 CRC-8: polynomial 0x31, init 0xFF, no reflection */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte frame from the SDP810                               */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[READ_LEN];

    /*
     * Trigger a continuous measurement read by writing a single
     * command byte 0x36 (no register address, just the command).
     * The sensor responds with the 9-byte data frame.
     */
    if (i2cWriteByte(handle, 0x36) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte failed (sensor absent or bus error)\n");
        return -1;
    }

    gpioDelay(CONV_DELAY_US);   /* wait for conversion to complete */

    int bytes_read = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (bytes_read != READ_LEN) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %d)\n",
                bytes_read, READ_LEN);
        return -1;
    }

    /* Validate CRC on each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    /*
     * Raw big-endian 16-bit signed values, scale factors in the
     * 16-bit big-endian words (words 1 and 2 contain pressure and
     * temperature scale factors respectively).
     */
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_pressure  = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t scale_temperature = (int16_t)((buf[9] << 8) | buf[10]);

    if (scale_pressure == 0 || scale_temperature == 0) {
        fprintf(stderr, "[ERROR] Invalid scale factor (zero)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_pressure;
    *temperature = (float)raw_temperature / (float)scale_temperature;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-125Pa reader started (bus %d, addr 0x%02X). Ctrl+C to exit.\n",
           I2C_BUS, I2C_ADDR);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle\n");
        }

        /* Sleep 1 s in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- cleanup ---------------------------------------------------- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

