code:
/*
 * HDC1000 temperature & humidity sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   HDC1000 SDA -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   HDC1000 SCL -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   HDC1000 VDD -> 3.3 V
 *   HDC1000 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc1000_reader hdc1000_reader.c
 * Run:    ./hdc1000_reader
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

/* ---- HDC1000 constants ------------------------------------------------- */
#define HDC1000_ADDR          0x40          /* default 7-bit I2C address     */
#define I2C_BUS               "/dev/i2c-1"  /* Pi 4 default user-land bus    */

#define REG_TEMP_LOW          0x00          /* T_low  (LSB first, then MSB)  */
#define REG_HUM_LOW           0x01          /* H_low  (LSB first, then MSB)  */
#define REG_CONFIG            0x02          /* configuration register        */
#define REG_MANUFACTURER_ID   0xFE          /* 0x54 for TI                   */
#define REG_DEVICE_ID         0xFF          /* 0x01 for HDC1000              */

#define CONFIG_RESET          0x80          /* bit 7: soft reset            */
#define CONFIG_T_TRIGGER      0x01          /* bit 0: T trigger             */
#define CONFIG_H_TRIGGER      0x02          /* bit 1: H trigger             */

#define CONV_DELAY_MS         20            /* conservative worst-case     */
#define POLL_INTERVAL_S       5

/* ---- Globals for signal handler --------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers --------------------------------------------- */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on error.
 */
static int reg_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "reg_write_byte(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a register.
 * Returns the byte value (0–255) on success, -1 on error.
 */
static int reg_read_byte(int fd, uint8_t reg)
{
    /* Select register */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "reg_read_byte: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "reg_read_byte: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return (int)val;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success, -1 on error.
 */
static int reg_read_word_le(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "reg_read_word_le: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "reg_read_word_le: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ---- HDC1000 operations ------------------------------------------------ */

/*
 * Soft-reset the sensor.
 * Returns 0 on success, -1 on error.
 */
static int hdc1000_reset(int fd)
{
    if (reg_write_byte(fd, REG_CONFIG, CONFIG_RESET) != 0)
        return -1;
