 * Read a single byte from a register.
 * Returns the byte value (0–255) on success, -1 on error.
 */
static int reg_read_byte(int fd, uint8_t reg)
{
    /* Select register */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "reg_read_byte: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
