/*
 * Si7051 Temperature Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7051 SDA -> GPIO2 (BCM)
 *   Si7051 SCL -> GPIO3 (BCM)
 *   Si7051 VDD -> 3.3V
 *   Si7051 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o si7051_reader si7051_reader.c -lpigpio -lrt
 * Run:   sudo ./si7051_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7051_ADDR    0x40
#define READ_INTERVAL  5          /* seconds between readings */
#define MAX_RETRIES    3

/* Si7051 commands */
#define CMD_MEASURE_TEMP 0xE3
#define CMD_RESET        0xFE

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/*
 * Send the reset command and wait for the device to complete the
 * internal reset before proceeding.
 */
static int reset_sensor(int handle)
{
    if (i2c_write_cmd(handle, CMD_RESET) < 0)
        return -1;

    /* Si7051 reset takes up to 15 ms; give a small margin */
    gpioDelay(20000);  /* microseconds */
    return 0;
}

/*
 * Read a 16-bit big-endian temperature result from the Si7051.
 * Returns 0 on success and stores the temperature in *out_celsius.
 * Returns -1 on any I2C or conversion error.
 */
static int read_temperature(int handle, float *out_celsius)
{
    uint8_t buf[2];
    int rc;

    /* Trigger a single-shot temperature measurement */
    if (i2c_write_cmd(handle, CMD_MEASURE_TEMP) < 0)
        return -1;

    /*
     * Conversion time: ~7 ms for the default 12-bit resolution.
     * Wait a bit before reading.
     */
    gpioDelay(10000);

    /* Read 2 bytes of data */
    rc = i2cReadDevice(handle, (char *)buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 2)\n", rc);
        return -1;
    }

    /* Assemble big-endian 16-bit value */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];

    /*
     * Si7051 temperature conversion:
     *   T(°C) = (175.72 * raw) / 65536 - 46.85
     * This is the default 12-bit resolution; the 14-bit and 16-bit
     * resolutions require a different formula.
     */
    *out_celsius = ((17572.0f * (float)raw) / 65536.0f) - 46.85f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7051_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Reset the sensor --- */
    if (reset_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si7051 reset failed — sensor may be absent or mis-wired\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7051 temperature reader started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (!g_terminate) {
        float temperature = 0.0f;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !g_terminate; ++attempt) {
            if (read_temperature(g_i2c_handle, &temperature) == 0) {
                success = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(1000000);  /* 1 s backoff before retry */
        }

        if (success) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "[WARN] Temperature read failed after %d attempts — continuing\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL * 10 && !g_terminate; ++i)
            gpioDelay(100000);
    }

    /* --- Cleanup --- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

