 *   gcc -O2 -Wall -Wextra -o mlx90833_reader mlx90833_reader.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./mlx90833_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1          /* /dev/i2c-1 on Raspberry Pi 4 */
#define MLX90833_I2C_ADDR    0x30       /* Default 7-bit I2C address */

/*
 * MLX90833 register map (representative subset).
 * The exact register map depends on the specific MLX90833 variant;
 * adjust the constants below to match the datasheet revision.
 */
#define REG_PRODUCT_ID       0x00
#define REG_DEVICE_ID        0x01
#define REG_PRESSURE_MSB     0x02
#define REG_PRESSURE_LSB     0x03
#define REG_TEMP_MSB         0x04
#define REG_TEMP_LSB         0x05
#define REG_CONFIG           0x06
#define REG_CTRL             0x07

#define CTRL_MEASURE_CMD     0x01       /* Start a single measurement */

/*
 * Expected device ID for the MLX90833.
 * This is a placeholder; verify against your specific variant's datasheet.
 */
#define EXPECTED_DEVICE_ID   0x8333

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US   500000

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal Handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }
}

/* --------------------------- I2C Helpers --------------------------------- */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a register.
 * Returns the byte value (0–255) on success, -1 on failure.
 */
static int i2c_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

/*
 * Read a 16-bit big-endian value from two consecutive registers.
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int i2c_read_reg16_be(int handle, uint8_t reg_msb, uint8_t reg_lsb, uint16_t *out)
{
    int msb = i2c_read_reg(handle, reg_msb);
    if (msb < 0) {
        return -1;
    }
    int lsb = i2c_read_reg(handle, reg_lsb);
    if (lsb < 0) {
        return -1;
    }
    *out = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

/* --------------------------- Sensor Logic -------------------------------- */

/*
 * Initialise the MLX90833: verify device identity and configure the sensor.
 * Returns 0 on success, -1 on failure.
 */
static int sensor_init(int handle)
{
    int device_id = i2c_read_reg16_be(handle, REG_DEVICE_ID, REG_DEVICE_ID + 1, NULL);
    if (device_id < 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID – sensor may be absent or bus error.\n");
        return -1;
    }

    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected DEVICE_ID: 0x%04X (expected 0x%04X).\n",
                device_id, EXPECTED_DEVICE_ID);
        return -1;
    }

    printf("[INFO] MLX90833 detected (DEVICE_ID = 0x%04X).\n", device_id);

    /*
     * Example configuration: enable pressure and temperature channels,
     * set a reasonable oversampling rate, and set the output data rate
     * to 1 Hz (or the highest rate your application tolerates).
     *
     * Adjust the config register value below to match your variant's
     * datasheet and your specific application requirements.
     */
    if (i2c_write_reg(handle, REG_CONFIG, 0x00) != 0) {
        return -1;
    }

    /*
     * Example control register: start a single measurement.
     * Some variants may use a different command sequence;
     * adjust CTRL_MEASURE_CMD to match your variant.
     */
    if (i2c_write_reg(handle, REG_CTRL, CTRL_MEASURE_CMD) != 0) {
        return -1;
    }

    return 0;
}

/*
 * Trigger a measurement and read the pressure value.
 * Returns 0 on success and stores the pressure in Pa in *pressure_pa,
 * -1 on failure.
 */
static int sensor_read_pressure(int handle, uint32_t *pressure_pa)
{
    /*
     * Trigger a new measurement.
     * Some variants may use a different command;
     * adjust CTRL_MEASURE_CMD to match your variant.
     */
    if (i2c_write_reg(handle, REG_CTRL, CTRL_MEASURE_CMD) != 0) {
        return -1;
    }

    /*
     * Wait for the measurement to complete.
     * The exact conversion time depends on the oversampling rate
     * configured in REG_CONFIG; 10 ms is a safe upper bound.
     */
    gpioDelay(10000);

    uint16_t raw_pressure;
    if (i2c_read_reg16_be(handle, REG_PRESSURE_MSB, REG_PRESSURE_LSB, &raw_pressure) != 0) {
        return -1;
    }

    /*
     * Convert raw pressure to Pascals.
     * The exact formula depends on the variant;
     * adjust the conversion below to match your variant's datasheet.
     */
    *pressure_pa = (uint32_t)raw_pressure * 1000U;
    return 0;
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    int rc = EXIT_SUCCESS;

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90833_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MLX90833_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    install_signal_handlers();

    /* --- Initialise sensor --- */
    if (sensor_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialisation failed.\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("[INFO] Starting pressure readings every 500 ms. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint32_t pressure_pa = 0;

        if (sensor_read_pressure(g_i2c_handle, &pressure_pa) != 0) {
            fprintf(stderr, "[WARN] Pressure read failed – continuing.\n");
        } else {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("[%s] Pressure: %u Pa\n", ts, pressure_pa);
            fflush(stdout);
        }

        /*
         * Sleep in small increments so signals are caught promptly.
         */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\n[INFO] Shutting down cleanly.\n");

cleanup:
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return rc;
}

