/*
 * Raspberry Pi Zero W – TDK ICP-10101 barometric pressure sensor reader
 *
 * Wiring:
 *   ICP-10101 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10101 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10101 VDD  -> 3.3 V
 *   ICP-10101 GND  -> GND
 *
 * I2C address: 0x60 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10101 icp10101.c -lpigpio -lrt
 * Run:    sudo ./icp10101
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- ICP-10101 constants (from datasheet) ------------------------------- */
#define ICP10101_ADDR        0x60          /* 7-bit I2C address            */
#define ICP10101_BUS         1             /* /dev/i2c-1 on Pi Zero W      */

#define CMD_MEASURE          0x00          /* single-shot measurement       */
#define CMD_READ_TEMP        0x01          /* read temperature register     */
#define CMD_READ_PRESSURE    0x02          /* read pressure register        */

#define MEASURE_DELAY_US     7000          /* 7 ms conversion time         */
#define READ_DELAY_US        1000          /* 1 ms between reads            */
#define LOOP_DELAY_S         5             /* 5 s between samples           */

/* Default register value when sensor is absent or not responding */
#define DEFAULT_REG_VALUE    0xFFFF

/* ---- Globals for signal-safe cleanup ------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ----------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read a 16-bit big-endian register ---------------------------------- */
static int read_register(int handle, uint8_t cmd, uint16_t *out)
{
    char buf[2];

    /* Send the read command */
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed\n", cmd);
        return -1;
    }

    /* Small delay so the sensor has time to latch the register */
    gpioDelay(READ_DELAY_US);

    /* Read two bytes back */
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(0x%02X) returned %d\n", cmd, n);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ---- Trigger a measurement and read temperature + pressure --------------- */
static int read_sensor(int handle, float *temperature, float *pressure)
{
    uint16_t raw_t = 0, raw_p = 0;

    /* Trigger a single-shot measurement */
    if (i2cWriteByte(handle, CMD_MEASURE) < 0) {
        fprintf(stderr, "[ERROR] Failed to trigger measurement\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read temperature register */
    if (read_register(handle, CMD_READ_TEMP, &raw_t) < 0)
        return -1;

    /* Read pressure register */
    if (read_register(handle, CMD_READ_PRESSURE, &raw_p) < 0)
        return -1;

    /* Sensor-absent heuristic: all bytes match the default */
    if (raw_t == DEFAULT_REG_VALUE && raw_p == DEFAULT_REG_VALUE) {
        fprintf(stderr,
                "[ERROR] Sensor absent or not responding (0x%04X / 0x%04X)\n",
                raw_t, raw_p);
        return -1;
    }

    /* Convert raw values to physical units (datasheet formulas) */
    *temperature = (float)raw_t / 100.0f;
    *pressure    = (float)raw_p / 100.0f;

    return 0;
}

/* ---- Print a timestamped reading ---------------------------------------- */
static void print_reading(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    }

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           ts, temperature, pressure);
    fflush(stdout);
}

/* ---- Cleanup helper ----------------------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x60 */
    g_i2c_handle = i2cOpen(ICP10101_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                ICP10101_BUS, ICP10101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("ICP-10101 reader started (bus %d, addr 0x%02X). Press Ctrl+C to stop.\n",
           ICP10101_BUS, ICP10101_ADDR);
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        float temperature = 0.0f, pressure = 0.0f;

        if (read_sensor(g_i2c_handle, &temperature, &pressure) == 0) {
            print_reading(temperature, pressure);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOOP_DELAY_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

