    uint32_t raw = ((uint32_t)buf[0] << 16) |
                   ((uint32_t)buf[1] << 8)  |
                   ((uint32_t)buf[2]);

    /* Convert to Pascals (example scaling; adjust per datasheet) */
    *pressure_out = (float)raw / 100.0f;
