    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX90819 Pressure Sensor Reader\n");
    printf("Bus: %s, Address: 0x%02X\n", I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float pressure;

        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                snprintf(ts, sizeof(ts), "unknown-time");
            }

            printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read pressure. Continuing...\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return rc;
}

