/*
 * SDP800-500Pa Differential Pressure Sensor Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C-1 (SDA=GPIO2, SCL=GPIO3)
 * Sensor: Sensirion SDP800-500Pa (I2C address 0x21)
 *
 * Build:  gcc -O2 -Wall -o pressure_monitor pressure_monitor.c -lm
 * Run:    ./pressure_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SDP800_ADDR      0x21
#define LOG_FILE         "pressure_log.txt"
#define SAMPLE_PERIOD_US 500000          /* 500 ms between samples */
#define MEAS_DELAY_US    45000           /* 45 ms measurement wait */
#define READ_LEN         9               /* 3 words × (2 data + 1 CRC) */

/* SDP800 measurement command (MSB = 0x36, LSB = 0x2F) */
static const uint8_t CMD_MEASURE[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, float *pressure, float *temperature)
{
    uint8_t buf[READ_LEN];

    /* Trigger a single-shot measurement */
    if (i2cWriteDevice(handle, (char *)CMD_MEASURE, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (measurement command) failed\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    int bytes_read = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (bytes_read != READ_LEN) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %d)\n",
                bytes_read, READ_LEN);
        return -1;
    }

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /* Conversion formulas per SDP8xx datasheet */
    *pressure    = (float)raw_pressure    / 200.0f;   /* Pa */
    *temperature = (float)raw_temperature / 200.0f;   /* °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to SDP800 */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP800_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa monitoring started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sdp800(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(SAMPLE_PERIOD_US / 10);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

