/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c -lpigpio -lrt
 * Run:    sudo ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25          /* SDP800-500Pa default I2C address */
#define LOG_FILE       "airflow_log.csv"
#define SAMPLE_PERIOD  0.5           /* seconds between samples */
#define MEAS_DELAY     0.008         /* 8 ms conversion time */
#define MAX_RETRIES    3

/* SDP800 measurement command (differential pressure, mass flow) */
static const uint8_t CMD_MEASURE[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one differential-pressure sample from the SDP800.             */
/* Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, float *pressure_pa)
{
    uint8_t buf[3];
    int rc;

    /* Trigger a single-shot measurement */
    rc = i2cWriteDevice(handle, (char *)CMD_MEASURE, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (8 ms max) */
    time_sleep(MEAS_DELAY);

    /* Read 3 bytes: MSB, LSB, CRC */
    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d: %s\n",
                rc, rc < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    /* Convert raw 16-bit signed value to Pa (per datasheet) */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure_pa = (float)raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV log.                        */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure)
{
    int need_header = (access(filename, F_OK) != 0);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "Timestamp,Pressure (Pa)\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, pressure);

    if (fclose(fp) != 0) {
        fprintf(stderr, "[ERROR] fclose(%s): %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP800-500Pa logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    int consecutive_errors = 0;

    while (!g_terminate) {
        float pressure = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !g_terminate; attempt++) {
            int rc = read_sdp800(g_i2c_handle, &pressure);
            if (rc == 0) {
                ok = 1;
                break;
            }
            if (rc == -2) {
                /* CRC error — log and continue */
                fprintf(stderr, "[WARN] CRC error, attempt %d/%d\n",
                        attempt + 1, MAX_RETRIES);
            } else {
                /* I2C bus error — back off and retry */
                fprintf(stderr, "[WARN] I2C error, attempt %d/%d: %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            }
            time_sleep(0.05);
        }

        if (ok) {
            consecutive_errors = 0;
            if (log_data(LOG_FILE, pressure) != 0)
                fprintf(stderr, "[WARN] logging failed\n");
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            consecutive_errors++;
            fprintf(stderr, "[ERROR] Sensor read failed after %d attempts (total errors %d)\n",
                    MAX_RETRIES, consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "[ERROR] Too many consecutive failures — sensor may be absent or bus stuck.\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

