code:
/*
 * MLX90821 Pressure Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90821 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90821 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90821 VDD  -> 3.3 V
 *   MLX90821 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c -lm
 *
 * Run:
 *   ./pressure_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1          /* /dev/i2c-1 on Raspberry Pi 4 */
#define MLX90821_ADDR        0x30       /* 7-bit I2C address */
#define CSV_FILENAME         "pressure_log.csv"
#define SAMPLE_INTERVAL_SEC  1
#define MAX_RETRIES          3
#define I2C_REOPEN_DELAY_SEC 5

/*
 * MLX90821 pressure register (16-bit, big-endian).
 * The sensor returns two consecutive bytes: [MSB, LSB].
 * The 16-bit value is left-justified in the 16-bit register,
 * so the full 16 bits are available for pressure scaling.
 */
#define MLX90821_REG_PRESSURE 0x00

/*
 * Conversion factor: raw 16-bit value -> kPa.
 * Adjust this constant to match the sensor's calibration curve
 * (e.g., 0x0000 -> 200 kPa, 0xFFFF -> 250 kPa).
 */
#define RAW_TO_KPA 0.01f

/* Safe tire pressure range (kPa) */
#define MIN_SAFE_PRESSURE 200.0f
#define MAX_SAFE_PRESSURE 250.0f

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_csv_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */

static void signal_handler(int sig);
static int  open_i2c_bus(void);
static int  read_pressure(float *pressure_out);
static int  log_data(float pressure);
static void cleanup(void);

/* ------------------------------- Handlers -------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_csv_file != NULL) {
        fflush(g_csv_file);
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------ I2C helpers ------------------------------ */

static int open_i2c_bus(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, MLX90821_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit pressure register from the MLX90821.
 * Returns 0 on success and stores the pressure in kPa;
 * returns -1 on I2C failure.
 */
static int read_pressure(float *pressure_out)
{
    char buf[2];
    int  bytes_read;

    bytes_read = i2cReadI2CBlockData(g_i2c_handle,
                                    MLX90821_REG_PRESSURE,
                                    buf,
                                    2);
    if (bytes_read != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d: %s\n",
                bytes_read, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) |
                   ((uint16_t)(uint8_t)buf[1]);

    *pressure_out = (float)raw * RAW_TO_KPA;
    return 0;
}

/* ------------------------------ CSV logging ------------------------------ */

static int log_data(float pressure)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_csv_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "[ERROR] fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_csv_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file (append mode) */
    g_csv_file = fopen(CSV_FILENAME, "a");
    if (g_csv_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n",
                CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_csv_file) == 0) {
        fprintf(g_csv_file, "timestamp,pressure_kPa\n");
        fflush(g_csv_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90821 Pressure Logger started. Logging to %s every %d s.\n",
           CSV_FILENAME, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure = 0.0f;
        int   attempt;
        int   read_ok = 0;

        for (attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_pressure(&pressure) == 0) {
                read_ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "[WARN] Retrying I2C open/read (%d/%d)...\n",
                        attempt + 1, MAX_RETRIES);
                if (open_i2c_bus() != 0) {
                    sleep(I2C_REOPEN_DELAY_SEC);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "[ERROR] Pressure read failed after %d attempts; "
                            "exiting.\n", MAX_RETRIES);
            break;
        }

        if (log_data(pressure) != 0) {
            fprintf(stderr, "[ERROR] Logging failed; continuing.\n");
        }

        /* Safety check */
        if (pressure < MIN_SAFE_PRESSURE || pressure > MAX_SAFE_PRESSURE) {
            fprintf(stderr,
                    "[WARN] Pressure %.2f kPa outside safe range "
                    "(%.0f-%.0f kPa)!\n",
                    pressure, MIN_SAFE_PRESSURE, MAX_SAFE_PRESSURE);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

