/*
 * Raspberry Pi Zero W – Honeywell HIH6130 I2C Temperature & Humidity Logger
 *
 * Wiring:
 *   HIH6130 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   HIH6130 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   HIH6130 VDD  -> 3.3 V
 *   HIH6130 GND  -> GND
 *
 * The HIH6130 has an internal pull-up on its SDA line; the Pi's bus
 * controller drives the line and the sensor's pull-up together.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hih6130_logger hih6130_logger.c -lpigpio -lrt
 * Run:    sudo ./hih6130_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS            1
#define HIH6130_ADDR       0x27          /* default 7-bit I2C address */
#define LOG_FILE           "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT (1024 * 1024) /* 1 MiB */
#define SAMPLE_INTERVAL_US 5000000       /* 5 s */
#define CONVERSION_DELAY_US 40000        /* 40 ms (datasheet: typ 36.65 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&t, &tm_buf);
    char timestamp[32];
    if (tm)
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    else
        snprintf(timestamp, sizeof(timestamp), "1970-01-01T00:00:00");

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* File size check & roll                                              */
/* ------------------------------------------------------------------ */
static void check_and_roll_log(void)
{
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        if (errno != ENOENT)
            fprintf(stderr, "Warning: cannot check log file: %s\n",
                    strerror(errno));
        return;
    }

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fclose(fp);

    if (size < 0) {
        fprintf(stderr, "Warning: ftell failed: %s\n", strerror(errno));
        return;
    }

    if (size > LOG_FILE_SIZE_LIMIT) {
        printf("Log file exceeds %d bytes; rolling...\n", LOG_FILE_SIZE_LIMIT);
        fp = fopen(LOG_FILE, "w");
        if (!fp)
            fprintf(stderr, "Error rolling log: %s\n", strerror(errno));
        else
            fclose(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * The HIH6130 is a read-only sensor; a measurement is triggered by a
 * write of 0 bytes (no data payload).  After ~36.65 ms the 40-bit
 * data word is returned on the next read.
 *
 * Returns 0 on success, -1 on I2C error, -2 on sensor status error.
 */
static int read_hih6130(int handle, float *temperature, float *humidity)
{
    char buf[5];
    int  rc;

    /* Trigger a new measurement by writing 0 bytes (no data payload). */
    rc = i2cWriteDevice(handle, "", 0);
    if (rc < 0) {
        fprintf(stderr, "I2C trigger write failed (rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);   /* wait for conversion */

    /* Read 5 bytes: 40-bit data + 2 status bits. */
    rc = i2cReadDevice(handle, buf, 5);
    if (rc != 5) {
        if (rc < 0)
            fprintf(stderr, "I2C read failed (rc=%d): %s\n",
                    rc, strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %d of 5 bytes\n", rc);
        return -1;
    }

    /* Status bits are the two LSBs of the first byte. */
    uint8_t status = (uint8_t)buf[0] & 0x03;
    if (status != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X (0=normal, 1=stale, 2=stuck)\n",
                status);
        return -2;
    }

    /*
     * 40-bit data word (big-endian):
     *   bits 39..32 : humidity MSBs
     *   bits 31..16 : humidity LSBs
     *   bits 15..8  : temperature MSBs
     *   bits 7..0   : temperature LSBs
     */
    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);

    /* Humidity: 0.1 %RH / count, scaled to 0..100 %RH. */
    *humidity = ((float)(raw >> 16) / 16383.0f) * 100.0f;

    /* Temperature: 0.1 °C / count, scaled to 0..175 °C. */
    *temperature = ((float)(raw & 0xFFFF) / 16383.0f) * 175.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X (rc=%d): %s\n",
                I2C_BUS, HIH6130_ADDR, g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HIH6130 logger started. Logging to '%s' every 5 s.\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float temperature, humidity;
        int rc = read_hih6130(g_i2c_handle, &temperature, &humidity);

        if (rc == 0) {
            log_data(temperature, humidity);
            check_and_roll_log();
            printf("T=%.2f C  H=%.2f %%\n", temperature, humidity);
        } else if (rc == -1) {
            fprintf(stderr, "I2C bus error – continuing.\n");
        } else {
            fprintf(stderr, "Sensor status error – continuing.\n");
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly. */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

