code:
/*
 * MLX90824 SENT Pressure Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX90824 VDD  -> 3.3 V (Pin 1)
 *   MLX90824 GND  -> GND   (Pin 6)
 *   MLX90824 SENT -> GPIO4 (Pin 7, BCM 4)
 *
 * The MLX90824 SENT protocol is a single-wire bus; the sensor clocks out
 * 16 nibbles (status + 3 data + 2 checksum) at each conversion cycle.
 * We sample the line at 1 µs intervals and track pulse widths to decode
 * the nibbles.  A synchronization pulse of ~56 ticks (360-810 µs) is
 * required before the first nibble.
 *
 * Build:  gcc -O2 -Wall -o mlx90824_log mlx90824_log.c -lpigpio -lrt
 * Run:    sudo ./mlx90824_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_PIN          4          /* BCM 4 */
#define LOG_FILE          "pressure_log.txt"
#define SAMPLE_US         1          /* 1 µs sampling interval */
#define SYNC_MIN_TICKS    36         /* 360 µs  */
#define SYNC_MAX_TICKS    813        /* 813 µs  */
#define NIB_MIN_TICKS     12         /* 12 µs   */
#define NIB_MAX_TICKS     271        /* 271 µs  */
#define MAX_NIBBLES       16
#define SYNC_TIMEOUT_US   100000     /* 100 ms  */
#define READ_TIMEOUT_US   500000     /* 500 ms  */

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Timing helpers                                                      */
/* ------------------------------------------------------------------ */

static uint32_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint32_t)ts.tv_sec * 1000000u + (uint32_t)(ts.tv_nsec / 1000);
}

static void sleep_us(uint32_t us)
{
    gpioDelay(us);
}

/* ------------------------------------------------------------------ */
/* SENT protocol                                                       */
/* ------------------------------------------------------------------ */

/*
 * Wait for the line to reach the requested level (0 or 1).
 * Returns 0 on success, -1 on timeout.
 */
static int wait_level(int level, uint32_t timeout_us)
{
    uint32_t deadline = now_us() + timeout_us;
    while (gpioRead(SENT_PIN) != level) {
        if (g_terminate) return -1;
        if (now_us() >= deadline) return -1;
    }
    return 0;
}

/*
 * Measure the width of the next edge transition.
 * level_out: 0 -> rising, 1 -> falling
 * ticks_out: number of SAMPLE_US intervals
 * Returns 0 on success, -1 on timeout.
 */
static int measure_edge(int *level_out, int *ticks_out)
{
    uint32_t deadline = now_us() + READ_TIMEOUT_US;

    /* Wait for the line to change */
    while (gpioRead(SENT_PIN) == gpioRead(SENT_PIN)) {
        if (g_terminate) return -1;
        if (now_us() >= deadline) return -1;
    }

    int level = gpioRead(SENT_PIN);
    uint32_t start = now_us();

    /* Wait for the line to stay constant */
    while (gpioRead(SENT_PIN) == level) {
        if (g_terminate) return -1;
        if (now_us() >= deadline) return -1;
    }

    uint32_t elapsed = now_us() - start;
    *level_out = level;
    *ticks_out = (int)(elapsed / SAMPLE_US);
    return 0;
}

/*
 * Read one nibble from the SENT bus.
 * Returns 0 on success (nibble stored in *nibble), -1 on error.
 */
static int read_nibble(int *nibble)
{
    int level, ticks;

    /* Rising edge (end of low phase) */
    if (measure_edge(&level, &ticks) != 0) return -1;
    if (level != 1) return -1;

    /* Falling edge (end of high phase) */
    if (measure_edge(&level, &ticks) != 0) return -1;
    if (level != 0) return -1;

    if (ticks < NIB_MIN_TICKS || ticks > NIB_MAX_TICKS) {
        fprintf(stderr, "Error: nibble pulse width %d ticks out of range\n", ticks);
        return -1;
    }

    *nibble = ticks - NIB_MIN_TICKS;
    return 0;
}

/*
 * Read a complete 16-nibble frame from the SENT bus.
 * Returns 0 on success, -1 on error.
 */
static int read_frame(int nibbles[MAX_NIBBLES])
{
    int level, ticks;

    /* Synchronization pulse: wait for line to go low, then high */
    if (wait_level(0, SYNC_TIMEOUT_US) != 0) {
        fprintf(stderr, "Error: timeout waiting for sync low\n");
        return -1;
    }
    uint32_t sync_start = now_us();
    if (wait_level(1, SYNC_TIMEOUT_US) != 0) {
        fprintf(stderr, "Error: timeout waiting for sync high\n");
        return -1;
    }
    uint32_t sync_end = now_us();
    int sync_ticks = (int)((sync_end - sync_start) / SAMPLE_US);

    if (sync_ticks < SYNC_MIN_TICKS || sync_ticks > SYNC_MAX_TICKS) {
        fprintf(stderr, "Error: sync pulse %d ticks out of range\n", sync_ticks);
        return -1;
    }

    /* Read 16 nibbles */
    for (int i = 0; i < MAX_NIBBLES; i++) {
        if (read_nibble(&nibbles[i]) != 0) {
            fprintf(stderr, "Error: failed to read nibble %d\n", i);
            return -1;
        }
    }
    return 0;
}

/*
 * Convert nibbles to pressure (Pa).
 * Frame layout: [status][d1][d2][d3][c1][c2]
 *   status nibble: 0 = OK, 1 = fault
 *   d1..d3: pressure data (12-bit, 0..4095 Pa)
 *   c1, c2: checksum (c1 = d1^d2^d3, c2 = c1^d1^d2^d3)
 */
static float nibbles_to_pressure(const int nibbles[MAX_NIBBLES])
{
    int status = nibbles[0];
    int d1 = nibbles[1];
    int d2 = nibbles[2];
    int d3 = nibbles[3];
    int c1 = nibbles[4];
    int c2 = nibbles[5];

    if (status != 0) {
        fprintf(stderr, "Warning: sensor reports status %d (fault)\n", status);
    }

    int calc_c1 = d1 ^ d2 ^ d3;
    int calc_c2 = calc_c1 ^ d1 ^ d2 ^ d3;

    if (c1 != calc_c1 || c2 != calc_c2) {
        fprintf(stderr, "Warning: checksum mismatch (c1=%d/calc=%d, c2=%d/calc=%d)\n",
                c1, calc_c1, c2, calc_c2);
        /* Continue anyway; the frame may still be valid */
    }

    int pressure_raw = (d1 << 8) | (d2 << 4) | d3;
    return (float)pressure_raw * 0.1f;  /* 0..4095 Pa */
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    } else {
        fprintf(fp, "<time-error>, Pressure: %.2f Pa\n", pressure);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up so the line is defined when the sensor
     * is disconnected (SENT bus is open-drain). */
    if (gpioSetPullUpDown(SENT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed\n");
    }

    printf("MLX90824 SENT Pressure Logger started. Press Ctrl+C to stop.\n");

    while (!g_terminate) {
        int nibbles[MAX_NIBBLES];

        if (read_frame(nibbles) != 0) {
            fprintf(stderr, "Error: SENT read failed (sensor absent or bus error)\n");
            sleep_us(100000);  /* 100 ms backoff */
            continue;
        }

        float pressure = nibbles_to_pressure(nibbles);
        log_pressure(pressure);
        printf("Pressure: %.2f Pa\n", pressure);

        sleep_us(100000);  /* 100 ms between samples */
    }

    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

