/*
 * TMP117 Greenhouse Temperature Monitor
 * Board:  Raspberry Pi Zero W
 * Sensor: Adafruit TMP117 (I2C address 0x49)
 * Bus:    /dev/i2c-1
 * Output: greenhouse_temps.dat (binary float, little-endian)
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_temps greenhouse_temps.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define TMP117_ADDR      0x49
#define TMP117_REG_TEMP  0x00
#define TMP117_REG_ID    0x0F
#define TMP117_ID_VALUE  0x117
#define LOG_FILE         "greenhouse_temps.dat"
#define SAMPLE_INTERVAL  60          /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16: read reg 0x%02X failed (got %zd bytes): %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    /* TMP117 sends MSB first */
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor                                                              */
/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    int16_t id;
    if (i2c_read_reg16(fd, TMP117_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read TMP117 device ID\n");
        return -1;
    }
    uint16_t raw = (uint16_t)id;
    if (raw != TMP117_ID_VALUE) {
        fprintf(stderr, "TMP117 ID mismatch: got 0x%04X, expected 0x%04X\n",
                raw, TMP117_ID_VALUE);
        return -1;
    }
    printf("TMP117 detected (device ID 0x%04X)\n", raw);
    return 0;
}

static int sensor_read_temp(int fd, float *temp_c)
{
    int16_t raw;
    if (i2c_read_reg16(fd, TMP117_REG_TEMP, &raw) != 0)
        return -1;
    /* 13-bit left-justified two's complement, LSB = 0.0078125 °C */
    *temp_c = (float)raw * 0.0078125f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(FILE **fp)
{
    *fp = fopen(LOG_FILE, "ab");
    if (!*fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    /* Write a sentinel 4-byte magic header so the file is self-describing */
    const uint32_t magic = 0x544D5031;   /* "TMP1" */
    if (fwrite(&magic, sizeof(magic), 1, *fp) != 1) {
        fprintf(stderr, "Cannot write header: %s\n", strerror(errno));
        fclose(*fp);
        *fp = NULL;
        return -1;
    }
    return 0;
}

static int log_write(FILE *fp, float temp_c)
{
    uint32_t raw;
    memcpy(&raw, &temp_c, sizeof(raw));
    if (fwrite(&raw, sizeof(raw), 1, fp) != 1) {
        fprintf(stderr, "Cannot write temperature to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Cannot flush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensor */
    if (sensor_init(fd) != 0) {
        fprintf(stderr, "TMP117 initialization failed\n");
        goto cleanup;
    }

    /* Open log file */
    if (log_open(&fp) != 0)
        goto cleanup;

    printf("Logging greenhouse temperatures to %s every %d s. Press Ctrl-C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    /* Main sampling loop */
    while (g_running) {
        float temp_c;
        if (sensor_read_temp(fd, &temp_c) != 0) {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        } else {
            printf("Temperature: %.2f °C\n", temp_c);
            if (log_write(fp, temp_c) != 0)
                fprintf(stderr, "Log write failed\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fflush(fp);
        fclose(fp);
    }
    if (fd >= 0)
        close(fd);
    return rc;
}

