/*
 * Raspberry Pi Zero W - SHT40 Temperature & Humidity Logger
 *
 * Reads temperature and humidity from an Adafruit SHT40 sensor on the I2C
 * bus (address 0x44) and appends timestamped readings to
 * environmental_data.txt.
 *
 * Build:  gcc -O2 -Wall -o sht40_logger sht40_logger.c -lpigpio -lrt
 * Run:    sudo ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT40_ADDR             0x44
#define SHT40_MEASURE_HIGHREP  0xFD   /* Hold Master mode, 14.5 ms typ */
#define SHT40_MEASURE_LOWREP   0xFE   /* Low power mode, 8.5 ms typ */
#define SHT40_SOFT_RESET       0x94
#define SHT40_MEASUREMENT_MS   15     /* Max conversion time */
#define SAMPLE_INTERVAL_S      5
#define LOG_FILE               "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SHT40 datasheet  */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from SHT40                            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_sht40(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_MEASURE_LOWREP;   /* Low power mode, ~8.5 ms */
    uint8_t data[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[SHT40] I2C write failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(SHT40_MEASUREMENT_MS * 1000);

    /* Read 6 bytes: T_MSB T_LSB T_CRC  H_MSB H_LSB H_CRC */
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[SHT40] I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRC for temperature */
    if (sht40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHT40] Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity */
    if (sht40_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHT40] Humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("[LOG] time()");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("[LOG] localtime_r");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        perror("[LOG] fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("[LOG] fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SHT40 address */
    g_i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                SHT40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float temperature, humidity;

        if (read_sht40(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(g_log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

