/* --------------------------- Add to circular buffer ----------------------- */
static void add_to_buffer(float temperature)
{
    temp_buffer.data[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE)
        temp_buffer.count++;
}

