/*
 * TMP117 Temperature Logger for Raspberry Pi 4 Model B
 *
 * Reads the TI TMP117 temperature sensor over I2C every 5 seconds,
 * stores readings in a circular buffer in memory, and persists the
 * entire buffer to temperature_log.dat on every sample and at program
 * termination.  SIGINT/SIGTERM triggers a clean shutdown with the
 * final buffer state written to disk.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp117_logger tmp117_logger.c
 *
 * Hardware:
 *   TMP117 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3V3, GND -> GND
 *   I2C bus 1, address 0x48 (ADDR pin tied to GND).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define TMP117_ADDR          0x48
#define TMP117_REG_TEMP      0x00
#define TMP117_REG_CONFIG    0x01

#define BUFFER_SIZE          100
#define SAMPLE_INTERVAL_SEC  5
#define LOG_FILE             "temperature_log.dat"

/* ------------------------------- Globals --------------------------------- */
static int                  i2c_handle = -1;
static volatile sig_atomic_t running    = 1;

/*
 * Circular buffer: temperature readings in degrees Celsius.
 * Access is guarded by the pigpio lock (gpioSerialReadByte), but we
 * also use a simple mutex-free model for the in-memory buffer because
 * we are single-threaded and pigpio holds the lock only during I2C
 * transactions.
 */
typedef struct {
    float   data[BUFFER_SIZE];
    int     head;          /* next write slot */
    int     count;         /* number of valid entries */
} CircularBuffer;

static CircularBuffer temp_buffer = { .head = 0, .count = 0 };

/* --------------------------- Function prototypes ------------------------- */
static int  init_i2c(void);
static int  read_temperature(float *temp_c);
static void add_to_buffer(float temperature);
static void write_buffer_to_file(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio error %d\n",
                I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }

    /*
     * Configure TMP117:
     *   CONFIG register (0x01), 16-bit value:
     *     [15]    SHUTDOWN = 0  (power on)
     *     [14:12] CONV_RATE = 000 (1 Hz conversion rate)
     *     [11:9]  MEAS_INT  = 000 (continuous conversion)
     *     [8]     POL      = 0  (active low alert)
     *     [7]     POL      = 0  (active low alert)
     *     [6]     FPOL     = 0  (active low fault)
     *     [5]     FQUE     = 0  (fault queue 1)
     *     [4]     POL      = 0  (active low alert)
     *     [3]     POL      = 0  (active low alert)
     *     [2]     POL      = 0  (active low fault)
     *     [1:0]   RES      = 00 (13-bit resolution)
     *   Value = 0x0000  -> 13-bit, continuous conversion, power on.
     */
    if (i2cWriteWordData(i2c_handle, TMP117_REG_CONFIG, 0x0000) < 0) {
        fprintf(stderr, "Error writing TMP117 config register: %s\n",
                strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
