    if (raw < 0) {
        fprintf(stderr, "Error reading TMP117 temperature register: %s\n",
                strerror(errno));
        return -1;
    }

    /* i2cReadWordData returns the byte-swapped value pigpio received */
    uint16_t swapped = (uint16_t)raw;
    uint16_t msb    = (swapped >> 8) & 0xFF;
    uint16_t lsb    = (swapped >> 0) & 0xFF;
    uint16_t val    = (msb << 8) | lsb;

    /* Sign-extend 16-bit two's-complement to int16_t */
    int16_t signed_val = (int16_t)val;

    *temp_c = (float)signed_val * 0.0078125f;
    return 0;
}

/* --------------------------- Add to circular buffer ----------------------- */
static void add_to_buffer(float temperature)
{
    temp_buffer.data[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE)
        temp_buffer.count++;
}

