static void write_buffer_to_file(void)
{
    FILE *fp = fopen(LOG_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    size_t n = (size_t)temp_buffer.count;
    size_t written = fwrite(temp_buffer.data, sizeof(float), n, fp);
    if (written != n) {
        fprintf(stderr, "Error writing %zu samples to %s: wrote %zu\n",
                n, LOG_FILE, written);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* --------------------------- Cleanup -------------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("TMP117 temperature logger started. Sampling every %d s.\n",
           SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            write_buffer_to_file();
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Skipping sample due to read error.\n");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++)
            sleep(1);
    }

    /* Final flush on exit */
    write_buffer_to_file();
    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

