/*
 * SHTC3 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   VDD  -> Pin 1 (3.3 V)
 *   VSS  -> Pin 2 (GND)
 *   SDA  -> GPIO2 / Pin 3
 *   SCL  -> GPIO3 / Pin 4
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o shtc3_logger shtc3_logger.c -lpigpio -lrt
 *   (pigpio must be installed and run with sudo)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHTC3_ADDR             0x44
#define SHTC3_CMD_MEASURE_HIGH 0xFD
#define SHTC3_CMD_CLEANUP      0x302F
#define SHTC3_CONV_MS          15          /* 12.4 ms typ, 15 ms safe margin */
#define SAMPLE_INTERVAL_S      5
#define LOG_FILE               "shtc3_environment.log"
#define TEMP_MIN_C             (-40.0f)
#define TEMP_MAX_C             125.0f
#define HUM_MIN_PCT            0.0f
#define HUM_MAX_PCT            100.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature and humidity from the SHTC3.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch,
 * -3 on out-of-range value.
 */
static int read_shtc3(float *temperature, float *humidity)
{
    uint8_t cmd = SHTC3_CMD_MEASURE_HIGH;
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd 0x%02X)\n", cmd);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(SHTC3_CONV_MS * 1000);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* CRC validation */
    if (shtc3_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }
    if (shtc3_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -2;
    }

    /* Convert raw values */
    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Range validation */
    if (*temperature < TEMP_MIN_C || *temperature > TEMP_MAX_C) {
        fprintf(stderr, "[ERROR] Temperature out of range: %.2f C\n", *temperature);
        return -3;
    }
    if (*humidity < HUM_MIN_PCT || *humidity > HUM_MAX_PCT) {
        fprintf(stderr, "[ERROR] Humidity out of range: %.2f %%\n", *humidity);
        return -3;
    }

    return 0;
}

static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SHTC3_ADDR */
    g_i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("SHTC3 logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        int rc = read_shtc3(&temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "[WARN] Failed to log data\n");
            }
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I2C communication error\n");
        } else if (rc == -2) {
            fprintf(stderr, "[WARN] CRC validation failed\n");
        } else {
            fprintf(stderr, "[WARN] Out-of-range sensor reading\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        /* Issue soft reset / cleanup command */
        uint8_t cleanup[2] = {
            (SHTC3_CMD_CLEANUP >> 8) & 0xFF,
            SHTC3_CMD_CLEANUP & 0xFF
        };
        (void)i2cWriteDevice(g_i2c_handle, (char *)cleanup, 2);
        gpioDelay(10000);  /* 10 ms for command to take effect */
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

