    printf("SHTC3 logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        int rc = read_shtc3(&temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "[WARN] Failed to log data\n");
            }
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I2C communication error\n");
        } else if (rc == -2) {
            fprintf(stderr, "[WARN] CRC validation failed\n");
        } else {
            fprintf(stderr, "[WARN] Out-of-range sensor reading\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        /* Issue soft reset / cleanup command */
        uint8_t cleanup[2] = {
            (SHTC3_CMD_CLEANUP >> 8) & 0xFF,
            SHTC3_CMD_CLEANUP & 0xFF
