/*
 * Si7202 I2C Hall-effect sensor rotational speed logger.
 *
 * Hardware:
 *   Raspberry Pi 3 Model B+
 *   Si7202 I2C Hall-effect sensor
 *     VDD  -> 3.3 V (Pin 1)
 *     GND  -> GND  (Pin 9)
 *     SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *     SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * I2C address: 0x68 (7-bit)
 *
 * Build:
 *   gcc -O2 -Wall -o mag_temp_log mag_temp_log.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS            1          /* /dev/i2c-1 on RPi 3B+               */
#define SI7202_ADDR        0x68       /* Si7202 7-bit I2C address            */

#define LOG_FILE           "mag_temp_log.csv"
#define SAMPLE_PERIOD_US   1000000    /* 1 second                           */

/*
 * Si7202 register map (representative subset).
 * The exact register layout depends on the Si7202 variant; adjust
 * these constants to match the datasheet for your specific module.
 */
#define REG_TEMP_L         0x00
#define REG_TEMP_H         0x01
#define REG_MAG_L          0x02
#define REG_MAG_H          0x03
#define REG_CTRL1          0x04
#define REG_CTRL2          0x05

/* ----------------------------- Globals ----------------------------------- */

static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  initialize_i2c(void);
static int  read_sensor_data(float *mag, float *temp);
static int  log_data(float mag, float temp);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- I2C init ---------------------------------- */

static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d).\n",
                i2c_handle);
        gpioTerminate();
        return -1;
    }

    /*
     * Configure the Si7202:
     *   CTRL1 = 0x00  -> default mode, continuous conversion
     *   CTRL2 = 0x00  -> default settings
     */
    if (i2cWriteByteData(i2c_handle, REG_CTRL1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write CTRL1 register.\n");
        cleanup();
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_CTRL2, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write CTRL2 register.\n");
        cleanup();
        return -1;
    }

    return 0;
}

/* ----------------------------- Sensor read ------------------------------- */

/*
 * Reads the 16-bit magnetometer (REG_MAG_L/REG_MAG_H) and temperature
 * (REG_TEMP_L/REG_TEMP_H) registers.
 *
 * Returns 0 on success, -1 on I2C error.
 */
static int read_sensor_data(float *mag, float *temp)
{
    int mag_l, mag_h, temp_l, temp_h;
    int16_t mag_raw, temp_raw;

    mag_l  = i2cReadByteData(i2c_handle, REG_MAG_L);
    mag_h  = i2cReadByteData(i2c_handle, REG_MAG_H);
    temp_l = i2cReadByteData(i2c_handle, REG_TEMP_L);
    temp_h = i2cReadByteData(i2c_handle, REG_TEMP_H);

    if (mag_l < 0 || mag_h < 0 || temp_l < 0 || temp_h < 0) {
        fprintf(stderr, "Error: I2C read failed (mag_l=%d, mag_h=%d, "
                        "temp_l=%d, temp_h=%d).\n",
                mag_l, mag_h, temp_l, temp_h);
        return -1;
    }

    mag_raw  = (int16_t)((mag_h << 8) | mag_l);
    temp_raw = (int16_t)((temp_h << 8) | temp_l);

    /*
     * Placeholder conversions.
     * Replace with the formulas from your Si7202 datasheet.
     */
    *mag = (float)mag_raw / 100.0f;   /* Example: raw / 100 for magnetometer */
    *temp = (float)temp_raw / 10.0f;  /* Example: raw / 10 for temperature    */

    return 0;
}

/* ----------------------------- Logging ----------------------------------- */

static int log_data(float mag, float temp)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mag, temp) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    float mag = NAN, temp = NAN;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if file is new/empty. */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Magnetometer,Temperature\n");
        fflush(log_file);
    }

    printf("Logging Si7202 data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        if (read_sensor_data(&mag, &temp) != 0) {
            fprintf(stderr, "Warning: sensor read failed; logging NaN.\n");
            mag = NAN;
            temp = NAN;
        }

        if (log_data(mag, temp) != 0) {
            fprintf(stderr, "Warning: logging failed.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

