#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X on bus %d (code %d)\n",
                TMP117_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (code %d)\n", result);
        return -1;
    }

    short raw = (buf[0] << 8) | buf[1];
    *temperature = (float)raw / 16.0f;
    return 0;
}

static int log_temperature(float temperature) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    int retry_count = 0;
    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            retry_count = 0;
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: Logging failed, continuing...\n");
            }
        } else {
            retry_count++;
            fprintf(stderr, "Warning: Temperature read failed (attempt %d/%d)\n",
                    retry_count, MAX_RETRIES);
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Error: Max retries reached, exiting.\n");
                break;
            }
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioTerminate();
            if (init_i2c() != 0) {
                fprintf(stderr, "Error: Re-initialisation failed, exiting.\n");
                break;
            }
        }
        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

