/*
 * Raspberry Pi Zero W – Honeywell HAFUHH0025PA3 flow sensor logger
 *
 * Wiring:
 *   Sensor SDA  -> Pi GPIO2  (pin 3, I2C bus 1 SDA)
 *   Sensor SCL  -> Pi GPIO3  (pin 5, I2C bus 1 SCL)
 *   Sensor VDD  -> 3.3 V
 *   Sensor GND  -> GND
 *
 * The Honeywell HAF series exposes a 4-byte API call (no register pointer
 * write required) that returns a 14-bit flow value and a 12-bit temperature
 * value.  The first two reads after power-up may return stale data; we
 * discard them and sample again.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x20          /* HAFUHH0025PA3 default I2C address */
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MAX_RETRIES    3             /* retries on transient I2C errors */

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Open the I2C bus and return a valid handle, or -1 on failure.
 */
static int open_i2c(void)
{
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, handle);
        return -1;
    }
    return handle;
}

/*
 * Read 4 bytes from the sensor.
 *
 * The Honeywell HAF series exposes a 4-byte API call:
 *   byte 0: MSB of 14-bit flow value
 *   byte 1: LSB of 14-bit flow value
 *   byte 2: MSB of 12-bit temperature value
 *   byte 3: LSB of 12-bit temperature value
 *
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(int handle, uint8_t data[4])
{
    int bytes_read = i2cReadDevice(handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 4)\n",
                bytes_read);
        return -1;
    }
    return 0;
}

/*
 * Extract flow and temperature from the 4-byte raw payload.
 *
 * Flow:       14 bits, bits [13:0] of data[0:1]
 * Temperature: 12 bits, bits [11:0] of data[2:3]
 */
static void extract_values(const uint8_t data[4],
                           float *flow, float *temperature)
{
    uint16_t raw_flow = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_temp = ((uint16_t)data[2] << 8) | data[3];

    /*
     * HAF series conversion formulas (example, adjust per your
     * sensor datasheet if different):
     *
     *   flow        = raw_flow / 100.0   (SLPM)
     *   temperature = raw_temp / 10.0    (°C)
     *
     * Replace the constants with the values from your datasheet.
     */
    *flow        = (float)raw_flow / 100.0f;
    *temperature = (float)raw_temp / 10.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(float flow, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, %.2f SLPM, %.2f C\n",
            timestamp, flow, temperature);
    fflush(g_log_file);
}

static void log_error(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = open_i2c();
    if (g_i2c_handle < 0) {
        log_error("Initial I2C open failed; will retry in 5 s");
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        sleep(5);
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HAF flow logger started.  Logging to %s  (Ctrl-C to stop)\n",
           LOG_FILE);

    /* ---- discard first two stale reads after power-up ---- */
    uint8_t stale[4];
    for (int i = 0; i < 2; i++) {
        if (read_sensor_data(g_i2c_handle, stale) != 0) {
            log_error("Stale read failed; continuing");
        }
        sleep(1);
    }

    /* ---- main sampling loop ---- */
    while (g_running) {
        uint8_t data[4];
        int read_ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor_data(g_i2c_handle, data) == 0) {
                read_ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                log_error("I2C read attempt failed; retrying in 1 s");
                sleep(1);
            }
        }

        if (!read_ok) {
            log_error("All I2C read attempts failed; re-initialising bus");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            sleep(5);
            g_i2c_handle = open_i2c();
            if (g_i2c_handle < 0) {
                log_error("Re-initialisation failed; exiting");
                break;
            }
            continue;
        }

        float flow, temperature;
        extract_values(data, &flow, &temperature);
        log_data(flow, temperature);

        sleep(SAMPLE_PERIOD);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

