#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define READ_INTERVAL_US 2000000  /* 2 seconds */
#define MAX_RETRIES 3
#define TIMEOUT_US 100000         /* 100 ms per phase */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen("dht11_errors.txt", "a");
    if (!fp) {
        perror("fopen dht11_errors.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    }
    fclose(fp);
}

static void log_reading(float temp, float hum) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (!fp) {
        perror("fopen dht11_readings.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.1f,%.1f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    }
    fclose(fp);
}

/*
 * Wait for the pin to reach the requested level or time out.
 * Returns 0 on success, -1 on timeout.
 */
static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if (gpioTick() - start > timeout_us) return -1;
    }
    return 0;
}

/*
 * Measure the duration (µs) that the pin stays at the given level.
 * Returns duration on success, -1 on timeout.
 */
static int measure_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == level) {
        if (gpioTick() - start > timeout_us) return -1;
    }
    return (int)(gpioTick() - start);
}

/*
 * Read 40 bits from the DHT11.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_dht11(int gpio, float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i;

    /* --- Start signal: pull low for >= 18 ms, then high --- */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, 0) < 0) return -1;
    gpioDelay(20000);                       /* 20 ms low (>= 18 ms) */
    if (gpioWrite(gpio, 1) < 0) return -1;
    gpioDelay(30);                          /* 30 µs high */

    /* Switch to input and let the sensor drive the line */
    if (gpioSetMode(gpio, PI_INPUT) < 0) return -1;

    /* --- Sensor response: ~80 µs low then ~80 µs high --- */
    if (wait_level(gpio, 0, TIMEOUT_US) < 0) return -1;   /* wait for low */
    if (wait_level(gpio, 1, TIMEOUT_US) < 0) return -1;   /* low ends */
    if (wait_level(gpio, 0, TIMEOUT_US) < 0) return -1;   /* high ends */

    /* --- Read 40 data bits --- */
    for (i = 0; i < 40; i++) {
        /* Each bit begins with ~50 µs low */
        if (wait_level(gpio, 1, TIMEOUT_US) < 0) return -1;

        /* Measure high duration: ~26–28 µs => '0', ~70 µs => '1' */
        int dur = measure_level(gpio, 0, TIMEOUT_US);
        if (dur < 0) return -1;

        data[i / 8] <<= 1;
        if (dur > 50) data[i / 8] |= 1;

        /* Skip the trailing ~26 µs low period (already consumed) */
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) return -2;

    *hum = (float)data[0];
    *temp = (float)data[2];
    return 0;
}

int main(void) {
    float temp, hum;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            ret = read_dht11(DHT11_GPIO, &temp, &hum);
            if (ret == 0) {
                ok = 1;
                break;
            }
            if (ret == -1)
                log_error("DHT11 timeout");
            else if (ret == -2)
                log_error("DHT11 checksum error");
            gpioDelay(1000000);  /* 1 s backoff before retry */
        }

        if (ok) {
            log_reading(temp, hum);
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else if (running) {
            log_error("DHT11 unreachable after retries");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 20 && running; i++)
            gpioDelay(100000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

