/*
 * SHT31-D Temperature & Humidity Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SHT31-D VDD  -> 3.3 V (Pin 1)
 *   SHT31-D GND  -> GND   (Pin 9)
 *   SHT31-D SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SHT31-D SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sht31d_logger sht31d_logger.c -lpigpio -lrt
 *   (Run as root, or with appropriate /dev/i2c-1 permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT31_ADDR     0x44          /* SHT31-D default I2C address */
#define LOG_FILE       "sht31d_data.log"
#define SAMPLE_PERIOD  5             /* seconds between readings */
#define MAX_RETRIES    3
#define MEAS_DELAY_US  20000         /* 20 ms (datasheet: typ 15 ms) */

/* SHT31-D command: single-shot, high repeatability, clock stretching disabled */
static const uint8_t CMD_MEASURE[2] = { 0x2C, 0x06 };

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — SHT31-D datasheet */
/* ------------------------------------------------------------------ */
static uint8_t sht31_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one measurement with retries                                   */
/* ------------------------------------------------------------------ */
static int read_sensor(float *temperature, float *humidity)
{
    uint8_t buf[6];

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        /* Issue measurement command */
        if (i2cWriteDevice(g_i2c_handle, (char *)CMD_MEASURE, 2) != 0) {
            fprintf(stderr, "[attempt %d/%d] I2C write failed\n",
                    attempt, MAX_RETRIES);
            gpioDelay(100000);
            continue;
        }

        /* Wait for conversion (datasheet: typ 15 ms, max 15 ms) */
        gpioDelay(MEAS_DELAY_US);

        /* Read 6 bytes: T_MSB T_LSB T_CRC  H_MSB H_LSB H_CRC */
        if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "[attempt %d/%d] I2C read failed\n",
                    attempt, MAX_RETRIES);
            gpioDelay(100000);
            continue;
        }

        /* Validate CRC-8 for temperature and humidity */
        if (sht31_crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d/%d] temperature CRC mismatch\n",
                    attempt, MAX_RETRIES);
            gpioDelay(100000);
            continue;
        }
        if (sht31_crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d/%d] humidity CRC mismatch\n",
                    attempt, MAX_RETRIES);
            gpioDelay(100000);
            continue;
        }

        /* Convert raw values */
        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Log a reading or an error                                           */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float humidity)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (temperature < -50.0f || temperature > 150.0f ||
        humidity    <   0.0f || humidity    > 100.0f) {
        fprintf(stderr, "[%s] Sensor reading out of range: T=%.2f C, H=%.2f %%\n",
                ts, temperature, humidity);
        fprintf(g_log_file, "%s,ERROR,ERROR\n", ts);
    } else {
        fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    }
    fflush(g_log_file);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "[%s] %s\n", ts, msg);
    fprintf(g_log_file, "%s,ERROR,ERROR,%s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SHT31_ADDR, g_i2c_handle);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT31-D logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            log_error("Sensor read failed after retries");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

