/*
 * Raspberry Pi Zero W – Dual ADPD105 CCT Logger
 *
 * Reads two Analog Devices ADPD105 photometric front-end sensors
 * over I2C and computes the correlated color temperature (CCT).
 * Logs the average CCT once per second to cct_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o cct_logger cct_logger.c -lm
 *
 * Wiring:
 *   ADPD105 SDA  -> GPIO2 (pin 3)
 *   ADPD105 SCL  -> GPIO3 (pin 5)
 *   ADPD105 VDD  -> 3.3 V
 *   ADPD105 GND  -> GND
 *   ADPD105 ADDR -> GND  (I2C address 0x39)
 *
 * The ADPD105 exposes a register map; the CCT is computed from
 * the ratio of the green channel to the red channel.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADPD105_ADDR         0x39          /* ADDR pin tied to GND */
#define NUM_SENSORS          2

/* ADPD105 register addresses (example – adjust to your datasheet) */
#define REG_RED_CH_DATA      0x04
#define REG_GREEN_CH_DATA    0x05
#define REG_CLEAR_CH_DATA    0x06
#define REG_CONFIG           0x00

#define LOG_FILE             "cct_log.csv"
#define SAMPLE_PERIOD_US     1000000       /* 1 second */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_terminate = 0;
static int      g_i2c_handles[NUM_SENSORS];
static FILE    *g_log_file = NULL;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* --------------------------- Sensor helpers ------------------------------ */

/*
 * Read a 16-bit little-endian register from the ADPD105.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "[handle %d] I2C write error (reg 0x%02X): %s\n",
                handle, reg, pigpio_error(i2cWriteByte(handle, reg)));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[handle %d] I2C read error (reg 0x%02X): %s\n",
                handle, reg, pigpio_error(i2cReadDevice(handle, buf, 2)));
        return -1;
    }

    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/*
 * Read all three channels of a sensor.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *clear)
{
    if (read_sensor_reg16(handle, REG_RED_CH_DATA,    red)    != 0) return -1;
    if (read_sensor_reg16(handle, REG_GREEN_CH_DATA,  green)  != 0) return -1;
    if (read_sensor_reg16(handle, REG_CLEAR_CH_DATA,  clear)  != 0) return -1;
    return 0;
}

/*
 * Compute correlated color temperature (Kelvin) from red/green/clear counts.
 * The ADPD105 green channel is often used as a proxy for CCT; this computes
 * a simple ratio-based estimate.  For a real application the calibration
 * curve must be derived from the sensor datasheet.
 */
static float calculate_cct(uint16_t red, uint16_t green, uint16_t clear)
{
    if (green == 0) return 0.0f;

    float ratio = (float)red / (float)green;
    float cct   = 2000.0f + 2000.0f * ratio;   /* placeholder linear model */

    if (cct < 1000.0f) cct = 1000.0f;
    if (cct > 10000.0f) cct = 10000.0f;
    return cct;
}

/* ------------------------------ Logging ---------------------------------- */

static void log_cct(float cct)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, cct) < 0) {
        perror("fprintf to log file");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------ Cleanup ---------------------------------- */

static void cleanup(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C handles for both sensors */
    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_handles[i] = i2cOpen(I2C_BUS, ADPD105_ADDR, 0);
        if (g_i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C device %d (addr 0x%02X): %s\n",
                    i, ADPD105_ADDR, pigpio_error(g_i2c_handles[i]));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Open log file (append mode) */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Average_CCT\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging ADPD105 CCT to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* Main sampling loop */
    while (!g_terminate) {
        uint16_t red[NUM_SENSORS], green[NUM_SENSORS], clear[NUM_SENSORS];
        int      ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_sensor_data(g_i2c_handles[i], &red[i], &green[i], &clear[i]) != 0) {
                fprintf(stderr, "Sensor %d read failed; skipping cycle\n", i);
                ok = 0;
                break;
            }
        }

        if (!ok) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float cct_sum = 0.0f;
        for (int i = 0; i < NUM_SENSORS; i++) {
            cct_sum += calculate_cct(red[i], green[i], clear[i]);
        }

        float avg_cct = cct_sum / (float)NUM_SENSORS;
        log_cct(avg_cct);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

