/*
 * MLX90824 pressure sensor logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90824 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90824 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90824 VDD  -> 3.3 V
 *   MLX90824 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90824_logger mlx90824_logger.c \
 *       -lm -lrt
 *
 * Run:
 *   ./mlx90824_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS            1          /* /dev/i2c-1 on Raspberry Pi 4 */
#define MLX90824_ADDR      0x30       /* 7-bit I2C address */
#define LOG_FILE           "pressure_log.txt"
#define READ_INTERVAL_SEC  2          /* seconds between readings */
#define MAX_READ_RETRIES   3          /* consecutive failures before aborting */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_sensor(float *pressure, float *temperature);
static void log_data(float pressure, float temperature);
static void log_error(const char *msg);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ---------------------------------- */

static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, MLX90824_ADDR, g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ----------------------------- Sensor read ------------------------------- */

/*
 * Reads the 16-bit raw pressure and temperature values from the MLX90824.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_sensor(float *pressure, float *temperature)
{
    char buf[4];
    int  bytes_read;

    /*
     * Read 4 bytes: pressure MSB, pressure LSB, temperature MSB, temperature LSB.
     * pigpio's i2cReadDevice returns the number of bytes read, or < 0 on error.
     */
    bytes_read = i2cReadDevice(g_i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 4): %s\n",
                bytes_read, strerror(errno));
        return -1;
    }

    /* Assemble 16-bit big-endian values */
    uint16_t raw_pressure    = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_temperature = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    /*
     * Convert raw values to physical units.
     *
     * Pressure:    raw / 65535.0 * 100.0  Pa  (0–100 Pa full-scale)
     * Temperature: raw / 65535.0 * 200.0 - 50.0 °C (0–200 °C full-scale)
     *
     * The MLX90824 is an absolute sensor; the scale factors are derived from
     * the datasheet's 16-bit resolution and the application-level full-scale
     * range.
     */
    *pressure    = (float)raw_pressure    / 65535.0f * 100.0f;
    *temperature = (float)raw_temperature / 65535.0f * 200.0f - 50.0f;

    return 0;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_data(float pressure, float temperature)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Pressure: %.2f Pa, Temperature: %.2f °C\n",
            timestamp, pressure, temperature);
    fflush(g_log_file);
}

static void log_error(const char *msg)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, ERROR: %s\n", timestamp, msg);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    float pressure, temperature;
    int   consecutive_failures = 0;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Initialise I2C */
    if (init_i2c() != 0) {
        log_error("I2C initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90824 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, READ_INTERVAL_SEC);

    /* Main acquisition loop */
    while (g_running) {
        if (read_sensor(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            consecutive_failures = 0;
        } else {
            log_error("Sensor read failed");
            consecutive_failures++;
            if (consecutive_failures >= MAX_READ_RETRIES) {
                log_error("Max consecutive failures reached, aborting");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 0, 100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

