/*
 * Raspberry Pi 4 Model B — LM75B temperature monitor with hysteresis fan control.
 *
 * Hardware:
 *   - LM75B I2C temperature sensor  (ADDR 0x48, bus /dev/i2c-1)
 *   - 4-wire NPN/N-FET cooling fan on GPIO18 (BCM), driven via hardware PWM
 *     (PWM0 on GPIO18, hardware-clocked via ALT0 function).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lm75b_fan lm75b_fan.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1          /* /dev/i2c-1 on Pi 4 */
#define LM75B_ADDR         0x48       /* LM75B default 7-bit address */
#define LM75B_TEMP_REG     0x00       /* Temperature register */
#define LM75B_CONFIG_REG   0x01       /* Configuration register */

#define FAN_GPIO           18         /* BCM 18 — hardware PWM0 */
#define PWM_FREQ_HZ        25000      /* 25 kHz — typical for 4-wire PC fans */
#define PWM_RANGE          1000       /* duty 0–1000 → 0–100 % */

#define TEMP_THRESHOLD_HIGH 28.0f     /* °C — fan ON  above this */
#define TEMP_THRESHOLD_LOW  26.0f     /* °C — fan OFF below this */

#define BUFFER_SIZE        60         /* seconds of history */
#define SAMPLE_PERIOD_S    1          /* seconds between samples */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_fan_on     = false;

/* Circular buffer */
typedef struct {
    float    data[BUFFER_SIZE];
    int      head;          /* next write slot */
    int      count;         /* valid samples (<= BUFFER_SIZE) */
} CircularBuffer;

static CircularBuffer g_temp_buffer = { {0.0f}, 0, 0 };

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_temperature(float *temp_c);
static void init_fan(void);
static void set_fan_speed(int duty);
static void cleanup(void);
static void buffer_add(CircularBuffer *cb, float value);
static float buffer_average(const CircularBuffer *cb);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, LM75B_ADDR, strerror(errno));
        return -1;
    }

    /*
     * Configure LM75B: continuous conversion, 11-bit resolution (0x00).
     * Write 0x00 to the config register to power the device and enable
     * continuous mode.  A negative result indicates a bus error.
     */
    if (i2cWriteByteData(g_i2c_handle, LM75B_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to configure LM75B: %s\n",
                strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- Temperature read -------------------------- */
static int read_temperature(float *temp_c)
{
    if (temp_c == NULL) {
        return -1;
    }

    /*
     * LM75B temperature register (0x00) contains a 16-bit value.
     * The upper byte is the most significant byte (MSB), the lower
     * byte is the least significant byte (LSB).
     *
     * The LSB bit 7 (D15) is the sign bit (0 = positive, 1 = negative).
     * Bits 14:12 (D14:D12) are the exponent; bits 11:0 (D11:D0) are the
     * mantissa.  The temperature is calculated as:
     *
     *   T = (mantissa / 2^exponent) * 0.125
     *
     * For 11-bit resolution (config = 0x00) the exponent is 0, so:
     *   T = mantissa * 0.125
     *
     * If the sign bit is set, the temperature is negative.
     */
    int msb = i2cReadByteData(g_i2c_handle, LM75B_TEMP_REG);
    if (msb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(temp MSB) failed: %s\n",
                strerror(errno));
        return -1;
    }

    int lsb = i2cReadByteData(g_i2c_handle, LM75B_TEMP_REG + 1);
    if (lsb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(temp LSB) failed: %s\n",
                strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)msb << 8) | (uint16_t)lsb;
    int16_t  signed_raw = (int16_t)raw;

    *temp_c = (float)signed_raw * 0.125f;
    return 0;
}

/* ----------------------------- Fan init / control ------------------------ */
static void init_fan(void)
{
    /*
     * pigpio hardware PWM on GPIO18 (BCM 18).
     * gpioSetMode(18, PI_ALT0) sets the pin to ALT0 (PWM0).
     */
    if (gpioSetMode(FAN_GPIO, PI_ALT0) < 0) {
        fprintf(stderr, "[WARN] gpioSetMode(18, ALT0) failed: %s\n",
                strerror(errno));
        return;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "[WARN] gpioSetPWMfrequency(%d, %d) failed: %s\n",
                FAN_GPIO, PWM_FREQ_HZ, strerror(errno));
        return;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "[WARN] gpioSetPWMrange(%d, %d) failed: %s\n",
                FAN_GPIO, PWM_RANGE, strerror(errno));
        return;
    }

    /* Start with fan off */
    set_fan_speed(0);
}

static void set_fan_speed(int duty)
{
    if (duty < 0)   duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpioPWM(FAN_GPIO, duty) < 0) {
        fprintf(stderr, "[WARN] gpioPWM(%d, %d) failed: %s\n",
                FAN_GPIO, duty, strerror(errno));
        return;
    }

    if (duty > 0) {
        g_fan_on = true;
    } else {
        g_fan_on = false;
    }
}

/* ----------------------------- Circular buffer --------------------------- */
static void buffer_add(CircularBuffer *cb, float value)
{
    if (cb == NULL) return;
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb)
{
    if (cb == NULL || cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->data[i];
    }
    return sum / (float)cb->count;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure fan is off before tearing down */
    if (g_fan_on) {
        set_fan_speed(0);
        g_fan_on = false;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize fan control */
    init_fan();

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("LM75B fan controller started.  Threshold ON > %.1f C, OFF < %.1f C\n",
           TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "[WARN] Temperature read failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        buffer_add(&g_temp_buffer, temperature);
        float avg = buffer_average(&g_temp_buffer);

        printf("Temperature: %.2f C | Average: %.2f C | Fan: %s\n",
               temperature, avg, g_fan_on ? "ON" : "OFF");

        /* Hysteresis control */
        if (avg > TEMP_THRESHOLD_HIGH && !g_fan_on) {
            set_fan_speed(PWM_RANGE / 2);   /* 50 % */
        } else if (avg < TEMP_THRESHOLD_LOW && g_fan_on) {
            set_fan_speed(0);
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

