/*
 * Raspberry Pi Zero W – Sensirion SDP810-500Pa differential pressure logger
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3)
 *   SDP810 SCL  -> GPIO3 (pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 * Run:    sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define SDP810_ADDR        0x21          /* default 7-bit I2C address */
#define MEASURE_CMD        0x3608        /* continuous measurement, mass flow */
#define MEASURE_DELAY_US   45000         /* 45 ms first-measurement wait */
#define SAMPLE_PERIOD_US   1000000       /* 1 s between samples */
#define PRESSURE_THRESHOLD 5.0f          /* Pa – warning threshold */
#define LOG_FILE           "airflow.log"
#define READ_BUF_LEN       9             /* 3 words × (2 data + 1 CRC) */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Sensirion CRC-8 (polynomial 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Initialise pigpio and open I2C ---- */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d) – sensor may be absent.\n",
                g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,pressure_pa,temperature_c\n");

    return 0;
}

/* ---- Send measurement command ---- */
static int send_measure_cmd(void)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (rc=%d).\n", rc);
        return -1;
    }
    return 0;
}

/* ---- Read 9 bytes and validate CRCs ---- */
static int read_sensor_data(int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[READ_BUF_LEN];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, READ_BUF_LEN);
    if (rc != READ_BUF_LEN) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected %d).\n",
                rc, READ_BUF_LEN);
        return -1;
    }

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d.\n", i);
            return -1;
        }
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

/* ---- Log one reading ---- */
static void log_data(int16_t pressure, int16_t temperature)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s,%d,%d\n", ts, pressure, temperature);
    fflush(g_log_file);
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize() != 0)
        return EXIT_FAILURE;

    /* First measurement after 45 ms */
    if (send_measure_cmd() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(MEASURE_DELAY_US);

    while (g_running) {
        int16_t pressure = 0, temperature = 0;

        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);

            float pa = (float)pressure / 100.0f;   /* raw / 100 = Pa */
            if (pa > PRESSURE_THRESHOLD)
                fprintf(stderr,
                        "Warning: pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pa, PRESSURE_THRESHOLD);
        } else {
            fprintf(stderr, "Warning: sensor read failed – will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

