/*
 * Raspberry Pi 3 Model B+ — STTS2004 temperature sensor monitor
 *
 * Hardware:
 *   - STTS2004 I2C address: 0x49 (ADDR pin tied to GND)
 *   - STTS2004 SDA: GPIO2 (pin 3), SCL: GPIO3 (pin 5), VDD: 3.3 V, GND: GND
 *   - LED anode: GPIO17 (BCM), cathode: GND
 *
 * Behavior:
 *   - Reads temperature once per second.
 *   - LED on when temperature > 28 °C (hysteresis: off at 27 °C).
 *   - Exits on repeated I2C errors or SIGINT/SIGTERM.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o stts2004_monitor stts2004_monitor.c -lpigpio -lrt
 *   (pigpio must be installed and run with sudo)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x49
#define GPIO_LED       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_INTERVAL  1          /* seconds */
#define MAX_CONSEC_ERR 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read the 16-bit temperature register (0x00) from the STTS2004.
 * Returns 0 on success and stores the temperature in *out_temp.
 * Returns -1 on error.
 */
static int read_temperature(int fd, float *out_temp)
{
    uint8_t reg = 0x00;
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg pointer) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Read 2 bytes of temperature data */
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /*
     * STTS2004 temperature register (0x00):
     *   buf[0] = MSB (bits 7:0)
     *   buf[1] = LSB (bits 7:2 = temperature MSB, bits 1:0 = LSB)
     *
     * Resolution: 0.0625 °C per LSB.
     */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_temp = (float)raw * 0.0625f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(int pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", pin);
        return -1;
    }
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

static int gpio_set(int pin, int level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int consecutive_errors = 0;
    bool led_on = false;

    install_signal_handlers();

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize LED GPIO */
    if (gpio_init(GPIO_LED) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus and target the STTS2004 */
    g_i2c_fd = i2c_open(I2C_BUS, STTS2004_ADDR);
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("STTS2004 monitor started.  I2C=%s  addr=0x%02X  LED=GPIO%d\n",
           I2C_BUS, STTS2004_ADDR, GPIO_LED);
    printf("Thresholds: %.1f °C (high), %.1f °C (low)  — Ctrl+C to exit\n",
           TEMP_HIGH, TEMP_LOW);
    fflush(stdout);

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            consecutive_errors = 0;

            printf("Temperature: %.2f °C\n", temperature);
            fflush(stdout);

            /* Hysteresis: turn LED on above high threshold, off below low */
            if (!led_on && temperature > TEMP_HIGH) {
                if (gpio_set(GPIO_LED, 1) == 0) {
                    led_on = true;
                    printf("  -> LED ON (above %.1f °C)\n", TEMP_HIGH);
                }
            } else if (led_on && temperature < TEMP_LOW) {
                if (gpio_set(GPIO_LED, 0) == 0) {
                    led_on = false;
                    printf("  -> LED OFF (below %.1f °C)\n", TEMP_LOW);
                }
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (%d consecutive)\n",
                    consecutive_errors);

            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL * 10 && g_running; i++)
            usleep(100000);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

