code:
/*
 * SDP800-500Pa differential pressure & temperature logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), SDP800-500Pa I2C address 0x2B
 * Output: flow_data.txt  (timestamp, pressure_Pa, temperature_degC)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define SDP800_ADDR        0x2B
#define MEASURE_CMD        0x362F   /* continuous measurement, no averaging */
#define MEASURE_DELAY_US   45000    /* 45 ms worst-case conversion time */
#define SAMPLE_PERIOD_US   1000000  /* 1 s between samples */
#define LOG_FILE           "flow_data.txt"
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Send the 16-bit measurement command as two bytes (big-endian).
 * Returns 0 on success, -1 on failure.
 */
static int send_measure_cmd(int handle)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (sensor may be absent)\n");
        return -1;
    }
    return 0;
}

/*
 * Read exactly 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(3).
 * Returns 0 on success, -1 on failure.
 */
static int read_measurement(int handle, uint8_t *buf)
{
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 9)\n", n);
        return -1;
    }
    return 0;
}

/*
 * Validate CRCs for pressure, temperature, and scale factor.
 * Returns 0 on success, -1 on failure.
 */
static int validate_crcs(const uint8_t *buf)
{
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] scale-factor CRC mismatch\n");
        return -1;
    }
    return 0;
}

/*
 * Convert raw big-endian signed 16-bit values to physical units.
 * SDP800-500Pa: pressure in Pa, temperature in °C.
 */
static void convert_data(const uint8_t *buf, float *pressure, float *temperature)
{
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    /*
     * Scale factors from the SDP8xx datasheet:
     *   pressure_scale  = buf[6] * 256 + buf[7]
     *   temp_scale      = buf[7] * 256 + buf[8]
     * (buf[6] is the low byte of the scale factor, buf[7] is the high byte).
     *
     * The SDP8xx outputs differential pressure and temperature as signed
     * 16-bit values scaled by the scale factor.  The scale factor is
     * constant for a given sensor and is provided in the 3-byte trailer.
     */
    uint16_t pressure_scale = (uint16_t)((buf[6] << 8) | buf[7]);
    uint16_t temp_scale     = (uint16_t)((buf[7] << 8) | buf[8]);

    if (pressure_scale == 0 || temp_scale == 0) {
        fprintf(stderr, "[ERROR] invalid scale factor (p=%u, t=%u)\n",
                pressure_scale, temp_scale);
        *pressure = 0.0f;
        *temperature = 0.0f;
        return;
    }

    *pressure    = (float)raw_pressure / (float)pressure_scale;
    *temperature = (float)raw_temp     / (float)temp_scale;
}

static void log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                pressure, temperature);
    } else {
        fprintf(fp, "%ld, %.2f, %.2f\n", (long)t, pressure, temperature);
    }

    if (fclose(fp) != 0)
        perror("[WARN] fclose(" LOG_FILE ")");
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP800_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

