    while (g_running) {
        uint8_t buf[9];
        bool success = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (send_measure_cmd(g_i2c_handle) != 0) {
                gpioDelay(100000);
