/*
 * Si7021 temperature & humidity logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si7021 SDA -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   Si7021 SCL -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   Si7021 VDD -> 3.3 V
 *   Si7021 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7021_logger si7021_logger.c -lpigpio -lrt
 *   (pigpio must be installed and run with sudo)
 *
 * Log file: environment.log  (CSV: timestamp,temperature_c,humidity_pct)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1          /* /dev/i2c-1 on RPi 4 */
#define SI7021_ADDR          0x40       /* default Si7021 I2C address */

#define CMD_MEASURE_RH_NO_HOLD   0xF5   /* RH, clock stretching disabled */
#define CMD_MEASURE_TEMP_NO_HOLD 0x24   /* Temp, clock stretching disabled */
#define CMD_READ_TEMP_PREV_RH    0xE0   /* Temp from RH measurement */
#define CMD_READ_ID_1            0xFA   /* Read electronic ID byte 1 */
#define CMD_READ_ID_2            0x0F   /* Read electronic ID byte 2 */
#define CMD_READ_FW_REV          0x84   /* Read firmware revision */

#define LOG_FILE              "environment.log"
#define SAMPLE_INTERVAL_SEC   60
#define MAX_RETRIES           3
#define MEASURE_WAIT_US       20000     /* 20 ms worst-case conversion */

/* --------------------------- Global state ------------------------------ */

static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  init_i2c(void);
static int  verify_sensor(void);
static int  read_measurement(uint8_t cmd, uint16_t *raw);
static float raw_to_celsius(uint16_t raw);
static float raw_to_humidity(uint16_t raw);
static void log_data(float temp_c, float rh_pct);
static void log_error(const char *msg);
static void cleanup(void);

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        log_error("I2C initialisation failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (verify_sensor() != 0) {
        log_error("Si7021 sensor not detected.");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t raw_rh = 0, raw_temp = 0;
        int      ok = 0;

        /*
         * Si7021 dual-measurement command sequence:
         *   1. Send RH measurement command (0xF5)
         *   2. Wait ~20 ms for conversion
         *   3. Send Temp measurement command (0x24)
         *   4. Wait ~20 ms for conversion
         *   5. Read both 2-byte results in one burst via 0xE0
         *
         * This sequence is atomic and avoids clock-stretching issues.
         */
        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; ++attempt) {
            /* Issue RH measurement command */
            if (i2cWriteByte(i2c_handle, CMD_MEASURE_RH_NO_HOLD) != 0) {
                log_error("I2C write RH command failed.");
                continue;
            }
            gpioDelay(MEASURE_WAIT_US);

            /* Issue Temp measurement command */
            if (i2cWriteByte(i2c_handle, CMD_MEASURE_TEMP_NO_HOLD) != 0) {
                log_error("I2C write Temp command failed.");
                continue;
            }
            gpioDelay(MEASURE_WAIT_US);

            /* Read both measurements via 0xE0 */
            if (i2cWriteByte(i2c_handle, CMD_READ_TEMP_PREV_RH) != 0) {
                log_error("I2C write read-temp command failed.");
                continue;
            }
            gpioDelay(1000);  /* small settle */

            char buf[4];
            int n = i2cReadDevice(i2c_handle, buf, 4);
            if (n != 4) {
                log_error("I2C read measurement data failed.");
                continue;
            }

            raw_rh    = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            raw_temp  = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
            ok = 1;
            break;
        }

        if (!ok) {
            log_error("Failed to read sensor after retries.");
        } else {
            float temp_c = raw_to_celsius(raw_temp);
            float rh_pct = raw_to_humidity(raw_rh);
            log_data(temp_c, rh_pct);
        }

        /* Sleep SAMPLE_INTERVAL_SEC, but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_SEC && !terminate; ++s) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------- I2C initialisation ------------------------- */

static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------ Verify sensor presence ------------------------ */

static int verify_sensor(void)
{
    /*
     * Read the electronic ID (byte 1) and firmware revision (byte 2).
     * A valid Si7021 returns 0x15 in byte 1 and 0x2 in byte 2.
     */
    if (i2cWriteByte(i2c_handle, CMD_READ_ID_1) != 0) {
        fprintf(stderr, "Error: failed to write ID read command.\n");
        return -1;
    }
    gpioDelay(1000);

    char id_buf[2];
    int n = i2cReadDevice(i2c_handle, id_buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: failed to read ID (got %d bytes).\n", n);
        return -1;
    }

    uint8_t id1 = (uint8_t)id_buf[0];
    uint8_t id2 = (uint8_t)id_buf[1];

    /* Si7021 electronic ID byte 1 is 0x15, byte 2 is 0x2 */
    if (id1 != 0x15 || id2 != 0x02) {
        fprintf(stderr, "Warning: unexpected ID bytes 0x%02X 0x%02X "
                        "(expected 0x15 0x02).\n", id1, id2);
        return -1;
    }

    /* Also read firmware revision for completeness */
    if (i2cWriteByte(i2c_handle, CMD_READ_FW_REV) != 0) {
        fprintf(stderr, "Warning: failed to read firmware revision.\n");
        return 0;  /* non-fatal */
    }
    gpioDelay(1000);

    char rev_buf[1];
    n = i2cReadDevice(i2c_handle, rev_buf, 1);
    if (n != 1) {
        fprintf(stderr, "Warning: failed to read firmware revision.\n");
        return 0;
    }

    uint8_t fw = (uint8_t)rev_buf[0];
    printf("Si7021 detected (ID=0x%02X, FW=0x%02X).\n", id1, fw);
    return 0;
}

/* ------------------------ Read a 16-bit measurement --------------------- */

static int read_measurement(uint8_t cmd, uint16_t *raw)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteByte(i2c_handle, cmd) != 0) {
            log_error("I2C write measurement command failed.");
            continue;
        }
        gpioDelay(MEASURE_WAIT_US);

        char buf[2];
        int n = i2cReadDevice(i2c_handle, buf, 2);
        if (n != 2) {
            log_error("I2C read measurement data failed.");
            continue;
        }

        *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        return 0;
    }
    return -1;
}

/* ------------------------ Convert raw to Celsius ------------------------ */

static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * raw / 65536.0f) - 46.85f;
}

/* ---------------------- Convert raw to humidity % ----------------------- */

static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* --------------------------- Log data to file --------------------------- */

static void log_data(float temp_c, float rh_pct)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fflush(log_file);

    printf("%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
}

/* --------------------------- Log error to file -------------------------- */

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(log_file);
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
}

/* ------------------------------ Cleanup --------------------------------- */

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

