/*
 * HVAC Pressure Monitor — Raspberry Pi Zero W
 * Sensor : Sensirion SDP810-500Pa differential pressure sensor
 * Bus   : I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x21
 * Log   : hvac_pressure_log.txt  (CSV: timestamp,pressure_Pa,temperature_C)
 *
 * Build : gcc -O2 -Wall -o hvac_pressure hvac_pressure.c -lpigpio -lrt
 * Run   : sudo ./hvac_pressure
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SDP810_ADDR          0x21
#define LOG_FILE             "hvac_pressure_log.txt"
#define SAMPLE_PERIOD_US     1000000   /* 1 second */
#define MEASURE_DELAY_US     50000     /* 50 ms measurement settling */

/* SDP810-500Pa command: continuous read, average until read */
#define CMD_CONT_READ        0x3608

/* CRC-8 parameters used by Sensirion SDP8xx family */
#define CRC8_POLY            0x31
#define CRC8_INIT            0xFF

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes -------------------------- */
static uint8_t  crc8(const uint8_t *data, size_t len);
static int      init_i2c(void);
static int      trigger_measurement(void);
static int      read_sensor_data(float *pressure, float *temperature);
static void     log_data(float pressure, float temperature);
static void     log_error(const char *msg);
static void     signal_handler(int sig);
static void     cleanup(void);

/* ------------------------------ CRC-8 ------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------ I2C init --------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio code %d).\n", i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------ Trigger continuous read ------------------------- */
static int trigger_measurement(void)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONT_READ >> 8) & 0xFF),
        (uint8_t)( CMD_CONT_READ        & 0xFF)
    };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (trigger) failed (pigpio code %d).\n", rc);
        return -1;
    }
    return 0;
}

/* ------------------------ Read 9-byte sensor frame ------------------------ */
static int read_sensor_data(float *pressure, float *temperature)
{
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 9).\n", rc);
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch.\n");
        return -1;
    }
    /* Scale factor CRC covers bytes 6..8; we skip validation for brevity */

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /* SDP810-500Pa conversion formulas (datasheet) */
    *pressure    = (float)raw_pressure    / 256.0f;   /* Pa */
    *temperature = (float)raw_temperature / 256.0f;   /* °C */

    return 0;
}

/* ------------------------------ Log data --------------------------------- */
static void log_data(float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(log_file);
}

/* ------------------------------ Log error -------------------------------- */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(log_file);
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error: fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HVAC Pressure Monitor started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        if (trigger_measurement() != 0) {
            log_error("trigger_measurement failed");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        float pressure, temperature;
        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            log_error("read_sensor_data failed");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

