code:
/*
 * SCD40 CO2 Sensor Data Logger for Raspberry Pi 4 Model B
 *
 * Uses pigpio for I2C communication.
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd40_logger scd40_logger.c -lpigpio -lpthread -lrt
 * Run:    sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR             0x60
#define SCD40_CMD_START_PERIODIC   0x0010
#define SCD40_CMD_STOP_PERIODIC    0x0104
#define SCD40_CMD_GET_DATA_READY   0x0202
#define SCD40_CMD_READ_MEASUREMENT 0x0300
#define SCD40_CMD_RESET            0x0006
#define SCD40_CRC8_POLYNOMIAL      0x31
#define SCD40_CRC8_INIT            0xFF

#define BUFFER_SIZE                100
#define LOG_DIR                    "/var/log/scd40_data"
#define ERROR_LOG_FILE             "/var/log/scd40_error.log"
#define CSV_FILE_PREFIX            "scd40_data_"
#define CSV_FILE_EXT               ".csv"
#define READ_INTERVAL_SEC          5
#define LOG_INTERVAL_SEC           60

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static circular_buffer_t buffer;
static pthread_t log_thread;
static int log_thread_created = 0;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t scd40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SCD40_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SCD40_CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Low-level I2C helpers ---- */
static int scd40_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_data(uint8_t *buf, size_t len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] I2C read failed (expected %zu bytes)\n", len);
        return -1;
    }
    return 0;
}

/* ---- SCD40 sensor operations ---- */
static int scd40_reset(void) {
    if (scd40_write_cmd(SCD40_CMD_RESET) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */
    return 0;
}

static int scd40_start_periodic(void) {
    return scd40_write_cmd(SCD40_CMD_START_PERIODIC);
}

static int scd40_stop_periodic(void) {
    return scd40_write_cmd(SCD40_CMD_STOP_PERIODIC);
}

static int scd40_is_data_ready(int *ready) {
    if (scd40_write_cmd(SCD40_CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    uint8_t buf[3];
    if (scd40_read_data(buf, sizeof(buf)) != 0)
        return -1;

    if (scd40_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }

    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    *ready = (word == 1);
    return 0;
}

static int scd40_read_measurement(uint16_t *co2, float *temp, float *rh) {
    if (scd40_write_cmd(SCD40_CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    uint8_t buf[9];
    if (scd40_read_data(buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (scd40_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw   = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t rh_raw  = (uint16_t)((buf[6] << 8) | buf[7]);

    *co2    = co2_raw;
    *temp   = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh     = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE)
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    else
        buf->count++;
    pthread_mutex_unlock(&buf->mutex);
}

static void buffer_flush(circular_buffer_t *buf, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for append\n", filename);
        return;
    }

    pthread_mutex_lock(&buf->mutex);
    int remaining = buf->count;
    int idx = buf->tail;

    while (remaining > 0) {
        sensor_data_t *d = &buf->data[idx];
        struct tm tm_info;
        localtime_r(&d->timestamp, &tm_info);
        char ts[24];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, d->co2, d->temperature, d->humidity);
        idx = (idx + 1) % BUFFER_SIZE;
        remaining--;
    }

    pthread_mutex_unlock(&buf->mutex);
    fclose(fp);
}

/* ---- Logging thread ---- */
static void *log_thread_fn(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (!running)
            break;

        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char filename[256];
        strftime(filename, sizeof(filename), LOG_DIR "/" CSV_FILE_PREFIX "%Y-%m-%d_%H-%M-%S" CSV_FILE_EXT, &tm_info);

        buffer_flush(&buffer, filename);
    }
    return NULL;
}

/* ---- Error logging ---- */
static void log_error(const char *msg) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for error logging\n", ERROR_LOG_FILE);
        return;
    }
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s,%s\n", ts, msg);
    fclose(fp);
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (log_thread_created) {
        pthread_join(log_thread, NULL);
        log_thread_created = 0;
    }

    /* Flush remaining data to a final CSV file */
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char filename[256];
    strftime(filename, sizeof(filename), LOG_DIR "/" CSV_FILE_PREFIX "final_%Y-%m-%d_%H-%M-%S" CSV_FILE_EXT, &tm_info);
    buffer_flush(&buffer, filename);

    if (i2c_handle >= 0) {
        scd40_stop_periodic();
        gpioDelay(10000); /* 10 ms for command to take effect */
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    pthread_mutex_destroy(&buffer.mutex);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

