/*
 * SDP810-500Pa differential pressure reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -lpigpio -lrt
 *   (pigpio must be installed and run with sudo)
 *
 * Log file: sdp810_log.txt (CSV: timestamp,pressure_Pa,temperature_C)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x21          /* SDP810 default I2C address */
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MEAS_DELAY_US  45000         /* 45 ms measurement wait */

/* SDP810 measurement command (differential pressure, no averaging) */
static const uint8_t CMD_MEASURE[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte sample from the SDP810                              */
/* ------------------------------------------------------------------ */
static bool read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Trigger a single-shot measurement */
    if (i2cWriteDevice(handle, (char *)CMD_MEASURE, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return false;
    }

    gpioDelay(MEAS_DELAY_US);   /* 45 ms conversion time */

    /* Read 9 bytes: dp_msb, dp_lsb, dp_crc, t_msb, t_lsb, t_crc, sf_msb, sf_lsb, sf_crc */
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 9)\n", n);
        return false;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return false;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return false;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] scale-factor CRC mismatch\n");
        return false;
    }

    int16_t dp_raw    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t t_raw     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t sf_raw    = (int16_t)((buf[6] << 8) | buf[7]);

    if (sf_raw == 0) {
        fprintf(stderr, "[ERROR] scale factor is zero — invalid sample\n");
        return false;
    }

    *pressure    = (float)dp_raw / (float)sf_raw;
    *temperature = (float)t_raw / 200.0f;   /* SDP810 temperature scale */
    return true;
}

/* ------------------------------------------------------------------ */
/* Log one sample                                                      */
/* ------------------------------------------------------------------ */
static bool log_sample(FILE *fp, float pressure, float temperature)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return false;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return false;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return false;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return false;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return false;
    }

    return true;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- write CSV header if file is empty -------------------------- */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_Pa,temperature_C\n");
        fflush(g_log_file);
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("SDP810 logging started. Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float pressure, temperature;

        if (read_sdp810(g_i2c_handle, &pressure, &temperature)) {
            if (!log_sample(g_log_file, pressure, temperature)) {
                fprintf(stderr, "[ERROR] logging failed — continuing\n");
            }
        } else {
            fprintf(stderr, "[ERROR] sensor read failed — continuing\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

