/*
 * Raspberry Pi 4 Model B – TDK ICP-10110 pressure sensor reader
 *
 * Wiring:
 *   ICP-10110 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10110 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10110 VDD  -> 3.3 V
 *   ICP-10110 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10110_logger icp10110_logger.c -li2c
 *
 * The ICP-10110 is a 7-bit I2C addressable sensor; the default address
 * is 0x60 (ADDR pin tied to GND).  A full production build would use
 * a configuration file or compile-time #define to let the user override
 * the address if the sensor is jumpered differently.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <i2c.h>

#define I2C_BUS            1
#define ICP10110_ADDR      0x60
#define FILENAME           "environmental_data.txt"
#define SAMPLE_INTERVAL_S  5
#define TRIGGER_DELAY_US   10000   /* 10 ms between trigger and read */

/* ICP-10110 command set (8-bit, MSB first on the bus) */
#define CMD_MEASURE_PRESSURE_TEMP  0x36
#define CMD_READ_ID_1              0xEF
#define CMD_READ_ID_2              0x01

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read the 16-bit device ID from the ICP-10110.
 * Returns 0 on success and stores the ID in *id; -1 on error.
 */
static int read_device_id(int handle, uint16_t *id)
{
    uint8_t cmd[2] = { CMD_READ_ID_1, CMD_READ_ID_2 };
    uint8_t buf[2];

    if (i2c_write(handle, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "[WARN] I2C write of ID command failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* The ICP-10110 needs a short delay after the read-ID command. */
    usleep(1000);

    if (i2c_read(handle, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[WARN] I2C read of ID data failed: %s\n",
                strerror(errno));
        return -1;
    }

    *id = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a pressure-and-temperature measurement and read the 6-byte
 * result.  Returns 0 on success and fills pressure_pa and temperature_c.
 * -1 on I2C error, -2 on invalid data length.
 */
static int read_sensor_data(int handle, float *pressure_pa, float *temperature_c)
{
    uint8_t trigger = CMD_MEASURE_PRESSURE_TEMP;
    uint8_t buf[6];

    if (i2c_write(handle, &trigger, sizeof(trigger)) != (ssize_t)sizeof(trigger)) {
        fprintf(stderr, "[WARN] I2C write of trigger command failed: %s\n",
                strerror(errno));
        return -1;
    }

    usleep(TRIGGER_DELAY_US);

    if (i2c_read(handle, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[WARN] I2C read of measurement data failed: %s\n",
                strerror(errno));
        return -1;
    }

    /*
     * ICP-10110 data format (6 bytes):
     *   buf[0] = MSB of pressure (upper 8 bits)
     *   buf[1] = LSB of pressure (lower 8 bits)
     *   buf[2] = MSB of temperature (upper 8 bits)
     *   buf[3] = LSB of temperature (lower 8 bits)
     *   buf[4] = status byte (0x00 = OK)
     *   buf[5] = CRC (not used here)
     */
    uint16_t raw_p = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_t = ((uint16_t)buf[2] << 8) | buf[3];

    /*
     * Conversion formulas per the TDK ICP-10110 datasheet.
     * Pressure is in Pa, temperature in °C.
     */
    *pressure_pa    = (float)raw_p / 2.0f;
    *temperature_c  = (float)raw_t / 256.0f - 45.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure_pa, float temperature_c)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[WARN] strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
            ts, pressure_pa, temperature_c);
    fflush(fp);
}

int main(void)
{
    int handle = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the I2C bus --- */
    handle = i2c_open(I2C_BUS);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2c_open(bus=%d) failed: %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire the sensor --- */
    if (i2c_acquire(handle, ICP10110_ADDR) != 0) {
        fprintf(stderr, "[ERROR] i2c_acquire(addr=0x%02X) failed: %s\n",
                ICP10110_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Verify the device ID --- */
    uint16_t dev_id = 0;
    if (read_device_id(handle, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding or wrong address.\n");
        goto cleanup;
    }
    printf("[INFO] ICP-10110 detected (device ID: 0x%04X)\n", dev_id);

    /* --- Open the log file --- */
    fp = fopen(FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n",
                FILENAME, strerror(errno));
        goto cleanup;
    }

    printf("[INFO] Logging to %s every %d s. Press Ctrl+C to stop.\n",
           FILENAME, SAMPLE_INTERVAL_S);

    /* --- Main sampling loop --- */
    while (g_running) {
        float pressure_pa = 0.0f;
        float temperature_c = 0.0f;

        if (read_sensor_data(handle, &pressure_pa, &temperature_c) == 0) {
            log_data(fp, pressure_pa, temperature_c);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure_pa, temperature_c);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; skipping sample.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\n[INFO] Shutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (handle >= 0) {
        i2c_release(handle);
        i2c_close(handle);
    }
    return rc;
}

