/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure sensor reader.
 *
 * Hardware:
 *   ICP-10125  I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x60.
 *   LED        GPIO17 (BCM), 330 Ω series resistor to GND.
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10125 icp10125.c -lpigpio -lrt
 * Run:    sudo ./icp10125
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define ICP_10125_ADDR   0x60
#define LED_GPIO         17
#define PRESSURE_THRESHOLD 95000.0f   /* Pa */
#define POLL_INTERVAL_S  1
#define TRIGGER_DELAY_US 20000        /* 20 ms */
#define LED_HIGH_US      500000       /* 500 ms */
#define LED_LOW_US       500000       /* 500 ms */
#define LED_FAST_HIGH_US 100000       /* 100 ms */
#define LED_FAST_LOW_US  100000       /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-4 calculation (polynomial 0x07, init 0x00, no final XOR)        */
/* ------------------------------------------------------------------ */
static uint8_t crc4(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x08)
                crc = (uint8_t)((crc << 1) ^ 0x07);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor(int fd, float *pressure, float *temperature)
{
    uint8_t data[6];

    /* Trigger a single measurement (command 0x00) */
    if (i2c_write_byte(fd, 0x00) != 0)
        return -1;

    usleep(TRIGGER_DELAY_US);

    /* Read 6 bytes: P_MSB, P_LSB, T_MSB, T_LSB, CRC_P, CRC_T */
    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* Verify CRCs */
    if (crc4(data, 2) != data[4]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc4(data + 2, 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    uint16_t p_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t t_raw = (uint16_t)((data[2] << 8) | data[3]);

    /* Conversion formulas per ICP-10125 datasheet */
    *pressure    = (float)p_raw * 100.0f;          /* Pa */
    *temperature = (float)t_raw * 100.0f - 45000.0f; /* deg C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void led_on(void)  { gpioWrite(LED_GPIO, 1); }
static void led_off(void) { gpioWrite(LED_GPIO, 0); }

static void blink_normal(void)
{
    led_on();  usleep(LED_HIGH_US);
    led_off(); usleep(LED_LOW_US);
}

static void blink_fast(void)
{
    led_on();  usleep(LED_FAST_HIGH_US);
    led_off(); usleep(LED_FAST_LOW_US);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_off();

    /* --- I2C init --------------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP_10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICP_10125_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICP-10125 monitoring started (I2C 0x%02X). Ctrl+C to exit.\n",
           ICP_10125_ADDR);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sensor(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);

            if (pressure < PRESSURE_THRESHOLD) {
                /* 5 Hz blink */
                blink_fast();
            } else {
                /* 1 Hz blink */
                blink_normal();
            }
