/*
 * Raspberry Pi Zero W – MLX90614ESF-BAA IR temperature monitor with fan control.
 *
 * Hardware:
 *   - MLX90614ESF-BAA on I2C bus 1, address 0x5A
 *     Ambient:  0x06, Object: 0x07 (16-bit big-endian, 0.02 °C / LSB)
 *   - Cooling fan on GPIO18 (BCM), active-high
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o temp_monitor temp_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for GPIO/I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MLX90614_ADDR        0x5A
#define MLX90614_REG_TA      0x06   /* Ambient temperature  */
#define MLX90614_REG_TO      0x07   /* Object  temperature */
#define FAN_GPIO             18
#define TEMP_HIGH_THRESHOLD  30.0f  /* °C – turn fan ON  */
#define TEMP_LOW_THRESHOLD   28.0f  /* °C – turn fan OFF */
#define LOG_FILE             "temperature_log.txt"
#define SAMPLE_INTERVAL_S    2      /* seconds between samples */
#define I2C_RETRIES          3
#define I2C_RETRY_DELAY_US   10000  /* 10 ms */
#define TEMP_INVALID         (-1000.0f)

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_fan_on     = false;

/* --------------------------- Function prototypes ------------------------- */
static float  read_temperature(uint8_t reg);
static void   log_temperature(float ambient, float object);
static void   control_fan(float object_temp);
static void   cleanup(void);
static void   signal_handler(int sig);

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);   /* Fan off at startup */

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, MLX90614_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started.  Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float ambient = read_temperature(MLX90614_REG_TA);
        float object  = read_temperature(MLX90614_REG_TO);

        if (ambient > TEMP_INVALID + 0.1f && object > TEMP_INVALID + 0.1f) {
            log_temperature(ambient, object);
            control_fan(object);
        } else {
            fprintf(stderr, "Warning: invalid sensor reading – skipping log.\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------ read_temperature -------------------------- */
static float read_temperature(uint8_t reg)
{
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        int raw = i2cReadWordData(g_i2c_handle, reg);
        if (raw >= 0) {
            /* MLX90614 returns 16-bit big-endian; 0x06 and 0x07 are signed. */
            int16_t signed_raw = (int16_t)((raw >> 8) | (raw << 8));
            return (float)signed_raw * 0.02f;
        }
        fprintf(stderr, "Warning: I2C read 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, I2C_RETRIES, raw);
        if (attempt < I2C_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return TEMP_INVALID;
}

/* ------------------------------ log_temperature --------------------------- */
static void log_temperature(float ambient, float object)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ambient, object);
    } else {
        fprintf(fp, "<timestamp-error>, Ambient: %.2f C, Object: %.2f C\n",
                ambient, object);
    }

    if (fclose(fp) != 0)
        perror("Warning: error closing log file");
}

/* ------------------------------ control_fan ------------------------------- */
static void control_fan(float object_temp)
{
    if (object_temp > TEMP_HIGH_THRESHOLD && !g_fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            g_fan_on = true;
            printf("Fan ON  (object %.2f C > %.1f C)\n", object_temp, TEMP_HIGH_THRESHOLD);
        } else {
            fprintf(stderr, "Error: failed to set fan GPIO high.\n");
        }
    } else if (object_temp < TEMP_LOW_THRESHOLD && g_fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            g_fan_on = false;
            printf("Fan OFF (object %.2f C < %.1f C)\n", object_temp, TEMP_LOW_THRESHOLD);
        } else {
            fprintf(stderr, "Error: failed to set fan GPIO low.\n");
        }
    }
}

/* ------------------------------- cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);   /* Ensure fan is off */
    gpioTerminate();
    printf("\nCleanup complete.\n");
}

/* --------------------------- signal_handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;   /* let main loop exit cleanly */
}

