#define SHT40_MEASURE_CMD 0xFD
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 15000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    char cmd = SHT40_MEASURE_CMD;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "Error writing measurement command (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "Error reading sensor data (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
