/*
 * TMP102 temperature logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMP102 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   TMP102 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   TMP102 VDD -> 3.3 V
 *   TMP102 GND -> GND
 *
 * The TMP102 default I2C address is 0x48 (A0=A1=A2=GND).
 * The device returns 16-bit data in two consecutive bytes on read.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp102_log tmp102_log.c -lpigpio -lrt
 * Run:    sudo ./tmp102_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

#define I2C_BUS        1
#define TMP102_ADDR    0x48
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define TMP102_CONV_MS 10         /* conversion time (ms) */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a heap-allocated timestamp string "YYYY-MM-DD HH:MM:SS".     */
static char *get_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return NULL;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return NULL;
    }

    char *buf = malloc(20);
    if (buf == NULL) {
        perror("malloc()");
        return NULL;
    }

    if (strftime(buf, 20, "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        free(buf);
        return NULL;
    }
    return buf;
}

/* ------------------------------------------------------------------ */
/* Read temperature from TMP102.                                       */
/* Returns 0 on success and stores Celsius in *out_temp.               */
/* Returns -1 on I2C or conversion error.                              */
static int read_temperature(int i2c_handle, float *out_temp)
{
    /*
     * TMP102 is a 16-bit ADC.  A read of two bytes returns the most
     * recent conversion result.  The device updates its register every
     * ~10 ms; a brief delay is required before the first conversion is
     * valid.
     */
    gpioDelay(TMP102_CONV_MS * 1000);   /* pigpio microsecond delay */

    char buf[2];
    int  bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed (returned %d): %s\n",
                bytes, strerror(errno));
        return -1;
    }

    /*
     * TMP102 data format (16-bit, big-endian):
     *   D15..D11 = reserved (0)
     *   D10     = sign bit (1 = negative, 0 = positive)
     *   D9..D0  = 9-bit temperature code (two's complement)
     *
     * Resolution: 0.0625 °C per LSB.
     */
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint16_t)(uint8_t)buf[1]);

    /* Arithmetic right-shift preserves sign for negative temperatures. */
    int16_t temp_code = raw >> 7;

    *out_temp = (float)temp_code * 0.0625f;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_temperature(const char *timestamp, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at TMP102 address 0x48 ---- */
    int i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, TMP102_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP102 logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            char *ts = get_timestamp();
            if (ts != NULL) {
                if (log_temperature(ts, temperature) == 0) {
                    printf("%s  %.2f °C\n", ts, temperature);
                } else {
                    fprintf(stderr, "Failed to log temperature.\n");
                }
                free(ts);
            } else {
                fprintf(stderr, "Failed to generate timestamp.\n");
            }
        } else {
            fprintf(stderr, "Skipping sample due to read failure.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100 * 1000);   /* 100 ms */
        }
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (i2cClose(i2c_handle) != 0) {
        perror("i2cClose()");
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

