#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HDC2010 constants (TI datasheet) ------------------------------------ */
#define HDC2010_ADDR             0x40          /* default 7-bit I2C address   */
#define REG_TEMP_LOW             0x00          /* TEMP_LOW  (LSB first)       */
#define REG_TEMP_HIGH            0x01          /* TEMP_HIGH                  */
#define REG_HUM_LOW              0x02          /* HUM_LOW   (LSB first)       */
#define REG_HUM_HIGH             0x03          /* HUM_HIGH                   */
#define REG_MEAS_CFG             0x0E          /* MEASUREMENT_CONFIG         */
#define REG_INT_CFG              0x0F          /* INTERRUPT_CONFIG           */
#define REG_MANUFACTURER_ID      0xFC          /* MANUFACTURER_ID            */
#define REG_DEVICE_ID            0xFE          /* DEVICE_ID                  */

#define EXPECTED_MANUFACTURER_ID 0x5449       /* 'TI'                       */
#define EXPECTED_DEVICE_ID       0x2010       /* HDC2010                    */

/* MEASUREMENT_CONFIG bit fields */
#define MEAS_CFG_MODE_MASK       0x03          /* mode bits                  */
#define MEAS_CFG_MODE_TEMP       0x00          /* temperature only           */
#define MEAS_CFG_MODE_HUM        0x01          /* humidity only              */
#define MEAS_CFG_MODE_BOTH       0x02          /* both                       */
#define MEAS_CFG_MEAS_TRIG       0x01          /* bit 0 = start measurement  */

/* ---- Application constants ---------------------------------------------- */
#define I2C_BUS                  1
#define POLL_TIMEOUT_MS          500           /* max wait for measurement    */
#define SAMPLE_INTERVAL_S        5             /* seconds between samples     */
#define MAX_RETRIES              3             /* retries per I2C op          */

/* ---- Globals ------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ----------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---------------------------------------------- */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on failure.
 */
static int hdc_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(1000); /* 1 ms back-off */
    }
    return -1;
}

/*
 * Read a single byte from a register.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int hdc_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadByteData(reg=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(1000);
    }
    return -1;
}

/*
 * Read a 16-bit little-endian register pair.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int hdc_read_reg16(int handle, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (hdc_read_reg(handle, reg_low, &lo) != 0)
        return -1;
    if (hdc_read_reg(handle, reg_low + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ---- Sensor detection --------------------------------------------------- */
static int hdc_detect(int handle)
{
    uint8_t mfr_id, dev_id;
    if (hdc_read_reg(handle, REG_MANUFACTURER_ID, &mfr_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read MANUFACTURER_ID – sensor absent or bus error.\n");
        return -1;
    }
    if ((mfr_id & 0xFF) != (EXPECTED_MANUFACTURER_ID & 0xFF)) {
        fprintf(stderr, "[ERROR] Manufacturer ID mismatch: got 0x%02X, expected 0x%02X.\n",
                mfr_id, EXPECTED_MANUFACTURER_ID & 0xFF);
        return -1;
    }
    if (hdc_read_reg(handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID – sensor absent or bus error.\n");
        return -1;
    }
    if ((dev_id & 0xFF) != (EXPECTED_DEVICE_ID & 0xFF)) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X.\n",
                dev_id, EXPECTED_DEVICE_ID & 0xFF);
        return -1;
    }
    printf("[INFO] HDC2010 detected (MANUFACTURER_ID=0x%02X, DEVICE_ID=0x%02X).\n",
           mfr_id, dev_id);
    return 0;
}

/* ---- Trigger a measurement and wait for completion ----------------------- */
static int hdc_trigger_and_wait(int handle)
{
    /* Start a both-temperature-and-humidity measurement */
    if (hdc_write_reg(handle, REG_MEAS_CFG, MEAS_CFG_MODE_BOTH | MEAS_CFG_MEAS_TRIG) != 0) {
        fprintf(stderr, "[ERROR] Failed to trigger measurement.\n");
        return -1;
    }

    /* Poll MEASUREMENT_CONFIG bit 0 until it clears (measurement done) */
    uint8_t cfg;
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 5) {
        if (hdc_read_reg(handle, REG_MEAS_CFG, &cfg) != 0) {
            fprintf(stderr, "[ERROR] Failed to poll MEASUREMENT_CONFIG.\n");
            return -1;
        }
        if ((cfg & MEAS_CFG_MEAS_TRIG) == 0)
            return 0;
        gpioDelay(5000); /* 5 ms */
    }
    fprintf(stderr, "[ERROR] Measurement timeout (%d ms).\n", POLL_TIMEOUT_MS);
    return -1;
}

/* ---- Read temperature (°C) and humidity (%RH) ---------------------------- */
static int hdc_read_th(int handle, float *temp_c, float *hum_pct)
{
    if (hdc_trigger_and_wait(handle) != 0)
        return -1;

    uint16_t raw_t, raw_h;
    if (hdc_read_reg16(handle, REG_TEMP_LOW, &raw_t) != 0) {
        fprintf(stderr, "[ERROR] Failed to read temperature registers.\n");
        return -1;
    }
    if (hdc_read_reg16(handle, REG_HUM_LOW, &raw_h) != 0) {
        fprintf(stderr, "[ERROR] Failed to read humidity registers.\n");
        return -1;
    }

    /* HDC2010 conversion formulas (datasheet) */
    *temp_c = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *hum_pct = ((float)raw_h / 65536.0f) * 100.0f;

    /* Clamp humidity to a physically realistic range */
    if (*hum_pct < 0.0f)   *hum_pct = 0.0f;
    if (*hum_pct > 100.0f) *hum_pct = 100.0f;

    return 0;
}

/* ---- Cleanup ------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at HDC2010 address */
    g_i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d).\n",
                I2C_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Detect the sensor */
    if (hdc_detect(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] HDC2010 not detected – check wiring and address.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging temperature and humidity every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_INTERVAL_S);

    /* Main sampling loop */
    while (g_running) {
        float temp_c, hum_pct;
        if (hdc_read_th(g_i2c_handle, &temp_c, &hum_pct) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", temp_c, hum_pct);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed – will retry next cycle.\n");
        }
        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; ++i)
            gpioDelay(100000);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

