#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define SAMPLE_PERIOD  500000          /* microseconds (500 ms) */
#define MEASURE_DELAY  45000           /* microseconds (45 ms)  */
#define MAX_RETRIES    3

/* SDP800-500Pa continuous measurement command (MSB first) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x1E };

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * CRC-8 used by Sensirion: polynomial 0x31, init 0xFF, no reflection.
 */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[6];
    int rc;

    /* Send continuous measurement command */
    rc = i2cWriteDevice(handle, (char *)CMD_CONT_MEAS, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed: %d\n", rc);
        return -1;
    }

    /* Wait for measurement to complete */
    gpioDelay(MEASURE_DELAY);

    /* Read 6 bytes: pressure(2) + CRC + temperature(2) + CRC */
    rc = i2cReadDevice(handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 6)\n", rc);
        return -1;
    }

    /* Validate CRCs */
    if (!crc8_check(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void)
{
    int handle = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x25 */
    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed: %d\n", handle);
        goto cleanup_gpio;
    }

    printf("SDP800-500Pa reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, I2C_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t pressure = 0, temperature = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sdp800(handle, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (ok) {
            printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed after %d attempts; "
                            "continuing.\n", MAX_RETRIES);
        }

        /* Sleep 500 ms; pigpioDelay is interruptible by signals */
        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

    if (handle >= 0)
        i2cClose(handle);

cleanup_gpio:
    gpioTerminate();
    return ret;
}

