/*
 * PID-controlled reflow oven for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX6675 thermocouple amplifier on SPI0 (CE0 / GPIO8)
 *   - Solid-state relay driver on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o reflow_oven reflow_oven.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM on GPIO17).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                       */
#define SPI_SPEED        1000000    /* 1 MHz                                  */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                  */

#define SSR_GPIO         17         /* BCM 17 - solid-state relay driver      */
#define PWM_FREQUENCY    1000       /* 1 kHz PWM frequency                     */
#define PWM_RANGE        1000       /* Duty-cycle range (0-1000)              */

#define LOG_FILE         "reflow_log.csv"
#define PROFILE_FILE     "profile.txt"

#define SAMPLE_PERIOD_US 1000000    /* 1 second between samples               */
#define LOOP_DELAY_US    10000      /* 10 ms loop delay                        */

/* PID gains (Kp, Ki, Kd) */
static const float Kp = 2.0f;
static const float Ki = 0.1f;
static const float Kd = 0.01f;

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  initialize(void);
static void cleanup(void);
static int  read_temperature(float *temp_celsius);
static float pid_control(float setpoint, float actual,
                          float *integral, float *prev_error);
static void log_data(float temperature, float setpoint, float duty_cycle);
static int  load_profile(const char *filename, float *target_temp, float *time_sec);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ Initialization ---------------------------- */

static int initialize(void)
{
    /* --- pigpio ----------------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* --- SSR GPIO --------------------------------------------------------- */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", SSR_GPIO);
        return -1;
    }
    if (gpioPWM(SSR_GPIO, 0) < 0) {                 /* start with SSR off    */
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n", SSR_GPIO);
        return -1;
    }

    /* --- SPI -------------------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, %d Hz).\n",
                SPI_CHANNEL, SPI_SPEED);
        return -1;
    }

    /* --- Log file --------------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error: cannot open log file");
        return -1;
    }
    fprintf(g_log_file, "timestamp,temperature_c,setpoint_c,duty_cycle\n");
    fflush(g_log_file);

    return 0;
}

/* -------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure SSR is off before terminating pigpio */
    gpioPWM(SSR_GPIO, 0);
    gpioTerminate();
}

/* --------------------------- MAX6675 temperature -------------------------- */

/*
 * MAX6675 32-bit SPI frame (Mode 0, MSB first):
 *   D[31:18] : thermocouple temperature (14-bit, 0.25 °C / count)
 *   D[17]    : reserved
 *   D[16]    : valid flag (1 = data valid)
 *   D[15:4]  : internal cold-junction temp (12-bit)
 *   D[3]     : reserved
 *   D[2]     : SCV fault (short to VCC)
 *   D[1]     : SCG fault (short to GND)
 *   D[0]     : OC  fault (open circuit)
 *
 * Returns 0 on success, -1 on SPI error, -2 on sensor-absent / fault.
 */
static int read_temperature(float *temp_celsius)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(g_spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d).\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Valid bit (D16) must be set */
    if ((raw & 0x00010000) == 0) {
        fprintf(stderr, "Error: MAX6675 data not valid (raw=0x%08X).\n", raw);
        return -2;
    }

    /* Fault bits (D2, D1, D0) */
    if (raw & 0x00000007) {
        if (raw & 0x00000001)
            fprintf(stderr, "Warning: MAX6675 open circuit fault.\n");
        if (raw & 0x00000002)
            fprintf(stderr, "Warning: MAX6675 short to GND fault.\n");
        if (raw & 0x00000004)
            fprintf(stderr, "Warning: MAX6675 short to VCC fault.\n");
        return -2;
    }

    /* Thermocouple temperature: bits 31:18 (14-bit signed, 0.25 °C / count) */
    int16_t thermocouple_raw = (int16_t)(raw >> 18);          /* sign-extends */
    *temp_celsius = thermocouple_raw * 0.25f;
    return 0;
}

/* --------------------------------- PID ----------------------------------- */

static float pid_control(float setpoint, float actual,
                          float *integral, float *prev_error)
{
    float error = setpoint - actual;

    *integral += error;
    /* Anti-windup clamp */
    if (*integral > 1.0f)  *integral = 1.0f;
    if (*integral < 0.0f)  *integral = 0.0f;

    float derivative = error - *prev_error;
    *prev_error = error;

    float output = Kp * error + Ki * (*integral) + Kd * derivative;

    /* Clamp output to [0, 1] */
    if (output < 0.0f)  output = 0.0f;
    if (output > 1.0f)  output = 1.0f;
    return output;
}

/* -------------------------------- Logging --------------------------------- */

static void log_data(float temperature, float setpoint, float duty_cycle)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%.2f,%.4f\n", ts, temperature, setpoint, duty_cycle);
    fflush(g_log_file);
}

/* ----------------------------- Profile load ------------------------------- */

static int load_profile(const char *filename, float *target_temp, float *time_sec)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error: cannot open profile file");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error: profile file is empty.\n");
        fclose(fp);
        return -1;
    }

    /* Parse first line: time_seconds,target_temp_celsius */
    char *endptr = NULL;
    char *tok = strtok(line, ",");
    if (!tok) {
        fprintf(stderr, "Error: invalid profile format (missing time).\n");
        fclose(fp);
        return -1;
    }
    *time_sec = strtof(tok, &endptr);
    if (endptr == tok) {
        fprintf(stderr, "Error: invalid time value in profile.\n");
        fclose(fp);
        return -1;
    }

    tok = strtok(NULL, ",");
    if (!tok) {
        fprintf(stderr, "Error: invalid profile format (missing temperature).\n");
        fclose(fp);
        return -1;
    }
    *target_temp = strtof(tok, &endptr);
    if (endptr == tok) {
        fprintf(stderr, "Error: invalid temperature value in profile.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction failed");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    float target_temp = 0.0f;
    float time_sec    = 0.0f;

    if (load_profile(PROFILE_FILE, &target_temp, &time_sec) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Reflow oven started. Target: %.2f C for %.0f s.\n",
           target_temp, time_sec);
    printf("Press Ctrl+C to exit.\n");

    float integral    = 0.0f;
    float prev_error  = 0.0f;
    time_t start_time = time(NULL);

    while (g_running) {
        float temperature = 0.0f;
        int rc = read_temperature(&temperature);

        if (rc == 0) {
            float duty_cycle = pid_control(target_temp, temperature,
                                            &integral, &prev_error);

            int pwm_value = (int)(duty_cycle * PWM_RANGE);
            if (pwm_value < 0)   pwm_value = 0;
            if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

            if (gpioPWM(SSR_GPIO, pwm_value) < 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n", SSR_GPIO);
            }

            log_data(temperature, target_temp, duty_cycle);
            printf("Temp: %.2f C | Setpoint: %.2f C | Duty: %.2f%%\n",
                   temperature, target_temp, duty_cycle * 100.0f);
        } else if (rc == -2) {
            /* Sensor fault: turn off SSR for safety */
            gpioPWM(SSR_GPIO, 0);
        } else {
            /* SPI bus error: turn off SSR and wait briefly */
            gpioPWM(SSR_GPIO, 0);
            gpioDelay(100000);   /* 100 ms back-off */
            continue;
        }

        /* Check if target time has elapsed */
        if (time(NULL) - start_time >= (time_t)time_sec) {
            printf("Target time reached. Turning off SSR.\n");
            gpioPWM(SSR_GPIO, 0);
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

