#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/file.h>
#include <linux/pwm.h>
#include <linux/fs.h>
#include <sys/ioctl.h>
#include <stdint.h>

#define DS18B20_DIR "/sys/bus/w1/devices/"
#define DS18B20_ID "28-00000430338b"
#define DS18B20_FILE DS18B20_DIR DS18B20_ID "/w1_slave"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 1000000000ULL
#define LOG_FILE "greenhouse.log"
#define LOG_INTERVAL 5
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int pwm_fd = -1;
static int pwm_exported = 0;
static int pwm_enabled = 0;
static int pwm_period_set = 0;
static int pwm_duty_set = 0;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_sys(const char *path, const char *val) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    ssize_t n = write(fd, val, strlen(val));
    close(fd);
    return (n < 0) ? -1 : 0;
}

static int read_sys(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    ssize_t n = read(fd, buf, len - 1);
    close(fd);
    if (n < 0) return -1;
    buf[n] = '\0';
    return 0;
}

static int init_pwm(void) {
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/export");
    if (write_sys(path, "0") < 0 && errno != EBUSY) {
        fprintf(stderr, "PWM export failed: %s\n", strerror(errno));
        return -1;
    }
    pwm_exported = 1;
    usleep(100000);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    if (write_sys(path, "1000000000") < 0) {
        fprintf(stderr, "PWM period set failed: %s\n", strerror(errno));
        return -1;
    }
    pwm_period_set = 1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    if (write_sys(path, "0") < 0) {
        fprintf(stderr, "PWM duty set failed: %s\n", strerror(errno));
        return -1;
    }
    pwm_duty_set = 1;
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    if (write_sys(path, "1") < 0) {
        fprintf(stderr, "PWM enable failed: %s\n", strerror(errno));
        return -1;
    }
    pwm_enabled = 1;
    return 0;
}

static void cleanup_pwm(void) {
    if (pwm_enabled) write_sys("/sys/class/pwm/pwmchip0/pwm0/enable", "0");
    if (pwm_duty_set) write_sys("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "0");
    if (pwm_period_set) write_sys("/sys/class/pwm/pwmchip0/pwm0/period", "1000000000");
    if (pwm_exported) write_sys("/sys/class/pwm/pwmchip0/unexport", "0");
}

static int init_gpio(void) {
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    if (write_sys(path, "17") < 0 && errno != EBUSY) {
        fprintf(stderr, "GPIO17 export failed: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio17/direction");
    if (write_sys(path, "out") < 0) {
        fprintf(stderr, "GPIO17 direction failed: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio17/value");
    if (write_sys(path, "0") < 0) {
        fprintf(stderr, "GPIO17 off failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    write_sys("/sys/class/gpio/gpio17/value", "0");
    write_sys("/sys/class/gpio/unexport", "17");
}

static int read_temperature(float *temp) {
    char buf[256];
    if (read_sys(DS18B20_FILE, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "DS18B20 read failed: %s\n", strerror(errno));
        return -1;
    }
    if (strstr(buf, "YES") == NULL) {
        fprintf(stderr, "DS18B20 CRC check failed\n");
        return -1;
    }
    char *t = strstr(buf, "t=");
    if (!t) {
        fprintf(stderr, "DS18B20 temperature parse failed\n");
        return -1;
    }
    long raw = strtol(t + 2, NULL, 10);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static void set_pwm_duty(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    unsigned long long duty_ns = (PWM_PERIOD_NS * (unsigned long long)duty_percent) / 100ULL;
    char val[32];
    snprintf(val, sizeof(val), "%llu", duty_ns);
    write_sys("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", val);
}

static void set_relay(int on) {
    char val = on ? '1' : '0';
    write_sys("/sys/class/gpio/gpio17/value", &val);
}

static void log_data(float avg_temp, float setpoint, float pid_out, int duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s,%.2f,%.2f,%.2f,%d\n", ts, avg_temp, setpoint, pid_out, duty);
    fflush(log_fp);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }
    float setpoint = atof(argv[1]);
    float Kp = atof(argv[2]);
    float Ki = atof(argv[3]);
    float Kd = atof(argv[4]);
    float integral = 0.0f;
    float prev_error = 0.0f;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Log open failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        fclose(log_fp);
        return 1;
    }
    if (init_pwm() < 0) {
        cleanup_gpio();
        fclose(log_fp);
        return 1;
    }

    while (running) {
        float temp;
        if (read_temperature(&temp) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        float error = setpoint - temp;
        integral += error;
        float deriv = error - prev_error;
        float pid_out = Kp * error + Ki * integral + Kd * deriv;
        prev_error = error;

        int duty = (int)(pid_out * 100.0f);
        if (duty < 0) duty = 0;
        if (duty > 100) duty = 100;
        set_pwm_duty(duty);

        int relay_on = (duty > 0) ? 1 : 0;
        set_relay(relay_on);

        log_data(temp, setpoint, pid_out, duty);
        sleep(SAMPLE_INTERVAL);
    }

    set_relay(0);
    set_pwm_duty(0);
    cleanup_pwm();
    cleanup_gpio();
    if (log_fp) fclose(log_fp);
    return 0;
}

