/*
 * Raspberry Pi 5 - AHT20 Humidity Monitor with Dehumidifier Relay
 *
 * Hardware:
 *   - AHT20 sensor on /dev/i2c-1, address 0x38
 *   - Dehumidifier relay on GPIO17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o aht20_dehumidifier aht20_dehumidifier.c \
 *       -lgpiod -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define AHT20_ADDR       0x38
#define DEHUMIDIFIER_PIN 17
#define HUMIDITY_HIGH    60.0f
#define HUMIDITY_LOW     55.0f
#define POLL_INTERVAL_S  5
#define MEASURE_DELAY_MS 80
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Trigger a measurement and read the 6-byte result from the AHT20.
 * Returns 0 on success, -1 on failure.
 */
static int aht20_read(int fd, float *humidity)
{
    uint8_t cmd = 0xAC;
    uint8_t buf[6];
    int retries = MAX_RETRIES;

    while (retries-- > 0) {
        /* Send measurement command (0xAC, nocrc, nocrc) */
        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            sleep_ms(RETRY_DELAY_MS);
            continue;
        }

        sleep_ms(MEASURE_DELAY_MS);

        ssize_t n = read(fd, buf, sizeof(buf));
        if (n != (ssize_t)sizeof(buf)) {
            fprintf(stderr, "I2C read failed: expected 6 bytes, got %zd (%s)\n",
                    n, n < 0 ? strerror(errno) : "short read");
            sleep_ms(RETRY_DELAY_MS);
            continue;
        }

        /* Status byte: bit 7 = busy, bit 6 = calibrated */
        if ((buf[0] & 0xC0) != 0x00) {
            fprintf(stderr, "AHT20 status invalid: 0x%02X (busy or uncalibrated)\n", buf[0]);
            sleep_ms(RETRY_DELAY_MS);
            continue;
        }

        uint32_t raw = ((uint32_t)buf[1] << 12) |
                       ((uint32_t)buf[2] << 4)  |
                       ((uint32_t)buf[3] >> 4);
        *humidity = (float)raw / 1024.0f;
        return 0;
    }

    return -1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay = NULL;
    int i2c_fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {
        .sa_handler = sig_handler,
        .sa_flags   = 0
    };
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and get the relay line */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    relay = gpiod_chip_get_line(chip, DEHUMIDIFIER_PIN);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DEHUMIDIFIER_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay, "aht20_dehumidifier", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                DEHUMIDIFIER_PIN, strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("AHT20 dehumidifier monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float humidity = 0.0f;

        if (aht20_read(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("[%s] Humidity: %.2f%%%s\n", ts, humidity,
                   humidity > HUMIDITY_HIGH ? "  -> Dehumidifier ON" :
                   humidity < HUMIDITY_LOW  ? "  -> Dehumidifier OFF" : "");

            int target = (humidity > HUMIDITY_HIGH) ? 1 :
                         (humidity < HUMIDITY_LOW)  ? 0 : -1;

            if (target != -1) {
                if (gpiod_line_set_value(relay, target) < 0) {
                    fprintf(stderr, "Failed to set relay: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Failed to read humidity after %d retries.\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++) {
            sleep_ms(100);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (relay) {
        gpiod_line_set_value(relay, 0);
        gpiod_line_release(relay);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);

