#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <netdb.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_CMD_TEMP_HOLD 0xE3
#define HTU21D_CMD_HUMID_HOLD 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sensor(int fd, uint8_t cmd, uint16_t *raw) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed for command 0x%02X: %s", cmd, strerror(errno));
        return -1;
    }
    usleep(50000);
    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        syslog(LOG_ERR, "I2C read failed for command 0x%02X: got %zd bytes, errno: %s", cmd, n, strerror(errno));
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "CRC mismatch for command 0x%02X", cmd);
        return -1;
    }
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return -46.85 + 175.72 * ((float)raw / 65536.0);
}

static float convert_humidity(uint16_t raw) {
    float h = -6.0 + 125.0 * ((float)raw / 65536.0);
    if (h < 0.0) h = 0.0;
    if (h > 100.0) h = 100.0;
    return h;
}

static int post_data(const char *json) {
    struct addrinfo hints, *res = NULL, *rp;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo("api.example.com", "80", &hints, &res) != 0) {
        syslog(LOG_ERR, "getaddrinfo failed");
        return -1;
    }
    int sock = -1;
    for (rp = res; rp != NULL; rp = rp->ai_next) {
        sock = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (sock < 0) continue;
        if (connect(sock, rp->ai_addr, rp->ai_addrlen) == 0) break;
        close(sock);
        sock = -1;
    }
    freeaddrinfo(res);
    if (sock < 0) {
        syslog(LOG_ERR, "Failed to connect to API endpoint");
        return -1;
    }
    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST /humidity HTTP/1.1\r\n"
        "Host: api.example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s", strlen(json), json);
    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request buffer overflow");
        close(sock);
        return -1;
    }
    if (write(sock, request, req_len) != req_len) {
        syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
        close(sock);
        return -1;
    }
    char resp[1024];
    ssize_t r = read(sock, resp, sizeof(resp) - 1);
    if (r > 0) {
        resp[r] = '\0';
        syslog(LOG_INFO, "API response: %s", resp);
    }
    close(sock);
    return 0;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "HTU21D monitor started on %s", I2C_BUS);
    while (running) {
        uint16_t raw_t, raw_h;
        if (read_sensor(fd, HTU21D_CMD_TEMP_HOLD, &raw_t) != 0 ||
            read_sensor(fd, HTU21D_CMD_HUMID_HOLD, &raw_h) != 0) {
            syslog(LOG_ERR, "Sensor read failed, retrying in %d seconds", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }
        float temp = convert_temperature(raw_t);
        float hum = convert_humidity(raw_h);
        char json[256];
        snprintf(json, sizeof(json),
            "{\"temperature\":%.2f,\"humidity\":%.2f}", temp, hum);
        if (post_data(json) != 0) {
            syslog(LOG_ERR, "Failed to post data");
        }
        sleep(POLL_INTERVAL);
    }
    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

