/*
 * BMP280 Pressure Monitor for Raspberry Pi 4 Model B
 *
 * Monitors a Bosch BMP280 sensor on I2C-1 (address 0x76), compensates
 * the raw data using the Bosch datasheet formulas, and logs readings
 * outside the range [980.0, 1020.0] hPa to pressure_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_monitor bmp280_monitor.c -lm
 * Run:    ./bmp280_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- BMP280 constants (from datasheet) ---- */
#define BMP280_I2C_ADDR        0x76
#define BMP280_CHIP_ID_ADDR    0xD0
#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_ADDR      0xE0
#define BMP280_RESET_CMD       0xB6
#define BMP280_CTRL_MEAS_ADDR  0xF4
#define BMP280_CONFIG_ADDR     0xF5
#define BMP280_DATA_ADDR       0xF7
#define BMP280_CALIB_ADDR      0x88
#define BMP280_CALIB_LEN       24

#define BMP280_OVERSAMPLING_TEMP  1
#define BMP280_OVERSAMPLING_PRESS 1
#define BMP280_MODE_NORMAL        3
#define BMP280_T_SB_1000MS        5

#define LOG_FILE "pressure_log.txt"
#define MIN_PRESSURE 980.0
#define MAX_PRESSURE 1020.0
#define SAMPLE_INTERVAL_US 2000000  /* 2 s */
#define CONVERSION_DELAY_US 10000   /* 10 ms */
#define MAX_RETRIES 3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Calibration coefficients ---- */
static uint16_t dig_T1;
static int16_t  dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t  dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t  t_fine;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at `reg` into `buf`.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to `reg`.                                            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian calibration word.                       */
/* ------------------------------------------------------------------ */
static int read_calib_word(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_block(handle, reg, buf, 2) < 0)
        return -1;
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian signed calibration word.                */
/* ------------------------------------------------------------------ */
static int read_calib_s16(int handle, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_block(handle, reg, buf, 2) < 0)
        return -1;
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and verify the chip ID.                                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int verify_chip_id(int handle)
{
    uint8_t id;
    if (i2c_read_block(handle, BMP280_CHIP_ID_ADDR, &id, 1) < 0)
        return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, BMP280_CHIP_ID);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and apply the calibration coefficients.                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_calibration(int handle)
{
    if (read_calib_word(handle, 0x88, &dig_T1) < 0) return -1;
    if (read_calib_s16(handle, 0x8A, &dig_T2)   < 0) return -1;
    if (read_calib_s16(handle, 0x8C, &dig_T3)   < 0) return -1;
    if (read_calib_word(handle, 0x8E, &dig_P1)  < 0) return -1;
    if (read_calib_s16(handle, 0x90, &dig_P2)   < 0) return -1;
    if (read_calib_s16(handle, 0x92, &dig_P3)   < 0) return -1;
    if (read_calib_s16(handle, 0x94, &dig_P4)   < 0) return -1;
    if (read_calib_s16(handle, 0x96, &dig_P5)   < 0) return -1;
