    if (read_calib_s16(handle, 0x9C, &dig_P8)   < 0) return -1;
    if (read_calib_s16(handle, 0x9E, &dig_P9)   < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Bosch compensation: temperature in 0.01 °C units.                   */
/* ------------------------------------------------------------------ */
static int32_t compensate_temperature(int32_t adc_T)
{
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12) *
