    return p;  /* Pa */
}

/* ------------------------------------------------------------------ */
/* Read pressure in hPa.  Returns 0 on success, -1 on error.           */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure_out)
{
    uint8_t data[6];
    int32_t raw_T, raw_P;

    /* Trigger a normal-mode measurement */
    if (i2c_write_byte(handle, BMP280_CTRL_MEAS_ADDR,
                       (BMP280_OVERSAMPLING_TEMP << 5) |
                       (BMP280_OVERSAMPLING_PRESS << 2) |
                       BMP280_MODE_NORMAL) < 0)
