/* Attempt to recover the sensor after an I2C error.                   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int recover_sensor(int *handle)
{
    if (*handle >= 0) {
        i2cClose(*handle);
