/*
 * Raspberry Pi 4B – TMP117 (temp), AHT20 (humidity), PIR (motion) logger.
 *
 * Wiring:
 *   TMP117  SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD 3V3, GND
 *   AHT20   SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD 3V3, GND
 *   PIR     OUT -> GPIO17 (pin 11), VDD 3V3, GND
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x3B
#define PIR_CHIP       "gpiochip4"
#define PIR_OFFSET     17
#define LOG_DIR        "."
#define SAMPLE_SEC     1
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- I2C helpers ---------- */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * TMP117: 16-bit big-endian, 0x00 = temperature MSB, 0x01 = LSB.
 * Resolution 0.01 °C per LSB.
 */
static int tmp117_read(int fd, float *temp)
{
    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "TMP117 write reg: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "TMP117 read: got %zd bytes (%s)\n", n, strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw * 0.01f;
    return 0;
}

/*
 * AHT20: start measurement with 0xAC (bit 7=1, bit 5=1, bit 4=0, bits 3-0=0010).
 * Wait 80 ms, then read 7 bytes starting at 0x00.
 *   humidity(8)(msb), humidity(8)(lsb), humidity(2)(status), temp(8)(msb),
 *   temp(8)(lsb), temp(2)(status), reserved.
 * Resolution: humidity ~0.01 %RH, temp ~0.01 °C.
 */
static int aht20_read(int fd, float *hum, float *temp)
{
    uint8_t cmd = 0xAC;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "AHT20 trigger: %s\n", strerror(errno));
        return -1;
    }
    usleep(80000);

    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "AHT20 write reg: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[7];
    ssize_t n = read(fd, buf, 7);
    if (n != 7) {
        fprintf(stderr, "AHT20 read: got %zd bytes (%s)\n", n, strerror(errno));
        return -1;
    }
    if ((buf[0] & 0x80) == 0) {
        fprintf(stderr, "AHT20 not ready (status=0x%02X)\n", buf[0]);
        return -1;
    }
    uint32_t h_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    uint32_t t_raw = ((uint32_t)(buf[3] & 0x0F) << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    *hum = (float)h_raw / 1048576.0f * 100.0f;
    *temp = (float)t_raw / 1048576.0f * 200.0f - 50.0f;
    return 0;
}

