/*
 * Rain-activated window closer for Raspberry Pi 5.
 *
 * Hardware:
 *   - YL-83 rain sensor  -> GPIO17 (active-low: 0 = rain detected)
 *   - L298N motor driver -> ENA=GPIO22, IN1=GPIO23, IN2=GPIO24
 *
 * Behavior:
 *   Polls GPIO17 every 2 s.  When rain is detected (line reads 0),
 *   drives the motor forward for 5 s, then stops the motor.
 *   All events are logged with timestamps to stdout.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_ENA_PIN    22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_SEC  2
#define MOTOR_RUN_SEC      5

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    time_t now = time(NULL);
    char ts[32];
    struct tm tmv;

    if (localtime_r(&now, &tmv) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_set(struct gpiod_line *ena, struct gpiod_line *in1,
                     struct gpiod_line *in2, int e, int i1, int i2)
{
    if (gpiod_line_set_value(ena, e) < 0) {
        perror("gpiod_line_set_value(ENA)");
        return -1;
    }
    if (gpiod_line_set_value(in1, i1) < 0) {
        perror("gpiod_line_set_value(IN1)");
        return -1;
    }
    if (gpiod_line_set_value(in2, i2) < 0) {
        perror("gpiod_line_set_value(IN2)");
        return -1;
    }
    return 0;
}

static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                      struct gpiod_line *in2)
{
    return motor_set(ena, in1, in2, 0, 0, 0);
}

static int motor_forward(struct gpiod_line *ena, struct gpiod_line *in1,
                         struct gpiod_line *in2)
{
    return motor_set(ena, in1, in2, 1, 1, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *rain,
                    struct gpiod_line *ena,
                    struct gpiod_line *in1,
                    struct gpiod_line *in2)
{
    if (in2) gpiod_line_release(in2);
    if (in1) gpiod_line_release(in1);
    if (ena) gpiod_line_release(ena);
    if (rain) gpiod_line_release(rain);
    if (chip) gpiod_chip_close(chip);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *motor_ena = NULL;
    struct gpiod_line *motor_in1 = NULL;
    struct gpiod_line *motor_in2 = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    /* Open the default gpiochip (gpiochip4 on Pi 5). */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto out;
    }

    /* Get lines. */
    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    motor_ena = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    motor_in1 = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    motor_in2 = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain_line || !motor_ena || !motor_in1 || !motor_in2) {
        perror("gpiod_chip_get_line");
        goto out;
    }

    /* Request rain sensor line as input. */
    if (gpiod_line_request_input(rain_line, "rain_window") < 0) {
        perror("gpiod_line_request_input(rain)");
        goto out;
    }

    /* Request motor lines as output, initial value LOW. */
    if (gpiod_line_request_output(motor_ena, "rain_window", 0) < 0) {
        perror("gpiod_line_request_output(ENA)");
        goto out;
    }
    if (gpiod_line_request_output(motor_in1, "rain_window", 0) < 0) {
        perror("gpiod_line_request_output(IN1)");
        goto out;
    }
    if (gpiod_line_request_output(motor_in2, "rain_window", 0) < 0) {
        perror("gpiod_line_request_output(IN2)");
        goto out;
    }

    log_event("Rain sensor monitoring started.");

    while (g_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            perror("gpiod_line_get_value(rain)");
            log_event("Error reading rain sensor.");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (val == 0) {
            log_event("Rain detected! Closing window.");

            if (motor_forward(motor_ena, motor_in1, motor_in2) != 0) {
                log_event("Error starting motor.");
            } else {
                log_event("Motor running forward.");

                /* Sleep in 1-second increments so we can respond to signals. */
                for (int i = 0; i < MOTOR_RUN_SEC && g_running; i++)
                    sleep(1);

                if (motor_stop(motor_ena, motor_in1, motor_in2) != 0)
                    log_event("Error stopping motor.");
                else
                    log_event("Motor stopped.");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_event("Shutting down.");
    rc = EXIT_SUCCESS;

out:
    /* Ensure motor is stopped on every exit path. */
    if (motor_ena && motor_in1 && motor_in2)
        (void)motor_stop(motor_ena, motor_in1, motor_in2);
    cleanup(chip, rain_line, motor_ena, motor_in1, motor_in2);
    return rc;
}

