#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_cpu_stats(unsigned long long *user,
                          unsigned long long *nice,
                          unsigned long long *system,
                          unsigned long long *idle,
                          unsigned long long *iowait,
                          unsigned long long *irq,
                          unsigned long long *softirq,
                          unsigned long long *steal,
                          unsigned long long *guest,
                          unsigned long long *guest_nice) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("fopen(\"/proc/stat\")");
        return -1;
    }

    char line[256];
    int found = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strncmp(line, "cpu ", 4) == 0) {
            if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                       user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice) == 10) {
                found = 1;
                break;
            }
        }
    }
    fclose(fp);

    if (!found) {
        fprintf(stderr, "Error: Could not find 'cpu' line in /proc/stat\n");
        return -1;
    }
    return 0;
}

static float calculate_cpu_usage(const unsigned long long *prev,
                                  const unsigned long long *curr) {
    unsigned long long prev_idle = prev[3] + prev[4];
    unsigned long long curr_idle = curr[3] + curr[4];

    unsigned long long prev_non_idle = prev[0] + prev[1] + prev[2] + prev[5] + prev[6] + prev[7] + prev[8] + prev[9];
    unsigned long long curr_non_idle = curr[0] + curr[1] + curr[2] + curr[5] + curr[6] + curr[7] + curr[8] + curr[9];

    unsigned long long prev_total = prev_idle + prev_non_idle;
    unsigned long long curr_total = curr_idle + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled  = curr_idle - prev_idle;

    if (totald == 0) {
        return 0.0f;
    }

    return (float)(totald - idled) / (float)totald;
}

static void set_led_color(int red, int green, int blue) {
    if (red < 0)   red   = 0;
    if (red > 255) red   = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue < 0)  blue  = 0;
    if (blue > 255) blue  = 255;

    if (gpioPWM(RED_PIN,   red)   != 0) fprintf(stderr, "Warning: gpioPWM(RED) failed\n");
    if (gpioPWM(GREEN_PIN, green) != 0) fprintf(stderr, "Warning: gpioPWM(GREEN) failed\n");
    if (gpioPWM(BLUE_PIN,  blue)  != 0) fprintf(stderr, "Warning: gpioPWM(BLUE) failed\n");
}

static void map_cpu_usage_to_color(float cpu_usage, int *red, int *green, int *blue) {
    if (cpu_usage < 0.0f) cpu_usage = 0.0f;
    if (cpu_usage > 1.0f) cpu_usage = 1.0f;

    if (cpu_usage < 0.5f) {
        *red   = (int)(cpu_usage * 255.0f);
        *green = 255;
        *blue  = 0;
    } else {
        *red   = 255;
        *green = (int)((1.0f - cpu_usage) * 255.0f);
        *blue  = 0;
    }
}

static void cleanup_gpio(void) {
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
    gpioTerminate();
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(RED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(GREEN_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BLUE_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned long long prev_cpu[10], curr_cpu[10];

    if (read_cpu_stats(&prev_cpu[0], &prev_cpu[1], &prev_cpu[2], &prev_cpu[3],
                       &prev_cpu[4], &prev_cpu[5], &prev_cpu[6], &prev_cpu[7],
                       &prev_cpu[8], &prev_cpu[9]) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000L};

    while (g_running) {
        if (read_cpu_stats(&curr_cpu[0], &curr_cpu[1], &curr_cpu[2], &curr_cpu[3],
                           &curr_cpu[4], &curr_cpu[5], &curr_cpu[6], &curr_cpu[7],
                           &curr_cpu[8], &curr_cpu[9]) != 0) {
            fprintf(stderr, "Error reading CPU stats, retrying...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        float cpu_usage = calculate_cpu_usage(prev_cpu, curr_cpu);

        int red, green, blue;
        map_cpu_usage_to_color(cpu_usage, &red, &green, &blue);
        set_led_color(red, green, blue);

        memcpy(prev_cpu, curr_cpu, sizeof(prev_cpu));
        nanosleep(&sleep_time, NULL);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

