/*
 * BMP280 I2C temperature/pressure reader → UDP JSON transmitter
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C-1  (SDA = GPIO2 / pin 3, SCL = GPIO3 / pin 5)
 * Sensor: Bosch BMP280 (I2C address 0x76, alt 0x77)
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_udp bmp280_udp.c -lpigpio -lrt
 * Run:    sudo ./bmp280_udp
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define BMP280_ADDR        0x76          /* SA0 tied to GND on Pi 4 */
#define UDP_SERVER_IP      "192.168.1.100"
#define UDP_SERVER_PORT    5000
#define SAMPLE_INTERVAL_S  5             /* seconds between samples */
#define MEAS_DELAY_US      10000         /* 10 ms worst-case conversion */

/* BMP280 registers */
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB       0x88        /* 24-byte calibration block */

#define BMP280_CHIP_ID        0x58
#define BMP280_RESET_CMD      0xB6

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_udp_socket = -1;
static uint8_t  g_calib[24];

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  bmp280_read_calibration(void);
static int  bmp280_init(void);
static int  bmp280_read(float *temp, float *press);
static int  udp_send(const char *json);
static void cleanup(void);

/* ------------------------------ Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Read calibration block ---------------------- */
static int bmp280_read_calibration(void)
{
    if (i2cReadI2CBlockData(g_i2c_handle, BMP280_REG_CALIB,
                           (char *)g_calib, sizeof(g_calib)) != (int)sizeof(g_calib)) {
        fprintf(stderr, "[ERROR] Failed to read 24-byte calibration block: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------ BMP280 init ------------------------------ */
static int bmp280_init(void)
{
    int id = i2cReadByteData(g_i2c_handle, BMP280_REG_ID);
    if (id < 0) {
        fprintf(stderr, "[ERROR] I2C read of chip ID failed: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "[ERROR] Unexpected chip ID 0x%02X (expected 0x%02X) — "
                        "sensor absent or wrong device\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "[ERROR] BMP280 reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);                       /* 2 ms reset settling */

    /* config: t_sb=500ms (0x08<<5), filter=off (0x00<<2), spi3w_en=0 */
    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_CONFIG, 0x08) < 0) {
        fprintf(stderr, "[ERROR] Config write failed: %s\n", strerror(errno));
        return -1;
    }

    /* ctrl_meas: osrs_t=x1 (0x01<<5), osrs_p=x1 (0x01<<2), mode=normal (0x03) */
    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "[ERROR] Ctrl_meas write failed: %s\n", strerror(errno));
        return -1;
    }

    if (bmp280_read_calibration() < 0)
        return -1;

    return 0;
}

/* --------------------------- Read temperature/pressure -------------------- */
static int bmp280_read(float *temp, float *press)
{
    uint8_t data[6];
    int32_t raw_p, raw_t;
    int32_t var1, var2, t_fine;
    uint32_t var_p;

    if (i2cReadI2CBlockData(g_i2c_handle, BMP280_REG_PRESS_MSB,
                           (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] Failed to read pressure/temp data: %s\n",
                strerror(errno));
        return -1;
    }

    raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);

    /* Temperature compensation (BMP280 datasheet, 32-bit integer variant) */
    var1 = ((((raw_t >> 3) - ((int32_t)g_calib[1] << 1)))
            * ((int32_t)g_calib[0])) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)g_calib[1]))
              * ((raw_t >> 4) - ((int32_t)g_calib[1]))) >> 12)
            * ((int32_t)g_calib[2])) >> 14;
    t_fine = var1 + var2;
    *temp  = (float)((t_fine * 5 + 128) >> 8) / 100.0f;

    /* Pressure compensation (BMP280 datasheet, 32-bit integer variant) */
    var1 = ((int32_t)t_fine) - 128000;
    var2 = var1 * var1 * (int32_t)g_calib[6];
    var2 = var2 + ((var1 * (int32_t)g_calib[5]) << 17);
    var2 = var2 + (((int32_t)g_calib[4]) << 35);
    var1 = ((var1 * var1 * (int32_t)g_calib[3]) >> 8)
         + ((var1 * (int32_t)g_calib[2]) << 12);
    var1 = (((((int32_t)1) << 47) + var1)) * ((int32_t)g_calib[1]) >> 33;

    if (var1 == 0) {
        *press = 0.0f;                     /* avoid division by zero */
    } else {
        var_p = 1048576 - raw_p;
        var_p = (((var_p << 31) - var2) * 3125) / var1;
        var1  = (((int32_t)g_calib[10] * (var_p >> 13) * (var_p >> 13)) >> 25);
        var2  = (((int32_t)g_calib[11] * var_p) >> 19);
        var_p = (var_p + var1 + var2) >> 8;
        var_p = (var_p + (((int32_t)g_calib[12]) << 4));
        *press = (float)(var_p / 256.0f);
    }

    return 0;
}

/* ------------------------------ UDP send --------------------------------- */
static int udp_send(const char *json)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &addr.sin_addr) != 1) {
        fprintf(stderr, "[ERROR] Invalid UDP address %s\n", UDP_SERVER_IP);
        return -1;
    }

    if (sendto(g_udp_socket, json, strlen(json), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "[ERROR] UDP sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

