#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define BMP280_ADDR        0x76          /* SA0 tied to GND on Pi 4 */
#define UDP_SERVER_IP      "192.168.1.100"
#define UDP_SERVER_PORT    5000
#define SAMPLE_INTERVAL_S  5             /* seconds between samples */
#define MEAS_DELAY_US      10000         /* 10 ms worst-case conversion */

/* BMP280 registers */
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB       0x88        /* 24-byte calibration block */

#define BMP280_CHIP_ID        0x58
#define BMP280_RESET_CMD      0xB6

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_udp_socket = -1;
static uint8_t  g_calib[24];

