static void cleanup(void);

/* ------------------------------ Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Read calibration block ---------------------- */
static int bmp280_read_calibration(void)
{
    if (i2cReadI2CBlockData(g_i2c_handle, BMP280_REG_CALIB,
                           (char *)g_calib, sizeof(g_calib)) != (int)sizeof(g_calib)) {
        fprintf(stderr, "[ERROR] Failed to read 24-byte calibration block: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------ BMP280 init ------------------------------ */
static int bmp280_init(void)
{
    int id = i2cReadByteData(g_i2c_handle, BMP280_REG_ID);
    if (id < 0) {
        fprintf(stderr, "[ERROR] I2C read of chip ID failed: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "[ERROR] Unexpected chip ID 0x%02X (expected 0x%02X) — "
                        "sensor absent or wrong device\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "[ERROR] BMP280 reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);                       /* 2 ms reset settling */

    /* config: t_sb=500ms (0x08<<5), filter=off (0x00<<2), spi3w_en=0 */
    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_CONFIG, 0x08) < 0) {
        fprintf(stderr, "[ERROR] Config write failed: %s\n", strerror(errno));
        return -1;
    }

    /* ctrl_meas: osrs_t=x1 (0x01<<5), osrs_p=x1 (0x01<<2), mode=normal (0x03) */
    if (i2cWriteByteData(g_i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "[ERROR] Ctrl_meas write failed: %s\n", strerror(errno));
        return -1;
    }

    if (bmp280_read_calibration() < 0)
        return -1;

    return 0;
}

/* --------------------------- Read temperature/pressure -------------------- */
static int bmp280_read(float *temp, float *press)
{
    uint8_t data[6];
    int32_t raw_p, raw_t;
    int32_t var1, var2, t_fine;
    uint32_t var_p;

    if (i2cReadI2CBlockData(g_i2c_handle, BMP280_REG_PRESS_MSB,
                           (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] Failed to read pressure/temp data: %s\n",
                strerror(errno));
        return -1;
    }

    raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);

    /* Temperature compensation (BMP280 datasheet, 32-bit integer variant) */
    var1 = ((((raw_t >> 3) - ((int32_t)g_calib[1] << 1)))
            * ((int32_t)g_calib[0])) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)g_calib[1]))
              * ((raw_t >> 4) - ((int32_t)g_calib[1]))) >> 12)
            * ((int32_t)g_calib[2])) >> 14;
    t_fine = var1 + var2;
    *temp  = (float)((t_fine * 5 + 128) >> 8) / 100.0f;

