    var1 = ((int32_t)t_fine) - 128000;
    var2 = var1 * var1 * (int32_t)g_calib[6];
    var2 = var2 + ((var1 * (int32_t)g_calib[5]) << 17);
    var2 = var2 + (((int32_t)g_calib[4]) << 35);
