/*
 * fan_control.c — Raspberry Pi 4 Model B
 *
 * Reads a MAX31855 thermocouple amplifier on SPI0 (CE0 / GPIO8),
 * drives a cooling fan on GPIO18 (hardware PWM, 1 kHz), and logs
 * temperature, timestamp, and PWM duty cycle to a 20-entry circular
 * buffer.  SIGINT stops PWM, prints the buffer, and exits cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_control fan_control.c -lpigpio -lrt
 * Run:    sudo ./fan_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0  (GPIO8)  */
#define SPI_SPEED      500000     /* 500 kHz, mode 0   */
#define FAN_GPIO       18         /* hardware PWM pin   */
#define PWM_FREQ       1000       /* 1 kHz                */
#define PWM_RANGE      255        /* duty 0..255         */
#define BUFFER_SIZE    20
#define SAMPLE_PERIOD  1          /* seconds between reads */

/* ------------------------------- Types ----------------------------------- */
typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} LogEntry;

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static LogEntry g_log_buffer[BUFFER_SIZE];
static int      g_log_index   = 0;
static int      g_log_count   = 0;

/* --------------------------- Forward declarations ------------------------ */
static int  read_max31855(int handle, float *temp_c);
static int  compute_duty(float temp_c);
static void log_data(float temp_c, int duty);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MAX31855 -------------------------------- */
/*
 * MAX31855 32-bit SPI payload (MSB first):
 *   D[31:18]  14-bit thermocouple temperature, 0.25 °C / count
 *   D[17]     reserved
 *   D[16]     fault bit (1 = fault)
 *   D[15:4]   12-bit internal cold-junction temperature, 0.0625 °C / count
 *   D[3]      reserved
 *   D[2]      SCV fault (short to VCC)
 *   D[1]      SCG fault (short to GND)
 *   D[0]      OC  fault (open circuit)
 *
 * Returns 0 on success and stores the thermocouple temperature in °C.
 */
static int read_max31855(int handle, float *temp_c)
{
    char rx[4] = {0, 0, 0, 0};
    int  ret;

    ret = spiRead(handle, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "[MAX31855] spiRead returned %d (expected 4)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {                       /* fault bit set */
        fprintf(stderr, "[MAX31855] fault detected (raw=0x%08X)\n", raw);
        if (raw & 0x00000004) fprintf(stderr, "  Short to VCC\n");
        if (raw & 0x00000002) fprintf(stderr, "  Short to GND\n");
        if (raw & 0x00000001) fprintf(stderr, "  Open circuit\n");
        return -1;
    }

    /* 14-bit signed thermocouple temperature */
    int16_t t = (int16_t)(raw >> 18);             /* sign-extends */
    *temp_c = (float)t * 0.25f;
    return 0;
}

/* ------------------------------- Fan curve ------------------------------- */
static int compute_duty(float temp_c)
{
    if (temp_c < 25.0f) return 0;
    if (temp_c < 40.0f) return (int)((temp_c - 25.0f) * 0.5f);   /* 0..50   */
    if (temp_c < 60.0f) return (int)((temp_c - 40.0f) * 2.0f);   /* 50..200 */
    return PWM_RANGE;                                            /* 200+   */
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(float temp_c, int duty)
{
    g_log_buffer[g_log_index].timestamp  = time(NULL);
    g_log_buffer[g_log_index].temperature = temp_c;
    g_log_buffer[g_log_index].duty_cycle  = duty;

    g_log_index = (g_log_index + 1) % BUFFER_SIZE;
    if (g_log_count < BUFFER_SIZE) g_log_count++;
}

/* ------------------------------- Signal / cleanup ------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); /* mode 0 */
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Fan PWM setup --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(%d) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "gpioPWM initial off failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Fan control started.  SPI0 CE0 -> MAX31855, PWM @ GPIO18.\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float temp_c;

        if (read_max31855(g_spi_handle, &temp_c) != 0) {
            fprintf(stderr, "MAX31855 read error — skipping fan update.\n");
        } else {
            int duty = compute_duty(temp_c);
            if (gpioPWM(FAN_GPIO, duty) < 0) {
                fprintf(stderr, "gpioPWM(%d) failed\n", duty);
            } else {
                log_data(temp_c, duty);
                printf("T=%.2f C  PWM=%d/%d\n", temp_c, duty, PWM_RANGE);
            }
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);

    printf("Log buffer contents (%d entries):\n", g_log_count);
    for (int i = 0; i < g_log_count; i++) {
        int idx = (g_log_index - g_log_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tmv;
        localtime_r(&g_log_buffer[idx].timestamp, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("  [%d] %s  T=%.2f C  PWM=%d/%d\n",
               i, ts, g_log_buffer[idx].temperature,
               g_log_buffer[idx].duty_cycle, PWM_RANGE);
    }

    cleanup();
    return EXIT_SUCCESS;
}

