/*
 * MAX31865 RTD Temperature Logger for Raspberry Pi 5
 *
 * Wiring:
 *   MAX31865 VDD  -> 3.3V (Pin 1)
 *   MAX31865 GND  -> GND  (Pin 6)
 *   MAX31865 SCLK -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MAX31865 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MAX31865 DO   -> GPIO9  (SPI0 MISO, Pin 21)
 *   MAX31865 CLK  -> GPIO10 (SPI0 MOSI, Pin 19)  (unused in 3-wire mode)
 *   MAX31865 VSH  -> 5V (external voltage supply for RTD)
 *   MAX31865 VREF -> 5V (external voltage supply for RTD)
 *   MAX31865 RT   -> RTD resistive load (e.g., 430 ohm)
 *
 * Build: gcc -O2 -Wall -o rtd_logger rtd_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define LOG_FILE        "rtd_log.csv"
#define SAMPLE_INTERVAL 5

/* MAX31865 Register Addresses */
#define MAX31865_CONFIG_WR   0x00
#define MAX31865_RTD_MSB_WR  0x01
#define MAX31865_RTD_LSB_WR  0x02
#define MAX31865_HFAULT_WR   0x03
#define MAX31865_LFAULT_WR   0x04
#define MAX31865_FAULT_STATUS 0x05

/*
 * MAX31865 Configuration Register (0x00)
 * Bits: [7:6] Mode, [5:4] Vbias, [3:2] Fault Polarity, [1:0] Open/Short
 * Mode 00 = 3-wire RTD, Vbias = 50uA, Fault Polarity = Active Low,
 * Open/Short = 16mA
 */
#define MAX31865_CONFIG_VALUE 0x00

/*
 * RTD Calibration Coefficients (Callendar-Van Dusen)
 * R0 = 100.0 ohms, a = 0.0039083
 */
#define R0_RTD 100.0
#define A_RTD  0.0039083

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int max31865_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};
    return spi_transfer(fd, tx, rx, 2);
}

static int max31865_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

static int max31865_init(int fd) {
    if (max31865_write_reg(fd, MAX31865_CONFIG_WR, MAX31865_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Failed to configure MAX31865\n");
        return -1;
    }
    usleep(10000); /* Wait for Vbias to stabilize */
    return 0;
}

static int read_rtd_temperature(int fd, float *temperature) {
    uint8_t rtd_msb = 0, rtd_lsb = 0, fault_status = 0;

    if (max31865_read_reg(fd, MAX31865_RTD_MSB_WR, &rtd_msb) < 0) {
        return -1;
    }
    if (max31865_read_reg(fd, MAX31865_RTD_LSB_WR, &rtd_lsb) < 0) {
        return -1;
    }
    if (max31865_read_reg(fd, MAX31865_FAULT_STATUS, &fault_status) < 0) {
        return -1;
    }

    if (fault_status & 0x01) {
        fprintf(stderr, "MAX31865 Fault: Open circuit\n");
        return -1;
    }
    if (fault_status & 0x02) {
        fprintf(stderr, "MAX31865 Fault: Short to GND\n");
        return -1;
    }
    if (fault_status & 0x04) {
        fprintf(stderr, "MAX31865 Fault: Short to VCC\n");
        return -1;
    }

    uint16_t rtd_raw = ((uint16_t)rtd_msb << 8) | rtd_lsb;
    rtd_raw >>= 1; /* Remove fault bit */

    if (rtd_raw == 0) {
        fprintf(stderr, "RTD raw value is zero, sensor absent or wiring fault\n");
        return -1;
    }

    float rtd_resistance = (float)rtd_raw * R0_RTD / 32768.0;
    float temperature_celsius = (rtd_resistance - R0_RTD) / (R0_RTD * A_RTD);

    *temperature = temperature_celsius;
    return 0;
}

static void log_data(FILE *fp, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    if (max31865_init(g_spi_fd) < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        close(g_spi_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_spi_fd);
        return 1;
    }

    fprintf(g_log_fp, "# MAX31865 RTD Logger started\n");
    fflush(g_log_fp);

    printf("MAX31865 RTD Logger started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 0.0;

        if (read_rtd_temperature(g_spi_fd, &temperature) == 0) {
            log_data(g_log_fp, temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read RTD temperature\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
    }

    printf("Cleanup complete.\n");
    return 0;
}

