/*
 * BME280 I2C reader for Raspberry Pi Zero W
 * Bus: /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * Address: 0x76 (SDO tied to GND) or 0x77 (SDO tied to VDDIO)
 * Logs to bme280_log.csv every 5 s.
 *
 * Build: gcc -O2 -Wall -Wextra -o bme280_logger bme280_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR_0 0x76
#define BME280_I2C_ADDR_1 0x77
#define BME280_CHIP_ID    0x60
#define I2C_BUS          "/dev/i2c-1"
#define LOG_FILE         "bme280_log.csv"
#define SAMPLE_PERIOD_S  5

/* BME280 register addresses */
#define BME280_REG_ID        0xD0
#define BME280_REG_RESET     0xE0
#define BME280_REG_CTRL_HUM  0xF2
#define BME280_REG_STATUS    0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG    0xF5
#define BME280_REG_DATA      0xF7
#define BME280_REG_CALIB     0x88

/* Calibration coefficients */
typedef struct {
    uint16_t dig_T1; int16_t dig_T2, dig_T3;
    uint16_t dig_P1; int16_t dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    uint8_t  dig_H1, dig_H3; int8_t dig_H6;
    int16_t  dig_H2, dig_H4, dig_H5;
} bme280_calib_t;

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

/* ---- BME280 helpers ---- */

static int bme280_read_calib(int fd, bme280_calib_t *c) {
    uint8_t t1[2], t2[2], t3[1];
    uint8_t p1[2], p2[2], p3[2], p4[2], p5[2], p6[2], p7[2], p8[2], p9[2];
    uint8_t h1[1], h2[2], h3[1], h4[2], h5[2], h6[1];

    if (i2c_read_block(fd, 0x88, t1, 2) || i2c_read_block(fd, 0x8A, t2, 2) ||
        i2c_read_block(fd, 0x8C, t3, 1)) return -1;
    c->dig_T1 = (uint16_t)(t1[0] | (t1[1] << 8));
    c->dig_T2 = (int16_t)(t2[0] | (t2[1] << 8));
    c->dig_T3 = (int16_t)(t3[0] | (t3[1] << 8));

    if (i2c_read_block(fd, 0x8E, p1, 2) || i2c_read_block(fd, 0x90, p2, 2) ||
        i2c_read_block(fd, 0x92, p3, 2) || i2c_read_block(fd, 0x94, p4, 2) ||
        i2c_read_block(fd, 0x96, p5, 2) || i2c_read_block(fd, 0x98, p6, 2) ||
        i2c_read_block(fd, 0x9A, p7, 2) || i2c_read_block(fd, 0x9C, p8, 2) ||
        i2c_read_block(fd, 0x9E, p9, 2)) return -1;
    c->dig_P1 = (uint16_t)(p1[0] | (p1[1] << 8));
    c->dig_P2 = (int16_t)(p2[0] | (p2[1] << 8));
    c->dig_P3 = (int16_t)(p3[0] | (p3[1] << 8));
    c->dig_P4 = (int16_t)(p4[0] | (p4[1] << 8));
    c->dig_P5 = (int16_t)(p5[0] | (p5[1] << 8));
    c->dig_P6 = (int16_t)(p6[0] | (p6[1] << 8));
    c->dig_P7 = (int16_t)(p7[0] | (p7[1] << 8));
    c->dig_P8 = (int16_t)(p8[0] | (p8[1] << 8));
    c->dig_P9 = (int16_t)(p9[0] | (p9[1] << 8));

    if (i2c_read_block(fd, 0xA1, h1, 1) || i2c_read_block(fd, 0xE1, h2, 2) ||
        i2c_read_block(fd, 0xE3, h3, 1) || i2c_read_block(fd, 0xE4, h4, 2) ||
        i2c_read_block(fd, 0xE6, h5, 2) || i2c_read_block(fd, 0xE8, h6, 1)) return -1;
    c->dig_H1 = h1[0];
    c->dig_H2 = (int16_t)(h2[0] | (h2[1] << 8));
    c->dig_H3 = h3[0];
    c->dig_H4 = (int16_t)(((int16_t)h4[0] << 4) | (h4[1] & 0x0F));
    c->dig_H5 = (int16_t)(((int16_t)h5[0] << 4) | (h5[1] >> 4));
    c->dig_H6 = (int8_t)h6[0];
    return 0;
}

static int bme280_init(int fd, bme280_calib_t *c) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id)) {
        fprintf(stderr, "Error: cannot read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID 0x%02X != expected 0x%02X (not a BME280)\n", id, BME280_CHIP_ID);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6)) {
        fprintf(stderr, "Error: soft reset write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    /* Wait for NVM calibration to be loaded (status bit 0 = im_update) */
    uint8_t status;
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status)) return -1;
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (status & 0x01) {
        fprintf(stderr, "Warning: calibration not ready (status=0x%02X)\n", status);
    }

    if (bme280_read_calib(fd, c)) {
        fprintf(stderr, "Error: failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }

    /* Humidity oversampling x1, standby 1000ms, filter off */
    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01)) return -1;
    /* Temp/Press oversampling x1, normal mode */
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27)) return -1;
    /* Standby 1000ms, IIR filter off */
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0)) return -1;

    return 0;
}

static int bme280_read(int fd, const bme280_calib_t *c, float *temp, float *hum, float *press) {
    uint8_t d[8];
    if (i2c_read_block(fd, BME280_REG_DATA, d, 8)) {
        fprintf(stderr, "Error: data read failed: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_p = (d[0] << 12) | (d[1] << 4) | (d[2] >> 4);
    int32_t raw_t = (d[3] << 12) | (d[4] << 4) | (d[5] >> 4);
    int32_t raw_h = (d[6] << 8) | d[7];

    /* Temperature compensation (datasheet 4.6.3) */
