/*
 * BMP180 Pressure Monitor with Alert System
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (I2C + GPIO)
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (I2C1 SDA)
 *   BMP180 SCL -> GPIO3 (I2C1 SCL)
 *   BMP180 VCC -> 3.3 V
 *   BMP180 GND -> GND
 *   Alert LED/indicator on GPIO24 (with appropriate series resistor)
 *
 * Build:  gcc -O2 -Wall -o bmp180_monitor bmp180_monitor.c -lpigpio -lrt
 * Run:    sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BMP180_ADDR          0x77          /* AD0 tied to GND on most BMP180 variants */
#define ALERT_GPIO           24
#define SAMPLE_INTERVAL_US   50000         /* 50 ms */
#define BUFFER_SIZE          (60 * 1000 / 50)  /* 60 s at 50 ms */
#define PRESSURE_THRESHOLD   5.0           /* hPa */
#define ALERT_DURATION_S     5             /* seconds */

/* BMP180 registers */
#define BMP180_REG_CONTROL   0xF4
#define BMP180_REG_MSB       0xF6
#define BMP180_REG_LSB       0xF7
#define BMP180_REG_XLSB      0xF8

#define BMP180_CMD_TEMP      0x2E
#define BMP180_CMD_PRESSURE  0x34          /* OSS = 0 */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Circular buffer for pressure readings (hPa) with timestamps */
typedef struct {
    time_t timestamp;
    float  pressure;
} PressureReading;

static PressureReading g_buffer[BUFFER_SIZE];
static int g_head = 0;   /* next write slot */
static int g_count = 0;  /* number of valid entries */

/* --------------------------- Function prototypes ------------------------- */
static int  bmp180_read_calibration(int handle, int32_t cal[11]);
static int  bmp180_read_raw_temp(int handle, int32_t *raw);
static int  bmp180_read_raw_pressure(int handle, int32_t *raw);
static float bmp180_calc_pressure(int32_t ut, int32_t up, const int32_t cal[11]);
static void buffer_add(time_t ts, float pressure);
static float buffer_rolling_average(time_t now);
static void alert_set(bool on);
static void timer_callback(void *userdata);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Calibration ----------------------------- */
static int bmp180_read_calibration(int handle, int32_t cal[11])
{
    uint8_t reg = 0xAA;
    uint8_t buf[22];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to select calibration register 0xAA\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, 22) != 22) {
        fprintf(stderr, "[ERROR] Failed to read 22-byte calibration block\n");
        return -1;
    }

    cal[0]  = (int16_t)((buf[0]  << 8) | buf[1]);
    cal[1]  = (int16_t)((buf[2]  << 8) | buf[3]);
    cal[2]  = (int16_t)((buf[4]  << 8) | buf[5]);
    cal[3]  = (int16_t)((buf[6]  << 8) | buf[7]);
    cal[4]  = (int16_t)((buf[8]  << 8) | buf[9]);
    cal[5]  = (int16_t)((buf[10] << 8) | buf[11]);
    cal[6]  = (int16_t)((buf[12] << 8) | buf[13]);
    cal[7]  = (int16_t)((buf[14] << 8) | buf[15]);
    cal[8]  = (int16_t)((buf[16] << 8) | buf[17]);
    cal[9]  = (int16_t)((buf[18] << 8) | buf[19]);
    cal[10] = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

/* --------------------------- Raw sensor reads ---------------------------- */
static int bmp180_read_raw_temp(int handle, int32_t *raw)
{
    uint8_t cmd[2] = { BMP180_REG_CONTROL, BMP180_CMD_TEMP };
    uint8_t buf[2];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to request temperature conversion\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    cmd[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(handle, (char *)cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to set temperature MSB pointer\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] Failed to read temperature MSB/LSB\n");
        return -1;
    }

    *raw = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp180_read_raw_pressure(int handle, int32_t *raw)
{
    uint8_t cmd[2] = { BMP180_REG_CONTROL, BMP180_CMD_PRESSURE };
    uint8_t buf[3];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to request pressure conversion\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms for OSS = 0 */

    cmd[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(handle, (char *)cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to set pressure MSB pointer\n");
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "[ERROR] Failed to read pressure MSB/LSB/XLSB\n");
        return -1;
    }

    *raw = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> 8;
    return 0;
}

/* --------------------------- Pressure calculation ------------------------ */
static float bmp180_calc_pressure(int32_t ut, int32_t up, const int32_t cal[11])
{
    int32_t x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    /* True temperature */
    x1 = ((ut - (int32_t)cal[5]) * (int32_t)cal[4]) >> 15;
    x2 = ((int32_t)cal[2] * ((ut - (int32_t)cal[5]) * (int32_t)cal[2] >> 11)) >> 11;
    b5 = x1 + x2 + 32768;

    /* Pressure */
    b6 = b5 - 4000;
    x1 = ((int32_t)cal[6] * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal[7] * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)cal[8] * 4) + x3) << 0) + 2) >> 2;

    x1 = ((int32_t)cal[9] * ((b6 * b6) >> 12)) >> 16;
    x2 = ((int32_t)cal[10] * b6) >> 15;
    x3 = ((x1 + x2 + 32768) >> 15);
    b4 = ((uint32_t)cal[0] * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)(up - b3) * (50000 >> 0));

    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p / 100.0f;  /* Pa -> hPa */
}

/* --------------------------- Circular buffer ----------------------------- */
static void buffer_add(time_t ts, float pressure)
{
    g_buffer[g_head].timestamp = ts;
    g_buffer[g_head].pressure  = pressure;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE)
        g_count++;
}

static float buffer_rolling_average(time_t now)
{
    if (g_count == 0)
        return 0.0f;

    float sum = 0.0f;
    int count = 0;

    for (int i = 0; i < g_count; i++) {
        int idx = (g_head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        if (now - g_buffer[idx].timestamp > 60)
            break;
        sum += g_buffer[idx].pressure;
        count++;
    }
    return (count > 0) ? (sum / count) : 0.0f;
}

/* ------------------------------- Alert ----------------------------------- */
static void alert_set(bool on)
{
    if (gpioWrite(ALERT_GPIO, on ? 1 : 0) != 0)
        fprintf(stderr, "[WARN] Failed to write GPIO %d\n", ALERT_GPIO);
}

/* --------------------------- Timer callback ------------------------------ */
static void timer_callback(void *userdata)
{
    (void)userdata;

    time_t now = time(NULL);
    int32_t cal[11];
    int32_t ut, up;
    float pressure;

    if (bmp180_read_calibration(g_i2c_handle, cal) != 0) {
        fprintf(stderr, "[ERROR] Calibration read failed; will retry next cycle\n");
        return;
    }

    if (bmp180_read_raw_temp(g_i2c_handle, &ut) != 0) {
        fprintf(stderr, "[ERROR] Temperature read failed\n");
        return;
    }
    if (bmp180_read_raw_pressure(g_i2c_handle, &up) != 0) {
        fprintf(stderr, "[ERROR] Pressure read failed\n");
        return;
    }

    pressure = bmp180_calc_pressure(ut, up, cal);
    buffer_add(now, pressure);

    float avg = buffer_rolling_average(now);
    if (avg > 0.0f && fabsf(pressure - avg) > PRESSURE_THRESHOLD) {
        alert_set(true);
        fprintf(stderr, "[ALERT] Pressure %.2f hPa exceeds average %.2f hPa by %.2f hPa\n",
                pressure, avg, fabsf(pressure - avg));
        sleep(ALERT_DURATION_S);
        alert_set(false);
    }
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioSetMode(ALERT_GPIO, PI_INPUT);
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) — sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    alert_set(false);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; Ctrl+C will not clean up\n");
    }

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US / 1000, timer_callback, NULL) != 0) {
        fprintf(stderr, "[FATAL] gpioSetTimerFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Sampling every 50 ms. Press Ctrl+C to exit.\n");

    while (g_running)
        gpioDelay(100000);  /* 100 ms sleep */

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

