#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define OSS 0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    cal.ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal.ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal.ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal.ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal.ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal.ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal.b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal.b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal.mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal.mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal.md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int32_t *ut) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

static double calculate_temperature(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temp(&ut) != 0) {
        fprintf(stderr, "Error: Failed to read raw temperature\n");
        return;
    }
    if (read_raw_pressure(&up) != 0) {
        fprintf(stderr, "Error: Failed to read raw pressure\n");
        return;
    }
    double temp = calculate_temperature(ut);
    double pres = calculate_pressure(up, ut);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, pres);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("bmp180_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 logging started. Press Ctrl+C to stop.\n");
    while (running) {
        gpioDelay(100000);
    }
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("BMP180 logging stopped.\n");
    return 0;
}

