#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define SLEEP_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp_out) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp_raw;
    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp_out = (float)temp_raw / 1000.0f;
    return 0;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature <= MIN_TEMP) return 0;
    if (temperature >= MAX_TEMP) return PWM_RANGE;
    return (int)(((temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * PWM_RANGE);
}

static int log_data(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", SLEEP_INTERVAL);
            sleep(SLEEP_INTERVAL);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        gpioPWM(FAN_GPIO, duty_cycle);

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
        sleep(SLEEP_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

