/*
 * BMP280 weather logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP280 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   BMP280 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   BMP280 VDD -> 3.3 V (pin 1)
 *   BMP280 GND -> GND  (pin 6)
 *   SDO tied to GND -> default address 0x76
 *   SDO tied to 3.3 V -> alternative address 0x77
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c
 * Run:    ./bmp280_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- BMP280 constants (datasheet rev 1.26) ---- */
#define BMP280_ADDR_DEFAULT  0x76
#define BMP280_ADDR_ALT      0x77

#define BMP280_REG_ID        0xD0
#define BMP280_REG_RESET     0xE0
#define BMP280_REG_STATUS    0xF3
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG    0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA
#define BMP280_REG_CALIB     0x88

#define BMP280_CHIP_ID       0x58
#define BMP280_RESET_CMD     0xB6

/* ctrl_meas: osrs_t=001 (x1), osrs_p=001 (x1), mode=01 (forced) */
#define BMP280_CTRL_MEAS_FORCED 0x25

/* config: t_sb=001 (0.5 ms standby), filter=000 (off), spi3w_en=0 */
#define BMP280_CONFIG_DEFAULT   0x08

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Calibration coefficients (BMP280 datasheet) ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static bmp280_calib_t g_cal;
static int32_t g_t_fine;

/* ---- Signal handler ---- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, %zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- BMP280 helpers ---- */
static int bmp280_read_calibration(int fd)
{
    uint8_t d[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, d, sizeof(d)) != 0)
        return -1;

    g_cal.dig_T1 = (uint16_t)(d[0]  | (d[1]  << 8));
    g_cal.dig_T2 = (int16_t)(d[2]  | (d[3]  << 8));
    g_cal.dig_T3 = (int16_t)(d[4]  | (d[5]  << 8));
    g_cal.dig_P1 = (uint16_t)(d[6]  | (d[7]  << 8));
    g_cal.dig_P2 = (int16_t)(d[8]  | (d[9]  << 8));
    g_cal.dig_P3 = (int16_t)(d[10] | (d[11] << 8));
    g_cal.dig_P4 = (int16_t)(d[12] | (d[13] << 8));
    g_cal.dig_P5 = (int16_t)(d[14] | (d[15] << 8));
    g_cal.dig_P6 = (int16_t)(d[16] | (d[17] << 8));
    g_cal.dig_P7 = (int16_t)(d[18] | (d[19] << 8));
    g_cal.dig_P8 = (int16_t)(d[20] | (d[21] << 8));
    g_cal.dig_P9 = (int16_t)(d[22] | (d[23] << 8));
    return 0;
}

static int bmp280_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) != 0)
        return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0)
        return -1;
    usleep(5000);  /* 5 ms reset settling */

    if (bmp280_read_calibration(fd) != 0)
        return -1;

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, BMP280_CONFIG_DEFAULT) != 0)
        return -1;

    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t d[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, d, 6) != 0)
        return -1;

    *raw_p = ((int32_t)d[0] << 12) | ((int32_t)d[1] << 4) | (d[2] >> 4);
    *raw_t = ((int32_t)d[3] << 12) | ((int32_t)d[4] << 4) | (d[5] >> 4);
    return 0;
}

/* Bosch 64-bit compensation (datasheet §4) */
static int32_t bmp280_compensate_temp(int32_t raw_t)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)g_cal.dig_T1 << 1)))
            * ((int32_t)g_cal.dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)g_cal.dig_T1))
              * ((raw_t >> 4) - ((int32_t)g_cal.dig_T1))) >> 12)
            * ((int32_t)g_cal.dig_T3)) >> 14;
    g_t_fine = var1 + var2;
    return (g_t_fine * 5 + 128) >> 8;  /* centi-degrees C */
}

static uint32_t bmp280_compensate_press(int32_t raw_p)
{
    int32_t var1, var2;
    uint32_t p;
    var1 = ((g_t_fine >> 1) - 64000);
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)g_cal.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)g_cal.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)g_cal.dig_P4) << 16);
    var1 = (((((int32_t)g_cal.dig_P3) * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3)
            + ((((int32_t)g_cal.dig_P2) * var1) >> 1)) >> 18;
    var1 = (((32768 + var1)) * ((int32_t)g_cal.dig_P1)) >> 15;
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - raw_p) - (var2 >> 12))) << 12);
    p = (p - ((p * var1) >> 12)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P9)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P8)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P7)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P6)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P5)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P4)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P3)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P2)) >> 13)) >> 12;
    p = (p + ((p * ((int32_t)g_cal.dig_P1)) >> 13)) >> 12;
    return p;  /* Pa */
}

/* ---- Data logging ---- */
static int log_data(float temp_c, float press_hpa)
{
    FILE *fp = fopen("weather_data.txt", "a");
    if (!fp) {
