        if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
            fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                    addr, strerror(errno));
            close(g_i2c_fd);
            return EXIT_FAILURE;
        }
    }
    printf("BMP280 found at address 0x%02X\n", addr);

