        if (i2c_write_reg(g_i2c_fd, BMP280_REG_CTRL_MEAS,
                          BMP280_CTRL_MEAS_FORCED) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            sleep(5);
            continue;
        }

