        uint32_t p_pa   = bmp280_compensate_press(raw_p);

        float temp_c = t_centi / 100.0f;
        float press_hpa = p_pa / 100.0f;

        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp_c, press_hpa);

        if (log_data(temp_c, press_hpa) != 0)
            fprintf(stderr, "Warning: data logging failed\n");

