/*
 * Raspberry Pi 4 Model B — LM75 temperature monitor with alert LED.
 *
 * Hardware:
 *   - LM75 on I2C bus 1, address 0x48 (7-bit).
 *   - Alert LED on GPIO18 (BCM), driven via pigpio.
 *
 * Behavior:
 *   - Reads temperature once per second.
 *   - Stores the reading in a 60-sample circular buffer.
 *   - Updates a running average from the buffer.
 *   - Drives GPIO18 HIGH when the average exceeds 28.0 °C and LOW otherwise.
 *   - On sensor-absent or bus-error conditions, logs the issue and
 *     attempts to re-initialize the I2C bus and GPIO line.
 *   - Cleanly releases all resources on SIGINT, normal exit, or error.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lm75_monitor lm75_monitor.c -lpigpio -lpthread
 *   Run with sudo (pigpio requires root for GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define LM75_ADDR        0x48
#define LM75_TEMP_REG    0x00
#define GPIO_LED         18
#define BUFFER_SIZE      60
#define TEMP_THRESHOLD   28.0f
#define POLL_INTERVAL_S  1
#define MAX_REINIT_ATTEMPTS 3

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    float  data[BUFFER_SIZE];
    int    head;
    int    count;
    pthread_mutex_t lock;
} CircularBuffer;

static CircularBuffer g_buffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
    if (pthread_mutex_init(&cb->lock, NULL) != 0)
        perror("pthread_mutex_init");
}

static void cb_push(CircularBuffer *cb, float value)
{
    pthread_mutex_lock(&cb->lock);
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
    pthread_mutex_unlock(&cb->lock);
}

static float cb_average(const CircularBuffer *cb)
{
    float sum = 0.0f;
    int   n   = 0;

    pthread_mutex_lock(&cb->lock);
    n   = cb->count;
    pthread_mutex_unlock(&cb->lock);

    if (n == 0)
        return 0.0f;

    pthread_mutex_lock(&cb->lock);
    for (int i = 0; i < n; i++)
        sum += cb->data[i];
    pthread_mutex_unlock(&cb->lock);

    return sum / (float)n;
}

/* ------------------------------------------------------------------ */
/* LM75 I2C                                                             */
/* ------------------------------------------------------------------ */

static int g_i2c_fd = -1;

static int i2c_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_temp(int fd, float *out_temp)
{
    uint8_t reg = LM75_TEMP_REG;
    uint8_t buf[2];

    /* Select the temperature register. */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select): %s\n", strerror(errno));
        return -1;
    }

    /* Read 2 bytes (MSB first). */
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (temp): %s\n", strerror(errno));
        return -1;
    }

    /* LM75 returns 13-bit two's-complement data in bits [15:3]. */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 3;                       /* arithmetic shift keeps sign */

    /* Sign-extend from 13 bits to 16 bits. */
    if (raw & 0x1000)
        raw |= 0xE000;

    *out_temp = (float)raw / 8.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_LED);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", GPIO_LED);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void gpio_set(int state)
{
    if (gpioWrite(GPIO_LED, state ? 1 : 0) != 0)
