        fprintf(stderr, "gpioWrite(%d, %d) failed\n", GPIO_LED, state);
}

/* ------------------------------------------------------------------ */
/* Alert thread                                                        */
/* ------------------------------------------------------------------ */

static void *alert_thread_fn(void *arg)
{
