    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize circular buffer ---- */
    cb_init(&g_buffer);

    /* ---- Initialize GPIO ---- */
    if (gpio_init() != 0)
        return EXIT_FAILURE;

    /* ---- Initialize I2C ---- */
    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Start alert thread ---- */
    rc = pthread_create(&alert_tid, NULL, alert_thread_fn, NULL);
    if (rc != 0) {
        fprintf(stderr, "pthread_create: %s\n", strerror(rc));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        float temp;

        if (i2c_read_temp(g_i2c_fd, &temp) == 0) {
            cb_push(&g_buffer, temp);
            printf("Temperature: %.2f °C | Average: %.2f °C\n",
                   temp, cb_average(&g_buffer));
        } else {
            fprintf(stderr, "Temperature read failed; attempting re-init.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;

            for (int attempt = 0; attempt < MAX_REINIT_ATTEMPTS && g_running; attempt++) {
                sleep(1);
