#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMPERATURE 80.0
#define CONFIG_FILE "config.json"
#define LOOP_DELAY_US 100000

#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_HFAULT_REG 0x03
#define MAX31865_LFAULT_REG 0x04

#define R_REF 430.0
#define RTD_NOMINAL 100.0
#define RTD_A 0.0039083
#define RTD_B -0.0000005775

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = 25.0;
static double kp = 1.0;
static double ki = 0.1;
static double kd = 0.01;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31865(uint16_t *rtd_raw, uint8_t *fault) {
    char tx[4] = {0x00, 0x00, 0x00, 0x00};
    char rx[4] = {0, 0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    *rtd_raw = ((uint16_t)(rx[1] & 0x0F) << 8) | (uint8_t)rx[2];
    *fault = (uint8_t)rx[3];
    return 0;
}

static double calculate_temperature(uint16_t rtd_raw) {
    double rtd_resistance = (rtd_raw * R_REF) / 32768.0;
    double rtd_temp = (rtd_resistance - RTD_NOMINAL) / (RTD_A + RTD_B * rtd_resistance);
    return rtd_temp;
}

static double calculate_pid(double setpoint, double process_variable, double *integral, double *previous_error, double dt) {
    double error = setpoint - process_variable;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;
    return output;
}

static int set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int load_configuration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file %s, using defaults\n", filename);
        return -1;
    }
    char buffer[1024];
    size_t n = fread(buffer, 1, sizeof(buffer) - 1, fp);
    buffer[n] = '\0';
    fclose(fp);

    char *target = strstr(buffer, "\"target_temperature\"");
    if (target) {
        target = strchr(target, ':');
        if (target) target++;
        char *end;
        double val = strtod(target, &end);
        if (end != target) target_temperature = val;
    }
    char *kp_str = strstr(buffer, "\"kp\"");
    if (kp_str) {
        kp_str = strchr(kp_str, ':');
        if (kp_str) kp_str++;
        char *end;
        double val = strtod(kp_str, &end);
        if (end != kp_str) kp = val;
    }
    char *ki_str = strstr(buffer, "\"ki\"");
    if (ki_str) {
        ki_str = strchr(ki_str, ':');
        if (ki_str) ki_str++;
        char *end;
        double val = strtod(ki_str, &end);
        if (end != ki_str) ki = val;
    }
    char *kd_str = strstr(buffer, "\"kd\"");
    if (kd_str) {
        kd_str = strchr(kd_str, ':');
        if (kd_str) kd_str++;
        char *end;
        double val = strtod(kd_str, &end);
        if (end != kd_str) kd = val;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }
    if (set_pwm_duty(0) != 0) {
        cleanup();
        return 1;
    }

    load_configuration(CONFIG_FILE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double integral = 0.0;
    double previous_error = 0.0;
    struct timespec last_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        uint16_t rtd_raw = 0;
        uint8_t fault = 0;
        if (read_max31865(&rtd_raw, &fault) != 0) {
            fprintf(stderr, "Failsafe: SPI read error\n");
            set_pwm_duty(0);
            break;
        }
        if (fault & 0x01) {
            fprintf(stderr, "Failsafe: RTD fault detected\n");
            set_pwm_duty(0);
            break;
        }
        if (fault & 0x02) {
            fprintf(stderr, "Failsafe: OC fault detected\n");
            set_pwm_duty(0);
            break;
        }
        double temperature = calculate_temperature(rtd_raw);
        if (temperature > MAX_TEMPERATURE) {
            fprintf(stderr, "Failsafe: Temperature %.2f exceeds max %.2f\n", temperature, MAX_TEMPERATURE);
            set_pwm_duty(0);
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double dt = (current_time.tv_sec - last_time.tv_sec) + (current_time.tv_nsec - last_time.tv_nsec) / 1e9;
        if (dt <= 0.0) dt = 0.01;
        last_time = current_time;

        double pid_output = calculate_pid(target_temperature, temperature, &integral, &previous_error, dt);
        int duty = (int)(pid_output * 100.0);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (set_pwm_duty(duty) != 0) {
            fprintf(stderr, "Failsafe: PWM set error\n");
            set_pwm_duty(0);
            break;
        }
        printf("Temperature: %.2f°C, Target: %.2f°C, PWM: %d/%d\n", temperature, target_temperature, duty, PWM_RANGE);
        usleep(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

