#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x5C
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, out, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3,
                            uint16_t *ac4, uint16_t *ac5, uint16_t *ac6,
                            int16_t *b1, int16_t *b2, int16_t *mb,
                            int16_t *mc, int16_t *md) {
    if (i2c_read_reg16(fd, 0xAA, ac1) || i2c_read_reg16(fd, 0xAC, ac2) ||
        i2c_read_reg16(fd, 0xAE, ac3) || i2c_read_reg16(fd, 0xB0, (int16_t*)ac4) ||
        i2c_read_reg16(fd, 0xB2, (int16_t*)ac5) || i2c_read_reg16(fd, 0xB4, (int16_t*)ac6) ||
        i2c_read_reg16(fd, 0xB6, b1) || i2c_read_reg16(fd, 0xB8, b2) ||
        i2c_read_reg16(fd, 0xBA, mb) || i2c_read_reg16(fd, 0xBC, mc) ||
        i2c_read_reg16(fd, 0xBE, md)) {
        return -1;
    }
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, 0xF4, 0x2E) < 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_reg8(fd, 0xF6, &buf[0]) || i2c_read_reg8(fd, 0xF7, &buf[1])) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, 0xF4, 0x34) < 0) return -1;
    usleep(2000);
    uint8_t buf[3];
    if (i2c_read_reg8(fd, 0xF6, &buf[0]) || i2c_read_reg8(fd, 0xF7, &buf[1]) ||
        i2c_read_reg8(fd, 0xF8, &buf[2])) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> 8;
    return 0;
}

static double calculate_temperature(int32_t ut, int16_t ac1, int16_t ac2,
                                     int16_t ac3, uint16_t ac4, uint16_t ac5,
                                     uint16_t ac6, int16_t b1, int16_t b2,
                                     int16_t mb, int16_t mc, int16_t md) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t ut, int16_t ac1, int16_t ac2,
                                 int16_t ac3, uint16_t ac4, uint16_t ac5,
                                 uint16_t ac6, int16_t b1, int16_t b2,
                                 int16_t mb, int16_t mc, int16_t md) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p / 100.0;
}

static void log_breach(double temp, double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Temperature: %.2f C, Pressure: %.2f hPa\n", ts, temp, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) { perror("ioctl"); close(fd); return 1; }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;

    if (read_calibration(fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data.\n");
        close(fd);
        return 1;
    }

    while (running) {
        int32_t ut = 0, up = 0;
        int retries = 0;
        int ok = 0;

        while (retries < MAX_RETRIES && !ok) {
            if (read_raw_temp(fd, &ut) == 0 && read_raw_pressure(fd, &up) == 0) ok = 1;
            else {
                retries++;
                if (retries < MAX_RETRIES) usleep(100000);
            }
        }

        if (!ok) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double temp = calculate_temperature(ut, ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md);
        double pressure = calculate_pressure(up, ut, ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md);

        if (temp > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            log_breach(temp, pressure);
        }

        sleep(SAMPLE_INTERVAL);
    }

    close(fd);
    return 0;
}

