/*
 * BMP180 I2C temperature/pressure logger with hardware timer fan control.
 *
 * Board : Raspberry Pi 4 Model B
 * Library: pigpio (hardware timer, GPIO)
 * Sensor : BMP180 (I2C address 0x77, bus 1)
 * Fan    : GPIO18 (active-high cooling fan)
 *
 * Build  : gcc -O2 -Wall -o bmp180_fan bmp180_fan.c -lpigpio -lrt
 * Run    : sudo ./bmp180_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS              1
#define BMP180_ADDR          0x77
#define FAN_GPIO             18
#define TEMP_THRESHOLD       30.0f
#define SAMPLE_PERIOD_MS     500
#define BUFFER_SIZE          60
#define OSS                  0

/* BMP180 registers */
#define BMP180_REG_CONTROL   0xF4
#define BMP180_REG_MSB       0xF6
#define BMP180_REG_LSB       0xF7
#define BMP180_REG_XLSB      0xF8

/* BMP180 commands */
#define BMP180_CMD_TEMP      0x2E
#define BMP180_CMD_PRESS_OSS0 0x34   /* 0x34 + (OSS << 6) */

/* Calibration register addresses */
#define BMP180_REG_CAL_AC1   0xAA
#define BMP180_REG_CAL_AC2   0xAC
#define BMP180_REG_CAL_AC3   0xAE
#define BMP180_REG_CAL_AC4   0xB0
#define BMP180_REG_CAL_AC5   0xB2
#define BMP180_REG_CAL_AC6   0xB4
#define BMP180_REG_CAL_B1    0xB6
#define BMP180_REG_CAL_B2    0xB8
#define BMP180_REG_CAL_MB    0xBA
#define BMP180_REG_CAL_MC    0xBC
#define BMP180_REG_CAL_MD    0xBE

/* ----------------------------- Globals --------------------------------- */
static int                  g_i2c_handle = -1;
static volatile sig_atomic_t g_running   = 1;

/* Calibration coefficients (signed / unsigned 16-bit) */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* Circular buffer */
typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static sensor_data_t g_buffer[BUFFER_SIZE];
static int           g_head = 0;   /* next write slot */
static int           g_tail = 0;   /* oldest read slot */

/* --------------------------- Prototypes -------------------------------- */
static int  read_calibration(void);
static int  read_raw_temperature(int32_t *ut);
static int  read_raw_pressure(int32_t *up);
static int  calculate_b5(int32_t ut, int32_t *out);
static int  calculate_temperature(int32_t ut, float *temp_out);
static int  calculate_pressure(int32_t up, int32_t b5, float *press_out);
static void timer_callback(void *userdata);
static void signal_handler(int sig);
static void cleanup(void);

/* --------------------------- Calibration ------------------------------- */
static int read_calibration(void)
{
    int rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_AC1);
    if (rc < 0) { fprintf(stderr, "AC1 read failed: %d\n", rc); return -1; }
    ac1 = (int16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_AC2);
    if (rc < 0) { fprintf(stderr, "AC2 read failed: %d\n", rc); return -1; }
    ac2 = (int16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_AC3);
    if (rc < 0) { fprintf(stderr, "AC3 read failed: %d\n", rc); return -1; }
    ac3 = (int16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_AC4);
    if (rc < 0) { fprintf(stderr, "AC4 read failed: %d\n", rc); return -1; }
    ac4 = (uint16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_AC5);
    if (rc < 0) { fprintf(stderr, "AC5 read failed: %d\n", rc); return -1; }
    ac5 = (uint16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_AC6);
    if (rc < 0) { fprintf(stderr, "AC6 read failed: %d\n", rc); return -1; }
    ac6 = (uint16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_B1);
    if (rc < 0) { fprintf(stderr, "B1 read failed: %d\n", rc); return -1; }
    b1  = (int16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_B2);
    if (rc < 0) { fprintf(stderr, "B2 read failed: %d\n", rc); return -1; }
    b2  = (int16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_MB);
    if (rc < 0) { fprintf(stderr, "MB read failed: %d\n", rc); return -1; }
    mb = (int16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_MC);
    if (rc < 0) { fprintf(stderr, "MC read failed: %d\n", rc); return -1; }
    mc = (int16_t)rc;

    rc = i2cReadWordData(g_i2c_handle, BMP180_REG_CAL_MD);
    if (rc < 0) { fprintf(stderr, "MD read failed: %d\n", rc); return -1; }
    md = (int16_t)rc;

    return 0;
}

/* --------------------------- Raw reads ---------------------------------- */
static int read_raw_temperature(int32_t *ut)
{
    if (i2cWriteByteData(g_i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0)
        return -1;
    gpioDelay(5000);                       /* 4.5 ms max conversion time */

    int msb = i2cReadByteData(g_i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(g_i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;

    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *up)
{
    uint8_t cmd = BMP180_CMD_PRESS_OSS0;
    if (i2cWriteByteData(g_i2c_handle, BMP180_REG_CONTROL, cmd) < 0)
        return -1;
    gpioDelay(5000);                       /* 4.5 ms for OSS=0 */

    int msb = i2cReadByteData(g_i2c_handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(g_i2c_handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(g_i2c_handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;

    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

/* --------------------------- B5 path ------------------------------------ */
static int calculate_b5(int32_t ut, int32_t *out)
{
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    *out = x1 + x2;
    return 0;
}

static int calculate_temperature(int32_t ut, float *temp_out)
{
    int32_t b5;
    if (calculate_b5(ut, &b5) < 0) return -1;
    *temp_out = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

static int calculate_pressure(int32_t up, int32_t b5, float *press_out)
{
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *press_out = (float)p / 100.0f;
    return 0;
}

/* --------------------------- Timer callback ----------------------------- */
static void timer_callback(void *userdata)
{
    (void)userdata;

    if (!g_running) return;

    int32_t ut, up, b5;
    float   temp, press;

    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Temperature read error; sample skipped.\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Pressure read error; sample skipped.\n");
        return;
    }
    if (calculate_b5(ut, &b5) < 0) {
        fprintf(stderr, "B5 calculation error; sample skipped.\n");
        return;
    }
    if (calculate_temperature(ut, &temp) < 0) {
        fprintf(stderr, "Temperature calc error; sample skipped.\n");
        return;
    }
    if (calculate_pressure(up, b5, &press) < 0) {
        fprintf(stderr, "Pressure calc error; sample skipped.\n");
        return;
    }

    time_t now = time(NULL);
    g_buffer[g_head].timestamp  = now;
    g_buffer[g_head].temperature = temp;
    g_buffer[g_head].pressure    = press;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_head == g_tail)
        g_tail = (g_tail + 1) % BUFFER_SIZE;   /* overwrite oldest */

    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f hPa\n",
           (long)now, temp, press);

    if (temp > TEMP_THRESHOLD)
        gpioWrite(FAN_GPIO, 1);
    else
        gpioWrite(FAN_GPIO, 0);
}

/* --------------------------- Signal / cleanup --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration() < 0) {
        fprintf(stderr, "BMP180 calibration read failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set timer.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 logging started (500 ms period). Ctrl+C to exit.\n");

    while (g_running)
        gpioDelay(100000);   /* 100 ms */

    cleanup();
    return EXIT_SUCCESS;
}

