/*
 * BMP180 pressure logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (I2C bus 1 SDA)
 *   BMP180 SCL -> GPIO3 (I2C bus 1 SCL)
 *   BMP180 VCC -> 3.3 V
 *   BMP180 GND -> GND
 *   GPIO27   -> GND (active-low falling edge toggles logging)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bmp180_logger bmp180_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./bmp180_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants (datasheet) ---- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE

#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34

#define GPIO_TOGGLE             27
#define LOG_FILE               "pressure_log.txt"
#define SAMPLE_INTERVAL_US     2000000  /* 2 s */
#define DEBOUNCE_US            200000   /* 200 ms */
#define I2C_RETRY_DELAY_US     100000   /* 100 ms */
#define I2C_RETRY_MAX          3

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static bool     g_logging    = false;

/* ---- Calibration coefficients ---- */
typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t g_cal;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read a signed 16-bit big-endian register ---- */
static int16_t read_s16(int handle, uint8_t reg)
{
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return (int16_t)hi;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return (int16_t)lo;
    return (int16_t)((hi << 8) | lo);
}

/* ---- Read a unsigned 16-bit big-endian register ---- */
static uint16_t read_u16(int handle, uint8_t reg)
{
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return (uint16_t)hi;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return (uint16_t)lo;
    return (uint16_t)((hi << 8) | lo);
}

/* ---- Read calibration data ---- */
static int read_calibration(int handle, bmp180_cal_t *cal)
{
    cal->ac1 = read_s16(handle, BMP180_REG_CAL_AC1);
    cal->ac2 = read_s16(handle, BMP180_REG_CAL_AC2);
    cal->ac3 = read_s16(handle, BMP180_REG_CAL_AC3);
    cal->ac4 = read_u16(handle, BMP180_REG_CAL_AC4);
    cal->ac5 = read_u16(handle, BMP180_REG_CAL_AC5);
    cal->ac6 = read_u16(handle, BMP180_REG_CAL_AC6);
    cal->b1  = read_s16(handle, BMP180_REG_CAL_B1);
    cal->b2  = read_s16(handle, BMP180_REG_CAL_B2);
    cal->mb  = read_s16(handle, BMP180_REG_CAL_MB);
    cal->mc  = read_s16(handle, BMP180_REG_CAL_MC);
    cal->md  = read_s16(handle, BMP180_REG_CAL_MD);

    /* Sanity-check: AC1 should never be 0 or 0xFFFF on a real BMP180 */
    if (cal->ac1 == 0 || cal->ac1 == (int16_t)0xFFFF) {
        fprintf(stderr, "Calibration data invalid (AC1=0x%04X). Sensor not present?\n",
                (uint16_t)cal->ac1);
        return -1;
    }
    return 0;
}

/* ---- Read raw temperature (UT) ---- */
static int read_raw_temp(int handle)
{
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0)
        return -1;
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    int16_t ut = read_s16(handle, BMP180_REG_MSB);
    if ((int)ut < 0) return -1;
    return ut;
}

/* ---- Read raw pressure (UP) ---- */
static int read_raw_pressure(int handle)
{
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS0) < 0)
        return -1;
    gpioDelay(5000);  /* 4.5 ms for OSS=0 */

    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return msb;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return lsb;
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (xlsb < 0) return xlsb;

    return ((msb << 16) | (lsb << 8) | xlsb) >> 8;  /* OSS=0: shift right 8 */
}

/* ---- Bosch compensation (datasheet formulas) ---- */
static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c)
{
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *c)
{
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);  /* OSS=0 */

    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);  /* OSS=0 */

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

/* ---- Log pressure with timestamp ---- */
static void log_pressure(int32_t pressure)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s, %ld\n", ts, (long)pressure);
    fflush(g_log_file);
}

/* ---- Interrupt callback (falling edge) ---- */
static void toggle_logging(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();
    if (now - last_tick > DEBOUNCE_US) {
        g_logging = !g_logging;
        printf("Logging %s\n", g_logging ? "enabled" : "disabled");
        last_tick = now;
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) { fclose(g_log_file); g_log_file = NULL; }
    if (g_i2c_handle >= 0) { i2cClose(g_i2c_handle); g_i2c_handle = -1; }
    gpioTerminate();
}

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at BMP180 address ---- */
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C (handle=%d). Check wiring and address.\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Read calibration ---- */
    if (read_calibration(g_i2c_handle, &g_cal) != 0) {
        fprintf(stderr, "BMP180 calibration read failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    gpioSetMode(GPIO_TOGGLE, PI_INPUT);
    gpioSetPullUpDown(GPIO_TOGGLE, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_TOGGLE, FALLING_EDGE, 0, toggle_logging, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", GPIO_TOGGLE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 logger started. Toggle logging with GPIO27 (falling edge).\n");
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int32_t ut = read_raw_temp(g_i2c_handle);
        if (ut < 0) {
            fprintf(stderr, "Temperature read error (I2C). Retrying in 1 s.\n");
            gpioDelay(1000000);
            continue;
        }

        int32_t up = read_raw_pressure(g_i2c_handle);
        if (up < 0) {
            fprintf(stderr, "Pressure read error (I2C). Retrying in 1 s.\n");
            gpioDelay(1000000);
            continue;
        }

        int32_t b5 = compute_b5(ut, &g_cal);
        int32_t pressure = compute_pressure(up, b5, &g_cal);

        if (g_logging)
            log_pressure(pressure);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

