/*
 * Raspberry Pi 3 Model B+ — MAX31855 thermocouple reader with PWM heater control
 *
 * Hardware:
 *   MAX31855 SPI0: CE0 (GPIO8), MISO (GPIO9), MOSI (GPIO10), SCLK (GPIO11)
 *   Solid-state relay control: GPIO17 (PWM-capable)
 *
 * Build:
 *   gcc -O2 -Wall -o heater_control heater_control.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                         */
#define SPI_SPEED      2000000    /* 2 MHz                                    */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                    */

#define HEATER_GPIO    17         /* PWM-capable GPIO17                       */
#define PWM_FREQ       1000       /* 1 kHz carrier                            */
#define PWM_RANGE      1000       /* 0–1000 → 0.1 % resolution               */
#define MAX_DUTY       800        /* 80 % duty cycle cap (0–1000)            */

#define TARGET_TEMP    25.0f      /* °C                                       */
#define KP             10.0f
#define KI             0.1f
#define KD             0.01f

#define LOG_FILE       "heater_log.csv"
#define SAMPLE_PERIOD  1.0        /* seconds                                 */

/* ------------------------------- Globals -------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log     = NULL;
static int                   g_spi_h   = -1;

/* --------------------------- Function prototypes ------------------------- */

static void  signal_handler(int sig);
static int   spi_read_max31855(int handle, float *temp_c, uint8_t *fault);
static float read_temperature(void);
static void  set_heater_duty(float duty_pct);
static void  log_data(float temp_c, float duty_pct, const char *fault);
static void  cleanup(void);

/* ------------------------------- Handlers -------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read 4 bytes from the MAX31855 and extract the thermocouple temperature.
 * Returns 0 on success, -1 on SPI error.
 * On success, *fault is 0 for OK, 1 for open circuit, 2 for short to GND,
 * 3 for short to VCC.
 */
static int spi_read_max31855(int handle, float *temp_c, uint8_t *fault)
{
    char rx[4] = {0, 0, 0, 0};

    if (spiRead(handle, rx, 4) != 4) {
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit (D16) — bit 16 of the 32-bit word */
    if (raw & 0x00010000) {
        *fault = (uint8_t)((raw >> 18) & 0x03);
        *temp_c = -1000.0f;          /* sentinel below freezing */
        return 0;
    }

    /*
     * Thermocouple temperature: bits 31..18, signed 14-bit, 0.25 °C LSB.
     * Mask to 14 bits, sign-extend, then scale.
     */
    int16_t t = (int16_t)((raw >> 18) & 0x3FFF);
    if (t & 0x2000) {                /* sign bit (bit 13) */
        t |= 0xC000;                 /* extend to 16 bits */
    }
    *temp_c = (float)t * 0.25f;
    *fault  = 0;
    return 0;
}

static float read_temperature(void)
{
    float temp;
    uint8_t fault;

    if (spi_read_max31855(g_spi_h, &temp, &fault) != 0) {
        return -1000.0f;             /* SPI bus error sentinel */
    }
    if (fault) {
        return -1000.0f - (float)fault; /* negative fault code */
    }
    return temp;
}

static void set_heater_duty(float duty_pct)
{
    if (duty_pct < 0.0f)   duty_pct = 0.0f;
    if (duty_pct > 100.0f) duty_pct = 100.0f;

    int duty = (int)(duty_pct * (float)PWM_RANGE / 100.0f);
    if (duty > MAX_DUTY) duty = MAX_DUTY;

    if (gpioPWM(HEATER_GPIO, duty) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on GPIO%d\n", HEATER_GPIO);
    }
}

static void log_data(float temp_c, float duty_pct, const char *fault)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fault) {
        fprintf(g_log, "%s,%.2f,%.2f,%s\n", ts, temp_c, duty_pct, fault);
    } else {
        fprintf(g_log, "%s,%.2f,%.2f\n", ts, temp_c, duty_pct);
    }
    fflush(g_log);
}

static void cleanup(void)
{
    if (g_spi_h >= 0) {
        spiClose(g_spi_h);
        g_spi_h = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    /* Ensure heater is off before terminating pigpio */
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_h = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_h < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_h);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Heater GPIO setup --- */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on GPIO%d\n", HEATER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on GPIO%d\n", HEATER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on GPIO%d\n", HEATER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    set_heater_duty(0.0f);          /* start with heater off */

    /* --- Log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error: fopen log file");
        cleanup();
