#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define POLL_US    500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in millidegrees Celsius.
 * Returns 0 on success, -1 on error.
 */
static int read_cpu_temp(int *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("fopen temperature file");
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "fscanf temperature failed\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "ferror on temperature file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose temperature file");
        return -1;
    }

    *temp_out = temp;
    return 0;
}

/*
 * Set a single PWM channel duty cycle (0-255, inverted for common anode).
 * Returns 0 on success, -1 on error.
 */
static int set_pwm(unsigned pin, unsigned duty)
{
    if (duty < 0 || duty > 255) {
        fprintf(stderr, "Invalid duty %u for pin %u\n", duty, pin);
        return -1;
    }

    /* Invert: 255 = off, 0 = full-on (common anode) */
    int actual = gpioPWM(pin, 255 - duty);
    if (actual < 0) {
        fprintf(stderr, "gpioPWM failed on pin %u (rc=%d)\n", pin, actual);
        return -1;
    }
    return 0;
}

/*
 * Turn off all three channels.
 * Returns 0 on success, -1 on error.
 */
static int all_off(void)
{
    int rc = 0;
    if (set_pwm(RED_PIN, 255) != 0) rc = -1;
    if (set_pwm(GREEN_PIN, 255) != 0) rc = -1;
    if (set_pwm(BLUE_PIN, 255) != 0) rc = -1;
    return rc;
}

/*
 * Map temperature to RGB values (common anode: inverted 0-255).
 * Returns 0 on success, -1 on error.
 */
static int temp_to_rgb(int temp_mC, unsigned *r, unsigned *g, unsigned *b)
{
    if (temp_mC < 0) {
        fprintf(stderr, "Temperature out of range: %d mC\n", temp_mC);
        return -1;
    }

    if (temp_mC < 40000) {
        *r = 0; *g = 0; *b = 255;   /* Blue */
    } else if (temp_mC < 60000) {
        *r = 0; *g = 255; *b = 0;   /* Green */
    } else {
        *r = 255; *g = 0; *b = 0;   /* Red */
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pins as output */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode RED_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode GREEN_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode BLUE_PIN failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (all_off() != 0) {
        fprintf(stderr, "Failed to initialise LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main polling loop */
    while (g_running) {
        int temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Temperature read failed; skipping update\n");
            gpioDelay(POLL_US);
            continue;
        }

        unsigned r, g, b;
        if (temp_to_rgb(temp, &r, &g, &b) != 0) {
            fprintf(stderr, "Temperature mapping failed\n");
            gpioDelay(POLL_US);
            continue;
        }

        if (set_pwm(RED_PIN, r) != 0 ||
            set_pwm(GREEN_PIN, g) != 0 ||
            set_pwm(BLUE_PIN, b) != 0) {
            fprintf(stderr, "PWM write failed\n");
            gpioDelay(POLL_US);
            continue;
        }

        printf("Temperature: %d mC, RGB: (%u,%u,%u)\n", temp, r, g, b);
        fflush(stdout);

        gpioDelay(POLL_US);
    }

    /* Graceful shutdown: turn off LED and release pigpio */
    all_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

