#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_IP "yourserver.com"
#define SERVER_PORT 80
#define MAX_RETRIES 3
#define DHT22_RETRIES 3
#define DHT22_TIMEOUT 1000000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int read_dht22(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int counter = 0;
    int j = 0, i;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, PI_LOW);
    gpioDelay(20000);
    gpioWrite(gpio_pin, PI_HIGH);
    gpioSetMode(gpio_pin, PI_INPUT);

    for (i = 0; i < DHT22_TIMEOUT; i++) {
        int state = gpioRead(gpio_pin);
        if (state != laststate) {
            if (counter == 0) {
                counter = 1;
            } else {
                data[j / 8] <<= 1;
                if (state == PI_HIGH) {
                    data[j / 8] |= 1;
                }
                j++;
            }
            laststate = state;
        }
        gpioDelay(30);
        if (j >= 40) break;
    }

    if (j >= 40) {
        if (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
            *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
            *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
            if (data[2] & 0x80) {
                *temperature = -*temperature;
            }
            return 0;
        }
    }
    return -1;
}

int post_data(const char *json_string) {
    int sockfd = -1;
    struct addrinfo hints, *res, *p;
    char *ip_address = SERVER_IP;
    int retry_count = 0;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(ip_address, "80", &hints, &res) != 0) {
        perror("getaddrinfo failed");
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (sockfd < 0) continue;

