    /* Sanity-check: AC1 / AC6 should never be 0 or 0xFFFF on a real BMP180 */
    if (cal->ac1 == 0 || cal->ac1 == (int16_t)0x8000 ||
        cal->ac6 == 0 || cal->ac6 == 0xFFFF) {
        fprintf(stderr, "[ERROR] Calibration data invalid (sensor absent or wrong part?)\n");
        return -1;
    }
    return 0;
}

/* -------------------------------------------------------------------------
 * Read the raw pressure value (OSS=3).
 * Returns 0 on success, -1 on I2C error.
 * -------------------------------------------------------------------------
 */
static int bmp180_read_raw_pressure(int handle, int32_t *raw_pressure)
{
    uint8_t cmd[2] = { BMP180_REG_CONTROL, (uint8_t)(0x34 | (BMP180_OSS << 6)) };
    uint8_t data[3];

    if (i2cWriteDevice(handle, (char *) cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (pressure cmd) failed\n");
        return -1;
    }
    gpioDelay(BMP180_CONV_DELAY_US);

    if (i2cReadDevice(handle, (char *) data, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cReadDevice (pressure data) failed\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16) | ((int32_t)data[1] << 8) | data[2];
    *raw_pressure >>= (8 - BMP180_OSS);
    return 0;
}

/* -------------------------------------------------------------------------
 * Full Bosch BMP180 integer-only compensation (OSS=3).
 * Returns pressure in hPa.
 * -------------------------------------------------------------------------
 */
static float bmp180_calc_pressure_hpa(int32_t raw_pressure, const bmp180_cal_t *cal)
{
    int32_t  x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    x1 = ((raw_pressure - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal->ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);

    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p / 100.0f;
}

/* -------------------------------------------------------------------------
 * Append a timestamped pressure reading to pressure_log.txt.
 * -------------------------------------------------------------------------
 */
static void log_pressure(float pressure_hpa)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open pressure_log.txt for appending\n");
        return;
    }
    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure_hpa);
    fclose(fp);
}

/* -------------------------------------------------------------------------
 * Button interrupt handler (falling-edge, internal pull-up).
 * Debounced using pigpio tick comparison (>= 200 ms).
 * -------------------------------------------------------------------------
 */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)userdata;

    if (level != 0)            /* only act on falling edge */
        return;

    uint32_t elapsed = tick - g_last_tick;
    if (elapsed < DEBOUNCE_US)
        return;
    g_last_tick = tick;

    g_logging = !g_logging;
    if (g_logging)
        printf("[INFO] Logging started\n");
    else
        printf("[INFO] Logging stopped\n");
}

/* -------------------------------------------------------------------------
 * Release all resources.
 * -------------------------------------------------------------------------
 */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* -------------------------------------------------------------------------
 * SIGINT / SIGTERM handler.
 * -------------------------------------------------------------------------
 */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* -------------------------------------------------------------------------
 * main
 * -------------------------------------------------------------------------
 */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(1, BMP180_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) — sensor absent or bus error\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Read calibration --- */
    if (bmp180_read_calibration(g_i2c_handle, &g_cal) != 0) {
        fprintf(stderr, "[FATAL] BMP180 calibration read failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Button GPIO setup --- */
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "[FATAL] gpioSetISRFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] BMP180 logger started (I2C 0x%02X, OSS=%d)\n",
           BMP180_I2C_ADDR, BMP180_OSS);
    printf("[INFO] Press button (GPIO %d) to toggle logging\n", BUTTON_GPIO);

    /* --- Main loop --- */
    while (g_running) {
        if (g_logging) {
            int32_t raw;
            if (bmp180_read_raw_pressure(g_i2c_handle, &raw) == 0) {
                float hpa = bmp180_calc_pressure_hpa(raw, &g_cal);
                log_pressure(hpa);
                printf("[LOG] %.2f hPa\n", hpa);
            } else {
                fprintf(stderr, "[WARN] Pressure read failed — continuing\n");
            }
        } else {
            printf("[INFO] Logging disabled — press button to start\n");
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

