/*
 * DHT22 humidity reader for Raspberry Pi 3 Model B+
 * Uses the pigpio GPIO library to issue a 1-wire start signal and
 * capture the 40-bit response from the DHT22 on GPIO4 (BCM 4, physical pin 7).
 *
 * Build:  gcc -O2 -Wall -Wextra -o dht22_reader dht22_reader.c -lpigpio -lcurl
 * Run:    sudo ./dht22_reader [-s http://your-api-endpoint.com/api/humidity]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO          4
#define MAX_RETRIES         3
#define READ_INTERVAL_SEC   10
#define POST_RETRY_DELAY_SEC 2
#define DHT22_TIMEOUT_US    200
#define DHT22_BIT_THRESHOLD 100   /* microseconds */

static volatile sig_atomic_t g_terminate = 0;
static char *g_api_url = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* 1-wire start signal                                                 */
/* ------------------------------------------------------------------ */
static bool dht22_start_signal(int gpio)
{
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(PI_OUTPUT) failed on GPIO %d", gpio);
        return false;
    }
    if (gpioWrite(gpio, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(0) failed on GPIO %d", gpio);
        return false;
    }
    gpioDelay(2000);                       /* >1 ms low */

    if (gpioWrite(gpio, 1) < 0) {
        syslog(LOG_ERR, "gpioWrite(1) failed on GPIO %d", gpio);
        return false;
    }
    gpioDelay(30);                         /* 20-40 us high */

    if (gpioSetMode(gpio, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(PI_INPUT) failed on GPIO %d", gpio);
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Capture 40-bit response                                             */
/* ------------------------------------------------------------------ */
static bool dht22_read_data(int gpio, uint8_t data[5])
{
    uint32_t start_tick, edge_tick;
    uint32_t last_tick = gpioTick();
    uint32_t levels[80];
    int idx = 0;

    /* Wait for sensor to pull line low (response start) */
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - last_tick > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22: no response (line stuck high)");
            return false;
        }
    }

    /* Sensor response: ~80 us low, ~80 us high */
    while (idx < 80) {
        edge_tick = gpioTick();
        if (edge_tick - last_tick > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "DHT22: response timeout at bit %d", idx);
            return false;
        }
        levels[idx++] = edge_tick;
        last_tick = edge_tick;

        /* Wait for level change */
        while (gpioRead(gpio) == (idx % 2 == 0 ? 0 : 1)) {
            if (gpioTick() - last_tick > DHT22_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22: bit %d timeout", idx);
                return false;
            }
        }
    }

    /* Decode: bit i is set if the high pulse at index 2*i+1 is > threshold */
    for (int i = 0; i < 40; i++) {
        uint32_t high_us = levels[2 * i + 1] - levels[2 * i];
        data[i / 8] <<= 1;
        if (high_us > DHT22_BIT_THRESHOLD)
            data[i / 8] |= 1;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Checksum validation                                                 */
/* ------------------------------------------------------------------ */
static bool dht22_checksum(const uint8_t data[5])
{
    uint8_t sum = 0;
    for (int i = 0; i < 4; i++)
        sum += data[i];
    return (sum == data[4]) ? true : false;
}

/* ------------------------------------------------------------------ */
/* Read humidity (0.1 %RH resolution)                                  */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int dht22_read_humidity(int gpio, float *humidity)
{
    uint8_t data[5] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (!dht22_start_signal(gpio)) {
            syslog(LOG_ERR, "DHT22: start signal failed (attempt %d/%d)",
                   attempt + 1, MAX_RETRIES);
            gpioDelay(POST_RETRY_DELAY_SEC * 1000000);
            continue;
        }

        if (!dht22_read_data(gpio, data)) {
            syslog(LOG_ERR, "DHT22: read data failed (attempt %d/%d)",
                   attempt + 1, MAX_RETRIES);
            gpioDelay(POST_RETRY_DELAY_SEC * 1000000);
            continue;
        }

        if (!dht22_checksum(data)) {
            syslog(LOG_ERR, "DHT22: checksum failed (attempt %d/%d)",
                   attempt + 1, MAX_RETRIES);
            gpioDelay(POST_RETRY_DELAY_SEC * 1000000);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        *humidity = (float)raw / 10.0f;
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Format JSON                                                         */
/* ------------------------------------------------------------------ */
static void format_json(float humidity, char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    snprintf(buf, len,
             "{\"timestamp\":\"%s\",\"humidity\":%.1f}", ts, humidity);
}

/* ------------------------------------------------------------------ */
/* libcurl write callback                                              */
/* ------------------------------------------------------------------ */
static size_t write_cb(char *ptr, size_t size, size_t nmemb, void *userdata)
{
    (void)ptr;
    (void)userdata;
    return size * nmemb;
}

/* ------------------------------------------------------------------ */
/* HTTP POST                                                           */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int post_data(const char *url, const char *json)
{
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int ret = -1;

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            syslog(LOG_INFO, "HTTP POST successful (code %ld)", http_code);
            ret = 0;
        } else {
            syslog(LOG_ERR, "HTTP POST failed (code %ld)", http_code);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return ret;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
        case 's':
            g_api_url = strdup(optarg);
            if (!g_api_url) {
                syslog(LOG_ERR, "strdup() failed for API URL");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (!g_api_url) {
        g_api_url = strdup("http://your-the-library-api-call.com/api/humidity");
        if (!g_api_url) {
            syslog(LOG_ERR, "strdup() failed for default URL");
            return EXIT_FAILURE;
        }
    }

    openlog("dht22_reader", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 reader (GPIO%d, API=%s)",
           DHT22_GPIO, g_api_url);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction() failed");
        closelog();
        free(g_api_url);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        free(g_api_url);
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init() failed");
        gpioTerminate();
        closelog();
        free(g_api_url);
        return EXIT_FAILURE;
    }

    while (!g_terminate) {
        float humidity = 0.0f;

        if (dht22_read_humidity(DHT22_GPIO, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.1f%%", humidity);

            char json[128];
            format_json(humidity, json, sizeof(json));

            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                if (post_data(g_api_url, json) == 0)
                    break;
                if (attempt < MAX_RETRIES - 1)
                    gpioDelay(POST_RETRY_DELAY_SEC * 1000000);
            }
        } else {
            syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < READ_INTERVAL_SEC && !g_terminate; s++)
            sleep(1);
    }

    syslog(LOG_INFO, "Shutting down");
    curl_global_cleanup();
    gpioTerminate();
    closelog();
    free(g_api_url);
    return EXIT_SUCCESS;
}

