#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_file(const char *path, char *buf, size_t buf_size) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (!fgets(buf, (int)buf_size, fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int write_file(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for write: %s\n", path, strerror(errno));
        return -1;
    }
    if (fputs(value, fp) == EOF) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(void) {
    char buf[16];
    if (read_file(TEMP_FILE, buf, sizeof(buf)) != 0) {
        return -1;
    }
    return atoi(buf) / 1000;
}

static int read_fan_state(void) {
    char buf[16];
    if (read_file(FAN_STATE_FILE, buf, sizeof(buf)) != 0) {
        return -1;
    }
    return atoi(buf);
}

static int read_max_fan_state(void) {
    char buf[16];
    if (read_file(FAN_MAX_STATE_FILE, buf, sizeof(buf)) != 0) {
        return -1;
    }
    return atoi(buf);
}

static int set_fan_speed(int speed) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", speed);
    return write_file(FAN_STATE_FILE, buf);
}

static int determine_fan_speed(int temperature) {
    if (temperature < 45) return 0;
    if (temperature < 55) return 1;
    if (temperature < 65) return 2;
    return 3;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return 1;
    }

    int max_fan_state = read_max_fan_state();
    if (max_fan_state < 0) {
        fprintf(stderr, "Failed to read max fan state. Exiting.\n");
        return 1;
    }
    printf("Max fan state: %d\n", max_fan_state);

    int current_fan_speed = read_fan_state();
    if (current_fan_speed < 0) {
        fprintf(stderr, "Failed to read initial fan state. Exiting.\n");
        return 1;
    }
    printf("Initial fan speed: %d\n", current_fan_speed);

    while (program_running) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int desired_fan_speed = determine_fan_speed(temperature);
        if (desired_fan_speed > max_fan_state) {
            desired_fan_speed = max_fan_state;
        }

        if (desired_fan_speed != current_fan_speed) {
            if (set_fan_speed(desired_fan_speed) == 0) {
                current_fan_speed = desired_fan_speed;
                char log_message[128];
                snprintf(log_message, sizeof(log_message),
                         "Fan speed set to %d (Temperature: %d°C)",
                         current_fan_speed, temperature);
                log_event(log_message);
                printf("%s\n", log_message);
            } else {
                fprintf(stderr, "Error setting fan speed. Retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (set_fan_speed(0) == 0) {
        log_event("Fan speed set to 0 on shutdown");
    } else {
        fprintf(stderr, "Error setting fan speed to 0 on shutdown.\n");
    }
    return 0;
}

