        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

static void log_data(float temp, int duty, float pid_out) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temp: %.2f, Duty: %d, PID: %.4f\n", ts, temp, duty, pid_out);
    fclose(fp);
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(spi)");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }
    return 0;
}

static int spi_read_max31855(uint32_t *raw) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    *raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
           ((uint32_t)rx[2] << 8)  | (uint32_t)rx[3];
    return 0;
}

static float read_temperature(void) {
    uint32_t raw;
    if (spi_read_max31855(&raw) < 0) return -1000.0f;
    if (raw & 0x00010000) {
        if (raw & 0x00000004) log_message("MAX31855 fault: short to VCC");
        else if (raw & 0x00000002) log_message("MAX31855 fault: short to GND");
        else if (raw & 0x00000001) log_message("MAX31855 fault: open circuit");
        else log_message("MAX31855 fault: unknown");
        return -1000.0f;
    }
    int16_t temp_raw = (int16_t)(raw >> 18);
    return (float)temp_raw * 0.25f;
}

static int set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty) < 0) {
        log_message("gpioPWM failed");
        return -1;
    }
    return 0;
}

static void heater_off(void) {
    gpioPWM(HEATER_GPIO, 0);
}

static void cleanup(void) {
    heater_off();
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        log_message("gpioSetMode failed");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        log_message("gpioSetPWMfrequency failed");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        log_message("gpioSetPWMrange failed");
        gpioTerminate();
        return 1;
    }
    heater_off();

    if (spi_init() < 0) {
        log_message("SPI init failed");
        gpioTerminate();
        return 1;
    }

    float integral = 0.0f;
    float prev_error = 0.0f;

    while (g_running) {
        float temp = read_temperature();
        if (temp < -999.0f) {
            log_message("Temperature read error");
            heater_off();
            integral = 0.0f;
            prev_error = 0.0f;
            sleep(1);
            continue;
        }

        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failsafe: temp=%.2f out of range", temp);
            log_message(msg);
            heater_off();
            integral = 0.0f;
            prev_error = 0.0f;
            sleep(1);
            continue;
        }

        float error = TARGET_TEMP - temp;
        integral += error;
        float derivative = error - prev_error;
        float pid_out = KP * error + KI * integral + KD * derivative;
        prev_error = error;

        int duty = (int)(pid_out + 0.5f);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        if (set_pwm_duty(duty) < 0) {
            log_message("Failed to set PWM duty cycle");
        }

        log_data(temp, duty, pid_out);
        sleep(1);
    }

    log_message("Shutting down");
    cleanup();
    return 0;
}

