#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temperature(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp_milli = -1;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature value\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli;
}

static int set_fan_speed(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;
    unsigned duty_cycle = (unsigned)((unsigned)duty_percent * 255U / 100U);
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %u\n", duty_cycle);
        return -1;
    }
    return 0;
}

static int calculate_duty_cycle(int temp_milli) {
    if (temp_milli < 0) return -1;
    double temp_c = (double)temp_milli / 1000.0;
    if (temp_c <= MIN_TEMP) return 0;
    if (temp_c >= MAX_TEMP) return 100;
    return (int)(((temp_c - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 100.0);
}

static int log_data(double temp_c, int duty_percent) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temp_c, duty_percent) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return 1;
    }

    if (set_fan_speed(0) != 0) {
        fprintf(stderr, "Error initializing fan to off state\n");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("Error creating log file");
            gpioTerminate();
            return 1;
        }
        if (fprintf(fp, "Timestamp,Temperature (C),PWM Duty Cycle (%%)\n") < 0) {
            perror("Error writing header to log file");
            fclose(fp);
            gpioTerminate();
            return 1;
        }
        if (fclose(fp) != 0) {
            perror("Error closing log file after writing header");
            gpioTerminate();
            return 1;
        }
    } else {
        fclose(fp);
    }

    printf("CPU temperature monitoring and PWM fan control started.\n");
    printf("Fan GPIO: %d, PWM Frequency: %d Hz, Log File: %s\n", FAN_GPIO, PWM_FREQUENCY, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milli = read_cpu_temperature();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading CPU temperature, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        int duty_percent = calculate_duty_cycle(temp_milli);
        if (duty_percent < 0) {
            fprintf(stderr, "Error calculating duty cycle, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        if (set_fan_speed(duty_percent) != 0) {
            fprintf(stderr, "Error setting fan speed, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        double temp_c = (double)temp_milli / 1000.0;
        if (log_data(temp_c, duty_percent) != 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d%%\n", temp_c, duty_percent);
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    if (set_fan_speed(0) != 0) {
        fprintf(stderr, "Error turning fan off during shutdown\n");
    }
    gpioTerminate();
    printf("Fan stopped and GPIO cleaned up.\n");
    return 0;
}

