/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid flow sensor logger
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3V3, GND -> GND
 *   Sensor 2 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD -> 3V3, GND -> GND
 *   (Shared I2C bus via SF06 multiplexer or similar)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x6B
#define SENSOR2_ADDR   0x6C
#define LOG_FILE       "flow_log.txt"
#define READ_RETRIES   3
#define POLL_INTERVAL  1.0   /* seconds */

/* SLF3S-1300F: continuous measurement command (MSB = 0x36, LSB = 0x08) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x08 };

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Read one 3-byte flow reading from the given I2C handle.
 * Returns 0 on success (flow stored in *flow), -1 on failure.
 */
static int read_flow(int handle, float *flow)
{
    uint8_t buf[3];
    int rc;

    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)CMD_CONT_MEAS, 2);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice failed: %d\n",
                    attempt + 1, rc);
            time_sleep(0.05);
            continue;
        }

        time_sleep(0.05); /* conversion time */

        rc = i2cReadDevice(handle, (char *)buf, 3);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cReadDevice failed: %d\n",
                    attempt + 1, rc);
            time_sleep(0.05);
            continue;
        }
        if (rc != 3) {
            fprintf(stderr, "[attempt %d] short read: %d bytes\n",
                    attempt + 1, rc);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] CRC mismatch\n", attempt + 1);
            continue;
        }

        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *flow = (float)raw;
        return 0;
    }

    return -1;
}

static int log_flow(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, f1, f2);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "i2cOpen(0x%02X) failed: %d\n", SENSOR1_ADDR, h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "i2cOpen(0x%02X) failed: %d\n", SENSOR2_ADDR, h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flow logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, POLL_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow(h1, &f1) == 0);
        int ok2 = (read_flow(h2, &f2) == 0);

        if (ok1 && ok2) {
            if (log_flow(f1, f2) != 0)
                fprintf(stderr, "Warning: failed to log flow data\n");
        } else {
            fprintf(stderr, "Sensor read error (s1=%s, s2=%s)\n",
                    ok1 ? "ok" : "fail", ok2 ? "ok" : "fail");
        }

        time_sleep(POLL_INTERVAL);
    }

