/*
 * Magnetic Rotary Encoder Monitor (Raspberry Pi 4 Model B)
 *
 * Monitors a dual TMAG5110A1 Hall-Effect latch sensor (A on GPIO17, B on GPIO18)
 * via a 2-bit quadrature state machine and logs timestamped position changes
 * to encoder_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o encoder_monitor encoder_monitor.c -lpigpio -lrt
 * Run:    sudo ./encoder_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18

#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360
#define SAMPLE_DELAY_US 10000   /* 10 ms */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_data(float position)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, %.2f\n", timestamp, position) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush on log file failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* GPIO initialization                                                */
/* ------------------------------------------------------------------ */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_A);
        return -1;
    }
    if (gpioSetMode(GPIO_B, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_B);
        return -1;
    }

    /* TMAG5110A1 outputs are open-drain; enable internal pull-ups so
     * the line is defined when the sensor is idle. */
    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", GPIO_A);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", GPIO_B);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* 2-bit quadrature state machine                                     */
/* ------------------------------------------------------------------ */

/*
 * State transitions for a 2-bit quadrature encoder:
 *
 *   |  A  |  B  |  Next state |  Delta |
 *   |-----|-----|-------------|--------|
 *   |  0  |  0  |     0       |    0   |
 *   |  1  |  0  |     1       |    1   |
 *   |  1  |  1  |     2       |   -1   |
 *   |  0  |  1  |     3       |   -1   |
 *   |  0  |  0  |     0       |    0   |
 */
static const int8_t state_table[4][4] = {
    {0, 1, 0, 0},   /* state 0 */
    {0, 1, 2, 0},   /* state 1 */
    {0, 1, 2, 3},   /* state 2 */
    {0, 1, 2, 3}    /* state 3 */
};

static int process_encoder_data(int a, int b, int *state, float *position)
{
    int current_state = *state;
    int new_state = state_table[current_state][(a << 1) | b];

    if (new_state < 0 || new_state > 3) {
        fprintf(stderr, "Invalid state transition: A=%d B=%d state=%d\n",
                a, b, current_state);
        return -1;
    }

    int8_t delta = new_state - current_state;
    if (delta != 0) {
        *position += (float)delta;
        if (*position < 0.0f) {
            *position += (float)PULSES_PER_REVOLUTION;
        } else if (*position >= (float)PULSES_PER_REVOLUTION) {
            *position -= (float)PULSES_PER_REVOLUTION;
        }
    }

    *state = new_state;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    int state = 0;
    float position = 0.0f;
    int last_a = 0, last_b = 0;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- GPIO init ---- */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        if (a < 0 || b < 0) {
            fprintf(stderr, "gpioRead failed (A=%d B=%d)\n", a, b);
            break;
        }

        /* Detect rising edge on Channel A to sample the current state */
        if (a != last_a) {
            if (process_encoder_data(a, b, &state, &position) != 0) {
                break;
            }
            log_data(position);
            last_a = a;
            last_b = b;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* ---- Cleanup ---- */
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            perror("fclose");
        }
        g_log_fp = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

