/*
 * ADPD144RI Red/IR Photometric Sensor Logger with GPIO Alert
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: ADPD144RI (I2C address 0x30)
 * Alert:  GPIO17 (active-high LED)
 *
 * Build:  gcc -O2 -Wall -o adpd144ri_logger adpd144ri_logger.c -lpigpio -lrt
 * Run:    sudo ./adpd144ri_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADPD144RI_ADDR       0x30
#define RED_REG              0x00
#define IR_REG               0x01
#define GPIO_LED             17
#define IR_THRESHOLD         2000
#define SAMPLE_INTERVAL_US   100000   /* 100 ms */
#define LOG_FILE             "adpd144ri_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  adpd144ri_read_reg16(int fd, uint8_t reg, uint16_t *out);
static int  adpd144ri_init(int fd);
static void log_data(FILE *fp, uint16_t red, uint16_t ir);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- I2C Helpers ------------------------------- */

/*
 * Read a 16-bit little-endian register from the ADPD144RI.
 * Returns 0 on success, -1 on error.
 */
static int adpd144ri_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(fd, reg) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %s\n",
                reg, pigpio_error(i2cReadByte(fd)));
        return -1;
    }
    if (i2cReadDevice(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(0x%02X) failed: %s\n",
                reg, pigpio_error(i2cReadDevice(fd)));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/*
 * Initialise the ADPD144RI: verify the device is present by reading the
 * first register.  Returns 0 on success, -1 on error.
 */
static int adpd144ri_init(int fd)
{
    uint16_t dummy;
    if (adpd144ri_read_reg16(fd, RED_REG, &dummy) != 0) {
        fprintf(stderr, "[ERROR] ADPD144RI not responding at 0x%02X\n",
                ADPD144RI_ADDR);
        return -1;
    }
    printf("[INFO] ADPD144RI detected (first reg = 0x%04X)\n", dummy);
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, ADPD144RI_ADDR, pigpio_error(g_i2c_fd));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (adpd144ri_init(g_i2c_fd) != 0) {
        fprintf(stderr, "[FATAL] ADPD144RI not detected; check wiring/address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "# timestamp,red,ir\n");
    fflush(g_log_file);

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        uint16_t red = 0, ir = 0;
        int      err = 0;

        if (adpd144ri_read_reg16(g_i2c_fd, RED_REG, &red) != 0)
            err = 1;
        if (adpd144ri_read_reg16(g_i2c_fd, IR_REG,  &ir)  != 0)
            err = 1;

        if (err) {
            fprintf(stderr, "[WARN] I2C read error — continuing\n");
            gpioWrite(GPIO_LED, 0);
        } else {
            log_data(g_log_file, red, ir);
            if (ir > IR_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
                printf("[ALERT] IR=%u > %d — LED ON\n", ir, IR_THRESHOLD);
            } else {
                gpioWrite(GPIO_LED, 0);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

