/*
 * MLX90254 RPM reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX90254 VCC  -> 3.3 V (pin 1)
 *   MLX90254 GND  -> GND   (pin 9)
 *   MLX90254 OUT  -> GPIO18 (pin 12)
 *
 * The MLX90254 outputs a digital pulse train proportional to speed.
 * We count rising edges on GPIO18 and compute RPM over a 1-second window.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90254_rpm mlx90254_rpm.c -lpigpio -lpthread
 * Run:    sudo ./mlx90254_rpm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN        18
#define LOG_FILE        "rpm_log.txt"
#define SAMPLE_PERIOD_S 1.0

/* ------------------------------------------------------------------ */
/* Shared state                                                       */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_pulse_count = 0;
static pthread_mutex_t   g_mutex       = PTHREAD_MUTEX_INITIALIZER;
static FILE             *g_log_fp      = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* ISR — runs in pigpio's thread                                       */
/* ------------------------------------------------------------------ */

static void isr_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    pthread_mutex_lock(&g_mutex);
    g_pulse_count++;
    pthread_mutex_unlock(&g_mutex);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void log_rpm(double rpm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s, RPM: %.2f\n", ts, rpm);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    pthread_mutex_destroy(&g_mutex);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, isr_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90254 RPM reader started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    /* ---- Main loop ---- */
    while (g_running) {
        time_sleep(SAMPLE_PERIOD_S);

        uint32_t pulses;
        pthread_mutex_lock(&g_mutex);
        pulses = g_pulse_count;
        g_pulse_count = 0;
        pthread_mutex_unlock(&g_mutex);

        double rpm = (double)pulses / SAMPLE_PERIOD_S;
        log_rpm(rpm);
        printf("RPM: %.2f\n", rpm);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

