#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x30
#define RED_REG 0x04
#define IR_REG 0x05
#define LED_GPIO 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_sensor(int fd, uint16_t *red, uint16_t *ir) {
    if (i2c_read_reg16(fd, RED_REG, red) != 0) return -1;
    if (i2c_read_reg16(fd, IR_REG, ir) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp);
}

static void control_led(int gpio, int ir_value) {
    gpioWrite(gpio, ir_value > THRESHOLD ? 1 : 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t red, ir;
        if (read_sensor(i2c_fd, &red, &ir) != 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            gpioWrite(LED_GPIO, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        log_data(log_fp, red, ir);
        control_led(LED_GPIO, ir);
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

