    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log file");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t red, ir;
        if (read_sensor(i2c_fd, &red, &ir) != 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            gpioWrite(LED_GPIO, 0);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        log_data(log_fp, red, ir);
        control_led(LED_GPIO, ir);
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

