/*
 * Raspberry Pi Zero W - Sensirion SLF3S-4000B Liquid Flow Sensor Monitor
 *
 * Wiring:
 *   Sensor SDA -> GPIO2 (I2C bus 1 SDA)
 *   Sensor SCL -> GPIO3 (I2C bus 1 SCL)
 *   Sensor VDD -> 3.3 V
 *   Sensor GND -> GND
 *
 * Build: gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x20          /* SLF3S-4000B default I2C address */
#define LOG_FILE         "flow_log.csv"
#define SAMPLE_PERIOD_US 1000000       /* 1 second */
#define READ_LEN         3             /* 2 data bytes + 1 CRC byte */

/* SLF3S-4000B CRC-8 parameters (polynomial 0x31, init 0xFF) */
#define CRC8_POLY        0x31
#define CRC8_INIT        0xFF

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_open_sensor(void)
{
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, handle);
        return -1;
    }
    return handle;
}

/*
 * Read 3 bytes from the SLF3S-4000B:
 *   [MSB][LSB][CRC]
 *   Flow rate in units of 0.01 uL/min (raw * 0.01).
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[READ_LEN];

    int bytes = i2cReadDevice(handle, (char *)buf, READ_LEN);
    if (bytes != READ_LEN) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %d)\n",
                bytes, READ_LEN);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch (calc=0x%02X, recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * 0.01f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open log file once --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2c_open_sensor();
    if (g_i2c_handle < 0) {
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("Flow monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        float flow_rate = 0.0f;
        int rc = read_flow_rate(g_i2c_handle, &flow_rate);

        if (rc == 0) {
            if (log_data(g_log_file, flow_rate) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing.\n");
            }
        } else if (rc == -1) {
            /* I2C read error: attempt to reopen the bus */
            fprintf(stderr, "[WARN] I2C read failed; reopening bus...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000); /* 100 ms back-off */
            g_i2c_handle = i2c_open_sensor();
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[ERROR] Reopen failed; retrying next cycle.\n");
            }
        } else {
            /* CRC mismatch: skip this sample, keep running */
            fprintf(stderr, "[WARN] CRC mismatch; skipping sample.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

