/*
 * Raspberry Pi Zero W - Honeywell MICS-VZ-89TE VOC Sensor Logger
 *
 * Wiring:
 *   MICS-VZ-89TE SDA -> GPIO2 (I2C bus 1 SDA)
 *   MICS-VZ-89TE SCL -> GPIO3 (I2C bus 1 SCL)
 *   MICS-VZ-89TE VDD -> 3.3V
 *   MICS-VZ-89TE GND -> GND
 *
 * The MICS-VZ-89TE is a 7-bit I2C addressable sensor.  The default
 * address is 0x5B (7-bit).  The sensor provides a continuous measurement
 * mode; to read it we issue a read-pointer command (0x00) and then
 * read 6 bytes of data.  The data layout (per the datasheet):
 *
 *   Byte 0: Status (0x00 = normal, 0x01 = busy, 0x02 = error)
 *   Byte 1: TVOC (ppb) low byte
 *   Byte 2: TVOC (ppb) high byte
 *   Byte 3: eCO2 (ppm) low byte
 *   Byte 4: eCO2 (ppm) high byte
 *   Byte 5: Reserved
 *
 * The IAQ index is computed as the average of the TVOC and eCO2 values.
 *
 * Build:  gcc -O2 -Wall -o air_quality air_quality.c -lpigpio -lrt
 * Run:    sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x5B          /* MICS-VZ-89TE default 7-bit I2C address */
#define LOG_FILE       "air_quality_log.csv"
#define SAMPLE_PERIOD  5             /* seconds between samples */
#define MEAS_DELAY_US  200000        /* 200 ms settle delay after a read */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read sensor data                                                    */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills tvoc_ppb and eco2_ppm.
 * Returns -1 on I2C error, -2 on sensor status error.
 */
static int read_sensor_data(int handle, uint16_t *tvoc_ppb, uint16_t *eco2_ppm)
{
    char buf[6];
    int  rc;

    /*
     * Issue a pointer-to-read command 0x00.  The sensor requires a
     * short delay after the write before a subsequent read.
     */
    rc = i2cWriteByte(handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte failed (rc=%d)\n", rc);
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);   /* 200 ms settle */

    rc = i2cReadDevice(handle, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 6)\n", rc);
        return -1;
    }

    /* Status byte: 0x00 = normal, 0x01 = busy, 0x02 = error */
    if (buf[0] == 0x02) {
        fprintf(stderr, "[ERROR] Sensor reports status 0x02 (error)\n");
        return -2;
    }
    if (buf[0] == 0x01) {
        fprintf(stderr, "[WARN] Sensor reports status 0x01 (busy)\n");
        return -2;
    }

    *tvoc_ppb = (uint16_t)((uint8_t)buf[1] | ((uint8_t)buf[2] << 8));
    *eco2_ppm = (uint16_t)((uint8_t)buf[3] | ((uint8_t)buf[4] << 8));

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute IAQ index                                                   */
/* ------------------------------------------------------------------ */
static float calculate_iaq_index(uint16_t tvoc, uint16_t eco2)
{
    return (float)(tvoc + eco2) / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d). Check wiring and that the sensor is present at 0x%02X.\n",
                g_i2c_handle, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(g_log_file);
    }

    /* --- signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("MICS-VZ-89TE air quality logger started.\n");
    printf("I2C bus %d, address 0x%02X, logging to %s every %d s.\n",
           I2C_BUS, I2C_ADDR, LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t tvoc = 0, eco2 = 0;
        int      rc;

        rc = read_sensor_data(g_i2c_handle, &tvoc, &eco2);
        if (rc == 0) {
            float iaq = calculate_iaq_index(tvoc, eco2);
            log_data(g_log_file, iaq, tvoc, eco2);
            printf("[%s] IAQ=%.2f  TVOC=%u ppb  eCO2=%u ppm\n",
                   "now", iaq, tvoc, eco2);
        } else if (rc == -2) {
            /* Sensor status error (busy or error) - log and continue */
            fprintf(stderr, "[WARN] Sensor status error, skipping sample.\n");
            log_data(g_log_file, -1.0f, 0, 0);
        } else {
            /* I2C error - log and back off briefly */
            fprintf(stderr, "[WARN] I2C read error, skipping sample.\n");
            log_data(g_log_file, -1.0f, 0, 0);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* --- graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

