code:
/*
 * TTP223B Capacitive Touch Sensor Monitor
 * Board:  Raspberry Pi 5 (BCM GPIO numbering)
 * Sensor: SainSmart TTP223B
 * Wiring: TTP223B OUT  -> GPIO17 (physical pin 11)
 *         TTP223B VCC  -> 3.3 V (physical pin 1)
 *         TTP223B GND  -> GND  (physical pin 9)
 *
 * Behavior:
 *   - Polls the OUT line every 100 ms using CLOCK_MONOTONIC.
 *   - When the line is HIGH for > 5 s, prints an intrusion alert.
 *   - Resets the timer on release so alerts are not repeated for the same touch.
 *   - Exits cleanly on any read error or signal.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* Pi 5 default gpiochip */
#define GPIO_LINE_OFFSET 17            /* BCM 17, physical pin 11 */
#define TAMPER_THRESHOLD_SEC 5         /* seconds of continuous touch to trigger alert */
#define POLL_INTERVAL_MS  100          /* polling cadence */
#define CONSUMER_NAME     "ttp223_tamper"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec poll_ts = { 0, POLL_INTERVAL_MS * 1000000L };
    struct timespec touch_start = { 0, 0 };
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpiod_line_request_input(line, CONSUMER_NAME) < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Monitoring TTP223B on GPIO%d (chip %s). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    fflush(stdout);

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO%d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        if (val == 1) {
            if (touch_start.tv_sec == 0 && touch_start.tv_nsec == 0) {
                if (clock_gettime(CLOCK_MONOTONIC, &touch_start) < 0) {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                    ret = EXIT_FAILURE;
                    break;
                }
            } else {
                struct timespec now;
                if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                    ret = EXIT_FAILURE;
                    break;
                }
                double elapsed = (now.tv_sec - touch_start.tv_sec)
                                 + (now.tv_nsec - touch_start.tv_nsec) / 1e9;
                if (elapsed > TAMPER_THRESHOLD_SEC) {
                    printf("Intrusion detected! (touch held > %d s)\n",
                           TAMPER_THRESHOLD_SEC);
                    fflush(stdout);
                    touch_start.tv_sec = 0;
                    touch_start.tv_nsec = 0;
                }
            }
        } else {
            touch_start.tv_sec = 0;
            touch_start.tv_nsec = 0;
        }

        nanosleep(&poll_ts, NULL);
    }

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

