            if (touch_start.tv_sec == 0 && touch_start.tv_nsec == 0) {
                if (clock_gettime(CLOCK_MONOTONIC, &touch_start) < 0) {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                    ret = EXIT_FAILURE;
                    break;
                }
            } else {
                struct timespec now;
                if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                    ret = EXIT_FAILURE;
                    break;
                }
                double elapsed = (now.tv_sec - touch_start.tv_sec)
                                 + (now.tv_nsec - touch_start.tv_nsec) / 1e9;
                if (elapsed > TAMPER_THRESHOLD_SEC) {
                    printf("Intrusion detected! (touch held > %d s)\n",
                           TAMPER_THRESHOLD_SEC);
                    fflush(stdout);
                    touch_start.tv_sec = 0;
                    touch_start.tv_nsec = 0;
                }
            }
        } else {
            touch_start.tv_sec = 0;
            touch_start.tv_nsec = 0;
        }

        nanosleep(&poll_ts, NULL);
    }

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

