/*
 * INMP441 I2S MEMS Microphone Audio Capture for Raspberry Pi 4 Model B
 *
 * Uses the Linux ALSA subsystem to read 16-bit PCM samples from the
 * I2S bus (e.g., /dev/snd/pcmC0D0c) and writes them to audio_capture.pcm.
 *
 * Wiring:
 *   INMP441 SDA  -> GPIO 2  (BCM)
 *   INMP441 SCL  -> GPIO 3  (BCM)
 *   INMP441 L/R  -> GPIO 17 (BCM)  [Left channel select]
 *   INMP441 SDO  -> I2S bus data line (e.g., GPIO 20)
 *   INMP441 SCLK -> I2S bus clock line (e.g., GPIO 22)
 *   INMP441 LRCLK-> I2S bus LRCLK line (e.g., GPIO 23)
 *   INMP441 VDD  -> 3.3 V
 *   INMP441 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o audio_capture audio_capture.c -lasound -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <linux/types.h>
#include <linux/i2s.h>
#include <pigpio.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define OUTPUT_FILE     "audio_capture.pcm"
#define SAMPLE_RATE     48000
#define BITS_PER_SAMPLE 16
#define CHANNELS        1
#define FRAME_SIZE      (CHANNELS * (BITS_PER_SAMPLE / 8))
#define BUFFER_SIZE     (SAMPLE_RATE / 10)   /* 4800 samples ~ 0.1 s */
#define GPIO_LR_SELECT  17

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int init_i2s(int *fd)
{
    *fd = open(I2S_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    /* Configure I2S mode: 16-bit, 48 kHz, 1 channel */
    struct i2s_config config;
    memset(&config, 0, sizeof(config));
    config.mode = I2S_MODE_TX;
    config.sample_rate = SAMPLE_RATE;
    config.bits_per_sample = BITS_PER_SAMPLE;
    config.channels = CHANNELS;

    if (ioctl(*fd, I2S_CONFIG, &config) < 0) {
        fprintf(stderr, "Error configuring I2S: %s\n", strerror(errno));
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_LR_SELECT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LR_SELECT);
        gpioTerminate();
        return -1;
    }

    /* Select left channel initially */
    if (gpioWrite(GPIO_LR_SELECT, 1) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", GPIO_LR_SELECT);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int open_output_file(FILE **fp)
{
    *fp = fopen(OUTPUT_FILE, "wb");
    if (*fp == NULL) {
        fprintf(stderr, "Error opening output file %s: %s\n",
                OUTPUT_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int write_pcm_data(FILE *fp, const uint8_t *data, size_t len)
{
    size_t written = fwrite(data, 1, len, fp);
    if (written != len) {
        fprintf(stderr, "Error writing to output file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2s_fd = -1;
    FILE *output_fp = NULL;
    uint8_t *buffer = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        goto cleanup;
    }

    if (init_i2s(&i2s_fd) < 0) {
        goto cleanup;
    }

    if (open_output_file(&output_fp) < 0) {
        goto cleanup;
    }

    buffer = malloc(BUFFER_SIZE * FRAME_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        goto cleanup;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (!g_terminate) {
        ssize_t bytes_read = read(i2s_fd, buffer, BUFFER_SIZE * FRAME_SIZE);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            goto cleanup;
        }

        if (bytes_read == 0) {
            /* No data available right now; retry */
            continue;
        }

        if (write_pcm_data(output_fp, buffer, (size_t)bytes_read) < 0) {
            goto cleanup;
        }
    }

    printf("\nAudio capture stopped.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (buffer != NULL) {
        free(buffer);
    }
    if (output_fp != NULL) {
        fclose(output_fp);
    }
    if (i2s_fd >= 0) {
        close(i2s_fd);
    }
    gpioTerminate();
    return ret;
}

