/*
 * Raspberry Pi 4 Model B – Flame Detection & Fan Control
 *
 * Hardware:
 *   - SainSmart IR Flame Sensor Module (LM393 comparator + IR photodiode)
 *     DO  -> GPIO4  (BCM)
 *     VCC -> 3.3 V
 *     GND -> GND
 *   - 4-pin PWM fan control module
 *     IN  -> GPIO18 (BCM) via hardware PWM (PWM0)
 *     VCC -> 5 V
 *     GND -> GND
 *
 * Behavior:
 *   - Polls DO every 50 ms with 50 ms debounce.
 *   - On LOW (flame), drives a 100 Hz hardware PWM signal on GPIO18.
 *   - Logs events to flame_log.txt with ISO-8601 timestamps.
 *   - Detects sensor-absent (no valid reading within 5 s).
 *   - Clean shutdown on SIGINT / SIGTERM.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_fan flame_fan.c -lpigpio -lrt
 *   Run as root (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4          /* BCM 4  – DO from flame sensor */
#define FAN_PWM_PIN      18         /* BCM 18 – hardware PWM capable */

#define PWM_FREQUENCY    100        /* Hz */
#define PWM_RANGE        255        /* duty-cycle steps */
#define PWM_DUTY_ON      255        /* fully on */
#define PWM_DUTY_OFF     0          /* fully off */

#define DEBOUNCE_MS      50         /* debounce window */
#define POLL_MS          50         /* main-loop period */
#define SENSOR_TIMEOUT_S 5          /* sensor-absent threshold */

#define LOG_FILE         "flame_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log, "%s %s\n", ts, event);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                FAN_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n",
                FAN_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMrange(FAN_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n",
                FAN_PWM_PIN);
        return -1;
    }

    if (gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO%d.\n",
                FAN_PWM_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: stop PWM and reset pins */
    gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF);
    gpioSetMode(FAN_PWM_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Flame detection with debounce                                       */
/* ------------------------------------------------------------------ */
/*
 * Returns 1 if flame is confirmed (LOW), 0 if not, -1 on read error.
 */
static int read_flame_sensor(void)
{
    int first = gpioRead(FLAME_SENSOR_PIN);
    if (first < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    if (first != 0)            /* HIGH or timeout – no flame */
        return 0;

    /* Debounce: wait DEBOUNCE_MS and re-read */
    gpioDelay(DEBOUNCE_MS * 1000);   /* microseconds */

    int second = gpioRead(FLAME_SENSOR_PIN);
    if (second < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d during debounce.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    return (first == second && second == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    log_event("Program started");

    /* Initialise GPIO */
    if (init_gpio() < 0) {
        log_event("GPIO initialisation failed");
        fclose(g_log);
        return EXIT_FAILURE;
    }

    printf("Flame detection running.  DO=GPIO%d  PWM=GPIO%d  %d Hz\n",
           FLAME_SENSOR_PIN, FAN_PWM_PIN, PWM_FREQUENCY);
    printf("Press Ctrl+C to exit.\n");

    int fan_on = 0;
    time_t last_valid_read = time(NULL);

    while (g_running) {
        int flame = read_flame_sensor();

        if (flame < 0) {
            /* Read error – ensure fan is off for safety */
            if (fan_on) {
                gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF);
                fan_on = 0;
                log_event("Fan stopped (read error)");
            }
            last_valid_read = time(NULL);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        last_valid_read = time(NULL);

        if (flame && !fan_on) {
            if (gpioPWM(FAN_PWM_PIN, PWM_DUTY_ON) < 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n",
                        FAN_PWM_PIN);
                log_event("Fan PWM start failed");
            } else {
                fan_on = 1;
                log_event("Flame detected – fan started");
            }
        } else if (!flame && fan_on) {
            if (gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF) < 0) {
                fprintf(stderr, "Error: gpioPWM stop failed on GPIO%d.\n",
                        FAN_PWM_PIN);
                log_event("Fan PWM stop failed");
            } else {
                fan_on = 0;
                log_event("Flame cleared – fan stopped");
            }
        }

        /* Sensor-absent detection */
        if (difftime(time(NULL), last_valid_read) > SENSOR_TIMEOUT_S) {
            fprintf(stderr,
                    "Warning: no valid sensor reading for %d s – "
                    "check wiring/sensor presence.\n",
                    SENSOR_TIMEOUT_S);
            log_event("Warning: sensor timeout – possible sensor absent");
            last_valid_read = time(NULL);   /* reset to avoid spamming */
        }

        gpioDelay(POLL_MS * 1000);   /* 50 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");

    if (fan_on) {
        gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF);
        log_event("Fan stopped (shutdown)");
    }

    cleanup_gpio();
    log_event("Program stopped");

    if (fclose(g_log) != 0)
        perror("Warning: error closing log file");

    printf("Done.\n");
    return EXIT_SUCCESS;
}

