                FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                FAN_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n",
                FAN_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMrange(FAN_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n",
                FAN_PWM_PIN);
        return -1;
    }

    if (gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO%d.\n",
                FAN_PWM_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: stop PWM and reset pins */
    gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF);
    gpioSetMode(FAN_PWM_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Flame detection with debounce                                       */
/* ------------------------------------------------------------------ */
/*
 * Returns 1 if flame is confirmed (LOW), 0 if not, -1 on read error.
 */
static int read_flame_sensor(void)
{
    int first = gpioRead(FLAME_SENSOR_PIN);
    if (first < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    if (first != 0)            /* HIGH or timeout – no flame */
        return 0;

    /* Debounce: wait DEBOUNCE_MS and re-read */
    gpioDelay(DEBOUNCE_MS * 1000);   /* microseconds */

    int second = gpioRead(FLAME_SENSOR_PIN);
    if (second < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d during debounce.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    return (first == second && second == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    log_event("Program started");

    /* Initialise GPIO */
    if (init_gpio() < 0) {
        log_event("GPIO initialisation failed");
        fclose(g_log);
        return EXIT_FAILURE;
    }

    printf("Flame detection running.  DO=GPIO%d  PWM=GPIO%d  %d Hz\n",
           FLAME_SENSOR_PIN, FAN_PWM_PIN, PWM_FREQUENCY);
    printf("Press Ctrl+C to exit.\n");

    int fan_on = 0;
    time_t last_valid_read = time(NULL);

    while (g_running) {
        int flame = read_flame_sensor();

        if (flame < 0) {
            /* Read error – ensure fan is off for safety */
            if (fan_on) {
                gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF);
                fan_on = 0;
                log_event("Fan stopped (read error)");
            }
            last_valid_read = time(NULL);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        last_valid_read = time(NULL);

        if (flame && !fan_on) {
            if (gpioPWM(FAN_PWM_PIN, PWM_DUTY_ON) < 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO%d.\n",
                        FAN_PWM_PIN);
                log_event("Fan PWM start failed");
            } else {
                fan_on = 1;
                log_event("Flame detected – fan started");
            }
        } else if (!flame && fan_on) {
            if (gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF) < 0) {
                fprintf(stderr, "Error: gpioPWM stop failed on GPIO%d.\n",
                        FAN_PWM_PIN);
                log_event("Fan PWM stop failed");
            } else {
                fan_on = 0;
                log_event("Flame cleared – fan stopped");
            }
        }

        /* Sensor-absent detection */
        if (difftime(time(NULL), last_valid_read) > SENSOR_TIMEOUT_S) {
            fprintf(stderr,
                    "Warning: no valid sensor reading for %d s – "
                    "check wiring/sensor presence.\n",
                    SENSOR_TIMEOUT_S);
            log_event("Warning: sensor timeout – possible sensor absent");
            last_valid_read = time(NULL);   /* reset to avoid spamming */
        }

        gpioDelay(POLL_MS * 1000);   /* 50 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");

    if (fan_on) {
        gpioPWM(FAN_PWM_PIN, PWM_DUTY_OFF);
        log_event("Fan stopped (shutdown)");
    }

    cleanup_gpio();
    log_event("Program stopped");

    if (fclose(g_log) != 0)
        perror("Warning: error closing log file");

    printf("Done.\n");
    return EXIT_SUCCESS;
}

