/*
 * AWR1642 mmWave Radar SPI Interface for Raspberry Pi 4 Model B
 *
 * Captures range-Doppler heatmap frames from the TI AWR1642 via SPI
 * (CE0/GPIO8, 1 MHz, mode 0) using a hardware frame trigger on GPIO23
 * and a data-ready interrupt on GPIO24.
 *
 * Build: gcc -O2 -Wall -o radar_spi radar_spi.c -lrt -lpigpio -lpthread
 * Run:   sudo ./radar_spi
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 / GPIO8  */
#define SPI_SPEED        1000000    /* 1 MHz        */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define TRIGGER_PIN      23         /* BCM 23 - hardware frame trigger */
#define READY_PIN        24         /* BCM 24 - data-ready interrupt   */

#define LOG_FILE         "radar_data.bin"
#define LOG_MAGIC        0x4144     /* 'AD' */
#define LOG_HEADER_SIZE  64
#define LOG_FRAME_SIZE   32768      /* 256 chirps * 128 samples * 4 bytes */

#define FRAME_PERIOD_US  100000     /* 100 ms */

/* ----------------------------- Data Structures --------------------------- */

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint32_t frame_size;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t start_freq_ghz;
    uint32_t end_freq_ghz;
    uint32_t reserved[4];
} __attribute__((packed)) log_header_t;

typedef struct {
    uint32_t frame_number;
    struct timespec timestamp;
} __attribute__((packed)) frame_header_t;

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void ready_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  init_spi(void);
static int  init_gpio(void);
static int  init_log(void);
static void close_spi(void);
static void close_gpio(void);
static void close_log(void);
static int  read_frame(uint8_t *frame_data, size_t frame_size);
static int  log_frame(const uint8_t *frame_data, size_t frame_size);

/* ----------------------------- Signal Handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Data-Ready ISR ---------------------------- */

/*
 * pigpio dispatches ISRs on a dedicated thread, so we keep work minimal here.
 * We just set a flag that the main loop will pick up and trigger a full-duplex
 * SPI transfer to read the frame payload.
 */
static volatile sig_atomic_t g_data_ready = 0;

static void ready_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_data_ready = 1;
}

/* ----------------------------- SPI Init ---------------------------------- */

static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed: %s\n", pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/* ----------------------------- GPIO Init --------------------------------- */

static int init_gpio(void)
{
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(TRIGGER_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(READY_PIN) failed\n");
        return -1;
    }
    if (gpioSetPullUpDown(READY_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "[ERROR] gpioSetPullUpDown failed\n");
        return -1;
    }
    if (gpioSetAlertFuncEx(READY_PIN, ready_isr, NULL) < 0) {
        fprintf(stderr, "[ERROR] gpioSetAlertFuncEx failed\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- Log Init ---------------------------------- */

static int init_log(void)
{
    g_log_file = fopen(LOG_FILE, "wb");
    if (!g_log_file) {
        perror("[ERROR] fopen");
        return -1;
    }

    log_header_t header;
    memset(&header, 0, sizeof(header));
    header.magic        = LOG_MAGIC;
    header.version      = 1;
    header.frame_size   = LOG_FRAME_SIZE;
    header.num_chirps   = 64;
    header.num_samples  = 256;
    header.start_freq_ghz = 77;
    header.end_freq_ghz = 79;

    if (fwrite(&header, sizeof(header), 1, g_log_file) != 1) {
        perror("[ERROR] fwrite header");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void close_spi(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
}

static void close_gpio(void)
{
    gpioSetAlertFuncEx(READY_PIN, NULL, NULL);
    gpioSetPullUpDown(READY_PIN, PI_PUD_OFF);
    gpioSetMode(READY_PIN, PI_INPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
}

static void close_log(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ----------------------------- Frame Read -------------------------------- */

/*
 * Full-duplex SPI transfer: send a dummy frame to clock out the received
 * data.  The AWR1642 is configured to stream range-Doppler heatmap data
 * and the ready pin goes high when a new frame is ready.
 */
static int read_frame(uint8_t *frame_data, size_t frame_size)
{
    if (!frame_data || frame_size == 0) {
        fprintf(stderr, "[ERROR] read_frame: invalid arguments\n");
        return -1;
    }

    /*
     * Drive the hardware frame trigger high briefly to request a new frame.
     * The AWR1642 responds by pulling the data-ready pin high and then
     * clocking out the frame payload on the next SPI transaction.
     */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(TRIGGER_PIN, 1)\n");
        return -1;
    }
    gpioDelay(100); /* 100 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(TRIGGER_PIN, 0)\n");
        return -1;
    }

    /*
     * Wait for the data-ready pin to go high (frame is ready for readout).
     * We poll with a 100 us granularity so we can exit promptly on signal.
     */
    int ready_count = 0;
    while (g_running) {
        if (gpioRead(READY_PIN) == 1) break;
        gpioDelay(100);
        if (++ready_count > 1000) { /* ~100 ms timeout */
            fprintf(stderr, "[ERROR] Data-ready timeout\n");
            return -1;
        }
    }
    if (!g_running) return -1;

    /*
     * Full-duplex SPI transfer: send dummy bytes to clock out the received
     * data.  pigpio's spiXfer returns the number of bytes transferred, or
     * a negative error code.
     */
    uint8_t dummy[frame_size];
    memset(dummy, 0xAA, sizeof(dummy));
    int ret = spiXfer(g_spi_handle, (char *)dummy, (char *)frame_data, frame_size);
    if (ret != (int)frame_size) {
        fprintf(stderr, "[ERROR] spiXfer returned %d (expected %zu)\n",
                ret, frame_size);
        return -1;
    }
    return 0;
}

/* ----------------------------- Frame Log --------------------------------- */

static int log_frame(const uint8_t *frame_data, size_t frame_size)
{
    if (!frame_data || frame_size == 0) {
        fprintf(stderr, "[ERROR] log_frame: invalid arguments\n");
        return -1;
    }

    frame_header_t fhdr;
    memset(&fhdr, 0, sizeof(fhdr));
    clock_gettime(CLOCK_REALTIME, &fhdr.timestamp);
    fhdr.frame_number = 0; /* patched in after the per-frame write */

    if (pthread_mutex_lock(&g_log_mutex) != 0) {
        fprintf(stderr, "[ERROR] pthread_mutex_lock\n");
        return -1;
    }

    /* Write frame header */
    if (fwrite(&fhdr, sizeof(fhdr), 1, g_log_file) != 1) {
        perror("[ERROR] fwrite frame header");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    /* Write frame payload */
    if (fwrite(frame_data, frame_size, 1, g_log_file) != 1) {
        perror("[ERROR] fwrite frame data");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    /* Flush immediately so data survives a crash */
    if (fflush(g_log_file) != 0) {
        perror("[ERROR] fflush");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    /* Update frame number in-place (rewind to the frame header) */
    long pos = ftell(g_log_file);
    if (pos < 0) {
        perror("[ERROR] ftell");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }
    if (fseek(g_log_file, -(long)sizeof(fhdr), SEEK_CUR) != 0) {
        perror("[ERROR] fseek");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }
    fhdr.frame_number = (uint32_t)((pos - LOG_HEADER_SIZE) / LOG_FRAME_SIZE);
    if (fwrite(&fhdr, sizeof(fhdr), 1, g_log_file) != 1) {
        perror("[ERROR] fwrite frame header (update)");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }
    if (fseek(g_log_file, pos, SEEK_SET) != 0) {
        perror("[ERROR] fseek (restore)");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    pthread_mutex_unlock(&g_log_mutex);
    return 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        close_spi();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize log file */
    if (init_log() != 0) {
        close_spi();
        close_gpio();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Radar data acquisition started.\n");
    printf("  SPI channel : %d @ %d Hz, mode 0\n", SPI_CHANNEL, SPI_SPEED);
    printf("  Trigger pin : BCM %d\n", TRIGGER_PIN);
    printf("  Ready pin   : BCM %d\n", READY_PIN);
    printf("  Log file    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    uint8_t *frame_data = malloc(LOG_FRAME_SIZE);
    if (!frame_data) {
        fprintf(stderr, "[ERROR] malloc(%zu) failed\n", LOG_FRAME_SIZE);
        close_log();
        close_spi();
        close_gpio();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main acquisition loop */
    while (g_running) {
        if (g_data_ready) {
            g_data_ready = 0;

            if (read_frame(frame_data, LOG_FRAME_SIZE) == 0) {
                if (log_frame(frame_data, LOG_FRAME_SIZE) != 0) {
                    fprintf(stderr, "[WARN] log_frame failed, continuing\n");
                }
            } else {
                fprintf(stderr, "[WARN] read_frame failed, continuing\n");
            }
        }
        gpioDelay(FRAME_PERIOD_US);
    }

    /* Cleanup */
    free(frame_data);
    close_log();
    close_spi();
    close_gpio();
    gpioTerminate();

    printf("\nRadar data acquisition stopped.\n");
    return EXIT_SUCCESS;
}

