        fprintf(stderr, "[ERROR] gpioWrite(TRIGGER_PIN, 1)\n");
        return -1;
    }
    gpioDelay(100); /* 100 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(TRIGGER_PIN, 0)\n");
        return -1;
    }

    /*
     * Wait for the data-ready pin to go high (frame is ready for readout).
     * We poll with a 100 us granularity so we can exit promptly on signal.
     */
    int ready_count = 0;
    while (g_running) {
        if (gpioRead(READY_PIN) == 1) break;
        gpioDelay(100);
        if (++ready_count > 1000) { /* ~100 ms timeout */
            fprintf(stderr, "[ERROR] Data-ready timeout\n");
            return -1;
        }
    }
    if (!g_running) return -1;

    /*
     * Full-duplex SPI transfer: send dummy bytes to clock out the received
     * data.  pigpio's spiXfer returns the number of bytes transferred, or
     * a negative error code.
     */
    uint8_t dummy[frame_size];
    memset(dummy, 0xAA, sizeof(dummy));
    int ret = spiXfer(g_spi_handle, (char *)dummy, (char *)frame_data, frame_size);
    if (ret != (int)frame_size) {
        fprintf(stderr, "[ERROR] spiXfer returned %d (expected %zu)\n",
                ret, frame_size);
        return -1;
    }
    return 0;
}

/* ----------------------------- Frame Log --------------------------------- */

static int log_frame(const uint8_t *frame_data, size_t frame_size)
{
    if (!frame_data || frame_size == 0) {
        fprintf(stderr, "[ERROR] log_frame: invalid arguments\n");
        return -1;
    }

    frame_header_t fhdr;
    memset(&fhdr, 0, sizeof(fhdr));
    clock_gettime(CLOCK_REALTIME, &fhdr.timestamp);
    fhdr.frame_number = 0; /* patched in after the per-frame write */

    if (pthread_mutex_lock(&g_log_mutex) != 0) {
        fprintf(stderr, "[ERROR] pthread_mutex_lock\n");
        return -1;
    }

    /* Write frame header */
    if (fwrite(&fhdr, sizeof(fhdr), 1, g_log_file) != 1) {
        perror("[ERROR] fwrite frame header");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    /* Write frame payload */
    if (fwrite(frame_data, frame_size, 1, g_log_file) != 1) {
        perror("[ERROR] fwrite frame data");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    /* Flush immediately so data survives a crash */
    if (fflush(g_log_file) != 0) {
        perror("[ERROR] fflush");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    /* Update frame number in-place (rewind to the frame header) */
    long pos = ftell(g_log_file);
    if (pos < 0) {
        perror("[ERROR] ftell");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }
    if (fseek(g_log_file, -(long)sizeof(fhdr), SEEK_CUR) != 0) {
        perror("[ERROR] fseek");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }
    fhdr.frame_number = (uint32_t)((pos - LOG_HEADER_SIZE) / LOG_FRAME_SIZE);
    if (fwrite(&fhdr, sizeof(fhdr), 1, g_log_file) != 1) {
        perror("[ERROR] fwrite frame header (update)");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }
    if (fseek(g_log_file, pos, SEEK_SET) != 0) {
        perror("[ERROR] fseek (restore)");
        pthread_mutex_unlock(&g_log_mutex);
        return -1;
    }

    pthread_mutex_unlock(&g_log_mutex);
    return 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        close_spi();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize log file */
    if (init_log() != 0) {
        close_spi();
        close_gpio();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Radar data acquisition started.\n");
    printf("  SPI channel : %d @ %d Hz, mode 0\n", SPI_CHANNEL, SPI_SPEED);
    printf("  Trigger pin : BCM %d\n", TRIGGER_PIN);
    printf("  Ready pin   : BCM %d\n", READY_PIN);
    printf("  Log file    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    uint8_t *frame_data = malloc(LOG_FRAME_SIZE);
    if (!frame_data) {
        fprintf(stderr, "[ERROR] malloc(%zu) failed\n", LOG_FRAME_SIZE);
        close_log();
        close_spi();
        close_gpio();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main acquisition loop */
    while (g_running) {
        if (g_data_ready) {
            g_data_ready = 0;

            if (read_frame(frame_data, LOG_FRAME_SIZE) == 0) {
                if (log_frame(frame_data, LOG_FRAME_SIZE) != 0) {
                    fprintf(stderr, "[WARN] log_frame failed, continuing\n");
                }
            } else {
                fprintf(stderr, "[WARN] read_frame failed, continuing\n");
            }
        }
        gpioDelay(FRAME_PERIOD_US);
    }

    /* Cleanup */
    free(frame_data);
    close_log();
    close_spi();
    close_gpio();
    gpioTerminate();

    printf("\nRadar data acquisition stopped.\n");
    return EXIT_SUCCESS;
}

