/*
 * KY-026 Flame Sensor - State Change Logger
 * Board:  Raspberry Pi Zero W
 * Sensor: KY-026 digital output -> GPIO20 (BCM)
 * Library: pigpio (modern GPIO API)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_logger flame_logger.c -lpigpio -lrt
 * Run:    sudo ./flame_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        20          /* BCM pin number */
#define LOG_FILE        "flame_log.txt"
#define POLL_DELAY_US   100000      /* 100 ms */
#define TIMESTAMP_LEN   32

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the line is defined when the sensor
     * is disconnected or its output is low. */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", GPIO_PIN);
        /* Non-fatal: continue anyway. */
    }

    return 0;
}

/*
 * Read the digital state of the KY-026 sensor.
 * Returns 0 or 1 on success, -1 on read error.
 */
static int read_sensor_state(void)
{
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed.\n", GPIO_PIN);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int generate_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_utc;

    if (time(&rawtime) == (time_t)-1) {
        perror("time()");
        return -1;
    }
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        perror("gmtime_r()");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }
    return 0;
}

static int log_state_change(int state)
{
    char timestamp[TIMESTAMP_LEN];
    FILE *fp;

    if (generate_timestamp(timestamp, sizeof(timestamp)) != 0) {
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s - Flame %s\n", timestamp,
                state ? "Detected" : "Cleared") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state = -1;   /* unknown -> forces first log */
    int current_state;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d.\n", GPIO_PIN);
    printf("Logging state changes to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        current_state = read_sensor_state();
        if (current_state < 0) {
            /* Sensor read error — back off briefly and retry. */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (current_state != last_state) {
            if (log_state_change(current_state) != 0) {
                fprintf(stderr, "Warning: failed to log state change.\n");
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

