 *   Bit  11    : CT       = 0    -> 100 ms conversion time
 *   Bit  10    : M[1:0]   = 11   -> Continuous conversion mode
 *   Bits  9-8  : FC       = 00   -> No forced conversion
 *   Bit   7    : L        = 0    -> LN bit (conversion ready)
 *   Bit   6    : POL      = 0    -> Active low
 *   Bit   5    : ME       = 0    -> No mask
 *   Bits  4-0  : FH       = 00000 -> No fault
 *
 * Binary: 1111 0000 1100 0000 = 0xF0C0
 */
#define CONFIG_VALUE         0xF0C0

#define LOG_FILE             "light_data.txt"
#define SAMPLE_PERIOD_US     100000        /* 100 ms */
#define MAX_RETRIES          3

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Forward Declarations ------------------------ */

static void signal_handler(int sig);
static int  init_i2c(void);
static int  configure_sensor(void);
static int  read_lux(float *lux_out);
static int  log_data(float lux);
static void cleanup(void);

/* ------------------------------- Handlers -------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------ I2C Setup -------------------------------- */

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d).\n",
                g_i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void)
{
    /*
     * i2cWriteWordData sends the 16-bit value as [reg_addr, data_hi, data_lo]
     * on the I2C bus, which is the correct order for the OPT3001.
     */
    int rc = i2cWriteWordData(g_i2c_handle, REG_CONFIGURATION, CONFIG_VALUE);
    if (rc < 0) {
        fprintf(stderr, "Error: Failed to write configuration register "
                        "(pigpio error %d).\n", rc);
        return -1;
    }
    return 0;
}

/* ------------------------------ Lux Reading ------------------------------ */

static int read_lux(float *lux_out)
{
    int raw;
    int rc;
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadWordData(g_i2c_handle, REG_RESULT);
        if (rc >= 0) {
            raw = rc;
            break;
        }
        fprintf(stderr, "Warning: I2C read failed (attempt %d/%d, "
                        "pigpio error %d).\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000); /* 10 ms back-off */
    }

    if (attempt >= MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to read result register after %d "
                        "attempts.\n", MAX_RETRIES);
        return -1;
    }

    /*
     * OPT3001 result register layout (16-bit, big-endian on the wire):
     *   Bits 15-12 : FL[3:0]  -> Fault count
     *   Bits 11-0  : RES[11:0] -> Result code
     *
     * The exponent is bits [11:4] and the mantissa is bits [3:0].
     * lux = 0.01 * 2^(RES[11:4]) * (1 + RES[3:0])
     */
    uint16_t res = (uint16_t)raw;
    int exponent = (res >> 4) & 0x0FF;
    int mantissa = res & 0x0F;

    *lux_out = 0.01f * (float)(1 << exponent) * (float)(1 + mantissa);
    return 0;
}

/* ------------------------------ Data Logging ----------------------------- */

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&t, &tm_buf);
    char ts[32];
    if (tm == NULL || strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, %.2f lux\n", ts, lux);
    fclose(fp);
    return 0;
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure the sensor */
    if (configure_sensor() != 0) {
        fprintf(stderr, "Error: Sensor configuration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3001 logger started. Logging to %s every 100 ms.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float lux;

        if (read_lux(&lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read lux value.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

