/*
 * TTP226 8-channel digital touch sensor reader for Raspberry Pi Zero W.
 *
 * Wiring (TTP226 OUT1..OUT8 -> BCM GPIO 2..9):
 *   OUT1 -> GPIO2  OUT2 -> GPIO3  OUT3 -> GPIO4  OUT4 -> GPIO5
 *   OUT5 -> GPIO6  OUT6 -> GPIO7  OUT7 -> GPIO8  OUT8 -> GPIO9
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int gpio_pins[NUM_CHANNELS] = {
    2, 3, 4, 5, 6, 7, 8, 9
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_acquired[NUM_CHANNELS] = {0};
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default GPIO chip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as an input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: failed to get GPIO line %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Error: failed to request GPIO line %u as input: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
        line_acquired[i] = 1;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Channels: OUT1=GPIO2 OUT2=GPIO3 OUT3=GPIO4 OUT4=GPIO5 "
           "OUT5=GPIO6 OUT6=GPIO7 OUT7=GPIO8 OUT8=GPIO9\n");
    fflush(stdout);

    while (program_running) {
        print_timestamp();

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error: failed to read GPIO line %u: %s\n",
                        gpio_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("CH%d=%d ", i + 1, val);
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (line_acquired[i] && lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

