/*
 * TTP226 8-channel touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (TTP226 OUT1..OUT8 -> BCM GPIO 2..9):
 *   OUT1 -> GPIO2  OUT2 -> GPIO3  OUT3 -> GPIO4  OUT4 -> GPIO5
 *   OUT5 -> GPIO6  OUT6 -> GPIO7  OUT7 -> GPIO8  OUT8 -> GPIO9
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lpigpio -lrt
 * Run:    sudo ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_US   100000          /* 100 ms sampling interval */

/* BCM GPIO numbers for the TTP226 OUT1..OUT8 pins */
static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = sensor_pins[i];

        if (gpioSetMode(pin, PI_INPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM GPIO %d.\n", pin);
            gpioTerminate();
            return -1;
        }

        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for BCM GPIO %d.\n", pin);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_ttp226(int *values)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int v = gpioRead(sensor_pins[i]);
        if (v < 0) {
            fprintf(stderr, "Error: gpioRead failed on BCM GPIO %d.\n",
                    sensor_pins[i]);
            return -1;
        }
        values[i] = v;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor reader started.\n");
    printf("Sampling every %d us on BCM GPIO 2..9. Press Ctrl+C to exit.\n",
           SAMPLE_US);
    fflush(stdout);

    int values[NUM_CHANNELS];
    uint32_t elapsed = 0;

    while (g_running) {
        if (read_ttp226(values) != 0) {
            fprintf(stderr, "Fatal: TTP226 read error.\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("[+%6u us] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               elapsed,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        elapsed += SAMPLE_US;
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly.\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

