/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (physical pin 29)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND  (physical pin 9)
 *
 * The TMAG5110 outputs are open-drain with external pull-up resistors.
 *   - When the magnet is away, the output is HIGH (pulled up by the resistor).
 *   - When the magnet is present, the output is LOW (the magnet pulls the
 *     output line to GND).
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:
 *   sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static const char *state_str(int level)
{
    /*
     * TMAG5110 open-drain output:
     *   HIGH  -> magnet absent (pulled up by external resistor)
     *   LOW   -> magnet present (output pulled to GND by magnet)
     */
    return (level == 0) ? "HIGH" : "LOW";
}

int main(void)
{
    int ret;

    /* --- Initialize pigpio library --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        fprintf(stderr, "       Is the pigpio daemon running? Stop it first with 'sudo killall pigpiod'.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs --- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set up signal handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("  Sensor 1: BCM GPIO%d\n", SENSOR_1_GPIO);
    printf("  Sensor 2: BCM GPIO%d\n", SENSOR_2_GPIO);
    printf("  Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        printf("Sensor 1: %-4s  |  Sensor 2: %-4s\n",
               state_str(s1), state_str(s2));
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\npigpio terminated. Exiting.\n");
    return EXIT_SUCCESS;
}

