code:
/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   Channel 0 -> BCM 2  (physical pin 3)
 *   Channel 1 -> BCM 3  (physical pin 5)
 *   Channel 2 -> BCM 4  (physical pin 7)
 *   Channel 3 -> BCM 17 (physical pin 11)
 *   Channel 4 -> BCM 27 (physical pin 13)
 *   Channel 5 -> BCM 22 (physical pin 15)
 *   Channel 6 -> BCM 10 (physical pin 19)
 *   Channel 7 -> BCM 9  (physical pin 21)
 *
 * Each channel is read as a simple digital input (bias disabled).
 * The program polls every 50 ms and writes an ISO-8601 timestamped CSV line
 * to stdout.  Press Ctrl-C to exit cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000          /* 50 ms */

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a heap-allocated ISO-8601 timestamp string (caller frees).  */
static char *get_timestamp(void)
{
    time_t rawtime;
    struct tm tm_info;
    char *buf = malloc(25);
    if (!buf) {
        perror("malloc");
        return NULL;
    }

    time(&rawtime);
    if (!localtime_r(&rawtime, &tm_info)) {
        perror("localtime_r");
        free(buf);
        return NULL;
    }

    if (strftime(buf, 25, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        free(buf);
        return NULL;
    }
    return buf;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int gpio_handles[NUM_CHANNELS];
    int rc;

    /* ---- Install SIGINT handler for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Request each GPIO line as input with bias disabled ---- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpio_handles[i] = gpioRequestLine(sensor_pins[i], PI_INPUT, 0);
        if (gpio_handles[i] < 0) {
            fprintf(stderr, "Failed to request GPIO line %d (BCM %d): %s\n",
                    i, sensor_pins[i], pigpio_error(gpio_handles[i]));
            /* Release any lines already requested */
            for (int j = 0; j < i; j++)
                gpioReleaseLine(gpio_handles[j]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 reader started.  Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        char *ts = get_timestamp();
        if (!ts) {
            /* Timestamp allocation failed; skip this sample */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("%s,", ts);
        free(ts);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = gpioRead(gpio_handles[i]);
            if (state < 0) {
                fprintf(stderr, "Warning: gpioRead failed on channel %d (BCM %d): %s\n",
                        i, sensor_pins[i], pigpio_error(state));
                printf("-1,");
            } else {
                printf("%d,", state);
            }
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_CHANNELS; i++)
        gpioReleaseLine(gpio_handles[i]);

    gpioTerminate();
    return EXIT_SUCCESS;
}

