/*
 * Raspberry Pi Zero W - Omron D7E-1 Tilt Sensor Monitor
 *
 * Wiring:
 *   Omron D7E-1 VCC  -> 3.3 V (Pin 1)
 *   Omron D7E-1 GND  -> GND    (Pin 9)
 *   Omron D7E-1 OUT  -> GPIO4 (BCM 7, Pin 26)
 *
 * The D7E-1 output is active-LOW: LOW  = tilted, HIGH = not tilted.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_PIN 4          /* BCM 4 / GPIO4 (Pin 7) */
#define POLL_DELAY_US   100000     /* 100 ms */
#define MAIN_LOOP_RET   0          /* normal exit code */
#define ERR_EXIT        1          /* error exit code */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for SIGINT / SIGTERM                                 */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return ERR_EXIT;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return ERR_EXIT;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return ERR_EXIT;
    }

    /* ---- Configure GPIO4 as input with internal pull-up ---- */
    if (gpioSetMode(TILT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n",
                TILT_SENSOR_PIN);
        gpioTerminate();
        return ERR_EXIT;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n",
                TILT_SENSOR_PIN);
        gpioTerminate();
        return ERR_EXIT;
    }

    /* ---- Print startup banner ---- */
    printf("Tilt sensor monitoring started on GPIO%d (BCM).\n",
           TILT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    bool last_tilted = false;

    while (g_running) {
        int level = gpioRead(TILT_SENSOR_PIN);

        if (level < 0) {
            fprintf(stderr,
                    "Error: gpioRead failed on pin %d (rc=%d).\n",
                    TILT_SENSOR_PIN, level);
            gpioTerminate();
            return ERR_EXIT;
        }

        /* D7E-1 output is active-LOW: LOW  = tilted, HIGH = not tilted */
        bool tilted = (level == 0);

        if (tilted != last_tilted) {
            printf("Tilted: %s\n", tilted ? "YES" : "NO");
            fflush(stdout);
            last_tilted = tilted;
        }

        gpioDelay(POLL_DELAY_US);   /* 100 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return MAIN_LOOP_RET;
}

