#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_I2C_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "uv_als_log.csv"

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_REV_ID 0x01
#define SI1145_REG_SEQ_ID 0x02
#define SI1145_REG_INT_CFG 0x03
#define SI1145_REG_IRQ_ENABLE 0x04
#define SI1145_REG_IRQ_MODE1 0x05
#define SI1145_REG_IRQ_MODE2 0x06
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_RATE 0x0A
#define SI1145_REG_ALS_IR_RATE 0x0B
#define SI1145_REG_ALS_VIS_RATE 0x0C
#define SI1145_REG_ALS_IR_ADC_MISC 0x0D
#define SI1145_REG_ALS_VIS_ADC_MISC 0x0E
#define SI1145_REG_ALS_IR_DATA0 0x10
#define SI1145_REG_ALS_IR_DATA1 0x11
#define SI1145_REG_ALS_VIS_DATA0 0x12
#define SI1145_REG_ALS_VIS_DATA1 0x13
#define SI1145_REG_UVINDEX_DATA0 0x14
#define SI1145_REG_UVINDEX_DATA1 0x15
#define SI1145_REG_COMMAND 0x18

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_PS_FORCE 0x07

#define SI1145_PART_ID 0x45

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write reg failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_reg8: read failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write reg failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read failed");
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_IR_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_VIS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_IR_ADC_MISC, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_VIS_ADC_MISC, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_INT_CFG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_uv_index(int fd, float *uv_index) {
    uint16_t raw;
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    usleep(10000);
    if (i2c_read_reg16(fd, SI1145_REG_UVINDEX_DATA0, &raw) < 0) return -1;
    *uv_index = (float)raw / 100.0f;
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    usleep(10000);
    if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, als_visible) < 0) return -1;
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - UV Index: %.2f, Ambient Light: %u\n", timestamp, uv_index, als_visible);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
        fflush(log_file);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,Ambient Light\n");
        fflush(log_file);
    }

    while (running) {
        float uv_index;
        uint16_t als_visible;

        if (read_uv_index(i2c_fd, &uv_index) < 0) {
            fprintf(stderr, "Error reading UV index.\n");
        } else if (read_als_visible(i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error reading ambient light.\n");
        } else {
            log_data(uv_index, als_visible);
        }

        sleep(1);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

