/*
 * Raspberry Pi 5 - Dual SLF3S-0600F Flow Sensor Monitor
 *
 * Reads flow rates from two Sensirion SLF3S-0600F sensors on /dev/i2c-1
 * (addresses 0x6B and 0x6A), averages them, and drives an alarm on GPIO17
 * when the average falls below 0.5 ml/min.  Logs the average to
 * flow_log.txt every second.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lgpiod
 *
 * Wiring:
 *   Sensor 1  SDA -> GPIO2  (I2C bus 1)
 *   Sensor 1  SCL -> GPIO3  (I2C bus 1)
 *   Sensor 1  VDD -> 3.3 V
 *   Sensor 1  GND -> GND
 *   Sensor 2  SDA -> GPIO2  (I2C bus 1)
 *   Sensor 2  SCL -> GPIO3  (I2C bus 1)
 *   Sensor 2  VDD -> 3.3 V
 *   Sensor 2  GND -> GND
 *   Alarm    IN -> GPIO17  (BCM)
 *   Alarm    GND -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define SENSOR1_ADDR     0x6B
#define SENSOR2_ADDR     0x6A
#define ALARM_GPIO       17
#define FLOW_THRESHOLD   0.5f   /* ml/min */
#define LOG_FILE         "flow_log.txt"
#define SAMPLE_PERIOD_S  1
#define STARTUP_DELAY_MS 100

/* Sensirion SLF3x: continuous measurement command (MSB, LSB) */
static const uint8_t CMD_START_MEASUREMENT[2] = {0x36, 0x1E};

/* Sensirion SLF3x: read measurement command (MSB, LSB) */
static const uint8_t CMD_READ_MEASUREMENT[2]  = {0x36, 0x08};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Sensirion 8-bit CRC (polynomial 0x31, init 0xFF).
 * Used by the Sensirion SLF3x family.
 */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Write a 2-byte command to the sensor.
 * Returns 0 on success, -1 on error.
 */
static int sensor_write_cmd(int fd, const uint8_t cmd[2])
{
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n",
                cmd[0], cmd[1], strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read 3 bytes (2 data + 1 CRC) from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int sensor_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Start continuous measurement on the sensor.
 * Returns 0 on success, -1 on error.
 */
static int sensor_start_measurement(int fd)
{
    return sensor_write_cmd(fd, CMD_START_MEASUREMENT);
}

/*
 * Read the latest flow rate from the sensor.
 * Returns 0 on success and stores the flow rate in *out_flow,
 * -1 on I2C or CRC error.
 */
static int sensor_read_flow(int fd, float *out_flow)
{
    uint8_t buf[3];

    if (sensor_write_cmd(fd, CMD_READ_MEASUREMENT) < 0)
        return -1;

    /* Datasheet: max conversion time ~45 ms; 50 ms is safe */
    struct timespec ts = {0, 50 * 1000 * 1000};
    nanosleep(&ts, NULL);

    if (sensor_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_flow = (float)raw / 100.0f;  /* ml/min */
    return 0;
}

/*
 * Log a flow reading to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_flow_rate(FILE *log_fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s, Flow Rate: %.2f ml/min\n", ts, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int ret = EXIT_FAILURE;
    int fd1 = -1, fd2 = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *alarm_line = NULL;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus --- */
    fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Cannot open %s (dup): %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SENSOR1_ADDR, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SENSOR2_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request alarm line --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: try gpiochip0 on older kernels */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        goto cleanup;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                ALARM_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(alarm_line, "flow_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Start continuous measurement on both sensors --- */
    if (sensor_start_measurement(fd1) < 0) {
        fprintf(stderr, "Failed to start sensor 1 measurement\n");
        goto cleanup;
    }
    if (sensor_start_measurement(fd2) < 0) {
        fprintf(stderr, "Failed to start sensor 2 measurement\n");
        goto cleanup;
    }

    /* First measurement is ready after ~50 ms; wait before first sample */
    struct timespec startup = {0, STARTUP_DELAY_MS * 1000 * 1000};
    nanosleep(&startup, NULL);

    /* --- Main loop --- */
    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        bool ok1 = false, ok2 = false;

        ok1 = (sensor_read_flow(fd1, &flow1) == 0);
        ok2 = (sensor_read_flow(fd2, &flow2) == 0);

        if (ok1 && ok2) {
            float avg = (flow1 + flow2) / 2.0f;

            if (log_flow_rate(log_fp, avg) < 0)
                fprintf(stderr, "Logging failed for this cycle\n");

            if (gpiod_line_set_value(alarm_line, (avg < FLOW_THRESHOLD) ? 1 : 0) < 0)
                fprintf(stderr, "gpiod_line_set_value failed: %s\n",
                        strerror(errno));
        } else {
            if (!ok1)
                fprintf(stderr, "Sensor 1 read failed; skipping this cycle\n");
            if (!ok2)
                fprintf(stderr, "Sensor 2 read failed; skipping this cycle\n");

            /* Ensure alarm is off on sensor failure */
            if (gpiod_line_set_value(alarm_line, 0) < 0)
                fprintf(stderr, "gpiod_line_set_value failed: %s\n",
                        strerror(errno));
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release resources in reverse order --- */
    if (alarm_line)
        gpiod_line_release(alarm_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);
    if (fd1 >= 0)
        close(fd1);
    if (fd2 >= 0)
        close(fd2);

    return ret;
}

