/*
 * KY-033 Obstacle Avoidance Sensor Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: KY-033 (digital output)
 * Wiring:
 *   VCC  -> 3.3 V (pin 1)
 *   GND  -> GND  (pin 6)
 *   OUT  -> GPIO4 / BCM 7 (pin 24)
 *
 * The module drives the output LOW when an obstacle is detected
 * within the module's threshold, HIGH otherwise.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky033_monitor ky033_monitor.c -lpigpio -lrt
 * Run:    sudo ./ky033_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM 4, physical pin 7 */
#define BUFFER_SIZE     100
#define SAMPLE_PERIOD_US 50000     /* 50 ms */

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
typedef struct {
    bool      obstacle_detected;
    struct timespec timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;          /* next write slot */
    int count;         /* number of valid entries */
} circular_buffer_t;

static circular_buffer_t g_buffer;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer operations                                          */
/* ------------------------------------------------------------------ */
static void buffer_init(circular_buffer_t *buf)
