/*
 * Raspberry Pi 5 - Omron D7S vibration sensor monitor (I2C)
 *
 * Wiring:
 *   D7S VCC  -> 3.3 V (Pin 1)
 *   D7S GND  -> GND   (Pin 9)
 *   D7S SDA  -> GPIO2 (BCM 2, Pin 3)
 *   D7S SCL  -> GPIO3 (BCM 3, Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_monitor fan_monitor.c -lm
 * Run:    ./fan_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (from the datasheet) ---- */
#define D7S_I2C_ADDR        0x2A          /* default 7-bit address */
#define D7S_REG_MODE        0x00          /* mode control register  */
#define D7S_REG_X_LSB       0x01          /* X-axis acceleration   */
#define D7S_REG_Y_LSB       0x03          /* Y-axis acceleration   */
#define D7S_REG_Z_LSB       0x05          /* Z-axis acceleration   */
#define D7S_MODE_ACTIVE     0x01          /* standby -> active mode */
#define D7S_MODE_STANDBY    0x00          /* active  -> standby mode */
#define D7S_ACTIVE_TIMEOUT  1000          /* ms to wait for sensor to become active */
#define POLL_INTERVAL_MS    500           /* polling interval */
#define CSV_FILENAME        "fan_health.csv"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv    = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a D7S register; returns 0 on success, -1 on error. */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a D7S register; returns 0 on success, -1 on error. */
static int d7s_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    /* Select the register */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian axis value from two consecutive registers. */
static int d7s_read_axis(int fd, uint8_t lsb_reg, int16_t *out)
{
    uint8_t lo, hi;
    if (d7s_read_reg(fd, lsb_reg, &lo) != 0)
        return -1;
    if (d7s_read_reg(fd, lsb_reg + 1, &hi) != 0)
        return -1;
    *out = (int16_t)((uint16_t)hi << 8 | (uint16_t)lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int d7s_set_mode(int fd, uint8_t mode)
{
    return d7s_write_reg(fd, D7S_REG_MODE, mode);
}

/* ------------------------------------------------------------------ */
static int d7s_wait_active(int fd)
{
    for (int elapsed = 0; elapsed < D7S_ACTIVE_TIMEOUT; elapsed += 50) {
        uint8_t mode;
        if (d7s_read_reg(fd, D7S_REG_MODE, &mode) != 0)
            return -1;
        if (mode == D7S_MODE_ACTIVE)
            return 0;
        msleep(50);
    }
    fprintf(stderr, "D7S did not become active within %d ms\n",
            D7S_ACTIVE_TIMEOUT);
    return -1;
}

/* ------------------------------------------------------------------ */
static int csv_write_header_if_new(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,x,y,z\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int csv_write_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *tm = localtime_r(&t, &tm_buf);
    if (!tm) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf sample failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush sample failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor back in standby before closing */
        (void)d7s_set_mode(g_i2c_fd, D7S_MODE_STANDBY);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (BCM pins 2/3) */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (csv_write_header_if_new(g_csv) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Put sensor in standby so we can configure it */
    if (d7s_set_mode(g_i2c_fd, D7S_MODE_STANDBY) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    msleep(10);

    /* Configure sensor: enable X, Y, Z axes (bits 0-2) and set range (bits 4-5) */
    if (d7s_write_reg(g_i2c_fd, 0x02, 0x07) != 0) {
        fprintf(stderr, "Failed to configure sensor axes/range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set to active mode */
    if (d7s_set_mode(g_i2c_fd, D7S_MODE_ACTIVE) != 0) {
        fprintf(stderr, "Failed to set active mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wait for the sensor to report it is active */
    if (d7s_wait_active(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor did not become active; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("D7S monitoring started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (d7s_read_axis(g_i2c_fd, D7S_REG_X_LSB, &x) != 0 ||
            d7s_read_axis(g_i2c_fd, D7S_REG_Y_LSB, &y) != 0 ||
            d7s_read_axis(g_i2c_fd, D7S_REG_Z_LSB, &z) != 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle.\n");
            msleep(POLL_INTERVAL_MS);
            continue;
        }

        if (csv_write_sample(g_csv, x, y, z) != 0) {
            fprintf(stderr, "CSV write error; continuing.\n");
        }

        msleep(POLL_INTERVAL_MS);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

