/*
 * Raspberry Pi 4 Model B – Dual KY-032 IR Obstacle Avoidance Monitor
 *
 * Wiring:
 *   Sensor 1 OUT  -> GPIO23 (BCM)
 *   Sensor 2 OUT  -> GPIO24 (BCM)
 *   LED anode     -> GPIO25 (BCM) via 220-330 ohm resistor to GND
 *
 * Behavior:
 *   Polls both sensors every 100 ms.  When either reads LOW (active-LOW
 *   sensor) an obstacle is detected; the LED illuminates.  Only when both
 *   read HIGH does the LED turn off.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ky032_monitor ky032_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./ky032_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN      25

#define POLL_DELAY_US 100000          /* 100 ms */
#define DEBOUNCE_DELAY_US 50000       /* 50 ms  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc = EXIT_SUCCESS;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        safe_set_mode(LED_PIN,      PI_OUTPUT) != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            rc = EXIT_FAILURE;
            break;
        }

        /* KY-032 modules are active-LOW: LOW means obstacle detected. */
        bool obstacle = (s1 == 0 || s2 == 0);

        if (safe_write(LED_PIN, obstacle ? 1 : 0) != 0) {
            rc = EXIT_FAILURE;
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* ---- Clean resource release on every exit path ---- */
    safe_write(LED_PIN, 0);          /* best-effort LED off */
    gpioTerminate();
    return rc;
}

