#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define STALL_DURATION_SEC 2
#define POLL_INTERVAL_US 100000
#define LOG_FILE "stall_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int log_stall_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring conveyor belt for stalls... Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (s1 == 0 && s2 == 0) {
            time_t start_time = time(NULL);
            int stall_confirmed = 1;

            while (running) {
                int s1_curr = read_sensor(SENSOR_1_PIN);
                int s2_curr = read_sensor(SENSOR_2_PIN);

                if (s1_curr < 0 || s2_curr < 0) {
                    fprintf(stderr, "Sensor read error during stall check, aborting...\n");
                    stall_confirmed = 0;
                    break;
                }

                if (s1_curr != 0 || s2_curr != 0) {
                    stall_confirmed = 0;
                    break;
                }

                if (difftime(time(NULL), start_time) >= STALL_DURATION_SEC) {
                    break;
                }

                gpioDelay(POLL_INTERVAL_US);
            }

            if (stall_confirmed) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    if (log_stall_event(timestamp) == 0) {
                        printf("Stall detected and logged: %s\n", timestamp);
                    } else {
                        fprintf(stderr, "Failed to log stall event.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to get timestamp.\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

