/*
 * TMAG5170 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMAG5170 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   TMAG5170 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   TMAG5170 VDD  -> 3.3 V (pin 1)
 *   TMAG5170 GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mag_logger mag_logger.c -lm
 *
 * Run:
 *   ./mag_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- TMAG5170 I2C address ---- */
#define TMAG5170_ADDR 0x48

/* ---- TMAG5170 register addresses ---- */
#define TMAG5170_REG_DEVICE_CONFIG  0x00
#define TMAG5170_REG_SENSOR_CONFIG  0x01
#define TMAG5170_REG_X_CH_RESULT   0x02
#define TMAG5170_REG_Y_CH_RESULT   0x04
#define TMAG5170_REG_Z_CH_RESULT   0x06

/* ---- TMAG5170 register values ---- */
#define TMAG5170_DEV_CONFIG_DEFAULT 0x0000  /* continuous, no sleep */
#define TMAG5170_SENSOR_CONFIG_50MT 0x0000  /* 50 mT range, all axes */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMAG5170 register                         */
/* ------------------------------------------------------------------ */
static int tmag_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%04X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMAG5170 register                        */
/* ------------------------------------------------------------------ */
static int tmag_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)(((uint8_t)data_buf[1] << 8) | (uint8_t)data_buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the TMAG5170 for continuous-conversion mode               */
/* ------------------------------------------------------------------ */
static int tmag_configure(int handle)
{
    if (tmag_write_reg16(handle, TMAG5170_REG_DEVICE_CONFIG,
                         TMAG5170_DEV_CONFIG_DEFAULT) != 0)
        return -1;

    if (tmag_write_reg16(handle, TMAG5170_REG_SENSOR_CONFIG,
                         TMAG5170_SENSOR_CONFIG_50MT) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X, Y, Z magnetic field values (raw 16-bit)                    */
/* ------------------------------------------------------------------ */
static int tmag_read_xyz(int handle, uint16_t *x, uint16_t *y, uint16_t *z)
{
    if (tmag_read_reg16(handle, TMAG5170_REG_X_CH_RESULT, x) != 0)
        return -1;
    if (tmag_read_reg16(handle, TMAG5170_REG_Y_CH_RESULT, y) != 0)
        return -1;
    if (tmag_read_reg16(handle, TMAG5170_REG_Z_CH_RESULT, z) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV row with an ISO-8601 timestamp                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t x, uint16_t y, uint16_t z)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at TMAG5170_ADDR ---- */
    g_i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                TMAG5170_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor ---- */
    if (tmag_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMAG5170 configuration failed — sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
