#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define RETRY_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", timestamp, message);
    } else {
        fprintf(fp, "<unknown-time> %s\n", message);
    }
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN);
    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        log_event("ERROR: GPIO initialization failed, exiting");
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);
    log_event("INFO: Water level monitoring started");

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", SENSOR_PIN);
            log_event("ERROR: GPIO read failed, attempting re-initialization");
            cleanup_gpio();
            sleep(RETRY_INTERVAL_SEC);
            if (initialize_gpio() != 0) {
                log_event("ERROR: Re-initialization failed, exiting");
                return EXIT_FAILURE;
            }
            continue;
        }

        if (level == 1) {
            printf("ALERT: Water detected!\n");
            log_event("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup_gpio();
    log_event("INFO: Water level monitoring stopped");
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

