/*
 * MLX90217 RPM reader for Raspberry Pi 4 Model B (Bookworm+)
 *
 * Wiring:
 *   MLX90217 VCC  -> 3V3 (pin 1)
 *   MLX90217 GND  -> GND (pin 9)
 *   MLX90217 OUT  -> BCM GPIO4 (pin 7)
 *
 * The MLX90217 output is a digital Hall signal that pulses high
 * when the magnet moves into the sensor's field and low when it
 * moves out.  We configure GPIO4 as input with the internal pull-up
 * enabled so the line idles high and reads reliably even if the
 * sensor is disconnected.  We sample one second of pulses using
 * pigpio's hardware-timed alert callback, compute RPM, and log
 * one sample per second to rpm_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rpm_reader rpm_reader.c -lpigpio -lrt
 * Run:    sudo ./rpm_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE        "rpm_log.txt"
#define SAMPLE_PERIOD_S 1.0        /* seconds between log entries */
#define WINDOW_S        1.0        /* pulse-counting window       */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static FILE                 *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio's notification thread)        */
/* ------------------------------------------------------------------ */

static void pulse_alert_cb(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == 1) {                 /* rising edge */
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Disable the alert callback first so no more pulses arrive. */
    if (gpioSetAlertFunc(SENSOR_PIN, NULL) != 0) {
        fprintf(stderr, "Warning: failed to disable alert on GPIO%d\n",
                SENSOR_PIN);
    }

    /* Cancel the timer so the main loop exits promptly. */
    if (gpioSetTimerFunc(0, 0, NULL) != 0) {
        fprintf(stderr, "Warning: failed to cancel timer 0\n");
    }

    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- open log file ---------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers -------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin -------------------------------------- */
