    if (gpioSetAlertFunc(SENSOR_PIN, pulse_alert_cb) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(%d) failed.\n",
                SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- start one-second timer ------------------------------------ */
    if (gpioSetTimerFunc(0, (int)(SAMPLE_PERIOD_S * 1000.0), NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFunc(0) failed.\n");
        cleanup();
        return EXIT_FAILURE;
