        rem.tv_nsec = (long)((SAMPLE_PERIOD_S - (time_t)SAMPLE_PERIOD_S)
                             * 1e9);
        while (nanosleep(&rem, &rem) != 0 && g_running) {
            /* retry on EINTR */
        }
    }

    /* ---- graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

