/*
 * Quadrature Hall-effect sensor logger for Raspberry Pi Zero W.
 *
 * Two Melexis MLX90217 unipolar Hall-effect sensors are wired to two
 * BCM GPIO pins (17 and 27) with external pull-up resistors providing
 * the 90-degree electrical offset needed for quadrature decoding.
 *
 * The program uses the pigpio library's edge-triggered alert callbacks
 * to detect rising and falling edges on each sensor line, infers
 * direction by tracking the quadrature state, and logs each edge
 * event with millisecond-precision timestamps to rotation_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rotation_logger rotation_logger.c -lpigpio -lpthread
 * Run:    sudo ./rotation_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE_NAME "rotation_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state                                                       */
/* ------------------------------------------------------------------ */

typedef struct {
    int  a_level;          /* last level on SENSOR_A_PIN                */
    int  b_level;          /* last level on SENSOR_B_PIN                */
    int  quad_state;       /* 0..3 quadrature state                     */
    bool valid;            /* true once first edge is captured          */
} sensor_state_t;

static sensor_state_t  g_sensor_state = {0, 0, 0, false};
static pthread_mutex_t g_mutex        = PTHREAD_MUTEX_INITIALIZER;
static FILE           *g_log_file     = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01 00:00:00.000");
        return;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000L);
}

static void log_rotation(int direction)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_file) {
        fprintf(g_log_file, "%s: %s\n", ts,
                direction > 0 ? "Clockwise" : "Counter-clockwise");
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio's notification thread)        */
/* ------------------------------------------------------------------ */

static void sensor_alert_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)tick;
    (void)userdata;

    if (level < 0 || level > 1) {
        /* pigpio may call us with level == 2 for a timeout; ignore. */
        return;
    }

    pthread_mutex_lock(&g_mutex);

    int prev_a = g_sensor_state.a_level;
    int prev_b = g_sensor_state.b_level;
    int prev_state = g_sensor_state.quad_state;

    if (gpio == SENSOR_A_PIN)
        g_sensor_state.a_level = level;
    else if (gpio == SENSOR_B_PIN)
        g_sensor_state.b_level = level;

    /*
     * Quadrature decoding:
     *   state 0 -> 1 -> 2 -> 3 -> 0
     *   rising A  ->  rising B  ->  falling A  ->  falling B
     *   rising B  ->  rising A  ->  falling B  ->  falling A
     */
    int direction = 0;

    if (g_sensor_state.valid) {
        if (gpio == SENSOR_A_PIN) {
            if (level == 1 && prev_b == 0) {
                g_sensor_state.quad_state = 1;
                direction = 1;
            } else if (level == 0 && prev_b == 1) {
                g_sensor_state.quad_state = 3;
                direction = -1;
            }
        } else if (gpio == SENSOR_B_PIN) {
            if (level == 1 && prev_a == 0) {
                g_sensor_state.quad_state = 2;
                direction = 1;
            } else if (level == 0 && prev_a == 1) {
                g_sensor_state.quad_state = 0;
                direction = -1;
            }
        }
    }

    g_sensor_state.valid = true;

    pthread_mutex_unlock(&g_mutex);

    if (direction != 0)
        log_rotation(direction);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO pins ---- */
    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_A_PIN);
        goto fail_gpio;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_B_PIN);
        goto fail_gpio;
    }

    /*
     * Enable internal pull-ups so the sensors read HIGH when no
     * magnet is present and LOW when the magnet is present (90-degree
     * offset).  External pull-ups are also recommended for robustness.
     */
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_A_PIN);
        goto fail_gpio;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_B_PIN);
        goto fail_gpio;
    }

    /* ---- register alert callbacks ---- */
    if (gpioSetAlertFuncEx(SENSOR_A_PIN, sensor_alert_cb, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on GPIO%d.\n", SENSOR_A_PIN);
        goto fail_gpio;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_PIN, sensor_alert_cb, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on GPIO%d.\n", SENSOR_B_PIN);
        goto fail_gpio;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    printf("Quadrature Hall-effect logger started.\n");
    printf("  Sensor A: GPIO%d | Sensor B: GPIO%d\n", SENSOR_A_PIN, SENSOR_B_PIN);
    printf("  Log file: %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop: sleep until signal ---- */
    while (g_running) {
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");

    /* ---- cleanup ---- */
    gpioSetAlertFuncEx(SENSOR_A_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_B_PIN, NULL, NULL);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_OFF);
    gpioTerminate();

    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    return EXIT_SUCCESS;

fail_gpio:
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return EXIT_FAILURE;
}

