 * Raspberry Pi 3 Model B+ — TTP223B capacitive touch sensor → LED toggle
 *
 * Wiring:
 *   TTP223B VCC  → 3.3 V (pin 1)
 *   TTP223B GND  → GND   (pin 9)
 *   TTP223B OUT  → GPIO17 (pin 11)
 *   LED anode    → GPIO18 (pin 12) through ~330 Ω resistor
 *   LED cathode  → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lgpiod
 *
 * Run:
 *   sudo ./touch_led
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TOUCH_PIN  17   /* GPIO17 — TTP223B OUT  */
#define LED_PIN    18   /* GPIO18 — LED anode    */
#define DEBOUNCE_MS 50  /* software debounce after a touch event */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sleep for the given number of milliseconds, interruptible by signals. */
static void sleep_ms(unsigned int ms)
{
    struct timespec req = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&req, &req) != 0 && errno == EINTR) {
        if (!g_running)
            return;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /*
     * Open the default gpiochip (gpiochip0 on the Pi 3 B+ maps to the
     * BCM GPIO numbering).
     */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "Failed to get GPIO%d line: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get GPIO%d line: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request the LED line as an output, initial value LOW. */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request the touch line for rising-edge events. */
    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO%d: %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor ready. GPIO%d = touch, GPIO%d = LED.\n"
           "Press Ctrl+C to exit.\n", TOUCH_PIN, LED_PIN);
    fflush(stdout);

    bool led_state = false;

    while (g_running) {
        /*
         * Block up to 1 s waiting for a rising edge.  If a signal
         * arrives during the wait, nanosleep returns EINTR and the
         * loop re-checks g_running.
         */
        int rv = gpiod_line_event_wait(touch_line, &(struct timespec){1, 0});
        if (rv < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "Error waiting for event on GPIO%d: %s\n",
                    TOUCH_PIN, strerror(errno));
            goto cleanup;
        }
        if (rv == 0)
            continue;  /* timeout, no event */

        /* Drain any pending events so we don't re-trigger immediately. */
        while (gpiod_line_event_read(touch_line, NULL) == 0)
            ;

        /* Software debounce: ignore further touches for DEBOUNCE_MS. */
        sleep_ms(DEBOUNCE_MS);

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to write GPIO%d: %s\n",
                    LED_PIN, strerror(errno));
            goto cleanup;
        }

        printf("Touch detected — LED %s\n", led_state ? "ON" : "OFF");
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL)
        gpiod_line_release(led_line);
    if (touch_line != NULL)
        gpiod_line_release(touch_line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

