/*
 * Raindrop sensor monitor — Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Raindrop Sensor Module (digital OUT) -> GPIO17 (BCM)
 *   3.3 V                                -> Pin 1 (3.3 V)
 *   GND                                  -> Pin 9 (GND)
 *
 * The module idles HIGH (no rain) and pulls the line LOW when rain is
 * detected.  The internal pull-up on GPIO17 ensures a defined level
 * when the sensor is disconnected.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain_monitor rain_monitor.c -lpigpio -lrt
 * Run:    sudo ./rain_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        17          /* BCM pin number */
#define LOG_FILE        "/var/log/rain_events.log"
#define POLL_DELAY_US   500000      /* 500 ms */
#define TIMESTAMP_LEN   32

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[TIMESTAMP_LEN];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Internal pull-up so the input is defined when the sensor is
     * disconnected.  The module idles HIGH and pulls LOW on rain. */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d) failed\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state = -1;   /* unknown — forces initial log */

    install_signal_handlers();

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    printf("Raindrop sensor monitoring started on GPIO%d.\n", GPIO_PIN);
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", GPIO_PIN);
            break;
        }

        /* Active-low: LOW (0) => rain detected */
        int current_state = (level == 0) ? 1 : 0;

        if (current_state != last_state) {
            const char *msg = (current_state == 1)
                ? "Rain Detected"
                : "No Rain";

            if (log_event(msg) != 0) {
                fprintf(stderr, "Failed to log event.\n");
                break;
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

