#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define TILT_THRESHOLD_MS 2000
#define POLL_INTERVAL_US  100000
#define LOG_FILE_NAME     "bridge_integrity.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

static void activate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate alarm on GPIO%d\n", ALARM_PIN);
    }
}

static void deactivate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate alarm on GPIO%d\n", ALARM_PIN);
    }
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", pin);
    }
    return value;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alarm pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int tilt_active = 0;
    int tilt_start_time = 0;
    int last_sensor_1_state = 0;
    int last_sensor_2_state = 0;

    log_event("Program started");

    while (program_running) {
        int sensor_1_state = read_sensor(SENSOR_1_PIN);
        int sensor_2_state = read_sensor(SENSOR_2_PIN);

        if (sensor_1_state < 0 || sensor_2_state < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_1_state == 1 && last_sensor_1_state == 0) {
            log_event("Tilt started on sensor 1");
        }
        if (sensor_2_state == 1 && last_sensor_2_state == 0) {
            log_event("Tilt started on sensor 2");
        }
        if (sensor_1_state == 0 && last_sensor_1_state == 1) {
            log_event("Tilt ended on sensor 1");
        }
        if (sensor_2_state == 0 && last_sensor_2_state == 1) {
            log_event("Tilt ended on sensor 2");
        }

        last_sensor_1_state = sensor_1_state;
        last_sensor_2_state = sensor_2_state;

        if (sensor_1_state == 1 && sensor_2_state == 1) {
            if (!tilt_active) {
                tilt_active = 1;
                tilt_start_time = gpioTick();
                log_event("Tilt threshold exceeded (both sensors HIGH)");
                activate_alarm();
            } else {
                int elapsed = gpioTick() - tilt_start_time;
                if (elapsed > TILT_THRESHOLD_MS * 1000) {
                    log_event("Tilt threshold exceeded for 2 seconds");
                }
            }
        } else {
            if (tilt_active) {
