/*
 * seismic.c — Raspberry Pi 3 Model B+ seismic monitor
 *
 * Sensor : Omron D7S-A0011 (I2C 0x2A, bus 1, SDA/SCL BCM 2/3)
 * Alert  : LED on BCM 17
 * Log    : seismic_events.log (ISO-8601 timestamps)
 *
 * Build  : gcc -O2 -Wall -o seismic seismic.c -lm -lrt
 * Run    : sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x2A          /* D7S-A0011 default I2C address */
#define ALERT_LED_PIN        17            /* BCM 17 */
#define THRESHOLD            500.0f        /* vibration magnitude threshold */
#define POLL_DELAY_US        100000        /* 100 ms between samples */
#define ALERT_DURATION_US    1000000       /* 1 s LED alert */
#define MAX_RETRIES          3             /* I2C read retries per sample */
#define LOG_FILE             "seismic_events.log"

/* D7S register addresses */
#define D7S_REG_CTRL1        0x20
#define D7S_REG_CTRL2        0x21
#define D7S_REG_OUT_X_L      0x28          /* X-axis low byte  */
#define D7S_REG_OUT_X_H      0x29          /* X-axis high byte */
#define D7S_REG_OUT_Y_L      0x2A          /* Y-axis low byte  */
#define D7S_REG_OUT_Y_H      0x2B          /* Y-axis high byte */
#define D7S_REG_OUT_Z_L      0x2C          /* Z-axis low byte  */
#define D7S_REG_OUT_Z_H      0x2D          /* Z-axis high byte */

/* CTRL1 bit masks */
#define D7S_CTRL1_PD        0x80          /* power-down / sleep bit */
#define D7S_CTRL1_DR_1HZ    0x00          /* 1 Hz output data rate   */

/* --------------------------- Global state ------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_sensor(void);
static int  read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
static float calculate_magnitude(int16_t x, int16_t y, int16_t z);
static void log_event(float magnitude);
static void trigger_alert(void);
static void cleanup(void);

/* --------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Sensor init ------------------------------- */
static int init_sensor(void)
{
    /* Open I2C bus 1 at address 0x2A */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }

    /* Verify sensor presence by reading CTRL1 */
    int ctrl1 = i2cReadByteData(g_i2c_handle, D7S_REG_CTRL1);
    if (ctrl1 < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Clear power-down bit and set 1 Hz data rate */
    if (i2cWriteByteData(g_i2c_handle, D7S_REG_CTRL1,
                         (uint8_t)(ctrl1 & ~D7S_CTRL1_PD)) < 0) {
        fprintf(stderr, "[ERROR] Failed to write CTRL1: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(50000);  /* 50 ms */

    printf("[INFO] D7S-A0011 initialized (CTRL1=0x%02X).\n", ctrl1);
    return 0;
}

/* --------------------------- Read sensor data -------------------------- */
static int read_sensor_data(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    int     attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int n = i2cReadI2CBlockData(g_i2c_handle, D7S_REG_OUT_X_L,
                                   (char *)buf, 6);
        if (n == 6) {
            *x = (int16_t)((buf[1] << 8) | buf[0]);
            *y = (int16_t)((buf[3] << 8) | buf[2]);
            *z = (int16_t)((buf[5] << 8) | buf[4]);
            return 0;
        }
        fprintf(stderr, "[WARN] I2C block read failed (attempt %d/%d, got %d): %s\n",
                attempt + 1, MAX_RETRIES, n, strerror(errno));
        gpioDelay(10000);  /* 10 ms back-off */
    }

    fprintf(stderr, "[ERROR] Sensor read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

/* --------------------------- Magnitude calculation --------------------- */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    return sqrtf((float)(x * x + y * y + z * z));
}

/* --------------------------- Log event --------------------------------- */
static void log_event(float magnitude)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s  magnitude=%.2f\n", timestamp, magnitude);
    fflush(g_log_file);
    printf("[ALERT] %s  magnitude=%.2f\n", timestamp, magnitude);
}

/* --------------------------- Alert LED --------------------------------- */
static void trigger_alert(void)
{
    gpioWrite(ALERT_LED_PIN, 1);
    gpioDelay(ALERT_DURATION_US);
    gpioWrite(ALERT_LED_PIN, 0);
}

/* --------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure alert LED pin */
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);
    gpioWrite(ALERT_LED_PIN, 0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Monitoring seismic activity (threshold=%.1f)... Press Ctrl+C to exit.\n",
           THRESHOLD);

    /* Main polling loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_sensor_data(&x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                log_event(magnitude);
                trigger_alert();
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\n[INFO] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

