/*
 * obstacle_detect.c — Raspberry Pi 5
 *
 * Reads four Keywish KY-032 IR obstacle sensors (active-low: 0 = object detected)
 * on GPIO4, GPIO17, GPIO27, GPIO22 and drives an LED on GPIO18 when any
 * sensor reports an object.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_detect obstacle_detect.c -lgpiod
 * Run:    sudo ./obstacle_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_US 50000   /* 50 ms */

static const unsigned int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};
static const unsigned int led_pin = 18;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++)
        sensor_lines[i] = NULL;

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open the default GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fall back to the first chip found (e.g., gpiochip0 on older kernels) */
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* ---- Acquire sensor lines as inputs ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
