/*
 * flame_monitor.c - KY-026 flame sensor monitor for Raspberry Pi 3 Model B+
 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27
 * (physical pins 3, 5, 7, 11, 13).  Polls each line once per second,
 * debounces HIGH -> LOW transitions, and logs each confirmed flame
 * event to /var/log/flame_events.log with an ISO 8601 UTC timestamp.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (root needed for /var/log access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define CONSUMER         "flame_monitor"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *message)
{
    syslog(priority, "%s", message);
    fprintf(stderr, "%s\n", message);
}

static void log_sensor_error(int sensor_id, const char *message)
{
    char buf[256];
    snprintf(buf, sizeof(buf), "Sensor ID: %d - %s", sensor_id, message);
    log_event(LOG_ERR, buf);
}

/* ------------------------------------------------------------------ */
/* File logging                                                        */
/* ------------------------------------------------------------------ */
static int log_flame_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_event(LOG_ERR, "Failed to open log file");
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        log_event(LOG_ERR, "Failed to lock log file");
        fclose(fp);
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        log_event(LOG_ERR, "time() failed");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        log_event(LOG_ERR, "gmtime_r() failed");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &tm_utc) == 0) {
        log_event(LOG_ERR, "strftime() failed");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                timestamp, sensor_id, pin) < 0) {
        log_event(LOG_ERR, "fprintf() to log file failed");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        log_event(LOG_ERR, "fflush() failed");
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        log_event(LOG_WARNING, "Failed to unlock log file");
    }

    if (fclose(fp) == EOF) {
        log_event(LOG_WARNING, "fclose() failed");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++)
        lines[i] = NULL;

    openlog(CONSUMER, LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_event(LOG_ERR, "sigaction(SIGINT) failed");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_event(LOG_ERR, "sigaction(SIGTERM) failed");
        goto cleanup;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_event(LOG_ERR, "Failed to open gpiochip0");
        goto cleanup;
    }

    /* ---- Acquire and request each sensor line ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Failed to get GPIO line %u", sensor_pins[i]);
            log_event(LOG_ERR, msg);
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], CONSUMER) < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Failed to request GPIO line %u as input",
                     sensor_pins[i]);
            log_event(LOG_ERR, msg);
            goto cleanup;
        }

        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Initial read failed on GPIO %u", sensor_pins[i]);
            log_sensor_error(i + 1, msg);
            prev_state[i] = 0;
        } else {
            prev_state[i] = val;
        }
    }

    log_event(LOG_INFO, "Flame monitor started");

    /* ---- Main polling loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "Read error on GPIO %u", sensor_pins[i]);
                log_sensor_error(i + 1, msg);
                continue;
            }

            if (val == 0 && prev_state[i] == 1) {
                /* Potential flame transition - debounce */
                usleep(DEBOUNCE_MS * 1000);
                int val2 = gpiod_line_get_value(lines[i]);
                if (val2 < 0) {
                    char msg[128];
                    snprintf(msg, sizeof(msg),
                             "Debounce read error on GPIO %u",
                             sensor_pins[i]);
                    log_sensor_error(i + 1, msg);
                    continue;
                }
                if (val2 == 0) {
                    if (log_flame_event(i + 1, sensor_pins[i]) == 0) {
                        char msg[128];
                        snprintf(msg, sizeof(msg),
                                 "Flame detected on sensor %d (GPIO %u)",
                                 i + 1, sensor_pins[i]);
                        log_event(LOG_INFO, msg);
                    }
                }
            }

            prev_state[i] = val;
        }

        sleep(POLL_INTERVAL_S);
    }

    log_event(LOG_INFO, "Flame monitor stopping");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines and close chip ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    closelog();
    return ret;
}

