/*
 * Adaptive grow light controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - VEML7700 ambient light sensor on I2C bus 1 (address 0x10).
 *   - Grow light LED on GPIO18 (BCM), driven via hardware PWM at 1000 Hz.
 *
 * Build:
 *   gcc -O2 -Wall -o grow_light grow_light.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VEML7700_ADDR        0x10
#define GPIO_LED             18
#define PWM_FREQUENCY        1000          /* Hz */
#define PWM_RANGE            100           /* duty 0-100 */
#define SAMPLE_INTERVAL_SEC  1
#define LOG_FILE             "grow_log.txt"

/* VEML7700 register addresses */
#define VEML7700_REG_CONF    0x00
#define VEML7700_REG_ALS     0x04

/* VEML7700 configuration: ALS_PERIOD=100ms (0x00), ALS_INT_PERIOD=100ms,
 * ALS_INT_THRESH=0, ALS_INT_CTRL=0, ALS_PERS=1, ALS_SD=0 (power on).
 * Value = 0x0000 (little-endian on the bus). */
#define VEML7700_CONF_VALUE  0x0000

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  veml7700_write_config(int handle, uint16_t value);
static int  veml7700_read_als(int handle, uint16_t *als);
static int  map_lux_to_brightness(uint16_t lux);
static void log_data(uint16_t lux, int brightness, int error_code);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- VEML7700 helpers -------------------------- */
static int veml7700_write_config(int handle, uint16_t value)
{
    char buf[2];
    buf[0] = (char)(value & 0xFF);          /* little-endian: low byte first */
    buf[1] = (char)((value >> 8) & 0xFF);

    if (i2cWriteI2CBlockData(handle, VEML7700_REG_CONF, buf, 2) < 0) {
        return -1;
    }
    return 0;
}

static int veml7700_read_als(int handle, uint16_t *als)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, VEML7700_REG_ALS, buf, 2) < 0) {
        return -1;
    }

    /* VEML7700 ALS register is little-endian: low byte first */
    *als = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ----------------------------- Brightness mapping ------------------------ */
static int map_lux_to_brightness(uint16_t lux)
{
    if (lux < 100)   return 100;
    if (lux < 500)   return 75;
    if (lux < 1000)  return 50;
    return 25;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(uint16_t lux, int brightness, int error_code)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    fprintf(g_log_file,
            "%s, lux=%u, brightness=%d, error=%d\n",
            ts, lux, brightness, error_code);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to VEML7700 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X (err=%d).\n",
                I2C_BUS, VEML7700_ADDR, g_i2c_handle);
        fprintf(g_log_file, "I2C_OPEN_FAILED, error=%d\n", g_i2c_handle);
        fflush(g_log_file);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure VEML7700 --- */
    if (veml7700_write_config(g_i2c_handle, VEML7700_CONF_VALUE) < 0) {
        fprintf(stderr, "Error: failed to configure VEML7700.\n");
        fprintf(g_log_file, "VEML7700_CONFIG_FAILED\n");
        fflush(g_log_file);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on GPIO18 --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_LED, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty on GPIO%d.\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Adaptive grow light controller started.\n");
    printf("  I2C bus %d, VEML7700 @ 0x%02X, LED on GPIO%d, PWM %d Hz, range %d.\n",
           I2C_BUS, VEML7700_ADDR, GPIO_LED, PWM_FREQUENCY, PWM_RANGE);
    printf("  Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t lux = 0;
        int      brightness = 0;
        int      error_code = 0;

        if (veml7700_read_als(g_i2c_handle, &lux) < 0) {
            fprintf(stderr, "Error: failed to read lux from VEML7700.\n");
            error_code = -1;
            log_data(0, 0, error_code);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        brightness = map_lux_to_brightness(lux);

        if (gpioPWM(GPIO_LED, brightness) < 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle to %d.\n", brightness);
            error_code = -2;
        }

        log_data(lux, brightness, error_code);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(GPIO_LED, 0);
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

