            log_data(0, 0, error_code);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        brightness = map_lux_to_brightness(lux);

        if (gpioPWM(GPIO_LED, brightness) < 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle to %d.\n", brightness);
            error_code = -2;
        }

        log_data(lux, brightness, error_code);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(GPIO_LED, 0);
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

