int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set touch pin %d as input\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on touch pin %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = gpioRead(touch_pins[i]);
        if (prev_state[i] < 0) {
            fprintf(stderr, "Failed to read initial state of touch pin %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int led_state = 0;
    int any_touched = 0;

    while (running) {
        any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current = gpioRead(touch_pins[i]);
            if (current < 0) {
                fprintf(stderr, "Error reading touch pin %d\n", touch_pins[i]);
                continue;
            }

            if (current == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
            }

            prev_state[i] = current;
            if (current == 1) {
                any_touched = 1;
            }
        }

        if (any_touched && led_state == 0) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED\n");
            } else {
                led_state = 1;
            }
        } else if (!any_touched && led_state == 1) {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            } else {
                led_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

