/*
 * OPT3001 Greenhouse Light Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   OPT3001 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *   OPT3001 ADD0 -> GND  (I2C address 0x44)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_logger light_logger.c -lpigpio -lrt
 *   (pigpio provides the I2C bus and GPIO management)
 *
 * Run:
 *   sudo ./light_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define OPT3001_ADDR         0x44          /* ADD0 tied to GND */
#define REG_RESULT           0x00          /* Result register (R) */
#define REG_CONFIGURATION    0x01          /* Configuration register (W) */
#define CONFIG_VALUE         0xC810        /* RN=1000 (1x), CT=00, M=10 (auto),
                                              FC=00, OVF=0, CR=00, FL=0,
                                              ME=00, L=0, POL=0, MODE=0,
                                              CT=00, RN=1000 */
#define LOG_FILE             "light_data.txt"
#define SAMPLE_INTERVAL_US   1000000       /* 1 second */
#define CONFIG_SETTLE_US     100000        /* 100 ms after config write */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  opt3001_write_config(int handle, uint16_t config);
static int  opt3001_read_lux(int handle, float *lux_out);
static int  log_data(FILE *fp, float lux);
static void cleanup(void);

/* ------------------------------- Handler --------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Configuration write -------------------------- */
/*
 * pigpio's i2cWriteWordData sends the 16-bit value as [low_byte, high_byte]
 * on the wire, which is little-endian on the Pi but the OPT3001 expects
 * big-endian, so we byte-swap before writing.
 */
static int opt3001_write_config(int handle, uint16_t config)
{
    uint8_t swapped = (uint8_t)((config >> 8) | (config << 8));
    int rc = i2cWriteByteData(handle, REG_CONFIGURATION, swapped);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(config) failed: %d\n", rc);
        return -1;
    }
    return 0;
}

/* ------------------------------- Read lux --------------------------------- */
/*
 * pigpio's i2cReadWordData returns the 16-bit word as [low_byte, high_byte]
 * on the wire, which is little-endian on the Pi, but the OPT3001 sends
 * big-endian data, so we byte-swap before decoding the exponent/mantissa.
 */
static int opt3001_read_lux(int handle, float *lux_out)
{
    int rc = i2cReadWordData(handle, REG_RESULT);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(result) failed: %d\n", rc);
        return -1;
    }

    /* pigpio returns the word as (low_byte << 8) | high_byte */
    uint16_t raw = (uint16_t)rc;
    uint16_t swapped = (uint16_t)((raw >> 8) | (raw << 8));

    uint32_t exponent = (swapped >> 12) & 0x000F;
    uint32_t mantissa =  swapped        & 0x0FFF;

    if (exponent == 0x000F) {
        fprintf(stderr, "[WARN] OPT3001 overflow flag set (exponent=15)\n");
        return -1;
    }

    *lux_out = (float)(mantissa * (0.01 * (1UL << exponent)));
    return 0;
}

/* ------------------------------- Log data --------------------------------- */
static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush() on log file failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure OPT3001 --- */
    if (opt3001_write_config(g_i2c_handle, CONFIG_VALUE) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure OPT3001\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow the configuration to settle before the first reading */
    gpioDelay(CONFIG_SETTLE_US);

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; continuing\n");
    }

    printf("OPT3001 greenhouse light logger started.\n");
    printf("Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "[WARN] Sensor read failed; skipping sample.\n");
        } else {
            printf("Lux: %.2f\n", lux);
            if (log_data(g_log_file, lux) != 0) {
                fprintf(stderr, "[WARN] Logging failed.\n");
            }
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

