    /* Allow the configuration to settle before the first reading */
    gpioDelay(CONFIG_SETTLE_US);

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; continuing\n");
    }

    printf("OPT3001 greenhouse light logger started.\n");
    printf("Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "[WARN] Sensor read failed; skipping sample.\n");
        } else {
            printf("Lux: %.2f\n", lux);
            if (log_data(g_log_file, lux) != 0) {
                fprintf(stderr, "[WARN] Logging failed.\n");
            }
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

