/*
 * TTP223 capacitive touch sensor logger for Raspberry Pi 5.
 *
 * Wiring (BCM numbering):
 *   TTP223 OUT  -> GPIO4  (physical pin 7)
 *   TTP223 VCC  -> 3.3 V
 *   TTP223 GND  -> GND
 *
 * The TTP223 has an internal pull-down; we configure GPIO4 as input
 * with the library's internal pull-down disabled (we let the sensor
 * drive the line), then poll for state transitions with a 50 ms
 * debounce interval.  Each event is appended to touch_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_logger touch_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* Pi 5 default gpiochip */
#define GPIO_LINE_OFFSET 4             /* BCM 4, physical pin 7 */
#define LOG_FILE         "touch_log.txt"
#define DEBOUNCE_MS      50
#define POLL_MS          10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(FILE *fp, const char *event)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling ------------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file -------------------------------------------------- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request line -------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /*
     * Request the line as input with the internal pull-down disabled.
     * The TTP223 drives the line high when touched, so we do not drive it.
     */
    if (gpiod_line_request_input_flags(line, "ttp223-touch",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE) < 0) {
        fprintf(stderr, "gpiod_line_request_input_flags failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor logging started on %s line %d.\n",
           GPIO_CHIP_NAME, GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    int last_state = gpiod_line_get_value(line);
    if (last_state < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    struct timespec last_change = { 0, 0 };
    clock_gettime(CLOCK_MONOTONIC, &last_change);

    /* --- Main polling loop ---------------------------------------------- */
    while (g_running) {
        int current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        if (current_state != last_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            long elapsed_ms = (now.tv_sec - last_change.tv_sec) * 1000L +
                              (now.tv_nsec - last_change.tv_nsec) / 1000000L;

            if (elapsed_ms >= DEBOUNCE_MS) {
                const char *event = (current_state == 1)
                                    ? "Touch Detected"
                                    : "Touch Released";

                if (log_event(fp, event) != 0) {
                    fprintf(stderr, "Failed to log event.\n");
                    goto cleanup;
                }

                last_state = current_state;
                last_change = now;
            }
        }

        struct timespec sleep_ts = { 0, POLL_MS * 1000000L };
        nanosleep(&sleep_ts, NULL);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (fp != NULL)
        fclose(fp);

    return ret;
}

