/*
 * Raspberry Pi Zero W – SLF3S-1300F Coolant Flow Monitor
 *
 * Monitors the coolant flow rate from a Sensirion SLF3S-1300F
 * Liquid Flow Sensor on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL).
 *
 * Build:  gcc -O2 -Wall -Wextra -o cooling_monitor cooling_monitor.c
 * Run:    ./cooling_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SLF3S_ADDR       0x6B
#define SLF3S_CMD_MSB    0x36
#define SLF3S_CMD_LSB    0x08
#define SLF3S_CRC_POLY   0x31
#define SLF3S_CRC_INIT   0xFF
#define FLOW_MIN         0.0f
#define FLOW_MAX         100.0f
#define LOG_FILE         "cooling_log.csv"
#define SAMPLE_PERIOD_S  1
#define MEASURE_DELAY_US 2000

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SLF3S_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ SLF3S_CRC_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
