/*
 * KY-033 Obstacle Avoidance Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern GPIO API)
 *
 * Wiring (BCM numbering):
 *   KY-033 #1 (left)  -> GPIO17
 *   KY-033 #2 (middle)-> GPIO27
 *   KY-033 #3 (right) -> GPIO22
 *
 * Build:  gcc -Wall -Wextra -O2 -o path_logger path_logger.c -lpigpio -lrt
 * Run:    sudo ./path_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22

#define LOG_FILE_NAME     "path_log.csv"
#define SAMPLE_PERIOD_US  50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a static ISO-8601 timestamp string (caller must not free).   */
static const char *get_timestamp(void)
{
    static char buf[32];
    time_t      t  = time(NULL);
    struct tm   tm;

    if (localtime_r(&t, &tm) == NULL) {
        snprintf(buf, sizeof(buf), "1970-01-01T00:00:00");
        return buf;
    }
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm);
    return buf;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error.                  */
static int read_sensor(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%u) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const char *ts,
                    int l, int m, int r)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, l, m, r) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    FILE *fp = NULL;
    int   rc = EXIT_FAILURE;

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup_gpio;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,left,middle,right\n") < 0 ||
            fflush(fp) != 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            goto cleanup_all;
        }
    }

    /* ---- Request GPIO lines as inputs ---- */
    unsigned pins[] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(%u) failed\n", pins[i]);
            goto cleanup_all;
        }
    }

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int l = read_sensor(LEFT_SENSOR_PIN);
        int m = read_sensor(MIDDLE_SENSOR_PIN);
        int r = read_sensor(RIGHT_SENSOR_PIN);

        if (l < 0 || m < 0 || r < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        const char *ts = get_timestamp();
        if (log_data(fp, ts, l, m, r) != 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    rc = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

