 */

#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define GPIO_CHIP_NAME   "/dev/gpiochip4"
#define TOUCH_BCM_PIN    23
#define LED_BCM_PIN      24
#define LOG_FILE         "touch_log.txt"
#define POLL_TIMEOUT_MS  1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int log_event(FILE *log, int led_state)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(log, "%s, LED: %s\n", timestamp, led_state ? "ON" : "OFF") < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log_file = NULL;
    int led_state = 0;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open(" GPIO_CHIP_NAME ")");
        goto cleanup;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_BCM_PIN);
    if (touch_line == NULL) {
        perror("gpiod_chip_get_line(touch)");
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_BCM_PIN);
    if (led_line == NULL) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "touch_lamp") < 0) {
        perror("gpiod_line_request_rising_edge_events(touch)");
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "touch_lamp", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Touch lamp running.  Touch GPIO%d to toggle GPIO%d.  Ctrl+C to exit.\n",
           TOUCH_BCM_PIN, LED_BCM_PIN);

    while (g_running) {
        int rv = gpiod_line_event_wait(touch_line, &(struct timespec){
            .tv_sec  = POLL_TIMEOUT_MS / 1000,
            .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L
        });

        if (rv < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (rv == 0)
            continue;  /* timeout, no event */

        /* Drain any pending events so we don't re-trigger immediately */
        while (gpiod_line_event_wait(touch_line, &(struct timespec){0, 0}) > 0)
            ;

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            perror("gpiod_line_set_value(led)");
            goto cleanup;
        }

        if (log_event(log_file, led_state) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL)
        gpiod_line_release(led_line);
    if (touch_line != NULL)
        gpiod_line_release(touch_line);
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_file != NULL)
        fclose(log_file);

    return ret;
}

