    for (int elapsed = 0; elapsed < duration_ms && g_running; elapsed += SLICE_MS) {
        usleep(SLICE_MS * 1000);
    }

    if (gpiod_line_set_value(buzzer, 0) < 0) {
        perror("gpiod_line_set_value(buzzer OFF)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

