        goto cleanup;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* ---- Log system start ---- */
    if (log_event(log_fp, "System started") != 0) {
        fprintf(stderr, "Warning: failed to log system start\n");
    }

    printf("Flame detection system running. Press Ctrl+C to exit.\n");

    int prev_flame = 1;   /* assume no flame at startup (active-low) */

    /* ---- Main polling loop ---- */
    while (g_running) {
