/*
 * Raspberry Pi Zero W – TTP223B capacitive touch sensor → LED toggle logger
 *
 * Wiring:
 *   TTP223B OUT  → GPIO4  (BCM 4,  physical pin 7)
 *   LED anode     → 330 Ω  → GPIO17 (BCM 17, physical pin 11) → 330 Ω → GND
 *   TTP223B VCC  → 3.3 V
 *   TTP223B GND  → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_logger touch_logger.c -lpigpio -lrt
 * Run:    sudo ./touch_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4          /* BCM 4  – TTP223B OUT  */
#define LED_PIN          17         /* BCM 17 – LED anode    */
#define DEBOUNCE_MS      200        /* software debounce window */
#define POLL_DELAY_US    10000      /* 10 ms polling interval  */
#define LOG_FILE         "touch_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Generate an ISO-8601 UTC timestamp string.
 * Returns 0 on success, -1 on failure.
 */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_utc;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }
    return 0;
}

/*
 * Append a timestamped touch event to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_touch_event(void)
{
    char ts[32];

    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp.\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s\n", ts) < 0) {
        fprintf(stderr, "Warning: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush on log file failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_touch_state = 1;   /* assume released (HIGH) at startup */
    uint32_t last_touch_tick = 0;
    int led_state = 0;
    int rc;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO pins ---- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                TOUCH_SENSOR_PIN);
        goto cleanup;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                LED_PIN);
        goto cleanup;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state.\n");
        goto cleanup;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    printf("Touch sensor logging started.\n");
    printf("  Sensor : GPIO%d (BCM)\n", TOUCH_SENSOR_PIN);
    printf("  LED    : GPIO%d (BCM)\n", LED_PIN);
    printf("  Log    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main polling loop ---- */
    while (g_running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n",
                    TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: LOW -> HIGH */
        if (touch_state == 1 && last_touch_state == 0) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_touch_tick;

            /* pigpio tick is a 32-bit microsecond counter that wraps
             * every ~71.6 min; handle the wrap-around correctly. */
            if (elapsed > DEBOUNCE_MS * 1000) {
                last_touch_tick = now;

                /* Toggle LED */
                led_state = !led_state;
                if (gpioWrite(LED_PIN, led_state) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n",
                            LED_PIN);
                    break;
                }

                /* Log the event */
                if (log_touch_event() != 0) {
                    fprintf(stderr, "Warning: failed to log touch event.\n");
                }
            }
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);   /* 10 ms */
    }

cleanup:
    /* ---- graceful shutdown ---- */
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            perror("fclose(log_fp)");
        }
        g_log_fp = NULL;
    }

    /* Ensure LED is off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off LED during cleanup.\n");
    }

    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

