/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern GPIO API)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4
 *   Sensor 2 OUT -> GPIO17
 *   Sensor 3 OUT -> GPIO27
 *
 * The TMAG5110A1 is an open-drain Hall-effect latch sensor.
 *   - When a south pole is near the sensor, the output pulls the line LOW.
 *   - When the magnet is removed, the output releases the line HIGH.
 *
 * This program polls each sensor every 100 ms, logs state transitions
 * with an ISO-8601 timestamp, and cleans up on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* Global flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* Sensor configuration structure */
typedef struct {
    int pin;
    const char *name;
    int initial_state;
    int current_state;
} sensor_config_t;

/* Sensor configuration array */
static sensor_config_t sensors[] = {
    {SENSOR_1_PIN, "Sensor 1", -1, -1},
    {SENSOR_2_PIN, "Sensor 2", -1, -1},
    {SENSOR_3_PIN, "Sensor 3", -1, -1}
};

static const int num_sensors =
    sizeof(sensors) / sizeof(sensors[0]);

/* File pointer for logging */
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helper: write an ISO-8601 timestamp to the log file                 */
/* ------------------------------------------------------------------ */
static void write_timestamp(FILE *fp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo);
        fprintf(fp, "%s", timestamp);
    } else {
        fprintf(fp, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* Log a state change event                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *sensor_name, int state)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return;
    }

    write_timestamp(log_file);
    fprintf(log_file, " - Sensor: %s - State: %s\n",
            sensor_name, state ? "MAGNET_REMOVED" : "MAGNET_PRESENT");
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1 on success, -1 on error           */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr,
                "Error: gpioRead failed on pin %d (rc=%d).\n",
                pin, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure sensor pins                         */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < num_sensors; i++) {
        if (gpioSetMode(sensors[i].pin, PI_INPUT) != 0) {
            fprintf(stderr,
                    "Error: gpioSetMode failed for pin %d.\n",
                    sensors[i].pin);
            return -1;
        }
        if (gpioSetPullUpDown(sensors[i].pin, PI_PUD_UP) != 0) {
            fprintf(stderr,
                    "Error: gpioSetPullUpDown failed for pin %d.\n",
                    sensors[i].pin);
            return -1;
        }
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read initial states and record them as the current state */
    for (int i = 0; i < num_sensors; i++) {
        int initial = read_sensor(sensors[i].pin);
        if (initial < 0) {
            fprintf(stderr,
                    "Error: failed to read initial state of %s (pin %d).\n",
                    sensors[i].name, sensors[i].pin);
            cleanup();
            return EXIT_FAILURE;
        }
        sensors[i].initial_state = initial;
        sensors[i].current_state = initial;
    }

    printf("Monitoring %d sensors. Press Ctrl+C to exit.\n", num_sensors);

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            int current = read_sensor(sensors[i].pin);
            if (current < 0) {
                /* Error already reported; skip this iteration */
                continue;
            }

            /* Log only on state change (ignore first read) */
            if (sensors[i].initial_state != -1 &&
                current != sensors[i].current_state) {
                log_event(sensors[i].name, current);
                sensors[i].current_state = current;
            }
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

