/*
 * Si1182-A-GM Heart Rate Monitor (Raspberry Pi 4 Model B)
 *
 * Reads the Si1182-A-GM optical heart-rate sensor on I2C bus 1,
 * applies a 5-sample moving average, validates the BPM value,
 * and logs valid readings to heart_rate.csv.
 *
 * Build:  gcc -O2 -Wall -o heart_rate heart_rate.c -lpigpio -lrt
 * Run:    sudo ./heart_rate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ----------------------------- */

#define I2C_BUS              1
#define I2C_ADDR             0x60          /* Si1182-A-GM default 7-bit address */

#define SI1182_REG_PART_ID   0x00
#define SI1182_REG_HW_REV    0x01
#define SI1182_REG_HW_ID     0x02
#define SI1182_REG_SEQ_ID    0x03
#define SI1182_REG_INT_CFG   0x0F
#define SI1182_REG_INT_STATUS 0x10
#define SI1182_REG_ALS_VIS_DATA0 0x11
#define SI1182_REG_ALS_VIS_DATA1 0x12
#define SI1182_REG_ALS_IR_DATA0  0x13
#define SI1182_REG_ALS_IR_DATA1  0x14
#define SI1182_REG_PS1_DATA0     0x15
#define SI1182_REG_PS1_DATA1     0x16
#define SI1182_REG_PS2_DATA0     0x17
#define SI1182_REG_PS2_DATA1     0x18
#define SI1182_REG_PS3_DATA0     0x19
#define SI1182_REG_PS3_DATA1     0x1A
#define SI1182_REG_COMMAND       0x30

#define SI1182_CMD_RESET        0x01
#define SI1182_CMD_PS_FORCE     0x05
#define SI1182_CMD_ALS_FORCE    0x06
#define SI1182_CMD_PSALS_FORCE  0x07

#define SI1182_PART_ID_EXPECTED 0x82
#define SI1182_HW_REV_EXPECTED  0x00

#define SAMPLE_COUNT           5
#define SAMPLE_PERIOD_US       1000000      /* 1 second */
#define MAX_CONSECUTIVE_ERRORS 10
#define LOG_FILE_NAME          "heart_rate.csv"

/* --------------------------- Global State ---------------------------- */

static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------- Signal Handling --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------- I2C Helpers ----------------------------- */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on failure.
 */
static int si1182_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a register.
 * Returns the byte value (0-255) on success, -1 on failure.
 */
static int si1182_read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

/*
 * Read a 16-bit little-endian register pair.
 * Returns 0 on success, -1 on failure.
 */
static int si1182_read_reg16(uint8_t reg_low, uint16_t *out)
{
    int lo = si1182_read_reg(reg_low);
    if (lo < 0)
        return -1;
    int hi = si1182_read_reg(reg_low + 1);
    if (hi < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/*
 * Send a command to the Si1182 command register.
 * Returns 0 on success, -1 on failure.
 */
static int si1182_send_command(uint8_t cmd)
{
    return si1182_write_reg(SI1182_REG_COMMAND, cmd);
}

/* ------------------------ Sensor Initialization ----------------------- */

/*
 * Verify the sensor is present and responding with the expected
 * PART_ID and HW_REV values.
 * Returns 0 on success, -1 on failure.
 */
static int verify_sensor(void)
{
    int part_id = si1182_read_reg(SI1182_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] PART_ID mismatch: got 0x%02X, expected 0x%02X.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    int hw_rev = si1182_read_reg(SI1182_REG_HW_REV);
    if (hw_rev < 0) {
        fprintf(stderr, "[ERROR] Cannot read HW_REV.\n");
        return -1;
    }
    if (hw_rev != SI1182_HW_REV_EXPECTED) {
        fprintf(stderr, "[WARN] HW_REV mismatch: got 0x%02X, expected 0x%02X.\n",
                hw_rev, SI1182_HW_REV_EXPECTED);
        /* Continue anyway — some clones report a different revision. */
    }

    int hw_id = si1182_read_reg(SI1182_REG_HW_ID);
    if (hw_id < 0) {
        fprintf(stderr, "[WARN] Cannot read HW_ID (continuing).\n");
    } else {
        fprintf(stderr, "[INFO] Si1182 detected: PART_ID=0x%02X, HW_REV=0x%02X, HW_ID=0x%02X\n",
                part_id, hw_rev, hw_id);
    }
    return 0;
}

/*
 * Configure the Si1182 for ALS (ambient light sensing) and PS (proximity).
 * Returns 0 on success, -1 on failure.
 */
static int configure_sensor(void)
{
    /* Reset the device to a known state. */
    if (si1182_write_reg(SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /*
     * Configure ALS_IR and PS1 channels.
     * (Adjust parameters as needed for your specific application.)
     */
    if (si1182_write_reg(0x07, 0x07) < 0) return -1; /* ALS_IR_ADC_MISC */
    if (si1182_write_reg(0x08, 0x07) < 0) return -1; /* ALS_VIS_ADC_MISC */
    if (si1182_write_reg(0x09, 0x07) < 0) return -1; /* PS1_ADC_MISC */
    if (si1182_write_reg(0x0A, 0x07) < 0) return -1; /* PS2_ADC_MISC */
    if (si1182_write_reg(0x0B, 0x07) < 0) return -1; /* PS3_ADC_MISC */

    /*
     * Enable ALS_VIS, ALS_IR, PS1, PS2, PS3.
     * (0x77 = enable ALS_VIS, ALS_IR, PS1, PS2, PS3)
     */
    if (si1182_write_reg(0x0E, 0x77) < 0) return -1; /* ADC_ENABLE */

    /*
     * Set measurement rate to 100 ms (0x0A = 100 ms).
     * (0x0A = 100 ms, 0x0B = 120 ms, 0x0C = 150 ms)
     */
    if (si1182_write_reg(0x0F, 0x0A) < 0) return -1; /* MEAS_RATE0 */

    /*
     * Set measurement rate for PS (0x0A = 100 ms).
     */
    if (si1182_write_reg(0x10, 0x0A) < 0) return -1; /* PS_RATE */

    /*
     * Set PS LED current to 20 mA (0x0F = 20 mA).
     */
    if (si1182_write_reg(0x11, 0x0F) < 0) return -1; /* PS_LED21 */

    /*
     * Set PS LED current for PS2 and PS3 to 20 mA.
     */
    if (si1182_write_reg(0x12, 0x0F) < 0) return -1; /* PS_LED3 */

    /*
     * Enable PS interrupts.
     */
    if (si1182_write_reg(0x13, 0x07) < 0) return -1; /* PS_THOLD1 */
    if (si1182_write_reg(0x14, 0x07) < 0) return -1; /* PS_THOLD2 */
    if (si1182_write_reg(0x15, 0x07) < 0) return -1; /* PS_THOLD3 */

    /*
     * Clear any pending interrupts.
     */
    if (si1182_write_reg(0x16, 0x00) < 0) return -1; /* PS_INT_CFG */
    if (si1182_write_reg(0x17, 0x00) < 0) return -1; /* PS_INT_STATUS */

    /*
     * Enable PS interrupts.
     */
    if (si1182_write_reg(0x18, 0x07) < 0) return -1; /* PS_INT_ENABLE */

    /*
     * Start a forced measurement.
     */
    if (si1182_send_command(SI1182_CMD_PSALS_FORCE) < 0) return -1;

    return 0;
}

/* --------------------------- Moving Average -------------------------- */

typedef struct {
    uint16_t samples[SAMPLE_COUNT];
    int      index;
    int      count;
} MovingAverage;

static void ma_init(MovingAverage *ma)
{
    memset(ma, 0, sizeof(*ma));
}

static void ma_add(MovingAverage *ma, uint16_t value)
{
    ma->samples[ma->index] = value;
    ma->index = (ma->index + 1) % SAMPLE_COUNT;
    if (ma->count < SAMPLE_COUNT)
        ma->count++;
}

static uint16_t ma_average(const MovingAverage *ma)
{
    if (ma->count == 0)
        return 0;
    uint32_t sum = 0;
    for (int i = 0; i < ma->count; i++)
        sum += ma->samples[i];
    return (uint16_t)(sum / ma->count);
}

/* ----------------------------- Logging ------------------------------- */

static void log_data(uint16_t bpm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, bpm);
    fflush(log_file);
}

/* ------------------------------- Main -------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence --- */
    if (verify_sensor() < 0) {
        fprintf(stderr, "[FATAL] Sensor verification failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (configure_sensor() < 0) {
        fprintf(stderr, "[FATAL] Sensor configuration failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE_NAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Write CSV header if file is empty --- */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,BPM\n");
        fflush(log_file);
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Moving average state --- */
    MovingAverage ma;
    ma_init(&ma);

    int consecutive_errors = 0;

    /* --- Main loop --- */
    while (!terminate) {
        uint16_t raw_hr = 0;

        /*
         * Read the heart-rate register (0x15).
         * The Si1182 provides a simple 16-bit value representing beats per minute.
         * Some clones use a different register; adjust the read call if needed.
         */
        if (si1182_read_reg16(SI1182_REG_PS1_DATA0, &raw_hr) < 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "[FATAL] %d consecutive I2C errors — aborting.\n",
                        consecutive_errors);
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        /* Apply moving average filter */
        ma_add(&ma, raw_hr);
        uint16_t filtered_hr = ma_average(&ma);

        /* Validate BPM range (30-220 beats per minute) */
        if (filtered_hr >= 30 && filtered_hr <= 220) {
            log_data(filtered_hr);
            printf("BPM: %u\n", filtered_hr);
        } else {
            fprintf(stderr, "[WARN] BPM out of range: %u\n", filtered_hr);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    fprintf(stderr, "[INFO] Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

