/*
 * KY-026 Flame Sensor monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (pin 1)
 *   KY-026 GND  -> GND   (pin 9)
 *   KY-026 DO   -> GPIO17 (BCM 17, physical pin 11)
 *
 * The sensor's digital output is active-low: LOW (0) means flame detected.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define LOG_FILE         "flame_log.txt"
#define POLL_INTERVAL_US 100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_flame_event(FILE *log_fp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("FLAME DETECTED\n");

    if (log_fp != NULL) {
        if (fprintf(log_fp, "%s FLAME DETECTED\n", timestamp) < 0) {
            fprintf(stderr, "fprintf to log file failed: %s\n",
                    strerror(errno));
        } else {
            if (fflush(log_fp) != 0) {
                fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            }
        }
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open log file --------------------------------------------- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* ---- Open GPIO chip -------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* ---- Get GPIO line --------------------------------------------- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* ---- Request line as input with internal pull-up --------------- */
    if (gpiod_line_request_input_flags(line, "ky026-flame",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "gpiod_line_request_input_flags failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Install signal handlers ----------------------------------- */
    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d (BCM).\n",
           GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ----------------------------------------- */
    int prev_value = gpiod_line_get_value(line);
    if (prev_value < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            /* Brief pause before retrying to avoid log flooding */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Detect falling edge: HIGH -> LOW (flame detected) */
        if (prev_value == 1 && value == 0) {
            log_flame_event(log_fp);
        }

        prev_value = value;
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(log_fp) failed: %s\n", strerror(errno));
        }
    }
    return ret;
}

