    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ----------------------------------------- */
    int prev_value = gpiod_line_get_value(line);
    if (prev_value < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            /* Brief pause before retrying to avoid log flooding */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Detect falling edge: HIGH -> LOW (flame detected) */
        if (prev_value == 1 && value == 0) {
            log_flame_event(log_fp);
        }

        prev_value = value;
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(log_fp) failed: %s\n", strerror(errno));
        }
    }
    return ret;
}

