/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads an 8-channel TTP226 capacitive touch sensor module (BCM pins 5-12)
 * and drives an 8-bit binary counter on BCM 17 (bit 0) and BCM 24 (bit 7).
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STAB_MS      200

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int out_pins[NUM_CHANNELS]   = {17, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_event(FILE *fp, int ch, int cnt)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!fp) {
        fprintf(stderr, "[WARN] log file unavailable; event lost: ch=%d cnt=%d\n", ch, cnt);
        return;
    }
    if (!gmtime_r(&t, &tm)) {
        fprintf(stderr, "[WARN] gmtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm) == 0) {
        fprintf(stderr, "[WARN] strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, ch, cnt) < 0)
        fprintf(stderr, "[WARN] fprintf to log failed: %s\n", strerror(errno));
    if (fflush(fp) != 0)
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *in_lines[NUM_CHANNELS];
    struct gpiod_line *out_lines[NUM_CHANNELS];
    FILE *log_fp = NULL;
    int counter = 0;
    int prev[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(in_lines, 0, sizeof(in_lines));
    memset(out_lines, 0, sizeof(out_lines));
    memset(prev, 0, sizeof(prev));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp)
        fprintf(stderr, "[WARN] Cannot open %s: %s\n", LOG_FILE, strerror(errno));

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        in_lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!in_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(touch %u): %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(in_lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "gpiod_line_request_input(touch %u): %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        out_lines[i] = gpiod_chip_get_line(chip, out_pins[i]);
        if (!out_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(out %u): %s\n", out_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(out_lines[i], "ttp226-counter", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(out %u): %s\n", out_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    usleep(STAB_MS * 1000);

    while (running) {
        int vals[NUM_CHANNELS];
        int ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(in_lines[i]);
            if (v < 0) {
                fprintf(stderr, "gpiod_line_get_value(touch %u): %s\n", touch_pins[i], strerror(errno));
                vals[i] = -1;
                ok = 0;
            } else {
                vals[i] = v;
            }
        }

        if (!ok) {
            usleep(POLL_MS * 1000);
            continue;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (vals[i] == 1 && prev[i] == 0) {
                counter = (counter + 1) & 0xFF;
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                log_event(log_fp, i + 1, counter);
                break;
            }
            prev[i] = vals[i];
        }

        int bits[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++)
            bits[i] = (counter >> i) & 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (gpiod_line_set_value(out_lines[i], bits[i]) < 0)
                fprintf(stderr, "gpiod_line_set_value(out %u): %s\n", out_pins[i], strerror(errno));
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (out_lines[i]) {
            gpiod_line_set_value(out_lines[i], 0);
            gpiod_line_release(out_lines[i]);
        }
        if (in_lines[i])
            gpiod_line_release(in_lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);
    return ret;
}

