#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LOG_FILE    "tracking_log.csv"
#define POLL_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static int log_data(FILE *fp, int s1, int s2, int s3, int s4)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", ts, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    int pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    int i;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", pins[i]);
            goto cleanup;
        }
        /* Enable internal pull-up so the line is defined when the sensor
           is idle (open-collector-style module). */
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pins[i]);
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        goto cleanup;
    }

    /* Write header only if file is empty */
    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek");
        goto cleanup;
    }
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Error: writing header failed\n");
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Error: fflush header failed\n");
            goto cleanup;
        }
    }

    printf("Logging KY-033 tracking data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);
        int s4 = read_sensor(SENSOR4_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "Warning: sensor read error, skipping log entry\n");
        } else {
            if (log_data(fp, s1, s2, s3, s4) != 0) {
                fprintf(stderr, "Warning: log write failed\n");
            }
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    gpioTerminate();
    return rc;
}

