/*
 * obstacle_avoidance.c — Raspberry Pi 3 Model B+
 *
 * Reads two TCRT5000 IR obstacle-avoidance modules (active-low: 0 = obstacle)
 * on GPIO17 and GPIO27, drives an LED on GPIO22 only when both sensors
 * detect an obstacle, and logs timestamped samples to obstacle_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_avoidance obstacle_avoidance.c -lpigpio -lrt
 * Run:    sudo ./obstacle_avoidance
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN     22

#define LOG_FILE    "obstacle_log.csv"
#define POLL_US     100000          /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a static "YYYY-MM-DD HH:MM:SS" timestamp string.             */
static const char *get_timestamp(void)
{
    static char buf[20];
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, sizeof(buf), "1970-01-01 00:00:00");
        return buf;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, sizeof(buf), "1970-01-01 00:00:00");
        return buf;
    }
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmv);
    return buf;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error.                  */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Drive the LED; returns 0 on success, -1 on error.                   */
static int control_led(int state)
{
    int rc = gpioWrite(LED_PIN, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n",
                LED_PIN, state, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row; returns 0 on success, -1 on error.                 */
static int log_data(int s1, int s2, int led)
{
    if (g_log == NULL) {
        fprintf(stderr, "log_data: log file not open\n");
        return -1;
    }
    if (fprintf(g_log, "%s,%d,%d,%d\n", get_timestamp(), s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush(log) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file --------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure pins -------------------------------------------- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR1_PIN);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR2_PIN);
        goto cleanup;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        goto cleanup;
    }

    /* ---- main loop -------------------------------------------------- */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read failure — turn LED off and continue. */
            (void)control_led(0);
            gpioDelay(POLL_US);
            continue;
        }

        /* Both sensors active-low: 0 => obstacle => LED on. */
        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (control_led(led_state) < 0) {
            /* Non-fatal: keep logging anyway. */
        }

        if (log_data(s1, s2, led_state) < 0) {
            /* Non-fatal: keep running. */
        }

        gpioDelay(POLL_US);
    }

    /* ---- graceful shutdown ----------------------------------------- */
    (void)control_led(0);

cleanup:
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

