/*
 * Raspberry Pi 4 Model B – ICS-40180 analog MEMS microphone peak detector
 *
 * Wiring:
 *   ICS-40180 analog output  -> GPIO4  (BCM 4,  physical pin 7)
 *   LED + 330 Ω current-limiting resistor -> GPIO17 (BCM 17, physical pin 11)
 *   LED anode                -> 3V3 (physical pin 1)
 *   LED cathode              -> GND (physical pin 9)
 *   Resistor divider (if used): 10k to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mic_peak mic_peak.c -lpigpio -lrt
 * Run:    sudo ./mic_peak
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN        4          /* BCM 4  – ICS-40180 analog out */
#define LED_PIN        17         /* BCM 17 – LED anode */
#define SAMPLE_US      125        /* 8 kHz polling interval */
#define LED_ON_MS      100        /* LED on duration per peak */
#define POLL_TIMEOUT_S 5          /* max idle seconds before exit */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long ms = (long)ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
    printf("%ld ms", ms);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(MIC_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_mode(LED_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (safe_write(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICS-40180 peak detection started.  Sampling GPIO%d, LED on GPIO%d.\n",
           MIC_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool last_mic_state = false;
    uint32_t idle_start = gpioTick();

    while (g_running) {
        int mic_val = gpioRead(MIC_PIN);
        if (mic_val < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", MIC_PIN);
            break;
        }

        bool peak = (mic_val == 1);

        /* Rising-edge detection for sound-peak detection */
        if (peak && !last_mic_state) {
            printf("Peak detected at ");
            print_timestamp_ms();
            printf("\n");
            fflush(stdout);

            if (safe_write(LED_PIN, 1) != 0) {
                break;
            }
            gpioDelay(LED_ON_MS * 1000);   /* 100 ms – microsecond units */
            if (safe_write(LED_PIN, 0) != 0) {
                break;
            }
            idle_start = gpioTick();
        }

        last_mic_state = peak;

        /* Check for idle timeout */
        uint32_t now = gpioTick();
        uint32_t elapsed = now - idle_start;
        if (elapsed > (uint32_t)(POLL_TIMEOUT_S * 1000000)) {
            printf("Idle timeout – no peak for %d s. Exiting.\n", POLL_TIMEOUT_S);
            break;
        }

        gpioDelay(SAMPLE_US);   /* 125 µs */
    }

    /* ---- Cleanup ---- */
    safe_write(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

