/*
 * Raspberry Pi 4 Model B - 3-Way Tracing Sensor Reader
 *
 * Reads the left, center, and right IR reflectance states from a
 * SunFounder 3-Way Tracing Sensor (3x 3.3V IR reflective sensors).
 *
 * Wiring (BCM numbering):
 *   Left   sensor -> GPIO17
 *   Center sensor -> GPIO27
 *   Right  sensor -> GPIO22
 *
 * Each sensor pin is configured as an active-low input with an
 * internal pull-up resistor so that a grounded sensor reads HIGH
 * (reflective surface detected) and an open sensor reads LOW.
 *
 * Build:  gcc -Wall -Wextra -O2 -o tracing_sensor tracing_sensor.c -lpigpio -lrt
 * Run:    sudo ./tracing_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22

#define POLL_DELAY_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int setup_gpio_pin(unsigned pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, PI_INPUT) failed\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, PI_PUD_UP) failed\n", pin);
        return -1;
    }
    return 0;
}

static int setup_gpio(void)
{
    if (setup_gpio_pin(LEFT_SENSOR_PIN)   != 0) return -1;
    if (setup_gpio_pin(CENTER_SENSOR_PIN) != 0) return -1;
    if (setup_gpio_pin(RIGHT_SENSOR_PIN)  != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   0  - success (states stored in *out)
 *  -1  - read error on one or more pins
 */
static int read_sensor_states(int *left, int *center, int *right)
{
    int lv = gpioRead(LEFT_SENSOR_PIN);
    int cv = gpioRead(CENTER_SENSOR_PIN);
    int rv = gpioRead(RIGHT_SENSOR_PIN);

    if (lv < 0 || cv < 0 || rv < 0) {
        fprintf(stderr, "Error: gpioRead failed (L=%d C=%d R=%d)\n", lv, cv, rv);
        return -1;
    }

    *left   = lv;
    *center = cv;
    *right  = rv;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int left, center, right;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        fprintf(stderr, "Error: GPIO setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("3-Way Tracing Sensor Reader\n");
    printf("Pins: L=GPIO%d  C=GPIO%d  R=GPIO%d  (active-low, pull-up)\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        if (read_sensor_states(&left, &center, &right) == 0) {
            printf("L: %d  C: %d  R: %d\n", left, center, right);
        }
        /*
         * gpioDelay returns the actual delay in microseconds; if it
         * returns < 0, pigpio reports an error.  We continue running
         * but log the issue to stderr.
         */
        if (gpioDelay(POLL_DELAY_US) < 0) {
            fprintf(stderr, "Warning: gpioDelay failed\n");
        }
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

