/*
 * Si1175 ALS (Ambient Light Sensor) reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si1175 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si1175 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si1175 VDD  -> 3.3 V (pin 1)
 *   Si1175 GND  -> GND  (pin 6)
 *
 * The Si1175 is a 7-bit I2C addressable sensor; the default address
 * is 0x60 (ADDR pin tied to GND).  A 16-bit raw ALS reading is
 * assembled from the LSB and MSB registers (ALS_DATA_LSB = 0x22,
 * ALS_DATA_MSB = 0x23).
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1175_als si1175_als.c -lpigpio -lrt
 * Run:    sudo ./si1175_als
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SI1175_DEFAULT_ADDR  0x60          /* ADDR pin tied to GND */

/* Si1175 register addresses */
#define SI1175_REG_ALS_DATA_LSB  0x22
#define SI1175_REG_ALS_DATA_MSB  0x23

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers ------------------------------- */

/*
 * Read a single byte from a Si1175 register.
 * Returns the byte value (0–255) on success, or -1 on error.
 */
static int si1175_read_reg(int handle, uint8_t reg)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, v);
    }
    return v;
}

/*
 * Write a single byte to a Si1175 register.
 * Returns 0 on success, -1 on error.
 */
static int si1175_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Probe the Si1175 by reading the ALS_DATA_LSB register.
 * Returns 0 on success (sensor present), -1 if the device is absent
 * or unresponsive.
 */
static int si1175_probe(int handle)
{
    int lsb = si1175_read_reg(handle, SI1175_REG_ALS_DATA_LSB);
    if (lsb < 0) {
        fprintf(stderr, "[WARN] Si1175 not responding at this address.\n");
        return -1;
    }
    printf("[INFO] Si1175 detected (ALS_DATA_LSB=0x%02X).\n", (uint8_t)lsb);
    return 0;
}

/*
 * Read the 16-bit ALS raw value from the Si1175.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int si1175_read_als(int handle, uint16_t *out)
{
    int lsb = si1175_read_reg(handle, SI1175_REG_ALS_DATA_LSB);
    if (lsb < 0) {
        return -1;
    }

    int msb = si1175_read_reg(handle, SI1175_REG_ALS_DATA_MSB);
    if (msb < 0) {
        return -1;
    }

    *out = (uint16_t)(((uint8_t)msb << 8) | (uint8_t)lsb);
    return 0;
}

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open the I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1175_DEFAULT_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1175_DEFAULT_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Probe the sensor --- */
    if (si1175_probe(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1175 not detected on bus %d at addr 0x%02X.\n",
                I2C_BUS, SI1175_DEFAULT_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Reading ALS every 100 ms. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t als_value = 0;

        if (si1175_read_als(g_i2c_handle, &als_value) == 0) {
            printf("ALS: %u\n", als_value);
        } else {
            fprintf(stderr, "[ERROR] Failed to read ALS data.\n");
        }

        /* 100 ms delay (pigpio uses microseconds) */
        gpioDelay(100000);
    }

    /* --- Clean shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

