        return -1;
    }

    *out = (uint16_t)(((uint8_t)msb << 8) | (uint8_t)lsb);
    return 0;
}

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open the I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1175_DEFAULT_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1175_DEFAULT_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Probe the sensor --- */
    if (si1175_probe(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1175 not detected on bus %d at addr 0x%02X.\n",
                I2C_BUS, SI1175_DEFAULT_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Reading ALS every 100 ms. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t als_value = 0;

        if (si1175_read_als(g_i2c_handle, &als_value) == 0) {
            printf("ALS: %u\n", als_value);
        } else {
            fprintf(stderr, "[ERROR] Failed to read ALS data.\n");
        }

        /* 100 ms delay (pigpio uses microseconds) */
        gpioDelay(100000);
    }

    /* --- Clean shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

