        safe_gpio_set_mode(MIDDLE_PIN, PI_INPUT) != 0 ||
        safe_gpio_set_mode(RIGHT_PIN, PI_INPUT) != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- Install SIGINT handler ---- */
    if (install_sigint_handler() != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Tracking sensor polling started (Ctrl+C to exit)\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int l = safe_gpio_read(LEFT_PIN);
        int m = safe_gpio_read(MIDDLE_PIN);
        int r = safe_gpio_read(RIGHT_PIN);

        if (l < 0 || m < 0 || r < 0) {
            rc = EXIT_FAILURE;
            break;
        }

        printf("L:%d M:%d R:%d\n", l, m, r);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);   /* 100 ms */
    }

