/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (BCM numbering):
 *   TP1 -> GPIO5  TP2 -> GPIO6  TP3 -> GPIO13 TP4 -> GPIO19
 *   TP5 -> GPIO26 TP6 -> GPIO12 TP7 -> GPIO16 TP8 -> GPIO20
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_poll touch_poll.c -lrt
 * Run:    ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
static const int CHANNEL_PINS[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

static double monotonic_seconds(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0.0;
    }
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;
}

int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    int lines[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpioRequestLine(CHANNEL_PINS[i], PI_INPUT, 0);
        if (lines[i] < 0) {
            fprintf(stderr, "Error: failed to request GPIO%d (channel %d): %s\n",
                    CHANNEL_PINS[i], i + 1, pigpio_error(lines[i]));
            for (int j = 0; j < i; j++)
                gpioReleaseLine(lines[j]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int values[NUM_CHANNELS];
        bool read_error = false;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpioRead(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Error: read failed on GPIO%d (channel %d): %s\n",
                        CHANNEL_PINS[i], i + 1, pigpio_error(v));
                read_error = true;
                break;
            }
            values[i] = v;
        }

        if (read_error)
            break;

        double ts = monotonic_seconds();
        if (ts == 0.0)
            break;

        printf("[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               ts,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(200000); /* 200 ms */
    }

    /* Clean up */
    for (int i = 0; i < NUM_CHANNELS; i++)
        gpioReleaseLine(lines[i]);
    gpioTerminate();

    printf("\nTouch sensor reader stopped.\n");
    return EXIT_SUCCESS;
}

