/*
 * RGB LED fading on Raspberry Pi 4 Model B
 * Library: pigpio (hardware PWM at 1000 Hz, 8-bit range)
 *
 * Wiring (common-anode RGB LED):
 *   Red   -> GPIO17 (BCM)
 *   Green -> GPIO18 (BCM)
 *   Blue  -> GPIO27 (BCM)
 *
 * Build: gcc -O2 -Wall -o rgb_fade rgb_fade.c -lpigpio -lrt
 * Run:   sudo ./rgb_fade
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY  1000   /* Hz */
#define PWM_RANGE      255    /* 8-bit resolution */

#define FADE_STEPS     50     /* linear interpolation steps per transition */
#define FADE_DURATION  5      /* seconds per full transition */

#define POLL_DELAY_US  10000  /* 10 ms idle sleep */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Random seeding from /dev/urandom                                    */
/* ------------------------------------------------------------------ */
static int seed_rand(void)
{
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "open(/dev/urandom) failed: %s", strerror(errno));
        return -1;
    }

    unsigned int seed;
    ssize_t n = read(fd, &seed, sizeof(seed));
    if (n < 0) {
        syslog(LOG_ERR, "read(/dev/urandom) failed: %s", strerror(errno));
        close(fd);
        return -1;
    }
    if (n == 0) {
        syslog(LOG_ERR, "/dev/urandom returned EOF (0 bytes)");
        close(fd);
        return -1;
    }

    close(fd);
    srand(seed);
    return 0;
}

/* ------------------------------------------------------------------ */
/* RGB value generation                                                */
/* ------------------------------------------------------------------ */
static void generate_random_color(uint8_t *r, uint8_t *g, uint8_t *b)
{
    *r = (uint8_t)(rand() % 256);
    *g = (uint8_t)(rand() % 256);
    *b = (uint8_t)(rand() % 256);
}

/* ------------------------------------------------------------------ */
/* PWM helpers                                                         */
/* ------------------------------------------------------------------ */
static int set_pwm(int pin, uint8_t value)
{
    if (gpioPWM(pin, value) != 0) {
        syslog(LOG_ERR, "gpioPWM(%d, %u) failed", pin, value);
        return -1;
    }
    return 0;
}

static int set_all_pwm(uint8_t r, uint8_t g, uint8_t b)
{
    if (set_pwm(RED_PIN,   r) != 0) return -1;
    if (set_pwm(GREEN_PIN, g) != 0) return -1;
    if (set_pwm(BLUE_PIN,  b) != 0) return -1;
    return 0;
}

static int fade_to_color(uint8_t tr, uint8_t tg, uint8_t tb,
                         uint8_t cr, uint8_t cg, uint8_t cb)
{
    uint8_t r = cr, g = cg, b = cb;

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        uint8_t dr = (uint8_t)(tr - cr) / FADE_STEPS * (uint8_t)i;
        uint8_t dg = (uint8_t)(tg - cg) / FADE_STEPS * (uint8_t)i;
        uint8_t db = (uint8_t)(tb - cb) / FADE_STEPS * (uint8_t)i;

        r = (uint8_t)(cr + dr);
        g = (uint8_t)(cg + dg);
        b = (uint8_t)(cb + db);

        if (set_all_pwm(r, g, b) != 0)
            return -1;

        usleep(FADE_DURATION * 1000000ULL / FADE_STEPS);
    }

    if (set_all_pwm(tr, tg, tb) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn LED off before releasing resources */
    (void)gpioPWM(RED_PIN,   0);
    (void)gpioPWM(GREEN_PIN, 0);
    (void)gpioPWM(BLUE_PIN,  0);

    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (seed_rand() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure PWM on the three channels */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode() failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency() failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange() failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (set_all_pwm(0, 0, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t current_r = 0, current_g = 0, current_b = 0;
    uint8_t target_r, target_g, target_b;

    generate_random_color(&target_r, &target_g, &target_b);

    syslog(LOG_INFO, "RGB fading started (PWM %d Hz, range %d)",
           PWM_FREQUENCY, PWM_RANGE);

    while (g_running) {
        if (fade_to_color(target_r, target_g, target_b,
                          current_r, current_g, current_b) != 0) {
            syslog(LOG_ERR, "fade_to_color() failed; aborting");
            break;
        }

        current_r = target_r;
        current_g = target_g;
        current_b = target_b;

        generate_random_color(&target_r, &target_g, &target_b);

        /* Small pause between transitions to avoid rapid flickering */
        usleep(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

