/*
 * TCS34725 color sensor reader with LED threshold indicator.
 *
 * Board:  Raspberry Pi 4 Model B
 * I2C:    /dev/i2c-1  (BCM pins 2 = SDA, 3 = SCL)
 * Sensor: TCS34725 (I2C address 0x29)
 * LED:    GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o tcs34725_led tcs34725_led.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- TCS34725 register definitions ---- */
#define TCS34725_I2C_ADDR          0x29
#define TCS34725_COMMAND_BIT       0x80
#define TCS34725_ENABLE            0x00
#define TCS34725_ATIME             0x01
#define TCS34725_CONTROL           0x0F
#define TCS34725_CDATA             0x14
#define TCS34725_RDATA             0x16
#define TCS34725_GDATA             0x18
#define TCS34725_BDATA             0x1A

#define TCS34725_ENABLE_PON        0x01
#define TCS34725_ENABLE_AEN        0x02

#define TCS34725_ATIME_154MS       0xC0   /* 154 ms integration, 256 cycles */
#define TCS34725_AGAIN_4X          0x02   /* 4x gain */

#define RED_THRESHOLD              200
#define POLL_INTERVAL_MS           200
#define MAX_REINIT_ATTEMPTS        3

/* ---- GPIO / LED definitions ---- */
#define GPIO_CHIP_NAME             "gpiochip4"   /* BCM GPIO on Pi 4 */
#define LED_LINE_OFFSET            17

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int                   g_i2c_fd  = -1;
static struct gpiod_line    *g_led_line = NULL;
static struct gpiod_chip    *g_chip     = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register.                              */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register.                             */
/* Returns 0 on success and stores value in *out, -1 on error.         */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian word from a TCS34725 register.          */
/* Returns 0 on success and stores value in *out, -1 on error.         */
/* ------------------------------------------------------------------ */
static int tcs34725_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (word) from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TCS34725: power on, set integration time, gain,     */
/* and enable RGBC.                                                    */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int fd)
{
    if (tcs34725_write_reg(fd, TCS34725_ENABLE,
                           TCS34725_ENABLE_PON) < 0)
        return -1;
    sleep_ms(3);

    if (tcs34725_write_reg(fd, TCS34725_ATIME,
                           TCS34725_ATIME_154MS) < 0)
        return -1;

    if (tcs34725_write_reg(fd, TCS34725_CONTROL,
                           TCS34725_AGAIN_4X) < 0)
        return -1;

    if (tcs34725_write_reg(fd, TCS34725_ENABLE,
                           TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    sleep_ms(3);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channels (C, R, G, B).                                */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_read_all(int fd, uint16_t *c, uint16_t *r,
                             uint16_t *g, uint16_t *b)
{
    if (tcs34725_read_word(fd, TCS34725_CDATA, c) < 0) return -1;
    if (tcs34725_read_word(fd, TCS34725_RDATA, r) < 0) return -1;
    if (tcs34725_read_word(fd, TCS34725_GDATA, g) < 0) return -1;
    if (tcs34725_read_word(fd, TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Power down the sensor.                                              */
/* ------------------------------------------------------------------ */
static void tcs34725_power_down(int fd)
{
    (void)tcs34725_write_reg(fd, TCS34725_ENABLE, 0x00);
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and set the slave address.                         */
/* Returns a valid file descriptor on success, -1 on error.            */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *device, uint8_t addr)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", device, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 ||
        sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }
    g_led_line = gpiod_chip_get_line(g_chip, LED_LINE_OFFSET);
    if (!g_led_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_led_line, "tcs34725_led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        g_led_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = i2c_open("/dev/i2c-1", TCS34725_I2C_ADDR);
    if (g_i2c_fd < 0) {
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (tcs34725_init(g_i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialisation failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialised. Polling every %d ms. "
           "Press Ctrl-C to exit.\n", POLL_INTERVAL_MS);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs34725_read_all(g_i2c_fd, &c, &r, &g, &b) == 0) {
            printf("C: %5u  R: %5u  G: %5u  B: %5u\n", c, r, g, b);

            if (gpiod_line_set_value(g_led_line, r > RED_THRESHOLD ? 1 : 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed: %s\n",
                        strerror(errno));
            }
        } else {
            fprintf(stderr, "Read failed; attempting re-initialisation.\n");
            tcs34725_power_down(g_i2c_fd);
            close(g_i2c_fd);
            g_i2c_fd = -1;

            for (int attempt = 0; attempt < MAX_REINIT_ATTEMPTS && g_running; ++attempt) {
                sleep_ms(100);
                g_i2c_fd = i2c_open("/dev/i2c-1", TCS34725_I2C_ADDR);
                if (g_i2c_fd < 0) {
                    fprintf(stderr, "Re-open attempt %d/%d failed.\n",
                            attempt + 1, MAX_REINIT_ATTEMPTS);
                    continue;
                }
                if (tcs34725_init(g_i2c_fd) == 0) {
                    printf("Re-initialisation succeeded.\n");
                    break;
                }
                fprintf(stderr, "Re-initialisation attempt %d/%d failed.\n",
                        attempt + 1, MAX_REINIT_ATTEMPTS);
                close(g_i2c_fd);
                g_i2c_fd = -1;
            }

            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-initialisation failed after %d attempts.\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        tcs34725_power_down(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

