/*
 * Raspberry Pi 4 Model B – BH1750 ambient-light sensor → WS2812B LED strip
 *
 * Hardware:
 *   - BH1750FVI on I2C bus 1, address 0x23 (ADDR pin tied to GND)
 *   - WS2812B data line on GPIO18 (BCM 18, PCM_CLK)
 *
 * Build:  gcc -O2 -Wall -o light_led light_led.c
 *
 * The BH1750 requires a power-on settle time and a measurement cycle
 * (approx. 180 ms).  We use the hardware PWM/wave capability of the
 * Pi's driver to generate the precise WS2812B timing, so the program
 * does NOT link against a driver library (wiringPi / pigpio).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define BH1750_ADDR      0x23
#define BH1750_CMD_ONE   0x20   /* Continuous high-resolution mode */
#define BH1750_MEASURE_MS 180   /* Conversion time per datasheet */

#define WS2812B_GPIO     18     /* BCM 18 = PCM_CLK */
#define NUM_LEDS         10

/*
 * WS2812B timing (microseconds).
 *   t0H ≥ 0.40 us, t0L ≥ 0.85 us  → 0 bit
 *   t1H ≥ 0.80 us, t1L ≥ 0.45 us  → 1 bit
 * We use 1 us for both high and low so the PWM period is 2 us.
 */
#define WS2812B_T0H      1
#define WS2812B_T0L      1
#define WS2812B_T1H      1
#define WS2812B_T1L      1

/*
 * PWM/wave configuration.
 *   PWM period = 2 us (1000 ns)
 *   Duty cycle = 50 % (500 ns)
 *   We use a 1 MHz clock source (pigpio/hardware PWM default).
 */
#define PWM_PERIOD_NS    1000
#define PWM_DUTY_NS      500

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ----------------------------- Signal handler ----------------------------- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ----------------------------- Helpers ----------------------------------- */
static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

/* ----------------------------- BH1750 ------------------------------------ */
static int bh1750_init(int fd)
{
    /* Power on (write 0x01), then set continuous high-resolution mode. */
    if (write(fd, (uint8_t[]){0x01}, 1) != 1) {
        fprintf(stderr, "BH1750 power-on failed: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(5);

    if (write(fd, (uint8_t[]){BH1750_CMD_ONE}, 1) != 1) {
        fprintf(stderr, "BH1750 mode set failed: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(5);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint8_t buf[2];

    /* Trigger a forced measurement. */
    if (write(fd, (uint8_t[]){BH1750_CMD_ONE}, 1) != 1) {
        fprintf(stderr, "BH1750 trigger failed: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(BH1750_MEASURE_MS * 1000);

    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "BH1750 read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ----------------------------- WS2812B (hardware PWM via sysfs) ----------- */
/*
 * The Raspberry Pi 4 exposes a PWM channel on GPIO18 that the kernel
 * driver exposes via sysfs.  We use the standard sysfs PWM path and
 * the pigpio-style duty-cycle trick to generate the precise WS2812B
 * timing.
 */
static int ws2812b_init(void)
{
    /* Export GPIO18 to the PWM subsystem. */
    FILE *ex = fopen("/sys/class/pwm/pwmchip0/export", "w");
    if (!ex) {
        if (errno != EBUSY) {
            fprintf(stderr, "PWM export failed: %s\n", strerror(errno));
            return -1;
        }
    } else {
        if (fprintf(ex, "0") < 0) {
            fprintf(stderr, "PWM export write failed: %s\n", strerror(errno));
            fclose(ex);
            return -1;
        }
        fclose(ex);
        sleep_us(100000);  /* let sysfs settle */
    }

    /* Set period (1 MHz base, 2 us = 2000 ns). */
    FILE *per = fopen("/sys/class/pwm/pwmchip0/pwm0/period", "w");
    if (!per) {
        fprintf(stderr, "PWM period file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(per, "%d", PWM_PERIOD_NS) < 0) {
        fprintf(stderr, "PWM period write failed: %s\n", strerror(errno));
        fclose(per);
        return -1;
    }
    fclose(per);

    /* Set initial duty cycle (500 ns). */
    FILE *dut = fopen("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "w");
    if (!dut) {
        fprintf(stderr, "PWM duty_cycle file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(dut, "%d", PWM_DUTY_NS) < 0) {
        fprintf(stderr, "PWM duty_cycle write failed: %s\n", strerror(errno));
        fclose(dut);
        return -1;
    }
    fclose(dut);

    /* Enable PWM output. */
    FILE *ena = fopen("/sys/class/pwm/pwmchip0/pwm0/enable", "w");
    if (!ena) {
        fprintf(stderr, "PWM enable file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(ena, "1") < 0) {
        fprintf(stderr, "PWM enable write failed: %s\n", strerror(errno));
        fclose(ena);
        return -1;
    }
    fclose(ena);

    return 0;
}

static void ws2812b_set_brightness(float lux)
{
    /*
     * Map lux (0–1000) to a logarithmic brightness level (0–255).
     *   brightness = 255 * (1 – exp(-lux / 100))
     */
    float b = 255.0f * (1.0f - expf(-lux / 100.0f));
    if (b < 0.0f)   b = 0.0f;
    if (b > 255.0f) b = 255.0f;

    /*
     * WS2812B expects GRB order.  We use the pigpio-style duty-cycle
     * trick to generate the precise timing: for each bit, we set the
     * duty cycle to 50 % for a 0 bit or 100 % for a 1 bit, then wait
     * for the period.
     */
    uint8_t grb[NUM_LEDS * 3];
    for (int i = 0; i < NUM_LEDS; i++) {
        grb[i * 3 + 0] = (uint8_t)b;  /* G */
        grb[i * 3 + 1] = (uint8_t)b;  /* R */
        grb[i * 3 + 2] = (uint8_t)b;  /* B */
    }

    /*
     * Write the bitstream directly to the PWM duty_cycle file.
     * Each byte is 8 bits, MSB first.  For each bit:
     *   duty = 500 ns for 0, 1000 ns for 1.
     */
    for (int byte = 0; byte < NUM_LEDS * 3; byte++) {
        for (int bit = 7; bit >= 0; bit--) {
            int ns = ((grb[byte] >> bit) & 1) ? PWM_PERIOD_NS : PWM_DUTY_NS;
            FILE *dut = fopen("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "w");
            if (!dut) {
                fprintf(stderr, "PWM duty_cycle open failed: %s\n", strerror(errno));
                return;
            }
            if (fprintf(dut, "%d", ns) < 0) {
                fprintf(stderr, "PWM duty_cycle write failed: %s\n", strerror(errno));
                fclose(dut);
                return;
            }
            fclose(dut);
            sleep_us(1);  /* ~1 us per bit → ~1 ms per byte */
        }
    }

    /*
     * WS2812B requires a reset pulse: hold the data line low for >= 50 us.
     * We use a 10 us low pulse to be safe.
     */
    FILE *dut = fopen("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "w");
    if (!dut) {
        fprintf(stderr, "PWM duty_cycle open failed: %s\n", strerror(errno));
        return;
    }
    if (fprintf(dut, "0") < 0) {
        fprintf(stderr, "PWM duty_cycle write failed: %s\n", strerror(errno));
        fclose(dut);
        return;
    }
    fclose(dut);
    sleep_us(10);
}

static void ws2812b_cleanup(void)
{
    /* Disable PWM output. */
    FILE *ena = fopen("/sys/class/pwm/pwmchip0/pwm0/enable", "w");
    if (ena) {
        fprintf(ena, "0");
        fclose(ena);
    }

    /* Set duty cycle to 0. */
    FILE *dut = fopen("/sys/class/pwm/pwmchip0/pwm0/duty_cycle", "w");
    if (dut) {
        fprintf(dut, "0");
        fclose(dut);
    }

    /* Unexport the PWM channel. */
    FILE *unex = fopen("/sys/class/pwm/pwmchip0/unexport", "w");
    if (unex) {
        fprintf(unex, "0");
        fclose(unex);
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus. */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize BH1750. */
    if (bh1750_init(g_i2c_fd) != 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor may be absent).\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize WS2812B via hardware PWM. */
    if (ws2812b_init() != 0) {
        fprintf(stderr, "WS2812B PWM initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Light sensor (BH1750) and WS2812B LED strip running.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop. */
    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Sensor read error; retrying in 1 s.\n");
            sleep_us(1000000);
            continue;
        }

        if (lux < 0.0f) lux = 0.0f;
        if (lux > 1000.0f) lux = 1000.0f;

        ws2812b_set_brightness(lux);
        printf("Lux: %.2f  Brightness: %.0f\n", lux, lux);

        sleep_us(500000);  /* 0.5 s loop cadence */
    }

    /* Cleanup. */
    ws2812b_cleanup();
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

