/*
 * Raspberry Pi Zero W: BH1750 ambient light sensor → APA102 LED strip.
 *
 * Wiring:
 *   BH1750  SDA → GPIO2 (pin 3), SCL → GPIO3 (pin 5), VCC 3V3, GND
 *   APA102  SCLK → GPIO11 (pin 23, SPI0 SCLK), MOSI → GPIO10 (pin 19, SPI0 MOSI),
 *           VCC 3V3, GND
 *
 * Build:  gcc -O2 -Wall -o light_led light_led.c -lm
 * Run:    sudo ./light_led   (SPI/I2C require root on some Pi models)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_DEVICE     "/dev/spidev0.0"
#define BH1750_ADDR    0x2a
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_H  0x10
#define BH1750_CONT_L  0x11
#define BH1750_CONV_MS 120

#define NUM_LEDS       30
#define SPI_SPEED_HZ   1000000
#define SPI_BITS        8
#define SPI_DELAY_US   0

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write 0x%02x failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }
    /* BH1750 sends LSB first */
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ---- APA102 helpers ---- */

static void apa102_build_frame(uint32_t *frame, int num_leds)
{
    /*
     * APA102 frame layout (32-bit words):
     *   word 0: start frame (8 × 0x00)
     *   word 1..N: LED frames (4 bytes each, MSB-first: B, G, R, brightness)
     *   word N+1: end frame (4 bytes of 0xFF)
     */
    int n = num_leds * 4 + 2;
    memset(frame, 0x00, (size_t)n * sizeof(uint32_t));
    for (int i = 0; i < num_leds; i++) {
        /* brightness = 0xE0 (11100000) → 100 % */
        frame[1 + i] = 0xE0000000;
    }
    for (int i = 0; i < 4; i++)
        frame[n - 1] |= 0xFF << (8 * i);
}

static int apa102_update(int spi_fd, uint32_t *frame, int num_leds)
{
    int n = num_leds * 4 + 2;
    uint8_t *buf = malloc((size_t)n * sizeof(uint32_t));
    if (!buf) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        return -1;
    }
    for (int i = 0; i < n; i++) {
        /* APA102 expects MSB-first data */
        buf[i] = (uint8_t)(frame[i] >> 24);
    }
    ssize_t total = (ssize_t)(n * sizeof(uint32_t));
    ssize_t off = 0;
    while (off < total) {
        ssize_t w = write(spi_fd, buf + off, (size_t)(total - off));
        if (w < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
            free(buf);
            return -1;
        }
        off += w;
    }
    free(buf);
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    int i2c_fd = -1, spi_fd = -1;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus ---- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02x failed: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- open SPI device ---- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = SPI_BITS;
    uint32_t spi_speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0) {
        fprintf(stderr, "SPI WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0) {
        fprintf(stderr, "SPI WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "SPI WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- BH1750 init ---- */
    if (i2c_write_cmd(i2c_fd, BH1750_PWR_ON) < 0) goto cleanup;
    if (i2c_write_cmd(i2c_fd, BH1750_RESET) < 0) goto cleanup;
    if (i2c_write_cmd(i2c_fd, BH1750_CONT_H) < 0) goto cleanup;

    /* ---- main loop ---- */
    uint32_t *frame = malloc((size_t)(NUM_LEDS * 4 + 2) * sizeof(uint32_t));
    if (!frame) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        /* trigger a one-shot conversion */
        if (i2c_write_cmd(i2c_fd, BH1750_CONT_H) < 0) break;
        usleep(BH1750_CONV_MS * 1000);

        uint16_t raw;
        if (i2c_read16(i2c_fd, &raw) < 0) {
            fprintf(stderr, "BH1750 read error — turning LEDs off\n");
            apa102_build_frame(frame, NUM_LEDS);
            apa102_update(spi_fd, frame, NUM_LEDS);
            break;
        }

        /* clamp to a physically reasonable range (0–65535) */
        float lux = (float)raw;
        if (lux > 65535.0f) lux = 65535.0f;

        /* scale: 0 lux → 0 brightness, 65535 lux → 100 % brightness */
        float brightness = lux / 65535.0f;
        if (brightness > 1.0f) brightness = 1.0f;

        apa102_build_frame(frame, NUM_LEDS);
        for (int i = 0; i < NUM_LEDS; i++) {
            /*
             * APA102 brightness is 0xE0..0x0F, so the scaled value
             * is clamped to the 4-bit range.  For a full-color LED
             * strip we could set R=brightness, G=0, B=0.
             */
            uint8_t b = (uint8_t)(brightness * 15.0f);
            if (b > 15) b = 15;
            frame[1 + i] = (uint32_t)(0xE0 | (b << 4));
        }

        if (apa102_update(spi_fd, frame, NUM_LEDS) < 0) break;

        usleep(50000); /* 50 ms loop cadence */
    }

    /* ---- turn off all LEDs on exit ---- */
    apa102_build_frame(frame, NUM_LEDS);
    apa102_update(spi_fd, frame, NUM_LEDS);
    ret = EXIT_SUCCESS;

    free(frame);

cleanup:
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return ret;
}

