/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient light reader + APA102 brightness controller.
 *
 * Hardware:
 *   - Up to three BH1750 sensors on I2C bus 1 (addresses 0x23 or 0x5C).
 *   - APA102 LED strip driven over hardware SPI (MOSI = GPIO10, SCLK = GPIO11).
 *
 * Build:
 *   gcc -O2 -Wall -o light_ctrl light_ctrl.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for SPI/I2C).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BH1750 constants ---- */
#define BH1750_ADDR_1   0x23
#define BH1750_ADDR_2   0x5C
#define BH1750_PWR_ON   0x01
#define BH1750_RESET    0x07
#define BH1750_CONT_H   0x10   /* continuous high-resolution mode */
#define BH1750_CONV_MS  180    /* conversion time ~120 ms, margin */

/* ---- APA102 constants ---- */
#define APA102_LED_COUNT 10
#define APA102_START_FRAME_SIZE 4
#define APA102_END_FRAME_SIZE   4
#define APA102_T0H_US  1
#define APA102_T0L_US  1
#define APA102_T1H_US  1
#define APA102_T1L_US  1
#define APA102_RESET_US 100000 /* 100 ms reset pulse */

#define SPI_CHANNEL    0       /* CE0 / GPIO8 */
#define SPI_BAUD       1000000 /* 1 MHz */
#define SPI_FLAGS      0

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[3] = {-1, -1, -1};
static int g_spi_handle = -1;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- BH1750 helpers ---- */
static int bh1750_open(int addr)
{
    int h = i2cOpen(1, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[BH1750] i2cOpen(0x%02X) failed: %s\n",
                addr, pigpio_error(h));
        return -1;
    }
    /* Power on */
    if (i2cWriteByte(h, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "[BH1750] power-on failed at 0x%02X\n", addr);
        i2cClose(h);
        return -1;
    }
    /* Reset */
    if (i2cWriteByte(h, BH1750_RESET) < 0) {
        fprintf(stderr, "[BH1750] reset failed at 0x%02X\n", addr);
        i2cClose(h);
        return -1;
    }
    return h;
}

static int bh1750_read_lux(int handle)
{
    if (i2cWriteByte(handle, BH1750_CONT_H) < 0) {
        fprintf(stderr, "[BH1750] write mode failed\n");
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000); /* microseconds */

    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[BH1750] read failed (got %d bytes)\n", n);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (int)(raw / 1.2);
}

/* ---- APA102 helpers ---- */
static void apa102_set_brightness(int brightness)
{
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t frame[APA102_LED_COUNT * 4 + APA102_START_FRAME_SIZE + APA102_END_FRAME_SIZE];
    size_t idx = 0;

    /* Start frame */
    memset(&frame[idx], 0x00, APA102_START_FRAME_SIZE);
    idx += APA102_START_FRAME_SIZE;

    /* LED frames */
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        frame[idx++] = 0xE0 | ((brightness >> 5) & 0x1F); /* G */
        frame[idx++] = 0xE0 | ((brightness >> 5) & 0x1F); /* R */
        frame[idx++] = 0xE0 | ((brightness >> 5) & 0x1F); /* B */
        frame[idx++] = 0xE0 | ((brightness >> 5) & 0x1F); /* A */
    }

    /* End frame */
    memset(&frame[idx], 0xFF, APA102_END_FRAME_SIZE);
    idx += APA102_END_FRAME_SIZE;

    if (spiWrite(g_spi_handle, (char *)frame, idx) != (int)idx) {
        fprintf(stderr, "[APA102] SPI write failed\n");
    }
}

/* ---- Fade ---- */
static void apa102_fade(int target, int duration_ms)
{
    int current = 0;
    int elapsed = 0;
    int step_ms = 10;
    int step = (target - current) / (duration_ms / step_ms);
    if (step == 0) step = (target > current) ? 1 : -1;

    while (current != target && elapsed < duration_ms && g_running) {
        current += step;
        if (current < 0) current = 0;
        if (current > 255) current = 255;
        apa102_set_brightness(current);
        gpioDelay(step_ms * 1000);
        elapsed += step_ms;
    }
    apa102_set_brightness(target);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    for (int i = 0; i < 3; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }
    if (g_spi_handle >= 0) {
        apa102_set_brightness(0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open BH1750 sensors at both addresses */
    int addrs[2] = {BH1750_ADDR_1, BH1750_ADDR_2};
    for (int i = 0; i < 3; i++) {
        g_i2c_handles[i] = -1;
        if (i < 2) {
            g_i2c_handles[i] = bh1750_open(addrs[i]);
            if (g_i2c_handles[i] >= 0) {
                printf("BH1750 sensor %d at 0x%02X opened\n", i + 1, addrs[i]);
            } else {
                fprintf(stderr, "BH1750 sensor %d not found\n", i + 1);
            }
        }
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    int current_brightness = 0;
    int target_brightness = 0;

    printf("Starting main loop. Press Ctrl+C to exit.\n");

    while (g_running) {
        int valid_count = 0;
        int sum = 0;

        /* Read all sensors */
        for (int i = 0; i < 3; i++) {
            if (g_i2c_handles[i] < 0) continue;
            int lux = bh1750_read_lux(g_i2c_handles[i]);
            if (lux >= 0) {
                sum += lux;
                valid_count++;
            }
        }

        if (valid_count > 0) {
            int avg_lux = sum / valid_count;
            target_brightness = (int)((float)avg_lux / 1000.0f * 255.0f);
            if (target_brightness > 255) target_brightness = 255;
            if (target_brightness < 0) target_brightness = 0;

            if (target_brightness != current_brightness) {
                printf("Avg lux: %d  ->  target brightness: %d\n",
                       avg_lux, target_brightness);
                apa102_fade(target_brightness, 500);
                current_brightness = target_brightness;
            }
        } else {
            fprintf(stderr, "No valid sensor readings this cycle\n");
        }

        gpioDelay(100 * 1000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

