/*
 * VEML7700 → WS2812B controller for Raspberry Pi 5
 *
 * Hardware:
 *   - VEML7700 I2C address: 0x50 (ADDR pin tied to GND)
 *   - VEML7700 data register: 0x04 (ALS_CONF) → 0x0000 (default, no SD)
 *   - VEML7700 ALS data register: 0x04 (ALS_DATA)
 *   - WS2812B data line: GPIO18 (BCM), 800 kHz bit-bang via sysfs
 *
 * Build:  gcc -O2 -Wall -o veml7700_ws2812 veml7700_ws2812.c
 *
 * NOTE: The WS2812B bit-bang timing is very sensitive to the exact
 *       execution speed of the CPU.  This program uses sysfs to
 *       toggle the GPIO line at the required frequencies; falling
 *       back to a simple threshold-based on/off scheme if the
 *       sysfs interface is unavailable or the timing loop fails.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VEML7700_ADDR  0x50
#define ALS_CONF_REG   0x00
#define ALS_DATA_REG   0x04
#define ALS_CONF_VAL   0x0000
#define GPIO_CHIP       "gpiochip4"
#define GPIO_OFFSET     18          /* BCM 18 */
#define LED_COUNT       100
#define MAX_LUX         1000.0f
#define MIN_LUX         0.0f
#define MAX_BRIGHTNESS  255
#define GAMMA           2.2f
#define POLL_MS         200
#define RETRY_COUNT     3
#define RETRY_DELAY_MS  100
#define BIT_THRESHOLD   128         /* simple threshold for safe mode */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_fd = -1;

/* ---------- helpers ---------- */

static void sleep_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void sleep_us(unsigned us)
{
    struct timespec ts = { 0, (long)us * 1000L };
    nanosleep(&ts, NULL);
}

/* ---------- I2C ---------- */

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val & 0xFF), (uint8_t)((val >> 8) & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf))
        return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf))
        return -1;
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int veml7700_init(int fd)
{
    if (i2c_write16(fd, ALS_CONF_REG, ALS_CONF_VAL) < 0) {
        fprintf(stderr, "VEML7700 config write failed: %s\n", strerror(errno));
        return -1;
    }
    sleep_ms(10);
    return 0;
}

static int veml7700_read_lux(int fd, float *lux)
{
    uint16_t raw;
    if (i2c_read16(fd, ALS_DATA_REG, &raw) < 0)
        return -1;
    *lux = (float)raw;
    return 0;
}

/* ---------- GPIO sysfs helpers ---------- */

static int gpio_export(void)
{
    char path[64];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "gpio export open failed: %s\n", strerror(errno));
            return -1;
        }
        return 0;  /* already exported */
    }
    snprintf(path, sizeof(path), "%d", GPIO_OFFSET);
    if (write(fd, path, strlen(path)) < 0 && errno != EBUSY) {
        fprintf(stderr, "gpio export failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(void)
{
    char path[64];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "gpio unexport open failed: %s\n", strerror(errno));
        return -1;
    }
    snprintf(path, sizeof(path), "%d", GPIO_OFFSET);
    if (write(fd, path, strlen(path)) < 0) {
        fprintf(stderr, "gpio unexport failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(const char *dir)
{
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", GPIO_OFFSET);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "gpio direction open failed: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "gpio direction set failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int val)
{
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", GPIO_OFFSET);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "gpio value open failed: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, val ? "1" : "0", 1) < 0) {
        fprintf(stderr, "gpio value set failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

/* ---------- WS2812B bit-bang ---------- */

/*
 * WS2812B timing (800 kHz, 565 mode):
 *   T0H >= 0.40 us, T0L >= 0.85 us
 *   T1H >= 0.80 us, T1L >= 0.45 us
 *   Reset: 50 us low
 */

static void ws2812_reset(void)
{
    gpio_set_value(0);
    sleep_us(50);
}

static void ws2812_send_byte(uint8_t byte)
{
    for (int i = 7; i >= 0; i--) {
        gpio_set_value(1);
        sleep_us(1);
        if (byte & (1 << i))
            gpio_set_value(1);
        else
            gpio_set_value(0);
        sleep_us(1);
    }
}

static void ws2812_send_frame(uint8_t *frame, int len)
{
    for (int i = 0; i < len; i++)
        ws2812_send_byte(frame[i]);
    ws2812_reset();
}

static void ws2812_set_brightness(int brightness)
{
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t frame[LED_COUNT * 3];
    memset(frame, (uint8_t)brightness, sizeof(frame));
    ws2812_send_frame(frame, sizeof(frame));
}

/* ---------- brightness mapping ---------- */

static int map_lux_to_brightness(float lux)
{
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float norm = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    float gamma_norm = powf(norm, 1.0f / GAMMA);
    int brightness = (int)(gamma_norm * (float)MAX_BRIGHTNESS + 0.5f);
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    return brightness;
}

/* ---------- cleanup ---------- */

static void cleanup(void)
{
    if (g_gpio_fd >= 0) {
        gpio_set_value(0);
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpio_unexport();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- main ---------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* I2C */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "I2C slave set failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (veml7700_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 init failed\n");
        close(g_i2c_fd);
        return 1;
    }

    /* GPIO sysfs */
    if (gpio_export() < 0) {
        fprintf(stderr, "GPIO export failed; falling back to simple threshold\n");
    } else {
        if (gpio_set_direction("out") < 0) {
            fprintf(stderr, "GPIO direction set failed; falling back\n");
            gpio_unexport();
        } else {
            g_gpio_fd = open("/sys/class/gpio/gpio18/value", O_WRONLY);
            if (g_gpio_fd < 0) {
