            sleep_ms(RETRY_DELAY_MS);
        }

        if (!ok) {
            fprintf(stderr, "All I2C retries exhausted; skipping cycle\n");
            sleep_ms(POLL_MS);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);

        if (g_gpio_fd >= 0) {
            /* bit-bang WS2812B via sysfs */
            ws2812_set_brightness(brightness);
        } else {
            /* simple threshold-based LED control */
            if (brightness > BIT_THRESHOLD)
                gpio_set_value(1);
            else
                gpio_set_value(0);
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        sleep_ms(POLL_MS);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return 0;
}

