/*
 * KY-026 Flame Sensor Self-Test & Monitoring for Raspberry Pi 5
 *
 * Wiring:
 *   KY-026 digital OUT -> BCM GPIO4  (active-low: LOW = flame detected)
 *   Buzzer (+)         -> BCM GPIO17 (active-high)
 *   LED anode          -> BCM GPIO18 (active-high)
 *   KY-026 VCC         -> 3.3 V
 *   KY-026 GND         -> GND
 *   Buzzer GND         -> GND
 *   LED cathode        -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN       17
#define LED_PIN          18

/* ---- Timing constants (microseconds unless noted) ---- */
#define BLINK_ON_US      500000          /* 500 ms LED on  */
#define BLINK_OFF_US     500000          /* 500 ms LED off */
#define RAPID_BLINK_ON_US   100000       /* 100 ms rapid blink */
#define RAPID_BLINK_OFF_US  100000       /* 100 ms rapid blink */
#define SAMPLE_DELAY_US    100000        /* 100 ms between samples */
#define POLL_DELAY_US      50000         /* 50 ms poll interval */
#define BUZZER_SHORT_US    200000        /* 200 ms */
#define BUZZER_LONG_US     600000        /* 600 ms */
#define BUZZER_REPEAT      3

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Blinking                                                           */
/* ------------------------------------------------------------------ */
static void blink_led(unsigned on_us, unsigned off_us, int cycles)
{
    for (int i = 0; i < cycles && g_running; i++) {
        if (safe_write(LED_PIN, 1) != 0) return;
        gpioDelay(on_us);
        if (safe_write(LED_PIN, 0) != 0) return;
        gpioDelay(off_us);
    }
}

static void buzzer_pattern(void)
{
    for (int i = 0; i < BUZZER_REPEAT && g_running; i++) {
        if (safe_write(BUZZER_PIN, 1) != 0) return;
        gpioDelay(BUZZER_SHORT_US);
        if (safe_write(BUZZER_PIN, 0) != 0) return;
        gpioDelay(BUZZER_SHORT_US);
        if (safe_write(BUZZER_PIN, 1) != 0) return;
        gpioDelay(BUZZER_LONG_US);
        if (safe_write(BUZZER_PIN, 0) != 0) return;
        gpioDelay(BUZZER_SHORT_US);
    }
}

/* ------------------------------------------------------------------ */
/* Self-test                                                          */
/* ------------------------------------------------------------------ */
static int self_test(void)
{
    log_event("Starting self-test...");

    /* Blink LED 500 ms on, 500 ms off twice */
    for (int i = 0; i < 2 && g_running; i++) {
        if (safe_write(LED_PIN, 1) != 0) return -1;
        gpioDelay(BLINK_ON_US);
        if (safe_write(LED_PIN, 0) != 0) return -1;
        gpioDelay(BLINK_OFF_US);
    }

    log_event("Self-test: LED blinks twice.");

    /* Read flame sensor five times at 100 ms intervals */
    int flame_count = 0;
    for (int i = 0; i < 5 && g_running; i++) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) {
            log_event("Self-test: GPIO read error during flame sensor sampling.");
            return -1;
        }
        if (v == 0)
            flame_count++;
        if (i < 4)
            gpioDelay(SAMPLE_DELAY_US);
    }

    if (flame_count == 5) {
        log_event("Self-test: Flame sensor detected on all samples.");
        return -1;
    }

    log_event("Self-test: Flame sensor OK.");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Best-effort: turn off outputs */
    gpioWrite(LED_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (safe_set_mode(FLAME_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(BUZZER_PIN, PI_OUTPUT)     != 0 ||
        safe_set_mode(LED_PIN, PI_OUTPUT)        != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure outputs start OFF */
    safe_write(BUZZER_PIN, 0);
    safe_write(LED_PIN, 0);

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Self-test */
    if (self_test() != 0) {
        log_event("Self-test failed: persistent flame detected.");
        blink_led(RAPID_BLINK_ON_US, RAPID_BLINK_OFF_US, 5);
        buzzer_pattern();
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Self-test passed. Monitoring flame sensor...");

    /* Main loop */
    bool flame_active = false;
    while (g_running) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) {
            log_event("Error reading flame sensor; retrying...");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (v == 0) {
            /* Flame detected (active-low) */
            if (!flame_active) {
                log_event("Flame detected!");
                if (safe_write(LED_PIN, 1) != 0 ||
                    safe_write(BUZZER_PIN, 1) != 0) {
                    log_event("Error: failed to activate alarm.");
                }
                flame_active = true;
            }
        } else {
            /* No flame */
            if (flame_active) {
                log_event("Flame cleared.");
                safe_write(LED_PIN, 0);
                safe_write(BUZZER_PIN, 0);
                flame_active = false;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

