/*
 * Raspberry Pi 4 Model B — BH1750 ambient light sensor → LED blink
 *
 * Hardware:
 *   BH1750  SDA → GPIO2  (BCM 2,  physical pin 3)
 *           SCL → GPIO3  (BCM 3,  physical pin 5)
 *           VDD → 3.3 V
 *           GND → GND
 *   LED     anode → GPIO17 (BCM 17, physical pin 11)
 *           cathode → GND
 *
 * Behavior:
 *   - Reads the BH1750 every second via /dev/i2c-1.
 *   - Stores the last 60 readings in a circular buffer.
 *   - Computes the average lux over the buffer.
 *   - Drives an LED on GPIO17 with a 50 % duty cycle square wave whose
 *     frequency varies from 0.5 Hz in darkness to 5 Hz at bright levels.
 *   - On SIGINT / SIGTERM the program releases GPIO and I2C resources
 *     cleanly and exits.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bh1750_led bh1750_led.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x2a          /* ADDR pin tied to GND */
#define BH1750_CMD_AUTO  0x10        /* continuous high-res mode */
#define BH1750_CONV_MS  180          /* max conversion time (ms) */

#define GPIO_CHIP       "/sys/class/gpio/gpiochip0"
#define LED_PIN         17            /* BCM 17 */

#define BUFFER_SIZE     60
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int gpio_export(unsigned pin)
{
    char buf[32];
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%u", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        if (errno == EBUSY) {                 /* already exported */
            close(fd);
            return 0;
        }
        fprintf(stderr, "gpio_export(%u): %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(unsigned pin)
{
    char buf[32];
    int fd = open(GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) for unexport: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%u", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        if (errno == EBUSY || errno == EINVAL) {
            close(fd);
            return 0;
        }
        fprintf(stderr, "gpio_unexport(%u): %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(unsigned pin, const char *dir)
{
    char path[128];
    snprintf(path, sizeof(path), "%s/gpio%u/direction", GPIO_CHIP, pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "gpio_set_direction(%u, %s): %s\n", pin, dir, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(unsigned pin, int val)
{
    char path[128];
    snprintf(path, sizeof(path), "%s/gpio%u/value", GPIO_CHIP, pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    char buf[4];
    snprintf(buf, sizeof(buf), "%d", val);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "gpio_write(%u, %d): %s\n", pin, val, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02x): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "bh1750_write_cmd(0x%02x): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "bh1750_read_lux: %s\n", strerror(errno));
        else
            fprintf(stderr, "bh1750_read_lux: short read (%zd bytes)\n", n);
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    float buf[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void cb_push(CircularBuffer *cb, float val)
{
    cb->buf[cb->head] = val;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_avg(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buf[i];
    return sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */

static void led_set_duty(float lux)
{
    /* 0.5 Hz at 0 lux, 5 Hz at 1000+ lux */
    float freq = 0.5f + (lux / 1000.0f) * 4.5f;
    if (freq < 0.5f) freq = 0.5f;
    if (freq > 5.0f) freq = 5.0f;

    /* 50 % duty cycle: half the period is spent high, half low */
    int half_period_us = (int)(500000.0f / freq);
    if (half_period_us < 1000) half_period_us = 1000;   /* sanity */

    gpio_write(LED_PIN, 1);
    usleep(half_period_us);
    gpio_write(LED_PIN, 0);
    usleep(half_period_us);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpio_export(LED_PIN) < 0)
        return EXIT_FAILURE;
    if (gpio_set_direction(LED_PIN, "out") < 0) {
        gpio_unexport(LED_PIN);
        return EXIT_FAILURE;
    }

    /* ---- I2C setup ---- */
    int i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        gpio_unexport(LED_PIN);
        return EXIT_FAILURE;
    }

    /* ---- circular buffer ---- */
    CircularBuffer lux_buf;
    cb_init(&lux_buf);

    /* ---- main loop ---- */
    while (g_running) {
        /* Start a single-shot measurement */
        if (bh1750_write_cmd(i2c_fd, BH1750_CMD_AUTO) < 0) {
            fprintf(stderr, "BH1750 write failed; retrying next cycle\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Wait for conversion */
        usleep(BH1750_CONV_MS * 1000);

        float lux = 0.0f;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read failed; retrying next cycle\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        cb_push(&lux_buf, lux);
        float avg = cb_avg(&lux_buf);

        printf("Lux: %.2f  Avg: %.2f\n", lux, avg);
        fflush(stdout);

        led_set_duty(avg);

        sleep(SAMPLE_PERIOD_S);
    }

    /* ---- cleanup ---- */
    gpio_write(LED_PIN, 0);
    gpio_unexport(LED_PIN);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

