        if (bh1750_write_cmd(i2c_fd, BH1750_CMD_AUTO) < 0) {
            fprintf(stderr, "BH1750 write failed; retrying next cycle\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Wait for conversion */
        usleep(BH1750_CONV_MS * 1000);

        float lux = 0.0f;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read failed; retrying next cycle\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        cb_push(&lux_buf, lux);
        float avg = cb_avg(&lux_buf);

        printf("Lux: %.2f  Avg: %.2f\n", lux, avg);
        fflush(stdout);

        led_set_duty(avg);

        sleep(SAMPLE_PERIOD_S);
    }

    /* ---- cleanup ---- */
    gpio_write(LED_PIN, 0);
    gpio_unexport(LED_PIN);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

