#include <signal.h>
#include <pigpio.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

/* Segment pattern for digit '5' (common cathode, active high):
 *   a b c d e f g dp
 *   1 1 1 0 1 1 1 0  -> 0xFC
 */
#define DIGIT_5_PATTERN 0xFC

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void shift_out(uint8_t data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        gpioWrite(DATA_PIN, bit);
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); /* 1 µs high clock */
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); /* 1 µs low clock  */
    }
}

static void latch_data(void) {
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); /* 1 µs latch */
    gpioWrite(LATCH_PIN, 0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all lines start low */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    while (running) {
        shift_out(DIGIT_5_PATTERN);
        latch_data();
        gpioDelay(500000); /* 500 ms on */

        if (!running) break;

        shift_out(0x00);
        latch_data();
        gpioDelay(500000); /* 500 ms off */
    }

    /* Clean shutdown: blank display and release pins */
    shift_out(0x00);
    latch_data();
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_INPUT);
    gpioSetMode(LATCH_PIN, PI_INPUT);
    gpioTerminate();
    return EXIT_SUCCESS;
}

