/*
 * blink_button.c — Raspberry Pi (any model with 40-pin header)
 *
 * Blinks an LED on GPIO17 (BCM 17, physical pin 11) with a 2-second period
 * (1 s on, 1 s off) while waiting for a falling-edge event from a momentary
 * push button on GPIO18 (BCM 18, physical pin 12).  The LED is requested
 * initially as an output line (value 0), the button is requested as an
 * input line with pull-up and falling-edge event detection.  On detection
 * the LED is turned off, a message is printed, and the program exits.
 *
 * Build:  gcc -o blink_button blink_button.c -lgpiod
 * Run:    sudo ./blink_button   (or ensure user is in the 'gpio' group)
 */

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>

#define LED_LINE    17          /* BCM 17, physical pin 11 */
#define BUTTON_LINE 18          /* BCM 18, physical pin 12 */
#define CHIP_NAME   "gpiochip0"
#define BLINK_MS    1000        /* 1 s half-period */
#define POLL_MS     1000        /* 1 s poll timeout for event wait */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    struct gpiod_line *button = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Install SIGINT handler for graceful Ctrl-C exit ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open the GPIO chip ---- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* ---- Get the LED line ---- */
    led = gpiod_chip_get_line(chip, LED_LINE);
    if (!led) {
        perror("gpiod_chip_get_line(LED)");
        goto cleanup;
    }

    /* ---- Request LED as output, initially low ---- */
    if (gpiod_line_request_output(led, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* ---- Get the button line ---- */
    button = gpiod_chip_get_line(chip, BUTTON_LINE);
    if (!button) {
        perror("gpiod_chip_get_line(BUTTON)");
        goto cleanup;
    }

    /* ---- Request button as input with pull-up and falling-edge events ---- */
    if (gpiod_line_request_falling_edge_events_flags(
            button, "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_falling_edge_events_flags");
        goto cleanup;
    }

    printf("Waiting for button press on GPIO%d (BCM)...\n", BUTTON_LINE);
    fflush(stdout);

    /* ---- Main blink loop ---- */
    while (g_running) {
        /* Blink LED on */
        if (gpiod_line_set_value(led, 1) < 0) {
            perror("gpiod_line_set_value(LED on)");
            goto cleanup;
        }
        usleep(BLINK_MS * 1000);
        if (!g_running)
            break;

        /* Blink LED off */
        if (gpiod_line_set_value(led, 0) < 0) {
            perror("gpiod_line_set_value(LED off)");
            goto cleanup;
        }
        usleep(BLINK_MS * 1000);

        /* Poll for a falling-edge event with a 1-second timeout */
        ret = gpiod_line_event_wait(button, &(struct timespec){ .tv_sec = POLL_MS / 1000, .tv_nsec = (POLL_MS % 1000) * 1000000L });
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (ret > 0) {
            /* Event detected — read it to clear the event queue */
            struct gpiod_line_event event;
            if (gpiod_line_event_read(button, &event) < 0) {
                perror("gpiod_line_event_read");
                goto cleanup;
            }
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed! Stopping LED blink.\n");
                fflush(stdout);
                g_running = 0;
                break;
            }
        }
    }

    /* ---- Turn LED off before exiting ---- */
    if (led)
        gpiod_line_set_value(led, 0);

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines and close chip ---- */
    if (led)
        gpiod_line_release(led);
    if (button)
        gpiod_line_release(button);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

