 *   10 k ohm   -> from GPIO22 to GND (or internal pull-down if available)
 *
 * Build:  gcc -O2 -Wall -Wextra -o gpio_blink gpio_blink.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define LED_PIN    24   /* BCM 24 */
#define BUTTON_PIN 22   /* BCM 22 */
#define CHIP_NAME  "gpiochip4"  /* main GPIO controller on Pi 5; use "gpiochip0" on Pi 3/4 */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* retry after signal interruption */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *btn_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- get the LED line --- */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get LED line (BCM %d): %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- get the button line --- */
    btn_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (btn_line == NULL) {
        fprintf(stderr, "Failed to get button line (BCM %d): %s\n",
                BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- request LED as output, initially low --- */
    if (gpiod_line_request_output(led_line, "led-blink", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- request button as input with internal pull-down --- */
    if (gpiod_line_request_input_flags(btn_line, "button-blink",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to request button line as input with pull-down: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("LED on GPIO%d, button on GPIO%d. Press Ctrl+C to exit.\n",
           LED_PIN, BUTTON_PIN);

    bool led_on = false;
    bool prev_pressed = false;

    while (g_running) {
        int val = gpiod_line_get_value(btn_line);
        if (val < 0) {
            fprintf(stderr, "Error reading button: %s\n", strerror(errno));
            goto cleanup;
        }

        bool pressed = (val == 1);

        if (pressed && !prev_pressed) {
            /* button just pressed: turn LED on */
            led_on = true;
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error writing LED on: %s\n", strerror(errno));
                goto cleanup;
            }
        } else if (!pressed && prev_pressed) {
            /* button just released: turn LED off */
            led_on = false;
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error writing LED off: %s\n", strerror(errno));
                goto cleanup;
            }
        }

        prev_pressed = pressed;

        if (led_on) {
            sleep_ms(500);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error writing LED off: %s\n", strerror(errno));
                goto cleanup;
            }
            sleep_ms(500);
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error writing LED on: %s\n", strerror(errno));
                goto cleanup;
            }
        } else {
            sleep_ms(10);  /* idle poll interval */
        }
    }

    /* --- graceful shutdown: ensure LED is off --- */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }
    ret = EXIT_SUCCESS;

cleanup:
    /* lines are released automatically when the chip is closed */
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

