#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    24
#define GREEN_PIN  23
#define BLUE_PIN   18

#define PWM_PERIOD_US 10000  /* 10 ms = 100 Hz */
#define PWM_STEPS     100    /* 0-99 range */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(uint32_t us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    while (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts) == -1) {
        /* Retry on EINTR (interrupted by signal) */
    }
}

static void pwm_set(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_STEPS) duty = PWM_STEPS;

    uint32_t on_us  = (uint32_t)duty * PWM_PERIOD_US / PWM_STEPS;
    uint32_t off_us = PWM_PERIOD_US - on_us;

    if (on_us > 0) {
        if (gpioWrite(pin, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(pin=%d, 1) failed\n", pin);
        }
        sleep_us(on_us);
    }
    if (off_us > 0) {
        if (gpioWrite(pin, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(pin=%d, 0) failed\n", pin);
        }
        sleep_us(off_us);
    }
}

int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(RED_PIN=%d, PI_OUTPUT) failed\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(GREEN_PIN=%d, PI_OUTPUT) failed\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BLUE_PIN=%d, PI_OUTPUT) failed\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Seed the random number generator */
    srand((unsigned int)time(NULL));

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int red   = rand() % (PWM_STEPS + 1);
        int green = rand() % (PWM_STEPS + 1);
        int blue  = rand() % (PWM_STEPS + 1);

        printf("R=%3d G=%3d B=%3d\n", red, green, blue);

        pwm_set(RED_PIN,   red);
        pwm_set(GREEN_PIN, green);
        pwm_set(BLUE_PIN,  blue);
    }

    /* Clean shutdown: turn off all LEDs and release GPIO lines */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

