code:
/*
 * LSM303DLHC Impact Detector for Raspberry Pi Zero W
 *
 * Polls the LSM303DLHC accelerometer on I2C bus 1 at 10 Hz, computes the
 * total G-force magnitude, and when it exceeds a threshold the GPIO17 pin
 * is pulsed HIGH for 50 ms as an impact indicator.  All data is logged to
 * impact_log.txt.
 *
 * Build:  gcc -O2 -Wall -o impact_detector impact_detector.c -lm
 * Run:    ./impact_detector [-t threshold_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

/* ---- LSM303DLHC accelerometer constants ---- */
#define LSM303_ACCEL_ADDR        0x19
#define LSM303_ACCEL_CTRL_REG1   0x20
#define LSM303_ACCEL_CTRL_REG4   0x23
#define LSM303_ACCEL_OUT_X_L     0x28
#define LSM303_ACCEL_OUT_X_H     0x29
#define LSM303_ACCEL_OUT_Y_L     0x2A
#define LSM303_ACCEL_OUT_Y_H     0x2B
#define LSM303_ACCEL_OUT_Z_L     0x2C
#define LSM303_ACCEL_OUT_Z_H     0x2D

/* ---- Hardware / application constants ---- */
#define I2C_BUS                  1
#define GPIO_PIN                 17
#define POLL_DELAY_US            100000   /* 10 Hz */
#define PULSE_DURATION_US        50000    /* 50 ms */
#define DEFAULT_THRESHOLD_G      2.0f
#define LOG_FILE                 "impact_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian axis value from the LSM303DLHC.         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_axis(int handle, uint8_t low_reg, int16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, low_reg, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the LSM303DLHC accelerometer: normal mode, 10 Hz ODR.     */
/* ------------------------------------------------------------------ */
static int configure_accelerometer(int handle)
{
    /* CTRL_REG1: 0x57 = 0b01010111 -> normal mode, ODR = 10 Hz */
    if (i2cWriteByteData(handle, LSM303_ACCEL_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }
    /* CTRL_REG4: 0x00 -> ±2 g full-scale, high-resolution disabled */
    if (i2cWriteByteData(handle, LSM303_ACCEL_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute the total G-force magnitude from the three axes.           */
/* ------------------------------------------------------------------ */
static float calculate_g_force(int16_t x, int16_t y, int16_t z)
{
    /*
     * LSM303DLHC accelerometer sensitivity:
     *   1 mg/LSB in normal mode (±2 g full-scale).
     *   1 g = 1000 mg.
     */
    const float x_g = (float)x / 1000.0f;
    const float y_g = (float)y / 1000.0f;
    const float z_g = (float)z / 1000.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

/* ------------------------------------------------------------------ */
/* Pulse the GPIO pin HIGH for PULSE_DURATION_US, then LOW.            */
/* ------------------------------------------------------------------ */
static void trigger_interrupt(int pin)
{
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d HIGH\n", pin);
        return;
    }
    gpioDelay(PULSE_DURATION_US);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d LOW\n", pin);
    }
}

/* ------------------------------------------------------------------ */
/* Log a timestamped accelerometer reading to the log file.           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float g)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %6d, Y: %6d, Z: %6d, G: %.2f\n", ts, x, y, z, g);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure GPIO17 is LOW before terminating pigpio */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD_G;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            threshold = (float)atof(optarg);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO17 as output, initially LOW ---- */
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    /* ---- Open I2C bus 1 at LSM303DLHC accelerometer address ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, LSM303_ACCEL_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor ---- */
    if (configure_accelerometer(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM303DLHC not detected or configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detector running. Threshold: %.2f G | GPIO%d | 10 Hz\n",
           threshold, GPIO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_axis(g_i2c_handle, LSM303_ACCEL_OUT_X_L, &x) < 0 ||
            read_axis(g_i2c_handle, LSM303_ACCEL_OUT_Y_L, &y) < 0 ||
            read_axis(g_i2c_handle, LSM303_ACCEL_OUT_Z_L, &z) < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float g = calculate_g_force(x, y, z);

        if (g > threshold) {
            trigger_interrupt(GPIO_PIN);
        }

        log_data(g_log_file, x, y, z, g);
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

