        fprintf(stderr, "Error writing CTRL_REG4\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute the total G-force magnitude from the three axes.           */
/* ------------------------------------------------------------------ */
static float calculate_g_force(int16_t x, int16_t y, int16_t z)
{
    /*
     * LSM303DLHC accelerometer sensitivity:
     *   1 mg/LSB in normal mode (±2 g full-scale).
     *   1 g = 1000 mg.
     */
    const float x_g = (float)x / 1000.0f;
    const float y_g = (float)y / 1000.0f;
    const float z_g = (float)z / 1000.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

/* ------------------------------------------------------------------ */
/* Pulse the GPIO pin HIGH for PULSE_DURATION_US, then LOW.            */
/* ------------------------------------------------------------------ */
static void trigger_interrupt(int pin)
{
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d HIGH\n", pin);
        return;
    }
    gpioDelay(PULSE_DURATION_US);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d LOW\n", pin);
    }
}

/* ------------------------------------------------------------------ */
/* Log a timestamped accelerometer reading to the log file.           */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float g)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %6d, Y: %6d, Z: %6d, G: %.2f\n", ts, x, y, z, g);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure GPIO17 is LOW before terminating pigpio */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD_G;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            threshold = (float)atof(optarg);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO17 as output, initially LOW ---- */
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    /* ---- Open I2C bus 1 at LSM303DLHC accelerometer address ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, LSM303_ACCEL_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor ---- */
    if (configure_accelerometer(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM303DLHC not detected or configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detector running. Threshold: %.2f G | GPIO%d | 10 Hz\n",
           threshold, GPIO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_axis(g_i2c_handle, LSM303_ACCEL_OUT_X_L, &x) < 0 ||
            read_axis(g_i2c_handle, LSM303_ACCEL_OUT_Y_L, &y) < 0 ||
            read_axis(g_i2c_handle, LSM303_ACCEL_OUT_Z_L, &z) < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float g = calculate_g_force(x, y, z);

        if (g > threshold) {
            trigger_interrupt(GPIO_PIN);
        }

        log_data(g_log_file, x, y, z, g);
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

