/*
 * Raspberry Pi Zero W - FXOS8700CQ Impact Logger
 *
 * Reads acceleration (x, y, z) over I2C bus 1 at 50 ms intervals,
 * computes the magnitude, and logs events above a threshold to
 * impact_log.txt with a timestamp.
 *
 * Build:  gcc -O2 -Wall -o impact_logger impact_logger.c -lpigpio -lm
 * Run:    sudo ./impact_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- FXOS8700CQ I2C constants ------------------------------------------ */
#define FXOS8700_I2C_ADDR        0x1C          /* SA0 tied to GND */
#define FXOS8700_WHO_AM_I        0x0D
#define FXOS8700_WHO_AM_I_VAL    0xC7

#define FXOS8700_CTRL_REG1       0x2A
#define FXOS8700_CTRL_REG2       0x2B
#define FXOS8700_M_CTRL_REG1     0x5B
#define FXOS8700_M_CTRL_REG2     0x5C
#define FXOS8700_OUT_X_MSB       0x01          /* accel X MSB (auto-increment) */

/* ---- Application constants --------------------------------------------- */
#define I2C_BUS                  1
#define SAMPLE_PERIOD_US         50000         /* 50 ms */
#define IMPACT_THRESHOLD         2.0           /* g */
#define LOG_FILE                 "impact_log.txt"

/* ---- Globals for signal-safe cleanup ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ------------------------------------------------------- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %s\n",
                reg, len, pigpio_error(rc));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData short read: got %d, expected %u\n",
                rc, len);
        return -1;
    }
    return 0;
}

/* ---- FXOS8700CQ driver ------------------------------------------------- */
static int fxos8700_init(int handle)
{
    uint8_t who;
    if (i2c_read_reg(handle, FXOS8700_WHO_AM_I, &who) != 0)
        return -1;
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby so configuration changes take effect immediately */
    if (i2c_write_reg(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* ±2 g range (FS = 00), no high-pass filter */
    if (i2c_write_reg(handle, FXOS8700_CTRL_REG2, 0x00) != 0)
        return -1;

    /* M_CTRL_REG1: auto-increment, no magnetometer */
    if (i2c_write_reg(handle, FXOS8700_M_CTRL_REG1, 0x1F) != 0)
        return -1;

    /* M_CTRL_REG2: no F_READ, no auto-sleep */
    if (i2c_write_reg(handle, FXOS8700_M_CTRL_REG2, 0x00) != 0)
        return -1;

    /* Activate: 200 Hz ODR, normal mode */
    if (i2c_write_reg(handle, FXOS8700_CTRL_REG1, 0x0D) != 0)
        return -1;

    return 0;
}

static int fxos8700_read_accel(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* ±2 g range: 1 LSB = 4 mg = 0.004 g */
    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;
    return 0;
}

static float accel_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(float x, float y, float z, float mag)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, mag);
    }
    fclose(fp);
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, FXOS8700_I2C_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- sensor init --- */
    if (fxos8700_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] FXOS8700 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("FXOS8700CQ impact logger started.  Threshold: %.1f g  Log: %s\n",
           IMPACT_THRESHOLD, LOG_FILE);
    printf("Press Ctrl-C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        float x, y, z;
        if (fxos8700_read_accel(g_i2c_handle, &x, &y, &z) == 0) {
            float mag = accel_magnitude(x, y, z);
            if (mag > IMPACT_THRESHOLD) {
                log_impact(x, y, z, mag);
                printf("[IMPACT] mag=%.3f g  x=%.3f y=%.3f z=%.3f\n",
                       mag, x, y, z);
            }
        }
        /* else: error already printed; continue loop */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        /* Put sensor in standby before closing */
        (void)i2cWriteByteData(g_i2c_handle, FXOS8700_CTRL_REG1, 0x00);
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

