/*
 * GY-50 L3G4200D gyroscope logger with 100-sample stationary calibration.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: GY-50 L3G4200D (I2C address 0x68)
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c
 * Run:    ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants ------------------------------------------------ */
#define L3G4200D_ADDR        0x68
#define WHO_AM_I_REG         0x0F
#define WHO_AM_I_VAL         0xD3
#define CTRL_REG1            0x20
#define CTRL_REG4            0x23
#define OUT_X_L              0x28
#define OUT_X_H              0x29
#define OUT_Y_L              0x2A
#define OUT_Y_H              0x2B
#define OUT_Z_L              0x2C
#define OUT_Z_H              0x2D

#define SAMPLE_COUNT         100
#define SAMPLE_PERIOD_US     50000   /* 50 ms -> 20 Hz */
#define ALERT_THRESHOLD_DPS  50.0
#define LOG_FILE             "gyro_log.txt"

/* ---- Globals for signal-safe cleanup ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Gyroscope data ---------------------------------------------------- */
typedef struct {
    float x, y, z;
} gyro_data_t;

/* ---- Calibration offsets ----------------------------------------------- */
typedef struct {
    float x_off, y_off, z_off;
} gyro_cal_t;

/* ---- Prototypes -------------------------------------------------------- */
static int  i2c_write_reg(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg(int fd, uint8_t reg, uint8_t *val);
static int  i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len);
static int  gyro_init(int fd);
static int  gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z);
static gyro_data_t gyro_calibrate(int fd, int count);
static gyro_data_t gyro_read_calibrated(int fd, const gyro_cal_t *cal);
static void log_data(FILE *fp, const gyro_data_t *d);
static void log_alert(FILE *fp, const gyro_data_t *d);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- Low-level I2C helpers --------------------------------------------- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst read(0x%02X): got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Gyroscope helpers ------------------------------------------------- */
static int gyro_init(int fd)
{
    /*
     * CTRL_REG1: ODR=100 Hz (0x0F), all axes enabled.
     * CTRL_REG4: FS=245 dps (0x00), continuous update.
     */
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L | 0x80, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static gyro_data_t gyro_calibrate(int fd, int count)
{
    gyro_data_t cal = { 0.0f, 0.0f, 0.0f };
    int16_t x, y, z;

    printf("Calibrating gyroscope (%d samples)...\n", count);
    for (int i = 0; i < count; i++) {
        if (gyro_read_raw(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            continue;
        }
        cal.x += (float)x;
        cal.y += (float)y;
        cal.z += (float)z;
        usleep(10000); /* 10 ms between samples */
    }
    cal.x /= count;
    cal.y /= count;
    cal.z /= count;
    printf("Calibration offsets: X=%.2f Y=%.2f Z=%.2f\n", cal.x, cal.y, cal.z);
    return cal;
}

static gyro_data_t gyro_read_calibrated(int fd, const gyro_cal_t *cal)
{
    gyro_data_t d = { 0.0f, 0.0f, 0.0f };
    int16_t x, y, z;

    if (gyro_read_raw(fd, &x, &y, &z) < 0)
        return d;

    d.x = (float)x - cal->x_off;
    d.y = (float)y - cal->y_off;
    d.z = (float)z - cal->z_off;
    return d;
}

/* ---- Logging ----------------------------------------------------------- */
static void log_data(FILE *fp, const gyro_data_t *d)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;

    if (localtime_r(&t, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, d->x, d->y, d->z);
    fflush(fp);
}

static void log_alert(FILE *fp, const gyro_data_t *d)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;

    if (localtime_r(&t, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s,ALERT,%.2f,%.2f,%.2f\n", ts, d->x, d->y, d->z);
    fflush(fp);
}

/* ---- Signal handling --------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, L3G4200D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n",
                L3G4200D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t whoami = 0;
    if (i2c_read_reg(g_i2c_fd, WHO_AM_I_REG, &whoami) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I – sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gyro_cal_t cal = gyro_calibrate(g_i2c_fd, SAMPLE_COUNT);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl-C to stop.\n", LOG_FILE);

    while (g_running) {
        gyro_data_t d = gyro_read_calibrated(g_i2c_fd, &cal);
        log_data(g_log_fp, &d);

        if (fabsf(d.x) > ALERT_THRESHOLD_DPS ||
            fabsf(d.y) > ALERT_THRESHOLD_DPS ||
            fabsf(d.z) > ALERT_THRESHOLD_DPS) {
            fprintf(stderr, "ALERT: |%.2f| |%.2f| |%.2f| > %.1f dps\n",
                    d.x, d.y, d.z, ALERT_THRESHOLD_DPS);
            log_alert(g_log_fp, &d);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

