    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst read(0x%02X): got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Gyroscope helpers ------------------------------------------------- */
static int gyro_init(int fd)
{
    /*
     * CTRL_REG1: ODR=100 Hz (0x0F), all axes enabled.
     * CTRL_REG4: FS=245 dps (0x00), continuous update.
     */
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L | 0x80, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static gyro_data_t gyro_calibrate(int fd, int count)
{
    gyro_data_t cal = { 0.0f, 0.0f, 0.0f };
    int16_t x, y, z;

    printf("Calibrating gyroscope (%d samples)...\n", count);
    for (int i = 0; i < count; i++) {
        if (gyro_read_raw(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            continue;
        }
        cal.x += (float)x;
        cal.y += (float)y;
        cal.z += (float)z;
        usleep(10000); /* 10 ms between samples */
    }
    cal.x /= count;
    cal.y /= count;
    cal.z /= count;
    printf("Calibration offsets: X=%.2f Y=%.2f Z=%.2f\n", cal.x, cal.y, cal.z);
    return cal;
}

static gyro_data_t gyro_read_calibrated(int fd, const gyro_cal_t *cal)
{
    gyro_data_t d = { 0.0f, 0.0f, 0.0f };
    int16_t x, y, z;

    if (gyro_read_raw(fd, &x, &y, &z) < 0)
        return d;

    d.x = (float)x - cal->x_off;
    d.y = (float)y - cal->y_off;
    d.z = (float)z - cal->z_off;
    return d;
}

/* ---- Logging ----------------------------------------------------------- */
static void log_data(FILE *fp, const gyro_data_t *d)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;

    if (localtime_r(&t, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, d->x, d->y, d->z);
    fflush(fp);
}

static void log_alert(FILE *fp, const gyro_data_t *d)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;

    if (localtime_r(&t, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    fprintf(fp, "%s,ALERT,%.2f,%.2f,%.2f\n", ts, d->x, d->y, d->z);
    fflush(fp);
}

/* ---- Signal handling --------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, L3G4200D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n",
                L3G4200D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t whoami = 0;
    if (i2c_read_reg(g_i2c_fd, WHO_AM_I_REG, &whoami) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I – sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gyro_cal_t cal = gyro_calibrate(g_i2c_fd, SAMPLE_COUNT);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl-C to stop.\n", LOG_FILE);

    while (g_running) {
        gyro_data_t d = gyro_read_calibrated(g_i2c_fd, &cal);
        log_data(g_log_fp, &d);

        if (fabsf(d.x) > ALERT_THRESHOLD_DPS ||
            fabsf(d.y) > ALERT_THRESHOLD_DPS ||
            fabsf(d.z) > ALERT_THRESHOLD_DPS) {
            fprintf(stderr, "ALERT: |%.2f| |%.2f| |%.2f| > %.1f dps\n",
                    d.x, d.y, d.z, ALERT_THRESHOLD_DPS);
            log_alert(g_log_fp, &d);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * ADXL345 accelerometer reader with LED threshold indicator.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA, physical pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL, physical pin 5)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   LED anode    -> GPIO17 (BCM 17, physical pin 11) via 330 Ω resistor
 *   LED cathode  -> GND
 *
 * Build:  gcc -O2 -Wall -o adxl345_log adxl345_log.c -lpigpio -lrt
 * Run:    sudo ./adxl345_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (datasheet) ---- */
#define ADXL345_ADDRESS        0x53          /* SA0 tied to GND */
#define ADXL345_DEVID          0x00          /* Device ID register (read-only) */
#define ADXL345_DEVID_VALUE    0xE5          /* ADXL345 expected device ID */
#define ADXL345_POWER_CTL      0x2D          /* Power-saving features control */
#define ADXL345_DATA_FORMAT    0x31          /* Data format register */
#define ADXL345_DATAX0         0x32          /* X-axis data register (low byte) */
#define ADXL345_BW_RATE        0x2C          /* Bandwidth rate register */

/* ---- Application constants ---- */
#define I2C_BUS                1
#define LED_GPIO               17            /* BCM 17 */
#define SAMPLE_PERIOD_US       100000        /* 100 ms -> 10 Hz */
#define ACCEL_THRESHOLD_G      2.0f
#define SCALE_FACTOR_G         0.0039f       /* 3.9 m/s² per g (full-res, ±2 g) */
#define LOG_FILE_NAME          "accel_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl_write_byte(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, then configure for full-res,
 * ±2 g, right-justified, interrupts off, measurement mode. */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;
    if (adxl_read_byte(handle, ADXL345_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby first so configuration changes take effect immediately. */
    if (adxl_write_byte(handle, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* DATA_FORMAT: 0x0B = full resolution (bit 3), ±2 g (bits 1:0 = 00),
     * right-justified (bit 3), interrupts off (bits 2:0 = 000). */
    if (adxl_write_byte(handle, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* BW_RATE: 0x0A = 100 Hz output data rate (bits 4:0 = 1010). */
    if (adxl_write_byte(handle, ADXL345_BW_RATE, 0x0A) != 0)
        return -1;

    /* POWER_CTL: 0x08 = measurement mode (bit 3). */
    if (adxl_write_byte(handle, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z) in full-resolution mode.
 * Returns 0 on success, -1 on error. */
static int adxl345_read_acceleration(int handle,
                                      float *x_g, float *y_g, float *z_g)
{
    char buffer[6];

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed\n");
        return -1;
    }

    int16_t x = (int16_t)(((uint8_t)buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t y = (int16_t)(((uint8_t)buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t z = (int16_t)(((uint8_t)buffer[5] << 8) | (uint8_t)buffer[4]);

    *x_g = (float)x * SCALE_FACTOR_G;
    *y_g = (float)y * SCALE_FACTOR_G;
    *z_g = (float)z * SCALE_FACTOR_G;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ADXL345 init ---- */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s for appending\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float x_g, y_g, z_g;

        if (adxl345_read_acceleration(g_i2c_handle, &x_g, &y_g, &z_g) == 0) {
            log_data(g_log_file, x_g, y_g, z_g);

            bool threshold_exceeded =
                (fabsf(x_g) > ACCEL_THRESHOLD_G) ||
                (fabsf(y_g) > ACCEL_THRESHOLD_G) ||
                (fabsf(z_g) > ACCEL_THRESHOLD_G);

            gpioWrite(LED_GPIO, threshold_exceeded ? 1 : 0);
        } else {
            /* On read failure, turn LED off and log a placeholder line. */
            gpioWrite(LED_GPIO, 0);
            fprintf(g_log_file, "ERROR,0.000,0.000,0.000\n");
            fflush(g_log_file);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

