    while (g_running) {
        float x_g, y_g, z_g;

        if (adxl345_read_acceleration(g_i2c_handle, &x_g, &y_g, &z_g) == 0) {
            log_data(g_log_file, x_g, y_g, z_g);

            bool threshold_exceeded =
                (fabsf(x_g) > ACCEL_THRESHOLD_G) ||
                (fabsf(y_g) > ACCEL_THRESHOLD_G) ||
                (fabsf(z_g) > ACCEL_THRESHOLD_G);

            gpioWrite(LED_GPIO, threshold_exceeded ? 1 : 0);
        } else {
            /* On read failure, turn LED off and log a placeholder line. */
            gpioWrite(LED_GPIO, 0);
            fprintf(g_log_file, "ERROR,0.000,0.000,0.000\n");
            fflush(g_log_file);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
