/*
 * Raspberry Pi Zero W – GY-51 LSM303DLHC tilt-compensated compass logger
 *
 * Wiring:
 *   LSM303DLHC VCC  -> Pi 3V3  (pin 1)
 *   LSM303DLHC GND  -> Pi GND  (pin 9)
 *   LSM303DLHC SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   LSM303DLHC SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -o compass compass.c -lm -lpigpio -lrt
 * Run:    sudo ./compass
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ADDR_ACCEL   0x19
#define LSM303_ADDR_MAG     0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_CTRL_REG1_A  0x20
#define LSM303_CTRL_REG4_A  0x23
#define LSM303_OUT_X_L_A    0x28
#define LSM303_OUT_X_H_A    0x29
#define LSM303_OUT_Y_L_A    0x2A
#define LSM303_OUT_Y_H_A    0x2B
#define LSM303_OUT_Z_L_A    0x2C
#define LSM303_OUT_Z_H_A    0x2D
#define LSM303_MR_REG_M     0x02
#define LSM303_OUT_X_L_M    0x08
#define LSM303_OUT_X_H_M    0x09
#define LSM303_OUT_Y_L_M    0x0A
#define LSM303_OUT_Y_H_M    0x0B
#define LSM303_OUT_Z_L_M    0x0C
#define LSM303_OUT_Z_H_M    0x0D

/* ---- Sensitivities (LSB per g / gauss) ---- */
#define ACCEL_SENSITIVITY   0.000061f   /* 1 mg / LSB  */
#define MAG_SENSITIVITY     0.000146f   /* 10 mgauss / LSB */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_accel_handle = -1;
static int g_mag_handle   = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an LSM303 register; returns 0 on success, -1 on error. */
static int lsm303_write_reg(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(handle=%d, reg=0x%02X, val=0x%02X) failed\n",
                handle, reg, val);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an LSM303 register; returns 0 on success, -1 on error. */
static int lsm303_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(handle=%d, reg=0x%02X) failed\n",
                handle, reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian axis; returns 0 on success, -1 on error. */
static int lsm303_read_axis(int handle, uint8_t low_reg, int16_t *out)
{
    uint8_t lo, hi;
    if (lsm303_read_reg(handle, low_reg, &lo) < 0) return -1;
    if (lsm303_read_reg(handle, low_reg + 1, &hi) < 0) return -1;
    *out = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the LSM303DLHC: accelerometer + magnetometer. */
static int lsm303_init(int accel_handle, int mag_handle)
{
    /* Accelerometer: normal mode, 50 Hz ODR, all axes enabled. */
    if (lsm303_write_reg(accel_handle, LSM303_CTRL_REG1_A, 0x57) < 0) return -1;
    /* Accelerometer: +/- 2 g full-scale. */
    if (lsm303_write_reg(accel_handle, LSM303_CTRL_REG4_A, 0x00) < 0) return -1;
    /* Magnetometer: medium performance, continuous conversion mode. */
    if (lsm303_write_reg(mag_handle, LSM303_MR_REG_M, 0x00) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six axes; returns 0 on success, -1 on error. */
static int lsm303_read_all(int accel_handle, int mag_handle,
                           float *ax, float *ay, float *az,
                           float *mx, float *my, float *mz)
{
    int16_t raw_ax, raw_ay, raw_az, raw_mx, raw_my, raw_mz;

    if (lsm303_read_axis(accel_handle, LSM303_OUT_X_L_A, &raw_ax) < 0) return -1;
    if (lsm303_read_axis(accel_handle, LSM303_OUT_Y_L_A, &raw_ay) < 0) return -1;
    if (lsm303_read_axis(accel_handle, LSM303_OUT_Z_L_A, &raw_az) < 0) return -1;
    if (lsm303_read_axis(mag_handle,   LSM303_OUT_X_L_M, &raw_mx) < 0) return -1;
    if (lsm303_read_axis(mag_handle,   LSM303_OUT_Y_L_M, &raw_my) < 0) return -1;
    if (lsm303_read_axis(mag_handle,   LSM303_OUT_Z_L_M, &raw_mz) < 0) return -1;

    *ax = (float)raw_ax * ACCEL_SENSITIVITY;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY;
    *az = (float)raw_az * ACCEL_SENSITIVITY;
    *mx = (float)raw_mx * MAG_SENSITIVITY;
    *my = (float)raw_my * MAG_SENSITIVITY;
    *mz = (float)raw_mz * MAG_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt-compensated heading (degrees) from accel + mag. */
static float calculate_heading(float ax, float ay, float az,
                                float mx, float my, float mz)
{
    /*
     * Tilt compensation: rotate the magnetic field vector so that the
     * Z-axis of the magnetic coordinate system points towards the Earth's
     * magnetic field (North).  This is the orientation that the
     * GY-51 module outputs when the magnetometer is in continuous-conversion
     * mode.
     */
    float mx_comp = mx * cosf(ay * M_PI / 180.0f) + mz * sinf(ay * M_PI / 180.0f);
    float my_comp = my;
    float mz_comp = -mx * sinf(ay * M_PI / 180.0f) + mz * cosf(ay * M_PI / 180.0f);

    float roll  = atan2f(ay, ax);
    float pitch = atan2f(-az, sqrtf(ax * ax + ay * ay));

    float mx_rot = mx_comp * cosf(pitch) + mz_comp * sinf(pitch);
    float my_rot = mx_comp * sinf(roll) * sinf(pitch)
                 + my_comp * cosf(roll)
                 - mz_comp * cosf(pitch) * sinf(roll);

    float heading = atan2f(my_rot, mx_rot) * 180.0f / M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float heading,
                     float ax, float ay, float az,
                     float mx, float my, float mz)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C handles ---- */
    g_accel_handle = i2cOpen(1, LSM303_ADDR_ACCEL, 0);
    if (g_accel_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(accel, 0x%02X) failed: %d\n",
                LSM303_ADDR_ACCEL, g_accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_mag_handle = i2cOpen(1, LSM303_ADDR_MAG, 0);
    if (g_mag_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(mag, 0x%02X) failed: %d\n",
                LSM303_ADDR_MAG, g_mag_handle);
        i2cClose(g_accel_handle);
        g_accel_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- verify sensor presence ---- */
    uint8_t who_mag;
    if (lsm303_read_reg(g_mag_handle, LSM303_MR_REG_M, &who_mag) < 0) {
        fprintf(stderr, "[FATAL] Magnetometer not responding at 0x%02X\n",
                LSM303_ADDR_MAG);
        goto cleanup;
    }

    /* ---- init sensors ---- */
    if (lsm303_init(g_accel_handle, g_mag_handle) < 0) {
        fprintf(stderr, "[FATAL] LSM303DLHC initialisation failed\n");
        goto cleanup;
    }

    /* ---- open log file ---- */
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "[FATAL] Cannot open compass_log.txt\n");
        goto cleanup;
    }

    /* write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,heading_deg,ax_g,ay_g,az_g,mx_gauss,my_gauss,mz_gauss\n");
        fflush(fp);
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM303DLHC compass logging started. Press Ctrl-C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        float ax, ay, az, mx, my, mz, heading;

        if (lsm303_read_all(g_accel_handle, g_mag_handle,
                            &ax, &ay, &az, &mx, &my, &mz) < 0) {
            fprintf(stderr, "[WARN] Sensor read error – continuing\n");
            gpioDelay(100000);
            continue;
        }

        heading = calculate_heading(ax, ay, az, mx, my, mz);
        log_data(fp, heading, ax, ay, az, mx, my, mz);
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down gracefully...\n");

    fclose(fp);

cleanup:
    if (g_accel_handle >= 0) i2cClose(g_accel_handle);
    if (g_mag_handle   >= 0) i2cClose(g_mag_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

