                if (g_i2c_handle >= 0) {
                    if (vl6180x_init(g_i2c_handle) == 0)
                        break;
                    i2cClose(g_i2c_handle);
                    g_i2c_handle = -1;
                }
                gpioDelay(INIT_DELAY_US);
            }

            if (g_i2c_handle < 0)
                fprintf(stderr, "[ERROR] Sensor re-initialization failed.\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- Clean shutdown ---- */
    if (g_i2c_handle >= 0) {
        (void)vl6180x_write_byte(g_i2c_handle, REG_SYSRANGE_START, 0x00);
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\n[INFO] Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

