/*
 * Raspberry Pi 4 Model B – Dual IMP23ABSU Ultrasonic Microphone TDOA Logger
 *
 * Wiring:
 *   Sensor 1  I2C bus 1, address 0x48
 *   Sensor 2  I2C bus 1, address 0x49
 *   3.3 V     Pin 1  (VDD)
 *   GND       Pin 9  (GND)
 *   SDA       Pin 3  (GPIO2 / I2C bus 1 SDA)
 *   SCL       Pin 5  (GPIO3 / I2C bus 1 SCL)
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c -lpigpio -lrt
 * Run:    sudo ./audio_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x48
#define SENSOR2_ADDR         0x49
#define SAMPLE_PERIOD_US     10000          /* 10 ms */
#define LOG_FILE_NAME        "audio_log.dat"
#define MAX_CONSECUTIVE_ERR  100            /* abort after this many failures */

/*
 * IMP23ABSU 16-bit audio register (big-endian on the bus).
 * pigpio's i2cReadWordData returns the raw 16-bit word as read on the wire,
 * so we must swap bytes to get the correct 16-bit signed value.
 */
#define IMP23_AUDIO_REG      0x00

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_h1 = -1;
static int      g_i2c_h2 = -1;
static FILE    *g_log    = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(int bus, int addr);
static int  read_audio_sample(int handle, int16_t *out);
static double calculate_tdoa(int16_t s1, int16_t s2,
                              struct timespec ts1, struct timespec ts2);
static void log_data(FILE *fp, int16_t s1, int16_t s2, double tdoa);
static void cleanup(void);

/* ------------------------------- Handlers -------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_h1 >= 0) { i2cClose(g_i2c_h1); g_i2c_h1 = -1; }
    if (g_i2c_h2 >= 0) { i2cClose(g_i2c_h2); g_i2c_h2 = -1; }
    if (g_log != NULL) { fclose(g_log); g_log = NULL; }
    gpioTerminate();
}

/* ------------------------------ I2C helpers ------------------------------ */
static int init_i2c(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                bus, addr, h);
        return -1;
    }
    return h;
}

/*
 * Read one 16-bit audio sample from the IMP23ABSU.
 * pigpio's i2cReadWordData returns the raw 16-bit word as read on the wire,
 * so we swap bytes to get the correct 16-bit signed value.
 */
static int read_audio_sample(int handle, int16_t *out)
{
    int w = i2cReadWordData(handle, IMP23_AUDIO_REG);
    if (w < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData failed: %d\n", w);
        return -1;
    }
    /* pigpio returns the raw 16-bit word; swap bytes to get the correct value */
    uint16_t swapped = (uint16_t)(((w & 0x00FF) << 8) | ((w & 0xFF00) >> 8));
    *out = (int16_t)swapped;
    return 0;
}

/* ---------------------------- TDOA calculation --------------------------- */
static double calculate_tdoa(int16_t s1, int16_t s2,
                              struct timespec ts1, struct timespec ts2)
{
    double t1 = (double)ts1.tv_sec + (double)ts1.tv_nsec / 1.0e9;
    double t2 = (double)ts2.tv_sec + (double)ts2.tv_nsec / 1.0e9;
    return t2 - t1;
}

/* ------------------------------ CSV logging ------------------------------ */
static void log_data(FILE *fp, int16_t s1, int16_t s2, double tdoa)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld,%09ld,%d,%d,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
    fflush(fp);
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C handles --- */
    g_i2c_h1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (g_i2c_h1 < 0) { gpioTerminate(); return EXIT_FAILURE; }

    g_i2c_h2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (g_i2c_h2 < 0) { i2cClose(g_i2c_h1); gpioTerminate(); return EXIT_FAILURE; }

    /* --- open log file --- */
    g_log = fopen(LOG_FILE_NAME, "a");
    if (g_log == NULL) {
        perror("[FATAL] fopen(" LOG_FILE_NAME ")");
        i2cClose(g_i2c_h1);
        i2cClose(g_i2c_h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- write CSV header if file is empty --- */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "sec,nsec,sensor1,sensor2,tdoa\n");
        fflush(g_log);
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Logging TDOA from IMP23ABSU@0x%02X and IMP23ABSU@0x%02X "
           "to %s (Ctrl+C to stop)\n", SENSOR1_ADDR, SENSOR2_ADDR, LOG_FILE_NAME);

    int consecutive_err = 0;

    while (g_running) {
        int16_t s1 = 0, s2 = 0;
        struct timespec ts1, ts2;

        if (read_audio_sample(g_i2c_h1, &s1) != 0) {
            if (++consecutive_err >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "[FATAL] Too many consecutive I2C errors "
                                "(%d >= %d); aborting.\n",
                        consecutive_err, MAX_CONSECUTIVE_ERR);
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_err = 0;

        if (read_audio_sample(g_i2c_h2, &s2) != 0) {
            if (++consecutive_err >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "[FATAL] Too many consecutive I2C errors "
                                "(%d >= %d); aborting.\n",
                        consecutive_err, MAX_CONSECUTIVE_ERR);
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_err = 0;

        clock_gettime(CLOCK_REALTIME, &ts1);
        /* Small delay so the second sample arrives at a different timestamp */
        gpioDelay(100);
        clock_gettime(CLOCK_REALTIME, &ts2);

        double tdoa = calculate_tdoa(s1, s2, ts1, ts2);
        log_data(g_log, s1, s2, tdoa);

        gpioDelay(SAMPLE_PERIOD_US - 100);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

