/*
 * ADIS16488A IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16488A CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16488A SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16488A DOUT-> GPIO9  (BCM 9,  SPI0 MISO)
 *   ADIS16488A DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16488A VDD-> 3.3 V
 *   ADIS16488A GND-> GND
 *
 * SPI: mode 3 (CPOL=1, CPHA=1), 1 MHz, 16-bit words.
 *
 * Build: gcc -O2 -Wall -o imu_reader imu_reader.c -lpigpio -lrt
 * Run:   sudo ./imu_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16488A register map (subset) ---- */
#define ADIS16488A_REG_GX_OUT  0x04
#define ADIS16488A_REG_GY_OUT  0x06
#define ADIS16488A_REG_GZ_OUT  0x08
#define ADIS16488A_REG_AX_OUT  0x0A
#define ADIS16488A_REG_AY_OUT  0x0C
#define ADIS16488A_REG_AZ_OUT  0x0E

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0x0003     /* mode 3: CPOL=1, CPHA=1 */

/* ---- Conversions ---- */
#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define STALL_US         40       /* min stall between command and data */

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit register from the ADIS16488A.
 * The ADIS16488A returns data on the *subsequent* 16-bit transfer,
 * so we send a command word (16-bit, MSB=0, 7-bit register address),
 * stall for >= 40 us, then read the data word.
 * Returns 0 on success, -1 on SPI error.
 */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  ret;

    tx[0] = (char)(reg & 0x7F);   /* MSB = 0 -> read */
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (cmd 0x%02X) failed: %d\n", reg, ret);
        return -1;
    }

    gpioDelay(STALL_US);          /* stall >= 40 us per datasheet */

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer (data 0x%02X) failed: %d\n", reg, ret);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];
    int16_t raw;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    int consecutive_errors = 0;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- CSV file ---- */
    csv_file = fopen("imu_data.csv", "w");
    if (!csv_file) {
        perror("fopen imu_data.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(csv_file);

    /* ---- cleanup + signals ---- */
    atexit(cleanup);

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16488A IMU logging started. Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (running) {
        if (read_register(ADIS16488A_REG_GX_OUT, &raw) != 0) goto err;
        gyro_x = (float)raw * GYRO_SENSITIVITY;

        if (read_register(ADIS16488A_REG_GY_OUT, &raw) != 0) goto err;
        gyro_y = (float)raw * GYRO_SENSITIVITY;

        if (read_register(ADIS16488A_REG_GZ_OUT, &raw) != 0) goto err;
        gyro_z = (float)raw * GYRO_SENSITIVITY;

        if (read_register(ADIS16488A_REG_AX_OUT, &raw) != 0) goto err;
        accel_x = (float)raw * ACCEL_SENSITIVITY;

        if (read_register(ADIS16488A_REG_AY_OUT, &raw) != 0) goto err;
        accel_y = (float)raw * ACCEL_SENSITIVITY;

        if (read_register(ADIS16488A_REG_AZ_OUT, &raw) != 0) goto err;
        accel_z = (float)raw * ACCEL_SENSITIVITY;

        consecutive_errors = 0;

        /* millisecond timestamp */
        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        snprintf(timestamp + strlen(timestamp),
                 sizeof(timestamp) - strlen(timestamp),
                 ".%03ld", ts.tv_nsec / 1000000);

        fprintf(csv_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp, gyro_x, gyro_y, gyro_z,
                accel_x, accel_y, accel_z);
        fflush(csv_file);

        gpioDelay(SAMPLE_PERIOD_US);
        continue;

    err:
        consecutive_errors++;
        if (consecutive_errors > 10) {
            fprintf(stderr, "Too many consecutive SPI errors; aborting.\n");
            break;
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    return EXIT_SUCCESS;
}

