/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM)
 *   ADIS16448 SCLK-> GPIO11 (BCM)
 *   ADIS16448 DOUT-> GPIO9  (BCM)
 *   ADIS16448 DIN -> GPIO10 (BCM)
 *   ADIS16448 VDD-> 3.3 V
 *   ADIS16448 GND-> GND
 *
 * Build:
 *   gcc -O2 -Wall -o adis16448 adis16448.c -lm
 *
 * Run:
 *   ./adis16448
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADIS16448 register addresses ---- */
#define ADIS16448_REG_XGYRO_OUT  0x04
#define ADIS16448_REG_YGYRO_OUT  0x06
#define ADIS16448_REG_ZGYRO_OUT  0x08
#define ADIS16448_REG_XACCEL_OUT 0x0A
#define ADIS16448_REG_YACCEL_OUT 0x0C
#define ADIS16448_REG_ZACCEL_OUT 0x0E

/* ---- SPI configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_3

/* ---- Scaling factors (from ADIS16448 datasheet) ---- */
#define GYRO_SCALE      0.02f      /* degrees/sec per LSB */
#define ACCEL_SCALE     0.00025f   /* g per LSB */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read a 16-bit register from the ADIS16448.
 *
 * The ADIS16448 single-register read protocol is:
 *   TX: [reg_addr | 0x80], [0x00]
 *   RX: [don't care], [data_hi, data_lo]
 *
 * The 8-bit register address is OR'd with bit 7 (0x80) to request a
 * single-register read.  The second 16-bit transfer returns the
 * register's 16-bit value.
 */
static int adis16448_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* ADIS16448 returns data in the second 16-bit transfer */
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI data-read failed for register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Data is big-endian (MSB first) */
    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI mode ---- */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI bits per word ---- */
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI max speed ---- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU reader started.\n");
    printf("SPI device : %s\n", SPI_DEVICE);
    printf("Mode       : %u\n", mode);
    printf("Bits       : %u\n", bits);
    printf("Speed      : %u Hz\n", speed);
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t gx = 0, gy = 0, gz = 0;
        int16_t ax = 0, ay = 0, az = 0;

        bool ok = true;

        if (adis16448_read_reg16(g_spi_fd, ADIS16448_REG_XGYRO_OUT, &gx) != 0) ok = false;
        if (adis16448_read_reg16(g_spi_fd, ADIS16448_REG_YGYRO_OUT, &gy) != 0) ok = false;
        if (adis16448_read_reg16(g_spi_fd, ADIS16448_REG_ZGYRO_OUT, &gz) != 0) ok = false;
        if (adis16448_read_reg16(g_spi_fd, ADIS16448_REG_XACCEL_OUT, &ax) != 0) ok = false;
        if (adis16448_read_reg16(g_spi_fd, ADIS16448_REG_YACCEL_OUT, &ay) != 0) ok = false;
        if (adis16448_read_reg16(g_spi_fd, ADIS16448_REG_ZACCEL_OUT, &az) != 0) ok = false;

        if (!ok) {
            fprintf(stderr, "Error reading one or more registers; retrying...\n");
            sleep_ms(100);
            continue;
        }

        float gx_dps = (float)gx * GYRO_SCALE;
        float gy_dps = (float)gy * GYRO_SCALE;
        float gz_dps = (float)gz * GYRO_SCALE;
        float ax_g   = (float)ax * ACCEL_SCALE;
        float ay_g   = (float)ay * ACCEL_SCALE;
        float az_g   = (float)az * ACCEL_SCALE;

        printf("Gyro: X=%7.2f dps, Y=%7.2f dps, Z=%7.2f dps | "
               "Accel: X=%7.4f g, Y=%7.4f g, Z=%7.4f g\n",
               gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g);

        sleep_ms(100);
    }

    /* ---- Cleanup ---- */
    printf("\nExiting...\n");
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return EXIT_SUCCESS;
}

