/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM 8, CE0)
 *   ADIS16448 SCLK-> GPIO11 (BCM 11, SCLK)
 *   ADIS16448 DOUT-> GPIO9  (BCM 9, MISO)
 *   ADIS16448 DIN -> GPIO10 (BCM 10, MOSI)
 *   ADIS16448 VDD-> 3.3 V
 *   ADIS16448 GND-> GND
 *
 * SPI: channel 0, CE0, 1 MHz, Mode 0 (CPOL=0, CPHA=0)
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lpigpio -lrt
 * Run:   sudo ./adis16448
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16448 register map (16-bit addresses, 16-bit data) ---- */
#define ADIS16448_REG_GX_OUT  0x04
#define ADIS16448_REG_GY_OUT  0x06
#define ADIS16448_REG_GZ_OUT  0x08
#define ADIS16448_REG_AX_OUT  0x0A
#define ADIS16448_REG_AY_OUT  0x0C
#define ADIS16448_REG_AZ_OUT  0x0E

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */

/* ---- Conversion factors (datasheet) ---- */
#define GYRO_SCALE  0.05f      /* deg/sec per LSB */
#define ACCEL_SCALE 0.00025f   /* g per LSB */

