 * Read a 16-bit register using the ADIS16448 two-cycle protocol.
 *
 *   Phase 1: send 16-bit address (reg << 1 | 0x8000), dummy clocks.
 *   Phase 2: send 0x0000 dummy, clock out 16-bit data.
 *
 * Returns 0 on success and stores the data in *out; returns -1 on error.
 */
static int read_register(int handle, uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  status;

