    tx[0] = (char)((reg << 1) | 0x80);
    tx[1] = 0x00;

    status = spiXfer(handle, tx, rx, 2);
    if (status != 2) {
        fprintf(stderr, "SPI phase 1 transfer failed (status=%d)\n", status);
        return -1;
    }

