    tx[0] = 0x00;
    tx[1] = 0x00;

    status = spiXfer(handle, tx, rx, 2);
    if (status != 2) {
        fprintf(stderr, "SPI phase 2 transfer failed (status=%d)\n", status);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

