    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl-C to stop.\n");
    printf("%-10s %-10s %-10s %-10s %-10s %-10s\n",
           "GyroX", "GyroY", "GyroZ", "AccelX", "AccelY", "AccelZ");
    fflush(stdout);

    while (g_running) {
        rc = read_register(g_spi_handle, ADIS16448_REG_GX_OUT, &gx);
        if (rc != 0) goto error;
        rc = read_register(g_spi_handle, ADIS16448_REG_GY_OUT, &gy);
        if (rc != 0) goto error;
        rc = read_register(g_spi_handle, ADIS16448_REG_GZ_OUT, &gz);
        if (rc != 0) goto error;
        rc = read_register(g_spi_handle, ADIS16448_REG_AX_OUT, &ax);
        if (rc != 0) goto error;
        rc = read_register(g_spi_handle, ADIS16448_REG_AY_OUT, &ay);
        if (rc != 0) goto error;
        rc = read_register(g_spi_handle, ADIS16448_REG_AZ_OUT, &az);
        if (rc != 0) goto error;

        printf("%-10.2f %-10.2f %-10.2f %-10.4f %-10.4f %-10.4f\n",
               (double)gx * GYRO_SCALE,
               (double)gy * GYRO_SCALE,
               (double)gz * GYRO_SCALE,
               (double)ax * ACCEL_SCALE,
