/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), Address: 0x68
 * Reads raw 16-bit accelerometer (X, Y, Z) and gyroscope (X, Y, Z) data
 * every 50 ms and prints it to stdout.
 *
 * Build: gcc -O2 -Wall -o mpu6886_reader mpu6886_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6886_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define ACCEL_XOUT_H        0x3B
#define GYRO_XOUT_H         0x43
#define SAMPLE_PERIOD_MS    50
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6886(int fd)
{
    /* Wake up the MPU-6886: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    /* Allow time for the oscillator to stabilize */
    struct timespec ts = { 0, 100 * 1000 * 1000 }; /* 100 ms */
    nanosleep(&ts, NULL);
    return 0;
}

static int read_sensor_data(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    int rc = 0;

    rc |= i2c_read_reg16(fd, ACCEL_XOUT_H, ax);
    rc |= i2c_read_reg16(fd, ACCEL_XOUT_H + 2, ay);
    rc |= i2c_read_reg16(fd, ACCEL_XOUT_H + 4, az);
    rc |= i2c_read_reg16(fd, GYRO_XOUT_H, gx);
    rc |= i2c_read_reg16(fd, GYRO_XOUT_H + 2, gy);
    rc |= i2c_read_reg16(fd, GYRO_XOUT_H + 4, gz);

    return rc;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6886 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the MPU-6886 */
    if (init_mpu6886(fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    printf("MPU-6886 initialized. Reading every %d ms. Press Ctrl-C to stop.\n",
           SAMPLE_PERIOD_MS);

    while (g_running) {
        int16_t ax = 0, ay = 0, az = 0, gx = 0, gy = 0, gz = 0;
        int read_ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_sensor_data(fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                read_ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                struct timespec ts = { 0, 10 * 1000 * 1000 }; /* 10 ms */
                nanosleep(&ts, NULL);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read sensor data after %d attempts\n",
                    MAX_RETRIES);
            break;
        }

        printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
               ax, ay, az, gx, gy, gz);

        /* Sleep for the sample period (interruptible by signals) */
        struct timespec sleep_ts = { 0, SAMPLE_PERIOD_MS * 1000 * 1000 };
        while (nanosleep(&sleep_ts, &sleep_ts) < 0 && errno == EINTR && g_running)
            ;
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    printf("\nExiting cleanly.\n");
    return rc;
}

