 * ADXL345 Impact Detector for Raspberry Pi Zero W
 *
 * Hardware:
 *   - Adafruit ADXL345 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3), address 0x53
 *   - Red LED on GPIO17 (BCM), with a 330 ohm series resistor
 *
 * Build:
 *   gcc -O2 -Wall -o impact_detector impact_detector.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for GPIO/I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADXL345_ADDRESS      0x53

#define LED_GPIO             17

#define IMPACT_THRESHOLD_G   2.5f
#define SCALE_FACTOR         256.0f   /* ±2 g full-resolution: 256 LSB/g */

#define POLL_DELAY_US        10000    /* 10 ms */
#define LED_ON_DELAY_US      500000   /* 500 ms */

#define LOG_FILE             "impact_log.txt"

/* ADXL345 register addresses */
#define REG_DEVID            0x00
#define REG_BW_RATE          0x2C
#define REG_POWER_CTL        0x2D
#define REG_DATA_FORMAT      0x31
#define REG_DATAX0           0x32

#define EXPECTED_DEVID       0xE5

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  init_adxl345(void);
