     * Verify device identity.  A read of REG_DEVID returns a single byte;
     * pigpio returns it as an int in the range 0–255.
     */
    int devid = i2cReadByteData(g_i2c_handle, REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register (I2C error %d).\n",
                devid);
        return -1;
    }
    if (devid != EXPECTED_DEVID) {
        fprintf(stderr,
                "Error: DEVID mismatch (got 0x%02X, expected 0x%02X).\n",
                (unsigned)devid, EXPECTED_DEVID);
        return -1;
    }

    /*
     * Data format: full resolution, ±2 g, right-justified, no interrupts.
     * Bits [7:6] = 00 (full resolution), [5:4] = 00 (±2 g), [3] = 0 (no
     * interrupts), [2] = 0 (right-justified), [1:0] = 00 (no self-test).
     */
    if (i2cWriteByteData(g_i2c_handle, REG_DATA_FORMAT, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write DATA_FORMAT register.\n");
        return -1;
    }

    /*
     * Power control: standby -> measure.
     * Bits [7:6] = 00 (standby), [5] = 0 (no sleep), [4] = 1 (measure),
     * [3:0] = 0000 (no auto-sleep).
     */
    if (i2cWriteByteData(g_i2c_handle, REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL register.\n");
        return -1;
    }

    return 0;
}

