static int read_acceleration(float *x, float *y, float *z)
{
    char raw[6];

    /*
     * Read 6 bytes starting at REG_DATAX0 (auto-increment).
     * pigpio returns the number of bytes read, or < 0 on error.
     */
    int n = i2cReadI2CBlockData(g_i2c_handle, REG_DATAX0, raw, 6);
    if (n != 6) {
        fprintf(stderr, "Error: I2C block read failed (returned %d).\n", n);
        return -1;
    }

    /* ADXL345 is little-endian: low byte first, then high byte */
    int16_t x_raw = (int16_t)((raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | (uint8_t)raw[4]);

