#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 registers */
#define REG_PWR_MGMT_1   0x6B
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

/* Burst read: 14 bytes starting at ACCEL_XOUT_H (0x3B) */
#define ACCEL_GYRO_LEN 14

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

static int init_imu(void)
{
    /* Wake up the device: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(g_i2c_handle, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    /* Allow time for the oscillator to stabilize */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

static int read_imu_data(int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[ACCEL_GYRO_LEN];

    /* Burst read 14 bytes starting at ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(g_i2c_handle, REG_ACCEL_XOUT_H, buf, ACCEL_GYRO_LEN) != ACCEL_GYRO_LEN) {
        fprintf(stderr, "Error: I2C burst read failed\n");
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature, skipped */
    *gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    *gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    *gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    return 0;
}

static void log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
            (long)ts.tv_sec, ts.tv_nsec,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_imu() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("imu_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error: fopen imu_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(g_log_file);
    }

    int16_t ax, ay, az, gx, gy, gz;

    while (g_running) {
        if (read_imu_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(g_log_file, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: sample skipped due to read error\n");
        }
        gpioDelay(100000); /* 100 ms -> 10 Hz */
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

