                     int16_t gx, int16_t gy, int16_t gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
            (long)ts.tv_sec, ts.tv_nsec,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_imu() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("imu_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error: fopen imu_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(g_log_file);
    }

    int16_t ax, ay, az, gx, gy, gz;

    while (g_running) {
        if (read_imu_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(g_log_file, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: sample skipped due to read error\n");
        }
        gpioDelay(100000); /* 100 ms -> 10 Hz */
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

