/*
 * GY-45 MMA8451Q accelerometer impact detector for Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - MMA8451Q on I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x1D.
 *   - LED on GPIO17 (BCM), with a 330 Ω series resistor to GND.
 *
 * Build:
 *   gcc -O2 -Wall -o impact_detector impact_detector.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for I2C/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- MMA8451Q register definitions (from datasheet) ---- */
#define MMA8451_ADDR            0x1D
#define MMA8451_REG_STATUS      0x00
#define MMA8451_REG_OUT_X_MSB   0x01
#define MMA8451_REG_WHOAMI      0x0D
#define MMA8451_REG_XYZ_DATA_CFG 0x0E
#define MMA8451_REG_CTRL_REG1   0x2A

#define MMA8451_WHOAMI_VAL      0x1A   /* expected device ID */
#define MMA8451_XYZ_2G         0x00   /* ±2 g range */
#define MMA8451_CTRL_ACTIVE    0x01   /* ACTIVE bit in CTRL_REG1 */

/* ---- Application constants ---- */
#define I2C_BUS              1
#define LED_GPIO             17
#define THRESHOLD_G          2.0f
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define LED_ON_TIME_US       500000   /* 500 ms */
#define LOG_FILE             "impact_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register; returns -1 on error.           */
static int mma8451_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register; returns -1 on error.            */
static int mma8451_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 consecutive bytes starting at OUT_X_MSB (auto-increment).   */
static int mma8451_read_xyz(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, MMA8451_REG_OUT_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: expected 6 bytes, got %d\n", rc);
        return -1;
    }
    *x = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)(((uint8_t)buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)(((uint8_t)buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MMA8451Q: verify identity, set ±2 g range, activate. */
static int mma8451_init(int handle)
{
    uint8_t whoami = 0;
    if (mma8451_read_reg(handle, MMA8451_REG_WHOAMI, &whoami) != 0)
        return -1;
    if (whoami != MMA8451_WHOAMI_VAL) {
        fprintf(stderr, "WHOAMI mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, MMA8451_WHOAMI_VAL);
        return -1;
    }

    if (mma8451_write_reg(handle, MMA8451_REG_XYZ_DATA_CFG, MMA8451_XYZ_2G) != 0)
        return -1;
    if (mma8451_write_reg(handle, MMA8451_REG_CTRL_REG1, MMA8451_CTRL_ACTIVE) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw counts to g-force for ±2 g range.                      */
static float raw_to_g(int16_t raw)
{
    return (float)raw / 1024.0f;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped reading to the log file.                          */
static void log_impact(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %d (%.3f g), Y: %d (%.3f g), Z: %d (%.3f g)\n",
            ts, x, raw_to_g(x), y, raw_to_g(y), z, raw_to_g(z));
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MMA8451_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, MMA8451_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- MMA8451Q init ---- */
    if (mma8451_init(g_i2c_handle) != 0) {
        fprintf(stderr, "MMA8451Q initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MMA8451Q impact detector running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t x, y, z;
        if (mma8451_read_xyz(g_i2c_handle, &x, &y, &z) != 0) {
            /* I2C error: back off briefly and retry */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gx = raw_to_g(x);
        float gy = raw_to_g(y);
        float gz = raw_to_g(z);

        if (fabsf(gx) > THRESHOLD_G ||
            fabsf(gy) > THRESHOLD_G ||
            fabsf(gz) > THRESHOLD_G) {

            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);

            log_impact(g_log_file, x, y, z);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

