/*
 * TMAG5273 3D Hall-Effect Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Reads magnetic field data from a TI TMAG5273 over I2C and logs it to
 * magnetic_field_log.csv once per second.  The CSV file is created with a
 * header row if it does not already exist.
 *
 * Wiring:
 *   TMAG5273 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   TMAG5273 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   TMAG5273 VDD  -> 3.3 V
 *   TMAG5273 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_logger mag_logger.c
 * Run:    ./mag_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- TMAG5273 register map (from TI datasheet) ---- */
#define TMAG5273_ADDR          0x37          /* default 7-bit I2C address */
#define TMAG5273_REG_DEVICE_ID 0x00          /* device ID register        */
#define TMAG5273_REG_X_MSB     0x01          /* X-axis MSB (signed)       */
#define TMAG5273_REG_X_LSB     0x02          /* X-axis LSB               */
#define TMAG5273_REG_Y_MSB     0x03          /* Y-axis MSB (signed)       */
#define TMAG5273_REG_Y_LSB     0x04          /* Y-axis LSB               */
#define TMAG5273_REG_Z_MSB     0x05          /* Z-axis MSB (signed)       */
#define TMAG5273_REG_Z_LSB     0x06          /* Z-axis LSB               */
#define TMAG5273_REG_TEMP_MSB  0x07          /* temperature MSB          */
#define TMAG5273_REG_TEMP_LSB  0x08          /* temperature LSB          */
#define TMAG5273_REG_CTRL      0x09          /* control register         */
#define TMAG5273_REG_CONFIG    0x0A          /* configuration register    */

#define I2C_BUS                "/dev/i2c-1"
#define LOG_FILE               "magnetic_field_log.csv"
#define SAMPLE_INTERVAL_SEC    1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;          /* let main loop exit cleanly              */
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg ptr 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16_signed(int fd, uint8_t msb_reg, int16_t *out)
{
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, msb_reg, &msb) == -1)
        return -1;
    if (i2c_read_reg8(fd, msb_reg + 1, &lsb) == -1)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMAG5273 driver                                                     */
/* ------------------------------------------------------------------ */
static int tmag5273_init(int fd)
{
    /*
     * Verify device identity.  The device ID register (0x00) should
     * read 0x52 for the TMAG5273.
     */
    uint8_t dev_id;
    if (i2c_read_reg8(fd, TMAG5273_REG_DEVICE_ID, &dev_id) == -1)
        return -1;
    if (dev_id != 0x52) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x52). "
                        "Sensor not present or wrong address.\n", dev_id);
        return -1;
    }

    /*
     * Configure:
     *   CONFIG = 0x00  -> 100 Hz sample rate, 12-bit resolution
     *   CTRL   = 0x01  -> continuous measurement mode
     */
    if (i2c_write_reg8(fd, TMAG5273_REG_CONFIG, 0x00) == -1)
        return -1;
    if (i2c_write_reg8(fd, TMAG5273_REG_CTRL, 0x01) == -1)
        return -1;

    return 0;
}

static int tmag5273_read(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16_signed(fd, TMAG5273_REG_X_MSB, x) == -1)
        return -1;
    if (i2c_read_reg16_signed(fd, TMAG5273_REG_Y_MSB, y) == -1)
        return -1;
    if (i2c_read_reg16_signed(fd, TMAG5273_REG_Z_MSB, z) == -1)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    /* Check whether the file already exists so we can write a header */
    int need_header = (access(LOG_FILE, F_OK) != 0);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (need_header) {
        if (fprintf(g_log_fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Error writing header: %s\n", strerror(errno));
            fclose(g_log_fp);
            g_log_fp = NULL;
            return -1;
        }
        if (fflush(g_log_fp) == EOF) {
            fprintf(stderr, "Error flushing header: %s\n", strerror(errno));
            fclose(g_log_fp);
            g_log_fp = NULL;
            return -1;
        }
    }
    return 0;
}

static int log_data(int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "Error writing data row: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) == EOF) {
        fprintf(stderr, "Error flushing log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the TMAG5273 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                TMAG5273_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tmag5273_init(g_i2c_fd) == -1) {
        fprintf(stderr, "TMAG5273 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file */
    if (log_open() == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (tmag5273_read(g_i2c_fd, &x, &y, &z) == -1) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            if (log_data(x, y, z) == -1)
                fprintf(stderr, "Logging error; continuing.\n");
        }

        /* Sleep for the sample interval, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * freefall_detect.c — Raspberry Pi 4 Model B
 *
 * Reads the SparkFun ADXL345 I2C accelerometer on /dev/i2c-1
 * (ADDR 0x53), configures interrupt1 on GPIO17 (BCM 17),
 * captures free-fall acceleration samples, and logs them
 * to freefall_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o freefall_detect freefall_detect.c \
 *               -lgpiod -lm
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   ADXL345 INT1 -> GPIO17 (pin 11, BCM 17)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 constants (from datasheet) ---- */
#define ADXL345_ADDR        0x53
#define ADXL345_DEVID       0x00
#define ADXL345_DEVID_VAL   0xE5
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_INT_ENABLE  0x2E
#define ADXL345_INT_MAP    0x2F
#define ADXL345_INT_SOURCE  0x30
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0     0x32
#define ADXL345_BW_RATE    0x2C
#define ADXL345_POWER_CTL_NORMAL 0x08
#define ADXL345_INT_FREEFALL 0x01

/* ---- GPIO / I2C constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO on Pi 4 */
#define GPIO_LINE      17            /* BCM 17, physical pin 11 */
#define LOG_FILE       "freefall_log.csv"
#define SAMPLE_PERIOD_MS 10

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst read(0x%02X, %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345                                                             */
/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby so we can configure registers */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* 100 Hz output data rate */
    if (i2c_write_reg8(fd, ADXL345_BW_RATE, 0x0A) < 0)
        return -1;

    /* +/- 2g range, full-resolution, right-justified */
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x00) < 0)
        return -1;

    /* Free-fall interrupt on INT1 (bit 0) */
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, ADXL345_INT_FREEFALL) < 0)
        return -1;

    /* Map free-fall to INT1 (bit 0) */
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) < 0)
        return -1;

    /* Clear any pending interrupts */
    uint8_t src = 0;
    if (i2c_read_reg8(fd, ADXL345_INT_SOURCE, &src) < 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, ADXL345_POWER_CTL_NORMAL) < 0)
        return -1;

    return 0;
}

static int adxl345_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_DATAX0, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *y = (int16_t)((uint16_t)buf[2] | ((uint16_t)buf[3] << 8));
    *z = (int16_t)((uint16_t)buf[4] | ((uint16_t)buf[5] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_buf[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", ts_buf, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable interrupts before closing */
        if (g_i2c_fd >= 0)
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_INT_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADXL345_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize ADXL345 ---- */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_falling_edge_events(g_line, "freefall_detect") < 0) {
        fprintf(stderr, "gpiod_line_request_falling_edge_events failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_fp, "timestamp,x,y,z\n");
    fflush(g_log_fp);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* ---- Event loop ---- */
    while (g_running) {
        /* Poll for falling-edge event with a 100 ms timeout */
        int ret = gpiod_line_event_wait(g_line, &(struct timespec){ 0, 100 * 1000000L });
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0)
            continue; /* timeout, no event */

        /* Drain the event queue */
        struct gpiod_line_event ev;
        while (gpiod_line_event_read(g_line, &ev) == 0) {
            if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                int16_t x, y, z;
                if (adxl345_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
                    log_sample(g_log_fp, x, y, z);
                } else {
                    fprintf(stderr, "Failed to read acceleration data during free-fall\n");
                }
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

