/*
 * LSM6DSR IMU fall-detection logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LSM6DSR SDA  -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   LSM6DSR SCL  -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   LSM6DSR VDD  -> 3.3 V
 *   LSM6DSR GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o imu_logger imu_logger.c -lm
 *
 * Run:
 *   ./imu_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM6DSR constants (verified against datasheet) ---- */
#define LSM6DSR_ADDR        0x6A   /* SA0 tied to GND */
#define LSM6DSR_WHO_AM_I    0x0F
#define LSM6DSR_WHO_AM_I_VAL 0x6A

#define LSM6DSR_CTRL1_XL   0x10   /* accelerometer ODR / FS */
#define LSM6DSR_CTRL2_G    0x11   /* gyroscope ODR / FS */
#define LSM6DSR_CTRL3_C    0x12   /* accelerometer anti-alias */
#define LSM6DSR_CTRL4_C    0x13   /* gyroscope anti-alias */

#define LSM6DSR_OUTX_L_G   0x22   /* gyro X low  */
#define LSM6DSR_OUTX_H_G   0x23   /* gyro X high */
#define LSM6DSR_OUTY_L_G   0x24   /* gyro Y low  */
#define LSM6DSR_OUTY_H_G   0x25   /* gyro Y high */
#define LSM6DSR_OUTZ_L_G   0x26   /* gyro Z low  */
#define LSM6DSR_OUTZ_H_G   0x27   /* gyro Z high */

#define LSM6DSR_OUTX_L_XL  0x28   /* accel X low  */
#define LSM6DSR_OUTX_H_XL  0x29   /* accel X high */
#define LSM6DSR_OUTY_L_XL  0x2A   /* accel Y low  */
#define LSM6DSR_OUTY_H_XL  0x2B   /* accel Y high */
#define LSM6DSR_OUTZ_L_XL  0x2C   /* accel Z low  */
#define LSM6DSR_OUTZ_H_XL  0x2D   /* accel Z high */

/*
 * CTRL1_XL = 0x80 -> ODR_XL = 104 Hz, FS_XL = +/-2g
 * CTRL2_G  = 0x80 -> ODR_G  = 104 Hz, FS_G  = +/-250 dps
 * CTRL3_C  = 0x00 -> accelerometer BW = 104 Hz, anti-alias enabled
 * CTRL4_C  = 0x00 -> gyro BW = 104 Hz, anti-alias enabled
 */
#define LSM6DSR_CTRL1_XL_VAL 0x80
#define LSM6DSR_CTRL2_G_VAL  0x80

/* Sensitivity: ±2 g  -> 16384 LSB/g, ±250 dps -> 131.072 LSB/dps */
#define ACCEL_LSB_PER_G  16384.0f
#define GYRO_LSB_PER_DPS 131.072f

#define LOG_FILE_NAME    "motion_log.txt"
#define SAMPLE_PERIOD_US 9500   /* 104 Hz */
#define FALL_WINDOW_S    1.0
#define FALL_THRESHOLD_G 0.2f
#define IMPACT_THRESHOLD_G 2.5f

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Sensor data ---- */
typedef struct {
    float accel_x, accel_y, accel_z;   /* g */
    float gyro_x,  gyro_y,  gyro_z;    /* dps */
} sensor_data_t;

/* ---- Fall detection state machine ---- */
typedef enum { IDLE, FREEFALL, IMPACT } fall_state_t;

static fall_state_t g_fall_state = IDLE;
static time_t       g_freefall_start = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_checked(int handle, uint8_t reg, uint8_t val, const char *label)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] I2C write to 0x%02X (%s) failed: %s\n",
                reg, label, pigpio_error(i2cWriteByteData(handle, reg, val)));
        return -1;
    }
    return 0;
}

static int i2c_read_block_checked(int handle, uint8_t reg, uint8_t *buf, uint32_t len, const char *label)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "[ERROR] I2C read from 0x%02X (%s) failed: got %d, expected %u: %s\n",
                reg, label, n, len, pigpio_error(n));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(int handle)
{
    int who = i2cReadByteData(handle, LSM6DSR_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I: %s\n", pigpio_error(who));
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_checked(handle, LSM6DSR_CTRL1_XL, LSM6DSR_CTRL1_XL_VAL, "CTRL1_XL") < 0)
        return -1;
    if (i2c_write_checked(handle, LSM6DSR_CTRL2_G,  LSM6DSR_CTRL2_G_VAL,  "CTRL2_G")  < 0)
        return -1;

    /* Allow sensors to settle after configuration */
    gpioDelay(20000); /* 20 ms */
    return 0;
}

/* ---- Read one sample ---- */
static int read_sensor_data(int handle, sensor_data_t *data)
{
    uint8_t buf[12];

    if (i2c_read_block_checked(handle, LSM6DSR_OUTX_L_G, buf, 6, "gyro") < 0)
        return -1;
    if (i2c_read_block_checked(handle, LSM6DSR_OUTX_L_XL, buf + 6, 6, "accel") < 0)
        return -1;

    int16_t gx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | buf[4]);

    int16_t ax = (int16_t)((buf[7]  << 8) | buf[6]);
    int16_t ay = (int16_t)((buf[9]  << 8) | buf[8]);
    int16_t az = (int16_t)((buf[11] << 8) | buf[10]);

    data->gyro_x  = (float)gx / GYRO_LSB_PER_DPS;
    data->gyro_y  = (float)gy / GYRO_LSB_PER_DPS;
    data->gyro_z  = (float)gz / GYRO_LSB_PER_DPS;

    data->accel_x = (float)ax / ACCEL_LSB_PER_G;
    data->accel_y = (float)ay / ACCEL_LSB_PER_G;
    data->accel_z = (float)az / ACCEL_LSB_PER_G;

    return 0;
}

/* ---- Log one reading ---- */
static void log_data(FILE *fp, const sensor_data_t *data)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double t = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

    fprintf(fp, "%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            t, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z,
            sqrtf(data->accel_x * data->accel_x +
                  data->accel_y * data->accel_y +
                  data->accel_z * data->accel_z),
            (g_fall_state == IMPACT) ? 1.0 : 0.0);
    fflush(fp);
}

/* ---- Fall detection ---- */
static void detect_fall(const sensor_data_t *data)
{
    float mag = sqrtf(data->accel_x * data->accel_x +
                      data->accel_y * data->accel_y +
                      data->accel_z * data->accel_z);

    switch (g_fall_state) {
    case IDLE:
        if (mag < FALL_THRESHOLD_G) {
            g_fall_state = FREEFALL;
            g_freefall_start = time(NULL);
        }
        break;

    case FREEFALL:
        if (difftime(time(NULL), g_freefall_start) >= FALL_WINDOW_S) {
            if (mag > IMPACT_THRESHOLD_G) {
                g_fall_state = IMPACT;
                printf("[ALERT] Fall detected! Magnitude: %.2f g\n", mag);
            } else {
                g_fall_state = IDLE;
            }
        } else if (mag > IMPACT_THRESHOLD_G) {
            g_fall_state = IDLE;
        }
        break;

    case IMPACT:
        if (mag > FALL_THRESHOLD_G) {
            g_fall_state = IDLE;
        }
        break;
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] LSM6DSR initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,accel_x_g,accel_y_g,accel_z_g,gyro_x_dps,gyro_y_dps,gyro_z_dps,accel_mag_g,impact\n");
    fflush(g_log_file);

    sensor_data_t data;
    int consecutive_errors = 0;

    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &data) == 0) {
            consecutive_errors = 0;
            log_data(g_log_file, &data);
            detect_fall(&data);
        } else {
            if (++consecutive_errors > 10) {
                fprintf(stderr, "[FATAL] Too many consecutive I2C errors, aborting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

