/*
 * ADIS16266 gyroscope reader for Raspberry Pi 3 Model B+
 * SPI channel 0, CE0 (GPIO8), mode 3 (CPOL=1, CPHA=1), 1 MHz
 * Reads angular rate (X/Y/Z) at 10 ms intervals, logs to gyro_log.csv
 * Build: gcc -O2 -Wall -o gyro_reader gyro_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0x0003     /* mode 3: CPOL=1, CPHA=1 */

#define WHO_AM_I_REG   0x02
#define WHO_AM_I_VAL   0x01    /* expected response for ADIS16266 */
#define GLOB_CMD_REG   0x06
#define SMPL_PRD_REG   0x36
#define SMPL_PRD_VAL   0x000A  /* 10 ms period */
#define ANG_OUT_X_REG  0x04
#define ANG_OUT_Y_REG  0x08
#define ANG_OUT_Z_REG  0x0C

#define SCALE_FACTOR   0.0305f   /* deg/sec per LSB (ADIS16266) */
#define SAMPLE_US      10000     /* 10 ms */
#define LOG_FILE       "gyro_log.csv"

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- SPI helpers ---- */

/*
 * Perform a 16-bit register read.
 * SPI transfer: TX[0]=reg | 0x80, TX[1]=0x00,
 *               RX[0]=don't care, RX[1]=data MSB.
 * Returns 0 on success, -1 on error.
 */
static int read_register(uint8_t reg, uint16_t *value)
{
    char tx[2], rx[2];
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0];
    return 0;
}

/*
 * Perform a 16-bit register write.
 * SPI transfer: TX[0]=reg & 0x7F, TX[1]=data MSB.
 * Returns 0 on success, -1 on error.
 */
static int write_register(uint8_t reg, uint16_t value)
{
    char tx[2];
    tx[0] = (char)(reg & 0x7F);
    tx[1] = (char)(value >> 8);

    if (spiWrite(spi_handle, tx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ---- Initialization ---- */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        gpioTerminate();
        return -1;
    }

    /* Verify device identity */
    uint16_t who_am_i = 0;
    if (read_register(WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        goto fail;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, WHO_AM_I_VAL);
        goto fail;
    }

    /* Configure sample period (10 ms) */
    if (write_register(SMPL_PRD_REG, SMPL_PRD_VAL) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        goto fail;
    }

    /* Clear any pending reset command */
    if (write_register(GLOB_CMD_REG, 0x0000) != 0) {
        fprintf(stderr, "Failed to clear GLOB_CMD\n");
        goto fail;
    }

    return 0;

fail:
    spiClose(spi_handle);
    spi_handle = -1;
    gpioTerminate();
    return -1;
}

/* ---- Logging ---- */
static int log_open(void)
{
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    fprintf(log_file, "timestamp_us,x_rate_deg_sec,y_rate_deg_sec,z_rate_deg_sec\n");
    fflush(log_file);
    return 0;
}

static void log_data(uint64_t ts_us, float x, float y, float z)
{
    if (!log_file) return;
    fprintf(log_file, "%llu,%.3f,%.3f,%.3f\n",
            (unsigned long long)ts_us, x, y, z);
    fflush(log_file);
}

/* ---- Read one sample ---- */
static int read_gyro_data(float *x, float *y, float *z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (read_register(ANG_OUT_X_REG, &raw_x) != 0) return -1;
    if (read_register(ANG_OUT_Y_REG, &raw_y) != 0) return -1;
    if (read_register(ANG_OUT_Z_REG, &raw_z) != 0) return -1;

    *x = (float)((int16_t)raw_x) * SCALE_FACTOR;
    *y = (float)((int16_t)raw_y) * SCALE_FACTOR;
    *z = (float)((int16_t)raw_z) * SCALE_FACTOR;
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
    }

    if (log_open() != 0) {
        fprintf(stderr, "Log file open failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16266 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float x, y, z;
        if (read_gyro_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            perror("clock_gettime");
            gpioDelay(SAMPLE_US);
            continue;
        }
        uint64_t ts_us = (uint64_t)ts.tv_sec * 1000000ULL +
                         (uint64_t)ts.tv_nsec / 1000ULL;

        log_data(ts_us, x, y, z);
        printf("%llu us  X: %.3f deg/s  Y: %.3f deg/s  Z: %.3f deg/s\n",
               (unsigned long long)ts_us, x, y, z);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

