/*
 * GY-50 L3G4200D gyroscope logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   L3G4200D VCC  -> Pi 3.3 V (Pin 1)
 *   L3G4200D GND  -> Pi GND  (Pin 9)
 *   L3G4200D SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *   L3G4200D SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *
 * I2C address: 0x68 (SA0 tied to GND)
 *
 * Build:  gcc -O2 -Wall -o gyro_log gyro_log.c -lm -lpigpio -lrt
 * Run:    sudo ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- L3G4200D constants ------------------------------------------------ */
#define L3G4200D_ADDR        0x68
#define WHO_AM_I_REG         0x0F
#define WHO_AM_I_VAL         0xD3
#define CTRL_REG1            0x20
#define CTRL_REG4            0x23
#define OUT_X_L              0x28
#define OUT_X_H              0x29
#define OUT_Y_L              0x2A
#define OUT_Y_H              0x2B
#define OUT_Z_L              0x2C
#define OUT_Z_H              0x2D

#define CTRL_REG1_VAL        0x0F   /* ODR=100 Hz, all axes enabled */
#define CTRL_REG4_VAL        0x00   /* Continuous update, 8.75 mdps/LSB */

#define SAMPLE_PERIOD_US     10000  /* 10 ms */
#define I2C_BUS              1
#define I2C_RETRIES          3
#define I2C_RETRY_DELAY_US   10000  /* 10 ms */

/* ---- Globals for signal-safe cleanup ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Signal handler ---------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers with retry -------------------------------------------- */
static int i2c_write_reg_retry(int handle, uint8_t reg, uint8_t val)
{
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        if (i2cWriteByteData(handle, reg, val) == 0)
            return 0;
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg_retry(int handle, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        int r = i2cReadByteData(handle, reg);
        if (r >= 0) {
            *val = (uint8_t)r;
            return 0;
        }
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ---- Sensor initialization ---------------------------------------------- */
static int init_gyro(int handle)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg_retry(handle, WHO_AM_I_REG, &who_am_i) != 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr,
                "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg_retry(handle, CTRL_REG1, CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1.\n");
        return -1;
    }
    if (i2c_write_reg_retry(handle, CTRL_REG4, CTRL_REG4_VAL) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ---- Read one gyro sample ----------------------------------------------- */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg_retry(handle, OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg_retry(handle, OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg_retry(handle, OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg_retry(handle, OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg_retry(handle, OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg_retry(handle, OUT_Z_H, &zh) != 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    /* 8.75 mdps/LSB -> degrees/s */
    *x = (float)raw_x / 114.285f;
    *y = (float)raw_y / 114.285f;
    *z = (float)raw_z / 114.285f;

    return 0;
}

/* ---- Log one record ----------------------------------------------------- */
static int log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    if (fprintf(fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
                (long)ts.tv_sec, ts.tv_nsec, x, y, z) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ---- Cleanup ------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- init sensor --- */
    if (init_gyro(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: gyroscope initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen("gyro_log.csv", "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    /* write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X,Y,Z\n");
        fflush(g_log_file);
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyro data to gyro_log.csv (Ctrl+C to stop)...\n");

    /* --- main loop --- */
    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (log_data(g_log_file, x, y, z) != 0) {
            fprintf(stderr, "Warning: log write failed, continuing...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

