#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME     "flame_events.log"
#define POLL_INTERVAL_US  500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fflush(log_file);
    }
}

int main(void)
{
    FILE *log_file = NULL;
    int rc;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as input with internal pull-up */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                FLAME_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n",
                FLAME_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* Main polling loop */
    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n",
                    FLAME_SENSOR_GPIO);
            log_event(log_file, "ERROR: sensor read failed");
        } else if (sensor_value == 0) {
            /* LOW (0) indicates flame detected */
            printf("FLAME DETECTED!\n");
            log_event(log_file, "Flame detected: YES");
        } else {
            /* HIGH (1) indicates no flame */
            log_event(log_file, "Flame detected: NO");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

