/*
 * Raspberry Pi 5 — Omron D7S-0001 vibration sensor reader
 *
 * Reads acceleration data over I2C (/dev/i2c-1) and logs it to
 * vibration_log.csv with an ISO-8601 UTC timestamp.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vibration_log vibration_log.c
 *
 * Hardware notes:
 *   - The D7S-0001 is typically addressed at 0x2A on /dev/i2c-1.
 *   - The X/Y/Z acceleration registers are 0x01, 0x03, 0x05.
 *   - Each axis is a signed 16-bit little-endian value.
 *   - A read failure (e.g. sensor absent or bus error) is detected
 *     and reported to stderr without crashing the program.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x2A
#define REG_X_LSB      0x01
#define REG_Y_LSB      0x03
#define REG_Z_LSB      0x05
#define SAMPLE_MS      100
#define LOG_FILE       "vibration_log.csv"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a signed 16-bit little-endian register pair from the D7S.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_axis(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                D7S_ADDR, strerror(errno));
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1)
        return -1;

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0)
        return -1;

    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    /* --- Open CSV file --- */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header only if the file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "fprintf header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Logging D7S-0001 vibration data to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        if (read_axis(fd, REG_X_LSB, &x) < 0 ||
            read_axis(fd, REG_Y_LSB, &y) < 0 ||
            read_axis(fd, REG_Z_LSB, &z) < 0) {
            /*
             * Sensor-absent or bus error: skip this sample,
             * report the error, and continue.
             */
            fprintf(stderr, "Sensor read error — skipping sample\n");
        } else {
            if (get_timestamp(ts, sizeof(ts)) < 0) {
                fprintf(stderr, "get_timestamp: %s\n", strerror(errno));
            } else {
                if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
                    fprintf(stderr, "fprintf data: %s\n", strerror(errno));
                } else if (fflush(fp) != 0) {
                    fprintf(stderr, "fflush data: %s\n", strerror(errno));
                }
            }
        }

        /* Sleep 100 ms; interruptible by signals */
        struct timespec rem;
        struct timespec req = { .tv_sec = 0, .tv_nsec = SAMPLE_MS * 1000000L };
        while (nanosleep(&req, &rem) < 0 && errno == EINTR && g_running) {
            req = rem;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose: %s\n", strerror(errno));
    }
    if (fd >= 0) {
        if (close(fd) < 0)
            fprintf(stderr, "close(fd): %s\n", strerror(errno));
    }
    return rc;
}

