/*
 * Conveyor monitor using two TI DRV5032 Hall-effect sensors on a Raspberry Pi 4.
 *
 * Wiring:
 *   Hall sensor 1 signal -> GPIO17 (BCM)
 *   Hall sensor 2 signal -> GPIO27 (BCM)
 *   VCC -> 3.3 V, GND -> GND
 *
 * The DRV5032 has an internal pull-up; the bias flag is set so the
 * Pi driver drives the line high when the sensor is closed (active
 * high).  A logic-1 reading from both sensors triggers a simulated
 * conveyor halt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o conveyor_monitor conveyor_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR1_PIN      17
#define SENSOR2_PIN      27
#define LOG_FILE         "conveyor_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a heap-allocated timestamp string; caller must free().       */
static char *get_timestamp(void)
{
    struct timespec ts;
    struct tm tm_info;
    char *buf = malloc(32);
    if (!buf) {
        perror("malloc");
        return NULL;
    }

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        free(buf);
        return NULL;
    }

    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        free(buf);
        return NULL;
    }

    if (strftime(buf, 32, "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        free(buf);
        return NULL;
    }

    size_t len = strlen(buf);
    snprintf(buf + len, 32 - len, ".%03ld", ts.tv_nsec / 1000000L);
    return buf;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int s1, int s2)
{
    char *ts = get_timestamp();
    if (!ts)
        return -1;

    if (fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", ts, s1, s2) < 0) {
        perror("fprintf");
        free(ts);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        free(ts);
        return -1;
    }

    free(ts);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* ---- Open the default gpiochip --------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(SENSOR1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(SENSOR2_PIN)");
        goto cleanup;
    }

    /* Request both lines as inputs with internal pull-ups. */
    if (gpiod_line_request_input_flags(line1, "conveyor-monitor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line2, "conveyor-monitor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags(line2)");
        goto cleanup;
    }

    /* ---- Open log file --------------------------------------------- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(\"" LOG_FILE "\")");
        goto cleanup;
    }

    printf("Conveyor monitor started.  Logging to %s every %d ms.\n",
           LOG_FILE, POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ----------------------------------------- */
    while (g_running) {
        int s1 = gpiod_line_get_value(line1);
        int s2 = gpiod_line_get_value(line2);

        if (s1 < 0) {
            perror("gpiod_line_get_value(line1)");
            break;
        }
        if (s2 < 0) {
            perror("gpiod_line_get_value(line2)");
            break;
        }

        if (log_data(log_fp, s1, s2) != 0) {
            fprintf(stderr, "Logging failed; aborting.\n");
            break;
        }

        if (s1 == 1 && s2 == 1) {
            printf("[HALT] Both sensors closed: conveyor halted.\n");
        }

        struct timespec sleep_ts = { 0, POLL_INTERVAL_MS * 1000000L };
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    printf("\nConveyor monitor stopped.\n");
    return ret;
}

