    if (gpiod_line_request_input_flags(line2, "conveyor-monitor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        perror("gpiod_line_request_input_flags(line2)");
        goto cleanup;
    }

    /* ---- Open log file --------------------------------------------- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(\"" LOG_FILE "\")");
        goto cleanup;
    }

    printf("Conveyor monitor started.  Logging to %s every %d ms.\n",
           LOG_FILE, POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ----------------------------------------- */
    while (g_running) {
        int s1 = gpiod_line_get_value(line1);
        int s2 = gpiod_line_get_value(line2);

        if (s1 < 0) {
            perror("gpiod_line_get_value(line1)");
            break;
        }
        if (s2 < 0) {
            perror("gpiod_line_get_value(line2)");
            break;
        }

        if (log_data(log_fp, s1, s2) != 0) {
            fprintf(stderr, "Logging failed; aborting.\n");
            break;
        }

        if (s1 == 1 && s2 == 1) {
            printf("[HALT] Both sensors closed: conveyor halted.\n");
        }

        struct timespec sleep_ts = { 0, POLL_INTERVAL_MS * 1000000L };
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    printf("\nConveyor monitor stopped.\n");
    return ret;
}

