/*
 * GY-45 MMA8452Q 3-axis accelerometer fall detector for Raspberry Pi 4.
 *
 * Wiring:
 *   MMA8452Q SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MMA8452Q SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MMA8452Q VCC  -> 3.3 V
 *   MMA8452Q GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o fall_detect fall_detect.c
 * Run:    ./fall_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MMA8452Q constants ------------------------------------------------ */
#define MMA8452Q_I2C_ADDR        0x1D          /* SA0 tied to GND */
#define MMA8452Q_REG_STATUS      0x00
#define MMA8452Q_REG_OUT_X_MSB   0x01          /* X-axis MSB */
#define MMA8452Q_REG_WHO_AM_I    0x0D
#define MMA8452Q_REG_CTRL_REG1   0x2A
#define MMA8452Q_REG_XYZ_DATA_CFG 0x0E
#define MMA8452Q_REG_CTRL_REG2   0x2B

#define MMA8452Q_WHO_AM_I_VAL    0x2A          /* expected device ID */
#define MMA8452Q_CTRL_ACTIVE     0x01          /* bit 0 = ACTIVE */
#define MMA8452Q_CTRL_DR_100HZ   0x08          /* bits 3-4 = 100 Hz */
#define MMA8452Q_CTRL_DR_50HZ    0x00          /* bits 3-4 = 50 Hz  */
#define MMA8452Q_CTRL_DR_200HZ   0x04          /* bits 3-4 = 200 Hz */
#define MMA8452Q_CTRL_DR_400HZ   0x0C          /* bits 3-4 = 400 Hz */
#define MMA8452Q_CTRL_DR_800HZ   0x10          /* bits 3-4 = 800 Hz */
#define MMA8452Q_CTRL_DR_1600HZ  0x14          /* bits 3-4 = 1600 Hz */
#define MMA8452Q_CTRL_DR_1000HZ  0x02          /* bits 3-4 = 1000 Hz */

#define I2C_BUS                 "/dev/i2c-1"
#define LOG_FILE                "fall_log.txt"
#define TILT_THRESHOLD_DEG      45.0f
#define POLL_DELAY_MS           10
#define MAX_RETRIES             3

/* ---- Globals for cleanup ---------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler --------------------------------------------------- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers --------------------------------------------- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization --------------------------------------------- */
static int mma8452q_init(int fd)
{
    uint8_t whoami = 0;
    if (i2c_read_reg(fd, MMA8452Q_REG_WHO_AM_I, &whoami) != 0)
        return -1;
    if (whoami != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg(fd, MMA8452Q_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Set data rate to 100 Hz (bits 3-4 = 0100) */
    if (i2c_write_reg(fd, MMA8452Q_REG_CTRL_REG1,
                      MMA8452Q_CTRL_DR_100HZ) != 0)
        return -1;

    /* Set full-scale range to +/-2g (bits 2-3 = 00) */
    if (i2c_write_reg(fd, MMA8452Q_REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Enable active mode (bit 0 = ACTIVE) */
    if (i2c_write_reg(fd, MMA8452Q_REG_CTRL_REG1,
                      MMA8452Q_CTRL_DR_100HZ | MMA8452Q_CTRL_ACTIVE) != 0)
        return -1;

    return 0;
}

/* ---- Read 6-byte block of XYZ data ------------------------------------ */
static int mma8452q_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_REG_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /* 12-bit left-justified: shift right by 4 to get signed 12-bit value */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

/* ---- Tilt angle from X and Y ------------------------------------------ */
static float calculate_tilt_angle(int16_t x, int16_t y)
{
    float ax = (float)x;
    float ay = (float)y;
    return atan2f(ay, ax) * 180.0f / (float)M_PI;
}

/* ---- Log a fall event ------------------------------------------------- */
static void log_fall_event(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, X=%d, Y=%d, Z=%d\n", ts, x, y, z);
    fflush(fp);
}

/* ---- Cleanup ---------------------------------------------------------- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor back in standby before closing */
        (void)i2c_write_reg(g_i2c_fd, MMA8452Q_REG_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ------------------------------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                MMA8452Q_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mma8452q_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MMA8452Q fall detector running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (mma8452q_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            usleep(1000);
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts; continuing\n",
                    MAX_RETRIES);
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        float angle = calculate_tilt_angle(x, y);
        if (fabsf(angle) > TILT_THRESHOLD_DEG) {
            printf("Tilt angle %.1f deg exceeds threshold (%.1f deg) -> FALL\n",
                   angle, TILT_THRESHOLD_DEG);
            log_fall_event(g_log_fp, x, y, z);
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

