/*
 * LIS3MDL Magnetic Field Logger with Metal Detector Alert
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x1C
 * Output: magnetic_log.txt (CSV: X,Y,Z per line, flushed after every write)
 *
 * Build:  gcc -O2 -Wall -o mag_logger mag_logger.c -lm
 * Run:    ./mag_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL constants (verified against datasheet) ---- */
#define LIS3MDL_ADDR        0x1C
#define LIS3MDL_CTRL_REG1   0x20
#define LIS3MDL_CTRL_REG2   0x21
#define LIS3MDL_CTRL_REG3   0x22
#define LIS3MDL_CTRL_REG4   0x23
#define LIS3MDL_CTRL_REG5   0x24
#define LIS3MDL_OUT_X_L     0x28
#define LIS3MDL_OUT_X_H     0x29
#define LIS3MDL_OUT_Y_L     0x2A
#define LIS3MDL_OUT_Y_H     0x2B
#define LIS3MDL_OUT_Z_L     0x2C
#define LIS3MDL_OUT_Z_H     0x2D

/* ±4 gauss full-scale: sensitivity 0.146 mG/LSB */
#define SENSITIVITY_MG_LSB  0.146f

/* Calibration constants (replace with your own values) */
#define X_OFFSET 0.0f
#define Y_OFFSET 0.0f
#define Z_OFFSET 0.0f
#define X_SCALE  1.0f
#define Y_SCALE  1.0f
#define Z_SCALE  1.0f

/* Metal detector threshold (mGauss) */
#define METAL_THRESHOLD 800.0f

/* Sampling */
#define SAMPLE_PERIOD_NS 100000000L  /* 100 ms -> 10 Hz */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.    */
static int reg_write(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("reg_write: write failed");
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on error.   */
static int reg_read(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("reg_read: write (reg select) failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("reg_read: read failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the LIS3MDL: power on, set ODR 80 Hz, continuous mode.   */
static int init_lis3mdl(int fd)
{
    /* CTRL_REG1: temp en | ODR 80 Hz | Z-axis enable */
    if (reg_write(fd, LIS3MDL_CTRL_REG1, 0x10) < 0) return -1;
    /* CTRL_REG2: full-scale ±4 gauss (bits[3:2]=00) */
    if (reg_write(fd, LIS3MDL_CTRL_REG2, 0x00) < 0) return -1;
    /* CTRL_REG3: continuous-conversion mode (bits[1:0]=00) */
    if (reg_write(fd, LIS3MDL_CTRL_REG3, 0x00) < 0) return -1;
    /* CTRL_REG4: Z-axis high performance (bits[1:0]=01) */
    if (reg_write(fd, LIS3MDL_CTRL_REG4, 0x01) < 0) return -1;
    /* CTRL_REG5: reset (bit[7]=1) then normal operation */
    if (reg_write(fd, LIS3MDL_CTRL_REG5, 0x80) < 0) return -1;
    if (reg_write(fd, LIS3MDL_CTRL_REG5, 0x00) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw X/Y/Z and convert to calibrated mGauss.                    */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (reg_read(fd, LIS3MDL_OUT_X_L, &xl) < 0) return -1;
    if (reg_read(fd, LIS3MDL_OUT_X_H, &xh) < 0) return -1;
    if (reg_read(fd, LIS3MDL_OUT_Y_L, &yl) < 0) return -1;
    if (reg_read(fd, LIS3MDL_OUT_Y_H, &yh) < 0) return -1;
    if (reg_read(fd, LIS3MDL_OUT_Z_L, &zl) < 0) return -1;
    if (reg_read(fd, LIS3MDL_OUT_Z_H, &zh) < 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = ((float)raw_x * SENSITIVITY_MG_LSB) + X_OFFSET;
    *y = ((float)raw_y * SENSITIVITY_MG_LSB) + Y_OFFSET;
    *z = ((float)raw_z * SENSITIVITY_MG_LSB) + Z_OFFSET;

    *x *= X_SCALE;
    *y *= Y_SCALE;
    *z *= Z_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z) < 0) {
        perror("log_data: fprintf failed");
    } else {
        fflush(fp);
    }
}

/* ------------------------------------------------------------------ */
static void metal_detector(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr,
                "[ALERT] Metal detected! Field magnitude: %.2f mG\n",
                magnitude);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor with retries ---- */
    int init_ok = 0;
    for (int attempt = 0; attempt < 3; attempt++) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Sensor init attempt %d/3 failed; retrying...\n",
                attempt + 1);
        usleep(100000);  /* 100 ms back-off */
    }
    if (!init_ok) {
        fprintf(stderr, "Sensor init failed after 3 attempts.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open log file once ---- */
    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen magnetic_log.txt");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("LIS3MDL logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);

    while (g_running) {
        float x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error; re-initialising sensor...\n");
            if (init_lis3mdl(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
            continue;
        }

        log_data(g_log_fp, x, y, z);
        metal_detector(x, y, z);

        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_sec  += 1;
            next.tv_nsec -= 1000000000L;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (next.tv_sec > now.tv_sec ||
            (next.tv_sec == now.tv_sec && next.tv_nsec > now.tv_nsec)) {
            struct timespec delta = {
                next.tv_sec  - now.tv_sec,
                next.tv_nsec - now.tv_nsec
            };
            nanosleep(&delta, NULL);
        } else {
            /* Fell behind; resync to current time */
            next = now;
        }
    }

    /* ---- Cleanup ---- */
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

