#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL354B register map (from datasheet) ---- */
#define ADXL354B_REG_STATUS        0x04
#define ADXL354B_REG_POWER_CTL     0x2D
#define ADXL354B_REG_RESET         0x1F
#define ADXL354B_REG_PARTID        0x02
#define ADXL354B_REG_XDATA_H       0x08
#define ADXL354B_REG_XDATA_L       0x0A
#define ADXL354B_REG_YDATA_H       0x0B
#define ADXL354B_REG_YDATA_L       0x0D
#define ADXL354B_REG_ZDATA_H       0x0E
#define ADXL354B_REG_ZDATA_L       0x10

#define ADXL354B_PARTID_EXPECTED   0xE5

/* SPI flags: bit 7 = read (1), bit 6 = multi-byte (1) */
#define ADXL354B_READ_BIT         0x80
#define ADXL354B_MULTI_BIT        0x40

/* ---- SPI configuration ---- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US  100000  /* 100 ms */
#define RESET_DELAY_US    1000    /* 1 ms after reset */
#define STABLE_TIMEOUT_US 500000  /* 500 ms to wait for STABLE bit */

/* ---- Globals for cleanup ---- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL354B register.                             */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int adxl354b_write_reg(uint8_t reg, uint8_t value)
{
    char tx[2] = { (char)(reg & 0x3F), (char)value };   /* bit7=0 (write), bit6=0 (single) */
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL354B register.                            */
/* Returns 0 on success and stores value in *out, -1 on error.        */
/* ------------------------------------------------------------------ */
static int adxl354b_read_reg(uint8_t reg, uint8_t *out)
{
    char tx[2] = { (char)(reg | ADXL354B_READ_BIT), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 20-bit axis value (3 bytes: high, low, X2).                 */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int adxl354b_read_axis(uint8_t reg_high, int32_t *out)
{
    uint8_t h, l, x2;

    if (adxl354b_read_reg(reg_high, &h) != 0)
        return -1;
    if (adxl354b_read_reg(reg_high + 1, &l) != 0)
        return -1;
    if (adxl354b_read_reg(reg_high + 2, &x2) != 0)
        return -1;

    /* 20-bit two's-complement: shift right 4 to get signed 12-bit value */
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)x2;
    raw >>= 4;
    if (raw & 0x00000800)                       /* sign-extend 12 -> 32 */
        raw |= 0xFFFFF000;
    *out = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the ADXL354B and wait for STABLE bit.                         */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int adxl354b_reset(void)
{
    /* Issue software reset: write 0x52 to RESET register */
    if (adxl354b_write_reg(ADXL354B_REG_RESET, 0x52) != 0)
        return -1;

    gpioDelay(RESET_DELAY_US);

    /* Clear RUN bit to enter standby */
    if (adxl354b_write_reg(ADXL354B_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* Wait for STABLE bit to be set (max ~500 ms) */
    uint8_t status = 0;
    for (int i = 0; i < STABLE_TIMEOUT_US / 10000; i++) {
        if (adxl354b_read_reg(ADXL354B_REG_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(10000);
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "ADXL354B STABLE bit never set (status=0x%02X)\n", status);
        return -1;
    }

    /* Set RUN bit to start measurement */
    if (adxl354b_write_reg(ADXL354B_REG_POWER_CTL, 0x02) != 0)
        return -1;

    return 0;
}

