/* ------------------------------------------------------------------ */
static int adxl354b_verify_partid(void)
{
    uint8_t partid = 0;
    if (adxl354b_read_reg(ADXL354B_REG_PARTID, &partid) != 0)
        return -1;
    if (partid != ADXL354B_PARTID_EXPECTED) {
        fprintf(stderr, "PARTID mismatch: got 0x%02X, expected 0x%02X\n",
                partid, ADXL354B_PARTID_EXPECTED);
        return -1;
    }
    return 0;
}

