/* Returns 0 on success, -1 on persistent failure.                    */
/* ------------------------------------------------------------------ */
static int adxl354b_read_all(int32_t *x, int32_t *y, int32_t *z)
{
    for (int attempt = 0; attempt < 3; attempt++) {
        if (adxl354b_read_axis(ADXL354B_REG_XDATA_H, x) == 0 &&
            adxl354b_read_axis(ADXL354B_REG_YDATA_H, y) == 0 &&
            adxl354b_read_axis(ADXL354B_REG_ZDATA_H, z) == 0)
            return 0;
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log one sample with timestamp.                                     */
/* ------------------------------------------------------------------ */
static void log_sample(int32_t x, int32_t y, int32_t z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X=%d, Y=%d, Z=%d\n", ts, x, y, z);
    fflush(log_file);
