/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        perror("fopen vibration_log.txt");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Sensor init ---- */
    if (adxl354b_verify_partid() != 0) {
        fprintf(stderr, "ADXL354B not detected or wrong part ID\n");
        goto cleanup;
    }
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        goto cleanup;
    }

    printf("ADXL354B vibration monitor started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (!terminate) {
        int32_t x, y, z;

        if (adxl354b_read_all(&x, &y, &z) == 0) {
            log_sample(x, y, z);
        } else {
            fprintf(stderr, "SPI read failed after retries; continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

cleanup:
