/*
 * ADIS16362 IMU reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADIS16362 CS  -> GPIO8  (BCM 8, SPI CE0)
 *   ADIS16362 SCLK-> GPIO11 (BCM 11, SPI SCLK)
 *   ADIS16362 DOUT-> GPIO9  (BCM 9, SPI MISO)
 *   ADIS16362 DIN -> GPIO10 (BCM 10, SPI MOSI)
 *   ADIS16362 VDD-> 3.3 V
 *   ADIS16362 GND-> GND
 *
 * Build:
 *   gcc -O2 -Wall -o imu_reader imu_reader.c -lpigpio -lrt
 *   (pigpio must be installed and run with sudo)
 *
 * Run:
 *   sudo ./imu_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16362 register addresses (8-bit addresses, MSB=1 for read) ---- */
#define ADIS16362_REG_XGYRO_OUT  0x04
#define ADIS16362_REG_YGYRO_OUT  0x06
#define ADIS16362_REG_ZGYRO_OUT  0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_BAUD    1000000    /* 1 MHz */
#define SPI_FLAGS   0x0003     /* Mode 3: CPOL=1, CPHA=1 */

/* ---- Scaling factors (from ADIS16362 datasheet) ---- */
#define GYRO_SCALE  0.05f      /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f    /* g per LSB */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 10000 /* 10 ms -> ~100 Hz */

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16362.                          */
/* Protocol: send [addr | 0x80] [dummy], then capture [dummy] [data].  */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *value)
{
    char tx[2], rx[2];
    int  ret;

    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }

    /* rx[0] is the echo of the address byte; rx[1] is the data byte. */
    *value = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];
    int16_t raw_gyro[3], raw_accel[3];
    float gyro[3], accel[3];
    int rc;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* ---- Signal handling ---- */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (!terminate) {
        /* Read all six channels in one pass for atomicity */
        rc = 0;
        rc |= read_register(ADIS16362_REG_XGYRO_OUT,  &raw_gyro[0]);
        rc |= read_register(ADIS16362_REG_YGYRO_OUT,  &raw_gyro[1]);
        rc |= read_register(ADIS16362_REG_ZGYRO_OUT,  &raw_gyro[2]);
        rc |= read_register(ADIS16362_REG_XACCEL_OUT, &raw_accel[0]);
        rc |= read_register(ADIS16362_REG_YACCEL_OUT, &raw_accel[1]);
        rc |= read_register(ADIS16362_REG_ZACCEL_OUT, &raw_accel[2]);

        if (rc != 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw to engineering units */
        gyro[0]  = (float)raw_gyro[0]  * GYRO_SCALE;
        gyro[1]  = (float)raw_gyro[1]  * GYRO_SCALE;
        gyro[2]  = (float)raw_gyro[2]  * GYRO_SCALE;
        accel[0] = (float)raw_accel[0] * ACCEL_SCALE;
        accel[1] = (float)raw_accel[1] * ACCEL_SCALE;
        accel[2] = (float)raw_accel[2] * ACCEL_SCALE;

        /* Timestamp */
        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        snprintf(timestamp + strlen(timestamp),
                 sizeof(timestamp) - strlen(timestamp),
                 ".%09ld", ts.tv_nsec);

        /* Log to CSV */
        fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp, gyro[0], gyro[1], gyro[2],
                accel[0], accel[1], accel[2]);
        fflush(log_file);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

