        rc = 0;
        rc |= read_register(ADIS16362_REG_XGYRO_OUT,  &raw_gyro[0]);
        rc |= read_register(ADIS16362_REG_YGYRO_OUT,  &raw_gyro[1]);
        rc |= read_register(ADIS16362_REG_ZGYRO_OUT,  &raw_gyro[2]);
        rc |= read_register(ADIS16362_REG_XACCEL_OUT, &raw_accel[0]);
        rc |= read_register(ADIS16362_REG_YACCEL_OUT, &raw_accel[1]);
        rc |= read_register(ADIS16362_REG_ZACCEL_OUT, &raw_accel[2]);

        if (rc != 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw to engineering units */
        gyro[0]  = (float)raw_gyro[0]  * GYRO_SCALE;
        gyro[1]  = (float)raw_gyro[1]  * GYRO_SCALE;
        gyro[2]  = (float)raw_gyro[2]  * GYRO_SCALE;
        accel[0] = (float)raw_accel[0] * ACCEL_SCALE;
        accel[1] = (float)raw_accel[1] * ACCEL_SCALE;
        accel[2] = (float)raw_accel[2] * ACCEL_SCALE;

        /* Timestamp */
        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        snprintf(timestamp + strlen(timestamp),
                 sizeof(timestamp) - strlen(timestamp),
                 ".%09ld", ts.tv_nsec);

        /* Log to CSV */
        fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp, gyro[0], gyro[1], gyro[2],
                accel[0], accel[1], accel[2]);
        fflush(log_file);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

