 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO bank on Raspberry Pi 5 */
#define GPIO_LINE_OFFSET 17           /* BCM 17 */
#define POLL_INTERVAL_SEC 1
#define SIMULATED_SEQUENCE_SEC 5

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_msg(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
        printf("[%s] %s\n", ts, msg);
    } else {
        printf("[unknown] %s\n", msg);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Install SIGINT handler for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get the GPIO line ---- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* ---- Request the line as input ---- */
    if (gpiod_line_request_input(line, "self_parking") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Self-parking monitor started.  Polling E18-D80NK on %s line %d "
           "every %d s.  Press Ctrl-C to exit.\n",
           GPIO_CHIP_NAME, GPIO_LINE_OFFSET, POLL_INTERVAL_SEC);
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        if (val == 0) {                 /* E18-D80NK output is active-LOW */
            log_msg("Self-parking sequence started");
            sleep(SIMULATED_SEQUENCE_SEC);
            log_msg("Self-parking sequence completed");
        }

        if (g_running) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

