/*
 * KY-032 IR Obstacle Avoidance Sensor Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern GPIO API)
 *
 * Wiring
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND   (physical pin 9)
 *
 * The Keyes KY-032 module outputs LOW (0) when an obstacle is
 * detected and HIGH (1) when the path is clear.  We log the
 * detection status to stdout every 100 ms.
 *
 * Build:  gcc -Wall -Wextra -O2 -o ky032_monitor ky032_monitor.c -lpigpio -lrt
 * Run:    sudo ./ky032_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define POLL_DELAY_US 100000          /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Read both sensor lines in a single bulk read.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensors(int *s1, int *s2)
{
    int v = gpioRead(SENSOR1_GPIO);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d (pigpio error %d)\n",
                SENSOR1_GPIO, v);
        return -1;
    }
    *s1 = v;

    v = gpioRead(SENSOR2_GPIO);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d (pigpio error %d)\n",
                SENSOR2_GPIO, v);
        return -1;
    }
    *s2 = v;

    return 0;
}

/*
 * Print a timestamped detection status line.
 * The KY-032 module is active-low: 0 = obstacle detected, 1 = clear.
 */
static void log_status(int s1, int s2)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "----");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    printf("[%s] Sensor1: %s | Sensor2: %s\n",
           ts,
           s1 ? "Clear" : "Obstacle",
           s2 ? "Clear" : "Obstacle");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers early ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins as inputs ---- */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1, s2;

        if (read_sensors(&s1, &s2) == 0) {
            log_status(s1, s2);
        } else {
            fprintf(stderr, "Sensor read error — continuing to retry.\n");
        }

        /*
         * gpioDelay returns the actual delay in microseconds.
         * If it returns < 0, pigpio reports an error; we log and
         * continue rather than aborting.
         */
        int delay_rc = gpioDelay(POLL_DELAY_US);
        if (delay_rc < 0) {
            fprintf(stderr, "gpioDelay failed (pigpio error %d)\n", delay_rc);
        }
    }

    /* ---- Clean shutdown ---- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

