/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16266 SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16266 DOUT-> GPIO9  (BCM 9,  SPI0 MISO)
 *   ADIS16266 DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16266 VCC-> 3.3 V
 *   ADIS16266 GND-> GND
 *
 * Build:
 *   gcc -O2 -Wall -o adis16266_reader adis16266_reader.c -lm
 *
 * Run:
 *   ./adis16266_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADIS16266 register map ---- */
#define ADIS16266_XGYRO_OUT  0x04
#define ADIS16266_YGYRO_OUT  0x06
#define ADIS16266_ZGYRO_OUT  0x08
#define ADIS16266_SMPL_PRD   0x36
#define ADIS16266_GLOB_CMD   0x68
#define ADIS16266_PROD_ID    0x7E
#define ADIS16266_PROD_ID_VAL 0x4D

/* ---- SPI configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_3

/* ---- Gyroscope scale factor (deg/sec per LSB) ---- */
#define GYRO_SCALE 0.02f

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_MS 100

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Delay for the given number of milliseconds, interrupt-safe.         */
static void delay_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* Retry if interrupted by a signal. */
    }
}

/* ------------------------------------------------------------------ */
/* Open the SPI device and configure it for ADIS16266-compatible mode. */
static int spi_open(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/*
 * ADIS16266 SPI read protocol (Mode 3, MSB first):
 *   TX: [0x80 | (reg << 1)]  [0x00]
 *   RX: [don't-care]         [don't-care]
 *   Then a second transfer to read the 16-bit data:
 *   TX: [0x00]               [0x00]
 *   RX: [don't-care]         [don't-care]
 *   The received data is assembled from the two transfers.
 */
static int adis_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx_cmd[2] = { (uint8_t)(0x80U | ((reg << 1U) & 0x7EU)), 0x00U };
    uint8_t rx_cmd[2] = { 0, 0 };
    uint8_t tx_data[2] = { 0x00U, 0x00U };
    uint8_t rx_data[2] = { 0, 0 };

    struct spi_ioc_transfer tr[2];
    memset(tr, 0, sizeof(tr));

    /* Transfer 1: send read command */
    tr[0].tx_buf        = (unsigned long)tx_cmd;
    tr[0].rx_buf        = (unsigned long)rx_cmd;
    tr[0].len           = 2;
    tr[0].speed_hz      = SPI_SPEED_HZ;
    tr[0].bits_per_word = SPI_BITS;
    tr[0].delay_usecs   = 0;
    tr[0].cs_change     = 0;

    /* Transfer 2: read 16-bit data */
    tr[1].tx_buf        = (unsigned long)tx_data;
    tr[1].rx_buf        = (unsigned long)rx_data;
    tr[1].len           = 2;
    tr[1].speed_hz      = SPI_SPEED_HZ;
    tr[1].bits_per_word = SPI_BITS;
    tr[1].delay_usecs   = 0;
    tr[1].cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(2), tr) < 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Data is returned in the second transfer's receive buffer. */
    *out = (int16_t)((rx_data[0] << 8) | rx_data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * ADIS16266 SPI write protocol (Mode 3, MSB first):
 *   TX: [0x00 | (reg << 1)]  [data_hi] [data_lo]
 *   RX: [don't-care]         [don't-care] [don't-care]
 */
static int adis_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t tx[3] = {
        (uint8_t)((reg << 1U) & 0x7EU),
        (uint8_t)((value >> 8) & 0xFFU),
        (uint8_t)(value & 0xFFU)
    };
    uint8_t rx[3] = { 0, 0, 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));

    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI write failed for register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adis_init(int fd)
{
    /* Software reset: write 0x0001 to GLOB_CMD and wait for reset to complete. */
    if (adis_write_reg16(fd, ADIS16266_GLOB_CMD, 0x0001U) < 0)
        return -1;
    delay_ms(100);

    /* Clear any pending reset by writing 0x0000. */
    if (adis_write_reg16(fd, ADIS16266_GLOB_CMD, 0x0000U) < 0)
        return -1;
    delay_ms(10);

    /* Verify product ID. */
    int16_t prod_id = 0;
    if (adis_read_reg16(fd, ADIS16266_PROD_ID, &prod_id) < 0)
        return -1;
    if ((uint8_t)prod_id != ADIS16266_PROD_ID_VAL) {
        fprintf(stderr, "Unexpected product ID: 0x%02X (expected 0x%02X)\n",
                (uint8_t)prod_id, ADIS16266_PROD_ID_VAL);
        return -1;
    }

    /* Set sample period to ~100 ms (0x0064 = 100 ms / 10 ms). */
    if (adis_write_reg16(fd, ADIS16266_SMPL_PRD, 0x0064U) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device. */
    g_spi_fd = spi_open();
    if (g_spi_fd < 0)
        return EXIT_FAILURE;

    /* Initialize sensor. */
    if (adis_init(g_spi_fd) < 0) {
        fprintf(stderr, "ADIS16266 initialization failed.\n");
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("ADIS16266 initialized. Logging gyroscope data every %d ms.\n",
           SAMPLE_PERIOD_MS);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop. */
    while (g_running) {
        int16_t x_raw = 0, y_raw = 0, z_raw = 0;

        if (adis_read_reg16(g_spi_fd, ADIS16266_XGYRO_OUT, &x_raw) < 0 ||
            adis_read_reg16(g_spi_fd, ADIS16266_YGYRO_OUT, &y_raw) < 0 ||
            adis_read_reg16(g_spi_fd, ADIS16266_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "SPI read error — continuing.\n");
        } else {
            float x_rate = (float)x_raw * GYRO_SCALE;
            float y_rate = (float)y_raw * GYRO_SCALE;
            float z_rate = (float)z_raw * GYRO_SCALE;
            printf("X: %7.2f deg/s  Y: %7.2f deg/s  Z: %7.2f deg/s\n",
                   x_rate, y_rate, z_rate);
        }

        delay_ms(SAMPLE_PERIOD_MS);
    }

    /* Clean shutdown. */
    printf("\nShutting down...\n");
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

