 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16266 SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16266 DOUT-> GPIO9  (BCM 9,  SPI0 MISO)
 *   ADIS16266 DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16266 VCC-> 3.3 V
 *   ADIS16266 GND-> GND
 *
 * Build:
 *   gcc -O2 -Wall -o adis16266_reader adis16266_reader.c -lm
 *
 * Run:
 *   ./adis16266_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADIS16266 register map ---- */
#define ADIS16266_XGYRO_OUT  0x04
#define ADIS16266_YGYRO_OUT  0x06
#define ADIS16266_ZGYRO_OUT  0x08
#define ADIS16266_SMPL_PRD   0x36
#define ADIS16266_GLOB_CMD   0x68
#define ADIS16266_PROD_ID    0x7E
#define ADIS16266_PROD_ID_VAL 0x4D

