static int adis_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t tx[3] = {
        (uint8_t)((reg << 1U) & 0x7EU),
        (uint8_t)((value >> 8) & 0xFFU),
        (uint8_t)(value & 0xFFU)
    };
