    /* Clear any pending reset by writing 0x0000. */
    if (adis_write_reg16(fd, ADIS16266_GLOB_CMD, 0x0000U) < 0)
        return -1;
    delay_ms(10);

    /* Verify product ID. */
    int16_t prod_id = 0;
    if (adis_read_reg16(fd, ADIS16266_PROD_ID, &prod_id) < 0)
        return -1;
    if ((uint8_t)prod_id != ADIS16266_PROD_ID_VAL) {
        fprintf(stderr, "Unexpected product ID: 0x%02X (expected 0x%02X)\n",
                (uint8_t)prod_id, ADIS16266_PROD_ID_VAL);
        return -1;
    }

    /* Set sample period to ~100 ms (0x0064 = 100 ms / 10 ms). */
    if (adis_write_reg16(fd, ADIS16266_SMPL_PRD, 0x0064U) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device. */
    g_spi_fd = spi_open();
    if (g_spi_fd < 0)
        return EXIT_FAILURE;

    /* Initialize sensor. */
    if (adis_init(g_spi_fd) < 0) {
        fprintf(stderr, "ADIS16266 initialization failed.\n");
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("ADIS16266 initialized. Logging gyroscope data every %d ms.\n",
           SAMPLE_PERIOD_MS);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop. */
    while (g_running) {
        int16_t x_raw = 0, y_raw = 0, z_raw = 0;

        if (adis_read_reg16(g_spi_fd, ADIS16266_XGYRO_OUT, &x_raw) < 0 ||
            adis_read_reg16(g_spi_fd, ADIS16266_YGYRO_OUT, &y_raw) < 0 ||
            adis_read_reg16(g_spi_fd, ADIS16266_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "SPI read error — continuing.\n");
        } else {
            float x_rate = (float)x_raw * GYRO_SCALE;
            float y_rate = (float)y_raw * GYRO_SCALE;
            float z_rate = (float)z_raw * GYRO_SCALE;
            printf("X: %7.2f deg/s  Y: %7.2f deg/s  Z: %7.2f deg/s\n",
                   x_rate, y_rate, z_rate);
        }

        delay_ms(SAMPLE_PERIOD_MS);
    }

    /* Clean shutdown. */
    printf("\nShutting down...\n");
    if (g_spi_fd >= 0) {
