 * CTRL1_XL = 0x60 -> ODR_XL = 1 kHz, FS_XL = +/- 2 g
 * CTRL2_G  = 0x60 -> ODR_G  = 1 kHz, FS_G  = 245 dps
 * CTRL3_C  = 0x00 -> accelerometer anti-alias bandwidth = 5 Hz, low-noise disabled
 */
#define CTRL1_XL_VAL 0x60
#define CTRL2_G_VAL  0x60
#define CTRL3_C_VAL  0x00

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_checked(int handle, uint8_t reg, uint8_t val, const char *label)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "Error: failed to write 0x%02X to register 0x%02X (%s)\n",
                val, reg, label);
        return -1;
    }
    return 0;
}

static int i2c_read_burst_checked(int handle, uint8_t reg, uint8_t *buf, uint32_t len,
                                  const char *label)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "Error: I2C burst read of %u bytes from 0x%02X (%s) failed: got %d\n",
                len, reg, label, n);
        return -1;
    }
    return 0;
}

/* ---- Initialization ---- */
static int initialize_lsm6dsr(int handle)
{
    /* Verify device identity */
    int who = i2cReadByteData(handle, LSM6DSR_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /* Configure accelerometer: 1 kHz, +/- 2 g */
    if (i2c_write_checked(handle, LSM6DSR_CTRL1_XL, CTRL1_XL_VAL, "CTRL1_XL") < 0)
        return -1;

    /* Configure gyroscope: 1 kHz, 245 dps */
    if (i2c_write_checked(handle, LSM6DSR_CTRL2_G, CTRL2_G_VAL, "CTRL2_G") < 0)
        return -1;

    /* Configure accelerometer anti-alias / low-noise */
    if (i2c_write_checked(handle, LSM6DSR_CTRL3_C, CTRL3_C_VAL, "CTRL3_C") < 0)
        return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[6];

    /* Burst read 6 bytes starting at OUTX_L_G (0x22) */
    if (i2c_read_burst_checked(handle, LSM6DSR_OUTX_L_G, buf, 6, "gyro") < 0)
        return -1;
    *gx = (int16_t)((buf[1] << 8) | buf[0]);
    *gy = (int16_t)((buf[3] << 8) | buf[2]);
    *gz = (int16_t)((buf[5] << 8) | buf[4]);

    /* Burst read 6 bytes starting at OUTX_L_XL (0x28) */
    if (i2c_read_burst_checked(handle, LSM6DSR_OUTX_L_XL, buf, 6, "accel") < 0)
        return -1;
    *ax = (int16_t)((buf[1] << 8) | buf[0]);
    *ay = (int16_t)((buf[3] << 8) | buf[2]);
    *az = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM6DSR_ADDR */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main sampling loop */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%d,%d,%d,%d,%d,%d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: sensor read failed, exiting\n");
            break;
        }

        /* 100 ms delay (microseconds) */
        gpioDelay(100000);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

