/*
 * Raspberry Pi 4 Model B – Adafruit FXOS8700 I2C accelerometer/magnetometer reader
 *
 * Wiring:
 *   FXOS8700 SDA  -> Pi GPIO2 (pin 3, I2C bus 1 SDA)
 *   FXOS8700 SCL  -> Pi GPIO3 (pin 5, I2C bus 1 SCL)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -lpigpio -lrt
 * Run:    sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 constants (per Adafruit breakout / datasheet) ---- */
#define FXOS8700_I2C_ADDR        0x1C          /* SA0 tied high on breakout */
#define FXOS8700_REG_STATUS      0x00
#define FXOS8700_REG_OUT_X_MSB   0x01          /* accel X MSB (auto-increment) */
#define FXOS8700_REG_M_OUT_X_MSB 0x31          /* mag   X MSB (auto-increment) */
#define FXOS8700_REG_WHOAMI      0x0D
#define FXOS8700_REG_CTRL_REG1   0x2A
#define FXOS8700_REG_CTRL_REG2   0x2B

#define FXOS8700_WHOAMI_VAL      0xC7

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

/*
 * Read a single byte from a register.
 * Returns 0 on success, -1 on error.
 */
static int read_register(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on error.
 */
static int write_register(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes starting at `reg` using a combined SMBus block read.
 * Returns 0 on success, -1 on error.
 */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ---- FXOS8700 driver ---- */

/*
 * Probe the device and verify identity.
 * Returns 0 on success, -1 on error.
 */
static int fxos8700_probe(int handle)
{
    uint8_t whoami = 0;
    if (read_register(handle, FXOS8700_REG_WHOAMI, &whoami) != 0)
        return -1;
    if (whoami != FXOS8700_WHOAMI_VAL) {
        fprintf(stderr, "[ERROR] WHOAMI mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, FXOS8700_WHOAMI_VAL);
        return -1;
    }
    printf("[INFO] FXOS8700 detected (WHOAMI=0x%02X)\n", whoami);
    return 0;
}

/*
 * Initialise the FXOS8700:
 *   CTRL_REG1 = 0x00  -> standby mode (we'll use M_CTRL_REG1 later)
 *   CTRL_REG2 = 0x02  -> auto-increment during multi-byte reads
 *   M_CTRL_REG1 = 0x1F -> hybrid mode, OSR=7, auto-increment
 *   M_CTRL_REG2 = 0x20 -> hybrid mode, OSR=7, auto-increment
 * Returns 0 on success, -1 on error.
 */
static int fxos8700_init(int handle)
{
    if (write_register(handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;
    if (write_register(handle, FXOS8700_REG_CTRL_REG2, 0x02) != 0)
        return -1;
    if (write_register(handle, 0x5B, 0x1F) != 0)   /* M_CTRL_REG1 */
        return -1;
    if (write_register(handle, 0x5C, 0x20) != 0)   /* M_CTRL_REG2 */
        return -1;
    return 0;
}

/*
 * Read one 12-byte block: 6 accel (14-bit left-aligned) + 6 mag (16-bit).
 * Returns 0 on success, -1 on error.
 */
static int fxos8700_read_data(int handle,
                              int16_t *ax, int16_t *ay, int16_t *az,
                              int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];
    if (read_block(handle, FXOS8700_REG_OUT_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    /* Accelerometer: 14-bit left-aligned, two's complement */
    int16_t raw_ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    int16_t raw_ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    int16_t raw_az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 16-bit two's complement */
    int16_t raw_mx = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t raw_my = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t raw_mz = (int16_t)((buf[10] << 8) | buf[11]);

    *ax = raw_ax; *ay = raw_ay; *az = raw_az;
    *mx = raw_mx; *my = raw_my; *mz = raw_mz;
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                FXOS8700_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe and configure the sensor */
    if (fxos8700_probe(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] FXOS8700 not detected at 0x%02X\n",
                FXOS8700_I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fxos8700_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] FXOS8700 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("[INFO] Reading every 100 ms. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (fxos8700_read_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Mag: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "[WARN] I2C read failed; will retry next cycle\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Graceful cleanup */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

