/*
 * tilt_monitor.c — Raspberry Pi 5 tilt monitor using ADXL345 (I2C)
 *
 * Reads acceleration from an ADXL345 over I2C and logs tilt-exceeding
 * events to /var/log/tilt_events.log.  Uses pigpio for I2C and a
 * modern, robust, signal-safe logging API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS            1          /* Pi 5 default user I2C bus           */
#define ADXL345_ADDR       0x53       /* ADXL345 default I2C address (ALT ADD=1) */

#define ADXL345_REG_DEVID   0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0   0x32

#define ADXL345_DEVID       0xE5      /* Expected device ID                  */
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_DATA_FORMAT_FULL_RES 0x08

#define TILT_THRESHOLD_DEG  30.0f
#define LOG_FILE            "/var/log/tilt_events.log"
#define SAMPLE_PERIOD_US    100000    /* 100 ms                              */
#define MAX_CONSECUTIVE_ERRORS 10

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  adxl345_init(int handle);
static int  read_acceleration(int handle, float *x, float *y, float *z);
static float calculate_tilt_angle(float x, float y, float z);
static void log_tilt_event(float angle);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly              */
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- ADXL345 init ------------------------------ */

static int adxl345_init(int handle)
{
    int devid = i2cReadByteData(handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: I2C read of DEVID failed (pigpio err %d).\n",
                devid);
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr,
                "Error: DEVID mismatch (got 0x%02X, expected 0x%02X).\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_REG_DATA_FORMAT,
                         ADXL345_DATA_FORMAT_FULL_RES) < 0) {
        fprintf(stderr, "Error: Failed to set DATA_FORMAT.\n");
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL,
                         ADXL345_POWER_CTL_MEASURE) < 0) {
        fprintf(stderr, "Error: Failed to set POWER_CTL (measure).\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Read acceleration -------------------------- */

static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];

    if (i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6-byte acceleration block.\n");
        return -1;
    }

    int16_t x_raw = (int16_t)((raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | (uint8_t)raw[4]);

    /*
     * Full-resolution mode: 4 mg/LSB => 0.004 g/LSB.
     * Raw values are already in g units (divide by 256).
     */
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

/* ----------------------------- Tilt angle -------------------------------- */

static float calculate_tilt_angle(float x, float y, float z)
{
    /*
     * Tilt angle from the X-Y plane (degrees).
     *   atan2(y, x)  -> roll
     *   atan2(-z, sqrt(x^2 + y^2)) -> pitch
     *   atan2(y, sqrt(x^2 + z^2))  -> roll (same as atan2(y, x))
     *   atan2(-z, sqrt(x^2 + y^2)) -> pitch (same as atan2(-z, sqrt(x^2 + y^2)))
     *
     * We use the roll-pitch decomposition:
     *   roll  = atan2(y, x)
     *   pitch = atan2(-z, sqrt(x^2 + y^2))
     *   tilt  = |roll| + |pitch|  (simplified for this application)
     */
    float roll  = atan2f(y, x) * 180.0f / (float)M_PI;
    float pitch = atan2f(-z, sqrtf(x * x + y * y)) * 180.0f / (float)M_PI;
    return fabsf(roll) + fabsf(pitch);
}

/* ----------------------------- Log event --------------------------------- */

static void log_tilt_event(float angle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Tilt angle: %.2f degrees\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, angle);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio err %d).\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize ADXL345 --- */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt monitor started. Logging to %s every 100 ms.\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    /* --- Main loop --- */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) < 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr,
                        "Error: %d consecutive I2C read failures. "
                        "Sensor may be absent or bus stuck. Exiting.\n",
                        consecutive_errors);
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        float angle = calculate_tilt_angle(x, y, z);

        if (angle > TILT_THRESHOLD_DEG) {
            log_tilt_event(angle);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

