/*
 * KY-038 sound sensor monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-038 VCC  -> 3.3 V (pin 1)
 *   KY-038 GND  -> GND   (pin 9)
 *   KY-038 OUT  -> GPIO17 (pin 11, BCM 17)
 *
 * The KY-038 OUT line is a digital output that goes high when sound
 * exceeds the module's internal threshold.  We sample it every 1 ms
 * over a 5-second window and count high readings; if the count exceeds
 * a user-supplied threshold we print "ALERT"; otherwise a status line.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_monitor sound_monitor.c -lpigpio -lrt
 * Run:    ./sound_monitor <threshold>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN      17          /* BCM 17, physical pin 11 */
#define WINDOW_SECONDS  5           /* sampling window duration */
#define SAMPLE_US       1000        /* 1 ms sampling interval   */
#define PAUSE_SECONDS   1           /* pause between windows    */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a static timestamp string; never returns NULL.              */
static const char *get_timestamp(void)
{
    static char buf[32];
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, sizeof(buf), "[time-error]");
        return buf;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, sizeof(buf), "[localtime-error]");
        return buf;
    }
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmv);
    return buf;
}

/* ------------------------------------------------------------------ */
/* Read the sensor pin; returns 0 or 1, or -1 on error.               */
static int read_sensor(void)
{
    int v = gpioRead(SENSOR_PIN);
    if (v < 0) {
        fprintf(stderr, "%s: gpioRead failed on pin %d (rc=%d)\n",
                get_timestamp(), SENSOR_PIN, v);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Sample the sensor for WINDOW_SECONDS, count high readings.         */
static int sample_window(int threshold)
{
    int high_count = 0;
    int elapsed_us = 0;
    const int window_us = WINDOW_SECONDS * 1000000;

    while (elapsed_us < window_us && g_running) {
        int v = read_sensor();
        if (v < 0) {
            return -1;                 /* error already reported */
        }
        if (v == 1) {
            high_count++;
        }
        gpioDelay(SAMPLE_US);
        elapsed_us += SAMPLE_US;
    }

    if (!g_running) {
        return -1;                     /* interrupted */
    }

    if (high_count > threshold) {
        printf("%s ALERT high_count=%d threshold=%d\n",
               get_timestamp(), high_count, threshold);
    } else {
        printf("%s STATUS high_count=%d threshold=%d\n",
               get_timestamp(), high_count, threshold);
    }
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold = integer count of high readings "
                        "per %d-second window (must be >= 0)\n",
                        WINDOW_SECONDS);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long val = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || val < 0) {
        fprintf(stderr, "Error: threshold must be a non-negative integer.\n");
        return EXIT_FAILURE;
    }
    int threshold = (int)val;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s: pigpio initialisation failed\n", get_timestamp());
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin as input ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "%s: gpioSetMode failed on pin %d\n",
                get_timestamp(), SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- optional: enable internal pull-down so the line is defined
           when the sensor is disconnected ---- */
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "%s: gpioSetPullUpDown warning on pin %d\n",
                get_timestamp(), SENSOR_PIN);
        /* non-fatal: continue anyway */
    }

    /* ---- signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("%s Monitoring KY-038 on GPIO%d every %d s, threshold=%d.\n",
           get_timestamp(), SENSOR_PIN, WINDOW_SECONDS, threshold);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* ---- main sampling loop ---- */
    while (g_running) {
        if (sample_window(threshold) < 0) {
            break;                     /* error or interrupt */
        }
        sleep(PAUSE_SECONDS);
    }

    /* ---- cleanup ---- */
    gpioTerminate();
    printf("%s Exiting cleanly.\n", get_timestamp());
    return EXIT_SUCCESS;
}

