    long val = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || val < 0) {
        fprintf(stderr, "Error: threshold must be a non-negative integer.\n");
        return EXIT_FAILURE;
    }
    int threshold = (int)val;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s: pigpio initialisation failed\n", get_timestamp());
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pin as input ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "%s: gpioSetMode failed on pin %d\n",
                get_timestamp(), SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- optional: enable internal pull-down so the line is defined
           when the sensor is disconnected ---- */
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "%s: gpioSetPullUpDown warning on pin %d\n",
                get_timestamp(), SENSOR_PIN);
        /* non-fatal: continue anyway */
    }

    /* ---- signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("%s Monitoring KY-038 on GPIO%d every %d s, threshold=%d.\n",
           get_timestamp(), SENSOR_PIN, WINDOW_SECONDS, threshold);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* ---- main sampling loop ---- */
    while (g_running) {
        if (sample_window(threshold) < 0) {
            break;                     /* error or interrupt */
        }
        sleep(PAUSE_SECONDS);
    }

    /* ---- cleanup ---- */
    gpioTerminate();
    printf("%s Exiting cleanly.\n", get_timestamp());
    return EXIT_SUCCESS;
}

