/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12 V electromagnetic door locks via TIP120-driven
 * 5 V active-HIGH relay modules on GPIO17 (BCM) and GPIO27 (BCM).
 *
 * Build:  gcc -Wall -Wextra -O2 -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN      17
#define DOOR_B_PIN      27
#define CODE_LENGTH     6
#define LOG_FILE        "access_log.txt"
#define UNLOCK_DURATION 5          /* seconds */
#define POLL_TIMEOUT_MS 1000       /* gpiod_line_event_wait timeout */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int generate_code(char *buf, size_t len)
{
    if (len < (size_t)CODE_LENGTH + 1) {
        fprintf(stderr, "generate_code: buffer too small\n");
        return -1;
    }
    int code = 100000 + (rand() % 900000);
    snprintf(buf, len, "%06d", code);
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", ts, code) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup_doors(struct gpiod_line *a, struct gpiod_line *b)
{
    if (a) gpiod_line_set_value(a, 0);
    if (b) gpiod_line_set_value(b, 0);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a = NULL;
    struct gpiod_line *door_b = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto out;
    }

    door_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto out;
    }

    door_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto out;
    }

    if (gpiod_line_request_output(door_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(door_a)");
        goto out;
    }

    if (gpiod_line_request_output(door_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(door_b)");
        goto out;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        char code[CODE_LENGTH + 1];
        if (generate_code(code, sizeof(code)) != 0) {
            fprintf(stderr, "Failed to generate code.\n");
            break;
        }

        printf("Enter the code: ");
        fflush(stdout);

        char input[32];
        if (!fgets(input, sizeof(input), stdin)) {
            if (feof(stdin)) {
                fprintf(stderr, "End of input.\n");
                break;
            }
            perror("fgets()");
            break;
        }

        input[strcspn(input, "\r\n")] = '\0';

        char *endptr = NULL;
        errno = 0;
        strtol(input, &endptr, 10);
        if (errno != 0 || *endptr != '\0' || endptr == input) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit code.\n");
            while (fgetc(stdin) != '\n') { /* drain */ }
            continue;
        }

        if (strcmp(input, code) == 0) {
            printf("Access granted. Unlocking doors for %d seconds...\n",
                   UNLOCK_DURATION);

            if (gpiod_line_set_value(door_a, 1) < 0) {
                perror("gpiod_line_set_value(door_a, HIGH)");
                break;
            }
            if (gpiod_line_set_value(door_b, 1) < 0) {
                perror("gpiod_line_set_value(door_b, HIGH)");
                gpiod_line_set_value(door_a, 0);
                break;
            }

            /*
             * Sleep in 100 ms chunks so we can respond to signals
             * promptly.
             */
            for (int i = 0; i < UNLOCK_DURATION * 10 && g_running; i++)
                usleep(100000);

            if (gpiod_line_set_value(door_a, 0) < 0)
                perror("gpiod_line_set_value(door_a, LOW)");
            if (gpiod_line_set_value(door_b, 0) < 0)
                perror("gpiod_line_set_value(door_b, LOW)");

            if (log_access(code) != 0)
                fprintf(stderr, "Warning: failed to log access.\n");
        } else {
            printf("Access denied.\n");
        }
    }

    rc = EXIT_SUCCESS;

out:
    cleanup_doors(door_a, door_b);
    if (door_a) gpiod_line_release(door_a);
    if (door_b) gpiod_line_release(door_b);
    if (chip)   gpiod_chip_close(chip);
    return rc;
}

