/*
 * Raspberry Pi 4 Model B – MPR121 Capacitive Touch Theremin
 *
 * Hardware:
 *   - MPR121 on I2C bus 1, address 0x5C
 *   - PWM output on GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lm -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define MPR121_ADDR             0x5C
#define I2C_BUS                 1
#define PWM_PIN                 18          /* BCM 18 */
#define PWM_RANGE               1000
#define PWM_FREQ                1000        /* 1 kHz carrier */
#define TCP_PORT                12345
#define LOG_FILE                "frequency_log.txt"
#define SHARED_SECRET           "MySecretKey"
#define TCP_BUF_SIZE            512
#define SAMPLE_PERIOD_US        20000       /* 20 ms */
#define PLAYBACK_DURATION_S      5

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L    0x00
#define MPR121_TOUCHSTATUS_H    0x01
#define MPR121_ELECONFIG        0x5E
#define MPR121_SOFTRESET        0x80
#define MPR121_MHDR             0x2B
#define MPR121_NHDR             0x2C
#define MPR121_NCLR             0x2D
#define MPR121_FDLR             0x2E
#define MPR121_MHDF             0x2F
#define MPR121_NHDF             0x30
#define MPR121_NCLF             0x31
#define MPR121_FDLF             0x32
#define MPR121_NHDT             0x33
#define MPR121_NCLT             0x34
#define MPR121_FDLT             0x35
#define MPR121_E0TTH            0x41
#define MPR121_E0RTH            0x42
#define MPR121_DEBOUNCE         0x5B
#define MPR121_CONFIG1          0x5C
#define MPR121_CONFIG2          0x5D
#define MPR121_ECR              0x5E

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_server_fd  = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MPR121 helpers                                                      */
/* ------------------------------------------------------------------ */
static int mpr121_write(uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(g_i2c_handle, reg, val) < 0) {
        fprintf(stderr, "[MPR121] write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
