        g_server_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] init failed\n");
        return EXIT_FAILURE;
    }

    /* PWM */
    if (pwm_init() < 0) {
