    if (mpr121_init() < 0) {
        fprintf(stderr, "[MPR121] init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* TCP */
    g_server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (g_server_fd < 0) {
        fprintf(stderr, "[TCP] socket failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(g_server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "[TCP] setsockopt failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port        = htons(TCP_PORT);

    if (bind(g_server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "[TCP] bind failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(g_server_fd, 3) < 0) {
        fprintf(stderr, "[TCP] listen failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[TCP] listening on port %d\n", TCP_PORT);

