    while (g_running) {
        int client_fd = accept(g_server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "[TCP] accept failed: %s\n", strerror(errno));
            break;
        }

        printf("[TCP] client connected\n");

        if (authenticate_client(client_fd)) {
            printf("[TCP] playing theremin for %d s\n", PLAYBACK_DURATION_S);
            play_theremin();
        }

        close(client_fd);
    }

    cleanup();
    return EXIT_SUCCESS;
}

