/*
 * LSM303DLHC Magnetometer Z-axis PWM LED controller for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - LSM303DLHC magnetometer on I2C bus 1 (physical SDA1/SCL1),
 *     I2C address 0x1D (SA0 tied to GND).
 *   - LED on GPIO17 (BCM), driven via hardware PWM channel 0.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm303_led lsm303_led.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
