#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- LSM303DLHC magnetometer constants ---- */
#define LSM303_ADDR        0x1D          /* SA0 tied to GND */
#define LSM303_CTRL_REG1_M 0x20
#define LSM303_CTRL_REG2_M 0x21
#define LSM303_CTRL_REG3_M 0x22
#define LSM303_CTRL_REG4_M 0x23
#define LSM303_CTRL_REG5_M 0x24
#define LSM303_OUT_X_L_M   0x28          /* X low byte, auto-increment */
#define LSM303_OUT_X_H_M   0x29
#define LSM303_OUT_Z_L_M   0x2A
#define LSM303_OUT_Z_H_M   0x2B
#define LSM303_OUT_Y_L_M   0x2C
#define LSM303_OUT_Y_H_M   0x2D

#define I2C_BUS            "/dev/i2c-1"
#define GPIO_LED           17            /* BCM 17 */
#define PWM_FREQ_HZ        1000          /* 1 kHz */
#define PWM_RANGE          1000          /* duty 0..1000 */
#define SAMPLE_PERIOD_US   100000        /* 100 ms */
#define MAX_CONSECUTIVE_ERRORS 10

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s ERROR: %s (errno=%d: %s)\n",
                ts, msg, errno, strerror(errno));
        fflush(g_log_fp);
    }
    fprintf(stderr, "%s ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an LSM303 register. Returns 0 on success, -1 on error. */
static int lsm303_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        log_error("I2C write to LSM303 register failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at `reg` into buf. Returns 0 on success, -1 on error. */
static int lsm303_read_block(int fd, uint8_t reg, uint8_t *buf, size_t n)
{
    if (write(fd, &reg, 1) != 1) {
        log_error("I2C write (reg select) to LSM303 failed");
        return -1;
    }
    ssize_t total = 0;
    while ((size_t)total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            log_error("I2C read from LSM303 failed");
            return -1;
        }
        if (r == 0) {
            log_error("I2C read from LSM303 returned 0 bytes (sensor absent?)");
            return -1;
        }
        total += r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the magnetometer: normal mode, 80 Hz ODR, medium gain. */
static int lsm303_init(int fd)
{
    /* CTRL_REG1_M: MD=00 (normal), ODR=100 (80 Hz) -> 0x10 */
    if (lsm303_write_reg(fd, LSM303_CTRL_REG1_M, 0x10) != 0) return -1;
    /* CTRL_REG2_M: FS=00 (medium gain) -> 0x00 */
    if (lsm303_write_reg(fd, LSM303_CTRL_REG2_M, 0x00) != 0) return -1;
    /* CTRL_REG3_M: MD=00 (normal), LPF=0, SIM=0 -> 0x00 */
    if (lsm303_write_reg(fd, LSM303_CTRL_REG3_M, 0x00) != 0) return -1;
    /* CTRL_REG4_M: FS=00 (medium), ST=00 (XYZ enabled) -> 0x00 */
    if (lsm303_write_reg(fd, LSM303_CTRL_REG4_M, 0x00) != 0) return -1;
    /* CTRL_REG5_M: ZOM=00 (normal), ZLP=00 (medium) -> 0x00 */
    if (lsm303_write_reg(fd, LSM303_CTRL_REG5_M, 0x00) != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X, Y, Z magnetometer data (2 bytes each, little-endian). */
static int lsm303_read_mag(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (lsm303_read_block(fd, LSM303_OUT_X_L_M, raw, 6) != 0)
        return -1;

    *x = (int16_t)((raw[1] << 8) | raw[0]);
    *y = (int16_t)((raw[3] << 8) | raw[2]);
    *z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map the Z-axis magnitude to a PWM duty cycle (0..PWM_RANGE). */
static int mag_to_duty(int16_t z)
{
    const int32_t abs_z = (z < 0) ? -(int32_t)z : (int32_t)z;
    /* Clamp to [0, PWM_RANGE] so the LED is never off. */
    if (abs_z < 0) abs_z = 0;
    if (abs_z > PWM_RANGE) abs_z = PWM_RANGE;
    return (int)abs_z;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put magnetometer into power-down mode. */
        if (g_i2c_fd >= 0)
            lsm303_write_reg(g_i2c_fd, LSM303_CTRL_REG1_M, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Stop PWM and release pigpio. */
    gpioPWM(GPIO_LED, 0);
    gpioTerminate();

    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("lsm303_led.log", "a");
    if (!g_log_fp) {
        perror("fopen(lsm303_led.log)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO for hardware PWM ---- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        log_error("gpioSetMode(GPIO_LED) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_LED, PWM_FREQ_HZ) < 0) {
        log_error("gpioSetPWMfrequency failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_LED, PWM_RANGE) != 0) {
        log_error("gpioSetPWMrange failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(GPIO_LED, 0) != 0) {
        log_error("gpioPWM(init) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("open(" I2C_BUS ")");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        log_error("ioctl(I2C_SLAVE)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize magnetometer ---- */
    if (lsm303_init(g_i2c_fd) != 0) {
        log_error("LSM303DLHC initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC LED control running. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t x, y, z;

        if (lsm303_read_mag(g_i2c_fd, &x, &y, &z) != 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("Too many consecutive I2C errors; aborting.");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        int duty = mag_to_duty(z);
        if (gpioPWM(GPIO_LED, duty) != 0) {
            log_error("gpioPWM set failed");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

