        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            log_error("I2C read from LSM303 failed");
            return -1;
        }
        if (r == 0) {
            log_error("I2C read from LSM303 returned 0 bytes (sensor absent?)");
            return -1;
        }
        total += r;
