/*
 * HMC5883L magnetometer reader with running-average hard-iron calibration.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * Address: 0x1E (HMC5883L default, ADDR pin tied to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hmc5883l_cal hmc5883l_cal.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- HMC5883L register map ---- */
#define HMC5883L_ADDR          0x1E
#define REG_CONFIG_A           0x00
#define REG_CONFIG_B           0x01
#define REG_MODE               0x02
#define REG_DATA_X_MSB         0x03
#define REG_DATA_X_LSB         0x04
#define REG_DATA_Z_MSB         0x05
#define REG_DATA_Z_LSB         0x06
#define REG_DATA_Y_MSB         0x07
#define REG_DATA_Y_LSB         0x08
#define REG_STATUS             0x09
#define REG_ID_A               0x0A
#define REG_ID_B               0x0B
#define REG_ID_C               0x0C

/* ---- Configuration values ---- */
#define CONFIG_A_8AVG_15HZ     0x70   /* 8-average, 15 Hz output rate */
#define CONFIG_B_1090GAUSS     0x20   /* 1090 gauss gain */
#define MODE_CONTINUOUS        0x00   /* continuous measurement mode */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Signal handler ---- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_be(int fd, uint8_t reg, int16_t *out)
{
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, reg, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &lsb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* ---- Self-test ---- */
static int self_test(int fd)
{
    uint8_t id[3];
    if (i2c_read_reg8(fd, REG_ID_A, &id[0]) < 0) return -1;
    if (i2c_read_reg8(fd, REG_ID_B, &id[1]) < 0) return -1;
    if (i2c_read_reg8(fd, REG_ID_C, &id[2]) < 0) return -1;
    if (id[0] != 'H' || id[1] != '4' || id[2] != '3') {
        fprintf(stderr, "Self-test failed: ID = {0x%02X, 0x%02X, 0x%02X}\n",
                id[0], id[1], id[2]);
        return -1;
    }
    return 0;
}

/* ---- Calibration ---- */
typedef struct {
    double x, y, z;
} offset_t;

static offset_t calibrate(int fd, int n_samples)
{
    offset_t sum = {0, 0, 0};
    offset_t avg = {0, 0, 0};
    int ok = 0;

    printf("Calibrating %d samples...\n", n_samples);
    for (int i = 0; i < n_samples && g_running; i++) {
        int16_t x, y, z;
        if (i2c_read_reg16_be(fd, REG_DATA_X_MSB, &x) < 0 ||
            i2c_read_reg16_be(fd, REG_DATA_Y_MSB, &y) < 0 ||
            i2c_read_reg16_be(fd, REG_DATA_Z_MSB, &z) < 0) {
            fprintf(stderr, "Calibration read error at sample %d\n", i);
            continue;
        }
        sum.x += x; sum.y += y; sum.z += z;
        ok++;
        if (i < n_samples - 1) usleep(10000); /* 10 ms between samples */
    }

    if (ok > 0) {
        avg.x = sum.x / ok;
        avg.y = sum.y / ok;
        avg.z = sum.z / ok;
    }
    printf("Calibration complete: X=%.2f Y=%.2f Z=%.2f\n",
           avg.x, avg.y, avg.z);
    return avg;
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Self-test */
    if (self_test(g_i2c_fd) < 0) {
        fprintf(stderr, "HMC5883L not detected or wrong device.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure magnetometer */
    if (i2c_write_reg8(g_i2c_fd, REG_CONFIG_A, CONFIG_A_8AVG_15HZ) < 0 ||
        i2c_write_reg8(g_i2c_fd, REG_CONFIG_B, CONFIG_B_1090GAUSS) < 0 ||
        i2c_write_reg8(g_i2c_fd, REG_MODE, MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Calibrate */
    offset_t offsets = calibrate(g_i2c_fd, 100);

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;
        if (i2c_read_reg16_be(g_i2c_fd, REG_DATA_X_MSB, &x) < 0 ||
            i2c_read_reg16_be(g_i2c_fd, REG_DATA_Y_MSB, &y) < 0 ||
            i2c_read_reg16_be(g_i2c_fd, REG_DATA_Z_MSB, &z) < 0) {
            fprintf(stderr, "Read error in main loop\n");
            usleep(500000);
            continue;
        }

        double x_corr = x - offsets.x;
        double y_corr = y - offsets.y;
        double z_corr = z - offsets.z;

        printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_corr, y_corr, z_corr);
        usleep(500000); /* 500 ms */
    }

    /* Cleanup */
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

