static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_int1 = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lsm303d(int fd)
{
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1_A: 50 Hz ODR, all axes enabled, normal mode */
    if (i2c_write_reg(fd, CTRL_REG1_A, 0x57) < 0)
        return -1;

    /* CTRL_REG4_A: high-resolution mode, ±2 g range */
    if (i2c_write_reg(fd, CTRL_REG4_A, 0x08) < 0)
        return -1;

    /* INT1_CTRL: enable INT1, all axes, rising-edge */
    if (i2c_write_reg(fd, INT1_CTRL, 0x0F) < 0)
        return -1;

    /* INT1_THS_A: threshold = |INT1_THRESHOLD_MG| / 16 / sensitivity */
    int16_t ths = (int16_t)(INT1_THRESHOLD_MG / (16.0f * ACCEL_SENSITIVITY));
    if (i2c_write_reg(fd, INT1_THS_A, (uint8_t)(ths & 0xFF)) < 0)
        return -1;

    /* INT1_DURATION: zero duration => immediate trigger */
    if (i2c_write_reg(fd, INT1_DURATION, INT1_DURATION_VAL) < 0)
        return -1;

    return 0;
}

static int read_accel(int fd, AccelData *out)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUT_X_L_A | 0x80, raw, 6) < 0)
        return -1;

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    out->x = (float)x * ACCEL_SENSITIVITY;
    out->y = (float)y * ACCEL_SENSITIVITY;
    out->z = (float)z * ACCEL_SENSITIVITY;
    return 0;
}

static void buffer_add(CircularBuffer *buf, AccelData d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_dump(const CircularBuffer *buf)
{
    int start = (buf->count < BUFFER_SIZE)
                ? 0
                : (buf->head - buf->count + BUFFER_SIZE) % BUFFER_SIZE;
    int n = buf->count;
    if (n > BUFFER_SIZE) n = BUFFER_SIZE;

    printf("\n--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%3d] X: %+.2f mg  Y: %+.2f mg  Z: %+.2f mg\n",
               i, buf->data[idx].x, buf->data[idx].y, buf->data[idx].z);
    }
    printf("------------------------\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Initialize LSM303D ---- */
    if (init_lsm303d(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request INT1 line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    g_int1 = gpiod_chip_get_line(g_chip, INT1_LINE);
    if (!g_int1) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                INT1_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(g_int1, "lsm303d_int1") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events failed: %s\n",
                strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    CircularBuffer accel_buf = {0};
    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);

    while (g_running) {
        AccelData sample;
        if (read_accel(g_i2c_fd, &sample) == 0) {
            buffer_add(&accel_buf, sample);
        } else {
            fprintf(stderr, "Warning: I2C read error, sample skipped.\n");
        }

        /* ---- Interrupt event polling ---- */
        struct timespec ts = { 0, 1000000 };   /* 1 ms poll */
        int ev = gpiod_line_event_wait(g_int1, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n",
                    strerror(errno));
            break;
        }
        if (ev > 0) {
            struct gpiod_line_event evt;
            if (gpiod_line_event_read(g_int1, &evt) == 0) {
                if (evt.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    buffer_dump(&accel_buf);
                }
            }
        }

        /* ---- Sample scheduling ---- */
        next.tv_nsec += SAMPLE_PERIOD_US * 1000;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_nsec -= 1000000000L;
            next.tv_sec++;
        }
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (next.tv_sec > now.tv_sec ||
            (next.tv_sec == now.tv_sec && next.tv_nsec > now.tv_nsec)) {
            struct timespec delta = {
                next.tv_sec - now.tv_sec,
                next.tv_nsec - now.tv_nsec
            };
            nanosleep(&delta, NULL);
        } else {
            now = next;
        }
    }

    /* ---- Graceful shutdown ---- */
    /* Disable accelerometer: normal mode, axes off */
    if (g_i2c_fd >= 0) {
        (void)i2c_write_reg(g_i2c_fd, CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
    }
    if (g_int1) gpiod_line_release(g_int1);
    if (g_chip) gpiod_chip_close(g_chip);

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

