/*
 * Dual 12 V DC solenoid driver for Raspberry Pi 3 Model B+
 * Uses pigpio for BCM GPIO access.
 *
 * Wiring:
 *   Solenoid 1 (A): GPIO17 -> TIP120 input -> Solenoid 1 (A)
 *   Solenoid 1 (K): GPIO17 -> TIP120 emitter -> GND
 *   Solenoid 1 (C): TIP120 collector -> Solenoid 1 (C)
 *   Solenoid 1 (D): TIP120 collector -> flyback diode -> GND
 *   Solenoid 2 (A): GPIO27 -> TIP120 input -> Solenoid 2 (A)
 *   Solenoid 2 (K): GPIO27 -> TIP120 emitter -> GND
 *   Solenoid 2 (C): TIP120 collector -> Solenoid 2 (C)
 *   Solenoid 2 (D): TIP120 collector -> flyback diode -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o solenoid_driver solenoid_driver.c -lpigpio -lrt
 * Run:    sudo ./solenoid_driver
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define SWITCH_DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1) {
        /* Retry on EINTR; exit loop if signal received */
        if (!g_running)
            return;
    }
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure both pins as outputs */
    if (safe_set_mode(SOLENOID_1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure both solenoids are OFF at startup */
    if (safe_write(SOLENOID_1_PIN, 0) != 0 ||
        safe_write(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Solenoid driver started. Press Ctrl+C to exit.\n");

    bool active_solenoid = false;  /* true = solenoid 2, false = solenoid 1 */

    while (g_running) {
        active_solenoid = !active_solenoid;

        if (active_solenoid) {
            /* De-energize the other solenoid first for safety */
            if (safe_write(SOLENOID_1_PIN, 0) != 0)
                break;
            if (safe_write(SOLENOID_2_PIN, 1) != 0)
                break;
            printf("Solenoid 2 energized\n");
        } else {
            if (safe_write(SOLENOID_2_PIN, 0) != 0)
                break;
            if (safe_write(SOLENOID_1_PIN, 1) != 0)
                break;
            printf("Solenoid 1 energized\n");
        }

        sleep_ms(SWITCH_DELAY_MS);
    }

    /* Clean shutdown: release both solenoids */
    safe_write(SOLENOID_1_PIN, 0);
    safe_write(SOLENOID_2_PIN, 0);
    gpioTerminate();

    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

