/*
 * Dual-factor door-lock authentication using two UART ports and two
 * active-HIGH relay modules driving 12 V electromagnetic door locks.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern GPIO API)
 *
 * Wiring:
 *   GPIO17 -> Relay 1 (first lock)
 *   GPIO27 -> Relay 2 (second lock)
 *   /dev/serial0 (GPIO14/15) -> first 6-digit code reader
 *   /dev/serial1  -> second 6-digit code reader
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <stdbool.h>
#include <stdint.h>
#include <pigpio.h>

/* ---- Pin / port definitions (BCM numbering) ---- */
#define RELAY1_PIN      17
#define RELAY2_PIN      27
#define UART1_DEVICE    "/dev/serial0"
#define UART2_DEVICE    "/dev/serial1"
#define BAUD_RATE       9600
#define EXPECTED_CODE   "123456"
#define LOCK_HOLD_US    2000000   /* 2 s */
#define READ_TIMEOUT_US 5000000   /* 5 s */
#define POLL_DELAY_US   10000     /* 10 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_uart1_handle = -1;
static int g_uart2_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Constant-time string comparison (no early exit) ---- */
static bool codes_match(const char *a, const char *b)
{
    if (a == NULL || b == NULL)
        return false;

    uint8_t eq = 1;
    for (size_t i = 0; a[i] != '\0' || b[i] != '\0'; ++i) {
        eq &= (uint8_t)(a[i] == b[i]);
    }
    return eq != 0;
}

/* ---- Read one 6-digit code from a UART port via pigpio ---- */
static bool read_code(int handle, char *code, size_t code_len)
{
    if (code == NULL || code_len < 7)
        return false;

    size_t idx = 0;
    code[0] = '\0';

    while (g_running && idx < code_len - 1) {
        int c = serReadByte(handle);
        if (c < 0) {
            /* pigpio error code: -1 = timeout, -2 = closed, -3 = EOF */
            if (c == -1)
                return false; /* timeout, no code available */
            fprintf(stderr, "UART read error (handle %d): %d\n", handle, c);
            return false;
        }

        if (c >= '0' && c <= '9') {
            code[idx++] = (char)c;
            code[idx]   = '\0';
        } else if (c == '\r' || c == '\n') {
            /* ignore line-ending whitespace */
        } else {
            /* non-digit: reset buffer */
            idx = 0;
            code[0] = '\0';
        }

        if (idx == code_len - 1) {
            code[idx] = '\0';
            return true;
        }
    }
    return false;
}

/* ---- Open a UART port via pigpio ---- */
static int open_uart(const char *device, int baud)
{
    int handle = serOpen(device, baud, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open %s: %d\n", device, handle);
        return -1;
    }
    return handle;
}

/* ---- Drive a relay GPIO HIGH for LOCK_HOLD_US, then LOW ---- */
static void activate_lock(int pin)
{
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", pin);
        return;
    }
    gpioDelay(LOCK_HOLD_US);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", pin);
    }
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    /* Ensure both locks are locked (relay LOW) */
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);

    if (g_uart1_handle >= 0) {
        serClose(g_uart1_handle);
        g_uart1_handle = -1;
    }
    if (g_uart2_handle >= 0) {
        serClose(g_uart2_handle);
        g_uart2_handle = -1;
    }

    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pins as outputs and drive both LOW (locked) */
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);

    /* Open UART ports */
    g_uart1_handle = open_uart(UART1_DEVICE, BAUD_RATE);
    if (g_uart1_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    g_uart2_handle = open_uart(UART2_DEVICE, BAUD_RATE);
    if (g_uart2_handle < 0) {
        serClose(g_uart1_handle);
        g_uart1_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    char code1[7] = {0};
    char code2[7] = {0};
    bool got1 = false;
    bool got2 = false;

    printf("Door lock system started. Waiting for codes...\n");
    fflush(stdout);

    while (g_running) {
        /* Read from UART1 */
        if (!got1) {
            if (read_code(g_uart1_handle, code1, sizeof(code1))) {
                got1 = true;
                printf("Code 1 received: %s\n", code1);
                fflush(stdout);
            }
        }

        /* Read from UART2 */
        if (!got2) {
            if (read_code(g_uart2_handle, code2, sizeof(code2))) {
                got2 = true;
                printf("Code 2 received: %s\n", code2);
                fflush(stdout);
            }
        }

        /* Both codes received: compare */
        if (got1 && got2) {
            if (codes_match(code1, code2)) {
                if (codes_match(code1, EXPECTED_CODE)) {
                    printf("Codes match expected value. Unlocking doors...\n");
                    fflush(stdout);
                    activate_lock(RELAY1_PIN);
                    activate_lock(RELAY2_PIN);
                    printf("Doors locked.\n");
                    fflush(stdout);
                } else {
                    fprintf(stderr, "Codes do not match expected value.\n");
                }
            } else {
                fprintf(stderr, "Codes do not match.\n");
            }
            /* Reset for next pair */
            got1 = false;
            got2 = false;
            code1[0] = '\0';
            code2[0] = '\0';
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

