/*
 * PIR-triggered door strike controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor  -> GPIO4  (physical pin 7,  active-HIGH)
 *   - Door strike relay    -> GPIO17 (physical pin 11, active-HIGH)
 *
 * Behavior:
 *   - Polls the PIR every 50 ms.
 *   - On a rising edge (HIGH) logs a syslog event and energizes the relay
 *     for 1 s, then de-energizes the relay.
 *   - If the PIR stays HIGH for > 10 s the program enters a failsafe
 *     state: the relay is de-energized, a LOG_WARNING is logged, and a
 *     shutdown event is logged.
 *   - SIGINT / SIGTERM trigger a clean shutdown: relay is driven LOW,
 *     GPIO lines are released, the chip is closed, and the log is closed.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_strike pir_strike.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_PIN          4
#define STRIKE_PIN       17
#define POLL_INTERVAL_US 50000   /* 50 ms  */
#define STRIKE_DURATION  1000000 /* 1 s    */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

static void log_errno(const char *msg)
{
    syslog(LOG_ERR, "%s: %s", msg, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup_relay(struct gpiod_line *relay_line)
{
    if (relay_line) {
        if (gpiod_line_set_value(relay_line, 0) < 0)
            log_errno("Failed to de-energize relay during cleanup");
        gpiod_line_release(relay_line);
    }
}

static void cleanup_all(struct gpiod_chip *chip,
                        struct gpiod_line *pir_line,
                        struct gpiod_line *relay_line)
{
    cleanup_relay(relay_line);
    if (pir_line)
        gpiod_line_release(pir_line);
    if (chip)
        gpiod_chip_close(chip);
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_errno("Failed to install signal handlers");
        return EXIT_FAILURE;
    }

    /* ---- Open syslog ---- */
    openlog("pir_strike", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_errno("Failed to open gpiochip4");
        goto out;
    }

    /* ---- Get PIR line ---- */
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_errno("Failed to get PIR line (GPIO4)");
        goto out;
    }

    if (gpiod_line_request_input(pir_line, "pir_strike") < 0) {
        log_errno("Failed to request PIR line as input");
        goto out;
    }

    /* ---- Get relay line ---- */
    relay_line = gpiod_chip_get_line(chip, STRIKE_PIN);
    if (!relay_line) {
        log_errno("Failed to get relay line (GPIO17)");
        goto out;
    }

    if (gpiod_line_request_output(relay_line, "pir_strike", 0) < 0) {
        log_errno("Failed to request relay line as output");
        goto out;
    }

    log_event(LOG_INFO, "PIR-strike controller started");

    /* ---- Main loop ---- */
    int last_pir = 0;
    time_t strike_start = 0;
    int failsafe_active = 0;

    while (g_running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            log_errno("Failed to read PIR sensor");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Rising edge: motion detected */
        if (pir_val == 1 && last_pir == 0) {
            log_event(LOG_INFO, "Motion detected - activating relay");

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_errno("Failed to energize relay");
            } else {
                log_event(LOG_INFO, "Relay energized");
            }

            strike_start = time(NULL);
            failsafe_active = 0;
        }

        /* Relay held for > 1 s: de-energize */
        if (pir_val == 1 && strike_start != 0 &&
            (time(NULL) - strike_start) >= STRIKE_DURATION / 1000000) {
            if (gpiod_line_set_value(relay_line, 0) < 0)
                log_errno("Failed to de-energize relay");
            else
                log_event(LOG_INFO, "Relay de-energized");
            strike_start = 0;
        }

        /* Failsafe: PIR stays HIGH for > 10 s */
        if (pir_val == 1 && strike_start != 0 &&
            (time(NULL) - strike_start) >= FAILSAFE_TIMEOUT) {
            if (!failsafe_active) {
                log_event(LOG_WARNING,
                          "PIR failsafe triggered: PIR HIGH for > 10 s");
                if (gpiod_line_set_value(relay_line, 0) < 0)
                    log_errno("Failed to de-energize relay in failsafe");
                else
                    log_event(LOG_INFO, "Relay de-energized in failsafe");
                strike_start = 0;
                failsafe_active = 1;
            }
        }

        last_pir = pir_val;
        usleep(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down");
    ret = EXIT_SUCCESS;

out:
    cleanup_all(chip, pir_line, relay_line);
    return ret;
}

