code:
/*
 * Irrigation system for Raspberry Pi 4 Model B
 * Relays: 4-channel active-LOW relay module
 *   Relay 1 -> GPIO4  (BCM)
 *   Relay 2 -> GPIO17 (BCM)
 *   Relay 3 -> GPIO27 (BCM)
 *   Relay 4 -> GPIO22 (BCM)
 *
 * Behavior:
 *   - All relays start OFF (HIGH).
 *   - A 60-second timer fires every 60 s.
 *   - On each timer tick:
 *       1. Relay 1 ON for 5 min (300 s), OFF for 1 min (60 s) -> Relay 2
 *       2. Relay 2 ON for 5 min, OFF for 1 min -> Relay 3
 *       3. Relay 3 ON for 5 min, OFF for 1 min -> Relay 4
 *       4. Relay 4 ON for 5 min, OFF for 1 min -> Relay 1
 *   - SIGINT / SIGTERM: deactivate all relays (HIGH), release GPIO,
 *     close syslog, exit cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lpigpio -lrt
 * Run:    sudo ./irrigation
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

#define RELAY_ACTIVE_TIME_SEC  300   /* 5 minutes  */
#define RELAY_PAUSE_TIME_SEC   60    /* 1 minute   */
#define TIMER_INTERVAL_SEC     60    /* 60 seconds */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Relay state machine ---- */
typedef enum {
    RELAY_STATE_OFF,
    RELAY_STATE_ON,
    RELAY_STATE_PAUSED
} relay_state_t;

typedef struct {
    int           pin;
    relay_state_t state;
    time_t        start_time;
} relay_t;

static relay_t g_relays[4] = {
    {RELAY_1_PIN, RELAY_STATE_OFF, 0},
    {RELAY_2_PIN, RELAY_STATE_OFF, 0},
    {RELAY_3_PIN, RELAY_STATE_OFF, 0},
    {RELAY_4_PIN, RELAY_STATE_OFF, 0}
};

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void timer_callback(void *userdata);
static void log_event(const char *msg);
static void log_relay_state(int pin, relay_state_t state);
static void cleanup(void);

/* ---- Helpers ---- */
static void log_event(const char *msg)
{
    time_t now = time(NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(LOG_INFO, "%s %s", ts, msg);
}

static void log_relay_state(int pin, relay_state_t state)
{
    char msg[128];
    const char *state_str;
    switch (state) {
        case RELAY_STATE_OFF:   state_str = "OFF";   break;
        case RELAY_STATE_ON:    state_str = "ON";    break;
        case RELAY_STATE_PAUSED:state_str = "PAUSED";break;
        default:                state_str = "UNKNOWN";break;
    }
    snprintf(msg, sizeof(msg), "Relay GPIO%d -> %s", pin, state_str);
    log_event(msg);
}

/* ---- Relay control ---- */
static void relay_set(relay_t *r, relay_state_t state)
{
    r->state      = state;
    r->start_time = time(NULL);

