    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC * 1000,
                           timer_callback, NULL) < 0) {
        log_event("FATAL: gpioSetTimerFuncEx failed");
        cleanup();
        return EXIT_FAILURE;
    }

