/*
 * Irrigation system for Raspberry Pi 4 Model B
 * Relays: 4-channel active-LOW relay module
 *   Relay 1 -> GPIO4  (BCM)
 *   Relay 2 -> GPIO17 (BCM)
 *   Relay 3 -> GPIO27 (BCM)
 *   Relay 4 -> GPIO22 (BCM)
 *
 * Behavior:
 *   - All relays start OFF (HIGH).
 *   - A 60-second timer fires every 60 s.
 *   - On each timer tick:
 *       1. Relay 1 ON for 5 min (300 s), OFF for 1 min (60 s) -> Relay 2
 *       2. Relay 2 ON for 5 min, OFF for 1 min -> Relay 3
 *       3. Relay 3 ON for 5 min, OFF for 1 min -> Relay 4
 *       4. Relay 4 ON for 5 min, OFF for 1 min -> Relay 1
 *   - SIGINT / SIGTERM: deactivate all relays (HIGH), release GPIO,
 *     close syslog, exit cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lpigpio -lrt
 * Run:    sudo ./irrigation
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Configuration ---- */
