#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

#define RELAY_ACTIVE_TIME_SEC  300   /* 5 minutes  */
#define RELAY_PAUSE_TIME_SEC   60    /* 1 minute   */
#define TIMER_INTERVAL_SEC     60    /* 60 seconds */

