    int           pin;
    relay_state_t state;
    time_t        start_time;
} relay_t;

static relay_t g_relays[4] = {
    {RELAY_1_PIN, RELAY_STATE_OFF, 0},
    {RELAY_2_PIN, RELAY_STATE_OFF, 0},
    {RELAY_3_PIN, RELAY_STATE_OFF, 0},
    {RELAY_4_PIN, RELAY_STATE_OFF, 0}
};

