    const char *state_str;
    switch (state) {
        case RELAY_STATE_OFF:   state_str = "OFF";   break;
        case RELAY_STATE_ON:    state_str = "ON";    break;
        case RELAY_STATE_PAUSED:state_str = "PAUSED";break;
        default:                state_str = "UNKNOWN";break;
    }
