/*
 * MPU6050 Accelerometer Sampler for Raspberry Pi 4 Model B
 *
 * Reads acceleration data from an MPU6050 on /dev/i2c-1 at 100 Hz
 * and exposes the most recent sample via a driver-library-style
 * filesystem interface (/sys/kernel/mpu6050_accel/latest).
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6050_sampler mpu6050_sampler.c
 * Run:    sudo ./mpu6050_sampler   (needs write access to /dev/i2c-1)
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU6050 constants ------------------------------------------------ */
#define I2C_BUS          "/dev/i2c-1"
#define MPU6050_ADDR     0x68
#define REG_PWR_MGMT_1   0x6B
#define REG_ACCEL_XOUT_H 0x3B

#define SAMPLE_RATE_HZ   100
#define BUFFER_SIZE      1000   /* must be power of 2 for bit-friendly masking */

/* ---- Driver-library filesystem interface ------------------------------ */
#define DRIVER_DIR       "/sys/kernel/mpu6050_accel"
#define DRIVER_FILE      DRIVER_DIR "/latest"

/* ---- Data structures -------------------------------------------------- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

/* ---- Globals ---------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_drv_file = NULL;
static timer_t  g_timer_id = 0;
static bool     g_timer_armed = false;

/* Circular buffer */
static accel_sample_t *g_buf = NULL;
static int g_head = 0;   /* next write slot */

/* ---- Signal handling -------------------------------------------------- */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t total = 0;
    while ((size_t)total < n) {
        ssize_t r = read(fd, dst + total, n - (size_t)total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                    reg, strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read from reg 0x%02X: unexpected EOF\n", reg);
            return -1;
        }
        total += r;
    }
    return 0;
}

/* ---- MPU6050 setup ---------------------------------------------------- */
static int mpu6050_init(int fd)
{
    /* Wake the device: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_byte(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    /* Allow time for the oscillator to stabilize */
    struct timespec ts = { .tv_sec = 0, .tv_nsec = 100 * 1000 * 1000 };
    nanosleep(&ts, NULL);
    return 0;
}

static int mpu6050_read(int fd, accel_sample_t *out)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, REG_ACCEL_XOUT_H, raw, sizeof(raw)) < 0)
        return -1;

    out->x = (int16_t)((raw[0] << 8) | raw[1]);
    out->y = (int16_t)((raw[2] << 8) | raw[3]);
    out->z = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ---- Circular buffer -------------------------------------------------- */
static void buf_push(accel_sample_t s)
{
    g_buf[g_head] = s;
    g_head = (g_head + 1) & (BUFFER_SIZE - 1);
}

/* ---- Driver filesystem write ------------------------------------------ */
static int driver_write(const accel_sample_t *s)
{
    char line[128];
    int len = snprintf(line, sizeof(line), "%d,%d,%d\n",
                       (int)s->x, (int)s->y, (int)s->z);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    if (!g_drv_file) {
        g_drv_file = fopen(DRIVER_FILE, "w");
        if (!g_drv_file) {
            fprintf(stderr, "Cannot open %s: %s\n", DRIVER_FILE, strerror(errno));
            return -1;
        }
    }

    if (fputs(line, g_drv_file) == EOF) {
        fprintf(stderr, "fputs to %s failed: %s\n", DRIVER_FILE, strerror(errno));
        return -1;
    }
    if (fflush(g_drv_file) != 0) {
        fprintf(stderr, "fflush on %s failed: %s\n", DRIVER_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Timer signal handler --------------------------------------------- */
static void timer_handler(int sig, siginfo_t *si, void *uc)
{
    (void)sig; (void)si; (void)uc;
    accel_sample_t sample;
    if (g_i2c_fd >= 0 && mpu6050_read(g_i2c_fd, &sample) == 0) {
        buf_push(sample);
        driver_write(&sample);
    }
}

/* ---- Timer setup ------------------------------------------------------ */
static int timer_setup(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_flags   = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return -1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify      = SIGEV_SIGNAL;
    sev.sigev_signo       = SIGRTMIN;
    sev.sigev_value.sival_ptr = &g_timer_id;

    if (timer_create(CLOCK_MONOTONIC, &sev, &g_timer_id) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        return -1;
    }
    g_timer_armed = true;

    struct itimerspec its;
    its.it_interval.tv_sec      = 0;
    its.it_interval.tv_nsec     = 1000000000L / SAMPLE_RATE_HZ;
    its.it_value                = its.it_interval;

    if (timer_settime(g_timer_id, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---------------------------------------------------------- */
static void cleanup(void)
{
    if (g_timer_armed) {
        timer_delete(g_timer_id);
        g_timer_armed = false;
    }
    if (g_drv_file) {
        fclose(g_drv_file);
        g_drv_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_buf) {
        free(g_buf);
        g_buf = NULL;
    }
}

/* ---- Main ------------------------------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Allocate buffer */
    g_buf = calloc(BUFFER_SIZE, sizeof(accel_sample_t));
    if (!g_buf) {
        fprintf(stderr, "calloc failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Acquire MPU6050 */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a register read */
    uint8_t probe;
    if (i2c_read_burst(g_i2c_fd, REG_PWR_MGMT_1, &probe, 1) < 0) {
        fprintf(stderr, "MPU6050 not responding at 0x%02X\n", MPU6050_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Create and arm timer */
    if (timer_setup() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampling at %d Hz.  Press Ctrl-C to stop.\n", SAMPLE_RATE_HZ);

    /* Main loop: sleep until signal */
    while (g_running) {
        pause();
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

