                       (int)s->x, (int)s->y, (int)s->z);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    if (!g_drv_file) {
        g_drv_file = fopen(DRIVER_FILE, "w");
        if (!g_drv_file) {
            fprintf(stderr, "Cannot open %s: %s\n", DRIVER_FILE, strerror(errno));
            return -1;
        }
    }

    if (fputs(line, g_drv_file) == EOF) {
        fprintf(stderr, "fputs to %s failed: %s\n", DRIVER_FILE, strerror(errno));
        return -1;
    }
    if (fflush(g_drv_file) != 0) {
        fprintf(stderr, "fflush on %s failed: %s\n", DRIVER_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Timer signal handler --------------------------------------------- */
static void timer_handler(int sig, siginfo_t *si, void *uc)
{
    (void)sig; (void)si; (void)uc;
    accel_sample_t sample;
    if (g_i2c_fd >= 0 && mpu6050_read(g_i2c_fd, &sample) == 0) {
        buf_push(sample);
        driver_write(&sample);
    }
}

/* ---- Timer setup ------------------------------------------------------ */
static int timer_setup(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_flags   = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return -1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify      = SIGEV_SIGNAL;
    sev.sigev_signo       = SIGRTMIN;
    sev.sigev_value.sival_ptr = &g_timer_id;

    if (timer_create(CLOCK_MONOTONIC, &sev, &g_timer_id) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        return -1;
    }
    g_timer_armed = true;

    struct itimerspec its;
    its.it_interval.tv_sec      = 0;
    its.it_interval.tv_nsec     = 1000000000L / SAMPLE_RATE_HZ;
    its.it_value                = its.it_interval;

    if (timer_settime(g_timer_id, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---------------------------------------------------------- */
static void cleanup(void)
{
    if (g_timer_armed) {
        timer_delete(g_timer_id);
        g_timer_armed = false;
    }
    if (g_drv_file) {
        fclose(g_drv_file);
        g_drv_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_buf) {
        free(g_buf);
        g_buf = NULL;
    }
}

/* ---- Main ------------------------------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Allocate buffer */
    g_buf = calloc(BUFFER_SIZE, sizeof(accel_sample_t));
    if (!g_buf) {
        fprintf(stderr, "calloc failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Acquire MPU6050 */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a register read */
    uint8_t probe;
    if (i2c_read_burst(g_i2c_fd, REG_PWR_MGMT_1, &probe, 1) < 0) {
        fprintf(stderr, "MPU6050 not responding at 0x%02X\n", MPU6050_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Create and arm timer */
    if (timer_setup() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU6050 sampling at %d Hz.  Press Ctrl-C to stop.\n", SAMPLE_RATE_HZ);

    /* Main loop: sleep until signal */
    while (g_running) {
        pause();
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

