/*
 * toggle_relays.c — Raspberry Pi 3 Model B+
 *
 * Toggles four 5V relay modules on the GPIO bus with independent
 * prime-number-second intervals using pigpio.
 *
 * Relay 1 -> GPIO18 (BCM), Relay 2 -> GPIO23 (BCM),
 * Relay 3 -> GPIO24 (BCM), Relay 4 -> GPIO25 (BCM)
 *
 * Intervals: 2 s, 3 s, 5 s, 7 s
 *
 * Build:  gcc -O2 -Wall -Wextra -o toggle_relays toggle_relays.c -lpigpio -lrt
 * Run:    sudo ./toggle_relays
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int relay_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_relay_pins(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", relay_pins[i]);
            return -1;
        }
        if (gpioWrite(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite(0) failed for GPIO%d\n", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void turn_off_all_relays(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        (void)gpioWrite(relay_pins[i], 0);
    }
}

static void cleanup(void)
{
    turn_off_all_relays();
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_relay_pins() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec next_toggle_times[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (clock_gettime(CLOCK_MONOTONIC, &next_toggle_times[i]) != 0) {
            perror("clock_gettime");
            cleanup();
            return EXIT_FAILURE;
        }
        next_toggle_times[i].tv_sec += relay_intervals[i];
    }

    int relay_states[NUM_RELAYS] = {0, 0, 0, 0};

    while (g_running) {
        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            perror("clock_gettime");
            break;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (now.tv_sec >= next_toggle_times[i].tv_sec) {
                relay_states[i] = !relay_states[i];
                if (gpioWrite(relay_pins[i], relay_states[i]) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed for GPIO%d\n", relay_pins[i]);
                    g_running = 0;
                    break;
                }
                next_toggle_times[i].tv_sec += relay_intervals[i];
            }
        }

        if (g_running) {
            struct timespec sleep_ts = {0, 100000000}; /* 100 ms */
            nanosleep(&sleep_ts, NULL);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

