/*
 * MPU-6050 Gyroscope Angular Velocity Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    Hardware I2C1 (SDA=GPIO2, SCL=GPIO3)
 * Sensor: MPU-6050 (I2C address 0x68)
 *
 * Reads angular velocity data from the MPU-6050 over I2C and stores
 * it in a 100-sample in-memory circular buffer.  When the absolute
 * angular velocity magnitude exceeds 50.0 degrees/second, the user-
 * supplied callback is invoked.
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_monitor gyro_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants ------------------------------------------------ */
#define MPU6050_ADDR        0x68
#define MPU6050_BUS         "/dev/i2c-1"

#define REG_SMPLRT_DIV      0x19
#define REG_PWR_MGMT_1      0x6B
#define REG_GYRO_CONFIG     0x1B
#define REG_GYRO_XOUT_H     0x43

#define GYRO_FS_SEL_250DPS  0x00
#define GYRO_FS_SEL_500DPS  0x01
#define GYRO_FS_SEL_1000DPS 0x02
#define GYRO_FS_SEL_2000DPS 0x03

#define GYRO_SENSITIVITY_250DPS  131.0f   /* LSB per deg/s at ±250 dps */
#define GYRO_SENSITIVITY_500DPS  65.5f    /* LSB per deg/s at ±500 dps */
#define GYRO_SENSITIVITY_1000DPS 32.8f    /* LSB per deg/s at ±1000 dps */
#define GYRO_SENSITIVITY_2000DPS 16.4f    /* LSB per deg/s at ±2000 dps */

/* ---- Application constants --------------------------------------------- */
#define BUFFER_SIZE         100
#define ANGULAR_VELOCITY_THRESHOLD 50.0f  /* deg/s */
#define SAMPLE_PERIOD_MS    10
#define MAX_CONSECUTIVE_ERRORS 10

/* ---- Data structures --------------------------------------------------- */
typedef struct {
    float x, y, z;          /* deg/s */
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ----------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Prototypes -------------------------------------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg8(int fd, uint8_t reg, uint8_t value);
static int  i2c_read_reg8(int fd, uint8_t reg, uint8_t *value);
static int  i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len);
static int  mpu6050_init(int fd);
static int  mpu6050_read_gyro(int fd, gyro_data_t *out);
static void circular_buffer_add(circular_buffer_t *cb, gyro_data_t d);
static void callback(gyro_data_t gyro_data);

/* ---- Signal handler ---------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers --------------------------------------------- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): write failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X): write failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, value, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X): read failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_burst(0x%02X): write failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst(0x%02X): read failed: %s (read %zd of %zu bytes)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ---- MPU-6050 helpers --------------------------------------------------- */
static int mpu6050_init(int fd)
{
    /* Wake the device: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake MPU-6050 (PWR_MGMT_1)\n");
        return -1;
    }
    usleep(100000);  /* allow oscillator to stabilize */

    /* Set gyro full-scale range to ±250 dps (default) */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, GYRO_FS_SEL_250DPS) != 0) {
        fprintf(stderr, "Failed to configure GYRO_CONFIG\n");
        return -1;
    }

    /* Sample rate divider = 0 → 1 kHz / (1 + 0) = 1 kHz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x00) != 0) {
        fprintf(stderr, "Failed to configure SMPLRT_DIV\n");
        return -1;
    }

    return 0;
}

static int mpu6050_read_gyro(int fd, gyro_data_t *out)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, REG_GYRO_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /*
     * Read GYRO_CONFIG to determine the full-scale range.
     * Default at startup is ±250 dps, so we use the default
     * sensitivity value.
     */
    uint8_t fs_sel = GYRO_FS_SEL_250DPS;
    if (i2c_read_reg8(fd, REG_GYRO_CONFIG, &fs_sel) != 0)
        return -1;

    float sensitivity;
    switch (fs_sel & 0x03) {
        case GYRO_FS_SEL_250DPS:  sensitivity = GYRO_SENSITIVITY_250DPS; break;
        case GYRO_FS_SEL_500DPS:  sensitivity = GYRO_SENSITIVITY_500DPS;  break;
        case GYRO_FS_SEL_1000DPS: sensitivity = GYRO_SENSITIVITY_1000DPS; break;
        case GYRO_FS_SEL_2000DPS: sensitivity = GYRO_SENSITIVITY_2000DPS; break;
        default:
            fprintf(stderr, "Unexpected GYRO_CONFIG value 0x%02X\n", fs_sel);
            return -1;
    }

    out->x = (float)raw_x / sensitivity;
    out->y = (float)raw_y / sensitivity;
    out->z = (float)raw_z / sensitivity;
    return 0;
}

/* ---- Circular buffer --------------------------------------------------- */
static void circular_buffer_add(circular_buffer_t *cb, gyro_data_t d)
{
    cb->data[cb->head] = d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ---- Callback (user-supplied) ------------------------------------------ */
static void callback(gyro_data_t gyro_data)
{
    float magnitude = sqrtf(gyro_data.x * gyro_data.x +
                            gyro_data.y * gyro_data.y +
                            gyro_data.z * gyro_data.z);

    if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
        time_t now = time(NULL);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
        printf("[%s] Angular velocity exceeded threshold: "
               "X=%.2f Y=%.2f Z=%.2f deg/s (magnitude=%.2f deg/s)\n",
               ts, gyro_data.x, gyro_data.y, gyro_data.z, magnitude);
        fflush(stdout);
    }
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(MPU6050_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", MPU6050_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Probe: try reading the WHO_AM_I register (0x75) */
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(g_i2c_fd, 0x75, &who_am_i) != 0) {
        fprintf(stderr, "MPU-6050 not detected at 0x%02X on %s\n",
                MPU6050_ADDR, MPU6050_BUS);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%02X (expected 0x68)\n", who_am_i);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    circular_buffer_t gyro_buffer = {0};
    int consecutive_errors = 0;

    printf("MPU-6050 gyroscope monitoring started.  Press Ctrl+C to exit.\n");

    while (g_running) {
        gyro_data_t gyro_data;

        if (mpu6050_read_gyro(g_i2c_fd, &gyro_data) != 0) {
            if (++consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        consecutive_errors = 0;
        circular_buffer_add(&gyro_buffer, gyro_data);
        callback(gyro_data);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

