/*
 * co2_monitor.c — Raspberry Pi 3 Model B+
 *
 * Reads CO2 concentration from an MH-Z19B sensor over UART (/dev/serial0)
 * using the the_driver API (libthe_driver) and logs to co2_log.json
 * with microsecond timestamps.  Errors are logged to co2_error.log.
 *
 * Build:  gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver -lrt
 *
 * Wiring:
 *   MH-Z19B TX  -> Pi GPIO15 (RXD, BCM 15)
 *   MH-Z19B RX  -> Pi GPIO14 (TXD, BCM 14)
 *   MH-Z19B VCC -> 3.3 V
 *   MH-Z19B GND -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <termios.h>

#include <the_driver.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define READ_TIMEOUT_MS  1000       /* max wait for a full 9-byte response */
#define MAX_RETRIES      3          /* retries per reading */
#define MHZ19B_CMD_LEN   9
#define MHZ19B_RESP_LEN  9

/* MH-Z19B command: start measurement, no CRC (sent as-is) */
static const uint8_t mhz19b_cmd[MHZ19B_CMD_LEN] = {
    0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timeval tv;
    struct tm tm_info;

    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%06ld", (long)tv.tv_usec);
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));
    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s (errno=%d: %s)\n",
                ts, msg, errno, strerror(errno));
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* UART initialization                                                 */
/* ------------------------------------------------------------------ */
static int init_uart(void)
{
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        log_error("open() UART device");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr()");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;   /* non-blocking within read() */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr()");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Read exactly n bytes with timeout                                   */
/* ------------------------------------------------------------------ */
static int read_exact(int fd, uint8_t *buf, size_t n, int timeout_ms)
{
    size_t got = 0;
    struct timeval start, now;
    gettimeofday(&start, NULL);

    while (got < n) {
        if (!g_running)
            return -1;

        gettimeofday(&now, NULL);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000L +
                       (now.tv_usec - start.tv_usec) / 1000L;
        if (elapsed >= timeout_ms)
            return -2;   /* timeout */

        ssize_t r = read(fd, buf + got, n - got);
        if (r < 0) {
            if (errno == EINTR)
                continue;
            return -3;   /* read error */
        }
        if (r == 0) {
            usleep(1000);
            continue;
        }
        got += (size_t)r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse CO2 value from 9-byte response                                */
/* ------------------------------------------------------------------ */
static int parse_co2(const uint8_t *resp, uint16_t *co2_out)
{
    if (resp[0] != 0xFF || resp[1] != 0x86) {
        log_error("Invalid response header");
        return -1;
    }

    uint8_t checksum = 0;
    for (int i = 0; i < 7; i++)
        checksum += resp[i];

    if (checksum != resp[7]) {
        log_error("Checksum mismatch");
        return -1;
    }

    *co2_out = ((uint16_t)resp[2] << 8) | resp[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to JSON file                                          */
/* ------------------------------------------------------------------ */
static void log_reading(uint16_t co2, int error)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    fprintf(g_log_fp,
            "{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
            ts, co2, error);
    fflush(g_log_fp);

    if (!error)
        printf("CO2: %u ppm\n", co2);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction()");
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart();
    if (g_uart_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        log_error("fopen() log file");
        cleanup();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        log_error("fopen() error log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started.  UART=%s  Baud=%d  Log=%s  Err=%s\n",
           UART_DEVICE, BAUD_RATE, LOG_FILE, ERROR_LOG_FILE);

    while (g_running) {
        uint8_t resp[MHZ19B_RESP_LEN];
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            tcflush(g_uart_fd, TCIOFLUSH);

            ssize_t w = write(g_uart_fd, mhz19b_cmd, MHZ19B_CMD_LEN);
            if (w < 0) {
                log_error("write() command");
                continue;
            }
            if (w != MHZ19B_CMD_LEN) {
                log_error("partial write() command");
                continue;
            }

            usleep(100000);   /* 100 ms for sensor response */

            int rc = read_exact(g_uart_fd, resp, MHZ19B_RESP_LEN,
                                READ_TIMEOUT_MS);
            if (rc == 0) {
                ok = 1;
                break;
            }
            if (rc == -1)
                break;          /* signal received */
            if (rc == -2)
                log_error("read() timeout");
            else
                log_error("read() error");
        }

        if (ok) {
            uint16_t co2;
            if (parse_co2(resp, &co2) == 0)
                log_reading(co2, 0);
            else
                log_reading(0, 1);
        } else {
            log_reading(0, 1);
        }

        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

