/* ------------------------------------------------------------------ */
/* UART initialization                                                 */
/* ------------------------------------------------------------------ */
static int init_uart(void)
{
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        log_error("open() UART device");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr()");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;   /* non-blocking within read() */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr()");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
