        return -1;
    }

    uint8_t checksum = 0;
    for (int i = 0; i < 7; i++)
        checksum += resp[i];

    if (checksum != resp[7]) {
        log_error("Checksum mismatch");
        return -1;
    }

    *co2_out = ((uint16_t)resp[2] << 8) | resp[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to JSON file                                          */
/* ------------------------------------------------------------------ */
static void log_reading(uint16_t co2, int error)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    fprintf(g_log_fp,
            "{\"timestamp\":\"%s\",\"co2_ppm\":%u,\"error\":%d}\n",
            ts, co2, error);
    fflush(g_log_fp);

    if (!error)
        printf("CO2: %u ppm\n", co2);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction()");
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart();
    if (g_uart_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        log_error("fopen() log file");
        cleanup();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
