/*
 * HMC5883L heading monitor with hard-iron compensation.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: HMC5883L on address 0x1E
 * Output: GPIO17 (BCM) high when heading deviates > 10 deg from target.
 *
 * Build:  gcc -O2 -Wall -o hmc5883l_monitor hmc5883l_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- HMC5883L constants ------------------------------------------------ */
#define HMC5883L_ADDR          0x1E
#define HMC5883L_CONFIG_A      0x00
#define HMC5883L_CONFIG_B      0x01
#define HMC5883L_MODE          0x02
#define HMC5883L_DATA_X_MSB    0x03
#define HMC5883L_DATA_Z_MSB    0x05
#define HMC5883L_DATA_Y_MSB    0x07
#define HMC5883L_ID_A          0x0A
#define HMC5883L_ID_B          0x0B
#define HMC5883L_ID_C          0x0C

#define HMC5883L_ID_A_VAL      0x3E
#define HMC5883L_ID_B_VAL      0x00
#define HMC5883L_ID_C_VAL      0x00

/* ---- Application constants --------------------------------------------- */
#define I2C_BUS                "/dev/i2c-1"
#define GPIO_PIN               17
#define TARGET_HEADING         90.0
#define HEADING_THRESHOLD      10.0
#define BUFFER_SIZE            100
#define SAMPLE_PERIOD_US       100000   /* 100 ms */
#define MAX_CONSECUTIVE_ERRORS 10

/* ---- Hard-iron offsets (user-configurable) ----------------------------- */
static const int16_t hard_iron_x = 100;
static const int16_t hard_iron_y = -50;

/* ---- Globals for signal-safe cleanup ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Circular buffer --------------------------------------------------- */
typedef struct {
    double  data[BUFFER_SIZE];
    int     head;
    int     count;
} CircularBuffer;

static CircularBuffer g_buffer;

/* ---- Signal handler ---------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ------------------------------------------------------- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- HMC5883L initialization ------------------------------------------- */
static int hmc5883l_init(int fd)
{
    uint8_t id[3];
    if (i2c_read_block(fd, HMC5883L_ID_A, id, 3) != 0)
        return -1;
    if (id[0] != HMC5883L_ID_A_VAL || id[1] != HMC5883L_ID_B_VAL ||
        id[2] != HMC5883L_ID_C_VAL) {
        fprintf(stderr, "HMC5883L ID mismatch: got 0x%02X 0x%02X 0x%02X "
                "(expected 0x%02X 0x%02X 0x%02X)\n",
                id[0], id[1], id[2],
                HMC5883L_ID_A_VAL, HMC5883L_ID_B_VAL, HMC5883L_ID_C_VAL);
        return -1;
    }

    /* Config A: 8-average, 15 Hz */
    if (i2c_write_byte(fd, HMC5883L_CONFIG_A, 0x70) != 0)
        return -1;
    /* Config B: 1.3 Gauss gain */
    if (i2c_write_byte(fd, HMC5883L_CONFIG_B, 0x20) != 0)
        return -1;
    /* Mode: continuous */
    if (i2c_write_byte(fd, HMC5883L_MODE, 0x00) != 0)
        return -1;

    return 0;
}

/* ---- Read raw magnetometer data --------------------------------------- */
static int hmc5883l_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, HMC5883L_DATA_X_MSB, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ---- Compensate for hard iron and compute heading ---------------------- */
static double calculate_heading(int16_t x, int16_t y)
{
    int16_t x_comp = x - hard_iron_x;
    int16_t y_comp = y - hard_iron_y;

    double heading = atan2((double)y_comp, (double)x_comp) * 180.0 / M_PI;
    if (heading < 0.0)
        heading += 360.0;
    return heading;
}

/* ---- Circular buffer operations --------------------------------------- */
static void buffer_add(CircularBuffer *cb, double value)
{
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    /* Initialize pigpio for GPIO control */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output and set it low initially */
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Acquire the HMC5883L slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus for 0x%02X: %s\n",
                HMC5883L_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (hmc5883l_init(g_i2c_fd) != 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    g_buffer.head  = 0;
    g_buffer.count = 0;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int consecutive_errors = 0;

    while (g_running) {
        int16_t x, y, z;

        if (hmc5883l_read_raw(g_i2c_fd, &x, &y, &z) == 0) {
            consecutive_errors = 0;

            double heading = calculate_heading(x, y);
            buffer_add(&g_buffer, heading);

            double deviation = fabs(heading - TARGET_HEADING);
            if (deviation > HEADING_THRESHOLD) {
                gpioWrite(GPIO_PIN, 1);
            } else {
                gpioWrite(GPIO_PIN, 0);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    gpioWrite(GPIO_PIN, 0);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

