#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define LOG_FILE "lighting_log.txt"

#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22

#define LUX_THRESHOLD_1 50
#define LUX_THRESHOLD_2 150
#define LUX_THRESHOLD_3 300

#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_TIME_MS 120

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int fd, float *lux_out) {
    unsigned char cmd = BH1750_CONT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    gpioDelay(BH1750_CONV_TIME_MS * 1000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux, red, green, blue);
    fflush(log_file);
}

static void control_relays(float lux) {
    int red = 0, green = 0, blue = 0;
    if (lux < LUX_THRESHOLD_1) {
        red = 1;
    } else if (lux < LUX_THRESHOLD_2) {
        green = 1;
    } else if (lux < LUX_THRESHOLD_3) {
        blue = 1;
    } else {
        red = 1; green = 1; blue = 1;
    }
    gpioWrite(RED_PIN, red);
    gpioWrite(GREEN_PIN, green);
    gpioWrite(BLUE_PIN, blue);
    log_data(lux, red, green, blue);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) == 0) {
            control_relays(lux);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor\n");
            log_data(-1.0f, 0, 0, 0);
        }
        sleep(1);
    }

    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

