#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_pwm(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static void motor_stop(void) {
    safe_write(MOTOR_A_IN1, 0);
    safe_write(MOTOR_A_IN2, 0);
    safe_write(MOTOR_B_IN3, 0);
    safe_write(MOTOR_B_IN4, 0);
    safe_pwm(MOTOR_A_IN2, 0);
    safe_pwm(MOTOR_B_IN4, 0);
}

static int motor_init(void) {
    if (safe_set_mode(MOTOR_A_IN1, PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_A_IN2, PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_B_IN3, PI_OUTPUT) != 0) return -1;
    if (safe_set_mode(MOTOR_B_IN4, PI_OUTPUT) != 0) return -1;

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(MOTOR_A_IN2) failed\n");
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(MOTOR_B_IN4) failed\n");
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_A_IN2) failed\n");
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(MOTOR_B_IN4) failed\n");
        return -1;
    }

    motor_stop();
    return 0;
}

static void motor_forward(int motor_a_speed, int motor_b_speed) {
    if (safe_write(MOTOR_A_IN1, 1) != 0) return;
    if (safe_write(MOTOR_B_IN3, 1) != 0) return;
    if (safe_write(MOTOR_A_IN2, 0) != 0) return;
    if (safe_write(MOTOR_B_IN4, 0) != 0) return;
    if (safe_pwm(MOTOR_A_IN2, motor_a_speed) != 0) return;
    if (safe_pwm(MOTOR_B_IN4, motor_b_speed) != 0) return;
}

static void motor_backward(int motor_a_speed, int motor_b_speed) {
    if (safe_write(MOTOR_A_IN1, 0) != 0) return;
    if (safe_write(MOTOR_B_IN3, 0) != 0) return;
    if (safe_write(MOTOR_A_IN2, 0) != 0) return;
    if (safe_write(MOTOR_B_IN4, 0) != 0) return;
    if (safe_pwm(MOTOR_A_IN2, motor_a_speed) != 0) return;
    if (safe_pwm(MOTOR_B_IN4, motor_b_speed) != 0) return;
}

static int calculate_speed(int distance) {
    if (distance < 10 || distance > 100) {
        fprintf(stderr, "Error: Invalid distance %d (must be 10-100)\n", distance);
        return 0;
    }
    int speed = (distance - 10) * 25;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (speed < 0) speed = 0;
    return speed;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance> <motor_b_distance>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int motor_a_distance = atoi(argv[1]);
    int motor_b_distance = atoi(argv[2]);

    if (motor_a_distance < 10 || motor_a_distance > 100 ||
        motor_b_distance < 10 || motor_b_distance > 100) {
        fprintf(stderr, "Error: Distance must be between 10 and 100 cm\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (motor_init() != 0) {
        fprintf(stderr, "Error: Motor initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int motor_a_speed = calculate_speed(motor_a_distance);
    int motor_b_speed = calculate_speed(motor_b_distance);

    if (motor_a_distance < 50) {
        motor_forward(motor_a_speed, motor_b_speed);
    } else {
        motor_backward(motor_a_speed, motor_b_speed);
    }

    while (running) {
        usleep(LOOP_DELAY_US);
    }

    motor_stop();
    gpioTerminate();
    return EXIT_SUCCESS;
}

