#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define SAMPLE_RATE 100
#define LOG_FILE "solar_tracker.log"
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_DUTY_MIN_NS 1000000
#define PWM_DUTY_MAX_NS 19000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_exported = 0;
static int pwm_enabled = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    int retries = 3;
    while (retries > 0) {
        if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) == 0) return 0;
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s. Retrying...\n", strerror(errno));
        usleep(100000);
        retries--;
    }
    return -1;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    int retries = 3;
    while (retries > 0) {
        if (i2c_read_reg16(fd, ACCEL_XOUT_H, ax) == 0 &&
            i2c_read_reg16(fd, ACCEL_YOUT_H, ay) == 0 &&
            i2c_read_reg16(fd, ACCEL_ZOUT_H, az) == 0) return 0;
        fprintf(stderr, "Error reading accelerometer data: %s. Retrying...\n", strerror(errno));
        usleep(100000);
        retries--;
    }
    return -1;
}

static float calculate_pitch(int16_t ax, int16_t ay, int16_t az) {
    return atan2f((float)ax, sqrtf((float)ay * ay + (float)az * az)) * 180.0f / M_PI;
}

static float calculate_roll(int16_t ax, int16_t ay, int16_t az) {
    return atan2f((float)ay, sqrtf((float)ax * ax + (float)az * az)) * 180.0f / M_PI;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }
    long duty_ns = PWM_DUTY_MIN_NS + (long)(angle * (PWM_DUTY_MAX_NS - PWM_DUTY_MIN_NS) / 180);
    char duty_str[32];
    snprintf(duty_str, sizeof(duty_str), "%ld", duty_ns);
    FILE *fp = fopen("/sys/class/pwm/pwmchip2/pwm0/duty_cycle", "w");
    if (!fp) {
        fprintf(stderr, "Error opening PWM duty_cycle: %s\n", strerror(errno));
        return -1;
    }
    if (fputs(duty_str, fp) == EOF) {
        fprintf(stderr, "Error writing to PWM duty_cycle: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return angle;
}

static void log_data(float pitch, float roll, int servo_pos) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_pos);
    fclose(fp);
}

static int init_pwm(void) {
