static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    int retries = 3;
    while (retries > 0) {
        if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) == 0) return 0;
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s. Retrying...\n", strerror(errno));
        usleep(100000);
        retries--;
    }
    return -1;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    int retries = 3;
    while (retries > 0) {
        if (i2c_read_reg16(fd, ACCEL_XOUT_H, ax) == 0 &&
            i2c_read_reg16(fd, ACCEL_YOUT_H, ay) == 0 &&
            i2c_read_reg16(fd, ACCEL_ZOUT_H, az) == 0) return 0;
