#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCHEDULE_FILE "lighting_schedule.txt"
#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} ScheduleEntry;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_schedule_file(const char *filename, ScheduleEntry **entries, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int count = 0;
    int capacity = 16;
    ScheduleEntry *data = malloc(capacity * sizeof(ScheduleEntry));
    if (!data) {
        perror("malloc failed");
        fclose(fp);
        return -1;
    }

    while (fgets(line, sizeof(line), fp)) {
        if (count >= capacity) {
            capacity *= 2;
            ScheduleEntry *tmp = realloc(data, capacity * sizeof(ScheduleEntry));
            if (!tmp) {
                perror("realloc failed");
                free(data);
                fclose(fp);
                return -1;
            }
            data = tmp;
        }

        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &data[count].hour, &data[count].minute, &data[count].second,
                   &data[count].relay_number, &data[count].state) != 5) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            continue;
        }

        if (data[count].relay_number < 1 || data[count].relay_number > NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number: %d\n", data[count].relay_number);
            continue;
        }
        if (data[count].state != 0 && data[count].state != 1) {
            fprintf(stderr, "Invalid state: %d\n", data[count].state);
            continue;
        }

        count++;
    }

    fclose(fp);

    if (count == 0) {
        fprintf(stderr, "No valid entries found in schedule file\n");
        free(data);
        return -1;
    }

    *entries = data;
    *num_entries = count;
    return 0;
}

static int compare_schedule_entries(const void *a, const void *b) {
    const ScheduleEntry *ea = (const ScheduleEntry *)a;
    const ScheduleEntry *eb = (const ScheduleEntry *)b;
    int t1 = ea->hour * 3600 + ea->minute * 60 + ea->second;
    int t2 = eb->hour * 3600 + eb->minute * 60 + eb->second;
    return (t1 > t2) - (t1 < t2);
}

static int get_current_time_seconds(void) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    return timeinfo->tm_hour * 3600 + timeinfo->tm_min * 60 + timeinfo->tm_sec;
}

static int find_next_transition(const ScheduleEntry *entries, int num_entries, int current_time) {
    int best_diff = 86400;
    int best_idx = -1;
    for (int i = 0; i < num_entries; i++) {
        int target = entries[i].hour * 3600 + entries[i].minute * 60 + entries[i].second;
        int diff = target - current_time;
        if (diff < 0) diff += 86400;
        if (diff < best_diff) {
            best_diff = diff;
            best_idx = i;
        }
    }
    return best_idx;
}

static void set_relay_state(int relay_number, int state) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) return;
    int pin = relay_pins[relay_number - 1];
    gpioWrite(pin, state);
}

static void fade_relay(int relay_number, int target_state, int duration) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) return;
    int pin = relay_pins[relay_number - 1];
    int current_state = gpioRead(pin);
    if (current_state == target_state) return;

    int steps = duration * PWM_FREQUENCY;
    int duty_step = (target_state == 1) ? 1 : -1;
    int duty = (current_state == 1) ? PWM_RANGE : 0;

    for (int i = 0; i < steps && program_running; i++) {
        duty += duty_step;
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        gpioPWM(pin, duty);
        gpioDelay(1000000 / (steps * PWM_FREQUENCY));
    }

    gpioWrite(pin, target_state);
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
        gpioPWM(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioWrite(relay_pins[i], 0);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
    }

    ScheduleEntry *schedule_entries = NULL;
    int num_schedule_entries = 0;
    if (read_schedule_file(SCHEDULE_FILE, &schedule_entries, &num_schedule_entries) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    qsort(schedule_entries, num_schedule_entries, sizeof(ScheduleEntry), compare_schedule_entries);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_time = get_current_time_seconds();
        int next_idx = find_next_transition(schedule_entries, num_schedule_entries, current_time);
        if (next_idx == -1) {
            sleep(1);
            continue;
        }

        int target_time = schedule_entries[next_idx].hour * 3600 +
                          schedule_entries[next_idx].minute * 60 +
                          schedule_entries[next_idx].second;
        int time_to_next = target_time - current_time;
        if (time_to_next < 0) time_to_next += 86400;

        if (time_to_next > FADE_DURATION) {
            sleep(1);
            continue;
        }

        int target_state = schedule_entries[next_idx].state;
        int relay_num = schedule_entries[next_idx].relay_number;
        printf("Transitioning relay %d to state %d in %d seconds\n", relay_num, target_state, time_to_next);

        for (int i = 0; i < time_to_next && program_running; i++) {
            sleep(1);
        }

        if (!program_running) break;

        fade_relay(relay_num, target_state, FADE_DURATION);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    free(schedule_entries);
    return EXIT_SUCCESS;
}

