        if (diff < 0) diff += 86400;
        if (diff < best_diff) {
            best_diff = diff;
            best_idx = i;
        }
    }
    return best_idx;
}

static void set_relay_state(int relay_number, int state) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) return;
    int pin = relay_pins[relay_number - 1];
    gpioWrite(pin, state);
}

static void fade_relay(int relay_number, int target_state, int duration) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) return;
    int pin = relay_pins[relay_number - 1];
    int current_state = gpioRead(pin);
    if (current_state == target_state) return;

    int steps = duration * PWM_FREQUENCY;
    int duty_step = (target_state == 1) ? 1 : -1;
    int duty = (current_state == 1) ? PWM_RANGE : 0;

    for (int i = 0; i < steps && program_running; i++) {
        duty += duty_step;
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        gpioPWM(pin, duty);
        gpioDelay(1000000 / (steps * PWM_FREQUENCY));
    }

    gpioWrite(pin, target_state);
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
        gpioPWM(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioWrite(relay_pins[i], 0);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
    }

    ScheduleEntry *schedule_entries = NULL;
    int num_schedule_entries = 0;
    if (read_schedule_file(SCHEDULE_FILE, &schedule_entries, &num_schedule_entries) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    qsort(schedule_entries, num_schedule_entries, sizeof(ScheduleEntry), compare_schedule_entries);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_time = get_current_time_seconds();
        int next_idx = find_next_transition(schedule_entries, num_schedule_entries, current_time);
        if (next_idx == -1) {
            sleep(1);
            continue;
        }

        int target_time = schedule_entries[next_idx].hour * 3600 +
                          schedule_entries[next_idx].minute * 60 +
                          schedule_entries[next_idx].second;
        int time_to_next = target_time - current_time;
        if (time_to_next < 0) time_to_next += 86400;

        if (time_to_next > FADE_DURATION) {
            sleep(1);
            continue;
        }

        int target_state = schedule_entries[next_idx].state;
        int relay_num = schedule_entries[next_idx].relay_number;
        printf("Transitioning relay %d to state %d in %d seconds\n", relay_num, target_state, time_to_next);

        for (int i = 0; i < time_to_next && program_running; i++) {
            sleep(1);
        }

        if (!program_running) break;

        fade_relay(relay_num, target_state, FADE_DURATION);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    free(schedule_entries);
    return EXIT_SUCCESS;
}

