/*
 * Rudimentary theremin for Raspberry Pi Zero W
 *
 * HC-SR04 ultrasonic distance sensor:
 *   Trigger -> GPIO23 (BCM)
 *   Echo    <- GPIO24 (BCM)
 * Buzzer PWM -> GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

/* ---- Timing constants (microseconds) ---- */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* ~5 m round trip */
#define LOOP_DELAY_US    20000   /* 50 Hz main-loop tick */
#define MEASURE_GAP_US   60000   /* 60 ms between readings */

/* ---- Buzzer frequency limits (Hz) ---- */
#define BUZZER_MIN_FREQ  2000
#define BUZZER_MAX_FREQ  5000

/* ---- Speed of sound at 20 °C (cm/s) ---- */
#define SOUND_SPEED_CM_S 34300.0

/* ---- Globals for signal-driven cleanup ---- */
static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Issue a 10 µs trigger pulse on the trigger pin.
 * Returns 0 on success, -1 on write failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    return 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in µs on success, or -1 on timeout/error.
 */
static long get_echo_pulse_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout (sensor absent?)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/*
 * Convert echo pulse width (µs) to distance (cm).
 * Returns -1.0 on invalid pulse.
 */
static double pulse_to_distance_cm(long pulse_us)
{
    if (pulse_us <= 0)
        return -1.0;
    return (double)pulse_us * SOUND_SPEED_CM_S / 2000000.0;
}

/*
 * Convert distance (cm) to buzzer frequency (Hz).
 * Clamps to BUZZER_MIN_FREQ .. BUZZER_MAX_FREQ.
 */
static int distance_to_frequency(double distance_cm)
{
    if (distance_cm < 2.0)
        distance_cm = 2.0;
    if (distance_cm > 40.0)
        distance_cm = 40.0;

    /* Linear mapping: 2 cm -> 2000 Hz, 40 cm -> 5000 Hz */
    double freq = BUZZER_MIN_FREQ +
                  (distance_cm - 2.0) *
                  (BUZZER_MAX_FREQ - BUZZER_MIN_FREQ) / 38.0;

    if (freq < BUZZER_MIN_FREQ) freq = BUZZER_MIN_FREQ;
    if (freq > BUZZER_MAX_FREQ) freq = BUZZER_MAX_FREQ;

    return (int)freq;
}

/*
 * Set buzzer PWM frequency.
 * Returns 0 on success, -1 on failure.
 */
static int set_buzzer_frequency(int freq_hz)
{
    if (gpioSetPWMfrequency(BUZZER_PIN, freq_hz) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", freq_hz);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {   /* 50 % duty cycle */
        fprintf(stderr, "Error: gpioPWM(128) failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    /* ---- Install signal handler for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO modes ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5000);   /* 5 ms settle */

    printf("Theremin running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (trigger_sensor() < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse = get_echo_pulse_us();
        if (pulse < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double distance = pulse_to_distance_cm(pulse);
        if (distance < 0.0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int freq = distance_to_frequency(distance);
        if (set_buzzer_frequency(freq) < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm  ->  Buzzer: %d Hz\n", distance, freq);

        /* Enforce 60 ms measurement gap */
        gpioDelay(MEASURE_GAP_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioPWM(BUZZER_PIN, 0);   /* Silence buzzer */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

