/*
 * RGB LED proximity indicator for Raspberry Pi 3 Model B+
 *
 * Uses pigpio hardware PWM on BCM pins 17 (red), 22 (green), 27 (blue).
 * Generates a smooth color transition that reflects a simulated proximity
 * value ranging from 0.0 to 1.0 (sine-wave over time).
 *
 * Build:  gcc -O2 -Wall -o rgb_proximity rgb_proximity.c -lpigpio -lrt
 * Run:    sudo ./rgb_proximity
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define PWM_FREQ   1000          /* Hz  -> 1 kHz PWM carrier */
#define PWM_RANGE  255           /* duty-cycle range (0..255) */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Set LED color using pigpio hardware PWM.                            */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map proximity (0.0..1.0) to RGB values.                            */
/* ------------------------------------------------------------------ */
static void proximity_to_rgb(double proximity, int *red, int *green, int *blue)
{
    /*
     * Simulated proximity -> color mapping:
     *   0.0 -> dark blue (0,0,255)
     *   1.0 -> bright red  (255,0,0)
     *   0.5 -> white       (128,128,128)
     */
    if (proximity <= 0.0) {
        *red   = 0;
        *green = 0;
        *blue  = 255;
    } else if (proximity >= 1.0) {
        *red   = 255;
        *green = 0;
        *blue  = 0;
    } else {
        /* Linear interpolation between blue and red */
        double frac = proximity / 1.0;
        *red   = (int)(frac * 255.0);
        *green = 0;
        *blue  = (int)((1.0 - frac) * 255.0);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure PWM pins ---- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(RED_PIN) failed.\n");
        goto cleanup_fail;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(GREEN_PIN) failed.\n");
        goto cleanup_fail;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BLUE_PIN) failed.\n");
        goto cleanup_fail;
    }

    /* ---- Set PWM frequency and range ---- */
    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed.\n");
        goto cleanup_fail;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed.\n");
        goto cleanup_fail;
    }

    /* ---- Ensure LED is off at start ---- */
    if (set_led_color(0, 0, 0) < 0) {
        fprintf(stderr, "Error: initial gpioPWM failed.\n");
        goto cleanup_fail;
    }

    /* ---- Main loop: simulate proximity over time ---- */
    while (g_running) {
        double proximity = 0.5 + 0.5 * sin(time_time());

        if (proximity < 0.0) proximity = 0.0;
        if (proximity > 1.0) proximity = 1.0;

        int red, green, blue;
        proximity_to_rgb(proximity, &red, &green, &blue);

        if (set_led_color(red, green, blue) < 0) {
            fprintf(stderr, "Error: gpioPWM failed during update.\n");
            break;
        }

        time_sleep(0.01);  /* 10 ms -> ~100 Hz refresh */
    }

    /* ---- Clean shutdown: turn LED off and release resources ---- */
    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;

cleanup_fail:
    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_FAILURE;
}

