#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "gyro_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1. Sensor may be absent.\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_gyro_data(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    if (i2c_read_reg16(fd, GYRO_XOUT_H, gx) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_XOUT_H + 2, gy) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_XOUT_H + 4, gz) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int16_t gx, int16_t gy, int16_t gz) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %d, %d, %d\n", timestamp, gx, gy, gz);
    fflush(fp);
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int16_t gx, gy, gz;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "Error initializing MPU6050.\n");
        close(fd);
        return 1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (read_gyro_data(fd, &gx, &gy, &gz) == 0) {
            log_data(fp, gx, gy, gz);
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return 0;
}

