/*
 * Vibration monitor for Raspberry Pi 3 Model B+
 * Sensor : SW-420 vibration module (digital output, active-high)
 * Wiring : module D0  -> GPIO17 (BCM 17, physical pin 11)
 *          module VCC -> 3.3 V
 *          module GND -> GND
 * Library: pigpio (http://abyz.me.uk/rpi/pigpio/)
 *
 * Build  : gcc -O2 -Wall -Wextra -o vibration_monitor vibration_monitor.c -lpigpio -lrt
 * Run    : sudo ./vibration_monitor [timeout_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define VIBRATION_GPIO      17          /* BCM pin number */
#define WINDOW_SIZE         5
#define DEFAULT_TIMEOUT_MS  1000
#define LOG_FILE_NAME       "vibration_events.log"

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;            /* no SA_RESTART so read() can return EINTR */

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static int log_event(FILE *fp, int value)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s value=%d\n", ts, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Earthquake detection                                               */
/* ------------------------------------------------------------------ */

/*
 * Sliding window of the last WINDOW_SIZE edge events.
 * We count the number of HIGH (1) events in the window and alert
 * whenever three or more of them are present.
 */
static int detect_earthquake(const int *window, int count)
{
    int high_count = 0;
    for (int i = 0; i < count; i++) {
        if (window[i] == 1)
            high_count++;
    }
    return (high_count >= 3) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int   timeout_ms = DEFAULT_TIMEOUT_MS;
    int   window[WINDOW_SIZE];
    int   window_count = 0;
    int   i;

    /* ---- Parse optional timeout argument ---- */
    if (argc > 1) {
        char *endptr = NULL;
        errno = 0;
        long val = strtol(argv[1], &endptr, 10);
        if (errno != 0 || endptr == argv[1] || *endptr != '\0' || val <= 0 || val > 60000) {
            fprintf(stderr, "Invalid timeout '%s'; using default %d ms.\n",
                    argv[1], DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        } else {
            timeout_ms = (int)val;
        }
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with pull-down ---- */
    if (gpioSetMode(VIBRATION_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", VIBRATION_GPIO);
        goto cleanup_fail;
    }
    if (gpioSetPullUpDown(VIBRATION_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                VIBRATION_GPIO);
        goto cleanup_fail;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        goto cleanup_fail;
    }

    /* ---- Initialise window to zeros ---- */
    for (i = 0; i < WINDOW_SIZE; i++)
        window[i] = 0;

    printf("Vibration monitoring started on GPIO%d.  Timeout=%d ms.  Ctrl+C to exit.\n",
           VIBRATION_GPIO, timeout_ms);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int value = gpioRead(VIBRATION_GPIO);
        if (value < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %s\n",
                    VIBRATION_GPIO, strerror(errno));
            break;
        }

        /* Shift window: drop oldest, append new */
        for (i = 0; i < WINDOW_SIZE - 1; i++)
            window[i] = window[i + 1];
        window[WINDOW_SIZE - 1] = value;
        if (window_count < WINDOW_SIZE)
            window_count++;

        /* Log every edge event */
        if (log_event(g_log_fp, value) != 0) {
            /* Non-fatal: keep monitoring */
        }

        /* Earthquake detection on the current window */
        if (detect_earthquake(window, window_count)) {
            time_t     rawtime;
            struct tm  tm_info;
            char       ts[32];

            time(&rawtime);
            if (localtime_r(&rawtime, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
                printf("[%s] EARTHQUAKE ALERT\n", ts);
            } else {
                printf("[timestamp-error] EARTHQUAKE ALERT\n");
            }
        }

        /*
         * gpioDelay returns the actual delay in microseconds;
         * a negative value indicates an error.
         */
        int delay_us = gpioDelay(timeout_ms * 1000);
        if (delay_us < 0) {
            fprintf(stderr, "gpioDelay(%d us) failed: %s\n",
                    timeout_ms * 1000, strerror(errno));
            break;
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetPullUpDown(VIBRATION_GPIO, PI_PUD_OFF);
    gpioTerminate();

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            perror("fclose(log)");
        g_log_fp = NULL;
    }
    return EXIT_SUCCESS;

cleanup_fail:
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    return EXIT_FAILURE;
}

