        if (errno != 0 || endptr == argv[1] || *endptr != '\0' || val <= 0 || val > 60000) {
            fprintf(stderr, "Invalid timeout '%s'; using default %d ms.\n",
                    argv[1], DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        } else {
            timeout_ms = (int)val;
        }
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with pull-down ---- */
    if (gpioSetMode(VIBRATION_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", VIBRATION_GPIO);
        goto cleanup_fail;
    }
    if (gpioSetPullUpDown(VIBRATION_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                VIBRATION_GPIO);
        goto cleanup_fail;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        goto cleanup_fail;
    }

    /* ---- Initialise window to zeros ---- */
    for (i = 0; i < WINDOW_SIZE; i++)
        window[i] = 0;

    printf("Vibration monitoring started on GPIO%d.  Timeout=%d ms.  Ctrl+C to exit.\n",
           VIBRATION_GPIO, timeout_ms);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int value = gpioRead(VIBRATION_GPIO);
        if (value < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %s\n",
                    VIBRATION_GPIO, strerror(errno));
            break;
        }

        /* Shift window: drop oldest, append new */
        for (i = 0; i < WINDOW_SIZE - 1; i++)
            window[i] = window[i + 1];
        window[WINDOW_SIZE - 1] = value;
        if (window_count < WINDOW_SIZE)
            window_count++;

        /* Log every edge event */
        if (log_event(g_log_fp, value) != 0) {
            /* Non-fatal: keep monitoring */
        }

        /* Earthquake detection on the current window */
        if (detect_earthquake(window, window_count)) {
            time_t     rawtime;
            struct tm  tm_info;
            char       ts[32];

            time(&rawtime);
            if (localtime_r(&rawtime, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
                printf("[%s] EARTHQUAKE ALERT\n", ts);
            } else {
                printf("[timestamp-error] EARTHQUAKE ALERT\n");
            }
        }

        /*
         * gpioDelay returns the actual delay in microseconds;
         * a negative value indicates an error.
         */
        int delay_us = gpioDelay(timeout_ms * 1000);
        if (delay_us < 0) {
            fprintf(stderr, "gpioDelay(%d us) failed: %s\n",
                    timeout_ms * 1000, strerror(errno));
            break;
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetPullUpDown(VIBRATION_GPIO, PI_PUD_OFF);
    gpioTerminate();

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            perror("fclose(log)");
        g_log_fp = NULL;
    }
    return EXIT_SUCCESS;

cleanup_fail:
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    return EXIT_FAILURE;
}

