/*
 * LSM303DLHC Magnetometer Compass Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC VCC  -> 3V3 (pin 1)
 *   LSM303DLHC GND  -> GND (pin 9)
 *   LSM303DLHC SDA  -> GPIO2 / physical pin 3
 *   LSM303DLHC SCL  -> GPIO3 / physical pin 5
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mag_compass mag_compass.c
 *
 * Run:
 *   ./mag_compass
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303DLHC Magnetometer constants (LSM303DLHC datasheet) ---- */
#define LSM303_MAG_ADDR        0x1E   /* 7-bit I2C address (SA0 tied to GND) */
#define LSM303_MAG_CTRL_REG1_M 0x20   /* Temp sensor enable, ODR */
#define LSM303_MAG_CTRL_REG2_M 0x21   /* Gain */
#define LSM303_MAG_CTRL_REG3_M 0x22   /* Mode (continuous-conversion) */
#define LSM303_MAG_CTRL_REG4_M 0x23   /* Operating mode */
#define LSM303_MAG_OUT_X_L_M   0x28   /* X-axis low byte (auto-increment) */

/* ---- Calibration constants ---- */
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read len bytes */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_block: read %zu bytes from 0x%02X failed: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_magnetometer(int fd)
{
    /* Temp sensor enabled, ODR = 8 Hz (0x10) -> 0x30 */
    if (i2c_write_reg(fd, LSM303_MAG_CTRL_REG1_M, 0x30) < 0) return -1;
    /* Gain = +/− 1.3 Gauss (0x00) */
    if (i2c_write_reg(fd, LSM303_MAG_CTRL_REG2_M, 0x00) < 0) return -1;
    /* Continuous-conversion mode (0x00) */
    if (i2c_write_reg(fd, LSM303_MAG_CTRL_REG3_M, 0x00) < 0) return -1;
    /* Operating mode = normal (0x00) */
    if (i2c_write_reg(fd, LSM303_MAG_CTRL_REG4_M, 0x00) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, LSM303_MAG_OUT_X_L_M, raw, sizeof(raw)) < 0)
        return -1;

    /* LSM303DLHC outputs are left-justified 16-bit two's complement */
    *x = (int16_t)((raw[1] << 8) | raw[0]);
    *y = (int16_t)((raw[3] << 8) | raw[2]);
    *z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void calibrate(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                      float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = (float)raw_x - X_OFFSET;
    *cal_y = (float)raw_y - Y_OFFSET;
    *cal_z = (float)raw_z - Z_OFFSET;
}

/* ------------------------------------------------------------------ */
static float calculate_heading(float cal_x, float cal_y)
{
    float heading = atan2f(cal_y, cal_x) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
static const char *map_heading_to_direction(float heading)
{
    if (heading < 22.5f)      return "N";
    if (heading < 67.5f)      return "NE";
    if (heading < 112.5f)     return "E";
    if (heading < 157.5f)     return "SE";
    if (heading < 202.5f)     return "S";
    if (heading < 247.5f)     return "SW";
    if (heading < 292.5f)     return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z,
                    float heading, const char *dir)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f, %.2f, %.2f, %.2f, %s\n",
                ts, cal_x, cal_y, cal_z, heading, dir) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (SDA=GPIO2/pin3, SCL=GPIO3/pin5) */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append); write header if new */
    int file_exists = (access("mag_log.csv", F_OK) == 0);
    g_log_fp = fopen("mag_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(mag_log.csv) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        if (fprintf(g_log_fp, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_fp);
    }

    printf("LSM303DLHC Compass Logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "I2C read error; skipping sample.\n");
        } else {
            float cal_x, cal_y, cal_z;
            calibrate(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
            float heading = calculate_heading(cal_x, cal_y);
            const char *dir = map_heading_to_direction(heading);

            if (log_data(g_log_fp, cal_x, cal_y, cal_z, heading, dir) < 0)
                fprintf(stderr, "Logging failed (continuing).\n");

            printf("Heading: %.2f deg (%s)\n", heading, dir);
        }

        /* Sleep 1 s (interruptible by signals) */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

