/*
 * TTP223 capacitive touch sensor -> relay toggle on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TTP223 OUT  -> GPIO4  (BCM 4, physical pin 7)
 *   Relay IN    -> GPIO17 (BCM 17, physical pin 11)
 *   Relay VCC   -> 5 V
 *   Relay GND   -> GND
 *   TTP223 VCC  -> 3.3 V
 *   TTP223 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_toggle relay_toggle.c -lpigpio -lrt
 * Run:
 *   sudo ./relay_toggle
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4    /* BCM 4  – TTP223 OUT  */
#define RELAY_PIN      17   /* BCM 17 – relay IN    */
#define DEBOUNCE_US    200000 /* 200 ms */
#define LOG_FILE       "relay_log.json"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_relay_state = 0; /* 0 = OFF, 1 = ON */

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_state_change(int relay_state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (!tm_info) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
                ts, relay_state ? "ON" : "OFF") < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ISR – runs in pigpio thread                                         */
/* ------------------------------------------------------------------ */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1)            /* only act on rising edge */
        return;

    static uint32_t last_tick = 0;
    uint32_t elapsed;

    /* pigpio tick wraps every ~71.6 min; handle wrap-around */
    if (tick >= last_tick)
        elapsed = tick - last_tick;
    else
        elapsed = (0xFFFFFFFFu - last_tick) + tick + 1u;

    if (elapsed < DEBOUNCE_US)
        return;                /* within debounce window – ignore */

    last_tick = tick;

    g_relay_state = !g_relay_state;

    if (safe_write(RELAY_PIN, g_relay_state) != 0)
        return;

    if (log_state_change(g_relay_state) != 0)
        fprintf(stderr, "Warning: failed to log state change\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is OFF before tearing down pigpio */
    if (safe_write(RELAY_PIN, 0) != 0)
        fprintf(stderr, "Warning: failed to force relay OFF during cleanup\n");

    if (log_state_change(0) != 0)
        fprintf(stderr, "Warning: failed to log final state change\n");

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* TTP223 module has an internal pull-down; enable Pi pull-down too */
    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%u, PI_PUD_DOWN) failed\n", TOUCH_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with relay OFF */
    if (safe_write(RELAY_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx(%u) failed\n", TOUCH_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Touch pin : BCM %d\n", TOUCH_PIN);
    printf("  Relay pin : BCM %d\n", RELAY_PIN);
    printf("  Debounce  : %u us\n", DEBOUNCE_US);
    printf("  Log file  : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running)
        gpioDelay(100000); /* 100 ms */

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

