#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1 17
#define RELAY2 23
#define RELAY3 24
#define RELAY4 25

#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define RELAY_GAP 1
#define SAMPLE_INTERVAL 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    int pins[] = {RELAY1, RELAY2, RELAY3, RELAY4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Failed to initialise GPIO %d high\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    int pins[] = {RELAY1, RELAY2, RELAY3, RELAY4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1);
    }
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static void log_irrigation_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n",
                    timestamp, relay_number, moisture_level) < 0) {
            fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        } else {
            if (fflush(log_file) != 0) {
                fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            }
        }
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

static void irrigate_relay(int relay_number, int moisture_level) {
    if (gpioWrite(relay_number, 0) != 0) {
        fprintf(stderr, "Failed to activate relay %d\n", relay_number);
        return;
    }
    printf("Relay %d activated for %d seconds.\n", relay_number, IRRIGATION_DURATION);
    log_irrigation_event(relay_number, moisture_level);

    for (int i = 0; i < IRRIGATION_DURATION && running; ++i) {
        gpioDelay(1000000);
    }

    if (gpioWrite(relay_number, 1) != 0) {
        fprintf(stderr, "Failed to deactivate relay %d\n", relay_number);
    }
    printf("Relay %d deactivated.\n", relay_number);
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
    }

    int relay_pins[] = {RELAY1, RELAY2, RELAY3, RELAY4};

    while (running) {
        int moisture_level = read_moisture_sensor();
        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (size_t i = 0; i < sizeof(relay_pins) / sizeof(relay_pins[0]) && running; ++i) {
                irrigate_relay(relay_pins[i], moisture_level);
                if (i + 1 < sizeof(relay_pins) / sizeof(relay_pins[0]) && running) {
                    gpioDelay(RELAY_GAP * 1000000);
                }
            }
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL * 1000000);
        }
    }

    printf("\nShutting down gracefully...\n");
    deactivate_all_relays();

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

