/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 *
 * Two SG90 servos driven via pigpio:
 *   GPIO17 (BCM 17, physical pin 11) -> valve servo
 *   GPIO18 (BCM 18, physical pin 12) -> nozzle servo
 *
 * Simulated soil-moisture readings (0–100) cycle every 1 s through
 *   20, 40, 60, 80, 100
 * Watering occurs when moisture < 50.
 *
 * Build:  gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define VALVE_PIN    17
#define NOZZLE_PIN   18

/* ---- Servo pulse-width limits (microseconds) ---- */
#define SERVO_MIN_PULSE 500   /* 0°   */
#define SERVO_MAX_PULSE 2500  /* 180° */
#define VALVE_OPEN_PULSE 1500 /* 90°  */
#define VALVE_CLOSED_PULSE 500 /* 0°  */

/* ---- Nozzle angle sequence (degrees) ---- */
static const int nozzle_angles[] = {0, 45, 90, 135, 180};
#define NUM_ANGLES (int)(sizeof(nozzle_angles) / sizeof(nozzle_angles[0]))

/* ---- Timing constants (milliseconds) ---- */
