/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 VCC -> 3.3V (Pin 1)
 *   MPU-6050 GND -> GND  (Pin 9)
 *   MPU-6050 SDA -> GPIO2 / I2C1 SDA (Pin 3)
 *   MPU-6050 SCL -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gyro_logger gyro_logger.c -lm
 *
 * Run:
 *   ./gyro_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_XOUT_H 0x43

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register. Returns 0 on success.    */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at `reg`. Returns 0 on success.               */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: write reg pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data bytes */
    ssize_t total = 0;
    while ((size_t)total < n) {
        ssize_t r = read(fd, dst + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "i2c_read_burst: read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "i2c_read_burst: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_mpu6050(int fd)
{
    /* Wake the device: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake MPU-6050 (sensor absent or bus error)\n");
        return -1;
    }
    /* Allow time for the oscillator to stabilize */
    usleep(100000);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_data(int fd, int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, MPU6050_REG_GYRO_XOUT_H, raw, sizeof(raw)) != 0)
        return -1;

    *gx = (int16_t)((raw[0] << 8) | raw[1]);
    *gy = (int16_t)((raw[2] << 8) | raw[3]);
    *gz = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t gx, int16_t gy, int16_t gz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, gx, gy, gz);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_mpu6050(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open gyro_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,gyro_x,gyro_y,gyro_z\n");
        fflush(g_log_fp);
    }

    printf("MPU-6050 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop at ~10 Hz */
    while (g_running) {
        int16_t gx, gy, gz;
        if (read_gyro_data(g_i2c_fd, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
        } else {
            log_data(g_log_fp, gx, gy, gz);
        }
        usleep(100000); /* 100 ms -> ~10 Hz */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

