/*
 * HC-SR04 ultrasonic distance sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   GPIO17 (Pin 11) -> HC-SR04 TRIG (10 kΩ pull-down recommended)
 *   GPIO18 (Pin 12) -> HC-SR04 ECHO (5 V -> 3.3 V divider recommended)
 *
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000          /* 50 ms */
#define SAMPLE_PERIOD_US 1000000        /* 1 s  */
#define MEASURE_CYCLE_US 60000          /* 60 ms between measurements */
#define SOUND_SPEED_CM_S 34300.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Wait for a level change on `pin` with a timeout in microseconds.
 * Returns the elapsed microseconds on success, or -1 on timeout.
 */
static long wait_for_level(int pin, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(pin) != level) {
        if ((gpioTick() - start) >= timeout_us)
            return -1;
    }
    return (long)(gpioTick() - start);
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout or GPIO error.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    long rise = wait_for_level(ECHO_PIN, 1, ECHO_TIMEOUT_US);
    if (rise < 0) {
        fprintf(stderr, "Error: echo rising edge timeout\n");
        return -1.0;
    }

    /* Wait for echo falling edge */
    long fall = wait_for_level(ECHO_PIN, 0, ECHO_TIMEOUT_US);
    if (fall < 0) {
        fprintf(stderr, "Error: echo falling edge timeout\n");
        return -1.0;
    }

    long elapsed = fall - rise;
    if (elapsed <= 0) {
        fprintf(stderr, "Error: invalid echo pulse duration\n");
        return -1.0;
    }

    /* distance = (elapsed * speed_of_sound) / 2 */
    return (double)elapsed * SOUND_SPEED_CM_S / 2000000.0;
}

static void log_distance(double distance)
{
    if (distance < 0.0) {
        fprintf(g_log, "-1\n");
    } else {
        fprintf(g_log, "%.2f\n", distance);
    }
    fflush(g_log);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open log file once and keep it open for the lifetime of the program */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        fclose(g_log);
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, echo pin as input */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN, OUTPUT) failed\n");
        goto cleanup;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN, INPUT) failed\n");
        goto cleanup;
    }

    /* Main sampling loop */
    while (g_running) {
        double distance = measure_distance();
        log_distance(distance);

        /*
         * Sleep for the remainder of the 1 s period.
         * gpioDelay is a busy-wait; for a precise 1 s sample period
         * we use a busy-wait loop that breaks early on signal.
         */
        uint32_t elapsed = 0;
        while (g_running && elapsed < SAMPLE_PERIOD_US) {
            uint32_t step = (SAMPLE_PERIOD_US - elapsed > 100000)
                            ? 100000 : (SAMPLE_PERIOD_US - elapsed);
            gpioDelay(step);
            elapsed += step;
        }
    }

cleanup:
    /* Release pigpio resources */
    gpioTerminate();
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    return EXIT_SUCCESS;
}

