/*
 * Raspberry Pi 4 Model B – VL53L1X distance-controlled relay
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Relay IN     -> GPIO18 (BCM, pin 12)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_relay vl53l1x_relay.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for GPIO/I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* default 7-bit I2C address     */
#define RELAY_GPIO           18            /* BCM pin 18                    */
#define DISTANCE_THRESHOLD   50            /* cm                            */
#define POLL_DELAY_US        100000        /* 100 ms                        */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET            0x0003
#define VL53L1X_REG_SYSTEM_MODE_START     0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS   0x0089
#define VL53L1X_REG_RESULT_DISTANCE       0x0096

/* ----------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers ------------------------------- */

/*
 * Write a 16-bit register address followed by a single byte value.
 * VL53L1X expects big-endian register addressing, so the high byte
 * is sent first.
 */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes starting at the 16-bit register address.
 * VL53L1X expects big-endian register addressing, so the high byte
 * is sent first.  We send the address, then read the data.
 */
static int vl53l1x_read_block(int handle, uint16_t reg, uint8_t *data, int len)
{
    char addr_buf[2];
    addr_buf[0] = (char)(reg >> 8);
    addr_buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice(0x%04X, %d) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------ VL53L1X initialization ------------------------ */

static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000);  /* 10 ms */

    /* Start ranging (mode 0 = continuous) */
    if (vl53l1x_write_byte(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0)
        return -1;
    gpioDelay(10000);  /* 10 ms for first measurement */

    return 0;
}

/* ------------------------ VL53L1X distance read ------------------------ */

/*
 * Returns distance in mm on success, -1 on error, -2 if data not ready.
 */
static int vl53l1x_read_distance(int handle)
{
    uint8_t status = 0;
    uint8_t data[2] = {0, 0};

    /* Check interrupt status to see if a new sample is ready */
    if (vl53l1x_read_block(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS,
                           &status, 1) != 0)
        return -1;

    if ((status & 0x07) == 0) {
        /* No new data yet */
        return -2;
    }

    /* Read 2-byte distance register */
    if (vl53l1x_read_block(handle, VL53L1X_REG_RESULT_DISTANCE,
                           data, 2) != 0)
        return -1;

    /* Clear interrupt so the next measurement can be flagged */
    if (vl53l1x_write_byte(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, 0x01) != 0)
        return -1;

    return (data[0] << 8) | data[1];
}

/* ----------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIO --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* relay OFF at startup */

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor running. Threshold: %d cm. Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance == -2) {
            /* Data not ready yet – brief sleep to avoid busy-waiting */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance < 0) {
            /* I2C error – log and continue */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Convert mm -> cm */
        int distance_cm = distance / 10;

        printf("Distance: %d cm\n", distance_cm);

        if (distance_cm <= DISTANCE_THRESHOLD) {
            gpioWrite(RELAY_GPIO, 1);
        } else {
            gpioWrite(RELAY_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

