    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t reg_buf = reg;
    ssize_t n = write(fd, &reg_buf, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    *out = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ---- MPU-6050 driver --------------------------------------------------- */
static int mpu6050_init(int fd)
{
    /* Wake the device: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) == -1)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */

    /* Set gyro full-scale range to +/- 250 deg/s (default) */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, GYRO_FS_SEL_250DPS) == -1)
        return -1;

    /* Sample-rate divider = 0 -> 1 kHz / (1 + 0) = 1 kHz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x00) == -1)
        return -1;

    return 0;
}

static int mpu6050_read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz)
{
    if (i2c_read_reg16(fd, REG_GYRO_XOUT_H, gx) == -1) return -1;
    if (i2c_read_reg16(fd, REG_GYRO_XOUT_H + 2, gy) == -1) return -1;
    if (i2c_read_reg16(fd, REG_GYRO_XOUT_H + 4, gz) == -1) return -1;
    return 0;
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    install_signal_handlers();

    g_fd = open(MPU6050_BUS, O_RDWR);
    if (g_fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", MPU6050_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6050_ADDR) == -1) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a register read to confirm the device is present */
    int16_t probe;
    if (i2c_read_reg16(g_fd, REG_SMPLRT_DIV, &probe) == -1) {
        fprintf(stderr, "MPU-6050 not detected at 0x%02X on %s\n",
                MPU6050_ADDR, MPU6050_BUS);
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_fd) == -1) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Logging gyro data (Ctrl+C to stop)...\n");

    while (g_running) {
        int16_t gx, gy, gz;

        if (mpu6050_read_gyro(g_fd, &gx, &gy, &gz) == -1) {
            fprintf(stderr, "Gyro read error; continuing...\n");
            usleep(100000);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("%ld.%09ld  Gyro: X=%6d  Y=%6d  Z=%6d\n",
               (long)ts.tv_sec, ts.tv_nsec, gx, gy, gz);
        fflush(stdout);

        usleep(10000);  /* 100 ms -> ~10 Hz */
    }

    printf("\nShutting down cleanly...\n");
    if (g_fd != -1)
        close(g_fd);
    return EXIT_SUCCESS;
}

