/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Relays (active-low modules):
 *   Relay 1 -> GPIO17 (BCM 17, physical pin 11)
 *   Relay 2 -> GPIO18 (BCM 18, physical pin 12)
 *   Relay 3 -> GPIO27 (BCM 27, physical pin 13)
 *   Relay 4 -> GPIO22 (BCM 22, physical pin 15)
 *
 * Build:  gcc -o watering watering.c -lgpiod
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_ACTIVE_TIME 5          /* seconds per relay activation */
#define CYCLE_INTERVAL  86400        /* seconds between full cycles  */
#define POLL_INTERVAL   60           /* seconds between relay polls   */
#define LOG_FILE        "watering_log.txt"
#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO controller on Pi 4/5 */

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int log_cycle_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Watering cycle started\n", timestamp) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int activate_relay(struct gpiod_line *line, int duration_sec)
{
    /* Active-low relay: set LOW to energise the coil. */
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(LOW)");
        return -1;
    }

    /*
     * Sleep in 1-second increments so we can respond to signals
     * promptly.
     */
    for (int i = 0; i < duration_sec && g_running; i++)
        sleep(1);

    /* De-energise the coil (HIGH for active-low module). */
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(HIGH)");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_acquired = 0;
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* ---- Acquire lines and configure as outputs, inactive --------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u): %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_acquired++;
    }

    printf("Plant watering system started.\n");
    printf("Relays on GPIO%u, GPIO%u, GPIO%u, GPIO%u.\n",
           relay_pins[0], relay_pins[1], relay_pins[2], relay_pins[3]);
    printf("Cycle interval: %d seconds (%d cycles per day).\n",
           CYCLE_INTERVAL, 86400 / CYCLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        if (log_cycle_start() < 0) {
            fprintf(stderr, "Warning: failed to log cycle start.\n");
        }

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            printf("Activating relay %d (GPIO%u) for %d seconds...\n",
                   i + 1, relay_pins[i], RELAY_ACTIVE_TIME);
            fflush(stdout);

            if (activate_relay(lines[i], RELAY_ACTIVE_TIME) < 0) {
                fprintf(stderr, "Relay activation failed on GPIO%u.\n",
                        relay_pins[i]);
                goto cleanup;
            }
        }

        /*
         * Wait for the next full cycle.  Sleep in 60-second
         * increments so we can respond to signals promptly.
         */
        for (int s = 0; s < CYCLE_INTERVAL && g_running; s += POLL_INTERVAL)
            sleep(POLL_INTERVAL);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* De-energise all relays before releasing lines. */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            gpiod_line_set_value(lines[i], 1);
    }

    for (int i = 0; i < lines_acquired; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }

    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

