#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define STEP_DELAY 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void set_relay_intensity(int intensity) {
    if (intensity < 0) intensity = 0;
    if (intensity > PWM_RANGE) intensity = PWM_RANGE;

    gpioPWM(RELAY1_PIN, intensity);
    gpioPWM(RELAY2_PIN, intensity);
    gpioPWM(RELAY3_PIN, intensity);
    gpioPWM(RELAY4_PIN, intensity);
}

static void cleanup_gpio(void) {
    set_relay_intensity(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        return 1;
    }
    log_event("GPIO initialized successfully.");

    for (int i = 0; i <= SUNRISE_DURATION && running; i += STEP_DELAY) {
        int intensity = (int)(((float)i / SUNRISE_DURATION) * PWM_RANGE);
        set_relay_intensity(intensity);
        char log_message[128];
        snprintf(log_message, sizeof(log_message),
                 "Sunrise step %d/%d: intensity=%d",
                 i / STEP_DELAY + 1, SUNRISE_DURATION / STEP_DELAY, intensity);
        log_event(log_message);
        sleep(STEP_DELAY);
    }

    if (!running) {
        log_event("Received signal, shutting down gracefully.");
    }

    cleanup_gpio();
    log_event("GPIO cleaned up. Exiting.");
    return 0;
}

