        set_relay_intensity(intensity);
        char log_message[128];
        snprintf(log_message, sizeof(log_message),
                 "Sunrise step %d/%d: intensity=%d",
                 i / STEP_DELAY + 1, SUNRISE_DURATION / STEP_DELAY, intensity);
        log_event(log_message);
        sleep(STEP_DELAY);
    }

    if (!running) {
        log_event("Received signal, shutting down gracefully.");
    }

    cleanup_gpio();
    log_event("GPIO cleaned up. Exiting.");
    return 0;
}

