/*
 * MPU-6050 gyroscope reader with in-memory circular buffer
 * and LED threshold indicator for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   MPU-6050 VCC -> 3.3 V (Pin 1)
 *   MPU-6050 GND -> GND    (Pin 9)
 *   MPU-6050 SDA -> GPIO2  (Pin 3, I2C bus 1)
 *   MPU-6050 SCL -> GPIO3  (Pin 5, I2C bus 1)
 *   LED anode    -> GPIO17 (Pin 11) through 330 ohm resistor
 *   LED cathode  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c -lpigpio -lrt
 *   sudo ./mpu6050_gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (verified against ADI MPU-6050 datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_BUS         1

#define REG_SMPLRT_DIV      0x19
#define REG_PWR_MGMT_1      0x6B
#define REG_GYRO_CONFIG     0x1B
#define REG_GYRO_XOUT_H     0x43

#define GYRO_FS_SEL_250DPS  0x00
#define GYRO_FS_SEL_500DPS  0x01
#define GYRO_FS_SEL_1000DPS 0x02
#define GYRO_FS_SEL_2000DPS 0x03

#define PWR_SLEEP_BIT       0x40   /* bit 6: sleep mode */
#define PWR_RESET_BIT       0x80   /* bit 7: reset device */

#define SAMPLE_PERIOD_US    50000  /* 20 Hz */
#define BUFFER_SIZE         100
#define GYRO_THRESHOLD      250.0f /* deg/s */

/* ---- Data structures ---- */
typedef struct {
    double timestamp;
    float  x;
    float  y;
    float  z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static int  g_led_pin    = 17;
static int  g_i2c_bus    = MPU6050_BUS;
static int  g_mpu_addr   = MPU6050_ADDR;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void cleanup(void);
static int  init_mpu6050(void);
static int  read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(circular_buffer_t *buf, gyro_data_t d);
static void check_threshold(float x, float y, float z);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(g_led_pin, 0);
    gpioTerminate();
}

/* ---- Initialize MPU-6050 ---- */
static int init_mpu6050(void)
{
    /* Wake up: clear sleep bit, use internal 8 MHz oscillator */
    if (i2cWriteByteData(g_i2c_handle, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050 (PWR_MGMT_1)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Configure gyro full-scale range (FS_SEL = 0 -> +/- 250 deg/s) */
    if (i2cWriteByteData(g_i2c_handle, REG_GYRO_CONFIG,
                         GYRO_FS_SEL_250DPS) < 0) {
        fprintf(stderr, "Error: failed to configure GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* ---- Read gyroscope data (raw -> deg/s) ---- */
static int read_gyro_data(float *x, float *y, float *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(g_i2c_handle, REG_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyroscope data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /*
     * FS_SEL = 0 -> 131 LSB/deg/s.
     * For FS_SEL = 1, 65 LSB/deg/s; for 2, 32.8 LSB/deg/s;
     * for 3, 16.4 LSB/deg/s.
     */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* ---- Add data to circular buffer ---- */
static void add_to_buffer(circular_buffer_t *buf, gyro_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

/* ---- Threshold check and LED control ---- */
static void check_threshold(float x, float y, float z)
{
    if (fabsf(x) > GYRO_THRESHOLD ||
        fabsf(y) > GYRO_THRESHOLD ||
        fabsf(z) > GYRO_THRESHOLD) {
        gpioWrite(g_led_pin, 1);
    } else {
        gpioWrite(g_led_pin, 0);
    }
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "a:b:l:")) != -1) {
        switch (opt) {
        case 'a': g_mpu_addr = (int)strtol(optarg, NULL, 0); break;
        case 'b': g_i2c_bus  = (int)strtol(optarg, NULL, 0); break;
        case 'l': g_led_pin  = (int)strtol(optarg, NULL, 0); break;
        default:
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-b i2c_bus] [-l led_pin]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(g_led_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", g_led_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(g_led_pin, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(g_i2c_bus, g_mpu_addr, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at addr 0x%02X (err=%d)\n",
                g_i2c_bus, g_mpu_addr, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Circular buffer */
    circular_buffer_t gyro_buffer = {0};

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) == 0) {
            gyro_data_t d;
            d.timestamp = time_time();
            d.x = x;
            d.y = y;
            d.z = z;
            add_to_buffer(&gyro_buffer, d);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Warning: I2C read failed, attempting re-init...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            int retries = 3;
            bool reinit_ok = false;
            while (retries > 0 && !reinit_ok) {
                gpioDelay(100000); /* 100 ms backoff */
                g_i2c_handle = i2cOpen(g_i2c_bus, g_mpu_addr, 0);
                if (g_i2c_handle >= 0) {
                    if (init_mpu6050() == 0) {
                        reinit_ok = true;
                    } else {
                        i2cClose(g_i2c_handle);
                        g_i2c_handle = -1;
                    }
                }
                retries--;
            }
            if (!reinit_ok) {
                fprintf(stderr, "Error: I2C re-initialisation failed after retries\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

