/*
 * MPU-9250 Gyroscope SPI Reader for Raspberry Pi 4 Model B
 *
 * Reads X, Y, and Z angular rates from an MPU-9250 over SPI using
 * spidev (/dev/spidev0.0) and manual chip-select via libgpiod on
 * /dev/gpiochip0 line offset 8 (BCM GPIO8).
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c -lgpiod
 * Run:    ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8          /* BCM GPIO8 */
#define SPI_SPEED_HZ    1000000    /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_DELAY_MS 10
#define MAX_RETRIES     3

/* MPU-9250 registers */
#define MPU9250_ADDR_GXST1   0x3B
#define MPU9250_ADDR_GYST1   0x3C
#define MPU9250_ADDR_GZST1   0x3D
#define MPU9250_ADDR_GXST2   0x3E
#define MPU9250_ADDR_GYST2   0x3F
#define MPU9250_ADDR_GZST2   0x40

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit gyro rate register pair.
 * Returns 0 on success, -1 on error.
 */
static int read_gyro_rate(int fd, struct gpiod_line *cs, uint8_t addr,
                          int16_t *rate)
{
    uint8_t tx[3] = { addr | 0x80, 0x00, 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr;
    int retries = 0;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    /* Assert chip select (active low) */
    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(0) failed: %s\n",
                strerror(errno));
        return -1;
    }

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) >= 0)
            break;
        retries++;
        if (retries < MAX_RETRIES)
            usleep(1000);
    }

    /* Deassert chip select */
    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(1) failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "SPI read failed after %d retries (reg 0x%02X)\n",
                MAX_RETRIES, addr);
        return -1;
    }

    /* rx[0] = dummy, rx[1] = MSB, rx[2] = LSB */
    *rate = (int16_t)((rx[1] << 8) | rx[2]);
    return 0;
}

static int get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    size_t used = strlen(buf);
    int remaining = (int)(len - used);
    if (remaining <= 10) {
        fprintf(stderr, "timestamp buffer too small\n");
        return -1;
    }

    snprintf(buf + used, (size_t)remaining, ".%09ld", ts.tv_nsec);
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open SPI device */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and request chip-select line */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging MPU-9250 gyro data to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int16_t x_rate = 0, y_rate = 0, z_rate = 0;
        char timestamp[40];
        int err = 0;

        if (read_gyro_rate(fd, cs, MPU9250_ADDR_GXST1, &x_rate) < 0)
            err = 1;
        if (read_gyro_rate(fd, cs, MPU9250_ADDR_GYST1, &y_rate) < 0)
            err = 1;
        if (read_gyro_rate(fd, cs, MPU9250_ADDR_GZST1, &z_rate) < 0)
            err = 1;

        if (err) {
            fprintf(stderr, "Gyro read error — continuing\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        if (get_timestamp(timestamp, sizeof(timestamp)) < 0) {
            fprintf(stderr, "Timestamp error — continuing\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x_rate, y_rate,
                     z_rate) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
            break;
        }

        if (fflush(log_file) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            break;
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file)
        fclose(log_file);
    if (cs)
        gpiod_line_release(cs);
    if (chip)
        gpiod_chip_close(chip);
    if (fd >= 0)
        close(fd);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

