    char tx[7] = { (char)(GYRO_XOUT_H | 0x80), 0, 0, 0, 0, 0, 0 };
    char rx[7] = { 0 };

    if (spiXfer(g_spi_handle, tx, rx, 7) != 7) {
        fprintf(stderr, "SPI transfer failed reading gyro data\n");
        return -1;
    }

    *x = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    *y = (int16_t)(((uint8_t)rx[3] << 8) | (uint8_t)rx[4]);
    *z = (int16_t)(((uint8_t)rx[5] << 8) | (uint8_t)rx[6]);
    return 0;
}

/* --------------------------- Circular buffer ----------------------------- */
static void add_to_buffer(struct timespec ts, int16_t x, int16_t y, int16_t z)
{
    g_buffer.data[g_buffer.head].timestamp = ts;
    g_buffer.data[g_buffer.head].x         = x;
    g_buffer.data[g_buffer.head].y         = y;
    g_buffer.data[g_buffer.head].z         = z;

    g_buffer.head = (g_buffer.head + 1) % BUFFER_SIZE;
    if (g_buffer.count < BUFFER_SIZE)
        g_buffer.count++;
}

static void print_buffer(void)
{
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < g_buffer.count; i++) {
        int idx = (g_buffer.head - g_buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld.%09ld,%d,%d,%d\n",
               (long)g_buffer.data[idx].timestamp.tv_sec,
               g_buffer.data[idx].timestamp.tv_nsec,
               g_buffer.data[idx].x,
               g_buffer.data[idx].y,
               g_buffer.data[idx].z);
    }
}

/* -------------------------------- Blink ---------------------------------- */
static void blink_warning(void)
{
    gpioWrite(LED_PIN, 1);
    gpioDelay(BLINK_MS * 1000);   /* gpioDelay takes microseconds */
    gpioWrite(LED_PIN, 0);
    gpioDelay(BLINK_MS * 1000);
}

/* ------------------------------ Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint8_t whoami = 0;
    if (spi_read_register(WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wake up MPU6050 (clear sleep bit) */
    if (spi_write_register(PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000);  /* 10 ms settle */

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU6050 monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_gyro_data(&x, &y, &z) != 0) {
            fprintf(stderr, "Sensor read error; continuing...\n");
            gpioDelay(SAMPLE_MS * 1000);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        add_to_buffer(ts, x, y, z);

        /* Threshold check */
        if (fabs((double)x) > THRESHOLD ||
            fabs((double)y) > THRESHOLD ||
            fabs((double)z) > THRESHOLD) {
            blink_warning();
        }

        gpioDelay(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

