/*
 * MPU-6050 Tilt Monitor for Raspberry Pi 4 Model B
 *
 * Reads roll and pitch from an MPU-6050 on I2C bus 1 (address 0x68),
 * logs them to tilt_log.txt, and illuminates an LED on GPIO21 when
 * tilt exceeds 45 degrees.
 *
 * Build:  gcc -O2 -Wall -o tilt_monitor tilt_monitor.c -lm -lpigpio -lrt
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (per datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_BUS         1

#define REG_SMPLRT_DIV      0x19
#define REG_PWR_MGMT_1      0x6B
#define REG_ACCEL_XOUT_H    0x3B
#define REG_ACCEL_YOUT_H    0x3D
#define REG_ACCEL_ZOUT_H    0x3F

#define ACCEL_SCALE         16384.0f   /* LSB per °/s at ±2g range */

/* ---- Application constants ---- */
#define LED_PIN             21
#define TILT_THRESHOLD      45.0f      /* degrees */
#define SAMPLE_PERIOD_US    100000     /* 100 ms */
#define LOG_FILE            "tilt_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPU-6050 register.                             */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(g_i2c_handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from two consecutive registers.      */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int mpu_read_reg16(uint8_t reg_high, int16_t *out)
{
    int hi = i2cReadByteData(g_i2c_handle, reg_high);
    if (hi < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg_high);
        return -1;
    }
    int lo = i2cReadByteData(g_i2c_handle, reg_high + 1);
    if (lo < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg_high + 1);
        return -1;
    }
    *out = (int16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050: wake it, set sample rate divider.          */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int mpu_init(void)
{
    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (mpu_write_reg(REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    gpioDelay(10000);  /* allow oscillator to stabilise (~10 ms) */

    /* Set sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_reg(REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all three accelerometer axes in one go.                       */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int read_accel(int16_t *ax, int16_t *ay, int16_t *az)
{
    if (mpu_read_reg16(REG_ACCEL_XOUT_H, ax) < 0) return -1;
    if (mpu_read_reg16(REG_ACCEL_YOUT_H, ay) < 0) return -1;
    if (mpu_read_reg16(REG_ACCEL_ZOUT_H, az) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw LSB values to degrees per second.                      */
/* ------------------------------------------------------------------ */
static void accel_to_dps(int16_t ax, int16_t ay, int16_t az,
                         float *roll, float *pitch)
{
    float x = (float)ax / ACCEL_SCALE;
    float y = (float)ay / ACCEL_SCALE;
    float z = (float)az / ACCEL_SCALE;

    *roll  = atan2f(y, z) * 180.0f / (float)M_PI;
    *pitch = atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / (float)M_PI;
}

/* ------------------------------------------------------------------ */
/* Append a CSV line to the log file.                                  */
/* ------------------------------------------------------------------ */
static void log_data(float roll, float pitch)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(MPU6050_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                MPU6050_BUS, MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (mpu_init() < 0) {
        fprintf(stderr, "[FATAL] MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 tilt monitor running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t ax, ay, az;

        if (read_accel(&ax, &ay, &az) < 0) {
            fprintf(stderr, "[WARN] Accelerometer read failed; skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float roll, pitch;
        accel_to_dps(ax, ay, az, &roll, &pitch);

        printf("Roll: %7.2f  Pitch: %7.2f\n", roll, pitch);

        bool tilt_exceeded = (fabsf(roll) > TILT_THRESHOLD) ||
                             (fabsf(pitch) > TILT_THRESHOLD);
        gpioWrite(LED_PIN, tilt_exceeded ? 1 : 0);

        log_data(roll, pitch);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

