#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x26
#define REG_COMMAND 0x30

#define CMD_RESET 0x01
#define CMD_PS_FORCE 0x05
#define CMD_ALS_FORCE 0x06

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Part ID 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x00) < 0) return -1;
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_PS_FORCE) < 0) return -1;
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;
