/*
 * ADXRS290 dual-axis gyroscope SPI reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   ADXRS290 CS  -> GPIO8  (BCM 8, CE0)
 *   ADXRS290 SCLK-> GPIO11 (BCM 11)
 *   ADXRS290 DOUT-> GPIO9  (BCM 9, MISO)
 *   ADXRS290 DIN -> GPIO10 (BCM 10, MOSI)
 *   ADXRS290 VDD -> 3.3 V
 *   ADXRS290 GND -> GND
 *
 * SPI: channel 0, CE0, 1 MHz, mode 0 (CPOL=0, CPHA=0).
 *
 * Build: gcc -O2 -Wall -o gyro_reader gyro_reader.c -lpigpio -lrt
 * Run:   sudo ./gyro_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- ADXRS290 register map (datasheet) ---- */
#define ADXRS290_REG_XGYRO_OUT  0x00
#define ADXRS290_REG_YGYRO_OUT  0x02
#define ADXRS290_REG_TEMP_OUT   0x04
#define ADXRS290_REG_WHO_AM_I   0x0C
#define ADXRS290_REG_WHO_AM_I_VAL 0x00
#define ADXRS290_REG_CTRL_REG1  0x10
#define ADXRS290_REG_CTRL_REG2  0x11
#define ADXRS290_REG_CTRL_REG3  0x12
#define ADXRS290_REG_CTRL_REG4  0x13
#define ADXRS290_REG_CTRL_REG5  0x14

/* Read bit (MSB) for all ADXRS290 register reads */
#define ADXRS290_READ_BIT       0x80

/* SPI configuration */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000   /* 1 MHz */
#define SPI_FLAGS      0         /* mode 0, active-low CE */

/* Sampling */
#define SAMPLE_PERIOD_US 10000  /* 10 ms -> ~100 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* ---- Globals for cleanup ---- */
static int  spi_handle = -1;
static FILE *csv_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- SPI helpers ---- */

/*
 * Read a single register from the ADXRS290.
 * Returns 0 on success and stores the byte in *value;
 * returns -1 on SPI transfer failure.
 */
static int adxrs290_read_reg(uint8_t reg, uint8_t *value)
{
    char tx[2], rx[2];
    tx[0] = (char)(reg | ADXRS290_READ_BIT);
    tx[1] = 0x00;                       /* dummy to clock out data */

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

/*
 * Write a single register to the ADXRS290.
 * Returns 0 on success, -1 on failure.
 */
static int adxrs290_write_reg(uint8_t reg, uint8_t value)
{
    char tx[2], rx[2];
    tx[0] = (char)(reg & ~ADXRS290_READ_BIT);
    tx[1] = (char)value;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Initialise the ADXRS290: verify device identity and configure
 * the control registers.  Returns 0 on success, -1 on failure.
 */
static int adxrs290_init(void)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (adxrs290_read_reg(ADXRS290_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != ADXRS290_REG_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, ADXRS290_REG_WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL_REG1 (0x10):
     *   ODR[3:0] = 0x07  -> 100 Hz output data rate
     *   MOD[1:0] = 0x00  -> normal mode
     *   bits[7:4] = 0x00
     * Result: 0x70
     */
    if (adxrs290_write_reg(ADXRS290_REG_CTRL_REG1, 0x70) != 0)
        return -1;

    /*
     * CTRL_REG2 (0x11):
     *   FULL_RES = 1  -> full resolution mode (12-bit)
     *   bits[7:1] = 0
     * Result: 0x80
     */
    if (adxrs290_write_reg(ADXRS290_REG_CTRL_REG2, 0x80) != 0)
        return -1;

    /*
     * CTRL_REG3 (0x12):
     *   LPF_EN = 1  -> low-pass filter enabled
     *   bits[7:1] = 0
     * Result: 0x80
     */
    if (adxrs290_write_reg(ADXRS290_REG_CTRL_REG3, 0x80) != 0)
        return -1;

    /*
     * CTRL_REG4 (0x13):
     *   FS[1:0] = 0x01  -> +/- 250 dps full scale
     *   bits[7:2] = 0
     * Result: 0x04
     */
    if (adxrs290_write_reg(ADXRS290_REG_CTRL_REG4, 0x04) != 0)
        return -1;

    /*
     * CTRL_REG5 (0x14):
     *   FIFO_EN = 0  -> FIFO disabled
     *   bits[7:0] = 0
     * Result: 0x00
     */
    if (adxrs290_write_reg(ADXRS290_REG_CTRL_REG5, 0x00) != 0)
        return -1;

    return 0;
}

/*
 * Read a 16-bit signed rate from a given register (X or Y).
 * The ADXRS290 returns the most-significant byte first, so we
 * read the first byte (address | RD bit), then the second byte.
 * Returns 0 on success and stores the signed value in *rate;
 * returns -1 on SPI failure.
 */
static int adxrs290_read_rate(uint8_t reg, int16_t *rate)
{
    uint8_t msb = 0, lsb = 0;

    if (adxrs290_read_reg(reg, &msb) != 0)
        return -1;
    if (adxrs290_read_reg((uint8_t)(reg + 1), &lsb) != 0)
        return -1;

    *rate = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* ---- CSV logging ---- */
static int log_data(int16_t x_rate, int16_t y_rate)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    if (fprintf(csv_file, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(csv_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    int reinit_attempts = 0;

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise ADXRS290 */
    if (adxrs290_init() != 0) {
        fprintf(stderr, "ADXRS290 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    csv_file = fopen("gyro_data.csv", "w");
    if (csv_file == NULL) {
        perror("fopen gyro_data.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fprintf(csv_file, "timestamp_s,x_rate,y_rate\n") < 0) {
        perror("fprintf header");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(csv_file) != 0) {
        perror("fflush header");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 logging started. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0;

        if (adxrs290_read_rate(ADXRS290_REG_XGYRO_OUT, &x_rate) != 0 ||
            adxrs290_read_rate(ADXRS290_REG_YGYRO_OUT, &y_rate) != 0) {

            fprintf(stderr, "Read error; attempting re-initialisation (%d/%d)...\n",
                    reinit_attempts + 1, MAX_REINIT_ATTEMPTS);

            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                reinit_attempts++;
                gpioDelay(100000); /* 100 ms back-off */
                spiClose(spi_handle);
                spi_handle = -1;
                gpioDelay(100000); /* 100 ms before retry */
                spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
                if (spi_handle < 0) {
                    fprintf(stderr, "SPI re-open failed: %s\n",
                            pigpio_error(spi_handle));
                } else if (adxrs290_init() != 0) {
                    fprintf(stderr, "ADXRS290 re-init failed\n");
                } else {
                    reinit_attempts = 0;
                    continue; /* success: restart sampling */
                }
            }
            fprintf(stderr, "Persistent SPI failure; exiting.\n");
            break;
        }

        if (log_data(x_rate, y_rate) != 0) {
            fprintf(stderr, "CSV logging failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

