#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define ALERT_DURATION_MS 2000
#define THRESHOLD_MS      500
#define LOG_FILE_NAME     "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_seismic_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set alert pin HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set alert pin LOW\n");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)userdata;
    static uint32_t last_tick_1 = 0;
    static uint32_t last_tick_2 = 0;
    static int      high_count_1 = 0;
    static int      high_count_2 = 0;
    static int      alert_active = 0;

    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            high_count_1++;
            if (high_count_1 >= THRESHOLD_MS / 10) {
                if (!alert_active) {
                    alert_active = 1;
                    log_seismic_event();
                    trigger_alert();
                }
            }
        } else if (level == 0) {
            high_count_1 = 0;
            alert_active = 0;
        }
        last_tick_1 = tick;
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            high_count_2++;
            if (high_count_2 >= THRESHOLD_MS / 10) {
                if (!alert_active) {
                    alert_active = 1;
                    log_seismic_event();
                    trigger_alert();
                }
            }
        } else if (level == 0) {
            high_count_2 = 0;
            alert_active = 0;
        }
        last_tick_2 = tick;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN mode\n");
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN mode\n");
        goto cleanup;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set ALERT_PIN mode\n");
        goto cleanup;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on SENSOR_1_PIN\n");
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on SENSOR_2_PIN\n");
        goto cleanup;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize ALERT_PIN LOW\n");
        goto cleanup;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for SENSOR_1_PIN\n");
        goto cleanup;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for SENSOR_2_PIN\n");
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Seismic monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

