code:
/*
 * ADXRS290 dual-axis MEMS gyroscope X-axis angular rate reader
 * Raspberry Pi Zero W  |  SPI0  |  CE0  |  1 MHz  |  Mode 0
 *   CE  -> GPIO8  (BCM)
 *   SCLK-> GPIO11 (BCM)
 *   MOSI-> GPIO10 (BCM)
 *   MISO-> GPIO9  (BCM)
 *
 * LED indicator on GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_x gyro_x.c -lpigpio -lpthread -lrt
 * Run:    sudo ./gyro_x
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0                                */
#define SPI_SPEED      1000000    /* 1 MHz                                   */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                   */

#define LED_PIN        17         /* BCM 17                                  */
#define THRESHOLD_DPS  20.0       /* deg/s                                   */
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD  100000     /* microseconds (100 ms)                   */

/* ADXRS290 register addresses (8-bit, MSB = 0 = write, MSB = 1 = read)     */
#define REG_X_AXIS_OUT 0x80       /* X-axis angular rate output (read)       */
#define REG_TEMP_OUT   0x81       /* Temperature output (read)              */
#define REG_DEVICE_ID  0x8C       /* Device ID (read)                        */
#define REG_POWER_MGMT 0x00       /* Power management / sleep               */

/* ADXRS290 device ID expected in upper nibble of first byte of REG_DEVICE_ID */
#define ADXRS290_DEVID 0x0C

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    struct timespec timestamp;
    float           rate_dps;
} gyro_data_t;

typedef struct {
    gyro_data_t  data[BUFFER_SIZE];
    int          head;
    int          tail;
    int          count;
    pthread_mutex_t lock;
} circular_buffer_t;

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static bool     g_pigpio_inited = false;
static circular_buffer_t g_buffer;

/* ----------------------------- Prototypes -------------------------------- */
static int  spi_read_register(uint8_t reg, uint8_t *value);
static int  spi_write_register(uint8_t reg, uint8_t value);
static int  read_gyro_x_axis(float *rate_dps);
static void buffer_init(circular_buffer_t *buf);
static void buffer_add(circular_buffer_t *buf, gyro_data_t d);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI helpers ------------------------------- */
/*
 * Read a single register from the ADXRS290.
 * The ADXRS290 SPI protocol: transmit the 8-bit address with MSB=1 (read),
 * then a dummy byte to clock out the data payload.
 */
static int spi_read_register(uint8_t reg, uint8_t *value)
{
    if (value == NULL) {
        fprintf(stderr, "spi_read_register: NULL value pointer\n");
        return -1;
    }

    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spi_read_register: spiXfer failed (ret=%d)\n", ret);
        return -1;
    }

    *value = (uint8_t)rx[1];
    return 0;
}

/*
 * Write a single register to the ADXRS290.
 * The ADXRS290 SPI protocol: transmit the 8-bit address with MSB=0 (write),
 * then the data byte.
 */
static int spi_write_register(uint8_t reg, uint8_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spi_write_register: spiXfer failed (ret=%d)\n", ret);
        return -1;
    }
    return 0;
}

/*
 * Read the X-axis angular rate (degrees per second).
 * The ADXRS290 outputs 12-bit two's-complement data in two consecutive
 * registers (X_AXIS_OUT_H, X_AXIS_OUT_L).  The LSB resolution is 0.061 deg/s.
 */
static int read_gyro_x_axis(float *rate_dps)
{
    uint8_t hi, lo;

    if (spi_read_register(REG_X_AXIS_OUT, &hi) != 0)
        return -1;
    if (spi_read_register(REG_X_AXIS_OUT + 1, &lo) != 0)
        return -1;

    int16_t raw = (int16_t)(((uint16_t)hi << 8) | (uint16_t)lo);
    /* Sign-extend 12-bit two's complement to 16-bit */
    if (raw & 0x0800)
        raw |= 0xF000;

    *rate_dps = (float)raw * 0.061f;
    return 0;
}

/* ----------------------------- Circular Buffer --------------------------- */
static void buffer_init(circular_buffer_t *buf)
{
    buf->head  = 0;
    buf->tail  = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->lock, NULL);
}

static void buffer_add(circular_buffer_t *buf, gyro_data_t d)
{
    pthread_mutex_lock(&buf->lock);
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE)
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;   /* overwrite oldest */
    else
        buf->count++;
    pthread_mutex_unlock(&buf->lock);
}

/* ----------------------------- Signal / Cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
