/*
 * Smart sunset simulator for Raspberry Pi Zero W.
 *
 * Three relay-controlled dimmable lamps are controlled via hardware PWM
 * on BCM GPIO17, GPIO18, and GPIO27.  Each lamp fades from full brightness
 * (100 % duty cycle) to off over a user-supplied total duration (seconds).
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunset sunset.c -lpigpio -lrt
 * Run:    ./sunset <duration_seconds>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_LAMPS        3
#define PWM_FREQUENCY    100          /* Hz  */
#define PWM_RANGE        255          /* duty-cycle steps 0..255 */
#define FADE_STEP_US     10000        /* 10 ms per brightness step */
#define FADE_STEP_DUTY   4            /* 4 % per step */

static const int lamp_pins[NUM_LAMPS] = {17, 18, 27};

static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static void cleanup_lamps(void)
{
    for (int i = 0; i < NUM_LAMPS; i++)
        gpioPWM(lamp_pins[i], 0);
}

/*
 * Fade a lamp from current duty cycle `start` to `end` over `duration_us`
 * microseconds.  Returns the final duty cycle reached, or -1 on error.
 */
static int fade_lamp(int pin, int start, int end, uint32_t duration_us)
{
    if (start < 0 || start > PWM_RANGE || end < 0 || end > PWM_RANGE) {
        fprintf(stderr, "Error: duty cycle out of range on pin %d\n", pin);
        return -1;
    }

    if (gpioPWM(pin, start) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }

    int current = start;
    int step    = (end > start) ? FADE_STEP_DUTY : -FADE_STEP_DUTY;
    uint32_t step_us = (duration_us / abs(end - start)) / FADE_STEP_DUTY;

    if (step_us < FADE_STEP_US)
        step_us = FADE_STEP_US;

    for (int i = 0; i < abs(end - start) && !g_terminate; i++) {
        current += step;
        if (gpioPWM(pin, current) < 0) {
            fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
            return -1;
        }
        usleep(step_us);
    }

    if (gpioPWM(pin, end) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }

    return end;
}

/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: duration must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM on each lamp pin */
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (gpioSetMode(lamp_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", lamp_pins[i]);
            cleanup_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(lamp_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", lamp_pins[i]);
            cleanup_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(lamp_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", lamp_pins[i]);
            cleanup_lamps();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Sunset simulator started.  Lamps fade from 100%% to 0%% over %ld s.\n", duration);
    printf("Press Ctrl+C to stop prematurely.\n");
    fflush(stdout);

    uint32_t total_us = (uint32_t)duration * 1000000UL;
    uint32_t per_lamp_us = total_us / NUM_LAMPS;

    int exit_code = EXIT_SUCCESS;

    for (int i = 0; i < NUM_LAMPS && !g_terminate; i++) {
        printf("Fading lamp %d (pin %d)...\n", i + 1, lamp_pins[i]);
        fflush(stdout);

        if (fade_lamp(lamp_pins[i], PWM_RANGE, 0, per_lamp_us) < 0) {
            fprintf(stderr, "Error: fade failed on lamp %d (pin %d).\n",
                    i + 1, lamp_pins[i]);
            exit_code = EXIT_FAILURE;
            break;
        }

        printf("Lamp %d faded to 0%%.\n", i + 1);
        fflush(stdout);
    }

    if (g_terminate) {
        printf("\nCaught termination signal. Shutting down gracefully...\n");
        exit_code = EXIT_SUCCESS;
    } else {
        printf("Sunset sequence complete. All lamps off.\n");
    }

    cleanup_lamps();
    gpioTerminate();
    return exit_code;
}

