#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define LOG_FILE "touch_relay.log"
#define DEBOUNCE_MS 100
#define POLL_MS 10

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0RFR 0x3B
#define MPR121_E0SRFR 0x3C
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, val, rc);
        log_error(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_E0RFR, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_E0SRFR, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_ECR, 0x8C) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (rc != 2) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: rc=%d", rc);
        log_error(msg);
        return -1;
    }
    *status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set relay GPIO mode");
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C bus 1 at 0x%02X: %d", MPR121_ADDR, i2c_handle);
        log_error(msg);
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        log_error("MPR121 initialization failed");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    uint32_t last_touch_ms = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(10000);
            continue;
        }

        uint32_t now_ms = gpioTick() / 1000;
        if (touch_status & 0x01) {
            if (now_ms - last_touch_ms > DEBOUNCE_MS) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                    log_error("Failed to write relay GPIO");
                }
                last_touch_ms = now_ms;
            }
        }
        gpioDelay(POLL_MS * 1000);
    }

    cleanup();
    return 0;
}

