#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN       18
#define LED_PIN          23
#define LOG_FILE         "flame_log.txt"
#define POLL_DELAY_US    50000   /* 50 ms */
#define CONFIRM_READINGS 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[64];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int control_outputs(int flame_detected)
{
    if (gpioWrite(BUZZER_PIN, flame_detected) < 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN) failed\n");
        return -1;
    }
    if (gpioWrite(LED_PIN, flame_detected) < 0) {
        fprintf(stderr, "gpioWrite(LED_PIN) failed\n");
        return -1;
    }
    return 0;
}

static int setup_gpio(void)
{
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FLAME_SENSOR_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN) failed\n");
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        return -1;
    }

    /* Ensure outputs start in a safe (off) state */
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN, 0) failed\n");
        return -1;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    /* Turn off outputs before releasing */
    if (gpioInitialise() >= 0) {
        gpioWrite(BUZZER_PIN, 0);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

int main(void)
{
    int flame_count = 0;
    int flame_detected = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(FLAME_SENSOR_PIN) failed\n");
            break;
        }

        /* KY-026 digital output is active LOW: 0 = flame detected */
        if (level == 0) {
            flame_count++;
            if (flame_count >= CONFIRM_READINGS && !flame_detected) {
                if (log_event("Flame Detected") != 0) {
                    fprintf(stderr, "Failed to log flame detection event\n");
                }
                if (control_outputs(1) != 0) {
                    fprintf(stderr, "Failed to activate outputs\n");
                }
                flame_detected = 1;
            }
        } else {
            flame_count = 0;
            if (flame_detected) {
                if (control_outputs(0) != 0) {
                    fprintf(stderr, "Failed to deactivate outputs\n");
                }
                flame_detected = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

