#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define KP 1.0
#define KI 0.01
#define KD 0.1

#define OBSTACLE_THRESHOLD 20.0
#define PID_LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int motor_pins[] = {MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_B_FORWARD, MOTOR_B_BACKWARD, MOTOR_A_ENABLE, MOTOR_B_ENABLE};
    for (size_t i = 0; i < sizeof(motor_pins) / sizeof(motor_pins[0]); i++) {
        if (gpioSetMode(motor_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", motor_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(MOTOR_A_ENABLE, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_ENABLE, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_ENABLE, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_ENABLE, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(MOTOR_A_ENABLE, 1) != 0 || gpioWrite(MOTOR_B_ENABLE, 1) != 0) {
        fprintf(stderr, "Error: failed to enable PWM outputs.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(MOTOR_A_ENABLE, -motor_a_speed);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, 0);
    }

    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(MOTOR_B_ENABLE, -motor_b_speed);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, 0);
    }
}

static void stop_motors(void) {
    set_motor_speed(0, 0);
}

static float generate_tilt_error(void) {
