    int motor_pins[] = {MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_B_FORWARD, MOTOR_B_BACKWARD, MOTOR_A_ENABLE, MOTOR_B_ENABLE};
    for (size_t i = 0; i < sizeof(motor_pins) / sizeof(motor_pins[0]); i++) {
