/*
 * TTP223 Capacitive Touch Sensor -> Active-HIGH Relay Toggle
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP223 digital output -> GPIO4 (BCM 4, physical pin 7)
 * Relay:  Active-HIGH relay module -> GPIO17 (BCM 17, physical pin 11)
 *
 * Behavior:
 *   - Pull-down is applied to GPIO4 so the sensor's open-collector output
 *     is stable when no touch is present.
 *   - On a rising edge (touch detected) the relay state is toggled.
 *   - A 50 ms debounce delay is enforced after each detection.
 *   - SIGINT / SIGTERM triggers graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4   /* BCM 4, physical pin 7  */
#define RELAY_PIN        17  /* BCM 17, physical pin 11 */
#define DEBOUNCE_US      50000  /* 50 ms debounce            */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure the two GPIO pins.                  */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /*
     * TTP223 has an open-collector output.  Applying a pull-down
     * ensures the line is defined when the sensor is idle.
     */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with the relay in the OFF state (active-high). */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n",
                RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Toggle the relay and log the new state.                             */
/* ------------------------------------------------------------------ */
static void toggle_relay(void)
{
    int level = gpioRead(RELAY_PIN);
    if (level < 0) {
        fprintf(stderr, "Warning: gpioRead failed on GPIO%d; skipping toggle.\n",
                RELAY_PIN);
        return;
    }

    int new_level = (level == 0) ? 1 : 0;
    if (gpioWrite(RELAY_PIN, new_level) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed on GPIO%d.\n",
                RELAY_PIN);
        return;
    }

    printf("Touch detected! Relay toggled to %s.\n",
           new_level ? "ON" : "OFF");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started.\n");
    printf("  Sensor : GPIO%d (BCM)\n", TOUCH_SENSOR_PIN);
    printf("  Relay  : GPIO%d (BCM)\n", RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial gpioRead failed on GPIO%d.\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n",
                    TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: touch just appeared. */
        if (current_state == 1 && last_state == 0) {
            toggle_relay();
            gpioDelay(DEBOUNCE_US);   /* 50 ms debounce */
        }

        last_state = current_state;
        gpioDelay(10000);             /* 10 ms poll interval */
    }

    /* Clean up: ensure relay is OFF and release pigpio resources. */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

