#ifdef ALSA_AVAILABLE
    int err;

    err = snd_pcm_open(&g_pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: cannot open audio device: %s\n",
                snd_strerror(err));
        cleanup();
        return EXIT_FAILURE;
    }

