                                                 &period_size, NULL);
    if (err < 0) {
        fprintf(stderr, "Error: cannot set period size: %s\n",
                snd_strerror(err));
        cleanup();
        return EXIT_FAILURE;
    }

    err = snd_pcm_hw_params(g_pcm, g_hw_params);
    if (err < 0) {
        fprintf(stderr, "Error: cannot apply hardware parameters: %s\n",
                snd_strerror(err));
        cleanup();
        return EXIT_FAILURE;
    }

    err = snd_pcm_prepare(g_pcm);
    if (err < 0) {
        fprintf(stderr, "Error: cannot prepare audio interface: %s\n",
                snd_strerror(err));
        cleanup();
        return EXIT_FAILURE;
    }

    err = snd_pcm_start(g_pcm);
    if (err < 0) {
        fprintf(stderr, "Error: cannot start audio stream: %s\n",
                snd_strerror(err));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio capture started: %u Hz, %d-bit, %d channel(s), period %lu frames\n",
           rate, 16, NUM_CHANNELS, (unsigned long)period_size);
#else
    printf("ALSA not available; simulating audio input at %d Hz\n", SAMPLE_RATE);
#endif

