    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop -------------------------------------------------- */
    short *buffer = malloc((size_t)BUFFER_SIZE * sizeof(short));
    if (!buffer) {
        fprintf(stderr, "Error: cannot allocate audio buffer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
#ifdef ALSA_AVAILABLE
        snd_pcm_sframes_t frames = snd_pcm_readi(g_pcm, buffer, BUFFER_SIZE);
        if (frames < 0) {
            fprintf(stderr, "Error: read from audio interface: %s\n",
