 * mood_light.c — Audio-reactive RGB mood light for Raspberry Pi 3 Model B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lm -lpigpio -lasound
 * Run:    sudo ./mood_light [sensitivity_scale]
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - Common-cathode RGB LED
 *     Red   -> GPIO17 (BCM)
 *     Green -> GPIO18 (BCM)
 *     Blue  -> GPIO27 (BCM)
 *   - Software PWM via pigpio (current-limiting resistors assumed)
 *   - Audio input via ALSA on "default" device at 8000 Hz, 16-bit mono
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_RANGE  255
#define PWM_FREQ   1000   /* Hz */

#define SAMPLE_RATE   8000
#define BUFFER_SIZE   1024
#define NUM_CHANNELS  1

#define DEFAULT_SENSITIVITY 1.0

#define STATUS_INTERVAL_US 10000  /* 10 ms */

static volatile sig_atomic_t g_running = 1;

#ifdef ALSA_AVAILABLE
static snd_pcm_t *g_pcm = NULL;
static snd_pcm_hw_params_t *g_hw_params = NULL;
#endif

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* RGB LED control via pigpio software PWM                             */
/* ------------------------------------------------------------------ */
static void set_led_color(int red, int green, int blue)
{
    if (red   < 0) red   = 0; if (red   > PWM_RANGE) red   = PWM_RANGE;
    if (green < 0) green = 0; if (green > PWM_RANGE) green = PWM_RANGE;
    if (blue  < 0) blue  = 0; if (blue  > PWM_RANGE) blue  = PWM_RANGE;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

/* ------------------------------------------------------------------ */
/* Non-linear mapping of RMS to RGB                                    */
/* ------------------------------------------------------------------ */
static void map_rms_to_color(float rms, float sensitivity,
                             int *red, int *green, int *blue)
{
    float scaled = rms * sensitivity;

    if (scaled < 0.0f) scaled = 0.0f;
    if (scaled > 1.0f) scaled = 1.0f;

    /* Non-linear mapping: loud -> saturated colors, quiet -> black */
    float hue = 0.0f;
    if (scaled > 0.0f) {
        hue = 360.0f * (1.0f - scaled);   /* fade through rainbow */
    }

    float sat = 1.0f;
    float val = scaled;

    /* HSL -> RGB (clamped) */
    float r = 0.0f, g = 0.0f, b = 0.0f;
    float c = val * sat;
    float x = c * (1.0f - fabsf((hue / 60.0f) - 2.0f * floorf(hue / 360.0f)));
    float m = val - c;

    if (hue < 60.0f) { r = c; g = x; b = 0.0f; }
    else if (hue < 120.0f) { r = x; g = c; b = 0.0f; }
    else if (hue < 180.0f) { r = 0.0f; g = c; b = x; }
    else if (hue < 240.0f) { r = 0.0f; g = x; b = c; }
    else if (hue < 300.0f) { r = x; g = 0.0f; b = c; }
    else { r = c; g = 0.0f; b = x; }

    *red   = (int)((r + m) * PWM_RANGE);
    *green = (int)((g + m) * PWM_RANGE);
    *blue  = (int)((b + m) * PWM_RANGE);
}

/* ------------------------------------------------------------------ */
/* Simulated audio input (sine wave) for ALSA-less mode               */
/* ------------------------------------------------------------------ */
static void simulate_audio_input(short *buffer, int num_samples)
{
    static double phase = 0.0;
    const double freq = 100.0;   /* 100 Hz sine wave */
    const double step = (2.0 * M_PI * freq) / (double)SAMPLE_RATE;

    for (int i = 0; i < num_samples; i++) {
        buffer[i] = (short)(32767.0 * sin(phase));
        phase += step;
        if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
    }
}

/* ------------------------------------------------------------------ */
/* RMS computation                                                      */
/* ------------------------------------------------------------------ */
static float calculate_rms(const short *buffer, int num_samples)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return (float)sqrt(sum_sq / (double)num_samples);
}

