                snd_strerror(err));
        cleanup();
        return EXIT_FAILURE;
    }

    err = snd_pcm_hw_params_set_format(g_pcm, g_hw_params,
                                       SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error: cannot set sample format: %s\n",
