/*
 * TCS34725 color sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TCS34725 VCC  -> Pi 3.3 V (pin 1)
 *   TCS34725 GND  -> Pi GND   (pin 9)
 *   TCS34725 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   TCS34725 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o color_reader color_reader.c -lpigpio -lrt
 * Run:
 *   sudo ./color_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TCS34725 constants (datasheet) ---- */
#define TCS34725_I2C_ADDR      0x29
#define TCS34725_COMMAND_BIT   0x80
#define TCS34725_ENABLE        0x00
#define TCS34725_ATIME         0x01
#define TCS34725_CONTROL       0x0F
#define TCS34725_CDATA         0x10  /* clear data low byte */
#define TCS34725_RDATA         0x12
#define TCS34725_GDATA         0x14
#define TCS34725_BDATA         0x16

#define TCS34725_ENABLE_PON    0x01
#define TCS34725_ENABLE_AEN    0x02

/* 154 ms integration time → register value 0xD5 */
#define TCS34725_ATIME_154MS   0xD5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_csv_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register.                              */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int tcs34725_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register.                             */
/* Returns 0 on success and stores value in *out, -1 on failure.      */
/* ------------------------------------------------------------------ */
static int tcs34725_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian word from a TCS34725 register.          */
/* Returns 0 on success and stores value in *out, -1 on failure.      */
/* ------------------------------------------------------------------ */
static int tcs34725_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns data as (msb << 8) | lsb */
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TCS34725: power on, set integration time, enable     */
/* RGBC ADC, then wait for the first integration cycle to complete.    */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    /* Power on */
    if (tcs34725_write_byte(handle, TCS34725_ENABLE,
                            TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000);  /* 3 ms power-up delay */

    /* Set integration time to 154 ms */
    if (tcs34725_write_byte(handle, TCS34725_ATIME,
                            TCS34725_ATIME_154MS) < 0)
        return -1;

    /* Enable RGBC ADC */
    if (tcs34725_write_byte(handle, TCS34725_ENABLE,
                            TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    /* Wait for first integration cycle to complete */
    gpioDelay(154000);  /* 154 ms × 1000 µs/ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channels (C, R, G, B).                                */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int tcs34725_read_all(int handle, uint16_t *c, uint16_t *r,
                             uint16_t *g, uint16_t *b)
{
    if (tcs34725_read_word(handle, TCS34725_CDATA, c) < 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_RDATA, r) < 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_GDATA, g) < 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row.                                                */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t c, uint16_t r,
                     uint16_t g, uint16_t b)
{
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus 1 at TCS34725 address ---- */
    g_i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                TCS34725_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- sensor init ---- */
    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] TCS34725 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open CSV file ---- */
    g_csv_file = fopen("color_data.csv", "a");
    if (!g_csv_file) {
        fprintf(stderr, "[FATAL] Cannot open color_data.csv for append\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* write header if file is empty */
    fseek(g_csv_file, 0, SEEK_END);
    if (ftell(g_csv_file) == 0) {
        fprintf(g_csv_file, "timestamp,clear,red,green,blue\n");
        fflush(g_csv_file);
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TCS34725 logging started. Press Ctrl-C to stop.\n");

    /* ---- main sampling loop ---- */
    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs34725_read_all(g_i2c_handle, &c, &r, &g, &b) == 0) {
            log_data(g_csv_file, c, r, g, b);
        } else {
            /* On read failure: log zeros so gaps are visible */
            fprintf(stderr, "[WARN] I2C read failed; logging zeros for this cycle\n");
            log_data(g_csv_file, 0, 0, 0, 0);
        }

        /* 500 ms sampling interval */
        gpioDelay(500000);  /* 500 ms × 1000 µs/ms */
    }

    /* ---- cleanup ---- */
    printf("\nShutting down...\n");
    if (g_csv_file) {
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

