#include <pigpio.h>

#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23

#define SUNRISE_DURATION  3600
#define DAYTIME_DURATION  21600
#define SUNSET_DURATION   3600
#define NIGHTTIME_DURATION 57600

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static void all_off(void) {
    safe_write(RELAY1, 1);
    safe_write(RELAY2, 1);
    safe_write(RELAY3, 1);
    safe_write(RELAY4, 1);
}

static void cleanup(void) {
    all_off();
    gpioTerminate();
}

static int set_relays(int d1, int d2, int d3, int d4) {
    if (safe_write(RELAY1, d1) != 0) return -1;
    if (safe_write(RELAY2, d2) != 0) return -1;
    if (safe_write(RELAY3, d3) != 0) return -1;
    if (safe_write(RELAY4, d4) != 0) return -1;
    return 0;
}

static int sunrise_phase(void) {
    for (int i = 0; i <= 100 && running; i++) {
        int d1 = (i < 50) ? (i / 5) : (10 - i / 5);
        int d2 = (i < 50) ? (i / 5) : (10 - i / 5);
        int d3 = (i < 50) ? (i / 5) : (10 - i / 5);
        int d4 = (i < 50) ? (i / 5) : (10 - i / 5);
        if (set_relays(d1, d2, d3, d4) != 0) return -1;
        sleep(60);
    }
    return 0;
}

static int daytime_phase(void) {
    for (int i = 0; i < DAYTIME_DURATION / 60 && running; i++) {
        if (set_relays(10, 10, 10, 10) != 0) return -1;
        sleep(60);
    }
    return 0;
}

static int sunset_phase(void) {
    for (int i = 0; i <= 100 && running; i++) {
        int d1 = (i < 50) ? (10 - i / 5) : (i / 5);
        int d2 = (i < 50) ? (10 - i / 5) : (i / 5);
        int d3 = (i < 50) ? (10 - i / 5) : (i / 5);
        int d4 = (i < 50) ? (10 - i / 5) : (i / 5);
        if (set_relays(d1, d2, d3, d4) != 0) return -1;
        sleep(60);
    }
    return 0;
}

static int nighttime_phase(void) {
    for (int i = 0; i < NIGHTTIME_DURATION / 60 && running; i++) {
        if (set_relays(0, 0, 0, 0) != 0) return -1;
        sleep(60);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RELAY1, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY2, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY3, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY4, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    all_off();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (sunrise_phase() != 0) break;
        if (!running) break;
        if (daytime_phase() != 0) break;
        if (!running) break;
        if (sunset_phase() != 0) break;
        if (!running) break;
        if (nighttime_phase() != 0) break;
    }

    cleanup();
    return EXIT_SUCCESS;
}

