#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define DEBOUNCE_MS 200
#define CAPTURE_SEC 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos"

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

static int read_sensor(void) {
    return gpioRead(SENSOR_GPIO);
}

static void log_motion_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_fp) {
        fprintf(log_fp, "%s Motion detected on GPIO %d\n", timestamp, SENSOR_GPIO);
        fflush(log_fp);
    }
    printf("%s Motion detected on GPIO %d\n", timestamp, SENSOR_GPIO);
}

static int capture_video(void) {
    time_t rawtime;
    struct tm timeinfo;
    char filename[256];
    char command[512];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", &timeinfo);

    snprintf(command, sizeof(command),
             "raspivid -o %s/%s -t %d000 -w 640 -h 480 -fps 25 -b 1000000",
             VIDEO_DIR, filename, CAPTURE_SEC);

    printf("Capturing video: %s/%s\n", VIDEO_DIR, filename);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid.\n");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d.\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: raspivid killed by signal %d.\n", WTERMSIG(status));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;
            if (elapsed >= DEBOUNCE_MS * 1000) {
                log_motion_event();
                if (capture_video() != 0) {
                    fprintf(stderr, "Warning: video capture failed.\n");
                }
                last_trigger_tick = now;
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
    }
    cleanup_gpio();
    return EXIT_SUCCESS;
}

