#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds in microseconds */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on SIGINT / SIGTERM            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate all relays (active-low: drive HIGH to deactivate)       */
/* ------------------------------------------------------------------ */
static void deactivate_all_relays(void)
{
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped log line; returns 0 on success, -1 on error    */
/* ------------------------------------------------------------------ */
static int log_data(int moisture,
                    int r1, int r2, int r3, int r4)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file,
                "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
                timestamp, moisture,
                r1 ? "OFF" : "ON",
                r2 ? "OFF" : "ON",
                r3 ? "OFF" : "ON",
                r4 ? "OFF" : "ON") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int i;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure relay pins as outputs, initial state HIGH (off) ---- */
    for (i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "gpioWrite (init HIGH) failed for pin %d\n",
                    relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Seed random number generator ---- */
    srand((unsigned int)time(NULL));

    printf("Smart Greenhouse Irrigation System started.\n");
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        int moisture = rand() % 101;  /* 0–100 */
        int r1, r2, r3, r4;

        /* Dry soil → relay ON (LOW), wet soil → relay OFF (HIGH) */
        if (moisture < MOISTURE_THRESHOLD) {
            r1 = gpioWrite(RELAY1_PIN, 0);
            r2 = gpioWrite(RELAY2_PIN, 0);
            r3 = gpioWrite(RELAY3_PIN, 0);
            r4 = gpioWrite(RELAY4_PIN, 0);
        } else {
            r1 = gpioWrite(RELAY1_PIN, 1);
            r2 = gpioWrite(RELAY2_PIN, 1);
            r3 = gpioWrite(RELAY3_PIN, 1);
            r4 = gpioWrite(RELAY4_PIN, 1);
        }

        if (r1 != 0 || r2 != 0 || r3 != 0 || r4 != 0) {
            fprintf(stderr,
                    "Warning: GPIO write failed (r1=%d r2=%d r3=%d r4=%d)\n",
                    r1, r2, r3, r4);
        }

        if (log_data(moisture,
                     gpioRead(RELAY1_PIN),
                     gpioRead(RELAY2_PIN),
                     gpioRead(RELAY3_PIN),
                     gpioRead(RELAY4_PIN)) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep 5 s, checking g_running every 100 ms for responsive exit */
        for (int ms = 0; ms < 5000 && g_running; ms += 100) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    deactivate_all_relays();

    if (fclose(g_log_file) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

