/*
 * Free-fall detector using Analog Devices ADXL345 on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C1 SDA, pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C1 SCL, pin 5)
 *   ADXL345 VDD  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   Alarm buzzer -> GPIO27 (pin 13) through a suitable transistor/driver
 *
 * Build:  gcc -O2 -Wall -o freefall freefall.c -lpigpio -lrt
 * Run:    sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (verified against ADXL345-datasheet rev D) ---- */
#define ADXL345_ADDR        0x53          /* SA0 tied to GND on ADXL345 */
#define ADXL345_REG_DEVID   0x00          /* Device ID register         */
#define ADXL345_REG_POWER_CTL 0x2D        /* Power-saving features      */
#define ADXL345_REG_DATA_FORMAT 0x31      /* Full-res / 4-wire / +/-2g  */
#define ADXL345_REG_DATAX0   0x32         /* X-axis low byte            */
#define ADXL345_REG_DATAY0   0x34         /* Y-axis low byte            */
#define ADXL345_REG_DATAZ0   0x36         /* Z-axis low byte            */
#define ADXL345_DEVID        0xE5         /* Expected device ID         */
#define ADXL345_POWER_CTL_MEASURE 0x08    /* Measurement mode bit      */
#define ADXL345_DATA_FORMAT_FULL_RES 0x08 /* Full resolution, +/-2g     */

/* ---- Free-fall detection parameters ---- */
#define FREEFALL_THRESHOLD_G  0.2f        /* |x|, |y|, |z| < threshold  */
#define FREEFALL_DURATION_S   0.5f        /* First-read -> second-read  */
#define POLL_INTERVAL_US      100000      /* 100 ms between samples     */
#define ALARM_HOLD_S          5           /* Alarm hold time            */
#define ALARM_GPIO            27          /* BCM pin for alarm output   */
#define LOG_FILE              "freefall.log"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a signed 16-bit little-endian axis value from the ADXL345.     */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_axis(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read of register 0x%02X failed (rc=%d)\n",
                reg, rc);
        return -1;
    }
    *out = (int16_t)((uint16_t)(uint8_t)buf[0]
                     | ((uint16_t)(uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw counts to g.  Full-resolution mode, +/-2g range.        */
/* ------------------------------------------------------------------ */
static float raw_to_g(int16_t raw)
{
    /* 4 mg/count => 1 count = 0.004 g */
    return (float)raw * 0.004f;
}

/* ------------------------------------------------------------------ */
/* Log a free-fall event to LOG_FILE in CSV format.                    */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "<timestamp-error>,%.3f,%.3f,%.3f\n", x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Detect a free-fall event: two readings below threshold within       */
/* FREEFALL_DURATION_S seconds.                                        */
/* ------------------------------------------------------------------ */
static bool detect_freefall(int handle)
{
    int16_t rx1, ry1, rz1;
    int16_t rx2, ry2, rz2;
    float   x1, y1, z1, x2, y2, z2;

    if (read_axis(handle, ADXL345_REG_DATAX0, &rx1) != 0) return false;
    if (read_axis(handle, ADXL345_REG_DATAY0, &ry1) != 0) return false;
    if (read_axis(handle, ADXL345_REG_DATAZ0, &rz1) != 0) return false;

    x1 = raw_to_g(rx1);
    y1 = raw_to_g(ry1);
    z1 = raw_to_g(rz1);

    /* Wait for the second reading (free-fall duration) */
    usleep((useconds_t)(FREEFALL_DURATION_S * 1e6));

    if (read_axis(handle, ADXL345_REG_DATAX0, &rx2) != 0) return false;
    if (read_axis(handle, ADXL345_REG_DATAY0, &ry2) != 0) return false;
    if (read_axis(handle, ADXL345_REG_DATAZ0, &rz2) != 0) return false;

    x2 = raw_to_g(rx2);
    y2 = raw_to_g(ry2);
    z2 = raw_to_g(rz2);

    /* Confirm all axes below threshold for both readings */
    bool below_threshold =
        (fabsf(x1) < FREEFALL_THRESHOLD_G &&
         fabsf(y1) < FREEFALL_THRESHOLD_G &&
         fabsf(z1) < FREEFALL_THRESHOLD_G) &&
        (fabsf(x2) < FREEFALL_THRESHOLD_G &&
         fabsf(y2) < FREEFALL_THRESHOLD_G &&
         fabsf(z2) < FREEFALL_THRESHOLD_G);

    if (below_threshold) {
        log_freefall(x2, y2, z2);
    }
    return below_threshold;
}

/* ------------------------------------------------------------------ */
/* Configure the ADXL345 for measurement mode and full resolution.     */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int configure_adxl345(int handle)
{
    int devid = i2cReadByteData(handle, ADXL345_REG_DEVID);
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_REG_DATA_FORMAT,
                         ADXL345_DATA_FORMAT_FULL_RES) != 0) {
        fprintf(stderr, "Failed to set DATA_FORMAT register\n");
        return -1;
    }

    if (i2cWriteByteData(handle, ADXL345_REG_POWER_CTL,
                         ADXL345_POWER_CTL_MEASURE) != 0) {
        fprintf(stderr, "Failed to set POWER_CTL register\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor config ---- */
    if (configure_adxl345(g_i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 configuration failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Alarm GPIO setup ---- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", ALARM_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection running.  Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (detect_freefall(g_i2c_handle)) {
            printf("Free-fall detected! Alarm ON for %d s.\n", ALARM_HOLD_S);
            gpioWrite(ALARM_GPIO, 1);
            /* Hold alarm for the configured duration, checking g_running */
            for (int i = 0; i < ALARM_HOLD_S * 10 && g_running; i++) {
                usleep(100000); /* 100 ms slices */
            }
            gpioWrite(ALARM_GPIO, 0);
        }
        usleep(POLL_INTERVAL_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(ALARM_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

