        pthread_mutex_lock(&g_log_mutex);
        if (g_timeout && !g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout (no response within %d us)\n",
                    ECHO_TIMEOUT_US);
        }
        pthread_mutex_unlock(&g_log_mutex);

