 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO4  (BCM 4, physical pin 7)
 *   HC-SR04 ECHO -> GPIO18 (BCM 18, physical pin 12)
 *   HC-SR04 VCC  -> 5 V
 *   HC-SR04 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04_logger hcsr04_logger.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware-accessible GPIO).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIG_PIN        4
#define ECHO_PIN        18
#define LOG_FILE        "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define MEASURE_CYCLE_US 200000   /* 200 ms between triggers */
#define ECHO_TIMEOUT_US  100000   /* 100 ms max echo wait */
#define MAX_PULSE_US     23200    /* ~4 m, well within HC-SR04 range */
#define TICK_WRAP_US     71600000 /* ~71.6 min; pigpio ticks wrap every ~71.6 min */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Per-echo-cycle state protected by g_log_mutex */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_timeout    = false;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 minutes.
 * Compute (b - a) modulo 2^32 so that it is always positive even across a wrap.
 */
static inline uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a; /* unsigned subtraction wraps correctly */
}

static void echo_rising_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&g_log_mutex);
        g_start_tick = tick;
        g_echo_seen  = false;
        g_timeout    = false;
        pthread_mutex_unlock(&g_log_mutex);
    }
}

static void echo_falling_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;
    if (level == 0) {
        pthread_mutex_lock(&g_log_mutex);
        g_end_tick = tick;
        g_echo_seen = true;
        pthread_mutex_unlock(&g_log_mutex);
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

static void log_distance(uint32_t pulse_us)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    double distance_cm = (double)pulse_us / 58.0;

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_fp) {
        fprintf(g_log_fp, "%lld,%.2f\n", timestamp_ns, distance_cm);
        fflush(g_log_fp);
    }
    pthread_mutex_unlock(&g_log_mutex);
}

static void cleanup(void)
{
    /* Cancel callbacks first so no more callbacks fire during teardown */
    gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
