/*
 * Raspberry Pi 5 - LIS3DH Free-Fall / Impact Detector
 *
 * Reads the LIS3DH accelerometer on I2C bus 1 (address 0x19), detects
 * free-fall (accel magnitude < 0.2 g) and impact (accel magnitude > 1.5 g),
 * and pulses a buzzer on GPIO17 for 1 second on impact.
 *
 * Build:  gcc -O2 -Wall -o lis3dh_detect lis3dh_detect.c -lm -lpigpio -lrt
 * Run:    sudo ./lis3dh_detect [freefall_g] [impact_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LIS3DH constants (verified against datasheet) ---- */
#define LIS3DH_ADDR        0x19
#define LIS3DH_REG_CTRL1   0x20
#define LIS3DH_REG_CTRL4   0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33

#define BUZZER_GPIO        17
#define I2C_BUS            1
#define SAMPLE_PERIOD_US   10000   /* 10 ms  -> 100 Hz */
#define BUZZER_DURATION_US 1000000 /* 1 s    */
#define MAX_RETRIES        3

/* ---- Default thresholds (g) ---- */
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD   1.5f

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on failure.  */
static int reg_write(int handle, uint8_t reg, uint8_t val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteByteData(handle, reg, val) == 0)
            return 0;
        gpioDelay(1000); /* 1 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on failure. */
static int reg_read(int handle, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int r = i2cReadByteData(handle, reg);
        if (r >= 0) {
            *val = (uint8_t)r;
            return 0;
        }
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a signed 16-bit little-endian axis value from two consecutive regs. */
static int read_axis(int handle, uint8_t reg_low, int16_t *out)
{
    uint8_t lo, hi;
    if (reg_read(handle, reg_low, &lo) != 0) return -1;
    if (reg_read(handle, reg_low + 1, &hi) != 0) return -1;
    *out = (int16_t)((uint16_t)lo | ((uint16_t)hi << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the LIS3DH: enable XYZ axes, normal mode, 100 Hz ODR.     */
static int init_lis3dh(int handle)
{
    uint8_t who;
    if (reg_read(handle, LIS3DH_REG_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL1: 100 Hz ODR, enable X/Y/Z axes (0x57) */
    if (reg_write(handle, LIS3DH_REG_CTRL1, 0x57) != 0) {
        fprintf(stderr, "Error: cannot write CTRL1.\n");
        return -1;
    }

    /* CTRL4: normal mode, high-resolution off (0x00) */
    if (reg_write(handle, LIS3DH_REG_CTRL4, 0x00) != 0) {
        fprintf(stderr, "Error: cannot write CTRL4.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw axis value to g (sensitivity 1 mg/LSB in normal mode). */
static float raw_to_g(int16_t raw)
{
    return (float)raw / 1000.0f;
}

/* ------------------------------------------------------------------ */
/* Activate buzzer for the given duration (microseconds).              */
static void activate_buzzer(int gpio, uint32_t duration_us)
{
    gpioWrite(gpio, 1);
    gpioDelay(duration_us);
    gpioWrite(gpio, 0);
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold   = DEFAULT_IMPACT_THRESHOLD;
    bool  freefall_active    = false;

    if (argc > 1) freefall_threshold = atof(argv[1]);
    if (argc > 2) impact_threshold   = atof(argv[2]);

    if (freefall_threshold <= 0.0f || impact_threshold <= 0.0f) {
        fprintf(stderr, "Error: thresholds must be positive (got %.2f, %.2f).\n",
                freefall_threshold, impact_threshold);
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_lis3dh(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: LIS3DH initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Buzzer GPIO setup ---- */
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LIS3DH free-fall / impact detector running.\n");
    printf("  freefall_threshold = %.2f g\n", freefall_threshold);
    printf("  impact_threshold   = %.2f g\n", impact_threshold);
    printf("  buzzer GPIO        = %d\n", BUZZER_GPIO);
    printf("  I2C bus            = %d\n", I2C_BUS);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_axis(g_i2c_handle, LIS3DH_REG_OUT_X_L, &x) != 0 ||
            read_axis(g_i2c_handle, LIS3DH_REG_OUT_X_L + 2, &y) != 0 ||
            read_axis(g_i2c_handle, LIS3DH_REG_OUT_X_L + 4, &z) != 0) {
            fprintf(stderr, "Warning: I2C read error, retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gx = raw_to_g(x);
        float gy = raw_to_g(y);
        float gz = raw_to_g(z);
        float mag = sqrtf(gx * gx + gy * gy + gz * gz);

        /* Free-fall detection */
        if (mag < freefall_threshold && !freefall_active) {
            printf("Free-fall detected (mag=%.3f g)\n", mag);
            freefall_active = true;
        }

        /* Impact detection (only after free-fall) */
        if (freefall_active && mag > impact_threshold) {
            printf("Impact detected (mag=%.3f g)\n", mag);
            activate_buzzer(BUZZER_GPIO, BUZZER_DURATION_US);
            freefall_active = false;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

