#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LIS3DH_ADDR_DEFAULT 0x19
#define LIS3DH_REG_CTRL1    0x20
#define LIS3DH_REG_CTRL4    0x23
#define LIS3DH_REG_OUT_X_L  0x28
#define LOG_FILE            "/var/log/high_acceleration.log"
#define SAMPLE_PERIOD_US    100000
#define DEFAULT_THRESHOLD   2.0f
#define MIN_THRESHOLD       0.01f
#define I2C_BUS             1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int init_lis3dh(int handle) {
    /* CTRL1: 100 Hz ODR, all axes enabled */
    if (i2c_write_byte(handle, LIS3DH_REG_CTRL1, 0x77) < 0) return -1;
    /* CTRL4: ±2 g full-scale, HR mode, little-endian */
    if (i2c_write_byte(handle, LIS3DH_REG_CTRL4, 0x08) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed: %s\n",
                rc < 0 ? pigpio_error(rc) : "short read");
        *x = *y = *z = 0.0f;
        return -1;
    }
    int16_t raw_x = (int16_t)(((uint8_t)buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)(((uint8_t)buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)(((uint8_t)buffer[5] << 8) | (uint8_t)buffer[4]);
    /* ±2 g, 12-bit left-justified: shift right 4 to get g */
    *x = (float)raw_x / 16.0f;
    *y = (float)raw_y / 16.0f;
    *z = (float)raw_z / 16.0f;
    return 0;
}

static void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    }
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    int rc = system("sudo shutdown -h now");
    if (rc == -1) {
        perror("system()");
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x03-0x77)\n",
                            i2c_address);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= MIN_THRESHOLD) {
                    fprintf(stderr, "Threshold must be > %.2f g\n", MIN_THRESHOLD);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lis3dh(g_i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring acceleration (threshold: %.2f g)... Ctrl+C to exit.\n",
           threshold);

    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            if (x > threshold || y > threshold || z > threshold) {
                log_acceleration(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

