/*
 * Autonomous line-following robot for Raspberry Pi 5.
 *
 * Hardware:
 *   - SunFounder 3-Way Tracking Sensor (IR reflectance, digital GPIO)
 *     Left  sensor -> GPIO4  (BCM)
 *     Center sensor -> GPIO17 (BCM)
 *     Right sensor -> GPIO27 (BCM)
 *   - Alert LED/buzzer on GPIO22 (BCM), active-high
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o line_follow line_follow.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LEFT_SENSOR_PIN   4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define ALERT_PIN         22

/* ---- Circular buffer ---- */
#define BUFFER_SIZE 5

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* ---- Motor placeholder functions (replace with real H-bridge / PWM) ---- */
static void motor_forward(void)  { fprintf(stderr, "Motor: forward\n");  }
static void motor_left(void)    { fprintf(stderr, "Motor: left\n");    }
static void motor_right(void)   { fprintf(stderr, "Motor: right\n");   }
static void motor_stop(void)    { fprintf(stderr, "Motor: stop\n");    }

/* ---- Alert LED/buzzer ---- */
static void alert_on(void)  { gpioWrite(ALERT_PIN, 1); }
static void alert_off(void) { gpioWrite(ALERT_PIN, 0); }

/* ---- Signal handling ---- */
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Sensor reading ---- */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n", pin, v);
        return -1;
    }
    return v;
}

/* ---- Circular buffer ---- */
static void add_to_buffer(int left, int center, int right)
{
    sensor_buffer[buffer_index].left   = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right  = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

/* ---- Line-following logic ---- */
static void line_follow(void)
{
    int left   = read_sensor(LEFT_SENSOR_PIN);
    int center = read_sensor(CENTER_SENSOR_PIN);
    int right  = read_sensor(RIGHT_SENSOR_PIN);

    if (left < 0 || center < 0 || right < 0) {
        fprintf(stderr, "Sensor read error; stopping for safety.\n");
        motor_stop();
        return;
    }

    add_to_buffer(left, center, right);

    /*
     * SunFounder 3-Way Tracking Sensor logic:
     *   0 = line detected (reflective IR beam)
     *   1 = no line (air)
     */
    if (center == 1) {
        /* Center sensor: no line — alert for five consecutive readings */
        if (buffer_count == BUFFER_SIZE) {
            bool all_no_line = true;
            for (int i = 0; i < BUFFER_SIZE; i++) {
                if (sensor_buffer[i].center == 0) { all_no_line = false; break; }
            }
            if (all_no_line) {
                fprintf(stderr, "Alert: center sensor no-line for 5 readings.\n");
                alert_on();
                gpioDelay(2000000); /* 2 s */
                alert_off();
            }
        }
        motor_stop();
    } else if (left == 0 && right == 0) {
        /* Line detected on both sides — move forward */
        motor_forward();
    } else if (left == 0) {
        /* Line on left — turn right */
        motor_right();
    } else if (right == 0) {
        /* Line on right — turn left */
        motor_left();
    } else {
        /* No line detected — move forward */
        motor_forward();
    }
}

/* ---- Main ---- */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set sensor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure alert pin as output, initial LOW ---- */
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set alert pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    alert_off();

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    fprintf(stderr, "Line-following robot started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (running) {
        line_follow();
        gpioDelay(10000); /* 10 ms */
    }

    /* ---- Cleanup ---- */
    motor_stop();
    alert_off();
    gpioTerminate();
    fprintf(stderr, "Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

