 * and logs timestamped events to magnetic_events.txt.
 *
 * Build:  gcc -O2 -Wall -o si7210_reader si7210_reader.c -lpigpio -lrt
 * Run:    sudo ./si7210_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SI7210_ADDR          0x6B          /* Si7210 default 7-bit address  */

/* Si7210 register addresses (datasheet) */
#define SI7210_REG_DEVICE_ID 0x00
#define SI7210_REG_X_MSB     0x01
#define SI7210_REG_X_LSB     0x02
#define SI7210_REG_Y_MSB     0x03
#define SI7210_REG_Y_LSB     0x04
#define SI7210_REG_Z_MSB     0x05
#define SI7210_REG_Z_LSB     0x06
#define SI7210_REG_CTRL      0x07

#define SI7210_DEVID         0x0F          /* expected device ID            */
#define SI7210_CTRL_DEFAULT  0x00          /* standby, no interrupts        */

#define RELAY_GPIO           17            /* BCM pin, active high          */
#define FIELD_THRESHOLD_MT   5.0f          /* milliTesla                    */
#define SAMPLE_PERIOD_US     100000        /* 100 ms                        */
#define POLL_TIMEOUT_MS      50
#define POLL_DELAY_US        1000          /* 1 ms between poll attempts    */

#define LOG_FILE             "magnetic_events.txt"

/* --------------------------- Global State ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static int  g_pigpio_inited = 0;

/* --------------------------- Prototypes -------------------------------- */

static void  signal_handler(int sig);
static int   init_i2c(void);
static int   init_gpio(void);
static int   read_sensor(int16_t *x, int16_t *y, int16_t *z);
static void  control_relay(int state);
static void  log_event(const char *msg);
static void  cleanup(void);

/* ------------------------------ Main ----------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = 1;

    if (init_i2c() != 0) {
        log_event("I2C initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        log_event("GPIO initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Si7210 reader started");

    while (g_running) {
        int16_t x, y, z;

        if (read_sensor(&x, &y, &z) != 0) {
            log_event("Sensor read error; deactivating relay and retrying");
            control_relay(0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float x_mt = (float)x / 1000.0f;   /* raw / 1000 = mT              */
        float y_mt = (float)y / 1000.0f;
        float z_mt = (float)z / 1000.0f;

        char buf[160];
        snprintf(buf, sizeof(buf),
                 "X=%.2f mT, Y=%.2f mT, Z=%.2f mT", x_mt, y_mt, z_mt);
        log_event(buf);

        if (x_mt > FIELD_THRESHOLD_MT ||
            y_mt > FIELD_THRESHOLD_MT ||
            z_mt > FIELD_THRESHOLD_MT) {
            control_relay(1);
            log_event("Field threshold exceeded; relay ON");
        } else {
            control_relay(0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Signal Handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C Init ----------------------------------- */

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SI7210_ADDR, g_i2c_handle);
        return -1;
    }

    /* Verify device identity */
    int devid = i2cReadByteData(g_i2c_handle, SI7210_REG_DEVICE_ID);
    if (devid < 0) {
        fprintf(stderr, "Failed to read DEVICE_ID register: %d\n", devid);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if ((devid & 0x0F) != SI7210_DEVID) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X)\n",
                devid, SI7210_DEVID);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Put sensor into standby so we can configure the control register */
    if (i2cWriteByteData(g_i2c_handle, SI7210_REG_CTRL, SI7210_CTRL_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write CTRL register\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* --------------------------- GPIO Init ---------------------------------- */

static int init_gpio(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

/* --------------------------- Read Sensor -------------------------------- */

static int read_sensor(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    /* Read 6 bytes starting at X_MSB (0x01) */
    int n = i2cReadI2CBlockData(g_i2c_handle, SI7210_REG_X_MSB, buf, 6);
    if (n != 6) {
        fprintf(stderr, "i2cReadI2CBlockData returned %d (expected 6)\n", n);
        return -1;
    }

    /* Si7210 outputs MSB first; each axis is 12-bit left-justified */
    *x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]) >> 4;
    *y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]) >> 4;
    *z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]) >> 4;

    /* Sign-extend 12-bit values */
    if (*x & 0x0800) *x |= 0xF000;
    if (*y & 0x0800) *y |= 0xF000;
    if (*z & 0x0800) *z |= 0xF000;

    return 0;
}

/* --------------------------- Relay Control ------------------------------ */

static void control_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", RELAY_GPIO, state);
    }
}

/* --------------------------- Logging ------------------------------------ */

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

/* --------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_pigpio_inited) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = 0;
    }
}

