#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define TCP_PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t) {
        fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, message);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (client_fd != -1) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd != -1) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(fd);
        return -1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);
    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

static void handle_client(int client) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    while (running && (bytes_received = recv(client, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        char *newline = strpbrk(buffer, "\r\n");
        if (newline) *newline = '\0';
        char *end = buffer + strlen(buffer);
        while (end > buffer && (*(end - 1) == ' ' || *(end - 1) == '\t')) {
            *(end - 1) = '\0';
            end--;
        }
        if (strcasecmp(buffer, "ON") == 0) {
            if (gpioWrite(RELAY_GPIO, 1) == 0) {
                log_event("Relay turned ON");
            } else {
                log_event("Failed to turn relay ON");
            }
        } else if (strcasecmp(buffer, "OFF") == 0) {
            if (gpioWrite(RELAY_GPIO, 0) == 0) {
                log_event("Relay turned OFF");
            } else {
                log_event("Failed to turn relay OFF");
            }
        } else {
            log_event("Invalid command received");
        }
    }
    if (bytes_received < 0 && errno != EINTR) {
        perror("recv");
    }
    close(client);
    client_fd = -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return 1;
    }
    if (init_gpio() != 0) {
        fclose(log_file);
        return 1;
    }
    server_fd = init_socket();
    if (server_fd < 0) {
        cleanup();
        return 1;
    }
    printf("Server listening on port %d\n", TCP_PORT);
    log_event("Server started");
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s\n", client_ip);
        handle_client(client_fd);
    }
    cleanup();
    return 0;
}

