code:
/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid-flow monitor
 *
 * Hardware:
 *   - Two Sensirion SLF3S-1300F (40 ml/min) sensors on I2C bus 1
 *       Sensor 1: I2C address 0x25
 *       Sensor 2: I2C address 0x26
 *   - Safety relay control on GPIO 18 (BCM), active-high
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for GPIO/I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define SENSOR1_ADDR         0x25
#define SENSOR2_ADDR         0x26

#define RELAY_GPIO           18
#define FLOW_THRESHOLD       5.0f   /* ml/min */
#define POLL_DELAY_US        100000 /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S-1300F: continuous measurement command (no clock stretching) */
#define MEASURE_CMD_MSB      0x36
#define MEASURE_CMD_LSB      0x1E

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;
static bool g_relay_initialized = false;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static bool initialize_gpio(void);
static bool initialize_i2c(void);
static bool start_measurement(int handle);
static bool read_flow_rate(int handle, float *flow_out);
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t expected);
static bool control_relay(float f1, float f2);
static bool log_flow_data(float f1, float f2);
static void cleanup(void);

/* ------------------------------- CRC-8 ----------------------------------- */

/*
 * Sensirion CRC-8: polynomial 0x31, initial value 0xFF, no final XOR.
 * Equivalent to the CRC-8 used by the Sensirion SHT family.
 */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == expected);
}

/* ------------------------------ Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ GPIO setup -------------------------------- */

static bool initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return false;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return false;
    }

    /* Ensure relay is de-energized at startup */
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d low.\n", RELAY_GPIO);
        gpioTerminate();
        return false;
    }

    g_relay_initialized = true;
    return true;
}

/* ------------------------------ I2C setup --------------------------------- */

static bool initialize_i2c(void)
{
    g_i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c_h1);
        return false;
    }

    g_i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c_h2);
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        return false;
    }

    /* Start continuous measurement on both sensors */
    if (!start_measurement(g_i2c_h1)) {
        fprintf(stderr, "Error: failed to start measurement on sensor 1.\n");
        cleanup();
        return false;
    }
    if (!start_measurement(g_i2c_h2)) {
        fprintf(stderr, "Error: failed to start measurement on sensor 2.\n");
        cleanup();
        return false;
    }

    return true;
}

static bool start_measurement(int handle)
{
    uint8_t cmd[2] = { MEASURE_CMD_MSB, MEASURE_CMD_LSB };
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc != 0) {
        fprintf(stderr, "Error: i2cWriteDevice(handle=%d) failed: %d\n", handle, rc);
        return false;
    }
    return true;
}

/* --------------------------- Read flow rate ------------------------------- */

/*
 * Reads three bytes (2 data + 1 CRC) from the sensor.
 * Returns true on success and stores the flow rate in ml/min.
 */
static bool read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Warning: i2cReadDevice(handle=%d) returned %d (expected 3).\n",
                handle, rc);
        return false;
    }

    if (!crc8_check(buf, 2, buf[2])) {
        fprintf(stderr, "Warning: CRC mismatch on handle %d.\n", handle);
        return false;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 100.0f; /* 1 LSB = 0.01 ml/min */
    return true;
}

/* --------------------------- Relay control -------------------------------- */

static bool control_relay(float f1, float f2)
{
    bool below = (f1 < FLOW_THRESHOLD) || (f2 < FLOW_THRESHOLD);
    int level = below ? 1 : 0;

    if (gpioWrite(RELAY_GPIO, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed.\n", RELAY_GPIO, level);
        return false;
    }
    return true;
}

/* ------------------------------ Logging ----------------------------------- */

static bool log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return false;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("Error getting time");
        fclose(fp);
        return false;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            timestamp, ms, f1, f2);
    fflush(fp);
    fclose(fp);
    return true;
}

/* ------------------------------ Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_relay_initialized) {
        gpioWrite(RELAY_GPIO, 0);
        g_relay_initialized = false;
    }

    if (g_i2c_h1 >= 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
    }

    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (!initialize_gpio())
        return EXIT_FAILURE;

    if (!initialize_i2c()) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        bool ok1 = read_flow_rate(g_i2c_h1, &f1);
        bool ok2 = read_flow_rate(g_i2c_h2, &f2);

        if (ok1 && ok2) {
            if (!control_relay(f1, f2))
                fprintf(stderr, "Warning: relay control failed.\n");
            if (!log_flow_data(f1, f2))
                fprintf(stderr, "Warning: logging failed.\n");
        } else {
            fprintf(stderr, "Warning: sensor read failure, skipping cycle.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

