static bool initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return false;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return false;
    }

    /* Ensure relay is de-energized at startup */
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIO %d low.\n", RELAY_GPIO);
        gpioTerminate();
        return false;
    }

    g_relay_initialized = true;
    return true;
