/*
 * rain_window.c — Raspberry Pi 5 rain-activated window actuator
 *
 * Hardware:
 *   - Seeed Studio Rain Sensor v1.0  (digital DO) -> GPIO17 (BCM)
 *   - L298N driver
 *       ENA -> GPIO22 (BCM)
 *       IN1 -> GPIO23 (BCM)
 *       IN2 -> GPIO24 (BCM)
 *
 * Behavior:
 *   Polls GPIO17 every 200 ms.  When the digital output transitions
 *   from HIGH (dry) to LOW (wet), the actuator motor is driven for
 *   5 s to close the window.  The sensor must then remain dry for
 *   at least three consecutive polls (≈600 ms) before another
 *   trigger is accepted.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lpigpio -lrt
 *   Run as root (pigpio requires root for hardware-level GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

/* ---- Timing constants (microseconds) ---- */
#define POLL_INTERVAL_US  200000   /* 200 ms  */
#define MOTOR_RUN_US      5000000  /* 5 s     */
#define DRY_REQUIRED_US   600000   /* 600 ms  */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on SIGINT / SIGTERM            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helper: log a pigpio call result with appropriate syslog level      */
/* ------------------------------------------------------------------ */
static void log_pigpio_result(int rc, const char *func)
{
    if (rc < 0) {
        syslog(LOG_ERR, "pigpio call %s failed (rc=%d): %s",
               func, rc, pigpio_error(rc));
    } else {
        syslog(LOG_INFO, "pigpio call %s succeeded (rc=%d)", func, rc);
    }
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as output with an optional initial value       */
/* ------------------------------------------------------------------ */
static int configure_output(unsigned pin, unsigned initial)
{
    int rc = gpioSetMode(pin, PI_OUTPUT);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioSetMode(%u, PI_OUTPUT) failed: %s",
               pin, pigpio_error(rc));
        return -1;
    }
    rc = gpioWrite(pin, initial);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed: %s",
               pin, initial, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as input with pull-up                          */
/* ------------------------------------------------------------------ */
static int configure_input_pullup(unsigned pin)
{
    int rc = gpioSetMode(pin, PI_INPUT);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioSetMode(%u, PI_INPUT) failed: %s",
               pin, pigpio_error(rc));
        return -1;
    }
    rc = gpioSetPullUpDown(pin, PI_PUD_UP);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%u, PI_PUD_UP) failed: %s",
               pin, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Drive the L298N motor for MOTOR_RUN_US, checking g_running every    */
/* 100 ms so SIGINT / SIGTERM can interrupt the cycle.                */
/* ------------------------------------------------------------------ */
static void run_motor(void)
{
    syslog(LOG_INFO, "Starting motor: ENA=HIGH IN1=HIGH IN2=LOW");

    int rc = gpioWrite(MOTOR_ENABLE_PIN, 1);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(ENA, 1) failed: %s", pigpio_error(rc));
        return;
    }
    rc = gpioWrite(MOTOR_IN1_PIN, 1);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(IN1, 1) failed: %s", pigpio_error(rc));
        gpioWrite(MOTOR_ENABLE_PIN, 0);
        return;
    }
    rc = gpioWrite(MOTOR_IN2_PIN, 0);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(IN2, 0) failed: %s", pigpio_error(rc));
        gpioWrite(MOTOR_ENABLE_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        return;
    }

    for (int elapsed = 0; elapsed < MOTOR_RUN_US && g_running; elapsed += 100000)
        usleep(100000);

    syslog(LOG_INFO, "Stopping motor: ENA=LOW IN1=LOW IN2=LOW");
    rc = gpioWrite(MOTOR_ENABLE_PIN, 0);
    if (rc < 0)
        syslog(LOG_ERR, "gpioWrite(ENA, 0) failed: %s", pigpio_error(rc));
    rc = gpioWrite(MOTOR_IN1_PIN, 0);
    if (rc < 0)
        syslog(LOG_ERR, "gpioWrite(IN1, 0) failed: %s", pigpio_error(rc));
    rc = gpioWrite(MOTOR_IN2_PIN, 0);
    if (rc < 0)
        syslog(LOG_ERR, "gpioWrite(IN2, 0) failed: %s", pigpio_error(rc));
}

/* ------------------------------------------------------------------ */
/* Cleanup all GPIO resources                                          */
/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    syslog(LOG_INFO, "Cleaning up GPIO resources");
    gpioWrite(MOTOR_ENABLE_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting rain_window (pigpio version %s)",
           pigpio_version());

    /* ---- Initialize pigpio ---- */
    int rc = gpioInitialise();
    if (rc < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed: %s", pigpio_error(rc));
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialized successfully");

    /* ---- Configure pins ---- */
    if (configure_input_pullup(RAIN_SENSOR_PIN) < 0) {
        syslog(LOG_ERR, "Failed to configure rain sensor pin");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }
    if (configure_output(MOTOR_ENABLE_PIN, 0) < 0 ||
        configure_output(MOTOR_IN1_PIN, 0)    < 0 ||
        configure_output(MOTOR_IN2_PIN, 0)    < 0)
    {
        syslog(LOG_ERR, "Failed to configure motor control pins");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction() failed: %m");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Entering main polling loop");

    int last_rain = 0;          /* 0 = dry, 1 = wet */
    int dry_count = 0;          /* consecutive dry polls since last wet */

    while (g_running) {
        int level = gpioRead(RAIN_SENSOR_PIN);
        if (level < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed: %s",
                   RAIN_SENSOR_PIN, pigpio_error(level));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (level == 0) {
            /* Rain detected (DO pulled low) */
            if (last_rain == 0) {
                syslog(LOG_INFO, "Rain detected (DO LOW) — starting close-window sequence");
                run_motor();
                dry_count = 0;
            } else {
                dry_count = 0;
            }
            last_rain = 1;
        } else {
            /* No rain (DO high) */
            if (last_rain == 1) {
                dry_count = 1;
            } else {
                dry_count++;
            }
            last_rain = 0;

            if (dry_count >= (DRY_REQUIRED_US / POLL_INTERVAL_US)) {
                syslog(LOG_INFO,
                       "Sensor dry for %.1f s — ready for next trigger",
                       (double)dry_count * POLL_INTERVAL_US / 1000000.0);
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    syslog(LOG_INFO, "Shutting down");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

