/*
 * door_lock.c — Raspberry Pi servo door lock control
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 *
 * Wiring:
 *   Servo signal  -> GPIO 18 (physical pin 12)
 *   Lock button   -> GPIO 21 (physical pin 32) to GND, internal pull-up enabled
 *   Unlock button -> GPIO 22 (physical pin 36) to GND, internal pull-up enabled
 *
 * The servo is driven via pigpio's hardware-PWM-capable GPIO 18.
 * A 2000 µs pulse = locked, 1000 µs pulse = unlocked.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000   /* 2 ms pulse width  -> locked   */
#define UNLOCK_PULSE_US 1000  /* 1 ms pulse width  -> unlocked */
#define STOP_PULSE_US   0     /* stop signal       -> servo off */

#define DEBOUNCE_US    50000  /* 50 ms debounce after button release */
#define POLL_US        10000  /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helper: send a servo pulse via pigpio                               */
/* ------------------------------------------------------------------ */
static int send_servo_pulse(int pulse_us)
{
    int rc = gpioServo(SERVO_PIN, pulse_us);
    if (rc < 0) {
        fprintf(stderr, "gpioServo(pin=%d, pulse=%d) failed: %s\n",
                SERVO_PIN, pulse_us, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helper: read a button with pull-up enabled                          */
/* ------------------------------------------------------------------ */
static int read_button(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead(pin=%d) failed: %s\n",
                pin, pigpio_error(level));
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SERVO_PIN=%d) failed\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(button) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the buttons read HIGH when released */
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with the servo off (0 µs pulse) */
    if (send_servo_pulse(STOP_PULSE_US) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool lock_held   = false;
    bool unlock_held = false;

    /* ---- Main polling loop ---- */
    while (g_running) {
        int lock   = read_button(LOCK_BUTTON);
        int unlock = read_button(UNLOCK_BUTTON);

        if (lock < 0 || unlock < 0) {
            /* Sensor read failure — stop the servo and exit */
            send_servo_pulse(STOP_PULSE_US);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        /* ---- Lock button pressed (active-low with pull-up) ---- */
        if (lock == 0 && !lock_held) {
            lock_held = true;
            if (send_servo_pulse(LOCK_PULSE_US) == 0) {
                printf("Door locked.\n");
                fflush(stdout);
            }
            /* Debounce: wait for release, then a short delay */
            while (g_running && gpioRead(LOCK_BUTTON) == 0)
                gpioDelay(DEBOUNCE_US);
            if (g_running)
                gpioDelay(DEBOUNCE_US);
            lock_held = false;
        }

        /* ---- Unlock button pressed ---- */
        if (unlock == 0 && !unlock_held) {
            unlock_held = true;
            if (send_servo_pulse(UNLOCK_PULSE_US) == 0) {
                printf("Door unlocked.\n");
                fflush(stdout);
            }
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0)
                gpioDelay(DEBOUNCE_US);
            if (g_running)
                gpioDelay(DEBOUNCE_US);
            unlock_held = false;
        }

        gpioDelay(POLL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fflush(stdout);

    /* Stop the servo (0 µs pulse) */
    if (send_servo_pulse(STOP_PULSE_US) != 0)
        fprintf(stderr, "Warning: failed to stop servo during shutdown\n");

    gpioTerminate();
    printf("Door lock system stopped.\n");
    return EXIT_SUCCESS;
}

