static int safe_set_relay(int level)
{
    int rc = gpioWrite(RELAY_PIN, level);
    if (rc < 0) {
        fprintf(stderr, "Error writing to relay pin %d: %s\n",
                RELAY_PIN, pigpio_error(rc));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure floodlight is OFF at startup */
    if (safe_set_relay(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security system started. PIR=GPIO%d, Relay=GPIO%d\n",
           PIR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_pir = gpioRead(PIR_PIN);
    if (last_pir < 0) {
        fprintf(stderr, "Failed to read initial PIR state\n");
        safe_set_relay(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "Error reading PIR pin %d: %s\n",
                    PIR_PIN, pigpio_error(pir));
            break;
        }

        if (pir == 1 && last_pir == 0) {
            /* Rising edge: motion detected */
            char ts[32];
            get_timestamp(ts, sizeof(ts));

            if (log_event("Motion Detected", ts, -1.0) < 0) {
                break;
            }

            printf("Motion detected at %s. Activating floodlight.\n", ts);

            if (safe_set_relay(1) < 0) {
                break;
            }

            /* Keep floodlight on for LIGHT_ON_S seconds, checking
               g_running every 100 ms so SIGINT/SIGTERM is responsive. */
            for (int elapsed = 0; elapsed < LIGHT_ON_S * 10 && g_running; elapsed++) {
                gpioDelay(POLL_US);
            }

            if (!g_running) {
                break;
            }

            if (safe_set_relay(0) < 0) {
                break;
            }

            get_timestamp(ts, sizeof(ts));
            double duration = (double)LIGHT_ON_S;
            if (log_event("Floodlight Deactivated", ts, duration) < 0) {
                break;
            }
            printf("Floodlight deactivated at %s.\n", ts);
        }

        last_pir = pir;
        gpioDelay(POLL_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    safe_set_relay(0);
    gpioTerminate();
    printf("Security system stopped.\n");
    return EXIT_SUCCESS;
}

