/*
 * MPR121 Capacitive Touch -> Relay Toggle on Rising Edge of Electrode 0
 * Board:  Raspberry Pi 5 (I2C bus 1, BCM GPIO17 as relay control)
 * Sensor: MPR121 at I2C address 0x5C (ADDR pin tied to GND)
 * Build:  gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MPR121_ADDR          0x5C          /* ADDR -> GND */
#define RELAY_GPIO           17            /* BCM 17 */
#define DEBOUNCE_MS          200           /* per-electrode debounce window */
#define POLL_DELAY_US        10000         /* 10 ms main-loop sleep */
#define DEBOUNCE_TICKS       (DEBOUNCE_MS * 1000)  /* microseconds */

/* MPR121 register addresses (datasheet rev 1.3) */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E          /* Electrode Configuration Register */
#define MPR121_SOFTRESET     0x80

/* Baseline filtering (MHD, NHD, NCL, FDL) */
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35

/* Debounce */
#define MPR121_TOUCH_DEBOUNCE 0x3B
#define MPR121_RELEASE_DEBOUNCE 0x3C

/* FFI / SFI / CDT */
#define MPR121_FFI           0x3D
#define MPR121_SFI           0x3E
#define MPR121_CDT           0x3F

/* Auto-configuration */
#define MPR121_USL           0x40
#define MPR121_LSL           0x41
#define MPR121_TL           0x42
#define MPR121_AUTO_CONFIG0  0x7B
#define MPR121_AUTO_CONFIG1  0x7C
#define MPR121_AUTO_CONFIG2  0x7D
#define MPR121_AUTO_CONFIG3  0x7E
#define MPR121_AUTO_CONFIG4  0x7F

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_relay_state = false;

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C Helpers ------------------------------- */
static int mpr121_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ----------------------------- MPR121 Init ------------------------------- */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(2000);  /* 2 ms settle after reset */

    /* Baseline filtering (rising) */
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;

    /* Baseline filtering (falling) */
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;

    /* Touch / release debounce (3 samples each) */
    if (mpr121_write_reg(MPR121_TOUCH_DEBOUNCE, 0x33) < 0) return -1;
    if (mpr121_write_reg(MPR121_RELEASE_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=3 samples, SFI=4 samples, CDT=0.5 us */
    if (mpr121_write_reg(MPR121_FFI, 0x03) < 0) return -1;
    if (mpr121_write_reg(MPR121_SFI, 0x04) < 0) return -1;
    if (mpr121_write_reg(MPR121_CDT, 0x00) < 0) return -1;

    /* Auto-config: USL=180, LSL=100, TL=0 */
    if (mpr121_write_reg(MPR121_USL, 0xB4) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 0x64) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL,  0x00) < 0) return -1;

    /* Auto-config0: enable auto-config (retries 3, max 10 samples) */
    if (mpr121_write_reg(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;

    /* Auto-config1: baseline tracking */
    if (mpr121_write_reg(MPR121_AUTO_CONFIG1, 0x10) < 0) return -1;

    /* Auto-config2: enable auto-config2 (re-enable after each config) */
    if (mpr121_write_reg(MPR121_AUTO_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config3: disable retries in auto-config3 */
    if (mpr121_write_reg(MPR121_AUTO_CONFIG3, 0x00) < 0) return -1;

    /* Auto-config4: disable retries in auto-config4 */
    if (mpr121_write_reg(MPR121_AUTO_CONFIG4, 0x00) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

/* ----------------------------- MPR121 Read ------------------------------- */
static int mpr121_read_touch_status(uint16_t *status)
{
    uint8_t lo, hi;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Relay Control ----------------------------- */
static void relay_set(bool on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(RELAY_GPIO, %d) failed\n", on ? 1 : 0);
    } else {
        g_relay_state = on;
        printf("Relay %s\n", on ? "ON" : "OFF");
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Relay GPIO setup --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(RELAY_GPIO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_set(false);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- MPR121 init --- */
    if (mpr121_init() < 0) {
        fprintf(stderr, "[FATAL] MPR121 initialisation failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 ready. Touch electrode 0 to toggle relay. Ctrl+C to exit.\n");

    /* --- Main loop --- */
    uint16_t touch_status = 0;
    uint32_t last_touch_tick = 0;

    while (g_running) {
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "[WARN] I2C read error; retrying in 100 ms\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x0001) {  /* Electrode 0 touched */
            uint32_t now = gpioTick();
            if (now - last_touch_tick > DEBOUNCE_TICKS) {
                relay_set(!g_relay_state);
                last_touch_tick = now;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    relay_set(false);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

