/*
 * Raspberry Pi 5 - Servo & PIR Security System
 *
 * Hardware:
 *   - Servo on BCM GPIO17 (physical pin 11)
 *   - PIR sensor on BCM GPIO4  (physical pin 7)
 *
 * Protocol:
 *   "the library's API call <angle>"  ->  servo angle 0-180
 *   "PIR"                             ->  PIR state (0 or 1)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o security security.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN        17
#define PIR_PIN          4
#define PORT             5000
#define BUFFER_SIZE      1024
#define LOG_FILE         "security.log"
#define SERVO_FREQ_HZ    50          /* 50 Hz -> 20 ms period */
#define SERVO_RANGE      1000       /* 1 ms..2 ms pulse width */

static volatile sig_atomic_t g_running = 1;
static int      g_server_fd = -1;
static int      g_client_fd = -1;
static FILE    *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_event(int priority, const char *fmt, ...)
{
    va_list ap;
    char ts[32];
    time_t now = time(NULL);
    struct tm tmv;

    if (localtime_r(&now, &tmv) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    va_start(ap, fmt);
    syslog(priority, "%s: ", ts);
    vsyslog(priority, fmt, ap);
    va_end(ap);

    if (g_log_file) {
        va_start(ap, fmt);
        fprintf(g_log_file, "%s [%d] ", ts, priority);
        vfprintf(g_log_file, fmt, ap);
        fputc('\n', g_log_file);
        fflush(g_log_file);
        va_end(ap);
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Servo control                                                      */
/* ------------------------------------------------------------------ */

static int set_servo_angle(int angle)
{
    if (angle < 0 || angle > 180) {
        log_event(LOG_ERR, "Invalid servo angle %d (must be 0-180)", angle);
        return -1;
    }

    /* 1 ms = 1000 us, 2 ms = 2000 us -> 1 ms/deg = 1000 us/deg */
    int pulsewidth = 1000 + (angle * 1000 / 180);

    if (gpioServo(SERVO_PIN, pulsewidth) < 0) {
        log_event(LOG_ERR, "gpioServo failed for pin %d: %s",
                  SERVO_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* PIR sensor                                                         */
/* ------------------------------------------------------------------ */

static int read_pir_sensor(void)
{
    int level = gpioRead(PIR_PIN);
    if (level < 0) {
        log_event(LOG_ERR, "gpioRead failed for pin %d: %s",
                  PIR_PIN, strerror(errno));
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* TCP server                                                         */
/* ------------------------------------------------------------------ */

static int setup_server(void)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        log_event(LOG_ERR, "socket creation failed: %s", strerror(errno));
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event(LOG_WARNING, "setsockopt(SO_REUSEADDR) failed: %s",
                  strerror(errno));
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port        = htons(PORT);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_event(LOG_ERR, "bind failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        log_event(LOG_ERR, "listen failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    log_event(LOG_INFO, "Listening on port %d", PORT);
    return fd;
}

static int handle_client(int client_fd)
{
    char buffer[BUFFER_SIZE];

    for (;;) {
        ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            log_event(LOG_ERR, "recv failed: %s", strerror(errno));
            return -1;
        }
        if (n == 0) {
            log_event(LOG_INFO, "Client disconnected");
            return 0;
        }

        buffer[n] = '\0';
        log_event(LOG_INFO, "Received: %s", buffer);

        /* Strip trailing newline / carriage return */
        for (ssize_t i = n - 1; i >= 0; i--) {
            if (buffer[i] == '\n' || buffer[i] == '\r') {
                buffer[i] = '\0';
            } else {
                break;
            }
        }

        char command[32];
        char *rest = NULL;
        if (sscanf(buffer, "%31s %ms", command, &rest) == 2) {
            if (strcmp(command, "the") == 0 &&
                strcmp(rest, "library's API call") == 0) {
                char *endptr = NULL;
                long val = strtol(buffer + strlen("the library's API call "),
                                  &endptr, 10);
                if (endptr == buffer + strlen("the library's API call ")) {
                    log_event(LOG_ERR, "Invalid angle format");
                } else if (set_servo_angle((int)val) == 0) {
                    log_event(LOG_INFO, "Servo angle set to %ld", val);
                }
            } else if (strcmp(command, "PIR") == 0) {
                int pir = read_pir_sensor();
                if (pir < 0) {
                    log_event(LOG_ERR, "Failed to read PIR sensor");
                } else {
                    char resp[32];
                    snprintf(resp, sizeof(resp), "PIR:%d", pir);
                    if (send(client_fd, resp, strlen(resp), 0) < 0) {
                        log_event(LOG_ERR, "send failed: %s", strerror(errno));
                    }
                }
            } else {
                log_event(LOG_ERR, "Unknown command: %s", command);
            }
            free(rest);
        } else {
            log_event(LOG_ERR, "Malformed command: %s", buffer);
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_client_fd >= 0) {
        close(g_client_fd);
        g_client_fd = -1;
    }
    if (g_server_fd >= 0) {
        close(g_server_fd);
        g_server_fd = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);   /* stop PWM */
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    openlog("security_system", LOG_PID | LOG_NDELAY, LOG_USER);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        /* continue without file logging */
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event(LOG_ERR, "sigaction failed: %s", strerror(errno));
        if (g_log_file) fclose(g_log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        if (g_log_file) fclose(g_log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_event(LOG_ERR, "gpioSetMode(SERVO_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_event(LOG_ERR, "gpioSetMode(PIR_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    g_server_fd = setup_server();
    if (g_server_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Security system started");

    while (g_running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        g_client_fd = accept(g_server_fd, (struct sockaddr *)&caddr, &clen);
        if (g_client_fd < 0) {
            if (errno == EINTR) continue;
            if (!g_running) break;
            log_event(LOG_ERR, "accept failed: %s", strerror(errno));
            continue;
        }

        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &caddr.sin_addr, ip, sizeof(ip));
        log_event(LOG_INFO, "Connection from %s:%d",
                  ip, ntohs(caddr.sin_port));

        handle_client(g_client_fd);
        close(g_client_fd);
        g_client_fd = -1;
    }

    log_event(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

