/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light monitor with relay control.
 *
 * Hardware:
 *   - BH1750FVI on I2C1:  SDA = GPIO2 (pin 3), SCL = GPIO3 (pin 5),
 *                         VCC = 3V3, GND = GND, Sensor Addr = 0x23
 *   - Grow-light relay:   IN = GPIO23 (BCM, pin 16), VCC = 5V, GND = GND
 *
 * Build:  gcc -O2 -Wall -o grow_monitor grow_monitor.c -lpigpio -lrt
 * Run:    sudo ./grow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23          /* ADDR pin tied to GND */
#define BH1750_CONT_HIGH_RES 0x10          /* Continuous high-resolution mode */
#define BH1750_CONV_TIME_MS  120           /* Max conversion time ~120 ms */
#define LUX_THRESHOLD        150.0f
#define RELAY_GPIO           23            /* BCM 23 — grow-light relay IN */
#define SAMPLE_INTERVAL_S    2.0           /* Seconds between readings */
#define LOG_FILE             "grow_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  read_bh1750(int handle, float *lux_out);
static void log_data(FILE *fp, float lux);
static void cleanup(void);

/* ------------------------------- Handlers -------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one sample from the BH1750.
 * Returns 0 on success and stores the lux value in *lux_out.
 * Returns -1 on I2C error or sensor-absent (no ACK on the first write).
 */
static int read_bh1750(int handle, float *lux_out)
{
    /* Trigger continuous high-resolution measurement */
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
        return -1;                 /* Sensor absent or bus error */
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_TIME_MS * 1000);  /* microseconds */

    /* Read 2 bytes of result */
    char buf[2];
    int  bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        perror("fprintf to log file");
    } else {
        fflush(fp);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIO --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* Relay OFF at startup */

    /* --- Open I2C bus to BH1750 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light monitor started.  Logging to '%s'.  Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        float lux = 0.0f;

        if (read_bh1750(g_i2c_handle, &lux) == 0) {
            log_data(g_log_file, lux);

            if (lux < LUX_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);  /* Activate relay */
            } else {
                gpioWrite(RELAY_GPIO, 0);  /* Deactivate relay */
            }

            printf("Lux: %.2f  Relay: %s\n",
                   lux,
                   (lux < LUX_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: BH1750 read failed (sensor absent or bus error).\n");
            log_data(g_log_file, -1.0f);  /* Sentinel for error entry */
        }

        /* Sleep for the remainder of the sample interval */
        time_sleep(SAMPLE_INTERVAL_S);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

