/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light monitor with relay control.
 *
 * Hardware:
 *   - BH1750FVI on I2C1:  SDA = GPIO2 (pin 3), SCL = GPIO3 (pin 5),
 *                         VCC = 3V3, GND = GND, Sensor Addr = 0x23
 *   - Grow-light relay:   IN = GPIO23 (BCM, pin 16), VCC = 5V, GND = GND
 *
 * Build:  gcc -O2 -Wall -o grow_monitor grow_monitor.c -lpigpio -lrt
 * Run:    sudo ./grow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23          /* ADDR pin tied to GND */
#define BH1750_CONT_HIGH_RES 0x10          /* Continuous high-resolution mode */
#define BH1750_CONV_TIME_MS  120           /* Max conversion time ~120 ms */
#define LUX_THRESHOLD        150.0f
#define RELAY_GPIO           23            /* BCM 23 — grow-light relay IN */
#define SAMPLE_INTERVAL_S    2.0           /* Seconds between readings */
#define LOG_FILE             "grow_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  read_bh1750(int handle, float *lux_out);
static void log_data(FILE *fp, float lux);
static void cleanup(void);

/* ------------------------------- Handlers -------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one sample from the BH1750.
 * Returns 0 on success and stores the lux value in *lux_out.
 * Returns -1 on I2C error or sensor-absent (no ACK on the first write).
 */
static int read_bh1750(int handle, float *lux_out)
{
    /* Trigger continuous high-resolution measurement */
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
        return -1;                 /* Sensor absent or bus error */
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_TIME_MS * 1000);  /* microseconds */

    /* Read 2 bytes of result */
    char buf[2];
    int  bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        perror("fprintf to log file");
    } else {
        fflush(fp);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIO --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* Relay OFF at startup */

    /* --- Open I2C bus to BH1750 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow light monitor started.  Logging to '%s'.  Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        float lux = 0.0f;

        if (read_bh1750(g_i2c_handle, &lux) == 0) {
            log_data(g_log_file, lux);

            if (lux < LUX_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);  /* Activate relay */
            } else {
                gpioWrite(RELAY_GPIO, 0);  /* Deactivate relay */
            }

            printf("Lux: %.2f  Relay: %s\n",
                   lux,
                   (lux < LUX_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: BH1750 read failed (sensor absent or bus error).\n");
            log_data(g_log_file, -1.0f);  /* Sentinel for error entry */
        }

        /* Sleep for the remainder of the sample interval */
        time_sleep(SAMPLE_INTERVAL_S);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Raspberry Pi 3 Model B+ — TAL220B load cell + HX711 + solenoid lock
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o solenoid_lock solenoid_lock.c -lgpiod
 *
 * Run:
 *   sudo ./solenoid_lock [--threshold <grams>] [--scale <factor>] [--duration <ms>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

#define HX711_DOUT_LINE  23   /* GPIO23 — input from HX711 DOUT  */
#define HX711_SCK_LINE   24   /* GPIO24 — output to HX711 SCK   */
#define SOLENOID_LINE    25   /* GPIO25 — output to solenoid     */

#define DEFAULT_THRESHOLD_GRAMS  1000
#define DEFAULT_SCALE_FACTOR     1.0
#define DEFAULT_DURATION_MS      200

#define NUM_TARE_READINGS        10
#define NUM_WEIGHT_READINGS      5
#define POLL_INTERVAL_MS         500
#define HX711_READY_TIMEOUT_MS   1000
#define HX711_CLOCK_DELAY_US     1
#define SOLENOID_SET_DELAY_US    200000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HX711 helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Read one 24-bit two's-complement sample from the HX711.
 * Returns 0 on success and stores the value in *out; returns -1 on
 * timeout (DOUT did not go LOW within HX711_READY_TIMEOUT_MS).
 */
static int hx711_read_raw(struct gpiod_line *dout, struct gpiod_line *sck,
                          int32_t *out)
{
    struct timespec t0, now;
    clock_gettime(CLOCK_MONOTONIC, &t0);

    /* Wait for DOUT to go LOW (HX711 data ready). */
    while (gpiod_line_get_value(dout) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - t0.tv_sec) * 1000L +
                          (now.tv_nsec - t0.tv_nsec) / 1000000L;
        if (elapsed_ms >= HX711_READY_TIMEOUT_MS)
            return -1;                 /* timeout — sensor absent or stuck */
        usleep(100);
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "HX711 SCK high failed: %s", strerror(errno));
            return -1;
        }
        usleep(HX711_CLOCK_DELAY_US);

        value <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0) {
            syslog(LOG_ERR, "HX711 DOUT read failed: %s", strerror(errno));
            return -1;
        }
        if (bit)
            value |= 1u;

        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "HX711 SCK low failed: %s", strerror(errno));
            return -1;
        }
        usleep(HX711_CLOCK_DELAY_US);
    }

    /* 25th clock pulse: select Channel A, gain 128. */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "HX711 SCK 25th high failed: %s", strerror(errno));
        return -1;
    }
    usleep(HX711_CLOCK_DELAY_US);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "HX711 SCK 25th low failed: %s", strerror(errno));
        return -1;
    }
    usleep(HX711_CLOCK_DELAY_US);

    /* Convert 24-bit two's-complement to int32_t. */
    if (value & 0x800000u)
        value |= 0xFF000000u;          /* sign-extend */
    *out = (int32_t)value;
    return 0;
}

/*
 * Average NUM_TARE_READINGS raw HX711 samples and return the tare
 * offset.  Returns 0 on success, -1 on error.
 */
static int hx711_tare(struct gpiod_line *dout, struct gpiod_line *sck,
                      int32_t *offset)
{
    int32_t sum = 0;
    for (int i = 0; i < NUM_TARE_READINGS; i++) {
        int32_t v;
        if (hx711_read_raw(dout, sck, &v) < 0) {
            syslog(LOG_ERR, "Tare read %d timed out", i);
            return -1;
        }
        sum += v;
        usleep(10000);                 /* 10 ms between samples */
    }
    *offset = sum / NUM_TARE_READINGS;
    syslog(LOG_INFO, "Tare offset = %d", *offset);
    return 0;
}

/*
 * Average NUM_WEIGHT_READINGS raw HX711 samples and apply the scale
 * factor.  Returns 0 on success, -1 on error.
 */
static int hx711_read_weight(struct gpiod_line *dout, struct gpiod_line *sck,
                             int32_t tare, double scale, double *weight)
{
    int32_t sum = 0;
    for (int i = 0; i < NUM_WEIGHT_READINGS; i++) {
        int32_t v;
        if (hx711_read_raw(dout, sck, &v) < 0) {
            syslog(LOG_ERR, "Weight read %d timed out", i);
            return -1;
        }
        sum += v;
        usleep(10000);
    }
    int32_t raw = sum / NUM_WEIGHT_READINGS - tare;
    *weight = (double)raw * scale;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Solenoid helpers                                                    */
/* ------------------------------------------------------------------ */

static int solenoid_set(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        syslog(LOG_ERR, "Solenoid set %d failed: %s", value, strerror(errno));
        return -1;
    }
    return 0;
}

static int solenoid_activate(struct gpiod_line *line, int duration_ms)
{
    if (solenoid_set(line, 1) < 0)
        return -1;
    usleep(duration_ms * 1000);
    if (solenoid_set(line, 0) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Argument parsing                                                    */
/* ------------------------------------------------------------------ */

static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n",
        prog);
}

static int parse_args(int argc, char *argv[],
                      int *threshold, double *scale, int *duration)
{
    *threshold = DEFAULT_THRESHOLD_GRAMS;
    *scale     = DEFAULT_SCALE_FACTOR;
    *duration  = DEFAULT_DURATION_MS;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            *threshold = atoi(argv[++i]);
            if (*threshold <= 0) {
                fprintf(stderr, "threshold must be positive\n");
                return -1;
            }
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            *scale = atof(argv[++i]);
            if (*scale <= 0.0) {
                fprintf(stderr, "scale factor must be positive\n");
                return -1;
            }
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            *duration = atoi(argv[++i]);
            if (*duration <= 0) {
                fprintf(stderr, "duration must be positive\n");
                return -1;
            }
        } else {
            fprintf(stderr, "Unknown option: %s\n", argv[i]);
            usage(argv[0]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int threshold = DEFAULT_THRESHOLD_GRAMS;
    double scale  = DEFAULT_SCALE_FACTOR;
    int duration  = DEFAULT_DURATION_MS;

    if (parse_args(argc, argv, &threshold, &scale, &duration) < 0)
        return EXIT_FAILURE;

    openlog("solenoid_lock", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting solenoid lock monitor");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_LINE);
    struct gpiod_line *sck  = gpiod_chip_get_line(chip, HX711_SCK_LINE);
    struct gpiod_line *sol  = gpiod_chip_get_line(chip, SOLENOID_LINE);
    if (!dout || !sck || !sol) {
        syslog(LOG_ERR, "gpiod_chip_get_line failed: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "request DOUT input failed: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "request SCK output failed: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "request solenoid output failed: %s", strerror(errno));
        goto cleanup;
    }

    int32_t tare = 0;
    if (hx711_tare(dout, sck, &tare) < 0) {
        syslog(LOG_ERR, "Tare failed — sensor not responding");
        goto cleanup;
    }

    syslog(LOG_INFO, "Monitoring weight (threshold %d g, scale %.2f, duration %d ms)",
           threshold, scale, duration);

    while (g_running) {
        double weight = 0.0;
        if (hx711_read_weight(dout, sck, tare, scale, &weight) < 0) {
            syslog(LOG_ERR, "Weight read failed — exiting");
            break;
        }

        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded — activating solenoid");
            if (solenoid_activate(sol, duration) < 0)
                syslog(LOG_ERR, "Solenoid activation failed");
        }

        /* Sleep in 100 ms slices so signals are caught promptly. */
        for (int ms = 0; ms < POLL_INTERVAL_MS && g_running; ms += 100)
            usleep(100000);
    }

    /* Ensure solenoid is off before releasing resources. */
    solenoid_set(sol, 0);

cleanup:
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(sol);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

