/*
 * relay_controller.c — Raspberry Pi 4 Model B
 *
 * Controls a relay module on GPIO17 (BCM 17, physical pin 11) via MQTT.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *               -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define GPIO_PIN       17
#define POLL_DELAY_US  1000000          /* 1 s */
#define RECONNECT_DELAY_S 5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

static int gpio_set_relay(int state)
{
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", GPIO_PIN);
        return -1;
    }
    if (gpioWrite(GPIO_PIN, state) < 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_PIN, state);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                       int     rc,
                       int     flags)
{
    (void)userdata;
    (void)flags;

    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker at %s:%d",
               MQTT_HOST, MQTT_PORT);

        rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc == MOSQ_ERR_SUCCESS) {
            syslog(LOG_INFO, "Subscribed to topic: %s", MQTT_TOPIC);
        } else {
            syslog(LOG_ERR, "Subscribe failed: %s", mosquitto_strerror(rc));
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(rc));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Disconnected cleanly from MQTT broker");
    } else {
        syslog(LOG_ERR, "Unexpected MQTT disconnect: %s",
               mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT payload received on topic %s",
               message->topic ? message->topic : "(null)");
        return;
    }

    /* NUL-terminate the payload safely */
    char payload[32];
    int copy_len = message->payloadlen < (int)sizeof(payload) - 1
                   ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, copy_len);
    payload[copy_len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (gpio_set_relay(1) == 0) {
            syslog(LOG_INFO, "Relay ON (GPIO%d HIGH)", GPIO_PIN);
        } else {
            syslog(LOG_ERR, "Failed to set relay ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpio_set_relay(0) == 0) {
            syslog(LOG_INFO, "Relay OFF (GPIO%d LOW)", GPIO_PIN);
        } else {
            syslog(LOG_ERR, "Failed to set relay OFF");
        }
    } else {
        syslog(LOG_ERR, "Invalid MQTT payload: \"%s\"", payload);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT client                                                         */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed (out of memory)");
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect to %s:%d failed: %s",
               MQTT_HOST, MQTT_PORT, mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void mqtt_run(void)
{
    int rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start failed: %s",
               mosquitto_strerror(rc));
        return;
    }

    while (g_running) {
        rc = mosquitto_loop_read(g_mosq, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop_read error: %s",
                   mosquitto_strerror(rc));
            break;
        }
        gpioDelay(POLL_DELAY_US);
    }

    rc = mosquitto_loop_stop(g_mosq, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_stop failed: %s",
               mosquitto_strerror(rc));
    }
}

static void mqtt_cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_set_relay(0) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started (GPIO%d)", GPIO_PIN);

    while (g_running) {
        if (mqtt_init() == 0) {
            mqtt_run();
            mqtt_cleanup();
        } else {
            syslog(LOG_ERR, "MQTT initialization failed; retrying in %d s",
                   RECONNECT_DELAY_S);
            sleep(RECONNECT_DELAY_S);
        }
    }

    /* Ensure relay is OFF before exiting */
    gpio_set_relay(0);
    gpioTerminate();
    syslog(LOG_INFO, "Relay controller stopped");
    closelog();
    return EXIT_SUCCESS;
}

