#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_CENTER_PULSE_WIDTH 1500

#define SERVO1_TARGET 1000
#define SERVO2_TARGET 1500
#define SERVO3_TARGET 2000
#define SERVO4_TARGET 500
#define SERVO5_TARGET 2500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d] on pin %d\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH, pin);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d (pw=%d)\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

static int move_servo(int pin, int target_pulse_width, int hold_seconds) {
    if (set_servo_pulse(pin, target_pulse_width) != 0) {
        return -1;
    }
    for (int i = 0; i < hold_seconds && g_running; i++) {
        sleep(1);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int targets[] = {SERVO1_TARGET, SERVO2_TARGET, SERVO3_TARGET, SERVO4_TARGET, SERVO5_TARGET};

    for (int i = 0; i < 5 && g_running; i++) {
        if (move_servo(pins[i], targets[i], 3) != 0) {
            fprintf(stderr, "Error: failed to move servo %d\n", i + 1);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    gpioServo(SERVO1_PIN, 0);
    gpioServo(SERVO2_PIN, 0);
    gpioServo(SERVO3_PIN, 0);
    gpioServo(SERVO4_PIN, 0);
    gpioServo(SERVO5_PIN, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

