/*
 * Miniature vehicle closed-loop DC motor speed control
 * Raspberry Pi 3 Model B+
 *
 * DRV8833 H-bridge control:
 *   Motor A PWM  -> GPIO17 (BCM)
 *   Motor A dir  -> GPIO18 (BCM)
 *   Motor B PWM  -> GPIO22 (BCM)
 *   Motor B dir  -> GPIO23 (BCM)
 *
 * Quadrature encoders:
 *   Encoder A phase A -> GPIO4
 *   Encoder A phase B -> GPIO5
 *   Encoder B phase A -> GPIO6
 *   Encoder B phase B -> GPIO12
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN   17
#define MOTOR_A_DIR_PIN   18
#define MOTOR_B_PWM_PIN   22
#define MOTOR_B_DIR_PIN   23

#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

/* ---- Control parameters ---- */
#define TARGET_RPM        50.0f
#define PWM_FREQUENCY     10000   /* Hz */
#define PWM_RANGE         255
#define TICKS_PER_REV     64      /* quadrature: 4 edges per revolution */
#define CONTROL_PERIOD_US 100000  /* 100 ms */
#define STALL_TIMEOUT_S   2.0

/* ---- PI controller gains ---- */
#define KP 100.0f
#define KI 0.1f

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* Encoder tick counters (read/written from ISRs) */
static volatile int32_t g_enc_a_ticks = 0;
static volatile int32_t g_enc_b_ticks = 0;

/* Stall detection */
static volatile uint32_t g_last_tick_a = 0;
static volatile uint32_t g_last_tick_b = 0;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void motor_set(int pwm_pin, int dir_pin, int duty);
static int  calculate_pwm(float target_rpm, float current_rpm);
static void control_loop(void);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor PWM pins ---- */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor PWM pin mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor direction pins ---- */
    if (gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor direction pin mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure encoder pins as inputs ---- */
    if (gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder pin mode.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency and range ---- */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register encoder ISRs ---- */
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register encoder A ISR.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register encoder B ISR.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    control_loop();

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)userdata;

    /* Count rising edges as +1 tick (quadrature, single-phase) */
    g_enc_a_ticks++;
    g_last_tick_a = tick;
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)userdata;

    g_enc_b_ticks++;
    g_last_tick_b = tick;
}

/* ------------------------------------------------------------------ */
static void motor_set(int pwm_pin, int dir_pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    /* Drive one input high, the other PWM-modulated, forward motion */
    gpioWrite(dir_pin, 1);
    gpioPWM(pwm_pin, duty);
}

/* ------------------------------------------------------------------ */
static int calculate_pwm(float target_rpm, float current_rpm)
{
    static float integral = 0.0f;
    float error = target_rpm - current_rpm;

    integral += error;

    /* Anti-windup clamp */
    if (integral > PWM_RANGE)  integral = PWM_RANGE;
    if (integral < 0.0f)       integral = 0.0f;

    float output = KP * error + KI * integral;

    if (output < 0.0f)   output = 0.0f;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return (int)output;
}

/* ------------------------------------------------------------------ */
static void control_loop(void)
{
    uint32_t last_tick = gpioTick();

    while (g_running) {
        uint32_t now = gpioTick();
        uint32_t elapsed = now - last_tick;  /* pigpio ticks are uint32_t; wraps are handled by subtraction */
        if (elapsed == 0) elapsed = 1;       /* avoid division by zero */

        /* ---- Read encoder tick counts (atomically) ---- */
        int32_t ticks_a = g_enc_a_ticks;
        int32_t ticks_b = g_enc_b_ticks;
        g_enc_a_ticks = 0;
        g_enc_b_ticks = 0;

        /* ---- Compute RPM from ticks per second ---- */
        float rpm_a = (float)ticks_a * 60.0f / (float)TICKS_PER_REV / ((float)elapsed / 1000000.0f);
        float rpm_b = (float)ticks_b * 60.0f / (float)TICKS_PER_REV / ((float)elapsed / 1000000.0f);

        /* ---- Stall detection ---- */
        if ((now - g_last_tick_a) > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            fprintf(stderr, "Warning: Encoder A stall detected (no ticks for >%.1f s).\n", STALL_TIMEOUT_S);
        }
        if ((now - g_last_tick_b) > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            fprintf(stderr, "Warning: Encoder B stall detected (no ticks for >%.1f s).\n", STALL_TIMEOUT_S);
        }

        /* ---- PI control for both motors ---- */
        int pwm_a = calculate_pwm(TARGET_RPM, rpm_a);
        int pwm_b = calculate_pwm(TARGET_RPM, rpm_b);

        /* ---- Drive motors ---- */
        motor_set(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, pwm_a);
        motor_set(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, pwm_b);

        printf("Motor A RPM: %7.2f  PWM: %3d  |  Motor B RPM: %7.2f  PWM: %3d\n",
               rpm_a, pwm_a, rpm_b, pwm_b);

        last_tick = now;
        gpioDelay(CONTROL_PERIOD_US);  /* 100 ms */
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motors */
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);

    /* Release ISRs */
    gpioSetISRFuncEx(ENCODER_A_PHASE_A, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_PHASE_A, RISING_EDGE, 0, NULL, NULL);

    /* Terminate pigpio */
    gpioTerminate();
}

