/*
 * Chicken Coop Automatic Lighting System
 * Board:  Raspberry Pi 4 Model B
 * Sensor: BH1750 light sensor (I2C bus 1, address 0x23)
 * Relay:  12 V LED strip driven via active-high relay on GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o coop_light coop_light.c -lpigpio -lrt
 * Run:    sudo ./coop_light
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23
#define BH1750_CONT_HIGH_RES  0x10   /* One-time high-resolution mode */
#define BH1750_MEASURE_MS    180    /* Conversion time after issuing mode */

#define RELAY_GPIO           17     /* BCM pin for relay control */

#define DUSK_LUX             50     /* Turn relay ON  below this */
#define DAWN_LUX             200    /* Turn relay OFF above this */

#define POLL_INTERVAL_S      5
#define LOG_FILE             "chicken_coop_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  bh1750_init(int bus, int addr);
static int  bh1750_read_lux(int handle);
static void relay_set(int gpio, int state);
static void log_event(int lux, int relay_state);
static void log_error(const char *msg);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- BH1750 ---------------------------------- */
static int bh1750_init(int bus, int addr)
{
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                bus, addr, handle);
        return -1;
    }
    return handle;
}

/*
 * Send the one-time-high-resolution measurement command, wait for the
 * conversion to complete, then read the 2-byte result.  Returns lux
 * (0–65535) on success, -1 on I2C error.
 */
static int bh1750_read_lux(int handle)
{
    /* Issue one-time high-resolution measurement */
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "[ERROR] BH1750: i2cWriteByte failed\n");
        return -1;
    }

    /* Wait for the conversion to complete */
    gpioDelay(BH1750_MEASURE_MS * 1000);  /* microseconds */

    /* Read 2 bytes of result */
    char buf[2];
    int  n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[ERROR] BH1750: i2cReadDevice returned %d\n", n);
        return -1;
    }

