/*
 * TTP223 capacitive touch sensor -> relay toggle on Raspberry Pi Zero W
 *
 * Wiring:
 *   TTP223 VCC  -> 3.3 V (pin 1)
 *   TTP223 GND  -> GND    (pin 9)
 *   TTP223 OUT  -> GPIO4  (pin 7, physical pin 14)
 *   Relay IN    -> GPIO17 (pin 11, physical pin 18)
 *   Relay VCC   -> 5 V    (pin 2 or 4)
 *   Relay GND   -> GND    (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4    /* GPIO4  - TTP223 OUT  */
#define RELAY_PIN      17   /* GPIO17 - relay IN    */
#define DEBOUNCE_US    50000 /* 50 ms debounce window */
#define LOOP_SLEEP_US  10000 /* 10 ms main-loop sleep  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_relay_state(int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        perror("localtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] Relay %s\n", ts, state ? "ON" : "OFF");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_PIN);
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        return -1;
    }

    /* Start with relay OFF */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay state on GPIO%d\n", RELAY_PIN);
        return -1;
    }

    log_relay_state(0);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Best-effort: ensure relay is OFF */
    (void)gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    bool touch_active = false;

    while (g_running) {
        int touch = gpioRead(TOUCH_PIN);
        if (touch < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", TOUCH_PIN);
            break;
        }

        if (touch == 1) {
            if (!touch_active) {
                /* Rising edge: debounce */
                gpioDelay(DEBOUNCE_US);

                touch = gpioRead(TOUCH_PIN);
                if (touch < 0) {
                    fprintf(stderr, "gpioRead failed on GPIO%d\n", TOUCH_PIN);
                    break;
                }

                if (touch == 1) {
                    /* Valid touch detected */
                    relay_state = !relay_state;
                    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                        fprintf(stderr, "gpioWrite failed on GPIO%d\n", RELAY_PIN);
                        break;
                    }
                    log_relay_state(relay_state);
                    touch_active = true;
                }
            }
        } else {
            /* Sensor released */
            touch_active = false;
        }

        gpioDelay(LOOP_SLEEP_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

