/*
 * water_flow_control.c — Raspberry Pi 5
 *
 * Monitors a YF-S201 water-flow sensor on GPIO 17 (BCM) and controls a
 * solenoid valve on GPIO 27 (BCM).  A 1-second ISR debounce timeout
 * guards the flow-sensor pin, and a 1-second sampling window reports
 * LPM and logs every solenoid state change.
 *
 * Build:  gcc -O2 -Wall -Wextra -o water_flow_control water_flow_control.c -lpigpio -lpthread
 * Run:    sudo ./water_flow_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN      17          /* BCM 17 — YF-S201 signal  */
#define SOLENOID_PIN         27          /* BCM 27 — solenoid control */

#define FLOW_THRESHOLD_HIGH  5.0         /* LPM — close valve above  */
#define FLOW_THRESHOLD_LOW   4.5         /* LPM — open valve below   */
#define DEBOUNCE_US          1000000     /* 1 s debounce window      */
#define SAMPLE_PERIOD_US     1000000     /* 1 s sampling window      */
#define LOG_FILE             "water_flow.log"

/* ------------------------------------------------------------------ */
/* Shared state                                                        */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_pulse_count = 0;
static volatile uint32_t g_last_tick   = 0;
static pthread_mutex_t   g_mutex       = PTHREAD_MUTEX_INITIALIZER;
static FILE             *g_log_fp      = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
