#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define PORT 12345
#define CALIBRATION_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_SERVO_PULSE_WIDTH 1500
#define HX711_TIMEOUT_US 1000
#define HX711_CLOCK_PULSE_US 1
#define DISPENSE_DELAY_US 1000000
#define SERVO_SETTLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static int servo_pulse_width = DEFAULT_SERVO_PULSE_WIDTH;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file, using defaults.\n");
        return -1;
    }
    char line[256];
    int found = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "calibration_factor", 17) == 0) {
            if (sscanf(line, "calibration_factor = %lf", &calibration_factor) == 1) {
                found = 1;
                break;
            }
        }
    }
    fclose(fp);
    if (!found) {
        fprintf(stderr, "Warning: calibration_factor not found, using default.\n");
        return -1;
    }
    if (calibration_factor <= 0.0) {
        fprintf(stderr, "Warning: Invalid calibration factor, using default.\n");
        calibration_factor = DEFAULT_CALIBRATION_FACTOR;
        return -1;
    }
    return 0;
}

static int hx711_read(void) {
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    int data = 0;
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout >= HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout (sensor absent or not ready).\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(HX711_CLOCK_PULSE_US);
        data = (data << 1) | gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(HX711_CLOCK_PULSE_US);
    }

    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(HX711_CLOCK_PULSE_US);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(HX711_CLOCK_PULSE_US);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }
    return data;
}

static double read_weight(void) {
    int raw = hx711_read();
    if (raw < 0) return -1.0;
    return (double)raw / calibration_factor;
}

static int dispense_ingredient(double target_weight) {
    int pulse_width = (int)(target_weight * 10.0 + 1000.0);
    if (pulse_width < 1000) pulse_width = 1000;
    if (pulse_width > 2000) pulse_width = 2000;

    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width.\n");
        return -1;
    }
    gpioDelay(DISPENSE_DELAY_US);
    return 0;
}

static void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message ? error_message : "");
    fclose(fp);
}

static void send_weight(double weight) {
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", weight);
    if (send(client_fd, buffer, len, 0) < 0) {
        fprintf(stderr, "Error: Failed to send weight.\n");
    }
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        fprintf(stderr, "Error: recv failed.\n");
        return;
    }
    if (valread == 0) {
        fprintf(stderr, "Client disconnected.\n");
        return;
    }
    buffer[valread] = '\0';

    double target_weight = strtod(buffer, NULL);
    if (target_weight <= 0.0) {
        fprintf(stderr, "Error: Invalid target weight.\n");
        send_weight(-1.0);
        return;
    }

    if (dispense_ingredient(target_weight) != 0) {
        fprintf(stderr, "Error: Dispensing failed.\n");
        send_weight(-1.0);
        log_dispensing_event(target_weight, -1.0, "Dispensing failed");
        return;
    }

    gpioDelay(SERVO_SETTLE_DELAY_US);
    double actual_weight = read_weight();
    if (actual_weight < 0) {
        fprintf(stderr, "Error: Failed to read weight after dispensing.\n");
        send_weight(-1.0);
        log_dispensing_event(target_weight, -1.0, "Weight read failed");
        return;
    }

    send_weight(actual_weight);
    log_dispensing_event(target_weight, actual_weight, NULL);
}

static int setup_server(void) {
    struct sockaddr_in address;
    int opt = 1;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        return -1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    read_config();

    if (setup_server() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (!running) break;
            perror("accept failed");
            continue;
        }
        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        handle_client(client_fd);
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

