#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, %d) failed\n", relay_state);
        return -1;
    }
    log_relay_state(relay_state);
    return 0;
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce interval must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(RELAY_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started. Touch GPIO%d, Relay GPIO%d, Debounce %d ms.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN, debounce_ms);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_touch_state < 0) {
        fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_touch_state < 0) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed\n");
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            if (toggle_relay() != 0) {
                break;
            }
            gpioDelay(debounce_ms * 1000);
        }

        last_touch_state = current_touch_state;
        gpioDelay(10000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

