/*
 * servo_adjust.c — Adjust an SG90 servo angle via keyboard on a Raspberry Pi.
 *
 * Wiring:
 *   SG90 signal  -> GPIO18 (BCM 18, physical pin 12)
 *   SG90 V+      -> 5 V (physical pin 2 or 4)
 *   SG90 GND     -> GND (physical pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o servo_adjust servo_adjust.c -lpigpio -lrt
 *   (pigpio must be installed and the daemon must NOT be running.)
 *
 * Run:
 *   sudo ./servo_adjust
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN        18          /* BCM 18 — hardware PWM0 on Pi 4/5 */
#define SERVO_FREQ_HZ    50          /* 20 ms period = 50 Hz */
#define SERVO_RANGE      1000        /* µs per pulse unit */
#define MIN_ANGLE        0
#define MAX_ANGLE        180
#define MIN_PULSE_US     500         /* SG90 safe lower bound */
#define MAX_PULSE_US     2500        /* SG90 safe upper bound */
#define INITIAL_ANGLE    90
#define STEP_DEGREES     10

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Terminal helpers                                                    */
/* ------------------------------------------------------------------ */
static int save_terminal_mode(struct termios *saved)
{
    if (tcgetattr(STDIN_FILENO, saved) != 0) {
        perror("tcgetattr");
        return -1;
    }
    return 0;
}

static int set_raw_terminal(void)
{
    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    /* Raw mode: no echo, no canonical, no signals, no special chars */
    cfmakeraw(&tty);
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal_mode(const struct termios *saved)
{
    if (saved != NULL)
        tcsetattr(STDIN_FILENO, TCSANOW, saved);
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int angle_to_pulse_us(int angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US +
           (int)((long)(angle - MIN_ANGLE) *
                 (MAX_PULSE_US - MIN_PULSE_US) /
                 (MAX_ANGLE - MIN_ANGLE));
}

static int set_servo_angle(int angle)
{
    int pulse = angle_to_pulse_us(angle);

    /*
     * gpioServo() sets the hardware PWM on the GPIO pin at the given
     * pulse width (µs).  Returns 0 on success, negative on error.
     */
    int rc = gpioServo(SERVO_PIN, pulse);
    if (rc < 0) {
        fprintf(stderr,
                "gpioServo(pin=%d, pulse=%d µs) failed: %s (rc=%d)\n",
                SERVO_PIN, pulse, pigpio_error(rc), rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct termios *saved)
{
    /* Stop PWM pulses on the servo pin */
    gpioServo(SERVO_PIN, 0);
    restore_terminal_mode(saved);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct termios saved = {0};
    int angle = INITIAL_ANGLE;
    int rc;

    /* --- Install SIGINT handler for clean Ctrl-C exit --------------- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Save terminal mode for restoration -------------------------- */
    if (save_terminal_mode(&saved) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set raw terminal mode -------------------------------------- */
    if (set_raw_terminal() != 0) {
        cleanup(&saved);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set servo to initial angle --------------------------------- */
    if (set_servo_angle(angle) != 0) {
        cleanup(&saved);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo angle: %d°  (+ = +%d°, - = -%d°, q = quit)\n",
           angle, STEP_DEGREES, STEP_DEGREES);
    fflush(stdout);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            /* No data available — loop and check g_running */
            continue;
        }

        switch (c) {
        case '+':
            angle += STEP_DEGREES;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            break;
        case '-':
            angle -= STEP_DEGREES;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            break;
        case 'q':
        case 'Q':
            g_running = 0;
            break;
        default:
            continue; /* ignore other characters */
        }

        if (set_servo_angle(angle) != 0) {
            cleanup(&saved);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Servo angle: %d°\n", angle);
        fflush(stdout);
    }

    /* --- Clean shutdown --------------------------------------------- */
    cleanup(&saved);
    gpioTerminate();
    return EXIT_SUCCESS;
}

