    int angle = INITIAL_ANGLE;
    int rc;

    /* --- Install SIGINT handler for clean Ctrl-C exit --------------- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Save terminal mode for restoration -------------------------- */
    if (save_terminal_mode(&saved) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set raw terminal mode -------------------------------------- */
    if (set_raw_terminal() != 0) {
        cleanup(&saved);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set servo to initial angle --------------------------------- */
    if (set_servo_angle(angle) != 0) {
        cleanup(&saved);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo angle: %d°  (+ = +%d°, - = -%d°, q = quit)\n",
           angle, STEP_DEGREES, STEP_DEGREES);
    fflush(stdout);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            /* No data available — loop and check g_running */
            continue;
        }

        switch (c) {
        case '+':
            angle += STEP_DEGREES;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            break;
        case '-':
            angle -= STEP_DEGREES;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            break;
        case 'q':
        case 'Q':
            g_running = 0;
            break;
        default:
            continue; /* ignore other characters */
        }

        if (set_servo_angle(angle) != 0) {
            cleanup(&saved);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Servo angle: %d°\n", angle);
        fflush(stdout);
    }

    /* --- Clean shutdown --------------------------------------------- */
    cleanup(&saved);
    gpioTerminate();
    return EXIT_SUCCESS;
}

