/*
 * RPM monitor using an A3144 Hall-effect sensor with a two-pole magnet
 * on a conveyor-belt motor.
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - A3144 Hall-effect sensor data pin -> GPIO17 (BCM 17, physical pin 11)
 *   - Internal pull-up enabled (libgpiod drives the line high when the
 *     magnet is away, low when the magnet is near).
 *   - Two-pole magnet mounted on the motor shaft (one pulse per revolution).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_rpm motor_rpm.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE_NAME    "motor_rpm.log"
#define SAMPLE_INTERVAL  5          /* seconds between RPM reports */
#define DEBOUNCE_MS      2          /* debounce window (ms) */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return monotonic milliseconds since an epoch-like start.            */
static uint64_t monotonic_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000ULL + (uint64_t)ts.tv_nsec / 1000000ULL;
}

/* ------------------------------------------------------------------ */
/* Return ISO-8601 timestamp string (caller frees).                    */
static char *iso8601_now(void)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return NULL;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return NULL;
    }
    char *buf = malloc(32);
    if (!buf) {
        perror("malloc");
        return NULL;
    }
    if (strftime(buf, 32, "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        free(buf);
        return NULL;
    }
    return buf;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* ---- open log file --------------------------------------------- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE_NAME ")");
        goto cleanup;
    }

    /* ---- open GPIO chip and line ----------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request rising-edge events with internal pull-up.
     * The A3144 output idles high when the magnet is away,
     * pulling low when the magnet is near. */
    if (gpiod_line_request_rising_edge_events_flags(line, "motor_rpm",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_rising_edge_events_flags");
        goto cleanup;
    }

    printf("Monitoring RPM on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* ---- main sampling loop ---------------------------------------- */
    uint64_t last_sample_ms = monotonic_ms();
    uint64_t last_pulse_ms  = last_sample_ms;
    uint64_t last_event_ms  = last_sample_ms;
    unsigned long pulse_count = 0;

    while (g_running) {
        uint64_t now_ms = monotonic_ms();
        if (now_ms == 0) {
            fprintf(stderr, "monotonic_ms failed\n");
            goto cleanup;
        }

        /* ---- consume any pending edge events ----------------------- */
        struct timespec ts = { 0, 100000000 };   /* 100 ms timeout */
        int ev = gpiod_line_event_wait(line, &ts);
        if (ev < 0) {
            if (errno == EINTR) {
                continue;   /* signal interrupted — re-check g_running */
            }
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) < 0) {
                if (errno == EINTR) {
                    continue;
                }
                perror("gpiod_line_event_read");
                goto cleanup;
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                uint64_t event_ms = monotonic_ms();
                if (event_ms == 0) {
                    fprintf(stderr, "monotonic_ms failed\n");
                    goto cleanup;
                }
                /* Debounce: ignore events within DEBOUNCE_MS of the
                 * last accepted pulse. */
                if (event_ms - last_pulse_ms > DEBOUNCE_MS) {
                    pulse_count++;
                    last_pulse_ms = event_ms;
                }
                last_event_ms = event_ms;
            }
        }

        /* ---- sample interval elapsed -------------------------------- */
        if (now_ms - last_sample_ms >= (uint64_t)SAMPLE_INTERVAL * 1000ULL) {
            /* RPM over the interval: pulses / (interval seconds) * 60 */
            uint64_t elapsed_s = (now_ms - last_sample_ms) / 1000ULL;
            float rpm = (float)pulse_count / (float)elapsed_s * 60.0f;

            char *ts = iso8601_now();
            if (ts) {
                fprintf(log_file, "%s,%.2f\n", ts, rpm);
                fflush(log_file);
                free(ts);
            } else {
                fprintf(stderr, "iso8601_now failed\n");
                goto cleanup;
            }

            printf("[%s] RPM: %.2f\n", ts ? ts : "?", rpm);
            if (ts) free(ts);

            /* Reset for the next interval. */
            pulse_count = 0;
            last_sample_ms = now_ms;
        }

        /* ---- sleep for a short poll interval ------------------------ */
        struct timespec sleep_ts = { 0, 10000000 };   /* 10 ms */
        nanosleep(&sleep_ts, NULL);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    return ret;
}

