/*
 * TTP223 capacitive touch → relay toggle on Raspberry Pi 5.
 *
 * Wiring:
 *   TTP223 OUT  → BCM GPIO4  (active-HIGH, 3.3 V output)
 *   Relay IN    → BCM GPIO17 (active-HIGH relay module)
 *   Relay VCC   → 5 V, Relay GND → GND
 *   TTP223 VCC  → 3.3 V, TTP223 GND → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17

#define POLL_DELAY_US  50000          /* 50 ms  */
#define HOLD_TIMEOUT   10             /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return 0 on success, -1 on failure.                                 */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Return 0 on success, -1 on failure.                                 */
static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Return 0 on success, -1 on failure.                                 */
static int safe_read(unsigned pin, int *out)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%u) failed: %d\n", pin, v);
        return -1;
    }
    *out = v;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is OFF before terminating pigpio. */
    (void)gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ------------------------------------------- */
    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with relay OFF. */
    if (safe_write(RELAY_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch relay ready. Touch BCM GPIO%d to toggle relay on BCM GPIO%d.\n",
           TOUCH_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ------------------------------------------------- */
    bool      relay_state   = false;
    bool      touch_active  = false;
    uint32_t  touch_start   = 0;

    while (g_running) {
        int touch_val = 0;
        if (safe_read(TOUCH_PIN, &touch_val) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (touch_val == 1) {
            if (!touch_active) {
                /* Rising edge: toggle relay. */
                relay_state = !relay_state;
                if (safe_write(RELAY_PIN, relay_state ? 1 : 0) != 0) {
                    cleanup();
                    return EXIT_FAILURE;
                }
                printf("Relay %s\n", relay_state ? "ON" : "OFF");
                touch_active = true;
                touch_start  = gpioTick();   /* microseconds since boot */
            } else {
                /* Sensor already HIGH — check hold timeout. */
                uint32_t elapsed = gpioTick() - touch_start;
                if (elapsed > (uint32_t)(HOLD_TIMEOUT * 1000000)) {
                    /* Force relay OFF and ignore further toggles until release. */
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        cleanup();
                        return EXIT_FAILURE;
                    }
                    relay_state = false;
                    printf("Hold timeout (%d s) — relay forced OFF\n", HOLD_TIMEOUT);
                }
            }
        } else {
            /* Sensor released. */
            touch_active = false;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

