                if (safe_write(RELAY_PIN, relay_state ? 1 : 0) != 0) {
                    cleanup();
                    return EXIT_FAILURE;
                }
                printf("Relay %s\n", relay_state ? "ON" : "OFF");
                touch_active = true;
                touch_start  = gpioTick();   /* microseconds since boot */
            } else {
                /* Sensor already HIGH — check hold timeout. */
                uint32_t elapsed = gpioTick() - touch_start;
                if (elapsed > (uint32_t)(HOLD_TIMEOUT * 1000000)) {
                    /* Force relay OFF and ignore further toggles until release. */
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        cleanup();
                        return EXIT_FAILURE;
                    }
                    relay_state = false;
                    printf("Hold timeout (%d s) — relay forced OFF\n", HOLD_TIMEOUT);
                }
            }
        } else {
            /* Sensor released. */
            touch_active = false;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

