/*
 * Proportional solenoid valve flow control for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - ASCO RedHat 8210 series proportional solenoid valve
 *       PWM signal:  GPIO 18 (BCM), hardware PWM channel 0
 *       Direction:  GPIO 23 (BCM), active-high enable
 *   - YF-S201 flow sensor
 *       Signal:     GPIO 24 (BCM), rising-edge interrupt
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_control flow_control.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define VALVE_PWM_PIN        18          /* BCM 18  - hardware PWM0  */
#define VALVE_DIR_PIN        23          /* BCM 23  - valve enable  */
#define FLOW_SENSOR_PIN      24          /* BCM 24  - YF-S201 signal */

#define PWM_FREQUENCY        1000        /* Hz                       */
#define PWM_RANGE            255         /* duty 0..255              */

#define SAMPLE_PERIOD_US     100000      /* 100 ms between samples   */
#define FLOW_WINDOW_SAMPLES  10          /* rolling-average window   */

#define KP                   1.0         /* proportional gain        */

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_file = NULL;
static double                g_target_flow = 0.0;

/* Flow sensor state (accessed from ISR and main thread) */
static volatile unsigned int g_flow_count = 0;
static volatile uint32_t     g_last_tick  = 0;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata);
static double calculate_flow_rate(void);
static int   set_valve_position(int position);
static void  log_data(double flow_rate, int valve_position);
static void  cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Flow sensor ISR --------------------------- */

/*
 * YF-S201 output is a digital pulse proportional to flow rate.
 * Count rising edges over a 100 ms window, then convert to L/min.
 */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1)            /* only rising edges */
        return;

    uint32_t prev = g_last_tick;
    g_last_tick   = tick;

    /* pigpio tick wraps every ~72 min (32-bit microseconds) */
    uint32_t diff = tick - prev;
    if (diff == 0)             /* spurious glitch */
        return;

    /* YF-S201: ~100 Hz pulse for 1 L/min => 1 pulse per 10 ms */
    unsigned int pulses = diff / 10000;   /* integer pulses in 100 ms */
    if (pulses > 0)
        g_flow_count += pulses;
}

/* ----------------------------- Flow rate calculation --------------------- */

static double calculate_flow_rate(void)
{
    static unsigned int window[FLOW_WINDOW_SAMPLES];
    static int          idx = 0;
    static int          filled = 0;
    static unsigned int sum   = 0;

    unsigned int current = g_flow_count;
    g_flow_count = 0;

    sum -= window[idx];
    window[idx] = current;
    sum += current;
    idx = (idx + 1) % FLOW_WINDOW_SAMPLES;
    if (filled < FLOW_WINDOW_SAMPLES)
        filled++;

    unsigned int avg = (filled > 0) ? (sum / (unsigned int)filled) : 0;

    /* avg counts in 100 ms => L/min = avg * (60 s/min) / (100 ms/s) */
    return (double)avg * 6.0;
}

/* ----------------------------- Valve control ----------------------------- */

static int set_valve_position(int position)
{
    if (position < 0)
        position = 0;
    if (position > PWM_RANGE)
        position = PWM_RANGE;

    if (gpioPWM(VALVE_PWM_PIN, position) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", VALVE_PWM_PIN);
        return -1;
    }
    return 0;
}

/* ----------------------------- Data logging ------------------------------- */

static void log_data(double flow_rate, int valve_position)
{
    if (g_log_file == NULL)
        return;

    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long timestamp_ms = (long)(ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (fprintf(g_log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf to log file");
    } else {
        fflush(g_log_file);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    /* Stop PWM first for safety */
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0)
        fprintf(stderr, "Warning: gpioPWM stop failed\n");

    /* Ensure valve is off */
    if (gpioWrite(VALVE_DIR_PIN, 0) < 0)
        fprintf(stderr, "Warning: gpioWrite(VALVE_DIR_PIN, 0) failed\n");

    /* Release ISR */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL) < 0)
        fprintf(stderr, "Warning: gpioSetISRFuncEx unregistration failed\n");

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(int argc, char *argv[])
{
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_target_flow = atof(optarg);
                if (g_target_flow <= 0.0) {
                    fprintf(stderr, "Error: target flow rate must be positive (L/min)\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_per_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (g_target_flow == 0.0) {
        fprintf(stderr, "Error: target flow rate must be specified with -t\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure valve direction pin as output, initially low */
    if (gpioSetMode(VALVE_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(VALVE_DIR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_DIR_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(VALVE_DIR_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure valve PWM pin: hardware PWM0, 1 kHz, range 0-255 */
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(VALVE_PWM_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM initial stop failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure flow sensor pin as input with pull-down */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(FLOW_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for flow sensor pin %d\n",
                FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate_L_per_min,valve_position\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow: %.2f L/min\n", g_target_flow);
    printf("Valve PWM: BCM %d | Direction: BCM %d | Sensor: BCM %d\n",
           VALVE_PWM_PIN, VALVE_DIR_PIN, FLOW_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        double flow_rate = calculate_flow_rate();

        double error = g_target_flow - flow_rate;
        int    position = (int)(KP * error);

        if (set_valve_position(position) < 0) {
            fprintf(stderr, "Error: failed to set valve position\n");
            break;
        }

        log_data(flow_rate, position);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

