/*
 * Two-factor door access control for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - 2 x YLI YM-180 electromagnetic lock actuators
 *       Lock 1 -> GPIO 17 (BCM)
 *       Lock 2 -> GPIO 27 (BCM)
 *   - RFID reader on SPI channel 0, 100 kHz
 *   - Button on GPIO 22 (BCM, active-low with internal pull-up, 50 ms debounce)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_access door_access.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware-level GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define LOCK_1_PIN        17          /* BCM GPIO 17 */
#define LOCK_2_PIN        27          /* BCM GPIO 27 */
#define BUTTON_PIN        22          /* BCM GPIO 22 (active-low) */

#define SPI_CHANNEL       0           /* SPI channel 0 */
#define SPI_SPEED         100000      /* 100 kHz */
#define SPI_FLAGS         0           /* Mode 0, active-low CS */

#define LOG_FILE          "/var/log/door_access.log"

#define DEBOUNCE_US       50000       /* 50 ms debounce */
#define LOCK_HOLD_US      5000000     /* 5 s hold-time */
#define POLL_DELAY_US     100000      /* 100 ms poll interval */
#define MAX_RFID_RETRIES  4           /* API call() retries per attempt */

/* YM-180 actuator: HIGH = engaged (locked), LOW = disengaged (unlocked) */
#define LOCK_ENGAGED      1
#define LOCK_DISENGAGED   0

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes -------------------------- */

static void  signal_handler(int sig);
static int   initialize(void);
static void  cleanup(void);
static int   read_rfid_tag(uint8_t *tag, size_t len);
static int   verify_tag(const uint8_t *tag, size_t len);
static void  log_event(const char *event);
static void  disengage_locks(void);
static void  engage_locks(void);
static int   button_pressed(void);

/* ------------------------------- Handlers --------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ Initialization ----------------------------- */

static int initialize(void)
{
    /* --- pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* --- Lock GPIO pins --- */
    if (gpioSetMode(LOCK_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LOCK_1_PIN);
        return -1;
    }
    if (gpioSetMode(LOCK_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LOCK_2_PIN);
        return -1;
    }

    /* Engage both locks at startup (HIGH) */
    if (gpioWrite(LOCK_1_PIN, LOCK_ENGAGED) < 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LOCK_1_PIN);
        return -1;
    }
    if (gpioWrite(LOCK_2_PIN, LOCK_ENGAGED) < 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LOCK_2_PIN);
        return -1;
    }

    /* --- Button GPIO pin --- */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", BUTTON_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", BUTTON_PIN);
        return -1;
    }

    /* --- SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", g_spi_handle);
        return -1;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: failed to open log file");
        return -1;
    }

    return 0;
}

/* -------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    /* Engage both locks (HIGH) to ensure safety on exit */
    if (g_spi_handle >= 0) {
        gpioWrite(LOCK_1_PIN, LOCK_ENGAGED);
        gpioWrite(LOCK_2_PIN, LOCK_ENGAGED);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------ RFID reader -------------------------------- */

/*
 * Reads a 10-byte tag from the RFID reader via SPI.
 * Returns 0 on success, -1 on SPI error, -2 on all-zero response (no tag).
 */
static int read_rfid_tag(uint8_t *tag, size_t len)
{
    if (tag == NULL || len < 10) {
        return -1;
    }

    uint8_t tx[10] = {0};
    uint8_t rx[10] = {0};

    /*
     * YM-180 readers typically expect a command byte (0x01) followed by
     * a read-request byte (0x01), then a 4-byte CRC, then a 1-byte
     * status byte, then a 4-byte tag ID, then a 1-byte checksum.
     * We send a 10-byte frame of 0x00s and read back the response.
     */
    tx[0] = 0x01;                       /* command byte */
    tx[1] = 0x01;                       /* read request */

    for (int attempt = 0; attempt < MAX_RFID_RETRIES; attempt++) {
        int rc = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 10);
        if (rc == 10) {
            /*
             * YM-180 responses typically start with a status byte
             * (0x00 = success) followed by the tag data.
             * A full 10-byte response is expected; we copy the last 8
             * bytes into the caller's buffer.
             */
            memcpy(tag, rx + 2, 8);
            return 0;
        }
        gpioDelay(1000);                /* 1 ms back-off */
    }

    /* All retries exhausted */
    return -1;
}

/*
 * Verifies a 10-byte tag against a known valid value.
 * Returns 1 if the tag is valid, 0 otherwise.
 */
static int verify_tag(const uint8_t *tag, size_t len)
{
    if (tag == NULL || len < 10) {
        return 0;
    }

    /*
     * Replace this with the actual valid tag value
     * (e.g., a 10-byte binary string).
     */
    static const uint8_t valid_tag[10] = {
        0x01, 0x23, 0x45, 0x67, 0x89,
        0xAB, 0xCD, 0xEF, 0x01, 0x23
    };

    return (memcmp(tag, valid_tag, 10) == 0) ? 1 : 0;
}

/* -------------------------------- Logging ---------------------------------- */

static void log_event(const char *event)
{
    if (g_log_file == NULL) {
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(g_log_file, "%s: %s\n", timestamp, event);
    fflush(g_log_file);
}

/* ----------------------------- Lock control -------------------------------- */

static void disengage_locks(void)
{
    log_event("Disengaging locks...");
    if (gpioWrite(LOCK_1_PIN, LOCK_DISENGAGED) < 0) {
        log_event("Error: failed to disengage lock 1.");
    }
    if (gpioWrite(LOCK_2_PIN, LOCK_DISENGAGED) < 0) {
        log_event("Error: failed to disengage lock 2.");
    }
    log_event("Locks disengaged.");
}

static void engage_locks(void)
{
    log_event("Engaging locks...");
    if (gpioWrite(LOCK_1_PIN, LOCK_ENGAGED) < 0) {
        log_event("Error: failed to engage lock 1.");
    }
    if (gpioWrite(LOCK_2_PIN, LOCK_ENGAGED) < 0) {
        log_event("Error: failed to engage lock 2.");
    }
    log_event("Locks engaged.");
}

/* ------------------------------ Button input -------------------------------- */

static int button_pressed(void)
{
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();

    if (gpioRead(BUTTON_PIN) == 0) {                 /* active-low */
        if (last_tick == 0) {
            last_tick = now;
        } else if ((now - last_tick) > DEBOUNCE_US) {
            last_tick = now;
            return 1;                                 /* confirmed press */
        }
    } else {
        last_tick = 0;                                /* reset on release */
    }
    return 0;
}

/* --------------------------------- Main ------------------------------------ */

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize hardware */
    if (initialize() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Door access control system started.");

    /* Main polling loop */
    while (g_running) {
        uint8_t tag[10] = {0};
        int rc = read_rfid_tag(tag, sizeof(tag));

        if (rc == 0) {
            /* Valid tag read */
            if (verify_tag(tag, sizeof(tag))) {
                log_event("Valid tag detected.");

                if (button_pressed()) {
