                    gpioDelay(LOCK_HOLD_US);
                    engage_locks();
                    log_event("Door unlocked.");
                } else {
                    log_event("Button not pressed.");
                }
            } else {
                /* All-zero tag is not an error; just log */
                log_event("Invalid tag detected.");
            }
        } else if (rc == -2) {
            /* No tag present (all-zero response) */
            log_event("No tag present.");
        } else {
