#define ENCODER2_B 19

#define PWM_FREQ_HZ 100
#define PWM_PERIOD_NS (1000000000L / PWM_FREQ_HZ)
#define PWM_RANGE 100
#define PWM_STEP_NS (PWM_PERIOD_NS / PWM_RANGE)

#define TARGET_SPEED_RPM 60.0
#define PID_KP 1.0
#define PID_KI 0.01
#define PID_KD 0.1
#define PID_DT_S 0.1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor1_ena = NULL, *motor1_in1 = NULL, *motor1_in2 = NULL;
static struct gpiod_line *motor2_enb = NULL, *motor2_in3 = NULL, *motor2_in4 = NULL;
static struct gpiod_line *enc1_a = NULL, *enc1_b = NULL;
static struct gpiod_line *enc2_a = NULL, *enc2_b = NULL;

static pthread_mutex_t enc1_mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t enc2_mtx = PTHREAD_MUTEX_INITIALIZER;
static volatile int32_t enc1_count = 0;
static volatile int32_t enc2_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_motor_speed(struct gpiod_line *ena, struct gpiod_line *in1,
                            struct gpiod_line *in2, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (duty == 0) {
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 0);
        gpiod_line_set_value(ena, 0);
        return;
    }
    if (duty == PWM_RANGE) {
        gpiod_line_set_value(in1, 1);
        gpiod_line_set_value(in2, 0);
        gpiod_line_set_value(ena, 1);
        return;
    }
    gpiod_line_set_value(in1, 1);
    gpiod_line_set_value(in2, 0);
    gpiod_line_set_value(ena, 1);
    usleep(duty * (PWM_PERIOD_NS / 1000000));
    gpiod_line_set_value(in1, 0);
    gpiod_line_set_value(in2, 0);
    gpiod_line_set_value(ena, 0);
}

static void *encoder1_thread(void *arg) {
    (void)arg;
    while (running) {
        int a = gpiod_line_get_value(enc1_a);
        int b = gpiod_line_get_value(enc1_b);
        if (a < 0 || b < 0) {
            fprintf(stderr, "Encoder1 read error: %s\n", strerror(errno));
            usleep(10000);
            continue;
        }
        pthread_mutex_lock(&enc1_mtx);
        if (a == 1 && b == 0) enc1_count++;
        else if (a == 0 && b == 1) enc1_count--;
        pthread_mutex_unlock(&enc1_mtx);
        usleep(10000);
    }
    return NULL;
}

static void *encoder2_thread(void *arg) {
    (void)arg;
    while (running) {
        int a = gpiod_line_get_value(enc2_a);
        int b = gpiod_line_get_value(enc2_b);
        if (a < 0 || b < 0) {
            fprintf(stderr, "Encoder2 read error: %s\n", strerror(errno));
            usleep(10000);
            continue;
        }
        pthread_mutex_lock(&enc2_mtx);
        if (a == 1 && b == 0) enc2_count++;
        else if (a == 0 && b == 1) enc2_count--;
        pthread_mutex_unlock(&enc2_mtx);
        usleep(10000);
    }
    return NULL;
}

static double calculate_pid(double setpoint, double actual,
                            double *integral, double *prev_error) {
    double error = setpoint - actual;
    *integral += error * PID_DT_S;
    double derivative = (error - *prev_error) / PID_DT_S;
    double output = PID_KP * error + PID_KI * (*integral) + PID_KD * derivative;
    *prev_error = error;
    return output;
}

static void log_data(double m1_rpm, double m2_rpm,
                     double p, double i, double d, double pid_out) {
    if (!log_file) return;
    time_t t = time(NULL);
