    if (enc1_a) gpiod_line_release(enc1_a);
    if (enc1_b) gpiod_line_release(enc1_b);
    if (enc2_a) gpiod_line_release(enc2_a);
    if (enc2_b) gpiod_line_release(enc2_b);
