#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(rc));
        return -1;
    }
    return rc;
}

static int mpr121_init(int handle) {
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(handle, 0x2B, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2C, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2D, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2E, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2F, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x30, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x31, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x32, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x33, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x34, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x35, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x36, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x37, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x38, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x39, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x3A, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x3B, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x3C, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x3D, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x3E, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x3F, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x40, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x41, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x42, 0x00) < 0) return -1;
