    if (mpr121_write_reg(handle, 0x46, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x47, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x48, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x49, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x4A, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x4B, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x4C, 0x00) < 0) return -1;
