    if (mpr121_write_reg(handle, 0x50, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x51, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x52, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x53, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x54, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x55, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x56, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x57, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x58, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x59, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x5A, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x5B, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x5C, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x5D, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, 0x41 + (i * 2), 0x0F) < 0) return -1;
        if (mpr121_write_reg(handle, 0x42 + (i * 2), 0x0A) < 0) return -1;
    }

    if (mpr121_write_reg(handle, MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    int lo = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) return -1;
    int hi = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_relay_state(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Relay: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            relay_state ? "ON" : "OFF");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
