/*
 * Water-valve timed schedule for Raspberry Pi 4 Model B.
 *
 * Two Adafruit Solenoid Valves (Product ID 997) are driven through
 * relay modules on the GPIO bus.  Valve 1 -> GPIO17 (BCM),
 * Valve 2 -> GPIO18 (BCM).
 *
 * Schedule:
 *   1. Valve 1 ON for 500 ms, log event, pause 5 s.
 *   2. Valve 2 ON for 1000 ms, log event, pause 10 s.
 *   3. Repeat.
 *
 * Build:  gcc -O2 -Wall -Wextra -o valve_schedule valve_schedule.c -lpigpio -lrt
 * Run:    sudo ./valve_schedule
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE1_GPIO      17
#define VALVE2_GPIO      18

#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000

#define VALVE1_PAUSE_S   5
#define VALVE2_PAUSE_S   10

#define LOG_FILE         "valve_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Write an ISO-8601 timestamped event line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(FILE *fp, int valve_number, int duration_ms)
{
    time_t     now;
    struct tm  tm_buf;
    char       ts[32];

    time(&now);
    if (localtime_r(&now, &tm_buf) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(fp, "%s Valve %d ON for %d ms\n", ts, valve_number, duration_ms) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/*
 * Activate a valve for duration_ms, then deactivate.
 * Returns 0 on success, -1 on GPIO write failure.
 */
static int activate_valve(int gpio, int duration_ms)
{
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "gpioWrite(ON) failed on GPIO %d\n", gpio);
        return -1;
    }

    gpioDelay(duration_ms * 1000);   /* microseconds */

    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "gpioWrite(OFF) failed on GPIO %d\n", gpio);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc = EXIT_SUCCESS;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure valve GPIOs as outputs, initial LOW (valves closed) ---- */
    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", VALVE1_GPIO);
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", VALVE2_GPIO);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioWrite(VALVE1_GPIO, 0) != 0 || gpioWrite(VALVE2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise valve GPIOs to LOW\n");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Valve schedule started.  Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        /* Valve 1 */
        if (activate_valve(VALVE1_GPIO, VALVE1_DURATION_MS) != 0) {
            rc = EXIT_FAILURE;
            break;
        }
        if (log_event(g_log_fp, 1, VALVE1_DURATION_MS) != 0) {
            rc = EXIT_FAILURE;
            break;
        }

        /* Pause between valves */
        for (int i = 0; i < VALVE1_PAUSE_S && g_running; i++) {
            sleep(1);
        }
        if (!g_running) break;

        /* Valve 2 */
        if (activate_valve(VALVE2_GPIO, VALVE2_DURATION_MS) != 0) {
            rc = EXIT_FAILURE;
            break;
        }
        if (log_event(g_log_fp, 2, VALVE2_DURATION_MS) != 0) {
            rc = EXIT_FAILURE;
            break;
        }

        /* Pause between schedules */
        for (int i = 0; i < VALVE2_PAUSE_S && g_running; i++) {
            sleep(1);
        }
    }

cleanup:
    /* ---- release GPIOs ---- */
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);
    gpioSetMode(VALVE1_GPIO, PI_INPUT);
    gpioSetMode(VALVE2_GPIO, PI_INPUT);

    /* ---- close log file ---- */
    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            perror("fclose");
            rc = EXIT_FAILURE;
        }
        g_log_fp = NULL;
    }

    /* ---- terminate pigpio ---- */
    gpioTerminate();

    printf("Valve schedule stopped.\n");
    return rc;
}

