/*
 * MPR121 Capacitive Touch Sensor - Relay Toggle on Touch
 * Board:  Raspberry Pi Zero W
 * I2C:    Bus 1 (SDA=GPIO2, SCL=GPIO3), MPR121 address 0x5C
 * Relay:  GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPR121 I2C ---- */
#define I2C_BUS        1
#define MPR121_ADDR    0x5C

/* ---- GPIO ---- */
#define RELAY_GPIO     17

/* ---- MPR121 registers ---- */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPR121 register; returns 0 on success, -1 on error. */
static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at reg; returns 0 on success, -1 on error. */
static int mpr121_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPR121 in stop mode, configure electrodes, then run. */
static int mpr121_init(int handle)
{
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* Put device in stop mode (ELE_CONFIG = 0) */
    if (mpr121_write_reg(handle, MPR121_ELECONFIG, 0x00) < 0)
        return -1;

    /*
     * AFE Configuration (0x5C-0x5B).
     * Default values from the MPR121 datasheet are safe.
     */
    if (mpr121_write_reg(handle, 0x5C, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, 0x5B, 0x01) < 0) return -1;

    /*
     * Touch / Release thresholds for all 12 electrodes.
     * Touch threshold = 12, Release threshold = 6 (typical defaults).
     */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, 0x41 + 2 * i, 12) < 0) return -1; /* touch  */
        if (mpr121_write_reg(handle, 0x42 + 2 * i, 6)  < 0) return -1; /* release */
    }

    /*
     * Filter / charge / discharge configuration (0x2B-0x34).
     * Default values from the MPR121 datasheet are safe.
     */
    if (mpr121_write_reg(handle, 0x2B, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2C, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2D, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2E, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x2F, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x30, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x31, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x32, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x33, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, 0x34, 0x00) < 0) return -1;

    /*
     * Electrode configuration: enable all 12 electrodes, baseline tracking.
     * ELE_CONFIG = 0x0C (CL=10, ELEPROX=0, ELE=12).
     */
    if (mpr121_write_reg(handle, MPR121_ELECONFIG, 0x0C) < 0)
        return -1;

    /* Allow electrodes to settle after entering run mode */
    gpioDelay(100000); /* 100 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Relay GPIO setup ---- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0); /* relay OFF at startup */

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- MPR121 init ---- */
    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] MPR121 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 ready. Monitoring touch (Ctrl+C to exit)...\n");

    /* ---- Main loop ---- */
    bool relay_state = false;

    while (g_running) {
        uint8_t buf[2];
        if (mpr121_read_block(g_i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) < 0) {
            fprintf(stderr, "[WARN] Touch status read failed; retrying...\n");
            gpioDelay(100000);
            continue;
        }

        uint16_t touch_status = (uint16_t)((buf[1] << 8) | buf[0]);

        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state ? 1 : 0) < 0) {
                fprintf(stderr, "[WARN] gpioWrite(%d) failed\n", RELAY_GPIO);
            }
            printf("Touch detected! Relay %s\n", relay_state ? "ON" : "OFF");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

