 * Append a timestamped event line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(const char *event)
{
    if (g_log == NULL)
        return -1;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&ts.tv_sec, &tm_buf);
    if (tm_info == NULL) {
        perror("localtime_r");
        return -1;
    }

    char timestamp[40];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    long ms = ts.tv_nsec / 1000000L;
    if (fprintf(g_log, "%s.%03ld: %s\n", timestamp, ms, event) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(g_log) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Is the pigpio daemon running? Stop it first.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Pull-down on PIR pin so the input is defined when the sensor
     * is disconnected or idle. */
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n", PIR_PIN);
    }

    /* Ensure relay starts in the OFF state. */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO %d.\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door strike controller started.\n");
    printf("  PIR sensor : GPIO %d\n", PIR_PIN);
    printf("  Relay      : GPIO %d\n", RELAY_PIN);
    printf("  Log file   : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int last_pir = gpioRead(PIR_PIN);
    if (last_pir < 0) {
        fprintf(stderr, "Error: initial read of GPIO %d failed.\n", PIR_PIN);
        fclose(g_log);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO %d.\n", PIR_PIN);
            sleep_ms_interruptible(POLL_MS);
            continue;
        }

        /* Rising edge: 0 -> 1 */
        if (pir == 1 && last_pir == 0) {
            printf("Motion detected!\n");

            if (log_event("Motion detected") != 0)
                fprintf(stderr, "Warning: failed to log motion event.\n");

            /* Activate relay for UNLOCK_MS */
            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to energize relay.\n");
            } else {
                sleep_ms_interruptible(UNLOCK_MS);
                if (gpioWrite(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to de-energize relay.\n");
                }
            }

            if (log_event("Door unlocked") != 0)
                fprintf(stderr, "Warning: failed to log unlock event.\n");

            /* Cooldown to prevent rapid re-triggering */
            sleep_ms_interruptible(COOLDOWN_MS);
        }

        last_pir = pir;
        sleep_ms_interruptible(POLL_MS);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");

    /* Ensure relay is off */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during shutdown.\n");
    }

    if (log_event("Shutdown initiated") != 0)
        fprintf(stderr, "Warning: failed to log shutdown event.\n");

    if (g_log != NULL) {
        if (fclose(g_log) != 0)
            perror("Warning: fclose failed");
        g_log = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

