#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15

typedef struct {
    int duty_cycle;
    int duration_ms;
} MotorStep;

typedef struct {
    MotorStep *steps;
    int length;
} MotorPattern;

static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int signal) {
    (void)signal;
    shutdown_requested = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

static void cleanup_gpio(void) {
    stop_motors();
    gpioTerminate();
}

static MotorPattern *generate_random_pattern(void) {
    int pattern_length = (rand() % (MAX_PATTERN_LENGTH - MIN_PATTERN_LENGTH + 1)) + MIN_PATTERN_LENGTH;
    MotorPattern *pattern = (MotorPattern *)malloc(sizeof(MotorPattern));
    if (pattern == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for pattern.\n");
        return NULL;
    }

    pattern->steps = (MotorStep *)malloc(pattern_length * sizeof(MotorStep));
    if (pattern->steps == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for pattern steps.\n");
        free(pattern);
        return NULL;
    }

    pattern->length = pattern_length;

    for (int i = 0; i < pattern_length; i++) {
        pattern->steps[i].duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        pattern->steps[i].duration_ms = (rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1)) + MIN_STEP_DURATION_MS;
    }

    return pattern;
}

static void play_pattern(const MotorPattern *pattern) {
    if (pattern == NULL || pattern->steps == NULL) {
        fprintf(stderr, "Error: Invalid pattern passed to play_pattern.\n");
        return;
    }

    for (int i = 0; i < pattern->length && !shutdown_requested; i++) {
        if (gpioPWM(MOTOR1_PIN, pattern->steps[i].duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", MOTOR1_PIN);
        }
        if (gpioPWM(MOTOR2_PIN, pattern->steps[i].duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM on GPIO %d.\n", MOTOR2_PIN);
        }
        gpioDelay(pattern->steps[i].duration_ms * 1000);
    }
}

int main(void) {
    srand(time(NULL));

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (!shutdown_requested) {
        MotorPattern *pattern = generate_random_pattern();
        if (pattern != NULL) {
            play_pattern(pattern);
            free(pattern->steps);
            free(pattern);
        }
    }

    cleanup_gpio();
    printf("Haptic feedback system stopped.\n");

    return EXIT_SUCCESS;
}

