/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* HX711 helpers                                                       */
/* ------------------------------------------------------------------ */
static int hx711_read(int data_pin, int clock_pin, long *raw_out)
{
    if (gpioSetMode(data_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set data pin %d as input\n", data_pin);
        return -1;
    }
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set clock pin %d as output\n", clock_pin);
        return -1;
    }

    /* Wait for data line to go low (data ready), with timeout */
    uint32_t start = gpioTick();
    while (gpioRead(data_pin) == 1) {
        if ((gpioTick() - start) > READ_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data-ready timeout on pin %d\n", data_pin);
            return -1;
        }
        gpioDelay(100);
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(clock_pin, 1) < 0) {
            fprintf(stderr, "Error: failed to set clock high\n");
            return -1;
        }
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(data_pin) == 1) {
            value |= 1;
        }
        if (gpioWrite(clock_pin, 0) < 0) {
            fprintf(stderr, "Error: failed to set clock low\n");
            return -1;
        }
        gpioDelay(1);
    }

    /* 25th pulse for gain 128 */
    if (gpioWrite(clock_pin, 1) < 0) {
        fprintf(stderr, "Error: failed to set clock high (25th pulse)\n");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(clock_pin, 0) < 0) {
        fprintf(stderr, "Error: failed to set clock low (25th pulse)\n");
        return -1;
    }
    gpioDelay(1);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (value & 0x800000) {
        value |= 0xFF000000L;
    }

    *raw_out = value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                         */
/* ------------------------------------------------------------------ */
static int load_calibration(const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s for reading; using defaults\n", filename);
        return -1;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: malformed calibration file; using defaults\n");
        fclose(fp);
        scale_factor = DEFAULT_SCALE_FACTOR;
        offset       = DEFAULT_OFFSET;
        return -1;
    }

    fclose(fp);
    printf("Calibration loaded: scale_factor=%.6f, offset=%.6f\n", scale_factor, offset);
    return 0;
}

static int save_calibration(const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for writing\n", filename);
        return -1;
    }
    fprintf(fp, "%.6f %.6f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration saved: scale_factor=%.6f, offset=%.6f\n", scale_factor, offset);
    return 0;
}

static int calibrate_offset(int data_pin, int clock_pin)
{
    printf("Calibrating offset... Place the load cell in zero-load condition.\n");
    printf("Waiting 5 seconds for readings to stabilize...\n");
    gpioDelay(5000000);

    long sum = 0;
    int valid = 0;
    for (int i = 0; i < NUM_CALIBRATION_READS; i++) {
        long raw;
        if (hx711_read(data_pin, clock_pin, &raw) == 0) {
            sum += raw;
            valid++;
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        fprintf(stderr, "Error: no valid HX711 readings during calibration\n");
        return -1;
    }

    offset = (double)sum / valid;
    printf("Calibration complete. Offset: %.6f\n", offset);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Weight computation                                                  */
/* ------------------------------------------------------------------ */
static double calculate_weight(long raw_value)
{
    return ((double)raw_value - offset) / scale_factor;
}

/* ------------------------------------------------------------------ */
/* Solenoid control                                                    */
/* ------------------------------------------------------------------ */
static int control_solenoid(int solenoid_pin, double weight)
{
    if (gpioSetMode(solenoid_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set solenoid pin %d as output\n", solenoid_pin);
        return -1;
    }

    if (weight > WEIGHT_THRESHOLD) {
        if (gpioWrite(solenoid_pin, 1) < 0) {
            fprintf(stderr, "Error: failed to engage solenoid\n");
            return -1;
        }
        printf("Weight %.2f kg exceeds threshold; solenoid engaged\n", weight);
    } else {
        if (gpioWrite(solenoid_pin, 0) < 0) {
            fprintf(stderr, "Error: failed to disengage solenoid\n");
            return -1;
        }
        printf("Weight %.2f kg below threshold; solenoid disengaged\n", weight);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_weight(double weight)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disengage solenoid and release GPIO resources */
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    load_calibration(CALIBRATION_FILE);

    if (calibrate_offset(HX711_DATA_PIN, HX711_CLOCK_PIN) < 0) {
        fprintf(stderr, "Warning: calibration failed; using default offset\n");
    }

    save_calibration(CALIBRATION_FILE);

    printf("Starting weight monitoring loop. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value;
        if (hx711_read(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) == 0) {
            double weight = calculate_weight(raw_value);
            printf("Raw: %ld, Weight: %.2f kg\n", raw_value, weight);

            if (control_solenoid(SOLENOID_PIN, weight) < 0) {
                fprintf(stderr, "Warning: solenoid control failed\n");
            }

            if (log_weight(weight) < 0) {
                fprintf(stderr, "Warning: logging failed\n");
            }
        } else {
            fprintf(stderr, "Warning: HX711 read failed; skipping iteration\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

