/*
 * window_control.c — Raspberry Pi 4 Model B
 *
 * Monitors a Seeed Studio Grove Rain Sensor on GPIO4 (BCM) and drives an
 * L298N-controlled DC motor to close a window when rain is detected.
 *
 * Build:  gcc -O2 -Wall -Wextra -o window_control window_control.c -lpigpio -lrt
 * Run:    sudo ./window_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RAIN_SENSOR_PIN  4
#define MOTOR_IN1_PIN    17
#define MOTOR_IN2_PIN    18
#define MOTOR_PWM_PIN    27

/* ---- Motor PWM parameters ---- */
#define PWM_FREQUENCY    1000   /* Hz  */
#define PWM_DUTY_CYCLE   150    /* 0-255 */

/* ---- Timing constants (seconds) ---- */
#define RAIN_CHECK_INTERVAL  60   /* seconds between sensor reads   */
#define MOTOR_RUN_DURATION   5    /* seconds the motor is closed for */
#define POST_CLOSE_DELAY     60   /* seconds after closing before next check */

/* ---- Debounce parameters ---- */
#define DEBOUNCE_READINGS    5
#define DEBOUNCE_DELAY_US    50000  /* 50 ms between readings */

/* ---- Logging ---- */
#define LOG_FILE "/var/log/window_control.log"

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t != NULL)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    syslog(LOG_INFO, "%s: %s", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static int motor_stop(void)
{
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        log_event("ERROR: gpioWrite IN1 failed during stop");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_event("ERROR: gpioWrite IN2 failed during stop");
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        log_event("ERROR: gpioPWM stop failed");
        return -1;
    }
    log_event("Motor stopped");
    return 0;
}

static int motor_close(void)
{
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        log_event("ERROR: gpioWrite IN1 (forward) failed");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_event("ERROR: gpioWrite IN2 (off) failed");
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) < 0) {
        log_event("ERROR: gpioPWM start failed");
        return -1;
    }
    log_event("Motor closing window");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Rain sensor (debounced)                                             */
/* ------------------------------------------------------------------ */
/*
 * Returns 1 if rain is detected (at least three consecutive LOW readings),
 * 0 if dry, -1 on read error.
 */
static int rain_detected(void)
{
    int low_count = 0;

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int v = gpioRead(RAIN_SENSOR_PIN);
        if (v < 0) {
            log_event("ERROR: gpioRead on rain sensor failed");
            return -1;
        }
        if (v == 0)
            low_count++;
        if (i < DEBOUNCE_READINGS - 1)
            gpioDelay(DEBOUNCE_DELAY_US);
    }

    return (low_count >= 3) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* GPIO initialization                                                 */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set rain sensor pin mode\n");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        return -1;
    }

    /* Start with motor off */
    if (motor_stop() < 0) {
        fprintf(stderr, "Failed to initialise motor state\n");
        return -1;
    }

    /* PWM frequency */
    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        log_event("ERROR: GPIO initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Window control system started");

    while (g_running) {
        int rain = rain_detected();

        if (rain < 0) {
            log_event("ERROR: Sensor read failure — skipping cycle");
        } else if (rain) {
            log_event("Rain detected");

            if (motor_close() == 0) {
                /*
                 * Run the motor for MOTOR_RUN_DURATION seconds, checking
                 * g_running every second so SIGINT/SIGTERM is responsive.
                 */
                for (int s = 0; s < MOTOR_RUN_DURATION && g_running; s++)
                    sleep(1);

                motor_stop();
            }

            /* Wait before next check (after closing) */
            for (int s = 0; s < POST_CLOSE_DELAY && g_running; s++)
                sleep(1);
        }

        /* Wait before next rain check */
        for (int s = 0; s < RAIN_CHECK_INTERVAL && g_running; s++)
            sleep(1);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

