/*
 * Raspberry Pi 4 Model B – HX711 Load Cell Monitor
 *
 * Hardware:
 *   - TAL220B load cell + HX711 (4.5–220 g range)
 *   - HX711 data  -> GPIO23 (BCM)
 *   - HX711 clock -> GPIO24 (BCM)
 *   - Solenoid    -> GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o stock_monitor stock_monitor.c
 *
 * Run:
 *   ./stock_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define HX711_DT_PIN      23          /* BCM 23 – data line  */
#define HX711_SCK_PIN     24          /* BCM 24 – clock line */
#define SOLENOID_PIN      17          /* BCM 17 – solenoid   */

#define WEIGHT_THRESHOLD  100.0f      /* grams */
#define LOCK_DURATION_S   5           /* seconds */
#define SAMPLE_PERIOD_S   1           /* seconds between readings */
#define HX711_TIMEOUT_US  1000000     /* 1 s timeout waiting for data-ready */
#define HX711_SETTLE_US   1000        /* 1 ms after clocking a channel */
#define HX711_CHANNEL     1           /* 1 = AIN0, 0 = AIN1 */

#define LOG_FILE          "stock_events.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log      = NULL;

/* --------------------------- Forward Declarations ------------------------ */

static void  signal_handler(int sig);
static void  log_event(const char *msg);
static int   init_gpio(void);
static void  cleanup_gpio(void);
static int   read_hx711(int32_t *raw);
static float raw_to_grams(int32_t raw);
static void  activate_lock(void);
static void  deactivate_lock(void);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Logging --------------------------------- */

static void log_event(const char *msg)
{
    if (!g_log)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log, "[%s] %s\n", ts, msg);
    fflush(g_log);
}

/* ------------------------------- GPIO Init ------------------------------- */

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DT pin mode\n");
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCK pin mode\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        return -1;
    }

    /* Ensure clock starts low and solenoid is off */
    gpioWrite(HX711_SCK_PIN, 0);
    deactivate_lock();

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort cleanup */
    gpioWrite(SOLENOID_PIN, 0);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioTerminate();
}

/* ------------------------------ HX711 Read ------------------------------- */

/*
 * Read 24 bits from the HX711, then pulse the SCK pin for the channel-ready
 * bit (channel select).  Returns 0 on success, -1 on timeout or GPIO error.
 */
static int read_hx711(int32_t *raw)
{
    if (!raw)
        return -1;

    /* Wait for data-ready (DT goes low) */
    uint32_t elapsed = 0;
    while (gpioRead(HX711_DT_PIN) == 1) {
        gpioDelay(100);                 /* 100 µs */
        elapsed += 100;
        if (elapsed >= HX711_TIMEOUT_US) {
            log_event("HX711 timeout: data line stuck high (sensor absent?)");
            return -1;
        }
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            log_event("HX711 clock write high failed");
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);

        value <<= 1;
        int bit = gpioRead(HX711_DT_PIN);
        if (bit < 0) {
            log_event("HX711 data read failed");
            return -1;
        }
        if (bit)
            value |= 1;

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            log_event("HX711 clock write low failed");
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);
    }

    /* 25th pulse: select channel 1 (gain 128) */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        log_event("HX711 channel-ready pulse high failed");
        return -1;
    }
    gpioDelay(HX711_SETTLE_US);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        log_event("HX711 channel-ready pulse low failed");
        return -1;
    }
    gpioDelay(HX711_SETTLE_US);

    /* Sign-extend 24-bit two's complement to 32-bit */
    if (value & 0x800000)
        value |= 0xFF000000;

    *raw = (int32_t)value;
    return 0;
}

/*
 * Convert raw ADC count to grams.
 *
 * NOTE: The TAL220B load cell requires a custom calibration factor.
 *       This value is a placeholder; replace with your calibrated value.
 */
static float raw_to_grams(int32_t raw)
{
    const float CALIBRATION_FACTOR = 42.0f;   /* Replace with your value */
    return (float)raw / CALIBRATION_FACTOR;
}

/* ----------------------------- Solenoid Lock ----------------------------- */

static void activate_lock(void)
{
    if (gpioWrite(SOLENOID_PIN, 1) < 0)
        log_event("Failed to activate solenoid lock");
    else
        log_event("Solenoid lock activated");
}

static void deactivate_lock(void)
{
    if (gpioWrite(SOLENOID_PIN, 0) < 0)
        log_event("Failed to deactivate solenoid lock");
    else
        log_event("Solenoid lock deactivated");
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(log)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialisation failed");
        fclose(g_log);
        return EXIT_FAILURE;
    }

    log_event("Stock monitoring started");

    while (g_running) {
        int32_t raw = 0;
        if (read_hx711(&raw) < 0) {
            log_event("HX711 read error");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float grams = raw_to_grams(raw);
        char msg[128];
        snprintf(msg, sizeof(msg), "Weight: %.2f g", grams);
        log_event(msg);

        if (grams < WEIGHT_THRESHOLD) {
            log_event("Weight below threshold – activating solenoid lock");
            activate_lock();

            /*
             * Sleep in 1-second increments so we can exit promptly on
             * signal.
             */
            for (int i = 0; i < LOCK_DURATION_S && g_running; i++)
                sleep(1);

            deactivate_lock();
            log_event("Solenoid lock deactivated");
        }

        if (g_running)
            sleep(SAMPLE_PERIOD_S);
    }

    log_event("Shutting down");
    cleanup_gpio();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    return EXIT_SUCCESS;
}

