 * Raspberry Pi 4 Model B – HX711 Load Cell Monitor
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO4  (BCM 4, physical pin 7)
 *   HX711 PD_SCK-> GPIO17 (BCM 17, physical pin 11)
 *   Solenoid    -> GPIO27 (BCM 27, physical pin 13)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hx711_monitor hx711_monitor.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware-level GPIO access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define HX711_DATA_PIN      4
#define HX711_SCK_PIN       17
#define SOLENOID_PIN        27

#define CALIBRATION_FILE    "calibration.txt"
#define LOG_FILE            "security.log"

#define WEIGHT_THRESHOLD_KG 5.0
#define SAMPLE_INTERVAL_US  100000   /* 100 ms between samples */
#define HX711_TIMEOUT_US    100000   /* 100 ms max wait for data-ready */
#define SCK_HIGH_US         1        /* HX711 requires >= 0.2 µs high */
#define SCK_LOW_US          1        /* HX711 requires >= 0.2 µs low  */
#define SOLENOID_PULSE_US   5000000  /* 5 s pulse to engage lock      */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static double g_calibration_factor = 1.0;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  initialize_gpio(void);
static int  read_hx711(int32_t *raw_out);
static double convert_to_kg(int32_t raw);
static int  calibrate(double known_weight_kg, double *factor_out);
static int  engage_solenoid(void);
static int  log_event(double weight_kg);
static int  read_calibration_factor(double *factor_out);
static int  save_calibration_factor(double factor);

/* ------------------------------- Handlers --------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- GPIO initialization -------------------------- */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set HX711 data pin mode.\n");
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set HX711 clock pin mode.\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set solenoid pin mode.\n");
        return -1;
    }

    /* Ensure clock starts low and solenoid is released (low = unlocked). */
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise HX711 clock low.\n");
        return -1;
    }
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise solenoid low.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------ HX711 read -------------------------------- */
/*
 * Reads 24 bits from the HX711, then performs a 25th clock pulse to set
 * the gain channel A / gain 128 for the next reading.
 *
 * Returns 0 on success and stores the signed 24-bit value in *raw_out.
 * Returns -1 on timeout (sensor not responding).
 */
static int read_hx711(int32_t *raw_out)
{
    if (raw_out == NULL) {
        return -1;
    }

    /* Wait for DOUT to go low (data ready). */
    uint32_t waited = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (waited >= HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout – sensor not ready.\n");
            return -1;
        }
        gpioDelay(100);  /* 100 µs granularity */
        waited += 100;
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            fprintf(stderr, "Error: SCK high write failed.\n");
            return -1;
        }
        gpioDelay(SCK_HIGH_US);

        data <<= 1;
        if (gpioRead(HX711_DATA_PIN) == 1) {
            data |= 1u;
        }

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            fprintf(stderr, "Error: SCK low write failed.\n");
            return -1;
        }
        gpioDelay(SCK_LOW_US);
    }

    /* 25th pulse: channel A / gain 128 for next reading. */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        fprintf(stderr, "Error: 25th SCK high write failed.\n");
        return -1;
    }
    gpioDelay(SCK_HIGH_US);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        fprintf(stderr, "Error: 25th SCK low write failed.\n");
        return -1;
    }
    gpioDelay(SCK_LOW_US);

    /* Convert 24-bit two's-complement to int32_t. */
    if (data & 0x800000u) {
        data |= 0xFF000000u;  /* sign-extend */
    }
    *raw_out = (int32_t)data;
    return 0;
}

/* ----------------------------- Conversion --------------------------------- */
static double convert_to_kg(int32_t raw)
{
    return (double)raw / g_calibration_factor;
}

/* ----------------------------- Calibration -------------------------------- */
static int calibrate(double known_weight_kg, double *factor_out)
{
    if (known_weight_kg <= 0.0) {
        fprintf(stderr, "Error: known weight must be positive.\n");
        return -1;
    }
    if (factor_out == NULL) {
        return -1;
    }

    int32_t raw;
    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "Error: calibration read failed.\n");
        return -1;
    }

    *factor_out = (double)raw / known_weight_kg;
    return 0;
}

/* --------------------------- Solenoid control ----------------------------- */
static int engage_solenoid(void)
{
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to engage solenoid (set high).\n");
        return -1;
    }
    gpioDelay(SOLENOID_PULSE_US);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to release solenoid (set low).\n");
        return -1;
    }
    return 0;
}

/* ------------------------------ Logging ----------------------------------- */
static int log_event(double weight_kg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.3f kg\n", timestamp, weight_kg) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

/* -------------------------- Calibration I/O ------------------------------- */
static int read_calibration_factor(double *factor_out)
{
    if (factor_out == NULL) {
        return -1;
    }

    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        perror("Error opening calibration file for reading");
        return -1;
    }

    if (fscanf(fp, "%lf", factor_out) != 1) {
        fprintf(stderr, "Error: failed to read calibration factor.\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing calibration file after read");
        return -1;
    }
    return 0;
}

static int save_calibration_factor(double factor)
{
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        perror("Error opening calibration file for writing");
        return -1;
    }

    if (fprintf(fp, "%.6f\n", factor) < 0) {
        perror("Error writing calibration factor");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing calibration file after write");
        return -1;
    }
    return 0;
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* ---- Calibration ---- */
    printf("Calibration\n");
    printf("Place a known weight on the load cell and enter its weight in kg: ");
    fflush(stdout);

    double known_weight_kg;
    if (scanf("%lf", &known_weight_kg) != 1 || known_weight_kg <= 0.0) {
        fprintf(stderr, "Invalid input. Exiting.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (calibrate(known_weight_kg, &g_calibration_factor) != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Calibration factor: %.6f\n", g_calibration_factor);
    if (save_calibration_factor(g_calibration_factor) != 0) {
        fprintf(stderr, "Warning: could not save calibration factor.\n");
    }

    /* ---- Main loop ---- */
    printf("Monitoring weight... (Ctrl+C to exit)\n");
    while (g_running) {
        int32_t raw;
        if (read_hx711(&raw) != 0) {
            /* Sensor timeout – skip this sample, keep running. */
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight_kg = convert_to_kg(raw);
        printf("Raw: %d, Weight: %.3f kg\n", raw, weight_kg);

        if (weight_kg > WEIGHT_THRESHOLD_KG) {
            printf("Threshold exceeded! Engaging solenoid...\n");
            if (engage_solenoid() != 0) {
                fprintf(stderr, "Solenoid pulse failed.\n");
            }
            if (log_event(weight_kg) != 0) {
                fprintf(stderr, "Logging failed.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

