/*
 * obstacle_relay.c — Raspberry Pi 3 Model B+
 *
 * Monitors a Keywish KY-022 IR obstacle avoidance sensor on GPIO16
 * (active-low) and toggles a Songle SRD-05VDC-SL relay on GPIO20
 * (active-high) when an obstacle is detected.  Logs each state
 * change with an ISO 8601 timestamp to relay_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_relay obstacle_relay.c
 *
 * Requires: libgpiod (libgpiod-dev)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN  16
#define RELAY_PIN   20
#define LOG_FILE    "relay_events.log"
#define POLL_MS     100

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm)) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    fprintf(fp, "%s %s\n", ts, msg);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "[ERROR] gpiod_chip_open_by_name: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        fprintf(stderr, "[ERROR] gpiod_chip_get_line(%d): %s\n",
                SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay) {
        fprintf(stderr, "[ERROR] gpiod_chip_get_line(%d): %s\n",
                RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor, "obstacle_relay") < 0) {
        fprintf(stderr, "[ERROR] request_input(sensor): %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay, "obstacle_relay", 0) < 0) {
        fprintf(stderr, "[ERROR] request_output(relay): %s\n",
                strerror(errno));
        gpiod_line_release(sensor);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-022 on GPIO%d, relay on GPIO%d.  Ctrl+C to exit.\n",
           SENSOR_PIN, RELAY_PIN);

    int relay_state = 0;
    int first = 1;

    while (g_running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            fprintf(stderr, "[ERROR] sensor read: %s\n", strerror(errno));
            log_event("ERROR: sensor read failed");
            usleep(POLL_MS * 1000);
            continue;
        }

        /* KY-022 is active-low: LOW (0) means obstacle detected. */
        if (val == 0) {
            relay_state = !relay_state;
            if (gpiod_line_set_value(relay, relay_state) < 0) {
                fprintf(stderr, "[ERROR] relay write: %s\n", strerror(errno));
                log_event("ERROR: relay write failed");
            } else {
                char msg[64];
                snprintf(msg, sizeof(msg),
                         "Relay toggled to %s",
                         relay_state ? "ON" : "OFF");
                log_event(msg);
                if (first) {
                    printf("[INIT] Relay %s\n", relay_state ? "ON" : "OFF");
                    first = 0;
                } else {
                    printf("[TOGGLE] Relay %s\n", relay_state ? "ON" : "OFF");
                }
            }
        }

        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay, 0);
    gpiod_line_release(sensor);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

