/*
 * Timed watering system for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Parker Hannifin Series 9 Solenoid Valve (12 V, 1.6 W)
 *   - N-channel MOSFET or relay module on GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM/GPIO access).
 *
 * Configuration:
 *   watering.conf  (single line: duration=<seconds>, 1..3600)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        18
#define CONFIG_FILE     "watering.conf"
#define MIN_DURATION    1
#define MAX_DURATION    3600
#define DEFAULT_DURATION 300

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;            /* no SA_RESTART so sleep() can wake on signal */

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                       */
/* ------------------------------------------------------------------ */
static int read_duration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (ferror(fp))
            fprintf(stderr, "Error reading config file: %s\n", strerror(errno));
        else
            fprintf(stderr, "Config file is empty (no duration line found)\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing newline / carriage return */
    line[strcspn(line, "\r\n")] = '\0';

    char *endptr = NULL;
    errno = 0;
    long val = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line) {
        fprintf(stderr, "Config file value is not a valid integer: '%s'\n", line);
        return -1;
    }
    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Duration %ld out of range [%d, %d]\n",
                val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(int pin)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", pin);
        gpioTerminate();
        return -1;
    }

    /* Active-low: 0 = valve OFF, 1 = valve ON */
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", pin);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void gpio_cleanup(int pin)
{
    /* Ensure valve is OFF before releasing the line */
    if (gpioWrite(pin, 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, 0) during cleanup failed\n", pin);
    gpioTerminate();
}

static int valve_on(int pin)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate valve (gpioWrite high)\n");
        return -1;
    }
    return 0;
}

static int valve_off(int pin)
{
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate valve (gpioWrite low)\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int duration = DEFAULT_DURATION;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (read_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Using default watering duration: %d seconds\n",
                DEFAULT_DURATION);
        duration = DEFAULT_DURATION;
    } else {
        printf("Watering duration read from config: %d seconds\n", duration);
    }

    if (gpio_init(GPIO_PIN) != 0)
        return EXIT_FAILURE;

    printf("Valve OFF — watering system started\n");

    if (valve_on(GPIO_PIN) != 0) {
        gpio_cleanup(GPIO_PIN);
        return EXIT_FAILURE;
    }
    printf("Valve ON  — watering for %d seconds\n", duration);

    /*
     * Sleep in 1-second increments so SIGINT/SIGTERM is noticed promptly.
     * sleep() is interrupted by signals and returns the remaining seconds;
     * if it returns 0 we know we were interrupted before the full duration.
     */
    for (int elapsed = 0; elapsed < duration && g_running; elapsed++)
        sleep(1);

    if (valve_off(GPIO_PIN) != 0) {
        gpio_cleanup(GPIO_PIN);
        return EXIT_FAILURE;
    }
    printf("Valve OFF — watering cycle complete\n");

    gpio_cleanup(GPIO_PIN);
    return EXIT_SUCCESS;
}

