#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27

#define LEFT_MOTOR_PIN     22
#define RIGHT_MOTOR_PIN    23
#define LEFT_PWM_PIN       24
#define RIGHT_PWM_PIN      25

/* ---- Physical constants ---- */
#define PWM_FREQUENCY      1000   /* Hz */
#define PWM_RANGE          255
#define BASE_SPEED         150
#define SAMPLE_PERIOD_US   10000  /* 10 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  initialize_gpio(void);
static void set_motor_speed(int left_speed, int right_speed);
static void log_data(int left, int middle, int right,
                     int left_speed, int right_speed);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure all pins                            */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* Sensor pins: input with pull-up (active-low sensors) */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set sensor pin modes.\n");
        return -1;
    }
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    /* Motor direction pins: output */
    if (gpioSetMode(LEFT_MOTOR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_MOTOR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor direction pin modes.\n");
        return -1;
    }

    /* PWM pins: output, set frequency and range */
    if (gpioSetMode(LEFT_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin modes.\n");
        return -1;
    }

    if (gpioSetPWMfrequency(LEFT_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        return -1;
    }

    if (gpioSetPWMrange(LEFT_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RIGHT_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        return -1;
    }

    /* Ensure motors are stopped at startup */
    set_motor_speed(0, 0);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Set motor speeds (0..255 each) and drive direction                  */
/* ------------------------------------------------------------------ */
static void set_motor_speed(int left_speed, int right_speed)
{
    /* Clamp to valid range */
    if (left_speed < 0)   left_speed = 0;
    if (left_speed > PWM_RANGE) left_speed = PWM_RANGE;
    if (right_speed < 0)  right_speed = 0;
    if (right_speed > PWM_RANGE) right_speed = PWM_RANGE;

    /* Left motor: forward if speed > 0, otherwise stop */
    if (left_speed > 0) {
        gpioWrite(LEFT_MOTOR_PIN, 1);
        gpioPWM(LEFT_PWM_PIN, left_speed);
    } else {
        gpioWrite(LEFT_MOTOR_PIN, 0);
        gpioPWM(LEFT_PWM_PIN, 0);
    }

    /* Right motor: forward if speed > 0, otherwise stop */
    if (right_speed > 0) {
        gpioWrite(RIGHT_MOTOR_PIN, 1);
        gpioPWM(RIGHT_PWM_PIN, right_speed);
    } else {
        gpioWrite(RIGHT_MOTOR_PIN, 0);
        gpioPWM(RIGHT_PWM_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Log one data row                                                    */
/* ------------------------------------------------------------------ */
static void log_data(int left, int middle, int right,
                     int left_speed, int right_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(g_log_file,
                "%s, Left: %d, Middle: %d, Right: %d, "
                "LeftSpeed: %d, RightSpeed: %d\n",
                timestamp, left, middle, right,
                left_speed, right_speed) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n",
                strerror(errno));
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup: stop motors, close log, terminate pigpio                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    set_motor_speed(0, 0);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open trace_log.txt: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        /* Active-low sensors: 0 = object detected */
        int left_detected   = (left   == 0);
        int middle_detected = (middle == 0);
        int right_detected  = (right  == 0);

        int left_speed  = 0;
        int right_speed = 0;

        if (middle_detected) {
            /* Straight ahead */
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_detected && !right_detected) {
            /* Turn right: reduce left motor speed */
            left_speed  = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (!left_detected && right_detected) {
            /* Turn left: reduce right motor speed */
            left_speed  = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            /* No sensor detected: stop */
            left_speed  = 0;
            right_speed = 0;
        }

