#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define POLL_INTERVAL_MS 100
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int read_lux(int handle, int *lux_out) {
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        return -1;
    }
    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_event("Program started");

    while (running) {
        if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) != 0) {
            log_event("I2C write error");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000);

        int lux = -1;
        if (read_lux(i2c_handle, &lux) != 0) {
            log_event("Lux read error");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Lux: %d", lux);
        log_event(msg);

        int target = (lux < LUX_THRESHOLD) ? 1 : 0;
        int cur = gpioRead(RELAY_GPIO);
        if (cur != target) {
            gpioWrite(RELAY_GPIO, target);
            snprintf(msg, sizeof(msg), "Relay %s", target ? "ON" : "OFF");
            log_event(msg);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_event("Shutting down");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

