/*
 * Door lock control for Raspberry Pi using pigpio.
 *
 * Wiring:
 *   - Servo signal -> GPIO18 (BCM)
 *   - Lock button  -> GPIO21 (BCM, active-low, pull-up enabled)
 *   - Unlock button-> GPIO22 (BCM, active-low, pull-up enabled)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o door_lock door_lock.c -lpigpio -lrt
 * Run:
 *   sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN        18
#define LOCK_BUTTON_PIN  21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH_US  500   /* ~0°   */
#define SERVO_MAX_PULSE_WIDTH_US  2500  /* ~180° */
#define SERVO_LOCK_PULSE_WIDTH_US 1000  /* ~0°   */
#define SERVO_UNLOCK_PULSE_WIDTH_US 2000 /* ~180° */

#define DEBOUNCE_DELAY_US 100000        /* 100 ms */
#define POLL_DELAY_US     10000         /* 10 ms  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as input with pull-up and verify               */
/* ------------------------------------------------------------------ */
static int configure_input_with_pullup(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Set servo pulse width with bounds checking                          */
/* ------------------------------------------------------------------ */
static int set_servo_pulse_width(int pulse_width_us)
{
    if (pulse_width_us < SERVO_MIN_PULSE_WIDTH_US ||
        pulse_width_us > SERVO_MAX_PULSE_WIDTH_US) {
        fprintf(stderr,
                "Error: pulse width %d us out of range [%d, %d]\n",
                pulse_width_us,
                SERVO_MIN_PULSE_WIDTH_US,
                SERVO_MAX_PULSE_WIDTH_US);
        return -1;
    }

    if (gpioServo(SERVO_PIN, pulse_width_us) != 0) {
        fprintf(stderr,
                "Error: gpioServo failed for GPIO%d (pw=%d us)\n",
                SERVO_PIN, pulse_width_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a button pin with debounce                                     */
/* Returns 1 if pressed (active-low), 0 if not pressed, -1 on error     */
/* ------------------------------------------------------------------ */
static int read_button_with_debounce(int pin)
{
    int first = gpioRead(pin);
    if (first < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", pin);
        return -1;
    }

    if (first == 0) {            /* button pressed (active-low) */
        gpioDelay(DEBOUNCE_DELAY_US);
        int second = gpioRead(pin);
        if (second < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", pin);
            return -1;
        }
        if (second == 0) {       /* confirmed press */
            return 1;
        }
    }
    return 0;                    /* not pressed or transient */
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop servo PWM signal */
    gpioServo(SERVO_PIN, 0);

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins with pull-ups */
    if (configure_input_with_pullup(LOCK_BUTTON_PIN) != 0 ||
        configure_input_with_pullup(UNLOCK_BUTTON_PIN) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started.\n");
    printf("  Servo: GPIO%d\n", SERVO_PIN);
    printf("  Lock:  GPIO%d (active-low)\n", LOCK_BUTTON_PIN);
    printf("  Unlock:GPIO%d (active-low)\n", UNLOCK_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int lock_pressed  = read_button_with_debounce(LOCK_BUTTON_PIN);
        int unlock_pressed = read_button_with_debounce(UNLOCK_BUTTON_PIN);

        if (lock_pressed < 0 || unlock_pressed < 0) {
            /* I/O error during button read — exit cleanly */
            break;
        }

        if (lock_pressed) {
            if (set_servo_pulse_width(SERVO_LOCK_PULSE_WIDTH_US) == 0) {
                printf("Door locked (servo ~0°)\n");
            }
        } else if (unlock_pressed) {
            if (set_servo_pulse_width(SERVO_UNLOCK_PULSE_WIDTH_US) == 0) {
                printf("Door unlocked (servo ~180°)\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful cleanup */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

