                "Error: gpioServo failed for GPIO%d (pw=%d us)\n",
                SERVO_PIN, pulse_width_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a button pin with debounce                                     */
/* Returns 1 if pressed (active-low), 0 if not pressed, -1 on error     */
/* ------------------------------------------------------------------ */
static int read_button_with_debounce(int pin)
{
    int first = gpioRead(pin);
    if (first < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", pin);
        return -1;
    }

    if (first == 0) {            /* button pressed (active-low) */
        gpioDelay(DEBOUNCE_DELAY_US);
        int second = gpioRead(pin);
        if (second < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", pin);
            return -1;
        }
        if (second == 0) {       /* confirmed press */
            return 1;
        }
    }
    return 0;                    /* not pressed or transient */
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop servo PWM signal */
    gpioServo(SERVO_PIN, 0);

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins with pull-ups */
    if (configure_input_with_pullup(LOCK_BUTTON_PIN) != 0 ||
        configure_input_with_pullup(UNLOCK_BUTTON_PIN) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started.\n");
    printf("  Servo: GPIO%d\n", SERVO_PIN);
    printf("  Lock:  GPIO%d (active-low)\n", LOCK_BUTTON_PIN);
    printf("  Unlock:GPIO%d (active-low)\n", UNLOCK_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int lock_pressed  = read_button_with_debounce(LOCK_BUTTON_PIN);
        int unlock_pressed = read_button_with_debounce(UNLOCK_BUTTON_PIN);

        if (lock_pressed < 0 || unlock_pressed < 0) {
            /* I/O error during button read — exit cleanly */
            break;
        }

        if (lock_pressed) {
            if (set_servo_pulse_width(SERVO_LOCK_PULSE_WIDTH_US) == 0) {
                printf("Door locked (servo ~0°)\n");
            }
        } else if (unlock_pressed) {
            if (set_servo_pulse_width(SERVO_UNLOCK_PULSE_WIDTH_US) == 0) {
                printf("Door unlocked (servo ~180°)\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful cleanup */
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

