/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 *
 * Two Precision Microdrives 310-101 vibration motors are driven sequentially
 * through external driver circuits (e.g., NPN transistor + flyback diode).
 *
 * Wiring:
 *   Motor 1 driver gate -> GPIO17 (BCM)
 *   Motor 2 driver gate -> GPIO27 (BCM)
 *   Driver base (VCC)   -> 3.3 V (or 5 V per motor spec)
 *   Driver emitter (GND) -> GND
 *
 * Build: gcc -O2 -Wall -o haptic_feedback haptic_feedback.c -lpigpio -lrt
 * Run:   sudo ./haptic_feedback
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_PULSE_US 200000   /* 200 ms */
#define MOTOR2_PULSE_US 300000   /* 300 ms */
#define LOOP_DELAY_US   100000   /* 100 ms between motor pulses */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned value)
{
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, value);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Ensure motors are off before releasing the lines */
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (safe_set_mode(MOTOR1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motors are off at startup */
    if (safe_write(MOTOR1_PIN, 0) != 0 || safe_write(MOTOR2_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    /* Main loop: pulse motors sequentially */
    while (g_running) {
        /* Motor 1: pulse for 200 ms */
        if (safe_write(MOTOR1_PIN, 1) != 0) break;
        gpioDelay(MOTOR1_PULSE_US);
        if (safe_write(MOTOR1_PIN, 0) != 0) break;

        /* Motor 2: pulse for 300 ms */
        if (safe_write(MOTOR2_PIN, 1) != 0) break;
        gpioDelay(MOTOR2_PULSE_US);
        if (safe_write(MOTOR2_PIN, 0) != 0) break;

        /* Delay between motor pulses */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful cleanup */
    cleanup();
    printf("Haptic feedback system stopped.\n");
    return EXIT_SUCCESS;
}

