        fprintf(stderr, "GPIO_LINE_GET_VALUES(offset=%u): %s\n",
                offset, strerror(errno));
        return -1;
    }
    return (vals.bits & (1u << offset)) ? 1 : 0;
}

static void gpio_release_line(int fd, unsigned int offset)
{
    struct gpio_line_release rel;
    rel.num_lines = 1;
    rel.offsets[0] = offset;
    if (ioctl(fd, GPIO_LINE_RELEASE, &rel) < 0) {
        fprintf(stderr, "GPIO_LINE_RELEASE(offset=%u): %s\n",
                offset, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* ZeroMQ helpers                                                      */
/* ------------------------------------------------------------------ */

static void *zmq_setup_pub(void)
{
    void *ctx = zmq_ctx_new();
    if (!ctx) {
        fprintf(stderr, "zmq_ctx_new: %s\n", zmq_strerror(errno));
        return NULL;
    }
    void *sock = zmq_socket(ctx, ZMQ_PUB);
    if (!sock) {
        fprintf(stderr, "zmq_socket(ZMQ_PUB): %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(ctx);
        return NULL;
    }
    int rc = zmq_bind(sock, ZMQ_ENDPOINT);
    if (rc < 0) {
        fprintf(stderr, "zmq_bind(%s): %s\n", ZMQ_ENDPOINT, zmq_strerror(errno));
        zmq_close(sock);
        zmq_ctx_destroy(ctx);
        return NULL;
    }
    return sock;
}

static void zmq_setup_sub(void)
{
    void *ctx = zmq_ctx_new();
    if (!ctx) {
        fprintf(stderr, "zmq_ctx_new: %s\n", zmq_strerror(errno));
        return;
    }
    void *sock = zmq_socket(ctx, ZMQ_SUB);
    if (!sock) {
        fprintf(stderr, "zmq_socket(ZMQ_SUB): %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(ctx);
        return;
    }
    int rc = zmq_connect(sock, ZMQ_SUB_ENDPOINT);
    if (rc < 0) {
        fprintf(stderr, "zmq_connect(%s): %s\n", ZMQ_SUB_ENDPOINT, zmq_strerror(errno));
        zmq_close(sock);
        zmq_ctx_destroy(ctx);
        return;
    }
    rc = zmq_setsockopt(sock, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (rc < 0) {
        fprintf(stderr, "zmq_setsockopt(SUBSCRIBE): %s\n", zmq_strerror(errno));
        zmq_close(sock);
        zmq_ctx_destroy(ctx);
        return;
    }
    printf("Alarm node subscribed to %s\n", ZMQ_SUB_ENDPOINT);
    while (g_running) {
        zmq_msg_t msg;
        rc = zmq_msg_init(&msg);
        if (rc < 0) {
            fprintf(stderr, "zmq_msg_init: %s\n", zmq_strerror(errno));
            break;
        }
        ssize_t n = zmq_recvmsg(sock, &msg, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "zmq_recvmsg: %s\n", zmq_strerror(errno));
            zmq_msg_close(&msg);
            break;
        }
        char *data = zmq_msg_data(&msg);
        size_t size = zmq_msg_size(&msg);
        if (size > 0 && data[0] == ZMQ_TOPIC[0]) {
            printf("Alarm triggered!\n");
            if (gpio_set_value(g_gpio_fd, ALARM_LED_PIN, 1) < 0)
                fprintf(stderr, "Failed to turn on alarm LED\n");
            sleep(ALARM_DURATION_S);
            if (gpio_set_value(g_gpio_fd, ALARM_LED_PIN, 0) < 0)
                fprintf(stderr, "Failed to turn off alarm LED\n");
        }
        zmq_msg_close(&msg);
    }
    zmq_close(sock);
    zmq_ctx_destroy(ctx);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    int gpio_fd = gpio_open_chip();
    if (gpio_fd < 0) return EXIT_FAILURE;

    if (strcmp(mode, "sound_sensor") == 0) {
        if (gpio_request_line(gpio_fd, SOUND_SENSOR_PIN,
                              GPIOLINE_REQUEST_DIRECTION_INPUT,
                              "sound_sensor") < 0) {
            close(gpio_fd);
            return EXIT_FAILURE;
        }
        if (gpio_request_line(gpio_fd, ALARM_LED_PIN,
                              GPIOLINE_REQUEST_DIRECTION_OUTPUT,
                              "alarm_led") < 0) {
            gpio_release_line(gpio_fd, SOUND_SENSOR_PIN);
            close(gpio_fd);
            return EXIT_FAILURE;
        }
        /* ensure LED is off at start */
        gpio_set_value(gpio_fd, ALARM_LED_PIN, 0);

        /* ---- ZeroMQ publisher ---- */
        void *zmq_sock = zmq_setup_pub();
        if (!zmq_sock) {
            gpio_release_line(gpio_fd, SOUND_SENSOR_PIN);
            gpio_release_line(gpio_fd, ALARM_LED_PIN);
            close(gpio_fd);
            return EXIT_FAILURE;
        }

        printf("Sound sensor mode. Listening on %s\n", ZMQ_ENDPOINT);

        while (g_running) {
            int val = gpio_get_value(gpio_fd, SOUND_SENSOR_PIN);
            if (val < 0) {
                usleep(POLL_INTERVAL_US);
                continue;
            }
            if (val == 0) {  /* active-low: sound detected */
                zmq_msg_t msg;
                int rc = zmq_msg_init_size(&msg, 0);
                if (rc < 0) {
                    fprintf(stderr, "zmq_msg_init_size: %s\n", zmq_strerror(errno));
                    break;
                }
                rc = zmq_sendmsg(zmq_sock, &msg, ZMQ_DONTWAIT);
                if (rc < 0) {
                    fprintf(stderr, "zmq_sendmsg: %s\n", zmq_strerror(errno));
                    zmq_msg_close(&msg);
                    break;
                }
                zmq_msg_close(&msg);
                printf("Sound event published\n");
            }
            usleep(POLL_INTERVAL_US);
        }

        zmq_close(zmq_sock);
        zmq_ctx_term();
    } else if (strcmp(mode, "alarm_node") == 0) {
        if (gpio_request_line(gpio_fd, ALARM_LED_PIN,
                              GPIOLINE_REQUEST_DIRECTION_OUTPUT,
                              "alarm_led") < 0) {
            close(gpio_fd);
            return EXIT_FAILURE;
        }
        gpio_set_value(gpio_fd, ALARM_LED_PIN, 0);

        printf("Alarm node mode. Subscribing to %s\n", ZMQ_SUB_ENDPOINT);
        zmq_setup_sub();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    /* ---- cleanup ---- */
    gpio_set_value(gpio_fd, ALARM_LED_PIN, 0);
    gpio_release_line(gpio_fd, SOUND_SENSOR_PIN);
    gpio_release_line(gpio_fd, ALARM_LED_PIN);
    close(gpio_fd);
    return EXIT_SUCCESS;
}

