/*
 * NEC IR Decoder for Raspberry Pi 3 Model B+
 * Uses pigpio for GPIO alert callback and syslog for logging.
 * Publishes decoded commands as JSON via MQTT (localhost:1883, topic ir/decoded).
 *
 * Build: gcc -O2 -Wall -o ir_decoder ir_decoder.c -lpigpio -lpaho-mqtt3as -lrt
 * Run:   sudo ./ir_decoder
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO          17
#define MQTT_BROKER      "tcp://localhost:1883"
#define MQTT_TOPIC       "ir/decoded"
#define MQTT_CLIENT_ID   "ir_decoder"
#define MAX_PULSES       100
#define NEC_HEADER_HIGH  9000
#define NEC_HEADER_LOW   4500
#define NEC_BIT_HIGH     560
#define NEC_ONE_LOW      1690
#define NEC_ZERO_LOW     560
#define NEC_REPEAT_HIGH  9000
#define NEC_REPEAT_LOW   2250
#define NEC_TIMEOUT_US   100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulses[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static MQTTClient mqtt_client = NULL;
static MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 0 && level != 1) return;

    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (pulse_count < MAX_PULSES) {
        pulses[pulse_count++] = diff;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow, resetting");
        pulse_count = 0;
    }

    if (level == 0 && pulse_count > 0) {
        uint32_t cmd = 0;
        int valid = 1;

        if (pulse_count >= 32) {
            uint32_t hdr_high = pulses[0];
            uint32_t hdr_low  = pulses[1];

            if (hdr_high < NEC_HEADER_HIGH * 0.8 || hdr_high > NEC_HEADER_HIGH * 1.2) {
                valid = 0;
            } else if (hdr_low < NEC_HEADER_LOW * 0.8 || hdr_low > NEC_HEADER_LOW * 1.2) {
                valid = 0;
            }

            if (valid) {
                for (int i = 0; i < 32; i++) {
                    uint32_t mark = pulses[2 + i * 2];
                    uint32_t space = pulses[3 + i * 2];

                    if (mark < NEC_BIT_HIGH * 0.8 || mark > NEC_BIT_HIGH * 1.2) {
                        valid = 0;
                        break;
                    }

                    if (space > NEC_ONE_LOW * 0.8 && space < NEC_ONE_LOW * 1.2) {
                        cmd |= (1UL << i);
                    } else if (space > NEC_ZERO_LOW * 0.8 && space < NEC_ZERO_LOW * 1.2) {
                        /* logic 0 */
                    } else {
                        valid = 0;
                        break;
                    }
                }
            }
        } else {
            valid = 0;
        }

        if (valid) {
            uint8_t addr = (cmd >> 24) & 0xFF;
            uint8_t inv_addr = (cmd >> 16) & 0xFF;
            uint8_t cmd_byte = (cmd >> 8) & 0xFF;
            uint8_t inv_cmd = (cmd >> 0) & 0xFF;

            if ((uint8_t)(~addr) != inv_addr) {
                syslog(LOG_WARNING, "NEC address check failed: 0x%02X vs 0x%02X", addr, inv_addr);
            } else if ((uint8_t)(~cmd_byte) != inv_cmd) {
                syslog(LOG_WARNING, "NEC command check failed: 0x%02X vs 0x%02X", cmd_byte, inv_cmd);
            } else {
                char json_payload[128];
                snprintf(json_payload, sizeof(json_payload),
                         "{\"address\":0x%02X,\"command\":0x%02X}", addr, cmd_byte);

                MQTTClient_message pubmsg = MQTTClient_message_initializer;
                pubmsg.payload = json_payload;
                pubmsg.payloadlen = (int)strlen(json_payload);
                pubmsg.qos = 0;
                pubmsg.retained = 0;

                int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, NULL);
                if (rc != MQTTCLIENT_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
                } else {
                    syslog(LOG_INFO, "Decoded NEC: addr=0x%02X cmd=0x%02X", addr, cmd_byte);
                }
            }
        }
        pulse_count = 0;
    }
}

static int init_mqtt(void) {
    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT create failed: %s", MQTTClient_strerror(rc));
        return -1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        mqtt_client = NULL;
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder on GPIO%d", IR_GPIO);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_mqtt() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        MQTTClient_loop(mqtt_client, 20, 1);
        usleep(100000);
    }

    syslog(LOG_INFO, "Shutting down...");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

