/*
 * Raspberry Pi 3 Model B+ — 4 × BH1750FVI ambient-light reader + UDP multicast.
 *
 * Wiring (I2C bus 1, GPIO 2/3):
 *   Sensor 1  ->  0x29
 *   Sensor 2  ->  0x2a
 *   Sensor 3  ->  0x2b
 *   Sensor 4  ->  0x2c
 *
 * Build:  gcc -O2 -Wall -Wextra -o bh1750_mcast bh1750_mcast.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define BH1750_ADDR_BASE 0x29
#define BH1750_CMD_AUTO  0x10   /* one-time high-resolution mode, ~120 ms */
#define BH1750_CONV_MS   180    /* conservative conversion wait            */
#define NUM_SENSORS      4
#define MULTICAST_ADDR   "239.255.255.250"
#define MULTICAST_PORT   5005
#define SAMPLE_PERIOD_S  1

static volatile sig_atomic_t g_terminate = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0)
        perror("open(" I2C_BUS ")");
    return fd;
}

static int i2c_set_addr(int fd, uint8_t addr)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02x): %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write(0x%02x): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "read: %s\n", strerror(errno));
        else
            fprintf(stderr, "read: short read (%zd bytes)\n", n);
        return -1;
    }
    /* BH1750 sends LSB first */
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* BH1750                                                              */
/* ------------------------------------------------------------------ */

/*
 * Returns lux on success, or NAN on failure.
