/*
 * Raspberry Pi Zero W – Honeywell AWM7300V mass airflow sensor reader.
 *
 * Wiring:
 *   AWM7300V SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   AWM7300V SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   AWM7300V VDD  -> 3.3 V
 *   AWM7300V GND  -> GND
 *
 * The AWM7300V is a zero-slope, 14-bit, left-justified, big-endian
 * I2C sensor.  A zero-length write generates a start condition,
 * followed by a repeated-start read of two bytes.  The 14-bit flow
 * value is masked from the first two bytes, shifted right 2, then
 * scaled to SLPM per the datasheet conversion factor.
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x30          /* 7-bit I2C address */
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000        /* 100 ms between retries */

/* AWM7300V datasheet conversion factor:  flow (SLPM) = raw / 100.0 */
#define FLOW_SCALE 100.0f

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static int open_i2c_device(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Issue a zero-length write to generate a start condition, then read
 * two bytes from the AWM7300V.  Returns 0 on success, -1 on error.
 */
static int read_awm7300v(int fd, uint16_t *raw_out)
{
    ssize_t n;

    /*
     * A zero-length write generates a start condition without
     * transferring data bytes.  The AWM7300V then latches the
     * current flow value and holds it until the master issues a
     * repeated-start read.
     */
    n = write(fd, NULL, 0);
    if (n < 0) {
        if (errno == ENXIO)
            fprintf(stderr, "AWM7300V not responding at 0x%02X\n",
                    AWM7300V_ADDR);
        else
            fprintf(stderr, "write(start): %s\n", strerror(errno));
        return -1;
    }

    /*
     * Read two bytes:  byte 0 = MSB, byte 1 = LSB.
     * The 14-bit flow value is left-justified in the first two bytes.
     */
    uint8_t buf[2];
    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "read: %s\n", strerror(errno));
        else
            fprintf(stderr, "read: short read (%zd bytes)\n", n);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];

    /* Mask out the 14-bit flow field (bits 15..2) and shift right 2. */
    *raw_out = (raw >> 2) & 0x3FFF;
    return 0;
}

/* ------------------------------------------------------------------ */
static float convert_to_slpm(uint16_t raw)
{
    return (float)raw / FLOW_SCALE;
}

/* ------------------------------------------------------------------ */
static void log_flow_rate(FILE *fp, float flow_slpm)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow_slpm) < 0)
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
    else
        fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open_i2c_device(I2C_BUS, AWM7300V_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("AWM7300V airflow monitor started.  Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw = 0;
        int      ok  = 0;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (read_awm7300v(g_i2c_fd, &raw) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES)
                usleep(RETRY_DELAY_US);
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts; "
                            "continuing.\n", MAX_RETRIES);
        } else {
            float flow = convert_to_slpm(raw);
            log_flow_rate(g_log_fp, flow);
            printf("Flow: %.2f SLPM\n", flow);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal. */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; ++s)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

