#define AS7341_I2C_ADDR        0x39

#define AS7341_REG_ENABLE      0x80
#define AS7341_REG_ATIME       0x81
#define AS7341_REG_WTIME       0x83
#define AS7341_REG_CONFIG1     0x8D
#define AS7341_REG_CONFIG2     0x8E
#define AS7341_REG_CONFIG3     0x8F
#define AS7341_REG_CONFIG4     0x90
#define AS7341_REG_CONFIG5     0x91
#define AS7341_REG_CONFIG6     0x92
#define AS7341_REG_ID          0x93
#define AS7341_REG_STATUS      0x97
#define AS7341_REG_DATA_F1     0x98
#define AS7341_REG_DATA_F2     0x9A
#define AS7341_REG_DATA_F3     0x9C
#define AS7341_REG_DATA_F4     0x9E
#define AS7341_REG_DATA_F5     0xA0
#define AS7341_REG_DATA_F6     0xA2
#define AS7341_REG_DATA_F7     0xA4
#define AS7341_REG_DATA_F8     0xA6
#define AS7341_REG_DATA_CLEAR  0xAA
#define AS7341_REG_DATA_NIR    0xAC

/* ENABLE register bits */
#define AS7341_ENABLE_PON      0x01
#define AS7341_ENABLE_SP_EN    0x02

/* ID register expected value */
#define AS7341_ID_VALUE        0x41

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_write8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "reg_write8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_read8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "reg_read8 write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "reg_read8 read(0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
