    if (reg_read8(fd, AS7341_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read ID register — sensor absent or bus error.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x%02X). Wrong sensor?\n",
                id, AS7341_ID_VALUE);
        return -1;
    }

