    if (reg_write8(fd, AS7341_REG_ATIME, 0xFF) != 0)
        return -1;

    /* WTIME = 256 – wait time ~256 µs (per datasheet) */
    if (reg_write8(fd, AS7341_REG_WTIME, 0xFF) != 0)
        return -1;

    /* CONFIG1: enable ADC, set ADC gain to 1x */
    if (reg_write8(fd, AS7341_REG_CONFIG1, 0x00) != 0)
        return -1;

    /* CONFIG2: disable interrupts, set ADC gain to 1x */
    if (reg_write8(fd, AS7341_REG_CONFIG2, 0x00) != 0)
        return -1;

    /* CONFIG3: disable interrupts, set ADC gain to 1x */
    if (reg_write8(fd, AS7341_REG_CONFIG3, 0x00) != 0)
        return -1;

    /* CONFIG4: disable interrupts, set ADC gain to 1x */
    if (reg_write8(fd, AS7341_REG_CONFIG4, 0x00) != 0)
        return -1;

    /* CONFIG5: disable interrupts, set ADC gain to 1x */
    if (reg_write8(fd, AS7341_REG_CONFIG5, 0x00) != 0)
        return -1;

    /* CONFIG6: set SMUX to F1 (violet) */
    if (reg_write8(fd, AS7341_REG_CONFIG6, 0x00) != 0)
        return -1;

    /* Enable spectral measurement */
    if (reg_write8(fd, AS7341_REG_ENABLE,
