    if (reg_read16(fd, AS7341_REG_DATA_F2, &ch[1]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_F3, &ch[2]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_F4, &ch[3]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_F5, &ch[4]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_F6, &ch[5]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_F7, &ch[6]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_F8, &ch[7]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_CLEAR, &ch[8]) != 0) return -1;
    if (reg_read16(fd, AS7341_REG_DATA_NIR, &ch[9]) != 0) return -1;
