}

/* ------------------------------------------------------------------ */
/* Simplified lux approximation: sum of first eight spectral channels. */
static float calculate_lux(const uint16_t ch[10])
{
    float lux = 0.0f;
    for (int i = 0; i < 8; i++)
        lux += (float)ch[i];
    return lux;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const uint16_t ch[10], float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
