        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_fp = fopen("spectral_log.csv", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open spectral_log.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp,
                "timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
        fflush(g_log_fp);
    }

    uint16_t ch[10];
    int consecutive_errors = 0;

    while (g_running) {
        if (read_all_channels(g_i2c_fd, ch) == 0) {
            consecutive_errors = 0;
            float lux = calculate_lux(ch);
            log_data(g_log_fp, ch, lux);
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }
        sleep(5);
    }

    /* Cleanup */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    fprintf(stderr, "Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

