/*
 * Raspberry Pi Zero W – Omron D7S tri-axial seismic sensor reader
 *
 * Reads acceleration data over I2C (/dev/i2c-1) and logs timestamped
 * X/Y/Z values in g to seismic_data.csv.  Error messages are logged to
 * seismic_error.log.  The D7S is typically addressed at 0x2A.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic seismic.c -lm
 * Run:    ./seismic [-a addr] [-i interval] [-f filename]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (per datasheet) ---- */
#define D7S_DEFAULT_ADDR   0x2A
#define D7S_REG_CTRL       0x00
#define D7S_REG_X_LSB      0x01
#define D7S_REG_X_MSB      0x02
#define D7S_REG_Y_LSB      0x03
#define D7S_REG_Y_MSB      0x04
#define D7S_REG_Z_LSB      0x05
#define D7S_REG_Z_MSB      0x06
#define D7S_CTRL_MODE_CONT 0x01   /* continuous measurement mode */
#define D7S_SENSITIVITY    0.0001 /* g/LSB (12-bit left-justified) */
#define D7S_SCALE_FACTOR   1.0    /* g/LSB (simplified) */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_csv    = NULL;
static FILE    *g_log    = NULL;

/* ---- Prototypes ---- */
static void  signal_handler(int sig);
static int   i2c_write_byte(int fd, uint8_t reg, uint8_t val);
static int   i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len);
static int   d7s_init(int fd);
static int   d7s_read_accel(int fd, float *x, float *y, float *z);
static void  log_data(float ts, float x, float y, float z);
static void  log_error(const char *msg);
static void  cleanup(void);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.    */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at `reg`; returns 0 on success, -1 on err. */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        log_error("I2C register-set failed");
        return -1;
    }
    /* Read data */
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int d7s_init(int fd)
{
    /* Put sensor into continuous measurement mode */
    if (i2c_write_byte(fd, D7S_REG_CTRL, D7S_CTRL_MODE_CONT) != 0) {
        log_error("Failed to set D7S continuous mode");
        return -1;
    }
    /* Allow first conversion to complete */
    usleep(10000);
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read X/Y/Z acceleration.
 * The D7S returns 12-bit left-justified data in the two-byte registers.
 * We right-shift by 4 to get the full 12-bit value, then scale to g.
 */
static int d7s_read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_block(fd, D7S_REG_X_LSB, buf, sizeof(buf)) != 0)
        return -1;

    /* 12-bit left-justified: low byte is bits[7:4], high byte is bits[3:0] */
    raw_x = (int16_t)((buf[1] << 8) | buf[0]) >> 4;
    raw_y = (int16_t)((buf[3] << 8) | buf[2]) >> 4;
    raw_z = (int16_t)((buf[5] << 8) | buf[4]) >> 4;

    /* Sign-extend 12-bit to 16-bit */
    if (raw_x & 0x0800) raw_x |= 0xF000;
    if (raw_y & 0x0800) raw_y |= 0xF000;
    if (raw_z & 0x0800) raw_z |= 0xF000;

    *x = (float)raw_x * D7S_SENSITIVITY;
    *y = (float)raw_y * D7S_SENSITIVITY;
    *z = (float)raw_z * D7S_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float ts, float x, float y, float z)
{
    if (g_csv) {
        fprintf(g_csv, "%.3f,%.6f,%.6f,%.6f\n", ts, x, y, z);
        fflush(g_csv);
    }
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_log) return;

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int   addr   = D7S_DEFAULT_ADDR;
    int   interval = 1;
    char  filename[256] = "seismic_data.csv";
    int   opt;

    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
        case 'a': addr = (int)strtol(optarg, NULL, 0); break;
        case 'i': interval = atoi(optarg); break;
        case 'f': strncpy(filename, optarg, sizeof(filename) - 1); break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Open error log */
    g_log = fopen("seismic_error.log", "a");
    if (!g_log) {
        perror("fopen(seismic_error.log)");
        return EXIT_FAILURE;
    }

    /* Open CSV */
    g_csv = fopen(filename, "w");
    if (!g_csv) {
        perror("fopen(csv)");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("open(/dev/i2c-1) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
        log_error("ioctl(I2C_SLAVE) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (d7s_init(g_i2c_fd) != 0) {
        log_error("D7S initialization failed (sensor absent or bus error)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("D7S seismic logger started.  Addr=0x%02X  Interval=%ds  File=%s\n",
           addr, interval, filename);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;
        int   ok = 0;

        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (d7s_read_accel(g_i2c_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            usleep(10000);  /* 10 ms backoff */
        }

        if (ok) {
            time_t now = time(NULL);
            log_data((float)now, x, y, z);
        } else {
            log_error("All I2C read attempts failed in one interval window");
        }

        sleep(interval);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

