#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define BH1750_ADDR     0x23
#define BH1750_CONT_HIGH_RES  0x10
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5000
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int bh1750_init(int fd)
{
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl(I2C_SLAVE, 0x%02X): %s\n",
                BH1750_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    unsigned char cmd = BH1750_CONT_HIGH_RES;
    unsigned char buf[2];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error: write(power on/set mode): %s\n", strerror(errno));
        return -1;
    }

    /* Datasheet: conversion time ~120 ms for high-resolution mode */
    usleep(120000);

    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: read(2 bytes): %s (got %zd bytes)\n",
                n < 0 ? strerror(errno) : "short read", n);
        return -1;
    }

    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, float lux)
{
    struct sockaddr_in addr;
    char buffer[32];

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    snprintf(buffer, sizeof(buffer), "%.2f", lux);

    if (sendto(sockfd, buffer, strlen(buffer), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error: sendto(): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    int sock_fd = -1;
    int opt = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: open(%s): %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: BH1750 initialization failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        fprintf(stderr, "Error: socket(): %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Error: setsockopt(IP_MULTICAST_TTL): %s\n", strerror(errno));
        close(sock_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor reader started. Sending to %s:%d every %d s.\n",
           MULTICAST_ADDR, MULTICAST_PORT, SAMPLE_INTERVAL);

    while (g_running) {
        float lux;

        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Warning: read failed, retrying in %d s...\n",
                    SAMPLE_INTERVAL);
        } else {
            printf("Lux: %.2f\n", lux);
            if (send_multicast(sock_fd, lux) < 0) {
                fprintf(stderr, "Warning: multicast send failed\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (sock_fd >= 0) close(sock_fd);
    return EXIT_SUCCESS;
}

