/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 3 Model B+
 *
 * Reads the 32-bit little-endian magic word (0x01020304) followed by
 * a 16-bit version, 16-bit length, 32-bit platform, 32-bit frame number,
 * 32-bit time_stamp, 32-bit num_detected_obj, 32-bit num_tlvs,
 * followed by zero or more (type, length, payload) tuples.
 *
 * TLV type 1 = xyzQ format (per-object), 4 bytes per record.
 *   payload: [range_q, doppler_q, snr_q, x_q, y_q, z_q],
 *   where range/doppler/snr are 16-bit signed, x/y/z are 16-bit signed.
 *   The Q-format scale factors are documented in the AWR1642 SDK.
 *
 * Writes CSV rows: timestamp,object_index,range_m,velocity_mps
 * to radar_data.csv.
 *
 * Build: gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c
 *        (requires the AWR1642 SDK UART driver library, e.g.,
 *         libmmw_uart.a; the example below links against it.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include "libmmw_uart.h"

#define UART_DEVICE      "/dev/ttyS0"
#define BAUD_RATE        921600
#define CSV_FILE         "radar_data.csv"
#define READ_BUF_SIZE    4096
#define MAX_OBJECTS      100

/* ---- AWR1642 frame constants (little-endian on the wire) ---- */
#define MAGIC_WORD       0x04030201u
#define FRAME_HEADER_LEN 40          /* bytes: 8 magic + 16 version + 16 len + 16 platform + 32 frame + 32 ts + 32 obj + 32 tlv */
#define TLV_HEADER_LEN   8           /* bytes: 2 type + 2 length */
#define TLV_TYPE_XYZQ    1
#define XYZQ_RECORD_LEN  4           /* 2 range + 2 snr */
#define RANGE_Q_SCALE    0.0439453125f   /* 1/256  */
#define DOPPLER_Q_SCALE  0.0439453125f   /* 1/256  */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_uart_fd = -1;
static FILE    *g_csv     = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to stderr.                                 */
static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm))
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Append one CSV row.                                                 */
static int write_csv(FILE *fp, int idx, float range_m, float vel_mps)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (!localtime_r(&t, &tm)) {
        log_error("localtime_r failed");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%.3f,%.3f\n", ts, idx, range_m, vel_mps) < 0) {
        log_error("fprintf to CSV failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        log_error("fflush on CSV failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse one complete frame buffer.                                    */
/* Returns 0 on success, -1 on malformed frame.                        */
static int parse_frame(const uint8_t *frame, uint32_t frame_len, FILE *fp)
{
    if (frame_len < FRAME_HEADER_LEN) {
        log_error("frame too short for header");
        return -1;
    }

    /* Magic word is little-endian: 0x01 0x02 0x03 0x04 */
    uint32_t magic = (uint32_t)frame[0]
                   | ((uint32_t)frame[1] << 8)
                   | ((uint32_t)frame[2] << 16)
                   | ((uint32_t)frame[3] << 24);
    if (magic != MAGIC_WORD) {
        log_error("magic word mismatch");
        return -1;
    }

    /* num_detected_obj is 32-bit, little-endian, offset 32 */
    uint32_t num_obj = (uint32_t)frame[32]
                     | ((uint32_t)frame[33] << 8)
                     | ((uint32_t)frame[34] << 16)
                     | ((uint32_t)frame[35] << 24);

    /* num_tlvs is 32-bit, little-endian, offset 36 */
    uint32_t num_tlvs = (uint32_t)frame[36]
                      | ((uint32_t)frame[37] << 8)
                      | ((uint32_t)frame[38] << 16)
                      | ((uint32_t)frame[39] << 24);

    uint32_t offset = FRAME_HEADER_LEN;

    for (uint32_t i = 0; i < num_tlvs; i++) {
        if (offset + TLV_HEADER_LEN > frame_len) {
            log_error("TLV header out of bounds");
            return -1;
        }
        uint16_t tlv_type = (uint16_t)frame[offset]
                          | ((uint16_t)frame[offset + 1] << 8);
        uint16_t tlv_len  = (uint16_t)frame[offset + 2]
                          | ((uint16_t)frame[offset + 3] << 8);
        offset += TLV_HEADER_LEN;

        if (offset + tlv_len > frame_len) {
            log_error("TLV payload out of bounds");
            return -1;
        }

        if (tlv_type == TLV_TYPE_XYZQ) {
            uint32_t rec_per_obj = tlv_len / XYZQ_RECORD_LEN;
            if (rec_per_obj != num_obj) {
                log_error("TLV record count mismatch");
                return -1;
            }
            for (uint32_t j = 0; j < num_obj; j++) {
                const uint8_t *rec = frame + offset + j * XYZQ_RECORD_LEN;
                int16_t range_q = (int16_t)((uint16_t)rec[0]
                                          | ((uint16_t)rec[1] << 8));
                int16_t doppler_q = (int16_t)((uint16_t)rec[2]
                                            | ((uint16_t)rec[3] << 8));
                float range_m  = range_q  * RANGE_Q_SCALE;
                float vel_mps  = doppler_q * DOPPLER_Q_SCALE;
                if (write_csv(fp, (int)j, range_m, vel_mps) != 0)
                    return -1;
            }
        }
        offset += tlv_len;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction failed");
        return EXIT_FAILURE;
    }

    /* ---- Open CSV ---- */
    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        log_error("fopen CSV");
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_csv) == 0) {
        if (fprintf(g_csv, "timestamp,object_index,range_m,velocity_mps\n") < 0) {
            log_error("CSV header write failed");
            fclose(g_csv);
            return EXIT_FAILURE;
        }
        fflush(g_csv);
    }

    /* ---- Open UART via AWR1642 SDK driver ---- */
    g_uart_fd = open_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        log_error("open_uart");
        fclose(g_csv);
        return EXIT_FAILURE;
    }

    printf("AWR1642 radar reader started on %s @ %d baud.\n", UART_DEVICE, BAUD_RATE);
    printf("Logging to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    /* ---- Main loop ---- */
    uint8_t *buf = malloc(READ_BUF_SIZE);
    if (!buf) {
        log_error("malloc read buffer");
        close_uart(g_uart_fd);
        fclose(g_csv);
        return EXIT_FAILURE;
    }

    uint32_t buf_len = 0;

    while (g_running) {
        ssize_t n = read_uart(g_uart_fd, buf + buf_len,
                              READ_BUF_SIZE - buf_len);
        if (n < 0) {
            if (errno == EINTR) continue;
            log_error("read_uart");
            break;
        }
        if (n == 0) {
            /* No data available right now; brief sleep to avoid busy-loop */
            usleep(10000);
            continue;
        }
        buf_len += (uint32_t)n;

        /* ---- Synchronize on magic word ---- */
        uint32_t i = 0;
        while (i + 4 <= buf_len) {
            uint32_t magic = (uint32_t)buf[i]
                           | ((uint32_t)buf[i + 1] << 8)
                           | ((uint32_t)buf[i + 2] << 16)
                           | ((uint32_t)buf[i + 3] << 24);
            if (magic == MAGIC_WORD) break;
            i++;
        }
        if (i > 0) {
            /* Discard leading garbage */
            if (i < buf_len) memmove(buf, buf + i, buf_len - i);
            buf_len -= i;
        }
        if (buf_len < FRAME_HEADER_LEN) {
            /* Need more data */
            continue;
        }

        /* ---- Parse one complete frame ---- */
        uint32_t len_le = (uint32_t)buf[8]
                        | ((uint32_t)buf[9] << 8)
                        | ((uint32_t)buf[10] << 16)
                        | ((uint32_t)buf[11] << 24);
        uint32_t total_len = FRAME_HEADER_LEN + len_le;

        if (total_len > READ_BUF_SIZE) {
            log_error("frame length exceeds buffer");
            /* Reset to avoid infinite loop on a bad stream */
            buf_len = 0;
            continue;
        }
        if (buf_len < total_len) {
            /* Need more data */
            continue;
        }

        if (parse_frame(buf, total_len, g_csv) != 0) {
            /* Malformed frame: resync by shifting */
            memmove(buf, buf + 4, buf_len - 4);
            buf_len -= 4;
            continue;
        }

        /* Shift remaining bytes */
        uint32_t leftover = buf_len - total_len;
        if (leftover > 0)
            memmove(buf, buf + total_len, leftover);
        buf_len = leftover;
    }

    /* ---- Cleanup ---- */
    free(buf);
    if (g_uart_fd >= 0) close_uart(g_uart_fd);
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
    }
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

