/*
 * AWR1642 mmWave radar range-detection reader for Raspberry Pi 4 Model B.
 *
 * Reads ASCII lines of the form "<unix_timestamp_seconds>,<range_meters>\n"
 * over /dev/serial0 at 115200 baud, 8N1, non-canonical mode, and logs
 * "Timestamp: YYYY-MM-DD HH:MM:SS, Range: X.XX meters" to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B115200
#define READ_TIMEOUT_SEC 2
#define LINE_BUF_SIZE    256

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* UART configuration                                                  */
/* ------------------------------------------------------------------ */
static int configure_uart(int fd)
{
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    /* 115200 baud, 8N1, raw mode */
    if (cfsetispeed(&tty, BAUD_RATE) != 0 || cfsetospeed(&tty, BAUD_RATE) != 0) {
        perror("cfsetspeed");
        return -1;
    }

    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |=  (CS8 | CLOCAL | CREAD);

    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    tty.c_oflag &= ~(OPOST | ONLCR);

    /* VMIN=0, VTIME=1 (0.5 s inter-byte timeout) */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Line-based parsing                                                  */
/* ------------------------------------------------------------------ */
static int parse_line(const char *line, time_t *timestamp, float *range)
{
    char *endptr = NULL;
    long  ts_l   = strtol(line, &endptr, 10);

    if (endptr == line || *endptr != ',') {
        return -1;
    }

    char *range_start = endptr + 1;
    errno = 0;
    float r = strtof(range_start, &endptr);

    if (errno == ERANGE || endptr == range_start ||
        (*endptr != '\0' && *endptr != '\n' && *endptr != '\r')) {
        return -1;
    }

    *timestamp = (time_t)ts_l;
    *range     = r;
    return 0;
}

static void log_detection(time_t timestamp, float range)
{
    struct tm tm_info;
    char      time_str[32];

    if (localtime_r(&timestamp, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int  uart_fd = -1;
    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("open(" UART_DEVICE ")");
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("AWR1642 radar reader started on %s @ 115200 8N1.\n", UART_DEVICE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        struct timeval tv;

        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        tv.tv_sec  = READ_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel = select(uart_fd + 1, &readfds, NULL, NULL, &tv);

        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            break;
        }

        if (sel == 0) {
            /* Timeout — no data within 2 s — sensor absent or bus error */
            fprintf(stderr, "Warning: no UART data for %d seconds (sensor absent?)\n",
                    READ_TIMEOUT_SEC);
            continue;
        }

        if (!FD_ISSET(uart_fd, &readfds)) {
            continue;
        }

        char chunk[128];
        ssize_t n = read(uart_fd, chunk, sizeof(chunk) - 1);

        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("read");
            break;
        }

        if (n == 0) {
            /* Device disappeared or closed */
            fprintf(stderr, "Warning: UART closed by peer\n");
            break;
        }

        chunk[n] = '\0';

        for (ssize_t i = 0; i < n; i++) {
            char c = chunk[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                if (line_len > 0) {
                    time_t  ts;
                    float   range;

                    if (parse_line(line_buf, &ts, &range) == 0) {
                        log_detection(ts, range);
                    } else {
                        fprintf(stderr, "Parse error: '%s'\n", line_buf);
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    /* Line too long — discard and reset */
                    fprintf(stderr, "Line exceeded buffer, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (uart_fd >= 0) {
        close(uart_fd);
    }

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

