#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE    115200
#define POLL_DELAY_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        serClose(g_uart_fd);
        g_uart_fd = -1;
    }
    gpioTerminate();
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIDDLE_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", MIDDLE_SENSOR_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", RIGHT_SENSOR_PIN);
        return -1;
    }

    return 0;
}

static int init_uart(void)
{
    g_uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_fd < 0) {
        fprintf(stderr, "Error: failed to open UART device %s (pigpio error %d).\n",
                UART_DEVICE, g_uart_fd);
        return -1;
    }
    return 0;
}

static void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static void send_emergency_stop(void)
{
    const char *msg = "EMERGENCY STOP!\n";
    int written = serWrite(g_uart_fd, (char *)msg, (int)strlen(msg));
    if (written < 0) {
        fprintf(stderr, "Warning: UART write failed (pigpio error %d).\n", written);
    } else if (written < (int)strlen(msg)) {
        fprintf(stderr, "Warning: UART partial write (%d/%zu bytes).\n",
                written, strlen(msg));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("KY-033 3-Way Tracking Sensor Program\n");
    printf("Left: GPIO%d, Middle: GPIO%d, Right: GPIO%d\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("UART: %s @ %d baud\n", UART_DEVICE, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            send_emergency_stop();
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

